INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '727285f1-736e-53df-9df5-91d16602f811', id, 'wudu-step-by-step', '{"bn": "ওযু করার নিয়ম: ধাপে ধাপে", "en": "How to Perform Wudu: Step by Step"}', '{"bn": "নামাজের আগে ওযু ফরজ। রাসুলুল্লাহ ﷺ যেভাবে ওযু করতেন, সেভাবে শুরু থেকে শেষ পর্যন্ত — দোয়াসহ।", "en": "Wudu is required before salah. Here is wudu as the Prophet ﷺ performed it, from start to finish, with the duas."}', 'basic', '[{"type": "text", "text": {"bn": "ওযু ছাড়া নামাজ হয় না। আল্লাহ তাআলা কুরআনে ওযুর মূল অঙ্গগুলো নিজেই বলে দিয়েছেন। রাসুলুল্লাহ ﷺ বলেছেন, যার ওযু ভেঙে গেছে, সে ওযু না করা পর্যন্ত আল্লাহ তার নামাজ কবুল করেন না।", "en": "Salah is not valid without wudu. Allah Himself names the main parts of wudu in the Quran, and the Prophet ﷺ said that Allah does not accept the prayer of someone whose wudu has broken until he performs wudu."}}, {"type": "arabic", "label": {"bn": "ওযুর আয়াত", "en": "The ayah of wudu"}, "ar": "يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا قُمْتُمْ إِلَى الصَّلَاةِ فَاغْسِلُوا وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى الْمَرَافِقِ وَامْسَحُوا بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى الْكَعْبَيْنِ", "pron": {"bn": "ইয়া আইয়্যুহাল্লাযিনা আমানু ইযা কুমতুম ইলাস সালাতি ফাগসিলু উজুহাকুম ওয়া আইদিয়াকুম ইলাল মারাফিকি ওয়ামসাহু বিরুউসিকুম ওয়া আরজুলাকুম ইলাল কা''বাইন।", "en": "Ya ayyuhal-ladhina amanu idha qumtum ilas-salati faghsilu wujuhakum wa aydiyakum ilal-marafiqi wamsahu bi-ru''usikum wa arjulakum ilal-ka''bayn."}, "meaning": {"bn": "হে ঈমানদারগণ! যখন তোমরা নামাজের জন্য দাঁড়াতে চাও, তখন তোমাদের মুখমণ্ডল ও কনুই পর্যন্ত হাত ধুয়ে নাও, মাথা মাসেহ করো এবং টাখনু পর্যন্ত পা ধুয়ে নাও।", "en": "O you who believe, when you rise for prayer, wash your faces and your arms up to the elbows, wipe your heads, and wash your feet up to the ankles."}, "ref": {"bn": "সূরা মায়েদা ৫:৬ (আংশিক)", "en": "Al-Ma''idah 5:6 (part)"}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৩৫; সহিহ মুসলিম ২২৫ — ওযু ছাড়া নামাজ কবুল হয় না", "en": "Sahih al-Bukhari 135; Sahih Muslim 225: prayer is not accepted without wudu"}}, {"type": "heading", "text": {"bn": "ওযুর ধাপগুলো", "en": "The steps of wudu"}}, {"type": "step", "title": {"bn": "নিয়ত", "en": "Intention (niyyah)"}, "text": {"bn": "মনে মনে ঠিক করুন যে আপনি আল্লাহর জন্য পবিত্রতা অর্জন করছেন। নিয়ত অন্তরের কাজ; মুখে বলা জরুরি নয়।", "en": "Intend in your heart that you are purifying yourself for Allah. Niyyah is in the heart; saying it aloud is not required."}}, {"type": "step", "title": {"bn": "বিসমিল্লাহ বলা", "en": "Say Bismillah"}, "text": {"bn": "ওযুর শুরুতে \"বিসমিল্লাহ\" বলুন। অধিকাংশ আলেমের মতে এটি সুন্নত; হাম্বলি মাযহাবের একটি মতে ওয়াজিব।", "en": "Say \"Bismillah\" at the start. Most scholars hold it is sunnah; one Hanbali view holds it obligatory."}}, {"type": "arabic", "label": {"bn": "ওযুর শুরুতে", "en": "At the start of wudu"}, "ar": "بِسْمِ اللَّهِ", "pron": {"bn": "বিসমিল্লাহ", "en": "Bismillah"}, "meaning": {"bn": "আল্লাহর নামে (শুরু করছি)।", "en": "In the name of Allah."}, "ref": {"bn": "সুনান আবু দাউদ ১০১", "en": "Sunan Abi Dawud 101"}}, {"type": "step", "title": {"bn": "দুই হাত কবজি পর্যন্ত ধোয়া", "en": "Wash both hands to the wrists"}, "text": {"bn": "প্রথমে ডান হাত, তারপর বাম হাত কবজি পর্যন্ত তিনবার ধুয়ে নিন। আঙুলের ফাঁকে পানি পৌঁছান।", "en": "Wash the hands up to the wrists three times, right first, letting water reach between the fingers."}}, {"type": "step", "title": {"bn": "মিসওয়াক করা", "en": "Use a miswak"}, "text": {"bn": "সম্ভব হলে মিসওয়াক বা ব্রাশ দিয়ে দাঁত পরিষ্কার করুন; না থাকলে আঙুল দিয়ে ঘষে নিন। এটি গুরুত্বপূর্ণ সুন্নত।", "en": "If possible, clean the teeth with a miswak (or brush); otherwise rub with a finger. It is an emphasised sunnah."}}, {"type": "step", "title": {"bn": "কুলি করা", "en": "Rinse the mouth"}, "text": {"bn": "ডান হাতে পানি নিয়ে তিনবার কুলি করুন। রোজা না থাকলে গড়গড়া করুন।", "en": "Take water with the right hand and rinse the mouth three times; gargle if you are not fasting."}}, {"type": "step", "title": {"bn": "নাকে পানি দেওয়া", "en": "Rinse the nose"}, "text": {"bn": "ডান হাতে নাকে পানি দিন এবং বাম হাতে নাক ঝেড়ে পরিষ্কার করুন — তিনবার। রোজা থাকলে বেশি ভেতরে টানবেন না।", "en": "Draw water into the nose with the right hand and blow it out with the left, three times. Do not sniff deeply when fasting."}}, {"type": "step", "title": {"bn": "মুখমণ্ডল ধোয়া (ফরজ)", "en": "Wash the face (fard)"}, "text": {"bn": "কপালের চুলের গোড়া থেকে থুতনির নিচ পর্যন্ত এবং এক কানের লতি থেকে অন্য কানের লতি পর্যন্ত পুরো মুখ তিনবার ধুয়ে নিন। ঘন দাড়ি থাকলে আঙুল দিয়ে খিলাল করুন।", "en": "Wash the whole face three times: from the hairline to below the chin and from ear to ear. Run wet fingers through a thick beard."}}, {"type": "step", "title": {"bn": "দুই হাত কনুইসহ ধোয়া (ফরজ)", "en": "Wash the arms including the elbows (fard)"}, "text": {"bn": "প্রথমে ডান হাত আঙুলের মাথা থেকে কনুইসহ তিনবার, তারপর বাম হাত একইভাবে তিনবার ধুয়ে নিন। আংটি বা চুড়ি থাকলে নাড়িয়ে নিচে পানি পৌঁছান।", "en": "Wash the right arm from the fingertips up to and including the elbow three times, then the left. Move any ring or bangle so water reaches beneath."}}, {"type": "step", "title": {"bn": "মাথা মাসেহ করা (ফরজ)", "en": "Wipe the head (fard)"}, "text": {"bn": "দুই হাত ভিজিয়ে কপালের দিক থেকে মাথার পেছন পর্যন্ত নিয়ে যান, তারপর আবার সামনে ফিরিয়ে আনুন — একবার। পুরো মাথা মাসেহ করা সুন্নত।", "en": "Wet both hands and pass them from the front of the head to the back and return them to the front, once. Wiping the whole head is sunnah."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৮৫ — মাথা মাসেহের পদ্ধতি", "en": "Sahih al-Bukhari 185: how the head is wiped"}}, {"type": "step", "title": {"bn": "কান মাসেহ করা", "en": "Wipe the ears"}, "text": {"bn": "একই ভেজা হাতে শাহাদাত আঙুল দিয়ে কানের ভেতরের অংশ এবং বুড়ো আঙুল দিয়ে কানের পেছনের অংশ মাসেহ করুন।", "en": "With the same wet hands, wipe the inside of the ears with the index fingers and the back of the ears with the thumbs."}}, {"type": "note", "tone": "info", "text": {"bn": "ঘাড় মাসেহ নিয়ে যেসব বর্ণনা আছে সেগুলো দুর্বল। কিছু হানাফি ফকিহ একে মুস্তাহাব বলেছেন, আবার অনেক আলেম বলেন এটি সুন্নত হিসেবে প্রমাণিত নয়। এটি না করলে ওযুর কোনো ক্ষতি হয় না।", "en": "Reports about wiping the neck are weak. Some Hanafi jurists called it recommended, while many scholars say it is not established as sunnah. Leaving it does not affect wudu."}, "check": true}, {"type": "step", "title": {"bn": "দুই পা টাখনুসহ ধোয়া (ফরজ)", "en": "Wash the feet including the ankles (fard)"}, "text": {"bn": "প্রথমে ডান পা টাখনুসহ তিনবার, তারপর বাম পা তিনবার ধুয়ে নিন। বাম হাতের কনিষ্ঠা আঙুল দিয়ে পায়ের আঙুলের ফাঁকে খিলাল করুন। গোড়ালি যেন শুকনো না থাকে।", "en": "Wash the right foot including the ankle three times, then the left. Pass the little finger between the toes. Make sure the heels are not left dry."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৬৫; সহিহ মুসলিম ২৪১ — শুকনো গোড়ালির জন্য সতর্কবাণী", "en": "Sahih al-Bukhari 165; Sahih Muslim 241: the warning about dry heels"}}, {"type": "step", "title": {"bn": "ওযুর পরের দোয়া পড়া", "en": "Recite the dua after wudu"}, "text": {"bn": "ওযু শেষ করে নিচের দোয়াটি পড়ুন। রাসুলুল্লাহ ﷺ বলেছেন, যে ভালোভাবে ওযু করে এই সাক্ষ্য দেয়, তার জন্য জান্নাতের আটটি দরজা খুলে দেওয়া হয়।", "en": "After finishing, recite the dua below. The Prophet ﷺ said that whoever performs wudu well and then says this testimony, the eight gates of Paradise are opened for him."}}, {"type": "arabic", "label": {"bn": "ওযুর পরের দোয়া", "en": "Dua after wudu"}, "ar": "أَشْهَدُ أَنْ لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ", "pron": {"bn": "আশহাদু আল লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারিকা লাহু, ওয়া আশহাদু আন্না মুহাম্মাদান আবদুহু ওয়া রাসুলুহ।", "en": "Ashhadu an la ilaha illallahu wahdahu la sharika lah, wa ashhadu anna Muhammadan ''abduhu wa rasuluh."}, "meaning": {"bn": "আমি সাক্ষ্য দিচ্ছি, আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি এক, তাঁর কোনো শরিক নেই; এবং আমি সাক্ষ্য দিচ্ছি, মুহাম্মাদ ﷺ তাঁর বান্দা ও রাসুল।", "en": "I bear witness that there is no god but Allah alone, with no partner, and I bear witness that Muhammad is His servant and Messenger."}, "ref": {"bn": "সহিহ মুসলিম ২৩৪", "en": "Sahih Muslim 234"}}, {"type": "arabic", "label": {"bn": "সাথে যোগ করা যায়", "en": "Can be added"}, "ar": "اللَّهُمَّ اجْعَلْنِي مِنَ التَّوَّابِينَ، وَاجْعَلْنِي مِنَ الْمُتَطَهِّرِينَ", "pron": {"bn": "আল্লাহুম্মাজ আলনি মিনাত তাওয়াবিনা, ওয়াজ আলনি মিনাল মুতাতাহহিরিন।", "en": "Allahummaj''alni minat-tawwabina waj''alni minal-mutatahhirin."}, "meaning": {"bn": "হে আল্লাহ! আমাকে তওবাকারীদের অন্তর্ভুক্ত করুন এবং পবিত্রতা অর্জনকারীদের অন্তর্ভুক্ত করুন।", "en": "O Allah, make me among those who repent often and among those who purify themselves."}, "ref": {"bn": "সুনান তিরমিযি ৫৫", "en": "Jami'' at-Tirmidhi 55"}}, {"type": "step", "title": {"bn": "দুই রাকাত তাহিয়্যাতুল ওযু (ঐচ্ছিক)", "en": "Two rakats after wudu (optional)"}, "text": {"bn": "ওযুর পর মনোযোগ দিয়ে দুই রাকাত নফল নামাজ পড়া ফজিলতপূর্ণ, যদি তা নিষিদ্ধ সময় না হয় (বিস্তারিত \"বিশেষ নামাজ\" বিভাগে)।", "en": "Praying two voluntary rakats with focus after wudu is virtuous, if it is not a forbidden time (details in the Special Prayers section)."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৫৯; সহিহ মুসলিম ২২৬ — উসমান (রা.) বর্ণিত রাসুলুল্লাহ ﷺ-এর ওযু", "en": "Sahih al-Bukhari 159; Sahih Muslim 226: the Prophet''s wudu as narrated by Uthman (RA)"}}, {"type": "note", "tone": "warn", "text": {"bn": "প্রত্যেক অঙ্গ ধোয়ার সময় আলাদা আলাদা দোয়া (যেমন মুখ ধোয়ার দোয়া, হাত ধোয়ার দোয়া) প্রচলিত আছে, কিন্তু এগুলো রাসুলুল্লাহ ﷺ থেকে নির্ভরযোগ্য সূত্রে প্রমাণিত নয়। শুরুতে বিসমিল্লাহ আর শেষে উপরের দোয়াই যথেষ্ট।", "en": "Separate duas for washing each limb are widespread, but they are not reliably established from the Prophet ﷺ. Bismillah at the start and the dua above at the end are enough."}}, {"type": "note", "tone": "tip", "text": {"bn": "পানি অপচয় করবেন না, প্রতিটি অঙ্গ তিনবারের বেশি ধোবেন না, আর অঙ্গগুলো পরপর ধোবেন — যেন আগের অঙ্গ শুকিয়ে না যায়।", "en": "Do not waste water, do not wash any part more than three times, and wash the parts one after another without long gaps."}}]', 'in_review', 10 FROM is_guide_topics WHERE slug = 'taharah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '4f20252d-a99f-5dd3-8340-9ac6f6a17e1c', id, 'wudu-fard-sunnah', '{"bn": "ওযুর ফরজ, সুন্নত ও মাকরুহ", "en": "Wudu: Fard, Sunnah and Makruh"}', '{"bn": "ওযুর কোন কাজ বাদ পড়লে ওযু হয় না, কোনগুলো সুন্নত, আর কোনগুলো করা অপছন্দনীয় — মাযহাবগুলোর মতপার্থক্যসহ।", "en": "Which acts of wudu are essential, which are sunnah, and which are disliked, with the differences between the madhhabs."}', 'detail', '[{"type": "heading", "text": {"bn": "ওযুর ফরজ (হানাফি মাযহাব অনুযায়ী ৪টি)", "en": "Fard of wudu (four, in the Hanafi madhhab)"}}, {"type": "list", "items": [{"bn": "পুরো মুখমণ্ডল একবার ধোয়া", "en": "Washing the whole face once"}, {"bn": "দুই হাত কনুইসহ একবার ধোয়া", "en": "Washing both arms including the elbows once"}, {"bn": "মাথার এক-চতুর্থাংশ মাসেহ করা", "en": "Wiping a quarter of the head"}, {"bn": "দুই পা টাখনুসহ একবার ধোয়া", "en": "Washing both feet including the ankles once"}]}, {"type": "text", "text": {"bn": "এর যেকোনো একটি বাদ পড়লে, বা কোনো অংশ চুল পরিমাণ শুকনো থাকলে ওযু হবে না। এই চারটি সরাসরি সূরা মায়েদার ৬ নম্বর আয়াতে আছে।", "en": "If any of these is missed, or even a hair''s breadth of the area stays dry, wudu is not valid. All four are named directly in Al-Ma''idah 5:6."}}, {"type": "differ", "title": {"bn": "ওযুর ফরজ কয়টি? — মাযহাবগুলোর মত", "en": "How many fard acts does wudu have?"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "ফরজ ৪টি — আয়াতে উল্লিখিত চার অঙ্গ। নিয়ত, ধারাবাহিকতা (তারতিব) ও পরপর করা (মুওয়ালাত) সুন্নত। মাথার এক-চতুর্থাংশ মাসেহ ফরজ।", "en": "Four: the four parts named in the ayah. Intention, order and continuity are sunnah. Wiping a quarter of the head is the obligatory amount."}, "evidence": {"bn": "সূরা মায়েদা ৫:৬ শুধু এই চারটির আদেশ দেয়। রাসুলুল্লাহ ﷺ মাথার সামনের অংশ (নাসিয়া) মাসেহ করেছেন — সহিহ মুসলিম ২৭৪।", "en": "Al-Ma''idah 5:6 commands only these four. The Prophet ﷺ wiped the front part of his head (Sahih Muslim 274)."}}, {"label": {"bn": "শাফেয়ি", "en": "Shafi''i"}, "text": {"bn": "ফরজ ৬টি — নিয়ত, মুখ, হাত, মাথার সামান্য অংশ মাসেহ, পা এবং ধারাবাহিকতা (তারতিব)।", "en": "Six: intention, face, arms, wiping any part of the head, feet, and doing them in order."}, "evidence": {"bn": "\"সকল কাজ নিয়তের উপর নির্ভরশীল\" — সহিহ বুখারি ১; আয়াতে অঙ্গগুলোর ক্রম এবং রাসুলুল্লাহ ﷺ সবসময় এই ক্রমেই ওযু করেছেন।", "en": "\"Actions are by intentions\" (Sahih al-Bukhari 1); the order in the ayah, and the Prophet ﷺ always kept that order."}}, {"label": {"bn": "মালেকি", "en": "Maliki"}, "text": {"bn": "ফরজ ৭টি — নিয়ত, চার অঙ্গ (পুরো মাথা মাসেহ), অঙ্গ ঘষা (দালক) এবং পরপর করা (মুওয়ালাত)।", "en": "Seven: intention, the four parts (wiping the whole head), rubbing the limbs, and continuity."}, "evidence": {"bn": "আয়াতের \"বিরুউসিকুম\" দ্বারা পুরো মাথা বোঝায়; রাসুলুল্লাহ ﷺ-এর ওযুতে পুরো মাথা মাসেহ — সহিহ বুখারি ১৮৫।", "en": "They read \"your heads\" in the ayah as the whole head; the Prophet ﷺ wiped his whole head (Sahih al-Bukhari 185)."}}, {"label": {"bn": "হাম্বলি", "en": "Hanbali"}, "text": {"bn": "ফরজ ৬টি — চার অঙ্গ (কুলি ও নাকে পানি মুখ ধোয়ার অংশ, পুরো মাথা ও কান মাসেহ), তারতিব ও মুওয়ালাত; নিয়ত শর্ত।", "en": "Six: the four parts (rinsing mouth and nose count as part of the face; the whole head with the ears), order and continuity; intention is a condition."}, "evidence": {"bn": "রাসুলুল্লাহ ﷺ কখনো কুলি ও নাকে পানি দেওয়া ছাড়েননি বলে বর্ণিত; আয়াতের ক্রম ও সুন্নাহর ধারাবাহিক আমল।", "en": "The Prophet ﷺ is not reported to have ever left rinsing the mouth and nose; the order in the ayah and his consistent practice."}}]}, {"type": "heading", "text": {"bn": "ওযুর সুন্নতসমূহ", "en": "Sunnah acts of wudu"}}, {"type": "list", "items": [{"bn": "নিয়ত করা (হানাফি মতে সুন্নত)", "en": "Making the intention (sunnah in the Hanafi view)"}, {"bn": "বিসমিল্লাহ বলে শুরু করা", "en": "Starting with Bismillah"}, {"bn": "দুই হাত কবজি পর্যন্ত তিনবার ধোয়া", "en": "Washing the hands to the wrists three times"}, {"bn": "মিসওয়াক করা", "en": "Using a miswak"}, {"bn": "তিনবার কুলি করা ও তিনবার নাকে পানি দেওয়া", "en": "Rinsing the mouth and nose three times each"}, {"bn": "প্রতিটি অঙ্গ তিনবার করে ধোয়া", "en": "Washing each part three times"}, {"bn": "ঘন দাড়ি এবং হাত-পায়ের আঙুল খিলাল করা", "en": "Running fingers through a thick beard and between fingers and toes"}, {"bn": "পুরো মাথা একবার মাসেহ করা এবং কান মাসেহ করা", "en": "Wiping the whole head once and wiping the ears"}, {"bn": "ডান দিক থেকে শুরু করা", "en": "Starting with the right side"}, {"bn": "কুরআনের ক্রম অনুযায়ী ধারাবাহিকভাবে ধোয়া", "en": "Following the order given in the Quran"}, {"bn": "এক অঙ্গ শুকানোর আগেই পরের অঙ্গ ধোয়া", "en": "Washing each part before the previous one dries"}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৫৯ (উসমান রা.) ও ১৮৫ (আবদুল্লাহ ইবনে যায়েদ রা.) — রাসুলুল্লাহ ﷺ-এর ওযুর বিবরণ", "en": "Sahih al-Bukhari 159 (Uthman RA) and 185 (Abdullah ibn Zayd RA): descriptions of the Prophet''s wudu"}}, {"type": "heading", "text": {"bn": "ওযুতে যা মাকরুহ (অপছন্দনীয়)", "en": "What is disliked (makruh) in wudu"}}, {"type": "list", "items": [{"bn": "প্রয়োজনের চেয়ে বেশি পানি খরচ করা, এমনকি নদীর পাশে থাকলেও", "en": "Using more water than needed, even beside a river"}, {"bn": "কোনো অঙ্গ তিনবারের বেশি ধোয়া", "en": "Washing any part more than three times"}, {"bn": "মুখে জোরে পানি ছিটিয়ে মারা", "en": "Splashing water forcefully on the face"}, {"bn": "ওযুর মধ্যে অপ্রয়োজনীয় দুনিয়াবি কথা বলা", "en": "Unnecessary worldly talk during wudu"}, {"bn": "কোনো সুন্নত ইচ্ছাকৃতভাবে ছেড়ে দেওয়া", "en": "Deliberately leaving out a sunnah"}]}]', 'in_review', 20 FROM is_guide_topics WHERE slug = 'taharah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'bb8d73eb-b5c9-5b9d-9675-5ef6f346d56f', id, 'wudu-breakers', '{"bn": "যেসব কারণে ওযু ভেঙে যায়", "en": "What Breaks Wudu"}', '{"bn": "যেসব কারণে ওযু ভাঙে তাতে সব আলেম একমত, আর কিছু বিষয়ে মতপার্থক্য আছে — দুটোই এখানে।", "en": "Some things break wudu by agreement of all scholars; on others they differ. Both are covered here."}', 'basic', '[{"type": "heading", "text": {"bn": "যেসব কারণে ওযু ভাঙে — সবাই একমত", "en": "What breaks wudu: agreed by all"}}, {"type": "list", "items": [{"bn": "পেশাব-পায়খানার রাস্তা দিয়ে কিছু বের হওয়া: পেশাব, পায়খানা, বায়ু, মজি (কামরস), ওদি ইত্যাদি", "en": "Anything leaving the front or back passage: urine, stool, wind, pre-seminal fluid (madhy), wadi and the like"}, {"bn": "গভীর ঘুম — বিশেষ করে শুয়ে বা হেলান দিয়ে এমনভাবে ঘুমানো যাতে শরীর ঢিলে হয়ে যায়", "en": "Deep sleep, especially lying down or leaning so the body relaxes"}, {"bn": "জ্ঞান হারানো: বেহুঁশ হওয়া, পাগলামি, নেশাগ্রস্ত হওয়া", "en": "Losing consciousness: fainting, insanity, intoxication"}, {"bn": "যেসব কারণে গোসল ফরজ হয় (সহবাস, বীর্যপাত, হায়েজ-নিফাস শেষ হওয়া) — সেগুলো ওযুও ভেঙে দেয়", "en": "Whatever makes ghusl obligatory (intercourse, ejaculation, end of menses or post-natal bleeding) also breaks wudu"}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৩৫ — \"হাদাস\" অর্থ বায়ু বের হওয়া ইত্যাদি", "en": "Sahih al-Bukhari 135: \"hadath\" explained as passing wind and the like"}}, {"type": "heading", "text": {"bn": "মতপার্থক্যপূর্ণ বিষয়", "en": "Points where scholars differ"}}, {"type": "differ", "title": {"bn": "রক্ত, পুঁজ বা বমি বের হলে কি ওযু ভাঙে?", "en": "Does flowing blood, pus or vomit break wudu?"}, "views": [{"label": {"bn": "হানাফি (এবং হাম্বলি — বেশি পরিমাণে হলে)", "en": "Hanafi (and Hanbali, if the amount is large)"}, "text": {"bn": "শরীরের কোথাও থেকে রক্ত বা পুঁজ বের হয়ে গড়িয়ে পড়লে, অথবা মুখ ভরে বমি হলে ওযু ভেঙে যায়। সামান্য রক্ত যা জায়গা থেকে গড়ায় না, তাতে ভাঙে না।", "en": "Blood or pus that flows from any part of the body, or a mouthful of vomit, breaks wudu. A little blood that does not flow does not."}, "evidence": {"bn": "রাসুলুল্লাহ ﷺ বমি করার পর ওযু করেছেন বলে বর্ণিত (সুনান তিরমিযি); কিছু সাহাবির আমল।", "en": "It is reported that the Prophet ﷺ vomited and then made wudu (Jami at-Tirmidhi); practice of some Companions."}}, {"label": {"bn": "শাফেয়ি ও মালেকি", "en": "Shafi''i and Maliki"}, "text": {"bn": "পেশাব-পায়খানার রাস্তা ছাড়া অন্য কোথাও থেকে রক্ত, পুঁজ বা বমি বের হলে ওযু ভাঙে না।", "en": "Blood, pus or vomit from anywhere other than the two passages does not break wudu."}, "evidence": {"bn": "এক আনসারি সাহাবি তির বিদ্ধ হয়ে রক্তাক্ত অবস্থায় নামাজ চালিয়ে গেছেন (সুনান আবু দাউদ); ওযু ভাঙার স্পষ্ট দলিল নেই বলে মূল অবস্থা বহাল।", "en": "A Companion kept praying while bleeding from arrow wounds (Sunan Abi Dawud); with no clear proof, the default (wudu remains) stands."}}], "check": true}, {"type": "differ", "title": {"bn": "লজ্জাস্থান বা বিপরীত লিঙ্গের শরীর স্পর্শ করলে", "en": "Touching the private part, or touching the opposite sex"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "নিজের লজ্জাস্থান স্পর্শ করলে বা স্ত্রী/নারীকে স্পর্শ করলে ওযু ভাঙে না (যদি কিছু বের না হয়)।", "en": "Touching one''s private part, or touching a woman, does not break wudu (if nothing is discharged)."}, "evidence": {"bn": "\"এটা তো তোমার শরীরেরই একটা অংশ\" — সুনান আবু দাউদ ১৮২ (তালক রা.); রাসুলুল্লাহ ﷺ নামাজে আয়েশা (রা.)-এর পা স্পর্শ করতেন — সহিহ বুখারি ৩৮২। সূরা নিসা ৪:৪৩-এর \"লামাসতুম\" দ্বারা ইবনে আব্বাস (রা.) সহবাস বুঝিয়েছেন।", "en": "\"It is only a part of you\" (Sunan Abi Dawud 182, Talq RA); the Prophet ﷺ touched Aisha''s feet while praying (Sahih al-Bukhari 382). Ibn Abbas understood \"lamastum\" in An-Nisa 4:43 as intercourse."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি (মালেকি — শর্তসাপেক্ষে)", "en": "Shafi''i and Hanbali (Maliki with conditions)"}, "text": {"bn": "হাতের তালু দিয়ে সরাসরি লজ্জাস্থান স্পর্শ করলে ওযু ভাঙে। শাফেয়ি মতে গায়রে মাহরাম নারী-পুরুষের ত্বক স্পর্শে ওযু ভাঙে; মালেকি ও হাম্বলি মতে কামভাবসহ স্পর্শ করলে ভাঙে।", "en": "Touching the private part directly with the hand breaks wudu. For Shafi''is, skin contact between a non-mahram man and woman breaks it; for Malikis and Hanbalis, only touch with desire."}, "evidence": {"bn": "\"যে নিজের লজ্জাস্থান স্পর্শ করে, সে যেন ওযু করে\" — সুনান আবু দাউদ ১৮১ (বুসরা রা.); সূরা নিসা ৪:৪৩ \"অথবা তোমরা নারীদের স্পর্শ করো\" আয়াতের বাহ্যিক অর্থ।", "en": "\"Whoever touches his private part, let him make wudu\" (Sunan Abi Dawud 181, Busrah RA); the apparent meaning of \"or you have touched women\" in An-Nisa 4:43."}}]}, {"type": "list", "items": [{"bn": "উটের গোশত খাওয়া: হাম্বলি মতে ওযু ভাঙে (সহিহ মুসলিম ৩৬০), অধিকাংশ আলেমের মতে ভাঙে না।", "en": "Eating camel meat: breaks wudu in the Hanbali view (Sahih Muslim 360); most scholars say it does not."}, {"bn": "নামাজের মধ্যে অট্টহাসি: হানাফি মতে নামাজ ও ওযু দুটোই ভাঙে; অন্যদের মতে শুধু নামাজ ভাঙে।", "en": "Laughing out loud in salah: in the Hanafi view it breaks both salah and wudu; others say only the salah."}]}, {"type": "heading", "text": {"bn": "যেসব কারণে ওযু ভাঙে না", "en": "What does not break wudu"}}, {"type": "list", "items": [{"bn": "ওযু ভেঙেছে কি না — শুধু সন্দেহ হলে। নিশ্চিত না হওয়া পর্যন্ত ওযু আছে ধরে নিতে হবে।", "en": "Mere doubt about whether wudu broke. Wudu remains until you are certain."}, {"bn": "বসে বসে হালকা ঝিমুনি বা তন্দ্রা, যাতে শরীর ঢিলে হয় না", "en": "Light dozing while sitting firmly"}, {"bn": "নখ বা চুল কাটা", "en": "Cutting nails or hair"}, {"bn": "নিজের বা অন্যের সতর দেখে ফেলা", "en": "Seeing someone''s awrah, or one''s own"}, {"bn": "সামান্য রক্ত যা গড়িয়ে পড়ে না", "en": "A little blood that does not flow"}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৩৭; সহিহ মুসলিম ৩৬২ — \"শব্দ না শোনা বা গন্ধ না পাওয়া পর্যন্ত নামাজ ছাড়বে না\"", "en": "Sahih al-Bukhari 137; Sahih Muslim 362: \"Do not leave (the prayer) until you hear a sound or smell something\""}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৩৭৬ — সাহাবিরা বসে ঝিমিয়ে নতুন ওযু ছাড়াই নামাজ পড়তেন", "en": "Sahih Muslim 376: Companions dozed while sitting and prayed without renewing wudu"}}, {"type": "note", "tone": "tip", "text": {"bn": "যার সবসময় ফোঁটা ফোঁটা পেশাব, বায়ু বা রক্ত বের হতে থাকে (মাজুর), সে প্রতি ওয়াক্তে নতুন ওযু করে সেই ওয়াক্তের সব নামাজ পড়বে।", "en": "Someone with a constant flow of urine drops, wind or blood (ma''dhur) makes a fresh wudu for each prayer time and prays all that time''s prayers with it."}}]', 'in_review', 30 FROM is_guide_topics WHERE slug = 'taharah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'af947358-5662-518e-9834-4c4a1a5fc76d', id, 'ghusl-fard', '{"bn": "ফরজ গোসল: কখন ও কীভাবে", "en": "Fard Ghusl: When and How"}', '{"bn": "কোন অবস্থায় গোসল ফরজ হয় এবং সুন্নত পদ্ধতিতে কীভাবে গোসল করতে হয় — ধাপে ধাপে।", "en": "When ghusl becomes obligatory and how to do it the sunnah way, step by step."}', 'basic', '[{"type": "text", "text": {"bn": "বড় নাপাকি (জানাবাত, হায়েজ বা নিফাস) থেকে পবিত্র হওয়ার জন্য পুরো শরীর ধোয়াকে গোসল বলে। গোসল ফরজ থাকা অবস্থায় নামাজ, কাবার তাওয়াফ, কুরআন শরিফ স্পর্শ করা এবং (অধিকাংশ আলেমের মতে) কুরআন তিলাওয়াত করা যায় না।", "en": "Ghusl is washing the whole body to remove major impurity (janabah, menses or post-natal bleeding). Until ghusl is done one may not pray, do tawaf, touch the Mushaf, or (in the view of most scholars) recite the Quran."}}, {"type": "ref", "text": {"bn": "সূরা মায়েদা ৫:৬ — \"আর যদি তোমরা জুনুবি (অপবিত্র) হও, তবে ভালোভাবে পবিত্র হও\"", "en": "Al-Ma''idah 5:6: \"And if you are in a state of janabah, then purify yourselves\""}}, {"type": "heading", "text": {"bn": "যেসব কারণে গোসল ফরজ হয়", "en": "When ghusl becomes obligatory"}}, {"type": "list", "items": [{"bn": "স্বামী-স্ত্রীর সহবাস — বীর্যপাত না হলেও", "en": "Sexual intercourse, even without ejaculation"}, {"bn": "জাগ্রত অবস্থায় উত্তেজনার সাথে বীর্যপাত", "en": "Ejaculation with desire while awake"}, {"bn": "স্বপ্নদোষ — ঘুম থেকে উঠে ভেজা চিহ্ন দেখলে", "en": "A wet dream, if one wakes and finds wetness"}, {"bn": "হায়েজ (মাসিক) শেষ হলে", "en": "When menstruation ends"}, {"bn": "নিফাস (সন্তান প্রসবের পরের রক্তস্রাব) শেষ হলে", "en": "When post-natal bleeding ends"}]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৩৪৮ — সহবাসে গোসল ফরজ, বীর্যপাত না হলেও; সহিহ বুখারি ২৮২ — স্বপ্নে ভেজা দেখলে গোসল", "en": "Sahih Muslim 348: ghusl after intercourse even without ejaculation; Sahih al-Bukhari 282: ghusl when wetness is seen after a dream"}}, {"type": "differ", "title": {"bn": "গোসলের ফরজ কী কী?", "en": "What is obligatory in ghusl?"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "ফরজ ৩টি — ভালোভাবে কুলি করা (গড়গড়াসহ, রোজা না থাকলে), নাকের নরম অংশ পর্যন্ত পানি পৌঁছানো, এবং পুরো শরীর এমনভাবে ধোয়া যাতে একটি চুল পরিমাণ জায়গাও শুকনো না থাকে।", "en": "Three: rinsing the whole mouth, rinsing the nose up to the soft bone, and washing the entire body so that not a hair''s breadth stays dry."}, "evidence": {"bn": "সূরা মায়েদা ৫:৬-এর \"ফাত্তাহহারু\" (ভালোভাবে পবিত্র হও) শব্দ পুরো শরীর, এমনকি মুখ ও নাকের ভেতরের যতটুকু ধোয়া সম্ভব তা-ও অন্তর্ভুক্ত করে।", "en": "The intensive word \"fattahharu\" (purify yourselves thoroughly) in Al-Ma''idah 5:6 includes all of the body, including the inside of mouth and nose as far as can be washed."}}, {"label": {"bn": "হাম্বলি", "en": "Hanbali"}, "text": {"bn": "নিয়তসহ পুরো শরীর ধোয়া ফরজ; কুলি ও নাকে পানি দেওয়াও ওয়াজিব।", "en": "Washing the whole body with intention; rinsing the mouth and nose is also obligatory."}, "evidence": {"bn": "রাসুলুল্লাহ ﷺ গোসলে সবসময় কুলি ও নাকে পানি দিয়েছেন।", "en": "The Prophet ﷺ always rinsed his mouth and nose in ghusl."}}, {"label": {"bn": "শাফেয়ি ও মালেকি", "en": "Shafi''i and Maliki"}, "text": {"bn": "নিয়ত এবং পুরো শরীরে পানি পৌঁছানো ফরজ; কুলি ও নাকে পানি সুন্নত। মালেকি মতে শরীর ঘষা ও পরপর ধোয়াও জরুরি।", "en": "Intention and water reaching the whole body; rinsing the mouth and nose is sunnah. Malikis also require rubbing and continuity."}, "evidence": {"bn": "\"তোমার মাথায় তিন আঁজলা পানি ঢেলে তারপর পুরো শরীরে পানি ঢাললেই তুমি পবিত্র হয়ে যাবে\" — সহিহ মুসলিম ৩৩০।", "en": "\"It is enough for you to pour three handfuls on your head, then pour water over yourself, and you are purified\" (Sahih Muslim 330)."}}]}, {"type": "heading", "text": {"bn": "সুন্নত পদ্ধতিতে গোসল", "en": "Ghusl the sunnah way"}}, {"type": "step", "title": {"bn": "নিয়ত ও বিসমিল্লাহ", "en": "Intention and Bismillah"}, "text": {"bn": "মনে মনে নাপাকি দূর করার নিয়ত করুন এবং বিসমিল্লাহ বলুন (বাথরুমের ভেতরে হলে মনে মনে)।", "en": "Intend in your heart to remove the impurity and say Bismillah (silently if inside the bathroom)."}}, {"type": "step", "title": {"bn": "দুই হাত ধোয়া", "en": "Wash the hands"}, "text": {"bn": "দুই হাত কবজি পর্যন্ত তিনবার ধুয়ে নিন।", "en": "Wash both hands up to the wrists three times."}}, {"type": "step", "title": {"bn": "লজ্জাস্থান ধোয়া ও নাপাকি দূর করা", "en": "Wash the private parts and remove any impurity"}, "text": {"bn": "বাম হাত দিয়ে লজ্জাস্থান এবং শরীরের যেখানে নাপাকি লেগে আছে তা ধুয়ে ফেলুন, তারপর হাত ভালো করে পরিষ্কার করুন।", "en": "With the left hand wash the private parts and any place with impurity, then clean the hand well."}}, {"type": "step", "title": {"bn": "পূর্ণ ওযু করা", "en": "Make a complete wudu"}, "text": {"bn": "নামাজের ওযুর মতো পুরো ওযু করুন। দাঁড়ানোর জায়গায় পানি জমলে পা দুটো সবশেষে ধোয়া যায়।", "en": "Perform a full wudu as for prayer. If water collects where you stand, you may wash the feet at the very end."}}, {"type": "step", "title": {"bn": "মাথায় তিনবার পানি ঢালা", "en": "Pour water over the head three times"}, "text": {"bn": "মাথায় তিনবার পানি ঢালুন এবং আঙুল দিয়ে চুলের গোড়া পর্যন্ত পানি পৌঁছান।", "en": "Pour water on the head three times, working it into the roots of the hair with the fingers."}}, {"type": "step", "title": {"bn": "পুরো শরীরে পানি ঢালা", "en": "Pour water over the whole body"}, "text": {"bn": "প্রথমে ডান কাঁধে, তারপর বাম কাঁধে, তারপর পুরো শরীরে পানি ঢালুন। নাভি, বগল, কানের ভাঁজ, আঙুলের ফাঁক — কোথাও যেন শুকনো না থাকে।", "en": "Pour water over the right shoulder, then the left, then the whole body. Make sure the navel, armpits, folds of the ears and between the fingers and toes are not left dry."}}, {"type": "step", "title": {"bn": "পা ধোয়া", "en": "Wash the feet"}, "text": {"bn": "আগে পা না ধুয়ে থাকলে এখন সরে গিয়ে দুই পা ধুয়ে নিন।", "en": "If you left the feet earlier, move aside and wash them now."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ২৪৮ (আয়েশা রা.) ও ২৪৯ (মাইমুনা রা.); সহিহ মুসলিম ৩১৬, ৩১৭ — রাসুলুল্লাহ ﷺ-এর গোসলের বিবরণ", "en": "Sahih al-Bukhari 248 (Aisha RA) and 249 (Maymunah RA); Sahih Muslim 316, 317: how the Prophet ﷺ performed ghusl"}}, {"type": "note", "tone": "info", "text": {"bn": "নারীদের চুল বেণি বা খোঁপা করা থাকলে, পানি চুলের গোড়ায় পৌঁছালে বেণি খোলা জরুরি নয় (সহিহ মুসলিম ৩৩০)।", "en": "A woman with braided hair need not undo the braids if water reaches the roots (Sahih Muslim 330)."}}, {"type": "note", "tone": "tip", "text": {"bn": "গোসলের আগে নখপালিশ বা পানি আটকায় এমন কিছু থাকলে তুলে ফেলুন; নইলে গোসল হবে না। গোসলের ভেতরে ওযু হয়ে যায় — গোসলের পর ওযু না ভাঙলে নতুন ওযু লাগবে না।", "en": "Remove nail polish or anything that blocks water first, or the ghusl is not valid. Wudu is included in the ghusl: if it is not broken afterwards, no new wudu is needed."}}, {"type": "note", "tone": "info", "text": {"bn": "জুমার দিন, দুই ঈদের দিন এবং ইহরাম বাঁধার আগে গোসল করা সুন্নত (ফরজ নয়)।", "en": "Ghusl on Friday, on the two Eids, and before entering ihram is sunnah, not fard."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৮৭৭ — জুমার জন্য গোসল", "en": "Sahih al-Bukhari 877: ghusl for Jumu''ah"}}]', 'in_review', 40 FROM is_guide_topics WHERE slug = 'taharah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '2f19fc04-d1b4-5347-a8f3-717507f8c76c', id, 'tayammum', '{"bn": "তায়াম্মুম: কখন ও কীভাবে", "en": "Tayammum: When and How"}', '{"bn": "পানি না পেলে বা পানি ব্যবহারে ক্ষতি হলে মাটি দিয়ে পবিত্রতা অর্জন — শর্ত ও পদ্ধতি।", "en": "Purifying with clean earth when water is not available or would cause harm: conditions and method."}', 'basic', '[{"type": "text", "text": {"bn": "তায়াম্মুম আল্লাহর দেওয়া একটি সহজতা। পানি না পাওয়া গেলে বা পানি ব্যবহারে ক্ষতির আশঙ্কা থাকলে ওযু ও গোসল — দুটোর পরিবর্তেই পবিত্র মাটি দিয়ে তায়াম্মুম করা যায়।", "en": "Tayammum is an ease granted by Allah. When water cannot be found or using it would cause harm, tayammum with clean earth replaces both wudu and ghusl."}}, {"type": "arabic", "label": {"bn": "তায়াম্মুমের আয়াত (অংশ)", "en": "The ayah of tayammum (part)"}, "ar": "فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ", "pron": {"bn": "ফালাম তাজিদু মাআন ফাতাইয়াম্মামু সাঈদান তাইয়িবান ফামসাহু বিউজুহিকুম ওয়া আইদিকুম।", "en": "Falam tajidu ma''an fatayammamu sa''idan tayyiban famsahu biwujuhikum wa aydikum."}, "meaning": {"bn": "অতঃপর যদি পানি না পাও, তবে পবিত্র মাটি দিয়ে তায়াম্মুম করো — তা দিয়ে তোমাদের মুখমণ্ডল ও হাত মাসেহ করো।", "en": "And if you find no water, then seek clean earth and wipe your faces and hands with it."}, "ref": {"bn": "সূরা নিসা ৪:৪৩; সূরা মায়েদা ৫:৬", "en": "An-Nisa 4:43; Al-Ma''idah 5:6"}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৩৩৫ — \"সমস্ত জমিন আমার জন্য মসজিদ ও পবিত্রতার উপকরণ করা হয়েছে\"", "en": "Sahih al-Bukhari 335: \"The earth has been made for me a place of prayer and a means of purification\""}}, {"type": "heading", "text": {"bn": "কখন তায়াম্মুম করা যায়", "en": "When tayammum is allowed"}}, {"type": "list", "items": [{"bn": "আশেপাশে পানি পাওয়া যায় না (হানাফি মতে প্রায় এক মাইল বা তার বেশি দূরে)", "en": "No water nearby (in the Hanafi view, about a mile away or more)"}, {"bn": "অসুস্থতা বা ক্ষত, যেখানে পানি ব্যবহারে রোগ বাড়া বা দেরিতে সারার আশঙ্কা আছে", "en": "Illness or wounds where water would worsen or delay healing"}, {"bn": "প্রচণ্ড ঠান্ডা, পানি গরম করার ব্যবস্থা নেই এবং ঠান্ডা পানিতে গুরুতর ক্ষতির আশঙ্কা", "en": "Severe cold with no way to heat water and real risk of harm"}, {"bn": "যে পানি আছে তা খাওয়ার জন্য প্রয়োজন", "en": "The only water available is needed for drinking"}, {"bn": "পানির কাছে যেতে শত্রু, হিংস্র প্রাণী বা অন্য কোনো বিপদের ভয়", "en": "Fear of an enemy, animal or other danger on the way to water"}]}, {"type": "note", "tone": "warn", "text": {"bn": "শুধু অলসতা বা পানি একটু দূরে বলে তায়াম্মুম জায়েজ নয়। পানি ব্যবহারের সামর্থ্য থাকলে তায়াম্মুম দিয়ে নামাজ হবে না।", "en": "Laziness, or water being slightly far, is not a valid reason. If you are able to use water, salah with tayammum is not valid."}}, {"type": "heading", "text": {"bn": "তায়াম্মুমের পদ্ধতি (হানাফি ও শাফেয়ি মত অনুযায়ী)", "en": "How to do tayammum (Hanafi and Shafi''i method)"}}, {"type": "step", "title": {"bn": "নিয়ত", "en": "Intention"}, "text": {"bn": "মনে মনে পবিত্রতা অর্জনের নিয়ত করুন। তায়াম্মুমে নিয়ত সব মাযহাবেই জরুরি।", "en": "Intend in your heart to purify yourself. Intention is required for tayammum in all the madhhabs."}}, {"type": "step", "title": {"bn": "বিসমিল্লাহ", "en": "Bismillah"}, "text": {"bn": "বিসমিল্লাহ বলুন।", "en": "Say Bismillah."}}, {"type": "step", "title": {"bn": "প্রথম বার মাটিতে হাত মারা ও মুখ মাসেহ", "en": "First strike: wipe the face"}, "text": {"bn": "দুই হাতের তালু পবিত্র মাটি, বালু বা পাথরে আলতো করে মারুন, অতিরিক্ত ধুলা ঝেড়ে নিন বা ফুঁ দিন, তারপর পুরো মুখমণ্ডল একবার মাসেহ করুন।", "en": "Strike both palms lightly on clean earth, sand or stone, shake or blow off the excess, then wipe the whole face once."}}, {"type": "step", "title": {"bn": "দ্বিতীয় বার হাত মারা ও দুই হাত মাসেহ", "en": "Second strike: wipe the arms"}, "text": {"bn": "আবার মাটিতে হাত মারুন। বাম হাত দিয়ে ডান হাত আঙুল থেকে কনুইসহ মাসেহ করুন, তারপর ডান হাত দিয়ে বাম হাত একইভাবে। আংটি থাকলে নাড়িয়ে নিন।", "en": "Strike again. Wipe the right arm from the fingers to and including the elbow with the left hand, then the left arm with the right hand. Move any ring."}}, {"type": "differ", "title": {"bn": "তায়াম্মুমে কয়বার মাটিতে হাত মারতে হবে, হাত কতটুকু মাসেহ করতে হবে?", "en": "How many strikes, and how much of the arms is wiped?"}, "views": [{"label": {"bn": "হানাফি ও শাফেয়ি", "en": "Hanafi and Shafi''i"}, "text": {"bn": "দুই বার মারা — একবার মুখের জন্য, একবার কনুইসহ দুই হাতের জন্য।", "en": "Two strikes: one for the face and one for the arms up to and including the elbows."}, "evidence": {"bn": "ইবনে উমর (রা.) সহ কয়েকজন সাহাবি থেকে এভাবে বর্ণিত (সুনান দারাকুতনি, মুয়াত্তা মালিক); ওযুতে হাত কনুই পর্যন্ত ধোয়ার সাথে মিল।", "en": "Reported from Ibn Umar (RA) and others (Sunan ad-Daraqutni, Muwatta Malik); it matches washing the arms to the elbows in wudu."}}, {"label": {"bn": "হাম্বলি ও অনেক মুহাদ্দিস (মালেকি মতে এটুকুই ফরজ)", "en": "Hanbali and many hadith scholars (for Malikis this is the obligatory minimum)"}, "text": {"bn": "একবার মাটিতে হাত মেরে মুখ এবং কবজি পর্যন্ত দুই হাত মাসেহ করাই যথেষ্ট।", "en": "One strike, wiping the face and the hands up to the wrists, is enough."}, "evidence": {"bn": "আম্মার (রা.)-কে রাসুলুল্লাহ ﷺ একবার মাটিতে হাত মেরে মুখ ও দুই হাত মাসেহ করে দেখিয়েছেন — সহিহ বুখারি ৩৩৮; সহিহ মুসলিম ৩৬৮।", "en": "The Prophet ﷺ showed Ammar (RA) one strike, then wiped his face and hands (Sahih al-Bukhari 338; Sahih Muslim 368)."}}], "check": true}, {"type": "heading", "text": {"bn": "তায়াম্মুম কী দিয়ে এবং কখন ভাঙে", "en": "What to use, and what ends tayammum"}}, {"type": "text", "text": {"bn": "মাটি, বালু, পাথর, ইট বা মাটিজাতীয় পবিত্র জিনিস দিয়ে তায়াম্মুম করা যায় (হানাফি মত)। শাফেয়ি মতে ধুলাযুক্ত মাটি জরুরি। যেসব কারণে ওযু বা গোসল ভাঙে, সেগুলোতে তায়াম্মুমও ভাঙে; আর পানি পাওয়া গেলে বা পানি ব্যবহারের সামর্থ্য ফিরে এলে তায়াম্মুম শেষ হয়ে যায়।", "en": "Earth, sand, stone, brick or anything of the earth''s kind may be used (Hanafi view); Shafi''is require earth with dust. Tayammum is broken by whatever breaks wudu or ghusl, and it ends once water is found or one becomes able to use it."}}, {"type": "note", "tone": "info", "text": {"bn": "এক তায়াম্মুমে ওযু ও গোসল দুটোর কাজই হয়, নিয়ত অনুযায়ী। আমর ইবনুল আস (রা.) প্রচণ্ড ঠান্ডায় গোসলের বদলে তায়াম্মুম করেছিলেন এবং রাসুলুল্লাহ ﷺ তা মেনে নিয়েছিলেন (সুনান আবু দাউদ ৩৩৪)।", "en": "The same tayammum serves for wudu or ghusl, according to the intention. Amr ibn al-As (RA) did tayammum instead of ghusl in severe cold and the Prophet ﷺ approved (Sunan Abi Dawud 334)."}, "check": true}]', 'in_review', 50 FROM is_guide_topics WHERE slug = 'taharah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '7509a390-592c-5eab-980e-528a7af765b6', id, 'masah-on-khuff', '{"bn": "মোজার উপর মাসেহ", "en": "Wiping over Khuffs (Leather Socks)"}', '{"bn": "ওযুতে পা না ধুয়ে মোজার উপর মাসেহ করার শর্ত, সময়সীমা ও পদ্ধতি।", "en": "Conditions, time limits and method for wiping over khuffs in wudu instead of washing the feet."}', 'detail', '[{"type": "text", "text": {"bn": "মোজার উপর মাসেহ রাসুলুল্লাহ ﷺ থেকে বহু সাহাবির সূত্রে প্রমাণিত একটি সহজতা। পূর্ণ ওযু করে মোজা পরলে, পরবর্তী ওযুতে পা ধোয়ার বদলে মোজার উপরে ভেজা হাত বুলিয়ে নেওয়া যায়।", "en": "Wiping over khuffs is an ease established from the Prophet ﷺ through many Companions. If you put them on after a complete wudu, in later wudus you may wipe over them with wet hands instead of washing the feet."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ২০৬; সহিহ মুসলিম ২৭৪ — \"এগুলো থাক, আমি পবিত্র অবস্থায় পরেছি\" (মুগিরা রা.)", "en": "Sahih al-Bukhari 206; Sahih Muslim 274: \"Leave them, I put them on in a state of purity\" (al-Mughirah RA)"}}, {"type": "heading", "text": {"bn": "শর্তসমূহ", "en": "Conditions"}}, {"type": "list", "items": [{"bn": "পূর্ণ ওযু করার পর মোজা পরতে হবে", "en": "The khuffs must be put on after a complete wudu"}, {"bn": "মোজা টাখনুসহ পুরো পা ঢেকে রাখবে", "en": "They must cover the whole foot including the ankles"}, {"bn": "এত মজবুত হবে যে তা পরে স্বাভাবিকভাবে হাঁটা যায়", "en": "They must be strong enough to walk in normally"}, {"bn": "বড় ছেঁড়া থাকবে না (হানাফি মতে পায়ের ছোট তিন আঙুল পরিমাণ ছেঁড়া হলে মাসেহ হবে না)", "en": "No large tear (Hanafi: a tear the size of three small toes prevents wiping)"}, {"bn": "গোসল ফরজ হলে মোজা খুলে গোসল করতে হবে — মাসেহ শুধু ওযুর জন্য", "en": "If ghusl becomes due, the khuffs must be removed; wiping is only for wudu"}]}, {"type": "heading", "text": {"bn": "সময়সীমা", "en": "Time limit"}}, {"type": "table", "head": [{"bn": "অবস্থা", "en": "Situation"}, {"bn": "মাসেহের মেয়াদ", "en": "Duration of wiping"}], "rows": [[{"bn": "নিজ এলাকায় অবস্থানকারী (মুকিম)", "en": "Resident"}, {"bn": "এক দিন এক রাত (২৪ ঘণ্টা)", "en": "One day and night (24 hours)"}], [{"bn": "মুসাফির (শরিয়তসম্মত সফরে)", "en": "Traveller (on a journey)"}, {"bn": "তিন দিন তিন রাত (৭২ ঘণ্টা)", "en": "Three days and nights (72 hours)"}]]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৭৬ (আলি রা.)", "en": "Sahih Muslim 276 (Ali RA)"}}, {"type": "note", "tone": "info", "text": {"bn": "হানাফি ও শাফেয়ি মতে মেয়াদ গণনা শুরু হয় মোজা পরার পর প্রথম যখন ওযু ভাঙে তখন থেকে।", "en": "In the Hanafi and Shafi''i views, the period is counted from the first time wudu breaks after putting the khuffs on."}}, {"type": "heading", "text": {"bn": "মাসেহের পদ্ধতি", "en": "How to wipe"}}, {"type": "step", "title": {"bn": "হাত ভেজানো", "en": "Wet the hands"}, "text": {"bn": "ওযুর বাকি সব অঙ্গ ধোয়ার পর দুই হাত পানিতে ভিজিয়ে নিন।", "en": "After washing the other parts of wudu, wet both hands."}}, {"type": "step", "title": {"bn": "মোজার উপরিভাগ মাসেহ", "en": "Wipe the top of the khuffs"}, "text": {"bn": "ডান হাতের আঙুলগুলো ডান পায়ের মোজার উপরে আঙুলের মাথা থেকে টেনে পায়ের গোছার দিকে নিয়ে যান; বাম হাত দিয়ে বাম পায়ে একইভাবে — একবার। হানাফি মতে কমপক্ষে হাতের ছোট তিন আঙুল পরিমাণ জায়গা মাসেহ করা ফরজ।", "en": "Draw the wet fingers of the right hand over the top of the right khuff from the toes towards the shin, and the left hand over the left, once. In the Hanafi view at least the width of three fingers must be wiped."}}, {"type": "note", "tone": "info", "text": {"bn": "মোজার নিচের দিকে বা গোড়ালিতে মাসেহ নেই। আলি (রা.) বলেছেন, দ্বীন যদি নিছক যুক্তি দিয়ে চলত, তবে মোজার উপরের চেয়ে নিচের দিক মাসেহ করাই বেশি যুক্তিযুক্ত হতো (সুনান আবু দাউদ ১৬২)।", "en": "The underside and heel are not wiped. Ali (RA) said that if religion were based on opinion, wiping the underside would seem more fitting than the top (Sunan Abi Dawud 162)."}}, {"type": "heading", "text": {"bn": "মাসেহ যেভাবে ভাঙে", "en": "What ends the wiping"}}, {"type": "list", "items": [{"bn": "যেসব কারণে ওযু ভাঙে", "en": "Anything that breaks wudu (then wipe again in the new wudu)"}, {"bn": "এক বা দুই পায়ের মোজা খুলে ফেলা বা পায়ের বেশির ভাগ বের হয়ে যাওয়া", "en": "Removing one or both khuffs, or most of the foot coming out"}, {"bn": "মেয়াদ শেষ হয়ে যাওয়া", "en": "The time limit running out"}, {"bn": "গোসল ফরজ হওয়া", "en": "Ghusl becoming obligatory"}]}, {"type": "note", "tone": "tip", "text": {"bn": "ওযু থাকা অবস্থায় মোজা খুললে বা মেয়াদ শেষ হলে হানাফি মতে শুধু দুই পা ধুয়ে নিলেই চলে; পুরো ওযু নতুন করে করা উত্তম।", "en": "If you remove the khuffs or the time ends while you still have wudu, the Hanafi view is that washing the feet is enough; repeating the whole wudu is better."}}, {"type": "differ", "title": {"bn": "সাধারণ কাপড়ের বা নাইলনের পাতলা মোজায় মাসেহ করা যাবে কি?", "en": "Can one wipe over ordinary thin cloth or nylon socks?"}, "views": [{"label": {"bn": "হানাফি, শাফেয়ি ও মালেকি", "en": "Hanafi, Shafi''i and Maliki"}, "text": {"bn": "চামড়ার মোজা (খুফ) বা এমন মোটা মোজায় মাসেহ জায়েজ যা খুফের মতো — বাঁধা ছাড়াই পায়ে থাকে, পানি সহজে ভেতরে যায় না এবং পরে অনেক পথ হাঁটা যায়। সাধারণ পাতলা সুতি বা নাইলনের মোজায় মাসেহ জায়েজ নয়।", "en": "Wiping is allowed over leather khuffs, or thick socks that act like khuffs: they stay up without tying, do not let water through easily, and can be walked in for a long distance. Ordinary thin cotton or nylon socks do not qualify."}, "evidence": {"bn": "মাসেহের মূল দলিল খুফ নিয়ে, যা মুতাওয়াতির; অন্য মোজাকে শুধু তখনই খুফের হুকুমে আনা যায় যখন তা খুফের মতো হয়। জাওরাবের হাদিসের সনদ নিয়ে অনেক মুহাদ্দিস আপত্তি করেছেন।", "en": "The mass-transmitted evidence is about khuffs; other socks take the same ruling only if they are like khuffs. Many hadith scholars criticised the chain of the narration about socks (jawrab)."}}, {"label": {"bn": "হাম্বলি ও কিছু আলেম", "en": "Hanbali and some scholars"}, "text": {"bn": "পা ঢেকে রাখে এমন সাধারণ মোজাতেও মাসেহ জায়েজ, যদিও শর্তের বিস্তারিত নিয়ে তাদের মধ্যেও পার্থক্য আছে।", "en": "Wiping over ordinary socks that cover the foot is permitted, though they also differ on the exact conditions."}, "evidence": {"bn": "মুগিরা (রা.) বর্ণনা করেছেন, রাসুলুল্লাহ ﷺ জাওরাব (মোজা) ও জুতার উপর মাসেহ করেছেন — সুনান আবু দাউদ ১৫৯; সুনান তিরমিযি ৯৯; কয়েকজন সাহাবির আমল।", "en": "Al-Mughirah (RA) reported that the Prophet ﷺ wiped over socks and sandals (Sunan Abi Dawud 159; Jami at-Tirmidhi 99); practice of several Companions."}}], "check": true}, {"type": "note", "tone": "info", "text": {"bn": "ক্ষতস্থানে ব্যান্ডেজ বা প্লাস্টার থাকলে এবং তা খুলে পানি দেওয়া ক্ষতিকর হলে, ব্যান্ডেজের উপর ভেজা হাত বুলিয়ে মাসেহ করা যায় — এর কোনো সময়সীমা নেই।", "en": "If there is a bandage or cast on a wound and removing it or washing would cause harm, wipe over it with a wet hand. There is no time limit for this."}}]', 'in_review', 60 FROM is_guide_topics WHERE slug = 'taharah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '29f60a12-ce89-5ef0-b4d7-fd6fb4f267f5', id, 'istinja', '{"bn": "ইস্তিঞ্জা ও টয়লেটের আদব", "en": "Istinja and Toilet Etiquette"}', '{"bn": "পেশাব-পায়খানার পর পবিত্র হওয়ার নিয়ম, টয়লেটে ঢোকা-বের হওয়ার দোয়া এবং জরুরি আদব।", "en": "How to clean oneself after relieving oneself, the duas for entering and leaving, and key etiquette."}', 'basic', '[{"type": "text", "text": {"bn": "পেশাব-পায়খানার পর পানি, টিস্যু বা ঢিলা দিয়ে নাপাকি পরিষ্কার করাকে ইস্তিঞ্জা বলে। পেশাবের ছিটা থেকে সাবধান না থাকা কবরের আজাবের একটি কারণ বলে রাসুলুল্লাহ ﷺ সতর্ক করেছেন।", "en": "Istinja is cleaning away impurity with water, tissue or stones after relieving oneself. The Prophet ﷺ warned that carelessness about urine splashes is a cause of punishment in the grave."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ২১৮; সহিহ মুসলিম ২৯২ — দুই কবরের ঘটনা", "en": "Sahih al-Bukhari 218; Sahih Muslim 292: the two graves"}}, {"type": "heading", "text": {"bn": "টয়লেটে ঢোকার সময়", "en": "When entering the toilet"}}, {"type": "arabic", "label": {"bn": "প্রবেশের দোয়া (বাম পা দিয়ে, ভেতরে যাওয়ার আগে)", "en": "Dua for entering (step in with the left foot, said before entering)"}, "ar": "بِسْمِ اللَّهِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ", "pron": {"bn": "বিসমিল্লাহ, আল্লাহুম্মা ইন্নি আউযু বিকা মিনাল খুবুসি ওয়াল খাবায়িস।", "en": "Bismillah. Allahumma inni a''udhu bika minal-khubuthi wal-khaba''ith."}, "meaning": {"bn": "আল্লাহর নামে। হে আল্লাহ! আমি আপনার কাছে পুরুষ ও নারী শয়তান (সব ধরনের অনিষ্ট) থেকে আশ্রয় চাই।", "en": "In the name of Allah. O Allah, I seek refuge with You from the male and female devils (from all filth and evil)."}, "ref": {"bn": "সহিহ বুখারি ১৪২; সহিহ মুসলিম ৩৭৫ (শুরুতে বিসমিল্লাহ: সুনান তিরমিযি)", "en": "Sahih al-Bukhari 142; Sahih Muslim 375 (Bismillah at the start: Jami at-Tirmidhi)"}, "check": true}, {"type": "heading", "text": {"bn": "বের হওয়ার সময়", "en": "When leaving"}}, {"type": "arabic", "label": {"bn": "বের হওয়ার দোয়া (ডান পা দিয়ে বের হয়ে)", "en": "Dua for leaving (step out with the right foot)"}, "ar": "غُفْرَانَكَ", "pron": {"bn": "গুফরানাকা", "en": "Ghufranaka"}, "meaning": {"bn": "হে আল্লাহ! আমি আপনার ক্ষমা চাই।", "en": "O Allah, I ask Your forgiveness."}, "ref": {"bn": "সুনান আবু দাউদ ৩০; সুনান তিরমিযি ৭", "en": "Sunan Abi Dawud 30; Jami'' at-Tirmidhi 7"}}, {"type": "heading", "text": {"bn": "ইস্তিঞ্জার নিয়ম", "en": "How to do istinja"}}, {"type": "step", "title": {"bn": "বাম হাত ব্যবহার করা", "en": "Use the left hand"}, "text": {"bn": "পরিষ্কারের কাজ বাম হাতে করুন; ডান হাতে লজ্জাস্থান ধরবেন না।", "en": "Clean with the left hand; do not hold the private part with the right hand."}}, {"type": "step", "title": {"bn": "টিস্যু বা ঢিলা", "en": "Tissue or stones"}, "text": {"bn": "প্রথমে টিস্যু, ঢিলা বা পবিত্র কিছু দিয়ে নাপাকি মুছে নিন — বেজোড় সংখ্যায়, কমপক্ষে তিনবার। হাড় বা গোবর দিয়ে নয়।", "en": "First wipe the impurity with tissue, stones or other clean material, an odd number of times and at least three. Not with bone or dung."}}, {"type": "step", "title": {"bn": "পানি দিয়ে ধোয়া", "en": "Wash with water"}, "text": {"bn": "তারপর পানি দিয়ে ভালো করে ধুয়ে নিন। টিস্যু ও পানি দুটো একসাথে ব্যবহার করা সবচেয়ে উত্তম; শুধু পানিও যথেষ্ট।", "en": "Then wash well with water. Using both tissue and water is best; water alone is enough."}}, {"type": "step", "title": {"bn": "হাত পরিষ্কার করা", "en": "Clean the hands"}, "text": {"bn": "শেষে সাবান বা মাটি দিয়ে হাত ভালোভাবে ধুয়ে নিন।", "en": "Finally wash the hands well with soap or earth."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৬২ (সালমান রা.) — কিবলামুখী না হওয়া, ডান হাতে ইস্তিঞ্জা না করা, তিনটির কম ঢিলা না নেওয়া, হাড় ও গোবর ব্যবহার না করা", "en": "Sahih Muslim 262 (Salman RA): not facing the qiblah, not cleaning with the right hand, not fewer than three stones, not using bone or dung"}}, {"type": "heading", "text": {"bn": "জরুরি আদব", "en": "Key etiquette"}}, {"type": "list", "items": [{"bn": "পেশাব-পায়খানার সময় কিবলার দিকে মুখ বা পিঠ করে বসবেন না — খোলা জায়গায় এটা নিষিদ্ধ; ঘরের ভেতরেও এড়িয়ে চলা নিরাপদ (হানাফি মতে ঘরের ভেতরেও মাকরুহ)।", "en": "Do not face or turn your back to the qiblah while relieving yourself. It is forbidden in the open; avoiding it indoors is safer (Hanafis hold it disliked indoors too)."}, {"bn": "পেশাবের ছিটা যেন শরীর বা কাপড়ে না লাগে; সম্ভব হলে বসে পেশাব করুন।", "en": "Avoid splashes on the body and clothes; sit to urinate where possible."}, {"bn": "আল্লাহর নাম লেখা কিছু (যেমন আংটি বা কাগজ) টয়লেটে না নেওয়া উত্তম।", "en": "It is better not to take anything with Allah''s name written on it into the toilet."}, {"bn": "ভেতরে কথা বলা, জিকির বা সালামের জবাব দেওয়া থেকে বিরত থাকুন।", "en": "Avoid talking, dhikr or returning greetings inside."}, {"bn": "মানুষের চলাচলের পথ, ছায়া ও পানির উৎসে পেশাব-পায়খানা করবেন না।", "en": "Do not relieve yourself on paths, in shade people use, or in water sources."}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৪৪; সহিহ মুসলিম ২৬৪ — কিবলার দিকে মুখ বা পিঠ না করা (আবু আইয়ুব রা.)", "en": "Sahih al-Bukhari 144; Sahih Muslim 264: not facing or turning one''s back to the qiblah (Abu Ayyub RA)"}}]', 'in_review', 70 FROM is_guide_topics WHERE slug = 'taharah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'b46fb125-3852-5d8f-ae39-fc8735d6fe26', id, 'hayd-nifas-salah', '{"bn": "হায়েজ ও নিফাস: নামাজের বিধান", "en": "Menstruation and Post-natal Bleeding: Rulings for Salah"}', '{"bn": "মাসিক ও প্রসব-পরবর্তী রক্তস্রাবের সময় নামাজ, রোজা ও অন্যান্য ইবাদতের বিধান — সংক্ষেপে।", "en": "A short guide to salah, fasting and other worship during menstruation and post-natal bleeding."}', 'detail', '[{"type": "text", "text": {"bn": "হায়েজ (মাসিক) ও নিফাস (সন্তান প্রসবের পরের রক্তস্রাব) আল্লাহর সৃষ্টিগত স্বাভাবিক বিষয়। এ সময় নারীদের জন্য নামাজ মাফ — এটা আল্লাহর দেওয়া সহজতা, এতে কোনো গুনাহ নেই।", "en": "Menstruation (hayd) and post-natal bleeding (nifas) are natural matters created by Allah. During them women are excused from salah. It is an ease from Allah, and there is no sin in it."}}, {"type": "ref", "text": {"bn": "সূরা বাকারা ২:২২২", "en": "Al-Baqarah 2:222"}}, {"type": "heading", "text": {"bn": "এ সময় যা নিষিদ্ধ", "en": "What is not allowed during this time"}}, {"type": "list", "items": [{"bn": "নামাজ পড়া — এবং পরে এই নামাজগুলো কাজা করতে হয় না", "en": "Praying salah, and these prayers are not made up later"}, {"bn": "রোজা রাখা — তবে রমজানের ছুটে যাওয়া রোজা পরে কাজা করতে হবে", "en": "Fasting, but missed Ramadan fasts must be made up later"}, {"bn": "কাবার তাওয়াফ", "en": "Tawaf of the Ka''bah"}, {"bn": "কুরআন শরিফ (মুসহাফ) সরাসরি স্পর্শ করা", "en": "Touching the Mushaf directly"}, {"bn": "মসজিদে অবস্থান করা", "en": "Staying in the mosque"}, {"bn": "স্বামী-স্ত্রীর মিলন", "en": "Marital intercourse"}]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৩৩৫; সহিহ বুখারি ৩২১ — \"আমাদের রোজা কাজা করার আদেশ দেওয়া হতো, নামাজ কাজার আদেশ দেওয়া হতো না\" (আয়েশা রা.)", "en": "Sahih Muslim 335; Sahih al-Bukhari 321: \"We were ordered to make up the fasts but not the prayers\" (Aisha RA)"}}, {"type": "note", "tone": "info", "text": {"bn": "অধিকাংশ আলেমের (হানাফি, শাফেয়ি, হাম্বলি) মতে এ সময় কুরআন তিলাওয়াত করা যায় না; মালেকি মাযহাব ও কিছু আলেম অনুমতি দিয়েছেন, কারণ নিষেধের হাদিসটির সনদ দুর্বল। জিকির, দোয়া, দরুদ, ইস্তিগফার এবং কুরআন শোনা সবার মতেই জায়েজ।", "en": "Most scholars (Hanafi, Shafi''i, Hanbali) hold that she does not recite the Quran in this state; the Maliki school and some others allow it, as the hadith forbidding it has a weak chain. Dhikr, dua, durood, istighfar and listening to the Quran are allowed by all."}, "check": true}, {"type": "heading", "text": {"bn": "সময়সীমা", "en": "Durations"}}, {"type": "differ", "title": {"bn": "হায়েজ ও নিফাসের সর্বনিম্ন ও সর্বোচ্চ সময়", "en": "Minimum and maximum duration of hayd and nifas"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "হায়েজ: সর্বনিম্ন ৩ দিন, সর্বোচ্চ ১০ দিন। নিফাস: সর্বোচ্চ ৪০ দিন, সর্বনিম্ন কোনো সীমা নেই। এর বাইরের রক্ত ইস্তিহাযা (রোগজনিত)।", "en": "Hayd: minimum 3 days, maximum 10. Nifas: maximum 40 days, no minimum. Bleeding outside these limits is istihadah (irregular bleeding)."}, "evidence": {"bn": "কিছু সাহাবি থেকে বর্ণিত বক্তব্য (যার সনদ নিয়ে আলোচনা আছে); নিফাসে নারীরা ৪০ দিন বসে থাকতেন — সুনান আবু দাউদ ৩১১।", "en": "Statements reported from some Companions (whose chains are discussed); women used to wait 40 days after childbirth (Sunan Abi Dawud 311)."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি (মালেকি ভিন্ন হিসাবে)", "en": "Shafi''i and Hanbali (Maliki counts differently)"}, "text": {"bn": "হায়েজ: সর্বনিম্ন এক দিন এক রাত, সর্বোচ্চ ১৫ দিন। নিফাস: সর্বোচ্চ ৬০ দিন (শাফেয়ি, মালেকি) বা ৪০ দিন (হাম্বলি)।", "en": "Hayd: minimum one day and night, maximum 15 days. Nifas: maximum 60 days (Shafi''i, Maliki) or 40 (Hanbali)."}, "evidence": {"bn": "কুরআন-হাদিসে নির্দিষ্ট সীমা স্পষ্টভাবে নেই বলে তারা নারীদের বাস্তব অভিজ্ঞতা ও প্রচলিত অভ্যাসকে ভিত্তি ধরেছেন।", "en": "As the texts give no explicit limit, they based it on women''s actual, observed patterns."}}], "check": true}, {"type": "heading", "text": {"bn": "পবিত্র হলে নামাজ", "en": "Resuming salah"}}, {"type": "step", "title": {"bn": "রক্ত বন্ধ হলে গোসল", "en": "Ghusl when the bleeding stops"}, "text": {"bn": "রক্ত পুরোপুরি বন্ধ হলে (সাদা স্রাব দেখা গেলে বা পুরো শুকনো থাকলে) ফরজ গোসল করে নামাজ শুরু করুন। নিফাসে ৪০ দিনের আগে রক্ত বন্ধ হলেও গোসল করে নামাজ পড়তে হবে।", "en": "When the bleeding fully stops (clear discharge or complete dryness), do the obligatory ghusl and start praying. If post-natal bleeding stops before 40 days, she still does ghusl and prays."}}, {"type": "step", "title": {"bn": "ওয়াক্তের ভেতরে পবিত্র হলে", "en": "Becoming pure within a prayer time"}, "text": {"bn": "কোনো নামাজের ওয়াক্ত থাকতেই রক্ত বন্ধ হলে, গোসল করে সেই ওয়াক্তের নামাজ আদায় করা জরুরি। কতটুকু সময় বাকি থাকলে নামাজ জরুরি হয় — এর বিস্তারিত নিয়ে মাযহাবগুলোতে পার্থক্য আছে; স্থানীয় আলেমের কাছে জেনে নিন।", "en": "If the bleeding stops while a prayer''s time remains, she does ghusl and prays that prayer. How much time must remain for this differs between the madhhabs; ask a local scholar for the details."}}, {"type": "note", "tone": "info", "text": {"bn": "পবিত্র হওয়ার পর হলুদ বা বাদামি স্রাব দেখা দিলে তা হায়েজ হিসেবে গণ্য হয় না (সহিহ বুখারি ৩২৬)।", "en": "Yellowish or brownish discharge after purity is not counted as menstruation (Sahih al-Bukhari 326)."}}, {"type": "heading", "text": {"bn": "ইস্তিহাযা (অনিয়মিত রক্তস্রাব)", "en": "Istihadah (irregular bleeding)"}}, {"type": "text", "text": {"bn": "স্বাভাবিক সময়ের বাইরে যে রক্ত আসে তা ইস্তিহাযা — এটা রোগজনিত, হায়েজ নয়। এ অবস্থায় নামাজ-রোজা মাফ নয়। প্রতি ওয়াক্তে নতুন ওযু করে নামাজ পড়বেন এবং প্যাড ব্যবহার করবেন।", "en": "Bleeding outside the normal pattern is istihadah: an illness, not menstruation. Salah and fasting are not excused. She makes a fresh wudu for each prayer time, uses a pad, and prays."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ২২৮ — \"এটা একটা শিরার রক্ত, হায়েজ নয়… প্রত্যেক নামাজের জন্য ওযু করো\" (ফাতিমা বিনতে আবি হুবাইশ রা.)", "en": "Sahih al-Bukhari 228: \"That is from a blood vessel, not menstruation… make wudu for every prayer\" (Fatimah bint Abi Hubaysh RA)"}}, {"type": "note", "tone": "tip", "text": {"bn": "নিজের মাসিকের নিয়ম (কত দিন, কবে শুরু) লিখে রাখলে ইস্তিহাযা আর হায়েজ আলাদা করা সহজ হয়। জটিল অবস্থায় একজন নির্ভরযোগ্য আলেম ও ডাক্তারের পরামর্শ নিন।", "en": "Keeping a record of your usual cycle (how many days, when it starts) makes it easier to tell istihadah from menstruation. In complicated cases, consult a trusted scholar and a doctor."}}]', 'in_review', 80 FROM is_guide_topics WHERE slug = 'taharah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '07e0a56a-7be7-50b7-ae6f-9a877d06d1d6', id, 'salah-importance', '{"bn": "নামাজের গুরুত্ব", "en": "The Importance of Salah"}', '{"bn": "নামাজ ইসলামের দ্বিতীয় স্তম্ভ এবং কিয়ামতের দিন বান্দার প্রথম হিসাব। কুরআন ও সহিহ হাদিসে নামাজের মর্যাদা।", "en": "Salah is the second pillar of Islam and the first deed to be judged on the Day of Judgement. Its place in the Quran and authentic hadith."}', 'basic', '[{"type": "text", "text": {"bn": "ঈমানের পর ইসলামের সবচেয়ে বড় ফরজ ইবাদত হলো নামাজ। প্রত্যেক প্রাপ্তবয়স্ক, সুস্থ মস্তিষ্কের মুসলিম নারী-পুরুষের উপর দিনে পাঁচ ওয়াক্ত নামাজ ফরজ। অসুস্থ হলে বসে বা শুয়ে, সফরে সংক্ষেপে — কিন্তু জ্ঞান থাকা পর্যন্ত নামাজ মাফ হয় না।", "en": "After faith, salah is the greatest obligation in Islam. Five daily prayers are obligatory on every adult, sane Muslim man and woman. When ill one prays sitting or lying down, when travelling it is shortened, but as long as one is conscious it is never dropped."}}, {"type": "arabic", "label": {"bn": "নামাজের প্রতি যত্নবান হওয়ার আদেশ", "en": "The command to guard the prayers"}, "ar": "حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلَاةِ الْوُسْطَىٰ وَقُومُوا لِلَّهِ قَانِتِينَ", "pron": {"bn": "হাফিযু আলাস সালাওয়াতি ওয়াস সালাতিল উসতা, ওয়া কুমু লিল্লাহি কানিতিন।", "en": "Hafizu ''alas-salawati was-salatil-wusta wa qumu lillahi qanitin."}, "meaning": {"bn": "তোমরা নামাজগুলোর প্রতি যত্নবান হও, বিশেষ করে মধ্যবর্তী নামাজের প্রতি, এবং আল্লাহর সামনে বিনীতভাবে দাঁড়াও।", "en": "Guard the prayers, especially the middle prayer, and stand before Allah in devout obedience."}, "ref": {"bn": "সূরা বাকারা ২:২৩৮", "en": "Al-Baqarah 2:238"}}, {"type": "arabic", "label": {"bn": "নামাজ মন্দ কাজ থেকে বিরত রাখে", "en": "Prayer restrains from wrong"}, "ar": "وَأَقِمِ الصَّلَاةَ ۖ إِنَّ الصَّلَاةَ تَنْهَىٰ عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ", "pron": {"bn": "ওয়া আকিমিস সালাহ, ইন্নাস সালাতা তানহা আনিল ফাহশায়ি ওয়াল মুনকার।", "en": "Wa aqimis-salah, innas-salata tanha ''anil-fahsha''i wal-munkar."}, "meaning": {"bn": "আর নামাজ কায়েম করো। নিশ্চয়ই নামাজ অশ্লীল ও মন্দ কাজ থেকে বিরত রাখে।", "en": "And establish prayer. Indeed, prayer restrains from indecency and wrongdoing."}, "ref": {"bn": "সূরা আনকাবুত ২৯:৪৫ (অংশ)", "en": "Al-''Ankabut 29:45 (part)"}}, {"type": "heading", "text": {"bn": "হাদিসে নামাজের মর্যাদা", "en": "Salah in the hadith"}}, {"type": "list", "items": [{"bn": "ইসলাম পাঁচটি স্তম্ভের উপর প্রতিষ্ঠিত — কালিমার সাক্ষ্য, নামাজ কায়েম, যাকাত, হজ ও রমজানের রোজা। (সহিহ বুখারি ৮; সহিহ মুসলিম ১৬)", "en": "Islam is built on five: the testimony, establishing prayer, zakat, hajj and fasting Ramadan. (Sahih al-Bukhari 8; Sahih Muslim 16)"}, {"bn": "কিয়ামতের দিন বান্দার আমলের মধ্যে প্রথম হিসাব নেওয়া হবে নামাজের। (সুনান তিরমিযি ৪১৩)", "en": "The first of a servant''s deeds to be judged on the Day of Resurrection is his prayer. (Jami at-Tirmidhi 413)"}, {"bn": "কারো দরজার সামনে নদী থাকলে আর সে দিনে পাঁচবার তাতে গোসল করলে যেমন শরীরে ময়লা থাকে না, পাঁচ ওয়াক্ত নামাজ তেমনি গুনাহ মুছে দেয়। (সহিহ বুখারি ৫২৮; সহিহ মুসলিম ৬৬৭)", "en": "Like a river at one''s door in which one bathes five times a day, leaving no dirt, the five prayers wipe away sins. (Sahih al-Bukhari 528; Sahih Muslim 667)"}, {"bn": "আল্লাহর কাছে সবচেয়ে প্রিয় আমল — সময়মতো নামাজ পড়া। (সহিহ বুখারি ৫২৭)", "en": "The deed most beloved to Allah is prayer at its proper time. (Sahih al-Bukhari 527)"}, {"bn": "মানুষ এবং শিরক-কুফরের মাঝে পার্থক্য হলো নামাজ ছেড়ে দেওয়া। (সহিহ মুসলিম ৮২)", "en": "Between a man and shirk and disbelief is abandoning the prayer. (Sahih Muslim 82)"}]}, {"type": "heading", "text": {"bn": "খুশু: মনোযোগ ও বিনয়", "en": "Khushu: focus and humility"}}, {"type": "arabic", "ar": "قَدْ أَفْلَحَ الْمُؤْمِنُونَ ﴿١﴾ الَّذِينَ هُمْ فِي صَلَاتِهِمْ خَاشِعُونَ ﴿٢﴾", "pron": {"bn": "কাদ আফলাহাল মু''মিনুন। আল্লাযিনা হুম ফি সালাতিহিম খাশিউন।", "en": "Qad aflahal-mu''minun. Alladhina hum fi salatihim khashi''un."}, "meaning": {"bn": "নিশ্চয়ই সফল হয়েছে মুমিনরা, যারা নিজেদের নামাজে বিনয়ী ও মনোযোগী।", "en": "Successful indeed are the believers, those who are humble and focused in their prayer."}, "ref": {"bn": "সূরা মুমিনুন ২৩:১–২", "en": "Al-Mu''minun 23:1–2"}}, {"type": "text", "text": {"bn": "নামাজে কী পড়ছেন তার অর্থ জানলে মনোযোগ অনেক বাড়ে। তাই এই গাইডের প্রতিটি দোয়া ও সূরার সাথে অর্থ দেওয়া আছে। রাসুলুল্লাহ ﷺ বলেছেন: \"তোমরা আমাকে যেভাবে নামাজ পড়তে দেখেছ, সেভাবে নামাজ পড়ো।\"", "en": "Knowing the meaning of what you recite greatly helps focus, so every dua and surah in these guides comes with its meaning. The Prophet ﷺ said: \"Pray as you have seen me praying.\""}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৬৩১", "en": "Sahih al-Bukhari 631"}}, {"type": "heading", "text": {"bn": "ছুটে যাওয়া নামাজ ও সন্তানদের শেখানো", "en": "Missed prayers and teaching children"}}, {"type": "list", "items": [{"bn": "ঘুম বা ভুলে যাওয়ার কারণে নামাজ ছুটে গেলে মনে পড়ামাত্র তা আদায় (কাজা) করতে হবে। (সহিহ বুখারি ৫৯৭; সহিহ মুসলিম ৬৮৪)", "en": "A prayer missed through sleep or forgetfulness is prayed (made up) as soon as it is remembered. (Sahih al-Bukhari 597; Sahih Muslim 684)"}, {"bn": "সন্তানের বয়স সাত হলে নামাজের আদেশ দাও, দশ বছরে নামাজের জন্য শাসন করো। (সুনান আবু দাউদ ৪৯৫)", "en": "Command your children to pray at seven, and discipline them for it at ten. (Sunan Abi Dawud 495)"}]}, {"type": "note", "tone": "tip", "text": {"bn": "নামাজ ছেড়ে দিয়ে থাকলে হতাশ হবেন না — আজই তওবা করে পরের ওয়াক্ত থেকে শুরু করুন। ছুটে যাওয়া ফরজ নামাজের কাজা কীভাবে করবেন, তা একজন আলেমের সাথে পরামর্শ করে ঠিক করে নিন।", "en": "If you have left prayer, do not despair: repent today and start from the next prayer. Ask a scholar how to plan making up missed obligatory prayers."}}]', 'in_review', 10 FROM is_guide_topics WHERE slug = 'salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '43c0925a-b591-5194-8f7f-70d0c076b367', id, 'salah-times-rakats', '{"bn": "পাঁচ ওয়াক্ত নামাজ: রাকাত সংখ্যা ও সময়", "en": "The Five Prayers: Rakats and Times"}', '{"bn": "কোন নামাজে কত রাকাত ফরজ, সুন্নত, বিতর ও নফল; প্রতিটি নামাজের শুরু-শেষের সময় এবং নিষিদ্ধ সময়।", "en": "How many fard, sunnah, witr and nafl rakats each prayer has; when each prayer begins and ends; and the forbidden times."}', 'basic', '[{"type": "heading", "text": {"bn": "রাকাত সংখ্যার তালিকা", "en": "Table of rakats"}}, {"type": "table", "head": [{"bn": "নামাজ", "en": "Prayer"}, {"bn": "ফরজ", "en": "Fard"}, {"bn": "সুন্নতে মুয়াক্কাদা", "en": "Sunnah muakkadah"}, {"bn": "সুন্নতে গায়রে মুয়াক্কাদা", "en": "Sunnah ghair muakkadah"}, {"bn": "বিতর", "en": "Witr"}, {"bn": "নফল (ঐচ্ছিক)", "en": "Nafl (optional)"}], "rows": [[{"bn": "ফজর", "en": "Fajr"}, {"bn": "২", "en": "2"}, {"bn": "২ (ফরজের আগে)", "en": "2 (before fard)"}, {"bn": "—", "en": "—"}, {"bn": "—", "en": "—"}, {"bn": "—", "en": "—"}], [{"bn": "জোহর", "en": "Zuhr"}, {"bn": "৪", "en": "4"}, {"bn": "৪ (আগে) + ২ (পরে)", "en": "4 (before) + 2 (after)"}, {"bn": "—", "en": "—"}, {"bn": "—", "en": "—"}, {"bn": "২ (পরে)", "en": "2 (after)"}], [{"bn": "আসর", "en": "Asr"}, {"bn": "৪", "en": "4"}, {"bn": "—", "en": "—"}, {"bn": "৪ (আগে)", "en": "4 (before)"}, {"bn": "—", "en": "—"}, {"bn": "—", "en": "—"}], [{"bn": "মাগরিব", "en": "Maghrib"}, {"bn": "৩", "en": "3"}, {"bn": "২ (পরে)", "en": "2 (after)"}, {"bn": "—", "en": "—"}, {"bn": "—", "en": "—"}, {"bn": "২ (পরে)", "en": "2 (after)"}], [{"bn": "এশা", "en": "Isha"}, {"bn": "৪", "en": "4"}, {"bn": "২ (পরে)", "en": "2 (after)"}, {"bn": "৪ (আগে)", "en": "4 (before)"}, {"bn": "৩ (এশার পর)", "en": "3 (after Isha)"}, {"bn": "২ (সুন্নতের পর) + ২ (বিতরের পর)", "en": "2 (after sunnah) + 2 (after witr)"}]]}, {"type": "note", "tone": "info", "text": {"bn": "ফরজ মোট ১৭ রাকাত — এতে সব মাযহাব একমত। সুন্নতের হিসাব উপরে বাংলাদেশে প্রচলিত হানাফি মত অনুযায়ী। শাফেয়ি ও হাম্বলি মতে জোহরের আগে নিয়মিত সুন্নত ২ রাকাত (ইবনে উমর রা.-এর বর্ণনা, সহিহ বুখারি ১১৮০), যদিও ৪ রাকাতও প্রমাণিত (সহিহ বুখারি ১১৮২)। বিতর নামাজের বিস্তারিত নিয়ম ও দোয়া কুনুত \"বিশেষ নামাজ\" বিভাগে দেওয়া আছে।", "en": "The fard total of 17 rakats is agreed by all. The sunnah counts above follow the Hanafi practice common in Bangladesh. Shafi''is and Hanbalis count 2 regular rakats before Zuhr (Ibn Umar''s report, Sahih al-Bukhari 1180), though 4 is also established (Sahih al-Bukhari 1182). The full method of witr and the dua qunut are in the Special Prayers section."}}, {"type": "text", "text": {"bn": "সুন্নতে মুয়াক্কাদা হলো সেই সুন্নত যা রাসুলুল্লাহ ﷺ নিয়মিত পড়তেন এবং খুব কমই ছেড়েছেন; বিনা কারণে নিয়মিত ছেড়ে দেওয়া উচিত নয়। গায়রে মুয়াক্কাদা পড়লে সওয়াব, না পড়লে গুনাহ নেই। রাসুলুল্লাহ ﷺ বলেছেন, যে দিনে-রাতে ১২ রাকাত (সুন্নত) পড়ে, তার জন্য জান্নাতে একটি ঘর তৈরি করা হয়।", "en": "Sunnah muakkadah are the sunnahs the Prophet ﷺ prayed regularly and rarely left; they should not be habitually skipped without reason. Ghair muakkadah earn reward if prayed, with no sin if left. The Prophet ﷺ said that whoever prays twelve (sunnah) rakats in a day and night, a house is built for him in Paradise."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৭২৮; বিস্তারিত তালিকা: সুনান তিরমিযি", "en": "Sahih Muslim 728; the detailed list: Jami at-Tirmidhi"}, "check": true}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৭২৫ — \"ফজরের দুই রাকাত (সুন্নত) দুনিয়া ও তার সবকিছুর চেয়ে উত্তম\"", "en": "Sahih Muslim 725: \"The two rakats of Fajr are better than the world and all it contains\""}}, {"type": "note", "tone": "info", "text": {"bn": "জুমার দিন জোহরের বদলে দুই রাকাত জুমার ফরজ নামাজ পড়া হয়। জুমার আগে-পরের সুন্নতের বিস্তারিত \"বিশেষ নামাজ\" বিভাগে দেওয়া আছে।", "en": "On Friday, two rakats of Jumu''ah replace Zuhr. The sunnahs before and after Jumu''ah are covered in the Special Prayers section."}}, {"type": "heading", "text": {"bn": "নামাজের সময়", "en": "Prayer times"}}, {"type": "table", "head": [{"bn": "নামাজ", "en": "Prayer"}, {"bn": "শুরু", "en": "Begins"}, {"bn": "শেষ", "en": "Ends"}], "rows": [[{"bn": "ফজর", "en": "Fajr"}, {"bn": "সুবহে সাদিক — পূর্ব আকাশে সাদা আলো আড়াআড়িভাবে ছড়িয়ে পড়া", "en": "True dawn: when white light spreads across the eastern horizon"}, {"bn": "সূর্যোদয় শুরু হওয়া পর্যন্ত", "en": "Until sunrise begins"}], [{"bn": "জোহর", "en": "Zuhr"}, {"bn": "সূর্য মাথার উপর থেকে পশ্চিমে হেলে পড়ার পর (জাওয়াল)", "en": "Once the sun passes its zenith and begins to decline"}, {"bn": "আসরের সময় শুরু হওয়া পর্যন্ত (নিচের মতপার্থক্য দেখুন)", "en": "Until Asr begins (see the difference below)"}], [{"bn": "আসর", "en": "Asr"}, {"bn": "জোহরের সময় শেষ হলে", "en": "When Zuhr time ends"}, {"bn": "সূর্যাস্ত পর্যন্ত; তবে সূর্য হলুদ হয়ে যাওয়া পর্যন্ত দেরি করা মাকরুহ", "en": "Until sunset, but delaying until the sun turns yellow is disliked"}], [{"bn": "মাগরিব", "en": "Maghrib"}, {"bn": "সূর্য পুরোপুরি অস্ত যাওয়ার পর", "en": "Right after the sun has fully set"}, {"bn": "পশ্চিম আকাশের লালিমা (শাফাক) মিলিয়ে যাওয়া পর্যন্ত", "en": "Until the twilight (shafaq) disappears from the western sky"}], [{"bn": "এশা", "en": "Isha"}, {"bn": "শাফাক মিলিয়ে যাওয়ার পর", "en": "After the twilight disappears"}, {"bn": "সুবহে সাদিক পর্যন্ত; তবে মধ্যরাতের আগে পড়ে নেওয়া উত্তম", "en": "Until true dawn, but it is best prayed before midnight"}]]}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ ৩৯৩; সুনান তিরমিযি ১৪৯ — জিবরাইল (আ.)-এর ইমামতি; সহিহ মুসলিম ৬১২ — নামাজের সময়সমূহ", "en": "Sunan Abi Dawud 393; Jami at-Tirmidhi 149: Jibril leading the prayers; Sahih Muslim 612: the prayer times"}}, {"type": "differ", "title": {"bn": "আসরের সময় কখন শুরু হয়?", "en": "When does Asr time begin?"}, "views": [{"label": {"bn": "অধিকাংশ আলেম (শাফেয়ি, মালেকি, হাম্বলি; হানাফি ইমাম আবু ইউসুফ ও মুহাম্মাদ)", "en": "Most scholars (Shafi''i, Maliki, Hanbali; the Hanafi imams Abu Yusuf and Muhammad)"}, "text": {"bn": "কোনো বস্তুর ছায়া (দুপুরের মূল ছায়া বাদ দিয়ে) যখন বস্তুর সমান হয়, তখন জোহর শেষ হয়ে আসর শুরু হয়।", "en": "Asr begins when an object''s shadow (beyond its noon shadow) equals its length."}, "evidence": {"bn": "জিবরাইল (আ.) প্রথম দিন ছায়া এক গুণ হলে আসর পড়িয়েছেন — সুনান আবু দাউদ ৩৯৩; সুনান তিরমিযি ১৪৯; সহিহ মুসলিম ৬১২।", "en": "Jibril led Asr on the first day when the shadow equalled the object (Sunan Abi Dawud 393; Jami at-Tirmidhi 149; Sahih Muslim 612)."}}, {"label": {"bn": "ইমাম আবু হানিফা (বাংলাদেশের প্রচলিত ক্যালেন্ডার সাধারণত এই মত অনুসরণ করে)", "en": "Imam Abu Hanifah (calendars in Bangladesh usually follow this)"}, "text": {"bn": "ছায়া বস্তুর দ্বিগুণ হলে আসর শুরু হয়; তাই হানাফি ক্যালেন্ডারে আসরের সময় কিছুটা দেরিতে।", "en": "Asr begins when the shadow is twice the object''s length, so Hanafi timetables show Asr somewhat later."}, "evidence": {"bn": "জিবরাইল (আ.) দ্বিতীয় দিন ছায়া এক গুণ হলে জোহর পড়িয়েছেন (একই হাদিস), অর্থাৎ তখনো জোহরের সময় ছিল; এবং গরম তীব্র হলে জোহর ঠান্ডা সময়ে পড়ার নির্দেশনা (সহিহ বুখারি)।", "en": "On the second day Jibril led Zuhr when the shadow equalled the object (the same hadith), so Zuhr time was still running then; and the instruction to delay Zuhr until it is cooler in intense heat (Sahih al-Bukhari)."}}], "check": true}, {"type": "heading", "text": {"bn": "নামাজ নিষিদ্ধ সময়", "en": "Forbidden times"}}, {"type": "list", "items": [{"bn": "সূর্যোদয়ের সময় — সূর্য পুরোপুরি উঠে কিছুটা উপরে না আসা পর্যন্ত (প্রায় ১৫–২০ মিনিট)", "en": "At sunrise, until the sun has fully risen and climbed a little (about 15–20 minutes)"}, {"bn": "ঠিক দুপুরে — সূর্য মাথার উপর থাকা অবস্থায়, পশ্চিমে হেলে পড়া পর্যন্ত", "en": "At midday, while the sun is at its zenith, until it declines"}, {"bn": "সূর্যাস্তের সময় — সূর্য হলুদ হয়ে অস্ত যাওয়া পর্যন্ত", "en": "At sunset, from when the sun turns yellow until it has set"}]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৮৩১ (উকবা ইবনে আমির রা.)", "en": "Sahih Muslim 831 (Uqbah ibn ''Amir RA)"}}, {"type": "text", "text": {"bn": "এ ছাড়া ফজরের ফরজের পর থেকে সূর্যোদয় পর্যন্ত এবং আসরের ফরজের পর থেকে সূর্যাস্ত পর্যন্ত নফল নামাজ পড়া নিষেধ। হানাফি মতে উপরের তিন সময়ে কাজা নামাজও পড়া যাবে না; তবে কেউ সেদিনের আসর এত দেরিতে পড়লে সূর্যাস্তের সময়ও শেষ করে নেবে (দেরি করার কারণে গুনাহ হবে)।", "en": "Also, voluntary prayer is not prayed after the Fajr fard until sunrise, nor after the Asr fard until sunset. In the Hanafi view not even missed prayers are made up in the three times above, except that a person who delayed that day''s Asr completes it even at sunset (though the delay is sinful)."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৫৮৬; সহিহ মুসলিম ৮২৭", "en": "Sahih al-Bukhari 586; Sahih Muslim 827"}}, {"type": "note", "tone": "tip", "text": {"bn": "নিজ এলাকার নির্ভরযোগ্য নামাজের ক্যালেন্ডার বা এই অ্যাপের সময়সূচি দেখে নামাজ পড়ুন। সময় শুরু হওয়ার আগে নামাজ পড়লে তা হয় না।", "en": "Follow a reliable local prayer timetable, or the times in this app. A prayer offered before its time has begun is not valid."}}]', 'in_review', 20 FROM is_guide_topics WHERE slug = 'salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '5a0b8f1a-a5ca-5520-bb82-3e1b3f23dcc8', id, 'salah-fard-wajib', '{"bn": "নামাজের ফরজ ও ওয়াজিব", "en": "Salah: Conditions, Pillars and Wajib Acts"}', '{"bn": "নামাজের বাইরের ও ভেতরের ফরজ এবং ওয়াজিবগুলো — কোনটি ছুটলে নামাজ হয় না, কোনটি ছুটলে সাহু সিজদা লাগে।", "en": "The conditions and pillars of salah, and its wajib acts: which ones invalidate the prayer if missed, and which call for sajdah sahw."}', 'basic', '[{"type": "text", "text": {"bn": "বাংলাদেশে প্রচলিত হানাফি কিতাবগুলোতে নামাজের ফরজ ১৩টি বলা হয়: ৭টি নামাজের বাইরে (আহকাম বা শর্ত) এবং ৬টি নামাজের ভেতরে (আরকান)। এর কোনো একটি বাদ পড়লে — ইচ্ছায় হোক বা ভুলে — নামাজ হয় না, আবার পড়তে হয়।", "en": "Hanafi books used in Bangladesh list 13 fard acts: 7 outside the prayer (conditions) and 6 inside it (pillars). If any is missed, deliberately or by mistake, the prayer is invalid and must be repeated."}}, {"type": "heading", "text": {"bn": "নামাজের বাইরের ফরজ (শর্ত) — ৭টি", "en": "Conditions (outside the prayer): seven"}}, {"type": "table", "head": [{"bn": "শর্ত", "en": "Condition"}, {"bn": "ব্যাখ্যা", "en": "Explanation"}, {"bn": "দলিল", "en": "Evidence"}], "rows": [[{"bn": "শরীর পবিত্র", "en": "Body pure"}, {"bn": "ওযু থাকা, প্রয়োজনে গোসল; শরীরে নাপাকি না থাকা", "en": "Having wudu (and ghusl if needed); no impurity on the body"}, {"bn": "সূরা মায়েদা ৫:৬; সহিহ বুখারি ১৩৫", "en": "Al-Ma''idah 5:6; Sahih al-Bukhari 135"}], [{"bn": "কাপড় পবিত্র", "en": "Clothes pure"}, {"bn": "পরনের কাপড়ে নাপাকি না থাকা", "en": "No impurity on what one wears"}, {"bn": "সূরা মুদ্দাসসির ৭৪:৪", "en": "Al-Muddaththir 74:4"}], [{"bn": "জায়গা পবিত্র", "en": "Place pure"}, {"bn": "দাঁড়ানো, হাঁটু, হাত ও সিজদার জায়গা পবিত্র হওয়া", "en": "Where one stands, kneels, places the hands and prostrates must be pure"}, {"bn": "সূরা বাকারা ২:১২৫ (ঘর পবিত্র রাখার আদেশ)", "en": "Al-Baqarah 2:125 (purify My House)"}], [{"bn": "সতর ঢাকা", "en": "Covering the awrah"}, {"bn": "পুরুষ: নাভি থেকে হাঁটুসহ; নারী: মুখমণ্ডল, দুই হাতের কবজি পর্যন্ত (এবং হানাফি মতে দুই পা) ছাড়া পুরো শরীর", "en": "Men: from navel to knees inclusive; women: the whole body except the face, the hands (and in the Hanafi view the feet)"}, {"bn": "সূরা আরাফ ৭:৩১; সুনান আবু দাউদ ৬৪১", "en": "Al-A''raf 7:31; Sunan Abi Dawud 641"}], [{"bn": "কিবলামুখী হওয়া", "en": "Facing the qiblah"}, {"bn": "কাবার দিকে মুখ করা", "en": "Facing towards the Ka''bah"}, {"bn": "সূরা বাকারা ২:১৪৪", "en": "Al-Baqarah 2:144"}], [{"bn": "ওয়াক্ত হওয়া", "en": "The time having begun"}, {"bn": "নামাজের সময় শুরু হওয়া", "en": "The prayer''s time must have started"}, {"bn": "সূরা নিসা ৪:১০৩", "en": "An-Nisa 4:103"}], [{"bn": "নিয়ত করা", "en": "Intention"}, {"bn": "অন্তরে কোন নামাজ পড়ছেন তা ঠিক করা", "en": "Knowing in the heart which prayer one is offering"}, {"bn": "সহিহ বুখারি ১; সহিহ মুসলিম ১৯০৭", "en": "Sahih al-Bukhari 1; Sahih Muslim 1907"}]]}, {"type": "heading", "text": {"bn": "নামাজের ভেতরের ফরজ (আরকান) — ৬টি", "en": "Pillars (inside the prayer): six"}}, {"type": "list", "items": [{"bn": "তাকবিরে তাহরিমা — \"আল্লাহু আকবার\" বলে নামাজ শুরু করা", "en": "Takbir at-tahrimah: beginning with \"Allahu akbar\""}, {"bn": "কিয়াম — দাঁড়িয়ে নামাজ পড়া (ফরজ ও ওয়াজিব নামাজে, সামর্থ্য থাকলে)", "en": "Qiyam: standing (in fard and wajib prayers, if able)"}, {"bn": "কিরাত — কুরআন থেকে কিছু পড়া", "en": "Qira''ah: reciting from the Quran"}, {"bn": "রুকু করা", "en": "Ruku: bowing"}, {"bn": "প্রতি রাকাতে দুটি সিজদা করা", "en": "Sujud: two prostrations in every rakat"}, {"bn": "শেষ বৈঠক — তাশাহহুদ পড়ার পরিমাণ সময় বসা", "en": "The final sitting, for as long as it takes to recite the tashahhud"}]}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ ৬১; সুনান তিরমিযি ৩ — \"নামাজের চাবি পবিত্রতা, তার শুরু তাকবির আর শেষ সালাম\"; সহিহ বুখারি ৭৫৭; সহিহ মুসলিম ৩৯৭ — ভুলভাবে নামাজ আদায়কারী সাহাবিকে শেখানোর হাদিস", "en": "Sunan Abi Dawud 61; Jami at-Tirmidhi 3: \"The key to prayer is purification, it begins with takbir and ends with salam\"; Sahih al-Bukhari 757; Sahih Muslim 397: the hadith of the man taught to pray properly"}}, {"type": "note", "tone": "info", "text": {"bn": "হানাফি কিতাবে আরেকটি বিষয়কে ফরজ ধরা হয়: নিজের কোনো কাজের মাধ্যমে নামাজ থেকে বের হওয়া — যা সাধারণত সালামের মাধ্যমে হয়। কিছু কিতাবে তাকবিরে তাহরিমাকে বাইরের শর্তের মধ্যেও গণনা করা হয়।", "en": "Hanafi books also count leaving the prayer by one''s own act (normally the salam) as fard. Some count the opening takbir among the conditions rather than the pillars."}}, {"type": "differ", "title": {"bn": "সূরা ফাতিহা, ধীরস্থিরতা ও সালাম কি রুকন (ফরজ), নাকি ওয়াজিব?", "en": "Are Al-Fatihah, calmness and the salam pillars, or wajib?"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "কুরআন থেকে যেকোনো অংশ পড়া ফরজ; সূরা ফাতিহা, রুকু-সিজদায় ধীরস্থিরতা (তাদিলে আরকান) এবং \"সালাম\" শব্দে শেষ করা ওয়াজিব। ভুলে ছুটলে সাহু সিজদা, ইচ্ছাকৃত ছাড়লে নামাজ আবার পড়া জরুরি।", "en": "Reciting any part of the Quran is fard; Al-Fatihah, calmness in ruku and sujud, and ending with the word \"salam\" are wajib. Missed by mistake, sajdah sahw makes up for them; left deliberately, the prayer must be repeated."}, "evidence": {"bn": "\"কুরআন থেকে যতটুকু সহজ হয় পড়ো\" — সূরা মুযযাম্মিল ৭৩:২০; ভুলভাবে নামাজ আদায়কারীকে রাসুলুল্লাহ ﷺ বলেছেন, \"কুরআন থেকে যা সহজ তা পড়ো\" — সহিহ বুখারি ৭৫৭।", "en": "\"Recite what is easy of the Quran\" (Al-Muzzammil 73:20); the Prophet ﷺ told the man who prayed badly, \"recite what is easy for you of the Quran\" (Sahih al-Bukhari 757)."}}, {"label": {"bn": "শাফেয়ি, মালেকি ও হাম্বলি", "en": "Shafi''i, Maliki and Hanbali"}, "text": {"bn": "সূরা ফাতিহা, প্রতিটি রুকনে ধীরস্থিরতা এবং সালাম — সবই রুকন। এর কোনোটি ছুটলে নামাজ হবে না। শাফেয়ি ও হাম্বলি মতে শেষ বৈঠকে তাশাহহুদ ও দরুদও রুকন।", "en": "Al-Fatihah, calmness in every pillar and the salam are all pillars; without them the prayer is invalid. Shafi''is and Hanbalis also count the final tashahhud and durood as pillars."}, "evidence": {"bn": "\"যে সূরা ফাতিহা পড়ে না তার নামাজ হয় না\" — সহিহ বুখারি ৭৫৬; সহিহ মুসলিম ৩৯৪; ভুলভাবে নামাজ আদায়কারীকে \"তুমি নামাজ পড়োনি\" বলে প্রতিটি রুকনে স্থির হতে বলেছেন — সহিহ বুখারি ৭৫৭।", "en": "\"There is no prayer for one who does not recite Al-Fatihah\" (Sahih al-Bukhari 756; Sahih Muslim 394); the man who prayed badly was told \"you have not prayed\" and taught to be at rest in each pillar (Sahih al-Bukhari 757)."}}]}, {"type": "heading", "text": {"bn": "নামাজের ওয়াজিব (হানাফি মাযহাব অনুযায়ী ১৪টি)", "en": "Wajib acts of salah (14, in the Hanafi madhhab)"}}, {"type": "list", "items": [{"bn": "সূরা ফাতিহা পূর্ণ পড়া", "en": "Reciting Al-Fatihah completely"}, {"bn": "ফাতিহার পর আরেকটি সূরা বা কমপক্ষে ছোট তিন আয়াত পরিমাণ পড়া — ফরজের প্রথম দুই রাকাতে এবং সুন্নত, নফল ও বিতরের সব রাকাতে", "en": "Adding a surah or at least three short ayat after Al-Fatihah: in the first two rakats of fard prayers and in every rakat of sunnah, nafl and witr"}, {"bn": "ফরজ নামাজের প্রথম দুই রাকাতকে কিরাতের জন্য নির্দিষ্ট করা", "en": "Making the first two rakats of fard prayers the ones with recitation"}, {"bn": "সূরা মিলানোর আগে ফাতিহা পড়া", "en": "Reciting Al-Fatihah before the added surah"}, {"bn": "রুকু, সিজদা, রুকুর পর দাঁড়ানো এবং দুই সিজদার মাঝে বসায় ধীরস্থিরতা (তাদিলে আরকান)", "en": "Calmness in ruku, sujud, standing after ruku and sitting between the sujud"}, {"bn": "প্রতিটি কাজ সঠিক ক্রমে করা", "en": "Keeping the correct order of the acts"}, {"bn": "তিন ও চার রাকাতের নামাজে প্রথম বৈঠক", "en": "The first sitting in three- and four-rakat prayers"}, {"bn": "দুই বৈঠকেই তাশাহহুদ (আত্তাহিয়্যাতু) পড়া", "en": "Reciting the tashahhud in both sittings"}, {"bn": "\"আসসালামু আলাইকুম ওয়া রাহমাতুল্লাহ\" বলে নামাজ শেষ করা", "en": "Ending the prayer with \"As-salamu ''alaykum wa rahmatullah\""}, {"bn": "ইমামের জন্য ফজর, মাগরিব ও এশার প্রথম দুই রাকাতে উচ্চস্বরে এবং জোহর-আসরে নিচু স্বরে কিরাত", "en": "For the imam: reciting aloud in Fajr and the first two rakats of Maghrib and Isha, and quietly in Zuhr and Asr"}, {"bn": "বিতরে দোয়া কুনুত পড়া", "en": "Reciting the qunut in witr"}, {"bn": "দুই ঈদের নামাজে অতিরিক্ত ছয় তাকবির", "en": "The six extra takbirs of the two Eid prayers"}, {"bn": "সিজদার আয়াত পড়লে সিজদায়ে তিলাওয়াত করা", "en": "Prostrating when an ayah of sajdah is recited"}, {"bn": "ইমামের অনুসরণ করা (মুক্তাদির জন্য)", "en": "Following the imam (for those praying behind him)"}]}, {"type": "note", "tone": "warn", "text": {"bn": "কোনো ওয়াজিব ভুলে ছুটে গেলে নামাজের শেষে সাহু সিজদা দিলে নামাজ পূর্ণ হয়। ইচ্ছাকৃতভাবে ছাড়লে বা সাহু সিজদা না দিলে নামাজটি আবার পড়া জরুরি। ফরজ (রুকন) ছুটে গেলে সাহু সিজদায় কাজ হয় না — নামাজ আবার পড়তে হবে।", "en": "If a wajib is missed by mistake, sajdah sahw at the end completes the prayer. If it is left deliberately, or sahw is not done, the prayer must be repeated. If a pillar (fard) is missed, sajdah sahw does not help: the prayer must be repeated."}}]', 'in_review', 30 FROM is_guide_topics WHERE slug = 'salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'a2cb4792-5425-5429-bd5a-18a41aa84685', id, 'salah-sunnah-makruh-mufsidat', '{"bn": "নামাজের সুন্নত, মাকরুহ ও যেসব কারণে নামাজ ভাঙে", "en": "Salah: Sunnah Acts, Disliked Acts and What Breaks It"}', '{"bn": "নামাজকে সুন্দর করে যেসব সুন্নত, যেসব কাজ নামাজকে ত্রুটিপূর্ণ করে, আর যেসব কারণে নামাজ ভেঙে যায়।", "en": "The sunnah acts that beautify salah, the acts that spoil it, and the things that break it."}', 'detail', '[{"type": "heading", "text": {"bn": "নামাজের গুরুত্বপূর্ণ সুন্নত", "en": "Important sunnah acts"}}, {"type": "list", "items": [{"bn": "তাকবিরে তাহরিমার সময় দুই হাত ওঠানো", "en": "Raising the hands at the opening takbir"}, {"bn": "ডান হাত বাম হাতের উপর রেখে হাত বাঁধা", "en": "Placing the right hand over the left"}, {"bn": "সানা, তাআউয ও বিসমিল্লাহ পড়া", "en": "Reciting the thana, ta''awwudh and Bismillah"}, {"bn": "সূরা ফাতিহার পর আমিন বলা", "en": "Saying Amin after Al-Fatihah"}, {"bn": "এক অবস্থা থেকে আরেক অবস্থায় যাওয়ার সময় তাকবির বলা", "en": "Saying the takbir when moving from one position to another"}, {"bn": "রুকু ও সিজদায় কমপক্ষে তিনবার তাসবিহ পড়া", "en": "Saying the tasbih at least three times in ruku and sujud"}, {"bn": "রুকু থেকে ওঠার সময় তাসমি ও দাঁড়িয়ে তাহমিদ বলা", "en": "Saying the tasmi'' while rising from ruku and the tahmid when standing"}, {"bn": "রুকুতে হাঁটু ধরা, পিঠ ও মাথা সমান রাখা", "en": "Holding the knees in ruku with the back and head level"}, {"bn": "সিজদায় যেতে প্রথমে হাঁটু, তারপর হাত, তারপর নাক ও কপাল রাখা (হানাফি মত)", "en": "Going down to sujud with knees first, then hands, then nose and forehead (Hanafi view)"}, {"bn": "শেষ বৈঠকে তাশাহহুদের পর দরুদ ও দোয়া পড়া", "en": "Reciting durood and a dua after the tashahhud in the final sitting"}, {"bn": "দাঁড়ানো অবস্থায় সিজদার জায়গার দিকে তাকানো", "en": "Looking at the place of prostration while standing"}, {"bn": "সালামের সময় ডানে ও বামে মুখ ফেরানো", "en": "Turning the face right and left at the salam"}]}, {"type": "note", "tone": "info", "text": {"bn": "সুন্নত ছুটে গেলে নামাজ ভাঙে না এবং সাহু সিজদাও লাগে না, তবে সওয়াব কমে যায়। হাত ওঠানো, হাত বাঁধা, আমিন ইত্যাদির পদ্ধতি নিয়ে মতপার্থক্য \"নামাজে মতপার্থক্যের বিষয়গুলো\" অংশে দেখুন।", "en": "Missing a sunnah does not break the prayer and does not need sajdah sahw, but reduces the reward. For differences on raising the hands, hand placement, Amin and so on, see \"Points of Difference in Salah\"."}}, {"type": "heading", "text": {"bn": "যেসব কারণে নামাজ ভেঙে যায় (মুফসিদাত)", "en": "What breaks the prayer (mufsidat)"}}, {"type": "list", "items": [{"bn": "কথা বলা — মানুষের সাথে কথাবার্তা নামাজে চলে না (হানাফি মতে ভুলে বললেও ভাঙে; অন্যদের মতে ভুলে বা না জেনে অল্প কথায় ভাঙে না)", "en": "Speaking: ordinary talk has no place in salah (Hanafis say it breaks even if by mistake; others excuse a little said by mistake or in ignorance)"}, {"bn": "কিছু খাওয়া বা পান করা", "en": "Eating or drinking anything"}, {"bn": "শব্দ করে হাসা (মুচকি হাসিতে নামাজ ভাঙে না)", "en": "Laughing aloud (a silent smile does not break it)"}, {"bn": "ওযু ভেঙে যাওয়া", "en": "Wudu breaking"}, {"bn": "বিনা কারণে বুক কিবলা থেকে ঘুরিয়ে ফেলা", "en": "Turning the chest away from the qiblah without excuse"}, {"bn": "আমলে কাসির — এত বেশি নড়াচড়া যে দেখলে মনে হয় সে নামাজে নেই", "en": "Excessive movement: so much that an onlooker would think one is not praying"}, {"bn": "কোনো রুকন (ফরজ) ছেড়ে দেওয়া", "en": "Leaving out a pillar (fard)"}, {"bn": "সতর এতক্ষণ খোলা থাকা যতক্ষণে একটি রুকন আদায় করা যায় (হানাফি মতে কোনো অঙ্গের এক-চতুর্থাংশ)", "en": "The awrah staying uncovered for as long as a pillar takes (Hanafi: a quarter of a limb)"}, {"bn": "কুরআন এমন ভুল পড়া যাতে অর্থ সম্পূর্ণ বদলে যায়", "en": "A recitation mistake that totally changes the meaning"}, {"bn": "কথায় সালামের জবাব দেওয়া বা হাঁচির জবাবে \"ইয়ারহামুকাল্লাহ\" বলা", "en": "Returning a greeting in words, or saying \"yarhamukallah\" to someone who sneezes"}, {"bn": "ব্যথা বা দুনিয়াবি দুঃখে শব্দ করে \"আহ-উহ\" করা বা কাঁদা (হানাফি মত); আল্লাহর ভয়ে কাঁদলে নামাজ ভাঙে না", "en": "Groaning or crying aloud from pain or worldly grief (Hanafi view); weeping from fear of Allah does not break it"}]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৫৩৭ — \"এই নামাজে মানুষের কথাবার্তার কিছুই চলে না; এটা তো শুধু তাসবিহ, তাকবির ও কুরআন তিলাওয়াত\"", "en": "Sahih Muslim 537: \"Nothing of people''s talk is fitting in this prayer; it is only glorification, takbir and recitation of the Quran\""}}, {"type": "heading", "text": {"bn": "নামাজে যা মাকরুহ", "en": "What is disliked (makruh) in salah"}}, {"type": "list", "items": [{"bn": "এদিক-ওদিক তাকানো (সহিহ বুখারি ৭৫১) বা আকাশের দিকে তাকানো (সহিহ বুখারি ৭৫০)", "en": "Looking around (Sahih al-Bukhari 751) or looking up at the sky (Sahih al-Bukhari 750)"}, {"bn": "কাপড়, দাড়ি বা শরীর নিয়ে খেলা করা; আঙুল ফোটানো", "en": "Fiddling with clothes, beard or body; cracking the knuckles"}, {"bn": "কোমরে হাত রাখা (সহিহ বুখারি ১২২০)", "en": "Putting the hands on the hips (Sahih al-Bukhari 1220)"}, {"bn": "খাবার সামনে রেখে বা পেশাব-পায়খানার বেগ চেপে নামাজ পড়া (সহিহ মুসলিম ৫৬০)", "en": "Praying with food served and desired, or while holding back the call of nature (Sahih Muslim 560)"}, {"bn": "কাপড় বা চুল গুটিয়ে রাখা, যেমন হাতা গুটানো (সহিহ মুসলিম ৪৯০)", "en": "Tucking up clothes or hair, such as rolled-up sleeves (Sahih Muslim 490)"}, {"bn": "পুরুষদের সিজদায় কুকুরের মতো হাতের কনুই মাটিতে বিছিয়ে দেওয়া (সহিহ বুখারি ৮২২)", "en": "Men spreading the forearms flat on the ground in sujud like a dog (Sahih al-Bukhari 822)"}, {"bn": "রুকু বা সিজদায় কুরআন তিলাওয়াত করা (সহিহ মুসলিম ৪৭৯)", "en": "Reciting the Quran in ruku or sujud (Sahih Muslim 479)"}, {"bn": "হাই আসলে না আটকানো — যথাসম্ভব আটকাবে, না পারলে মুখে হাত রাখবে (সহিহ মুসলিম ২৯৯৫)", "en": "Not holding back a yawn: restrain it, or cover the mouth (Sahih Muslim 2995)"}, {"bn": "বিনা প্রয়োজনে চোখ বন্ধ রাখা", "en": "Closing the eyes without need"}, {"bn": "প্রাণীর ছবির দিকে মুখ করে বা কারো মুখোমুখি হয়ে নামাজ পড়া", "en": "Praying facing a picture of a living being, or facing someone''s face"}, {"bn": "তাড়াহুড়া করে রুকু-সিজদা করা, ধীরস্থির না হওয়া", "en": "Rushing ruku and sujud without becoming still"}]}, {"type": "note", "tone": "tip", "text": {"bn": "নামাজের সময় মোবাইল সাইলেন্ট রাখুন। নামাজে অনিচ্ছায় মোবাইল বেজে উঠলে এক হাতে অল্প নড়াচড়ায় বন্ধ করা যায়; এতে নামাজ ভাঙে না।", "en": "Silence your phone before praying. If it rings, you may switch it off with a small movement of one hand; this does not break the prayer."}}]', 'in_review', 40 FROM is_guide_topics WHERE slug = 'salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '308f1c0b-ede4-5d0a-a0da-7cd89d06c1ff', id, 'salah-niyyah', '{"bn": "নামাজের নিয়ত", "en": "The Intention (Niyyah) for Salah"}', '{"bn": "নিয়ত হলো অন্তরের সংকল্প — মুখে বলা জরুরি নয়। প্রতিটি নামাজের জন্য প্রচলিত বাংলা নিয়তের উদাহরণসহ।", "en": "Niyyah is the resolve of the heart; saying it aloud is not required. With common Bangla phrasings for each prayer as examples."}', 'basic', '[{"type": "text", "text": {"bn": "নিয়ত মানে মনে মনে জানা ও ঠিক করা যে আমি আল্লাহর জন্য অমুক নামাজ পড়ছি। এটি অন্তরের কাজ। নামাজে দাঁড়িয়ে আপনি যদি জানেন যে এখন জোহরের চার রাকাত ফরজ পড়ছেন, তাহলেই নিয়ত হয়ে গেছে — আলাদা কোনো শব্দ মুখে উচ্চারণ করা জরুরি নয়।", "en": "Niyyah means knowing and deciding in your mind that you are offering a particular prayer for Allah. It is an act of the heart. If, as you stand, you know you are praying the four fard rakats of Zuhr, your intention is made; no words need be spoken."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১; সহিহ মুসলিম ১৯০৭ — \"সকল কাজ নিয়তের উপর নির্ভরশীল\"", "en": "Sahih al-Bukhari 1; Sahih Muslim 1907: \"Actions are only by intentions\""}}, {"type": "heading", "text": {"bn": "নিয়তে কী খেয়াল রাখবেন", "en": "What the intention should include"}}, {"type": "list", "items": [{"bn": "ফরজ ও ওয়াজিব নামাজে কোন নামাজ (যেমন আজকের আসরের ফরজ) তা নির্দিষ্ট করা", "en": "For fard and wajib prayers, which prayer it is (e.g. today''s Asr fard)"}, {"bn": "জামাতে পড়লে ইমামের অনুসরণের নিয়ত করা (হানাফি মতে জরুরি)", "en": "In congregation, intending to follow the imam (required in the Hanafi view)"}, {"bn": "সুন্নত ও নফলে সাধারণভাবে নামাজের নিয়তই যথেষ্ট", "en": "For sunnah and nafl, a general intention to pray is enough"}, {"bn": "নিয়ত তাকবিরে তাহরিমার সাথে বা ঠিক আগে হওয়া", "en": "The intention is made with, or just before, the opening takbir"}]}, {"type": "differ", "title": {"bn": "নিয়ত মুখে উচ্চারণ করা", "en": "Saying the intention aloud"}, "views": [{"label": {"bn": "অনেক আলেম (মালেকি মাযহাবসহ)", "en": "Many scholars (including the Maliki school)"}, "text": {"bn": "মুখে নিয়ত বলা রাসুলুল্লাহ ﷺ বা সাহাবিদের থেকে প্রমাণিত নয়; অন্তরের নিয়তই যথেষ্ট, তাই মুখে না বলাই উত্তম।", "en": "Saying the intention aloud is not reported from the Prophet ﷺ or the Companions; the heart''s intention suffices, so it is better not to say it."}, "evidence": {"bn": "রাসুলুল্লাহ ﷺ নামাজ শুরু করতেন তাকবির দিয়ে — সুনান আবু দাউদ ৬১; তাঁর নামাজের বিস্তারিত বর্ণনায় মুখে নিয়তের উল্লেখ নেই।", "en": "The Prophet ﷺ began the prayer with the takbir (Sunan Abi Dawud 61); detailed descriptions of his prayer do not mention a spoken intention."}}, {"label": {"bn": "পরবর্তী যুগের কিছু হানাফি ও শাফেয়ি ফকিহ", "en": "Some later Hanafi and Shafi''i jurists"}, "text": {"bn": "অন্তরের নিয়তই আসল; তবে মনকে একাগ্র করতে সাহায্য করলে মুখে বলাকে তারা উত্তম (মুস্তাহসান) বলেছেন।", "en": "The heart''s intention is what counts, but they considered saying it good if it helps the mind focus."}, "evidence": {"bn": "অন্তর ও মুখ একসাথে হলে মনোযোগ দৃঢ় হয় — এটি তাদের ইজতিহাদ; উভয় পক্ষ একমত যে মুখে বলা জরুরি নয়।", "en": "Joining tongue and heart strengthens focus; this is their reasoning, and both sides agree it is not required."}}]}, {"type": "heading", "text": {"bn": "প্রচলিত বাংলা নিয়তের উদাহরণ", "en": "Common Bangla phrasings (examples)"}}, {"type": "note", "tone": "info", "text": {"bn": "নিচের বাক্যগুলো শুধু উদাহরণ — হুবহু এই শব্দ বলা জরুরি নয়। মনে মনে নামাজটি নির্দিষ্ট করাই যথেষ্ট। জামাতে হলে \"এই ইমামের পেছনে\" যোগ করুন।", "en": "The sentences below are only examples; there is no required wording. Knowing the prayer in your heart is enough. In congregation, add \"behind this imam\"."}}, {"type": "table", "head": [{"bn": "নামাজ", "en": "Prayer"}, {"bn": "উদাহরণ (বাংলা)", "en": "Example"}], "rows": [[{"bn": "ফজরের সুন্নত", "en": "Fajr sunnah"}, {"bn": "আমি আল্লাহর সন্তুষ্টির জন্য কিবলামুখী হয়ে ফজরের দুই রাকাত সুন্নত নামাজ পড়ছি।", "en": "I am praying the two sunnah rakats of Fajr, facing the qiblah, for the pleasure of Allah."}], [{"bn": "ফজরের ফরজ (জামাতে)", "en": "Fajr fard (in congregation)"}, {"bn": "আমি আল্লাহর সন্তুষ্টির জন্য কিবলামুখী হয়ে এই ইমামের পেছনে ফজরের দুই রাকাত ফরজ নামাজ পড়ছি।", "en": "I am praying the two fard rakats of Fajr behind this imam, facing the qiblah, for the pleasure of Allah."}], [{"bn": "জোহরের আগের সুন্নত", "en": "Zuhr sunnah (before)"}, {"bn": "আমি আল্লাহর সন্তুষ্টির জন্য কিবলামুখী হয়ে জোহরের চার রাকাত সুন্নত নামাজ পড়ছি।", "en": "I am praying the four sunnah rakats of Zuhr, facing the qiblah, for the pleasure of Allah."}], [{"bn": "জোহরের ফরজ", "en": "Zuhr fard"}, {"bn": "আমি আল্লাহর সন্তুষ্টির জন্য কিবলামুখী হয়ে জোহরের চার রাকাত ফরজ নামাজ পড়ছি।", "en": "I am praying the four fard rakats of Zuhr, facing the qiblah, for the pleasure of Allah."}], [{"bn": "জোহরের পরের সুন্নত", "en": "Zuhr sunnah (after)"}, {"bn": "আমি আল্লাহর সন্তুষ্টির জন্য কিবলামুখী হয়ে জোহরের দুই রাকাত সুন্নত নামাজ পড়ছি।", "en": "I am praying the two sunnah rakats after Zuhr, facing the qiblah, for the pleasure of Allah."}], [{"bn": "আসরের ফরজ", "en": "Asr fard"}, {"bn": "আমি আল্লাহর সন্তুষ্টির জন্য কিবলামুখী হয়ে আসরের চার রাকাত ফরজ নামাজ পড়ছি।", "en": "I am praying the four fard rakats of Asr, facing the qiblah, for the pleasure of Allah."}], [{"bn": "মাগরিবের ফরজ", "en": "Maghrib fard"}, {"bn": "আমি আল্লাহর সন্তুষ্টির জন্য কিবলামুখী হয়ে মাগরিবের তিন রাকাত ফরজ নামাজ পড়ছি।", "en": "I am praying the three fard rakats of Maghrib, facing the qiblah, for the pleasure of Allah."}], [{"bn": "এশার ফরজ", "en": "Isha fard"}, {"bn": "আমি আল্লাহর সন্তুষ্টির জন্য কিবলামুখী হয়ে এশার চার রাকাত ফরজ নামাজ পড়ছি।", "en": "I am praying the four fard rakats of Isha, facing the qiblah, for the pleasure of Allah."}], [{"bn": "বিতর", "en": "Witr"}, {"bn": "আমি আল্লাহর সন্তুষ্টির জন্য কিবলামুখী হয়ে তিন রাকাত বিতর নামাজ পড়ছি।", "en": "I am praying the three rakats of witr, facing the qiblah, for the pleasure of Allah."}], [{"bn": "কাজা নামাজ", "en": "A missed prayer"}, {"bn": "আমি আল্লাহর সন্তুষ্টির জন্য কিবলামুখী হয়ে গত (অমুক দিনের) জোহরের চার রাকাত ফরজ নামাজ কাজা পড়ছি।", "en": "I am making up the four fard rakats of the Zuhr of (that day), facing the qiblah, for the pleasure of Allah."}]]}, {"type": "note", "tone": "warn", "text": {"bn": "কিছু বইয়ে \"নাওয়াইতু আন উসাল্লিয়া…\" ধরনের আরবি নিয়ত দেওয়া থাকে। এগুলো রাসুলুল্লাহ ﷺ থেকে বর্ণিত নয়; মুখস্থ করা জরুরি নয়, আর না জানলেও নামাজের কোনো ক্ষতি নেই।", "en": "Some books give Arabic formulas such as \"Nawaytu an usalliya…\". These are not narrated from the Prophet ﷺ; memorising them is not required, and not knowing them does not harm the prayer."}}]', 'in_review', 50 FROM is_guide_topics WHERE slug = 'salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'f3de3915-5321-55da-9f21-ef1ce8368250', id, 'salah-two-rakat-step-by-step', '{"bn": "দুই রাকাত নামাজ: ধাপে ধাপে", "en": "How to Pray Two Rakats: Step by Step"}', '{"bn": "তাকবির থেকে সালাম পর্যন্ত দুই রাকাত নামাজের পূর্ণ পদ্ধতি — প্রতিটি দোয়া ও তাসবিহ আরবি, উচ্চারণ ও অর্থসহ।", "en": "The full method of a two-rakat prayer from takbir to salam, with every recitation in Arabic, pronunciation and meaning."}', 'basic', '[{"type": "text", "text": {"bn": "ফজরের ফরজ, ফজরের সুন্নত, জোহর-মাগরিব-এশার পরের সুন্নত এবং যেকোনো দুই রাকাত নফল — সব এভাবেই পড়া হয়। এখানে বাংলাদেশে প্রচলিত হানাফি পদ্ধতি অনুসরণ করা হয়েছে। হাত ওঠানো, হাত বাঁধার জায়গা, আমিন ইত্যাদি যেসব বিষয়ে অন্য মাযহাবে ভিন্নতা আছে, সেগুলো দলিলসহ \"নামাজে মতপার্থক্যের বিষয়গুলো\" অংশে দেওয়া আছে।", "en": "The Fajr fard, the Fajr sunnah, the sunnahs after Zuhr, Maghrib and Isha, and any two-rakat nafl are all prayed this way. The Hanafi method common in Bangladesh is followed here. Where other madhhabs differ (raising the hands, where to place them, Amin and so on), the views and evidence are in \"Points of Difference in Salah\"."}}, {"type": "note", "tone": "tip", "text": {"bn": "বাংলা ও ইংরেজি উচ্চারণ শুধু সাহায্যের জন্য; আরবির অনেক উচ্চারণ এতে পুরোপুরি ধরা যায় না। সূরা ফাতিহা ও অন্যান্য সূরার সঠিক উচ্চারণ একজন ভালো কারি বা শিক্ষকের কাছ থেকে শিখে নিন।", "en": "The Bangla and English transliterations are only aids; they cannot fully capture Arabic sounds. Learn the correct pronunciation of Al-Fatihah and other surahs from a good teacher."}}, {"type": "heading", "text": {"bn": "নামাজের আগে", "en": "Before the prayer"}}, {"type": "step", "title": {"bn": "প্রস্তুতি", "en": "Prepare"}, "text": {"bn": "ওযু করুন, শরীর-কাপড়-জায়গা পবিত্র কিনা দেখে নিন, সতর ঢাকুন, নামাজের ওয়াক্ত হয়েছে কিনা নিশ্চিত হোন এবং কিবলার দিকে মুখ করে দাঁড়ান। দুই পায়ের মাঝে স্বাভাবিক ফাঁক রাখুন।", "en": "Make wudu; make sure your body, clothes and place are pure; cover the awrah; check that the prayer time has started; and stand facing the qiblah with a natural gap between the feet."}}, {"type": "step", "title": {"bn": "নিয়ত", "en": "Intention"}, "text": {"bn": "মনে মনে ঠিক করুন কোন নামাজ পড়ছেন (যেমন ফজরের দুই রাকাত ফরজ)। মুখে বলা জরুরি নয়।", "en": "Know in your heart which prayer you are offering (e.g. the two fard rakats of Fajr). Saying it aloud is not required."}}, {"type": "heading", "text": {"bn": "প্রথম রাকাত", "en": "The first rakat"}}, {"type": "step", "title": {"bn": "তাকবিরে তাহরিমা", "en": "The opening takbir"}, "text": {"bn": "দুই হাত কান পর্যন্ত ওঠান — হাতের তালু কিবলার দিকে, বুড়ো আঙুল কানের লতির কাছাকাছি — এবং বলুন \"আল্লাহু আকবার\"। এখন থেকে নামাজের বাইরের সব কাজ ও কথা হারাম।", "en": "Raise both hands to the ears, palms facing the qiblah and thumbs near the earlobes, and say \"Allahu akbar\". From now, everything outside the prayer is forbidden."}}, {"type": "arabic", "label": {"bn": "তাকবিরে তাহরিমা", "en": "The opening takbir (takbir at-tahrimah)"}, "ar": "اللَّهُ أَكْبَرُ", "pron": {"bn": "আল্লাহু আকবার", "en": "Allahu akbar"}, "meaning": {"bn": "আল্লাহ সবচেয়ে বড়।", "en": "Allah is the Greatest."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৩৯১ (কান পর্যন্ত হাত ওঠানো); সহিহ বুখারি ৭৩৫ (কাঁধ পর্যন্ত)", "en": "Sahih Muslim 391 (raising to the ears); Sahih al-Bukhari 735 (to the shoulders)"}}, {"type": "step", "title": {"bn": "হাত বাঁধা ও সানা", "en": "Fold the hands and recite the thana"}, "text": {"bn": "ডান হাতের তালু বাম হাতের কবজির উপর রেখে নাভির নিচে হাত বাঁধুন (হানাফি মত)। দৃষ্টি থাকবে সিজদার জায়গায়। নিচু স্বরে সানা পড়ুন।", "en": "Place the right palm over the left wrist and fold the hands below the navel (Hanafi view). Keep your gaze on the place of prostration. Quietly recite the thana."}}, {"type": "arabic", "label": {"bn": "সানা", "en": "Thana (opening praise)"}, "ar": "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، وَتَبَارَكَ اسْمُكَ، وَتَعَالَىٰ جَدُّكَ، وَلَا إِلَٰهَ غَيْرُكَ", "pron": {"bn": "সুবহানাকা আল্লাহুম্মা ওয়া বিহামদিকা, ওয়া তাবারাকাসমুকা, ওয়া তাআলা জাদ্দুকা, ওয়া লা ইলাহা গাইরুক।", "en": "Subhanaka Allahumma wa bihamdika, wa tabarakasmuka, wa ta''ala jadduka, wa la ilaha ghayruk."}, "meaning": {"bn": "হে আল্লাহ! আপনি পবিত্র, সকল প্রশংসা আপনার। আপনার নাম বরকতময়, আপনার মর্যাদা অতি উঁচু, আর আপনি ছাড়া কোনো ইলাহ নেই।", "en": "Glory be to You, O Allah, and praise. Blessed is Your Name, exalted is Your majesty, and there is no god but You."}, "ref": {"bn": "সুনান আবু দাউদ ৭৭৬; সুনান তিরমিযি ২৪৩", "en": "Sunan Abi Dawud 776; Jami at-Tirmidhi 243"}}, {"type": "step", "title": {"bn": "তাআউয ও বিসমিল্লাহ", "en": "Ta''awwudh and Bismillah"}, "text": {"bn": "নিচু স্বরে আউযুবিল্লাহ এবং বিসমিল্লাহ পড়ুন।", "en": "Quietly recite the ta''awwudh, then Bismillah."}}, {"type": "arabic", "label": {"bn": "তাআউয", "en": "Ta''awwudh"}, "ar": "أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ", "pron": {"bn": "আউযু বিল্লাহি মিনাশ শাইতানির রাজিম।", "en": "A''udhu billahi minash-shaytanir-rajim."}, "meaning": {"bn": "বিতাড়িত শয়তান থেকে আমি আল্লাহর কাছে আশ্রয় চাই।", "en": "I seek refuge with Allah from Satan, the accursed."}, "ref": {"bn": "সূরা নাহল ১৬:৯৮ (কুরআন পড়ার আগে আশ্রয় চাওয়ার নির্দেশ)", "en": "An-Nahl 16:98 (the command to seek refuge before reciting)"}}, {"type": "arabic", "label": {"bn": "তাসমিয়া (বিসমিল্লাহ)", "en": "Tasmiyah (Bismillah)"}, "ar": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "pron": {"bn": "বিসমিল্লাহির রাহমানির রাহিম।", "en": "Bismillahir-rahmanir-rahim."}, "meaning": {"bn": "পরম করুণাময়, অতি দয়ালু আল্লাহর নামে (শুরু করছি)।", "en": "In the name of Allah, the Most Gracious, the Most Merciful."}}, {"type": "step", "title": {"bn": "সূরা ফাতিহা", "en": "Surah Al-Fatihah"}, "text": {"bn": "সূরা ফাতিহা পড়ুন — ধীরে, প্রতিটি আয়াতে থেমে। একা নামাজে ফজর, মাগরিব ও এশায় চাইলে শব্দ করে পড়তে পারেন; জোহর-আসরে নিচু স্বরে।", "en": "Recite Al-Fatihah slowly, pausing at each ayah. Alone, you may recite aloud in Fajr, Maghrib and Isha; in Zuhr and Asr recite quietly."}}, {"type": "arabic", "label": {"bn": "সূরা আল-ফাতিহা", "en": "Surah Al-Fatihah"}, "ar": "الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ﴿٢﴾ الرَّحْمَٰنِ الرَّحِيمِ ﴿٣﴾ مَالِكِ يَوْمِ الدِّينِ ﴿٤﴾ إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ﴿٥﴾ اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ ﴿٦﴾ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ ﴿٧﴾", "pron": {"bn": "আলহামদু লিল্লাহি রাব্বিল আলামিন। আর-রাহমানির রাহিম। মালিকি ইয়াওমিদ্দিন। ইয়্যাকা না''বুদু ওয়া ইয়্যাকা নাসতাইন। ইহদিনাস সিরাতাল মুসতাকিম। সিরাতাল্লাযিনা আন''আমতা আলাইহিম, গাইরিল মাগদুবি আলাইহিম ওয়ালাদ্দাল্লিন।", "en": "Al-hamdu lillahi rabbil-''alamin. Ar-rahmanir-rahim. Maliki yawmid-din. Iyyaka na''budu wa iyyaka nasta''in. Ihdinas-siratal-mustaqim. Siratal-ladhina an''amta ''alayhim, ghayril-maghdubi ''alayhim wa lad-dallin."}, "meaning": {"bn": "সকল প্রশংসা আল্লাহর, যিনি সমস্ত জগতের রব। যিনি পরম করুণাময়, অতি দয়ালু। যিনি প্রতিদান দিবসের মালিক। আমরা শুধু আপনারই ইবাদত করি এবং শুধু আপনারই কাছে সাহায্য চাই। আমাদের সরল পথ দেখান — তাদের পথ, যাদের আপনি নিয়ামত দিয়েছেন; তাদের পথ নয় যাদের উপর আপনার গজব পড়েছে, আর তাদের পথও নয় যারা পথভ্রষ্ট।", "en": "All praise is for Allah, Lord of all the worlds, the Most Gracious, the Most Merciful, Master of the Day of Judgement. You alone we worship and You alone we ask for help. Guide us to the straight path: the path of those You have blessed, not of those who earned Your anger, nor of those who went astray."}, "ref": {"bn": "সূরা ফাতিহা ১:২–৭ (মুসহাফে বিসমিল্লাহ ১ নম্বর আয়াত)", "en": "Al-Fatihah 1:2–7 (the Basmalah is ayah 1 in the Mushaf)"}}, {"type": "note", "tone": "info", "text": {"bn": "মুসহাফে বিসমিল্লাহ সূরা ফাতিহার প্রথম আয়াত; আগের ধাপে তা পড়া হয়েছে, তাই এখানে \"আলহামদু লিল্লাহ\" থেকে শুরু।", "en": "In the Mushaf the Basmalah is the first ayah of Al-Fatihah; it was said in the previous step, so here we begin from \"Al-hamdu lillah\"."}}, {"type": "step", "title": {"bn": "আমিন", "en": "Amin"}, "text": {"bn": "ফাতিহা শেষ হলে \"আমিন\" বলুন (হানাফি মতে নিচু স্বরে)।", "en": "When Al-Fatihah ends, say \"Amin\" (quietly, in the Hanafi view)."}}, {"type": "arabic", "label": {"bn": "আমিন", "en": "Amin"}, "ar": "آمِينَ", "pron": {"bn": "আমিন", "en": "Amin"}, "meaning": {"bn": "হে আল্লাহ! কবুল করুন।", "en": "O Allah, accept (answer our prayer)."}, "ref": {"bn": "সহিহ বুখারি ৭৮০; সহিহ মুসলিম ৪১০", "en": "Sahih al-Bukhari 780; Sahih Muslim 410"}}, {"type": "step", "title": {"bn": "আরেকটি সূরা মিলানো", "en": "Recite another surah"}, "text": {"bn": "এরপর কুরআন থেকে যেকোনো একটি সূরা বা কমপক্ষে ছোট তিন আয়াত পরিমাণ পড়ুন। উদাহরণ হিসেবে সূরা ইখলাস:", "en": "Then recite any surah, or at least the length of three short ayat. For example, Surah Al-Ikhlas:"}}, {"type": "arabic", "label": {"bn": "সূরা ইখলাস (উদাহরণ)", "en": "Surah Al-Ikhlas (example)"}, "ar": "قُلْ هُوَ اللَّهُ أَحَدٌ ﴿١﴾ اللَّهُ الصَّمَدُ ﴿٢﴾ لَمْ يَلِدْ وَلَمْ يُولَدْ ﴿٣﴾ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ ﴿٤﴾", "pron": {"bn": "কুল হুয়াল্লাহু আহাদ। আল্লাহুস সামাদ। লাম ইয়ালিদ ওয়া লাম ইউলাদ। ওয়া লাম ইয়াকুল লাহু কুফুওয়ান আহাদ।", "en": "Qul huwallahu ahad. Allahus-samad. Lam yalid wa lam yulad. Wa lam yakul-lahu kufuwan ahad."}, "meaning": {"bn": "বলুন, তিনিই আল্লাহ, এক ও অদ্বিতীয়। আল্লাহ কারো মুখাপেক্ষী নন, সবাই তাঁর মুখাপেক্ষী। তিনি কাউকে জন্ম দেননি এবং কেউ তাঁকে জন্ম দেয়নি। আর তাঁর সমকক্ষ কেউ নেই।", "en": "Say: He is Allah, the One. Allah, the Self-Sufficient on whom all depend. He neither begets nor was He begotten. And there is none comparable to Him."}, "ref": {"bn": "সূরা ইখলাস ১১২:১–৪", "en": "Al-Ikhlas 112:1–4"}}, {"type": "step", "title": {"bn": "রুকু", "en": "Ruku (bowing)"}, "text": {"bn": "\"আল্লাহু আকবার\" বলে রুকুতে যান। আঙুল ছড়িয়ে দুই হাঁটু ধরুন, পিঠ সোজা রাখুন, মাথা পিঠের সমান রাখুন — উঁচুও না, নিচুও না। ধীরস্থিরভাবে কমপক্ষে তিনবার তাসবিহ পড়ুন।", "en": "Say \"Allahu akbar\" and bow. Grip the knees with the fingers spread, keep the back straight and the head level with it, neither raised nor lowered. Calmly say the tasbih at least three times."}}, {"type": "arabic", "label": {"bn": "রুকুতে যাওয়ার তাকবির", "en": "Takbir for going into ruku"}, "ar": "اللَّهُ أَكْبَرُ", "pron": {"bn": "আল্লাহু আকবার", "en": "Allahu akbar"}, "meaning": {"bn": "আল্লাহ সবচেয়ে বড়।", "en": "Allah is the Greatest."}}, {"type": "arabic", "label": {"bn": "রুকুর তাসবিহ (কমপক্ষে ৩ বার)", "en": "Ruku tasbih (at least 3 times)"}, "ar": "سُبْحَانَ رَبِّيَ الْعَظِيمِ", "pron": {"bn": "সুবহানা রাব্বিয়াল আযিম।", "en": "Subhana rabbiyal-''azim."}, "meaning": {"bn": "আমার মহান রব পবিত্র।", "en": "Glory be to my Lord, the Magnificent."}, "ref": {"bn": "সহিহ মুসলিম ৭৭২; সুনান আবু দাউদ ৮৭১", "en": "Sahih Muslim 772; Sunan Abi Dawud 871"}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৪৯৮ — রুকুতে মাথা না উঁচু, না নিচু", "en": "Sahih Muslim 498: in ruku the head neither raised nor lowered"}}, {"type": "step", "title": {"bn": "রুকু থেকে ওঠা (কাওমা)", "en": "Rising from ruku (qawmah)"}, "text": {"bn": "ওঠার সময় \"সামিআল্লাহু লিমান হামিদাহ\" বলুন। পুরোপুরি সোজা হয়ে দাঁড়িয়ে স্থির হোন এবং \"রাব্বানা ওয়া লাকাল হামদ\" বলুন। জামাতে ইমাম তাসমি বলবেন, মুক্তাদিরা শুধু তাহমিদ বলবেন (হানাফি মত)।", "en": "While rising say \"Sami''allahu liman hamidah\". Stand fully upright, become still, and say \"Rabbana wa lakal-hamd\". In congregation the imam says the tasmi'' and the followers say only the tahmid (Hanafi view)."}}, {"type": "arabic", "label": {"bn": "তাসমি (রুকু থেকে ওঠার সময়)", "en": "Tasmi'' (while rising from ruku)"}, "ar": "سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ", "pron": {"bn": "সামিআল্লাহু লিমান হামিদাহ।", "en": "Sami''allahu liman hamidah."}, "meaning": {"bn": "যে আল্লাহর প্রশংসা করে, আল্লাহ তার কথা শোনেন।", "en": "Allah hears the one who praises Him."}, "ref": {"bn": "সহিহ বুখারি ৭৯৬", "en": "Sahih al-Bukhari 796"}}, {"type": "arabic", "label": {"bn": "তাহমিদ (সোজা হয়ে দাঁড়িয়ে)", "en": "Tahmid (once standing straight)"}, "ar": "رَبَّنَا وَلَكَ الْحَمْدُ", "pron": {"bn": "রাব্বানা ওয়া লাকাল হামদ।", "en": "Rabbana wa lakal-hamd."}, "meaning": {"bn": "হে আমাদের রব! সকল প্রশংসা আপনারই।", "en": "Our Lord, and to You belongs all praise."}, "ref": {"bn": "সহিহ বুখারি ৭৯৬", "en": "Sahih al-Bukhari 796"}}, {"type": "arabic", "label": {"bn": "তাহমিদের দীর্ঘ রূপ (ঐচ্ছিক)", "en": "Longer form of tahmid (optional)"}, "ar": "رَبَّنَا وَلَكَ الْحَمْدُ، حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ", "pron": {"bn": "রাব্বানা ওয়া লাকাল হামদু, হামদান কাসিরান তাইয়িবান মুবারাকান ফিহ।", "en": "Rabbana wa lakal-hamdu, hamdan kathiran tayyiban mubarakan fih."}, "meaning": {"bn": "হে আমাদের রব! সকল প্রশংসা আপনার — অনেক অনেক, পবিত্র ও বরকতময় প্রশংসা।", "en": "Our Lord, to You belongs all praise: abundant, pure and blessed praise."}, "ref": {"bn": "সহিহ বুখারি ৭৯৯", "en": "Sahih al-Bukhari 799"}}, {"type": "step", "title": {"bn": "প্রথম সিজদা", "en": "The first sujud"}, "text": {"bn": "\"আল্লাহু আকবার\" বলে সিজদায় যান: প্রথমে দুই হাঁটু, তারপর দুই হাত, তারপর নাক ও কপাল মাটিতে রাখুন। মুখ দুই হাতের মাঝে থাকবে, আঙুলগুলো মিলিয়ে কিবলামুখী। পুরুষরা পেট উরু থেকে এবং বাহু পাঁজর থেকে আলাদা রাখবেন, কনুই মাটি থেকে উঁচুতে। পায়ের আঙুল কিবলার দিকে মোড়ানো থাকবে। কমপক্ষে তিনবার তাসবিহ পড়ুন।", "en": "Say \"Allahu akbar\" and go down: knees first, then hands, then nose and forehead. The face is between the hands, fingers together and pointing to the qiblah. Men keep the belly away from the thighs and the arms away from the sides, elbows off the ground. The toes are bent towards the qiblah. Say the tasbih at least three times."}}, {"type": "arabic", "label": {"bn": "সিজদায় যাওয়ার তাকবির", "en": "Takbir for going into sujud"}, "ar": "اللَّهُ أَكْبَرُ", "pron": {"bn": "আল্লাহু আকবার", "en": "Allahu akbar"}, "meaning": {"bn": "আল্লাহ সবচেয়ে বড়।", "en": "Allah is the Greatest."}}, {"type": "arabic", "label": {"bn": "সিজদার তাসবিহ (কমপক্ষে ৩ বার)", "en": "Sujud tasbih (at least 3 times)"}, "ar": "سُبْحَانَ رَبِّيَ الْأَعْلَىٰ", "pron": {"bn": "সুবহানা রাব্বিয়াল আ''লা।", "en": "Subhana rabbiyal-a''la."}, "meaning": {"bn": "আমার সর্বোচ্চ রব পবিত্র।", "en": "Glory be to my Lord, the Most High."}, "ref": {"bn": "সহিহ মুসলিম ৭৭২; সুনান আবু দাউদ ৮৭১", "en": "Sahih Muslim 772; Sunan Abi Dawud 871"}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৮১২; সহিহ মুসলিম ৪৯০ — সাত অঙ্গে সিজদা: কপাল (নাকসহ), দুই হাত, দুই হাঁটু ও দুই পায়ের আঙুল", "en": "Sahih al-Bukhari 812; Sahih Muslim 490: prostrating on seven bones: forehead (with the nose), two hands, two knees and the toes of both feet"}}, {"type": "step", "title": {"bn": "দুই সিজদার মাঝে বসা (জালসা)", "en": "Sitting between the two sujud (jalsah)"}, "text": {"bn": "\"আল্লাহু আকবার\" বলে উঠে বসুন — বাম পা বিছিয়ে তার উপর বসুন, ডান পা খাড়া রাখুন, আঙুল কিবলামুখী; হাত দুটি উরুর উপর। পুরোপুরি স্থির হয়ে বসুন; চাইলে নিচের দোয়াটি পড়ুন।", "en": "Say \"Allahu akbar\" and sit up: sit on the left foot laid flat, with the right foot upright and its toes facing the qiblah, hands on the thighs. Become fully still; you may recite the dua below."}}, {"type": "arabic", "label": {"bn": "দুই সিজদার মাঝের দোয়া", "en": "Dua between the two sujud"}, "ar": "اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَعَافِنِي، وَاهْدِنِي، وَارْزُقْنِي", "pron": {"bn": "আল্লাহুম্মাগফিরলি, ওয়ারহামনি, ওয়া আফিনি, ওয়াহদিনি, ওয়ারযুকনি।", "en": "Allahummaghfir li, warhamni, wa ''afini, wahdini, warzuqni."}, "meaning": {"bn": "হে আল্লাহ! আমাকে ক্ষমা করুন, আমার উপর দয়া করুন, আমাকে নিরাপদ রাখুন, সঠিক পথ দেখান এবং রিজিক দিন।", "en": "O Allah, forgive me, have mercy on me, keep me safe and well, guide me and provide for me."}, "ref": {"bn": "সুনান আবু দাউদ ৮৫০", "en": "Sunan Abi Dawud 850"}}, {"type": "step", "title": {"bn": "দ্বিতীয় সিজদা", "en": "The second sujud"}, "text": {"bn": "\"আল্লাহু আকবার\" বলে আবার আগের মতো সিজদা করুন এবং কমপক্ষে তিনবার \"সুবহানা রাব্বিয়াল আ''লা\" পড়ুন। এর মাধ্যমে প্রথম রাকাত শেষ হলো।", "en": "Say \"Allahu akbar\" and prostrate again as before, saying \"Subhana rabbiyal-a''la\" at least three times. This completes the first rakat."}}, {"type": "heading", "text": {"bn": "দ্বিতীয় রাকাত", "en": "The second rakat"}}, {"type": "step", "title": {"bn": "দাঁড়িয়ে যাওয়া", "en": "Stand up"}, "text": {"bn": "\"আল্লাহু আকবার\" বলে দ্বিতীয় রাকাতের জন্য সোজা দাঁড়িয়ে হাত বাঁধুন। হানাফি মতে মাঝখানে না বসে পায়ের পাতার উপর ভর দিয়ে উঠবেন।", "en": "Say \"Allahu akbar\" and stand straight up for the second rakat, folding the hands. In the Hanafi view one rises on the front of the feet without sitting first."}}, {"type": "note", "tone": "info", "text": {"bn": "শাফেয়ি মাযহাবসহ কিছু আলেমের মতে দ্বিতীয় সিজদার পর দাঁড়ানোর আগে সামান্য বসা (জালসায়ে ইস্তিরাহা) সুন্নত (সহিহ বুখারি ৮২৩)। হানাফি মতে এটি বার্ধক্য বা প্রয়োজনের কারণে ছিল।", "en": "Shafi''is and some others hold that a brief sit before standing (jalsat al-istirahah) is sunnah (Sahih al-Bukhari 823). Hanafis understand it as done due to age or need."}}, {"type": "step", "title": {"bn": "ফাতিহা ও সূরা", "en": "Al-Fatihah and a surah"}, "text": {"bn": "দ্বিতীয় রাকাতে সানা ও আউযুবিল্লাহ পড়বেন না। বিসমিল্লাহ পড়ে সূরা ফাতিহা, আমিন, তারপর আরেকটি সূরা (যেমন সূরা কাওসার বা যেকোনো সূরা) পড়ুন। প্রথম রাকাতের চেয়ে দ্বিতীয় রাকাতের কিরাত একটু ছোট হওয়া সুন্নত।", "en": "In the second rakat do not repeat the thana or ta''awwudh. Say Bismillah, recite Al-Fatihah, say Amin, then another surah (e.g. Al-Kawthar or any surah). It is sunnah for the second rakat''s recitation to be a little shorter than the first."}}, {"type": "step", "title": {"bn": "রুকু ও সিজদা", "en": "Ruku and sujud"}, "text": {"bn": "প্রথম রাকাতের মতোই রুকু, রুকু থেকে ওঠা, দুই সিজদা ও মাঝের বসা আদায় করুন — প্রতিটিতে ধীরস্থিরভাবে।", "en": "Do the ruku, the rising, the two sujud and the sitting between them exactly as in the first rakat, calmly in each."}}, {"type": "heading", "text": {"bn": "শেষ বৈঠক ও সালাম", "en": "The final sitting and salam"}}, {"type": "step", "title": {"bn": "বসা ও তাশাহহুদ", "en": "Sit and recite the tashahhud"}, "text": {"bn": "দ্বিতীয় সিজদার পর \"আল্লাহু আকবার\" বলে জালসার মতো বসুন, হাত দুটি উরুর উপর। আত্তাহিয়্যাতু পড়ুন। \"আশহাদু আল লা ইলাহা\" বলার সময় ডান হাতের শাহাদাত আঙুল উঠিয়ে ইশারা করুন, \"ইল্লাল্লাহ\" বলার সময় নামিয়ে নিন (হানাফি পদ্ধতি)।", "en": "After the second sujud say \"Allahu akbar\" and sit as in the jalsah, hands on the thighs. Recite the tashahhud. At \"ashhadu an la ilaha\" raise the right index finger to point, and lower it at \"illallah\" (Hanafi method)."}}, {"type": "arabic", "label": {"bn": "তাশাহহুদ (আত্তাহিয়্যাতু)", "en": "Tashahhud (At-tahiyyat)"}, "ar": "التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَىٰ عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَٰهَ إِلَّا اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ", "pron": {"bn": "আত্তাহিয়্যাতু লিল্লাহি ওয়াস সালাওয়াতু ওয়াত তাইয়িবাতু, আসসালামু আলাইকা আইয়্যুহান নাবিয়্যু ওয়া রাহমাতুল্লাহি ওয়া বারাকাতুহ, আসসালামু আলাইনা ওয়া আলা ইবাদিল্লাহিস সালিহিন। আশহাদু আল লা ইলাহা ইল্লাল্লাহু, ওয়া আশহাদু আন্না মুহাম্মাদান আবদুহু ওয়া রাসুলুহ।", "en": "At-tahiyyatu lillahi was-salawatu wat-tayyibat. As-salamu ''alayka ayyuhan-nabiyyu wa rahmatullahi wa barakatuh. As-salamu ''alayna wa ''ala ''ibadillahis-salihin. Ashhadu an la ilaha illallahu, wa ashhadu anna Muhammadan ''abduhu wa rasuluh."}, "meaning": {"bn": "সকল সম্মান, সকল নামাজ-ইবাদত ও সকল পবিত্র বিষয় আল্লাহর জন্য। হে নবী! আপনার প্রতি সালাম এবং আল্লাহর রহমত ও বরকত। সালাম আমাদের প্রতি এবং আল্লাহর সকল নেক বান্দার প্রতি। আমি সাক্ষ্য দিচ্ছি, আল্লাহ ছাড়া কোনো ইলাহ নেই, এবং আমি সাক্ষ্য দিচ্ছি, মুহাম্মাদ ﷺ তাঁর বান্দা ও রাসুল।", "en": "All greetings, prayers and good things are for Allah. Peace be upon you, O Prophet, and the mercy of Allah and His blessings. Peace be upon us and upon the righteous servants of Allah. I bear witness that there is no god but Allah, and I bear witness that Muhammad is His servant and Messenger."}, "ref": {"bn": "সহিহ বুখারি ৮৩১; সহিহ মুসলিম ৪০২", "en": "Sahih al-Bukhari 831; Sahih Muslim 402"}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৫৮০ — তাশাহহুদে শাহাদাত আঙুল দিয়ে ইশারা", "en": "Sahih Muslim 580: pointing with the index finger in the tashahhud"}}, {"type": "step", "title": {"bn": "দরুদ", "en": "Durood"}, "text": {"bn": "এরপর দরুদে ইবরাহিম পড়ুন।", "en": "Then recite the Durood Ibrahim."}}, {"type": "arabic", "label": {"bn": "দরুদে ইবরাহিম", "en": "Durood Ibrahim (Salat Ibrahimiyyah)"}, "ar": "اللَّهُمَّ صَلِّ عَلَىٰ مُحَمَّدٍ وَعَلَىٰ آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَىٰ إِبْرَاهِيمَ وَعَلَىٰ آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ. اللَّهُمَّ بَارِكْ عَلَىٰ مُحَمَّدٍ وَعَلَىٰ آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَىٰ إِبْرَاهِيمَ وَعَلَىٰ آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ", "pron": {"bn": "আল্লাহুম্মা সাল্লি আলা মুহাম্মাদিও ওয়া আলা আলি মুহাম্মাদ, কামা সাল্লাইতা আলা ইবরাহিমা ওয়া আলা আলি ইবরাহিম, ইন্নাকা হামিদুম মাজিদ। আল্লাহুম্মা বারিক আলা মুহাম্মাদিও ওয়া আলা আলি মুহাম্মাদ, কামা বারাকতা আলা ইবরাহিমা ওয়া আলা আলি ইবরাহিম, ইন্নাকা হামিদুম মাজিদ।", "en": "Allahumma salli ''ala Muhammadin wa ''ala ali Muhammad, kama sallayta ''ala Ibrahima wa ''ala ali Ibrahim, innaka hamidum majid. Allahumma barik ''ala Muhammadin wa ''ala ali Muhammad, kama barakta ''ala Ibrahima wa ''ala ali Ibrahim, innaka hamidum majid."}, "meaning": {"bn": "হে আল্লাহ! মুহাম্মাদ ﷺ ও তাঁর পরিবারবর্গের প্রতি রহমত বর্ষণ করুন, যেমন আপনি ইবরাহিম (আ.) ও তাঁর পরিবারবর্গের প্রতি রহমত বর্ষণ করেছেন; নিশ্চয়ই আপনি প্রশংসিত, মহিমান্বিত। হে আল্লাহ! মুহাম্মাদ ﷺ ও তাঁর পরিবারবর্গের প্রতি বরকত দিন, যেমন আপনি ইবরাহিম (আ.) ও তাঁর পরিবারবর্গের প্রতি বরকত দিয়েছেন; নিশ্চয়ই আপনি প্রশংসিত, মহিমান্বিত।", "en": "O Allah, send prayers upon Muhammad and the family of Muhammad, as You sent prayers upon Ibrahim and the family of Ibrahim; You are Praiseworthy, Glorious. O Allah, bless Muhammad and the family of Muhammad, as You blessed Ibrahim and the family of Ibrahim; You are Praiseworthy, Glorious."}, "ref": {"bn": "সহিহ বুখারি ৩৩৭০; সহিহ মুসলিম ৪০৬", "en": "Sahih al-Bukhari 3370; Sahih Muslim 406"}}, {"type": "step", "title": {"bn": "দোয়া", "en": "Dua"}, "text": {"bn": "এরপর কুরআন-হাদিসের কোনো দোয়া পড়ুন; সবচেয়ে প্রচলিত হলো দোয়া মাসুরা, যা রাসুলুল্লাহ ﷺ আবু বকর (রা.)-কে নামাজে পড়ার জন্য শিখিয়েছিলেন।", "en": "Then recite a dua from the Quran or Sunnah. The most common is dua ma''thura, which the Prophet ﷺ taught Abu Bakr (RA) to say in his prayer."}}, {"type": "arabic", "label": {"bn": "দোয়া মাসুরা", "en": "Dua ma''thura"}, "ar": "اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا، وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ، وَارْحَمْنِي، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ", "pron": {"bn": "আল্লাহুম্মা ইন্নি যালামতু নাফসি যুলমান কাসিরা, ওয়ালা ইয়াগফিরুয যুনুবা ইল্লা আনতা, ফাগফিরলি মাগফিরাতাম মিন ইনদিকা, ওয়ারহামনি, ইন্নাকা আনতাল গাফুরুর রাহিম।", "en": "Allahumma inni zalamtu nafsi zulman kathira, wa la yaghfirudh-dhunuba illa anta, faghfir li maghfiratam min ''indika, warhamni, innaka antal-ghafurur-rahim."}, "meaning": {"bn": "হে আল্লাহ! আমি নিজের উপর অনেক জুলুম করেছি, আর আপনি ছাড়া কেউ গুনাহ ক্ষমা করতে পারে না। তাই আপনার পক্ষ থেকে আমাকে বিশেষ ক্ষমা দান করুন এবং আমার উপর রহম করুন। নিশ্চয়ই আপনি অতি ক্ষমাশীল, পরম দয়ালু।", "en": "O Allah, I have wronged myself greatly, and none forgives sins but You. So grant me forgiveness from Yourself and have mercy on me; You are the Oft-Forgiving, the Most Merciful."}, "ref": {"bn": "সহিহ বুখারি ৮৩৪; সহিহ মুসলিম ২৭০৫", "en": "Sahih al-Bukhari 834; Sahih Muslim 2705"}}, {"type": "step", "title": {"bn": "সালাম ফেরানো", "en": "Give the salam"}, "text": {"bn": "প্রথমে ডান দিকে মুখ ফিরিয়ে বলুন \"আসসালামু আলাইকুম ওয়া রাহমাতুল্লাহ\", তারপর বাম দিকে মুখ ফিরিয়ে একই কথা বলুন। এর মাধ্যমে নামাজ শেষ হলো।", "en": "Turn your face to the right and say \"As-salamu ''alaykum wa rahmatullah\", then to the left saying the same. The prayer is complete."}}, {"type": "arabic", "label": {"bn": "সালাম (প্রথমে ডানে, তারপর বামে)", "en": "Salam (right, then left)"}, "ar": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ", "pron": {"bn": "আসসালামু আলাইকুম ওয়া রাহমাতুল্লাহ।", "en": "As-salamu ''alaykum wa rahmatullah."}, "meaning": {"bn": "আপনাদের উপর শান্তি ও আল্লাহর রহমত বর্ষিত হোক।", "en": "Peace be upon you and the mercy of Allah."}, "ref": {"bn": "সহিহ মুসলিম ৫৮২; সুনান আবু দাউদ ৯৯৬", "en": "Sahih Muslim 582; Sunan Abi Dawud 996"}}, {"type": "note", "tone": "tip", "text": {"bn": "সালামের পর তাড়াহুড়া করে উঠে না গিয়ে নামাজের পরের জিকিরগুলো পড়ুন — \"নামাজের পরের জিকির ও দোয়া\" অংশে দেওয়া আছে।", "en": "After the salam, do not rush off: recite the dhikr after prayer, given in \"Dhikr and Duas after Salah\"."}}]', 'in_review', 60 FROM is_guide_topics WHERE slug = 'salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '9f9d5a21-06e2-5755-b6a4-cf272418c8ac', id, 'salah-three-four-rakat', '{"bn": "তিন ও চার রাকাত নামাজ", "en": "Praying Three and Four Rakats"}', '{"bn": "মাগরিবের তিন রাকাত এবং জোহর, আসর ও এশার চার রাকাত — দুই রাকাতের পর প্রথম বৈঠক থেকে শেষ পর্যন্ত কী করবেন।", "en": "The three rakats of Maghrib and the four of Zuhr, Asr and Isha: what to do from the first sitting after two rakats to the end."}', 'basic', '[{"type": "text", "text": {"bn": "তিন বা চার রাকাতের নামাজের প্রথম দুই রাকাত হুবহু \"দুই রাকাত নামাজ\" অংশের মতো। পার্থক্য শুরু হয় দ্বিতীয় রাকাতের দ্বিতীয় সিজদার পর।", "en": "The first two rakats of a three- or four-rakat prayer are exactly as in \"How to Pray Two Rakats\". The difference begins after the second sujud of the second rakat."}}, {"type": "heading", "text": {"bn": "প্রথম বৈঠক (কাদায়ে উলা)", "en": "The first sitting"}}, {"type": "step", "title": {"bn": "বসে শুধু তাশাহহুদ", "en": "Sit and recite only the tashahhud"}, "text": {"bn": "দ্বিতীয় রাকাতের দুই সিজদার পর বসুন এবং শুধু আত্তাহিয়্যাতু \"আবদুহু ওয়া রাসুলুহ\" পর্যন্ত পড়ুন। ফরজ ও সুন্নতে মুয়াক্কাদায় এখানে দরুদ বা দোয়া পড়বেন না।", "en": "After the two sujud of the second rakat, sit and recite only the tashahhud up to \"''abduhu wa rasuluh\". In fard and sunnah muakkadah prayers do not add the durood or dua here."}}, {"type": "arabic", "label": {"bn": "তাশাহহুদ (আত্তাহিয়্যাতু)", "en": "Tashahhud (At-tahiyyat)"}, "ar": "التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَىٰ عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَٰهَ إِلَّا اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ", "pron": {"bn": "আত্তাহিয়্যাতু লিল্লাহি ওয়াস সালাওয়াতু ওয়াত তাইয়িবাতু, আসসালামু আলাইকা আইয়্যুহান নাবিয়্যু ওয়া রাহমাতুল্লাহি ওয়া বারাকাতুহ, আসসালামু আলাইনা ওয়া আলা ইবাদিল্লাহিস সালিহিন। আশহাদু আল লা ইলাহা ইল্লাল্লাহু, ওয়া আশহাদু আন্না মুহাম্মাদান আবদুহু ওয়া রাসুলুহ।", "en": "At-tahiyyatu lillahi was-salawatu wat-tayyibat. As-salamu ''alayka ayyuhan-nabiyyu wa rahmatullahi wa barakatuh. As-salamu ''alayna wa ''ala ''ibadillahis-salihin. Ashhadu an la ilaha illallahu, wa ashhadu anna Muhammadan ''abduhu wa rasuluh."}, "meaning": {"bn": "সকল সম্মান, সকল নামাজ-ইবাদত ও সকল পবিত্র বিষয় আল্লাহর জন্য। হে নবী! আপনার প্রতি সালাম এবং আল্লাহর রহমত ও বরকত। সালাম আমাদের প্রতি এবং আল্লাহর সকল নেক বান্দার প্রতি। আমি সাক্ষ্য দিচ্ছি, আল্লাহ ছাড়া কোনো ইলাহ নেই, এবং আমি সাক্ষ্য দিচ্ছি, মুহাম্মাদ ﷺ তাঁর বান্দা ও রাসুল।", "en": "All greetings, prayers and good things are for Allah. Peace be upon you, O Prophet, and the mercy of Allah and His blessings. Peace be upon us and upon the righteous servants of Allah. I bear witness that there is no god but Allah, and I bear witness that Muhammad is His servant and Messenger."}, "ref": {"bn": "সহিহ বুখারি ৮৩১; সহিহ মুসলিম ৪০২", "en": "Sahih al-Bukhari 831; Sahih Muslim 402"}}, {"type": "note", "tone": "warn", "text": {"bn": "প্রথম বৈঠকে ভুলে \"আল্লাহুম্মা সাল্লি আলা মুহাম্মাদ\" পর্যন্ত বা তার বেশি পড়ে ফেললে হানাফি মতে শেষে সাহু সিজদা দিতে হবে। আর প্রথম বৈঠক ভুলে গিয়ে পুরোপুরি দাঁড়িয়ে গেলে আর বসতে ফিরবেন না; নামাজ শেষে সাহু সিজদা দেবেন (সহিহ বুখারি ১২২৪; সহিহ মুসলিম ৫৭০)।", "en": "If in the first sitting you mistakenly add \"Allahumma salli ''ala Muhammad\" or more, Hanafis require sajdah sahw at the end. If you forget the first sitting and have fully stood up, do not go back; do sajdah sahw at the end (Sahih al-Bukhari 1224; Sahih Muslim 570)."}}, {"type": "step", "title": {"bn": "তৃতীয় রাকাতের জন্য দাঁড়ানো", "en": "Stand for the third rakat"}, "text": {"bn": "\"আল্লাহু আকবার\" বলে সোজা দাঁড়িয়ে হাত বাঁধুন।", "en": "Say \"Allahu akbar\", stand straight up and fold the hands."}}, {"type": "arabic", "label": {"bn": "দাঁড়ানোর তাকবির", "en": "Takbir for standing up"}, "ar": "اللَّهُ أَكْبَرُ", "pron": {"bn": "আল্লাহু আকবার", "en": "Allahu akbar"}, "meaning": {"bn": "আল্লাহ সবচেয়ে বড়।", "en": "Allah is the Greatest."}}, {"type": "heading", "text": {"bn": "তৃতীয় রাকাত", "en": "The third rakat"}}, {"type": "step", "title": {"bn": "কিরাত", "en": "Recitation"}, "text": {"bn": "বিসমিল্লাহ পড়ে সূরা ফাতিহা পড়ুন। ফরজ নামাজের তৃতীয় ও চতুর্থ রাকাতে ফাতিহার পর অন্য সূরা মেলাবেন না। কিন্তু সুন্নত, নফল ও বিতরের প্রতিটি রাকাতে ফাতিহার পর সূরা মেলানো ওয়াজিব।", "en": "Say Bismillah and recite Al-Fatihah. In the third and fourth rakats of fard prayers do not add another surah. But in every rakat of sunnah, nafl and witr prayers, adding a surah after Al-Fatihah is wajib."}}, {"type": "arabic", "label": {"bn": "সূরা আল-ফাতিহা", "en": "Surah Al-Fatihah"}, "ar": "الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ﴿٢﴾ الرَّحْمَٰنِ الرَّحِيمِ ﴿٣﴾ مَالِكِ يَوْمِ الدِّينِ ﴿٤﴾ إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ﴿٥﴾ اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ ﴿٦﴾ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ ﴿٧﴾", "pron": {"bn": "আলহামদু লিল্লাহি রাব্বিল আলামিন। আর-রাহমানির রাহিম। মালিকি ইয়াওমিদ্দিন। ইয়্যাকা না''বুদু ওয়া ইয়্যাকা নাসতাইন। ইহদিনাস সিরাতাল মুসতাকিম। সিরাতাল্লাযিনা আন''আমতা আলাইহিম, গাইরিল মাগদুবি আলাইহিম ওয়ালাদ্দাল্লিন।", "en": "Al-hamdu lillahi rabbil-''alamin. Ar-rahmanir-rahim. Maliki yawmid-din. Iyyaka na''budu wa iyyaka nasta''in. Ihdinas-siratal-mustaqim. Siratal-ladhina an''amta ''alayhim, ghayril-maghdubi ''alayhim wa lad-dallin."}, "meaning": {"bn": "সকল প্রশংসা আল্লাহর, যিনি সমস্ত জগতের রব। যিনি পরম করুণাময়, অতি দয়ালু। যিনি প্রতিদান দিবসের মালিক। আমরা শুধু আপনারই ইবাদত করি এবং শুধু আপনারই কাছে সাহায্য চাই। আমাদের সরল পথ দেখান — তাদের পথ, যাদের আপনি নিয়ামত দিয়েছেন; তাদের পথ নয় যাদের উপর আপনার গজব পড়েছে, আর তাদের পথও নয় যারা পথভ্রষ্ট।", "en": "All praise is for Allah, Lord of all the worlds, the Most Gracious, the Most Merciful, Master of the Day of Judgement. You alone we worship and You alone we ask for help. Guide us to the straight path: the path of those You have blessed, not of those who earned Your anger, nor of those who went astray."}, "ref": {"bn": "সূরা ফাতিহা ১:২–৭ (মুসহাফে বিসমিল্লাহ ১ নম্বর আয়াত)", "en": "Al-Fatihah 1:2–7 (the Basmalah is ayah 1 in the Mushaf)"}}, {"type": "differ", "title": {"bn": "ফরজের শেষ দুই রাকাতে সূরা ফাতিহা", "en": "Al-Fatihah in the last two rakats of fard"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "শেষ দুই রাকাতে ফাতিহা পড়া সুন্নত ও উত্তম; কেউ না পড়ে তিনবার \"সুবহানাল্লাহ\" পরিমাণ চুপ থাকলে বা তাসবিহ পড়লেও নামাজ হয়ে যায়।", "en": "Reciting Al-Fatihah in the last two rakats is sunnah and best; if one instead stays silent or says tasbih for about three \"subhanallah\"s, the prayer is still valid."}, "evidence": {"bn": "আলি ও ইবনে মাসউদ (রা.) থেকে বর্ণিত — প্রথম দুই রাকাতে কিরাত পড়ো, শেষ দুই রাকাতে তাসবিহ (মুসান্নাফ ইবনে আবি শাইবা)।", "en": "Reported from Ali and Ibn Mas''ud (RA): recite in the first two rakats and glorify Allah in the last two (Musannaf Ibn Abi Shaybah)."}}, {"label": {"bn": "শাফেয়ি, মালেকি ও হাম্বলি", "en": "Shafi''i, Maliki and Hanbali"}, "text": {"bn": "প্রতিটি রাকাতেই সূরা ফাতিহা পড়া ফরজ (রুকন)।", "en": "Al-Fatihah is obligatory (a pillar) in every rakat."}, "evidence": {"bn": "রাসুলুল্লাহ ﷺ জোহরের শেষ দুই রাকাতে শুধু ফাতিহা পড়তেন — সহিহ বুখারি ৭৭৬; \"যে ফাতিহা পড়ে না তার নামাজ হয় না\" — সহিহ বুখারি ৭৫৬; ভুলভাবে নামাজ আদায়কারীকে প্রতি রাকাতে একই রকম করতে বলেছেন — সহিহ বুখারি ৭৫৭।", "en": "The Prophet ﷺ recited only Al-Fatihah in the last two rakats of Zuhr (Sahih al-Bukhari 776); \"no prayer for one who does not recite Al-Fatihah\" (Sahih al-Bukhari 756); the man who prayed badly was told to do the same in every rakat (Sahih al-Bukhari 757)."}}], "check": true}, {"type": "step", "title": {"bn": "রুকু ও দুই সিজদা", "en": "Ruku and two sujud"}, "text": {"bn": "আগের মতোই রুকু, কাওমা, দুই সিজদা ও জালসা আদায় করুন।", "en": "Do the ruku, rising, two sujud and the sitting between them as before."}}, {"type": "heading", "text": {"bn": "মাগরিব (তিন রাকাত) হলে", "en": "If it is Maghrib (three rakats)"}}, {"type": "step", "title": {"bn": "শেষ বৈঠক", "en": "The final sitting"}, "text": {"bn": "তৃতীয় রাকাতের দুই সিজদার পর বসে তাশাহহুদ, দরুদে ইবরাহিম ও দোয়া মাসুরা পড়ে ডানে-বামে সালাম ফেরান — ঠিক দুই রাকাতের শেষ বৈঠকের মতো।", "en": "After the two sujud of the third rakat, sit and recite the tashahhud, Durood Ibrahim and dua ma''thura, then give salam right and left, exactly as at the end of a two-rakat prayer."}}, {"type": "heading", "text": {"bn": "জোহর, আসর ও এশা (চার রাকাত) হলে", "en": "If it is Zuhr, Asr or Isha (four rakats)"}}, {"type": "step", "title": {"bn": "চতুর্থ রাকাত", "en": "The fourth rakat"}, "text": {"bn": "তৃতীয় রাকাতের পর না বসে \"আল্লাহু আকবার\" বলে দাঁড়িয়ে যান। চতুর্থ রাকাত তৃতীয় রাকাতের মতোই পড়ুন (ফরজে শুধু ফাতিহা)।", "en": "After the third rakat do not sit; say \"Allahu akbar\" and stand. Pray the fourth rakat like the third (only Al-Fatihah in fard)."}}, {"type": "step", "title": {"bn": "শেষ বৈঠক ও সালাম", "en": "The final sitting and salam"}, "text": {"bn": "চতুর্থ রাকাতের দুই সিজদার পর বসে তাশাহহুদ, দরুদ ও দোয়া পড়ে সালাম ফেরান।", "en": "After the two sujud of the fourth rakat, sit, recite the tashahhud, durood and dua, and give salam."}}, {"type": "arabic", "label": {"bn": "দরুদে ইবরাহিম", "en": "Durood Ibrahim (Salat Ibrahimiyyah)"}, "ar": "اللَّهُمَّ صَلِّ عَلَىٰ مُحَمَّدٍ وَعَلَىٰ آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَىٰ إِبْرَاهِيمَ وَعَلَىٰ آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ. اللَّهُمَّ بَارِكْ عَلَىٰ مُحَمَّدٍ وَعَلَىٰ آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَىٰ إِبْرَاهِيمَ وَعَلَىٰ آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ", "pron": {"bn": "আল্লাহুম্মা সাল্লি আলা মুহাম্মাদিও ওয়া আলা আলি মুহাম্মাদ, কামা সাল্লাইতা আলা ইবরাহিমা ওয়া আলা আলি ইবরাহিম, ইন্নাকা হামিদুম মাজিদ। আল্লাহুম্মা বারিক আলা মুহাম্মাদিও ওয়া আলা আলি মুহাম্মাদ, কামা বারাকতা আলা ইবরাহিমা ওয়া আলা আলি ইবরাহিম, ইন্নাকা হামিদুম মাজিদ।", "en": "Allahumma salli ''ala Muhammadin wa ''ala ali Muhammad, kama sallayta ''ala Ibrahima wa ''ala ali Ibrahim, innaka hamidum majid. Allahumma barik ''ala Muhammadin wa ''ala ali Muhammad, kama barakta ''ala Ibrahima wa ''ala ali Ibrahim, innaka hamidum majid."}, "meaning": {"bn": "হে আল্লাহ! মুহাম্মাদ ﷺ ও তাঁর পরিবারবর্গের প্রতি রহমত বর্ষণ করুন, যেমন আপনি ইবরাহিম (আ.) ও তাঁর পরিবারবর্গের প্রতি রহমত বর্ষণ করেছেন; নিশ্চয়ই আপনি প্রশংসিত, মহিমান্বিত। হে আল্লাহ! মুহাম্মাদ ﷺ ও তাঁর পরিবারবর্গের প্রতি বরকত দিন, যেমন আপনি ইবরাহিম (আ.) ও তাঁর পরিবারবর্গের প্রতি বরকত দিয়েছেন; নিশ্চয়ই আপনি প্রশংসিত, মহিমান্বিত।", "en": "O Allah, send prayers upon Muhammad and the family of Muhammad, as You sent prayers upon Ibrahim and the family of Ibrahim; You are Praiseworthy, Glorious. O Allah, bless Muhammad and the family of Muhammad, as You blessed Ibrahim and the family of Ibrahim; You are Praiseworthy, Glorious."}, "ref": {"bn": "সহিহ বুখারি ৩৩৭০; সহিহ মুসলিম ৪০৬", "en": "Sahih al-Bukhari 3370; Sahih Muslim 406"}}, {"type": "arabic", "label": {"bn": "দোয়া মাসুরা", "en": "Dua ma''thura"}, "ar": "اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا، وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ، وَارْحَمْنِي، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ", "pron": {"bn": "আল্লাহুম্মা ইন্নি যালামতু নাফসি যুলমান কাসিরা, ওয়ালা ইয়াগফিরুয যুনুবা ইল্লা আনতা, ফাগফিরলি মাগফিরাতাম মিন ইনদিকা, ওয়ারহামনি, ইন্নাকা আনতাল গাফুরুর রাহিম।", "en": "Allahumma inni zalamtu nafsi zulman kathira, wa la yaghfirudh-dhunuba illa anta, faghfir li maghfiratam min ''indika, warhamni, innaka antal-ghafurur-rahim."}, "meaning": {"bn": "হে আল্লাহ! আমি নিজের উপর অনেক জুলুম করেছি, আর আপনি ছাড়া কেউ গুনাহ ক্ষমা করতে পারে না। তাই আপনার পক্ষ থেকে আমাকে বিশেষ ক্ষমা দান করুন এবং আমার উপর রহম করুন। নিশ্চয়ই আপনি অতি ক্ষমাশীল, পরম দয়ালু।", "en": "O Allah, I have wronged myself greatly, and none forgives sins but You. So grant me forgiveness from Yourself and have mercy on me; You are the Oft-Forgiving, the Most Merciful."}, "ref": {"bn": "সহিহ বুখারি ৮৩৪; সহিহ মুসলিম ২৭০৫", "en": "Sahih al-Bukhari 834; Sahih Muslim 2705"}}, {"type": "arabic", "label": {"bn": "সালাম (প্রথমে ডানে, তারপর বামে)", "en": "Salam (right, then left)"}, "ar": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ", "pron": {"bn": "আসসালামু আলাইকুম ওয়া রাহমাতুল্লাহ।", "en": "As-salamu ''alaykum wa rahmatullah."}, "meaning": {"bn": "আপনাদের উপর শান্তি ও আল্লাহর রহমত বর্ষিত হোক।", "en": "Peace be upon you and the mercy of Allah."}, "ref": {"bn": "সহিহ মুসলিম ৫৮২; সুনান আবু দাউদ ৯৯৬", "en": "Sahih Muslim 582; Sunan Abi Dawud 996"}}, {"type": "heading", "text": {"bn": "এক নজরে", "en": "At a glance"}}, {"type": "table", "head": [{"bn": "রাকাত", "en": "Rakat"}, {"bn": "ফরজ নামাজে", "en": "In fard prayers"}, {"bn": "সুন্নত, নফল ও বিতরে", "en": "In sunnah, nafl and witr"}], "rows": [[{"bn": "১ম", "en": "1st"}, {"bn": "সানা, আউযুবিল্লাহ, বিসমিল্লাহ, ফাতিহা + সূরা", "en": "Thana, ta''awwudh, Bismillah, Al-Fatihah + surah"}, {"bn": "সানা, আউযুবিল্লাহ, বিসমিল্লাহ, ফাতিহা + সূরা", "en": "Thana, ta''awwudh, Bismillah, Al-Fatihah + surah"}], [{"bn": "২য়", "en": "2nd"}, {"bn": "বিসমিল্লাহ, ফাতিহা + সূরা; তারপর প্রথম বৈঠক (৩–৪ রাকাতে)", "en": "Bismillah, Al-Fatihah + surah; then the first sitting (in 3–4 rakat prayers)"}, {"bn": "বিসমিল্লাহ, ফাতিহা + সূরা; তারপর বৈঠক", "en": "Bismillah, Al-Fatihah + surah; then sitting"}], [{"bn": "৩য়", "en": "3rd"}, {"bn": "বিসমিল্লাহ, শুধু ফাতিহা", "en": "Bismillah, Al-Fatihah only"}, {"bn": "বিসমিল্লাহ, ফাতিহা + সূরা", "en": "Bismillah, Al-Fatihah + surah"}], [{"bn": "৪র্থ", "en": "4th"}, {"bn": "বিসমিল্লাহ, শুধু ফাতিহা; তারপর শেষ বৈঠক", "en": "Bismillah, Al-Fatihah only; then the final sitting"}, {"bn": "বিসমিল্লাহ, ফাতিহা + সূরা; তারপর শেষ বৈঠক", "en": "Bismillah, Al-Fatihah + surah; then the final sitting"}]]}, {"type": "heading", "text": {"bn": "কোন নামাজে শব্দ করে কিরাত", "en": "Which prayers are recited aloud"}}, {"type": "table", "head": [{"bn": "নামাজ", "en": "Prayer"}, {"bn": "ইমামের কিরাত", "en": "The imam''s recitation"}], "rows": [[{"bn": "ফজর", "en": "Fajr"}, {"bn": "দুই রাকাতেই শব্দ করে", "en": "Aloud in both rakats"}], [{"bn": "জোহর ও আসর", "en": "Zuhr and Asr"}, {"bn": "সব রাকাতে নিচু স্বরে", "en": "Quietly in all rakats"}], [{"bn": "মাগরিব", "en": "Maghrib"}, {"bn": "প্রথম দুই রাকাতে শব্দ করে, তৃতীয়তে নিচু স্বরে", "en": "Aloud in the first two, quietly in the third"}], [{"bn": "এশা", "en": "Isha"}, {"bn": "প্রথম দুই রাকাতে শব্দ করে, শেষ দুই রাকাতে নিচু স্বরে", "en": "Aloud in the first two, quietly in the last two"}], [{"bn": "জুমা, দুই ঈদ, তারাবিহ, রমজানে জামাতের বিতর", "en": "Jumu''ah, the two Eids, tarawih, witr in congregation in Ramadan"}, {"bn": "শব্দ করে", "en": "Aloud"}]]}, {"type": "note", "tone": "info", "text": {"bn": "একা নামাজ পড়লে জোহর-আসরে অবশ্যই নিচু স্বরে পড়বেন; ফজর, মাগরিব ও এশায় চাইলে শব্দ করে বা নিচু স্বরে পড়তে পারেন (হানাফি মত)। দিনের সুন্নত-নফলে নিচু স্বরে, রাতের নফলে দুটোই চলে।", "en": "Praying alone, recite quietly in Zuhr and Asr; in Fajr, Maghrib and Isha you may recite aloud or quietly (Hanafi view). Daytime sunnah and nafl are quiet; at night either is fine."}}, {"type": "note", "tone": "info", "text": {"bn": "হানাফি কিতাবে আছে: চার রাকাত সুন্নতে মুয়াক্কাদায় (যেমন জোহরের আগের চার রাকাত) প্রথম বৈঠকে শুধু তাশাহহুদ পড়বে। আর আসর ও এশার আগের চার রাকাতের মতো গায়রে মুয়াক্কাদা নামাজে প্রথম বৈঠকে দরুদ-দোয়াও পড়া যায় এবং তৃতীয় রাকাতে সানা দিয়ে শুরু করা মুস্তাহাব।", "en": "Hanafi books say: in four-rakat sunnah muakkadah (such as the four before Zuhr) only the tashahhud is recited in the first sitting. In ghair muakkadah ones (such as the four before Asr and Isha) the durood and dua may also be recited in the first sitting, and it is recommended to begin the third rakat with the thana."}}]', 'in_review', 70 FROM is_guide_topics WHERE slug = 'salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '23f835fe-4dd6-50c9-a4c4-cc1dfc07e55f', id, 'short-surahs-takathur-to-kawthar', '{"bn": "নামাজের ছোট সূরা (১): তাকাসুর থেকে কাওসার", "en": "Short Surahs for Salah (1): At-Takathur to Al-Kawthar"}', '{"bn": "কুরআনের শেষ দিকের সাতটি ছোট সূরা — আরবি, উচ্চারণ ও অর্থসহ, মুসহাফের ক্রমে।", "en": "Seven short surahs from the end of the Quran, in Mushaf order, with Arabic, pronunciation and meaning."}', 'basic', '[{"type": "text", "text": {"bn": "নামাজে সূরা ফাতিহার পর যেকোনো সূরা বা কমপক্ষে ছোট তিন আয়াত পড়তে হয়। কুরআনের শেষ দিকের এই ছোট সূরাগুলো (সূরা ১০২–১১৪) সবচেয়ে বেশি মুখস্থ করা হয়। এই অংশে প্রথম সাতটি, পরের অংশে বাকি ছয়টি।", "en": "In salah, any surah or at least three short ayat are recited after Al-Fatihah. These short surahs at the end of the Quran (102–114) are the most commonly memorised. This guide has the first seven; the next has the remaining six."}}, {"type": "note", "tone": "tip", "text": {"bn": "দুই রাকাতে দুটি সূরা পড়লে মুসহাফের ক্রম রক্ষা করা উত্তম — যেমন প্রথম রাকাতে সূরা আসর, দ্বিতীয় রাকাতে সূরা কাওসার। উল্টো ক্রমে পড়লে নামাজ নষ্ট হয় না, তবে ইচ্ছাকৃতভাবে করা হানাফি মতে মাকরুহ।", "en": "When reciting two surahs in two rakats, it is better to keep the Mushaf order, e.g. Al-''Asr in the first and Al-Kawthar in the second. Reversing the order does not invalidate the prayer, though doing it deliberately is disliked in the Hanafi view."}}, {"type": "arabic", "label": {"bn": "সূরা তাকাসুর", "en": "Surah At-Takathur"}, "ar": "أَلْهَاكُمُ التَّكَاثُرُ ﴿١﴾ حَتَّىٰ زُرْتُمُ الْمَقَابِرَ ﴿٢﴾ كَلَّا سَوْفَ تَعْلَمُونَ ﴿٣﴾ ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ ﴿٤﴾ كَلَّا لَوْ تَعْلَمُونَ عِلْمَ الْيَقِينِ ﴿٥﴾ لَتَرَوُنَّ الْجَحِيمَ ﴿٦﴾ ثُمَّ لَتَرَوُنَّهَا عَيْنَ الْيَقِينِ ﴿٧﴾ ثُمَّ لَتُسْأَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ ﴿٨﴾", "pron": {"bn": "আলহাকুমুত তাকাসুর। হাত্তা যুরতুমুল মাকাবির। কাল্লা সাওফা তা''লামুন। সুম্মা কাল্লা সাওফা তা''লামুন। কাল্লা লাও তা''লামুনা ইলমাল ইয়াকিন। লাতারাউন্নাল জাহিম। সুম্মা লাতারাউন্নাহা আইনাল ইয়াকিন। সুম্মা লাতুসআলুন্না ইয়াওমাইযিন আনিন নাইম।", "en": "Alhakumut-takathur. Hatta zurtumul-maqabir. Kalla sawfa ta''lamun. Thumma kalla sawfa ta''lamun. Kalla law ta''lamuna ''ilmal-yaqin. Latarawunnal-jahim. Thumma latarawunnaha ''aynal-yaqin. Thumma latus''alunna yawma''idhin ''anin-na''im."}, "meaning": {"bn": "বেশি পাওয়ার প্রতিযোগিতা তোমাদের (আল্লাহ থেকে) উদাসীন করে রেখেছে, যতক্ষণ না তোমরা কবরে পৌঁছে যাও। কখনো নয়! শীঘ্রই তোমরা জানতে পারবে। আবারও বলি, কখনো নয়! শীঘ্রই তোমরা জানতে পারবে। কখনো নয়! যদি তোমরা নিশ্চিত জ্ঞানে জানতে! তোমরা অবশ্যই জাহান্নাম দেখবে। তারপর তোমরা তা নিশ্চিত চোখে দেখবে। তারপর সেদিন তোমাদের অবশ্যই নিয়ামত সম্পর্কে জিজ্ঞাসা করা হবে।", "en": "Competition for more distracts you, until you reach the graves. No! You will soon know. Again no! You will soon know. No! If only you knew with certain knowledge. You will surely see the Blazing Fire. Then you will surely see it with the eye of certainty. Then on that Day you will surely be asked about the blessings."}, "ref": {"bn": "সূরা তাকাসুর ১০২:১–৮", "en": "At-Takathur 102:1–8"}}, {"type": "arabic", "label": {"bn": "সূরা আসর", "en": "Surah Al-''Asr"}, "ar": "وَالْعَصْرِ ﴿١﴾ إِنَّ الْإِنْسَانَ لَفِي خُسْرٍ ﴿٢﴾ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ ﴿٣﴾", "pron": {"bn": "ওয়াল আসর। ইন্নাল ইনসানা লাফি খুসর। ইল্লাল্লাযিনা আমানু ওয়া আমিলুস সালিহাতি ওয়া তাওয়াসাও বিল হাক্কি ওয়া তাওয়াসাও বিস সাবর।", "en": "Wal-''asr. Innal-insana lafi khusr. Illal-ladhina amanu wa ''amilus-salihati wa tawasaw bil-haqqi wa tawasaw bis-sabr."}, "meaning": {"bn": "সময়ের শপথ! নিশ্চয়ই মানুষ ক্ষতির মধ্যে আছে — তারা ছাড়া, যারা ঈমান এনেছে, সৎকাজ করেছে, পরস্পরকে সত্যের উপদেশ দিয়েছে এবং পরস্পরকে ধৈর্যের উপদেশ দিয়েছে।", "en": "By time! Surely mankind is in loss, except those who believe, do righteous deeds, and urge one another to the truth and urge one another to patience."}, "ref": {"bn": "সূরা আসর ১০৩:১–৩", "en": "Al-''Asr 103:1–3"}}, {"type": "arabic", "label": {"bn": "সূরা হুমাযাহ", "en": "Surah Al-Humazah"}, "ar": "وَيْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ ﴿١﴾ الَّذِي جَمَعَ مَالًا وَعَدَّدَهُ ﴿٢﴾ يَحْسَبُ أَنَّ مَالَهُ أَخْلَدَهُ ﴿٣﴾ كَلَّا ۖ لَيُنْبَذَنَّ فِي الْحُطَمَةِ ﴿٤﴾ وَمَا أَدْرَاكَ مَا الْحُطَمَةُ ﴿٥﴾ نَارُ اللَّهِ الْمُوقَدَةُ ﴿٦﴾ الَّتِي تَطَّلِعُ عَلَى الْأَفْئِدَةِ ﴿٧﴾ إِنَّهَا عَلَيْهِمْ مُؤْصَدَةٌ ﴿٨﴾ فِي عَمَدٍ مُمَدَّدَةٍ ﴿٩﴾", "pron": {"bn": "ওয়াইলুল লিকুল্লি হুমাযাতিল লুমাযাহ। আল্লাযি জামাআ মালাও ওয়া আদ্দাদাহ। ইয়াহসাবু আন্না মালাহু আখলাদাহ। কাল্লা, লাইউমবাযান্না ফিল হুতামাহ। ওয়ামা আদরাকা মাল হুতামাহ। নারুল্লাহিল মুকাদাহ। আল্লাতি তাত্তালিউ আলাল আফইদাহ। ইন্নাহা আলাইহিম মু''সাদাহ। ফি আমাদিম মুমাদ্দাদাহ।", "en": "Waylul-likulli humazatil-lumazah. Alladhi jama''a malan wa ''addadah. Yahsabu anna malahu akhladah. Kalla, layunbadhanna fil-hutamah. Wa ma adraka mal-hutamah. Narullahil-muqadah. Allati tattali''u ''alal-af''idah. Innaha ''alayhim mu''sadah. Fi ''amadim-mumaddadah."}, "meaning": {"bn": "দুর্ভোগ প্রত্যেক এমন ব্যক্তির জন্য, যে সামনে-পেছনে মানুষের নিন্দা করে; যে সম্পদ জমা করে আর বারবার গুনে রাখে। সে মনে করে তার সম্পদ তাকে চিরকাল বাঁচিয়ে রাখবে। কখনো নয়! তাকে অবশ্যই \"হুতামা\"য় নিক্ষেপ করা হবে। আপনি কি জানেন হুতামা কী? তা আল্লাহর প্রজ্বলিত আগুন, যা হৃদয় পর্যন্ত পৌঁছে যায়। নিশ্চয়ই তা তাদের উপর ঘিরে বন্ধ করে দেওয়া হবে — লম্বা লম্বা স্তম্ভে।", "en": "Woe to every slanderer and backbiter, who gathers wealth and keeps counting it, thinking his wealth will make him live forever. No! He will surely be thrown into the Crusher. And what will make you know what the Crusher is? It is the kindled Fire of Allah, which rises over the hearts. It will be closed over them, in extended columns."}, "ref": {"bn": "সূরা হুমাযাহ ১০৪:১–৯", "en": "Al-Humazah 104:1–9"}}, {"type": "arabic", "label": {"bn": "সূরা ফিল", "en": "Surah Al-Fil"}, "ar": "أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَابِ الْفِيلِ ﴿١﴾ أَلَمْ يَجْعَلْ كَيْدَهُمْ فِي تَضْلِيلٍ ﴿٢﴾ وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ ﴿٣﴾ تَرْمِيهِمْ بِحِجَارَةٍ مِنْ سِجِّيلٍ ﴿٤﴾ فَجَعَلَهُمْ كَعَصْفٍ مَأْكُولٍ ﴿٥﴾", "pron": {"bn": "আলাম তারা কাইফা ফাআলা রাব্বুকা বিআসহাবিল ফিল। আলাম ইয়াজআল কাইদাহুম ফি তাদলিল। ওয়া আরসালা আলাইহিম তাইরান আবাবিল। তারমিহিম বিহিজারাতিম মিন সিজ্জিল। ফাজাআলাহুম কাআসফিম মা''কুল।", "en": "Alam tara kayfa fa''ala rabbuka bi-ashabil-fil. Alam yaj''al kaydahum fi tadlil. Wa arsala ''alayhim tayran ababil. Tarmihim bihijaratim min sijjil. Faja''alahum ka''asfim ma''kul."}, "meaning": {"bn": "আপনি কি দেখেননি, আপনার রব হাতিওয়ালাদের সাথে কী করেছিলেন? তিনি কি তাদের চক্রান্ত ব্যর্থ করে দেননি? তিনি তাদের উপর ঝাঁকে ঝাঁকে পাখি পাঠালেন, যারা তাদের উপর পোড়ামাটির পাথর ছুড়ছিল। ফলে তিনি তাদের করে দিলেন (পশুর) চিবানো ভুসির মতো।", "en": "Have you not seen how your Lord dealt with the people of the elephant? Did He not make their plan go astray? He sent against them birds in flocks, pelting them with stones of baked clay, and made them like chewed-up straw."}, "ref": {"bn": "সূরা ফিল ১০৫:১–৫", "en": "Al-Fil 105:1–5"}}, {"type": "arabic", "label": {"bn": "সূরা কুরাইশ", "en": "Surah Quraysh"}, "ar": "لِإِيلَافِ قُرَيْشٍ ﴿١﴾ إِيلَافِهِمْ رِحْلَةَ الشِّتَاءِ وَالصَّيْفِ ﴿٢﴾ فَلْيَعْبُدُوا رَبَّ هَٰذَا الْبَيْتِ ﴿٣﴾ الَّذِي أَطْعَمَهُمْ مِنْ جُوعٍ وَآمَنَهُمْ مِنْ خَوْفٍ ﴿٤﴾", "pron": {"bn": "লিঈলাফি কুরাইশ। ঈলাফিহিম রিহলাতাশ শিতায়ি ওয়াস সাইফ। ফালইয়া''বুদু রাব্বা হাযাল বাইত। আল্লাযি আত''আমাহুম মিন জু'', ওয়া আমানাহুম মিন খাওফ।", "en": "Li-ilafi Quraysh. Ilafihim rihlatash-shita''i was-sayf. Falya''budu rabba hadhal-bayt. Alladhi at''amahum min ju'', wa amanahum min khawf."}, "meaning": {"bn": "কুরাইশের অভ্যস্ততার জন্য — শীত ও গ্রীষ্মের সফরে তাদের অভ্যস্ততার জন্য — তারা যেন এই ঘরের (কাবার) রবের ইবাদত করে, যিনি তাদের ক্ষুধায় খাবার দিয়েছেন এবং ভয় থেকে নিরাপদ রেখেছেন।", "en": "For the security of Quraysh, their security in the journeys of winter and summer, let them worship the Lord of this House, who fed them against hunger and made them safe from fear."}, "ref": {"bn": "সূরা কুরাইশ ১০৬:১–৪", "en": "Quraysh 106:1–4"}}, {"type": "arabic", "label": {"bn": "সূরা মাউন", "en": "Surah Al-Ma''un"}, "ar": "أَرَأَيْتَ الَّذِي يُكَذِّبُ بِالدِّينِ ﴿١﴾ فَذَٰلِكَ الَّذِي يَدُعُّ الْيَتِيمَ ﴿٢﴾ وَلَا يَحُضُّ عَلَىٰ طَعَامِ الْمِسْكِينِ ﴿٣﴾ فَوَيْلٌ لِلْمُصَلِّينَ ﴿٤﴾ الَّذِينَ هُمْ عَنْ صَلَاتِهِمْ سَاهُونَ ﴿٥﴾ الَّذِينَ هُمْ يُرَاءُونَ ﴿٦﴾ وَيَمْنَعُونَ الْمَاعُونَ ﴿٧﴾", "pron": {"bn": "আরাআইতাল্লাযি ইউকাযযিবু বিদ্দিন। ফাযালিকাল্লাযি ইয়াদু''উল ইয়াতিম। ওয়ালা ইয়াহুদ্দু আলা তাআমিল মিসকিন। ফাওয়াইলুল লিল মুসাল্লিন। আল্লাযিনা হুম আন সালাতিহিম সাহুন। আল্লাযিনা হুম ইউরাউন। ওয়া ইয়ামনাউনাল মাউন।", "en": "Ara''aytal-ladhi yukadhdhibu bid-din. Fadhalikal-ladhi yadu''''ul-yatim. Wa la yahuddu ''ala ta''amil-miskin. Fawaylul-lil-musallin. Alladhina hum ''an salatihim sahun. Alladhina hum yura''un. Wa yamna''unal-ma''un."}, "meaning": {"bn": "আপনি কি তাকে দেখেছেন, যে প্রতিদান দিবসকে অস্বীকার করে? সে-ই তো এতিমকে রূঢ়ভাবে তাড়িয়ে দেয় এবং মিসকিনকে খাবার দিতে উৎসাহ দেয় না। অতএব দুর্ভোগ সেই নামাজিদের জন্য, যারা নিজেদের নামাজের ব্যাপারে উদাসীন, যারা লোক দেখানোর জন্য কাজ করে, এবং ছোটখাটো প্রয়োজনীয় জিনিস দিতেও নিষেধ করে।", "en": "Have you seen the one who denies the Judgement? That is the one who pushes away the orphan and does not urge the feeding of the poor. So woe to those who pray, who are heedless of their prayer, who only show off, and who withhold small kindnesses."}, "ref": {"bn": "সূরা মাউন ১০৭:১–৭", "en": "Al-Ma''un 107:1–7"}}, {"type": "arabic", "label": {"bn": "সূরা কাওসার", "en": "Surah Al-Kawthar"}, "ar": "إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ﴿١﴾ فَصَلِّ لِرَبِّكَ وَانْحَرْ ﴿٢﴾ إِنَّ شَانِئَكَ هُوَ الْأَبْتَرُ ﴿٣﴾", "pron": {"bn": "ইন্না আ''তাইনাকাল কাওসার। ফাসাল্লি লিরাব্বিকা ওয়ানহার। ইন্না শানিআকা হুয়াল আবতার।", "en": "Inna a''taynakal-kawthar. Fasalli lirabbika wanhar. Inna shani''aka huwal-abtar."}, "meaning": {"bn": "নিশ্চয়ই আমি আপনাকে কাওসার দান করেছি। অতএব আপনার রবের উদ্দেশে নামাজ পড়ুন এবং কুরবানি করুন। নিশ্চয়ই আপনার শত্রুই শিকড়কাটা (নির্বংশ)।", "en": "Indeed, We have given you al-Kawthar. So pray to your Lord and sacrifice. Indeed, it is your enemy who is cut off."}, "ref": {"bn": "সূরা কাওসার ১০৮:১–৩", "en": "Al-Kawthar 108:1–3"}}, {"type": "note", "tone": "tip", "text": {"bn": "উচ্চারণ শুধু সহায়ক। সঠিক মাখরাজ ও তাজবিদসহ তিলাওয়াত একজন শিক্ষকের কাছে শুনে শুনে শিখুন — এই অ্যাপের কুরআন অংশে তিলাওয়াত শুনেও অনুশীলন করতে পারেন।", "en": "Transliteration is only an aid. Learn proper articulation and tajwid by listening to a teacher; you can also practise with the recitations in the Quran section of this app."}}]', 'in_review', 80 FROM is_guide_topics WHERE slug = 'salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'bd79a8c8-4be8-5306-ac5c-e12151ff7ab7', id, 'short-surahs-kafirun-to-nas', '{"bn": "নামাজের ছোট সূরা (২): কাফিরুন থেকে নাস", "en": "Short Surahs for Salah (2): Al-Kafirun to An-Nas"}', '{"bn": "কুরআনের শেষ ছয়টি সূরা — আরবি, উচ্চারণ ও অর্থসহ, সাথে সহিহ হাদিসে বর্ণিত কিছু ফজিলত।", "en": "The last six surahs of the Quran with Arabic, pronunciation and meaning, plus some virtues from authentic hadith."}', 'basic', '[{"type": "arabic", "label": {"bn": "সূরা কাফিরুন", "en": "Surah Al-Kafirun"}, "ar": "قُلْ يَا أَيُّهَا الْكَافِرُونَ ﴿١﴾ لَا أَعْبُدُ مَا تَعْبُدُونَ ﴿٢﴾ وَلَا أَنْتُمْ عَابِدُونَ مَا أَعْبُدُ ﴿٣﴾ وَلَا أَنَا عَابِدٌ مَا عَبَدْتُمْ ﴿٤﴾ وَلَا أَنْتُمْ عَابِدُونَ مَا أَعْبُدُ ﴿٥﴾ لَكُمْ دِينُكُمْ وَلِيَ دِينِ ﴿٦﴾", "pron": {"bn": "কুল ইয়া আইয়্যুহাল কাফিরুন। লা আ''বুদু মা তা''বুদুন। ওয়ালা আনতুম আবিদুনা মা আ''বুদ। ওয়ালা আনা আবিদুম মা আবাদতুম। ওয়ালা আনতুম আবিদুনা মা আ''বুদ। লাকুম দিনুকুম ওয়ালিয়া দিন।", "en": "Qul ya ayyuhal-kafirun. La a''budu ma ta''budun. Wa la antum ''abiduna ma a''bud. Wa la ana ''abidum ma ''abadtum. Wa la antum ''abiduna ma a''bud. Lakum dinukum wa liya din."}, "meaning": {"bn": "বলুন, হে কাফিররা! তোমরা যার ইবাদত করো, আমি তার ইবাদত করি না। আর আমি যাঁর ইবাদত করি, তোমরা তাঁর ইবাদতকারী নও। আর তোমরা যার ইবাদত করেছ, আমি তার ইবাদতকারী হব না। আর আমি যাঁর ইবাদত করি, তোমরা তাঁর ইবাদতকারী নও। তোমাদের জন্য তোমাদের দ্বীন, আর আমার জন্য আমার দ্বীন।", "en": "Say: O disbelievers, I do not worship what you worship, nor do you worship what I worship. Nor will I worship what you have worshipped, nor will you worship what I worship. To you your religion, and to me mine."}, "ref": {"bn": "সূরা কাফিরুন ১০৯:১–৬", "en": "Al-Kafirun 109:1–6"}}, {"type": "note", "tone": "info", "text": {"bn": "রাসুলুল্লাহ ﷺ ফজরের দুই রাকাত সুন্নতে সূরা কাফিরুন ও সূরা ইখলাস পড়তেন (সহিহ মুসলিম ৭২৬)।", "en": "The Prophet ﷺ recited Al-Kafirun and Al-Ikhlas in the two sunnah rakats of Fajr (Sahih Muslim 726)."}}, {"type": "arabic", "label": {"bn": "সূরা নাসর", "en": "Surah An-Nasr"}, "ar": "إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ ﴿١﴾ وَرَأَيْتَ النَّاسَ يَدْخُلُونَ فِي دِينِ اللَّهِ أَفْوَاجًا ﴿٢﴾ فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُ ۚ إِنَّهُ كَانَ تَوَّابًا ﴿٣﴾", "pron": {"bn": "ইযা জাআ নাসরুল্লাহি ওয়াল ফাতহ। ওয়া রাআইতান নাসা ইয়াদখুলুনা ফি দিনিল্লাহি আফওয়াজা। ফাসাব্বিহ বিহামদি রাব্বিকা ওয়াসতাগফিরহ, ইন্নাহু কানা তাওয়াবা।", "en": "Idha ja''a nasrullahi wal-fath. Wa ra''aytan-nasa yadkhuluna fi dinillahi afwaja. Fasabbih bihamdi rabbika wastaghfirh, innahu kana tawwaba."}, "meaning": {"bn": "যখন আল্লাহর সাহায্য ও বিজয় আসবে, এবং আপনি দেখবেন মানুষ দলে দলে আল্লাহর দ্বীনে প্রবেশ করছে, তখন আপনার রবের প্রশংসাসহ তাঁর পবিত্রতা ঘোষণা করুন এবং তাঁর কাছে ক্ষমা চান। নিশ্চয়ই তিনি তওবা কবুলকারী।", "en": "When the help of Allah and victory come, and you see people entering Allah''s religion in crowds, then glorify your Lord with praise and seek His forgiveness. Indeed, He ever accepts repentance."}, "ref": {"bn": "সূরা নাসর ১১০:১–৩", "en": "An-Nasr 110:1–3"}}, {"type": "arabic", "label": {"bn": "সূরা লাহাব (মাসাদ)", "en": "Surah Al-Masad"}, "ar": "تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ ﴿١﴾ مَا أَغْنَىٰ عَنْهُ مَالُهُ وَمَا كَسَبَ ﴿٢﴾ سَيَصْلَىٰ نَارًا ذَاتَ لَهَبٍ ﴿٣﴾ وَامْرَأَتُهُ حَمَّالَةَ الْحَطَبِ ﴿٤﴾ فِي جِيدِهَا حَبْلٌ مِنْ مَسَدٍ ﴿٥﴾", "pron": {"bn": "তাব্বাত ইয়াদা আবি লাহাবিও ওয়া তাব্ব। মা আগনা আনহু মালুহু ওয়ামা কাসাব। সাইয়াসলা নারান যাতা লাহাব। ওয়ামরাআতুহু হাম্মালাতাল হাতাব। ফি জিদিহা হাবলুম মিম মাসাদ।", "en": "Tabbat yada Abi Lahabin wa tabb. Ma aghna ''anhu maluhu wa ma kasab. Sayasla naran dhata lahab. Wamra''atuhu hammalatal-hatab. Fi jidiha hablum mim masad."}, "meaning": {"bn": "আবু লাহাবের দুই হাত ধ্বংস হোক, এবং সে নিজেও ধ্বংস হয়েছে। তার সম্পদ ও তার উপার্জন তার কোনো কাজে আসেনি। শীঘ্রই সে লেলিহান আগুনে প্রবেশ করবে, এবং তার স্ত্রীও — যে কাঠ বহন করত (কুৎসা ছড়াত)। তার গলায় থাকবে খেজুর-আঁশের পাকানো রশি।", "en": "Perish the hands of Abu Lahab, and perish he! His wealth and what he earned did not avail him. He will burn in a Fire of blazing flame, and his wife too, the carrier of firewood, with a rope of twisted fibre around her neck."}, "ref": {"bn": "সূরা লাহাব (মাসাদ) ১১১:১–৫", "en": "Al-Masad 111:1–5"}}, {"type": "arabic", "label": {"bn": "সূরা ইখলাস", "en": "Surah Al-Ikhlas"}, "ar": "قُلْ هُوَ اللَّهُ أَحَدٌ ﴿١﴾ اللَّهُ الصَّمَدُ ﴿٢﴾ لَمْ يَلِدْ وَلَمْ يُولَدْ ﴿٣﴾ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ ﴿٤﴾", "pron": {"bn": "কুল হুয়াল্লাহু আহাদ। আল্লাহুস সামাদ। লাম ইয়ালিদ ওয়া লাম ইউলাদ। ওয়া লাম ইয়াকুল লাহু কুফুওয়ান আহাদ।", "en": "Qul huwallahu ahad. Allahus-samad. Lam yalid wa lam yulad. Wa lam yakul-lahu kufuwan ahad."}, "meaning": {"bn": "বলুন, তিনিই আল্লাহ, এক ও অদ্বিতীয়। আল্লাহ কারো মুখাপেক্ষী নন, সবাই তাঁর মুখাপেক্ষী। তিনি কাউকে জন্ম দেননি এবং কেউ তাঁকে জন্ম দেয়নি। আর তাঁর সমকক্ষ কেউ নেই।", "en": "Say: He is Allah, the One. Allah, the Self-Sufficient on whom all depend. He neither begets nor was He begotten. And there is none comparable to Him."}, "ref": {"bn": "সূরা ইখলাস ১১২:১–৪", "en": "Al-Ikhlas 112:1–4"}}, {"type": "note", "tone": "info", "text": {"bn": "সূরা ইখলাস কুরআনের এক-তৃতীয়াংশের সমান (সহিহ বুখারি ৫০১৩; সহিহ মুসলিম ৮১১)।", "en": "Surah Al-Ikhlas equals a third of the Quran (Sahih al-Bukhari 5013; Sahih Muslim 811)."}}, {"type": "arabic", "label": {"bn": "সূরা ফালাক", "en": "Surah Al-Falaq"}, "ar": "قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ﴿١﴾ مِنْ شَرِّ مَا خَلَقَ ﴿٢﴾ وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ﴿٣﴾ وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ﴿٤﴾ وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ ﴿٥﴾", "pron": {"bn": "কুল আউযু বিরাব্বিল ফালাক। মিন শাররি মা খালাক। ওয়া মিন শাররি গাসিকিন ইযা ওয়াকাব। ওয়া মিন শাররিন নাফফাসাতি ফিল উকাদ। ওয়া মিন শাররি হাসিদিন ইযা হাসাদ।", "en": "Qul a''udhu birabbil-falaq. Min sharri ma khalaq. Wa min sharri ghasiqin idha waqab. Wa min sharrin-naffathati fil-''uqad. Wa min sharri hasidin idha hasad."}, "meaning": {"bn": "বলুন, আমি আশ্রয় চাই ভোরের রবের কাছে — তিনি যা সৃষ্টি করেছেন তার অনিষ্ট থেকে, অন্ধকার রাতের অনিষ্ট থেকে যখন তা ছেয়ে যায়, গিঁটে ফুঁ দেওয়া জাদুকারিণীদের অনিষ্ট থেকে, এবং হিংসুকের অনিষ্ট থেকে যখন সে হিংসা করে।", "en": "Say: I seek refuge with the Lord of daybreak, from the evil of what He created, from the evil of darkness when it settles, from the evil of those who blow on knots, and from the evil of an envier when he envies."}, "ref": {"bn": "সূরা ফালাক ১১৩:১–৫", "en": "Al-Falaq 113:1–5"}}, {"type": "arabic", "label": {"bn": "সূরা নাস", "en": "Surah An-Nas"}, "ar": "قُلْ أَعُوذُ بِرَبِّ النَّاسِ ﴿١﴾ مَلِكِ النَّاسِ ﴿٢﴾ إِلَٰهِ النَّاسِ ﴿٣﴾ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ﴿٤﴾ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ﴿٥﴾ مِنَ الْجِنَّةِ وَالنَّاسِ ﴿٦﴾", "pron": {"bn": "কুল আউযু বিরাব্বিন নাস। মালিকিন নাস। ইলাহিন নাস। মিন শাররিল ওয়াসওয়াসিল খান্নাস। আল্লাযি ইউওয়াসউইসু ফি সুদুরিন নাস। মিনাল জিন্নাতি ওয়ান নাস।", "en": "Qul a''udhu birabbin-nas. Malikin-nas. Ilahin-nas. Min sharril-waswasil-khannas. Alladhi yuwaswisu fi sudurin-nas. Minal-jinnati wan-nas."}, "meaning": {"bn": "বলুন, আমি আশ্রয় চাই মানুষের রবের কাছে, মানুষের অধিপতির কাছে, মানুষের ইলাহের কাছে — সেই কুমন্ত্রণাদাতার অনিষ্ট থেকে, যে (আল্লাহর স্মরণে) পিছিয়ে যায়, যে মানুষের অন্তরে কুমন্ত্রণা দেয় — জিনদের মধ্য থেকে হোক বা মানুষের মধ্য থেকে।", "en": "Say: I seek refuge with the Lord of mankind, the King of mankind, the God of mankind, from the evil of the whisperer who withdraws, who whispers into the hearts of mankind, from among the jinn and mankind."}, "ref": {"bn": "সূরা নাস ১১৪:১–৬", "en": "An-Nas 114:1–6"}}, {"type": "note", "tone": "info", "text": {"bn": "সূরা ফালাক ও নাস সম্পর্কে রাসুলুল্লাহ ﷺ বলেছেন, এমন আয়াত আর কখনো দেখা যায়নি (সহিহ মুসলিম ৮১৪)। প্রতি নামাজের পর এই সূরাগুলো (মুআওয়িযাত) পড়ার কথাও হাদিসে আছে (সুনান আবু দাউদ ১৫২৩)।", "en": "The Prophet ﷺ said of Al-Falaq and An-Nas that verses like them had never been seen (Sahih Muslim 814). Reciting these protective surahs after every prayer is also in the hadith (Sunan Abi Dawud 1523)."}}]', 'in_review', 90 FROM is_guide_topics WHERE slug = 'salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'fffa2555-7286-546d-9016-2b51e73e245a', id, 'salah-after-dhikr', '{"bn": "নামাজের পরের জিকির ও দোয়া", "en": "Dhikr and Duas after Salah"}', '{"bn": "সালাম ফেরানোর পর রাসুলুল্লাহ ﷺ যেসব জিকির ও দোয়া পড়তেন — ইস্তিগফার, আয়াতুল কুরসি, তাসবিহ ইত্যাদি।", "en": "The dhikr and duas the Prophet ﷺ said after the salam: istighfar, Ayat al-Kursi, tasbih and more."}', 'basic', '[{"type": "text", "text": {"bn": "ফরজ নামাজের সালাম ফেরানোর পর কিছুক্ষণ বসে আল্লাহর জিকির করা সুন্নত। নিচের জিকিরগুলো সহিহ হাদিস থেকে নেওয়া; সবগুলো একসাথে না পারলে যতটুকু পারেন নিয়মিত পড়ুন।", "en": "After the salam of a fard prayer it is sunnah to sit a little and remember Allah. The dhikr below come from authentic hadith; if you cannot do them all, keep regularly to what you can."}}, {"type": "arabic", "label": {"bn": "ইস্তিগফার — ৩ বার", "en": "Istighfar: 3 times"}, "ar": "أَسْتَغْفِرُ اللَّهَ", "pron": {"bn": "আসতাগফিরুল্লাহ", "en": "Astaghfirullah"}, "meaning": {"bn": "আমি আল্লাহর কাছে ক্ষমা চাই।", "en": "I seek Allah''s forgiveness."}, "ref": {"bn": "সহিহ মুসলিম ৫৯১", "en": "Sahih Muslim 591"}}, {"type": "arabic", "label": {"bn": "ইস্তিগফারের পর", "en": "After the istighfar"}, "ar": "اللَّهُمَّ أَنْتَ السَّلَامُ، وَمِنْكَ السَّلَامُ، تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ", "pron": {"bn": "আল্লাহুম্মা আনতাস সালাম, ওয়া মিনকাস সালাম, তাবারাকতা ইয়া যাল জালালি ওয়াল ইকরাম।", "en": "Allahumma antas-salam, wa minkas-salam, tabarakta ya dhal-jalali wal-ikram."}, "meaning": {"bn": "হে আল্লাহ! আপনিই শান্তি, আপনার কাছ থেকেই শান্তি। হে মহিমা ও সম্মানের অধিকারী! আপনি বরকতময়।", "en": "O Allah, You are Peace and from You is peace. Blessed are You, O Possessor of majesty and honour."}, "ref": {"bn": "সহিহ মুসলিম ৫৯১", "en": "Sahih Muslim 591"}}, {"type": "arabic", "ar": "لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ، اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ", "pron": {"bn": "লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারিকা লাহু, লাহুল মুলকু ওয়া লাহুল হামদু, ওয়া হুয়া আলা কুল্লি শাইয়িন কাদির। আল্লাহুম্মা লা মানিআ লিমা আ''তাইতা, ওয়ালা মু''তিয়া লিমা মানা''তা, ওয়ালা ইয়ানফাউ যাল জাদ্দি মিনকাল জাদ্দ।", "en": "La ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamdu wa huwa ''ala kulli shay''in qadir. Allahumma la mani''a lima a''tayta, wa la mu''tiya lima mana''ta, wa la yanfa''u dhal-jaddi minkal-jadd."}, "meaning": {"bn": "আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি এক, তাঁর কোনো শরিক নেই; রাজত্ব তাঁরই, প্রশংসাও তাঁরই, তিনি সবকিছুর উপর ক্ষমতাবান। হে আল্লাহ! আপনি যা দেন তা কেউ আটকাতে পারে না, আর আপনি যা আটকান তা কেউ দিতে পারে না; আর কোনো সম্পদশালীর সম্পদ আপনার কাছে তার কোনো উপকারে আসে না।", "en": "There is no god but Allah alone, with no partner; His is the dominion and His the praise, and He has power over all things. O Allah, none can withhold what You give, none can give what You withhold, and the wealth of the wealthy is of no avail against You."}, "ref": {"bn": "সহিহ বুখারি ৮৪৪; সহিহ মুসলিম ৫৯৩", "en": "Sahih al-Bukhari 844; Sahih Muslim 593"}}, {"type": "heading", "text": {"bn": "তাসবিহ, তাহমিদ ও তাকবির", "en": "Tasbih, tahmid and takbir"}}, {"type": "arabic", "label": {"bn": "৩৩ বার", "en": "33 times"}, "ar": "سُبْحَانَ اللَّهِ", "pron": {"bn": "সুবহানাল্লাহ", "en": "Subhanallah"}, "meaning": {"bn": "আল্লাহ পবিত্র।", "en": "Glory be to Allah."}}, {"type": "arabic", "label": {"bn": "৩৩ বার", "en": "33 times"}, "ar": "الْحَمْدُ لِلَّهِ", "pron": {"bn": "আলহামদুলিল্লাহ", "en": "Alhamdulillah"}, "meaning": {"bn": "সকল প্রশংসা আল্লাহর।", "en": "All praise is for Allah."}}, {"type": "arabic", "label": {"bn": "৩৪ বার", "en": "34 times"}, "ar": "اللَّهُ أَكْبَرُ", "pron": {"bn": "আল্লাহু আকবার", "en": "Allahu akbar"}, "meaning": {"bn": "আল্লাহ সবচেয়ে বড়।", "en": "Allah is the Greatest."}, "ref": {"bn": "সহিহ মুসলিম ৫৯৬", "en": "Sahih Muslim 596"}}, {"type": "note", "tone": "info", "text": {"bn": "আরেকটি সহিহ পদ্ধতি: সুবহানাল্লাহ, আলহামদুলিল্লাহ ও আল্লাহু আকবার ৩৩ বার করে, তারপর একবার \"লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারিকা লাহু, লাহুল মুলকু ওয়া লাহুল হামদু, ওয়া হুয়া আলা কুল্লি শাইয়িন কাদির\" বলে ১০০ পূর্ণ করা। হাদিসে আছে, এতে সমুদ্রের ফেনার সমান গুনাহও মাফ হয় (সহিহ মুসলিম ৫৯৭)।", "en": "Another authentic way: 33 each of Subhanallah, Alhamdulillah and Allahu akbar, then completing 100 with \"La ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamdu wa huwa ''ala kulli shay''in qadir\". The hadith says sins are forgiven even if like the foam of the sea (Sahih Muslim 597)."}}, {"type": "heading", "text": {"bn": "আয়াতুল কুরসি", "en": "Ayat al-Kursi"}}, {"type": "arabic", "label": {"bn": "আয়াতুল কুরসি — প্রতি ফরজ নামাজের পর", "en": "Ayat al-Kursi: after every fard prayer"}, "ar": "اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ", "pron": {"bn": "আল্লাহু লা ইলাহা ইল্লা হুয়াল হাইয়্যুল কাইয়্যুম। লা তা''খুযুহু সিনাতুও ওয়ালা নাওম। লাহু মা ফিস সামাওয়াতি ওয়ামা ফিল আরদ। মান যাল্লাযি ইয়াশফাউ ইনদাহু ইল্লা বিইযনিহ। ইয়া''লামু মা বাইনা আইদিহিম ওয়ামা খালফাহুম। ওয়ালা ইউহিতুনা বিশাইয়িম মিন ইলমিহি ইল্লা বিমা শাআ। ওয়াসিআ কুরসিইয়্যুহুস সামাওয়াতি ওয়াল আরদ। ওয়ালা ইয়াউদুহু হিফযুহুমা, ওয়া হুয়াল আলিইয়্যুল আযিম।", "en": "Allahu la ilaha illa huwal-hayyul-qayyum. La ta''khudhuhu sinatun wa la nawm. Lahu ma fis-samawati wa ma fil-ard. Man dhal-ladhi yashfa''u ''indahu illa bi-idhnih. Ya''lamu ma bayna aydihim wa ma khalfahum. Wa la yuhituna bishay''im min ''ilmihi illa bima sha''. Wasi''a kursiyyuhus-samawati wal-ard. Wa la ya''uduhu hifzuhuma, wa huwal-''aliyyul-''azim."}, "meaning": {"bn": "আল্লাহ, তিনি ছাড়া কোনো ইলাহ নেই; তিনি চিরঞ্জীব, সবকিছুর ধারক। তাঁকে তন্দ্রাও স্পর্শ করে না, নিদ্রাও না। আসমান ও জমিনে যা কিছু আছে সব তাঁরই। কে আছে যে তাঁর অনুমতি ছাড়া তাঁর কাছে সুপারিশ করবে? তাদের সামনে ও পেছনে যা আছে তিনি সব জানেন। তিনি যতটুকু চান, তার বাইরে তাঁর জ্ঞানের কিছুই তারা আয়ত্ত করতে পারে না। তাঁর কুরসি আসমান ও জমিন পরিব্যাপ্ত। এ দুটির রক্ষণাবেক্ষণ তাঁকে ক্লান্ত করে না। তিনি সর্বোচ্চ, মহান।", "en": "Allah: there is no god but Him, the Ever-Living, the Sustainer of all. Neither drowsiness nor sleep overtakes Him. To Him belongs whatever is in the heavens and the earth. Who can intercede with Him except by His permission? He knows what is before them and behind them, and they encompass nothing of His knowledge except what He wills. His Kursi extends over the heavens and the earth, and preserving them does not tire Him. He is the Most High, the Most Great."}, "ref": {"bn": "সূরা বাকারা ২:২৫৫", "en": "Al-Baqarah 2:255"}}, {"type": "ref", "text": {"bn": "প্রতি ফরজ নামাজের পর আয়াতুল কুরসি পড়ার ফজিলত: আবু উমামা (রা.) থেকে বর্ণিত — সুনানে নাসায়ি আল-কুবরা (ইবনে হিব্বান ও অন্যরা সহিহ বলেছেন)", "en": "The virtue of Ayat al-Kursi after every obligatory prayer: narrated by Abu Umamah (RA) in as-Sunan al-Kubra of an-Nasa''i (graded authentic by Ibn Hibban and others)"}, "check": true}, {"type": "heading", "text": {"bn": "আরও কিছু দোয়া", "en": "More duas"}}, {"type": "arabic", "label": {"bn": "প্রতি নামাজের শেষে — মুআয (রা.)-কে শেখানো", "en": "At the end of every prayer: taught to Mu''adh (RA)"}, "ar": "اللَّهُمَّ أَعِنِّي عَلَىٰ ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ", "pron": {"bn": "আল্লাহুম্মা আইন্নি আলা যিকরিকা ওয়া শুকরিকা ওয়া হুসনি ইবাদাতিক।", "en": "Allahumma a''inni ''ala dhikrika wa shukrika wa husni ''ibadatik."}, "meaning": {"bn": "হে আল্লাহ! আপনার জিকির, আপনার শুকরিয়া এবং সুন্দরভাবে আপনার ইবাদত করতে আমাকে সাহায্য করুন।", "en": "O Allah, help me to remember You, to thank You, and to worship You well."}, "ref": {"bn": "সুনান আবু দাউদ ১৫২২", "en": "Sunan Abi Dawud 1522"}}, {"type": "text", "text": {"bn": "প্রতি নামাজের পর সূরা ইখলাস, ফালাক ও নাস (মুআওয়িযাত) পড়ার কথা হাদিসে আছে (সুনান আবু দাউদ ১৫২৩)। সূরাগুলো \"নামাজের ছোট সূরা (২)\" অংশে আরবি ও অর্থসহ দেওয়া আছে।", "en": "Reciting Al-Ikhlas, Al-Falaq and An-Nas after every prayer is in the hadith (Sunan Abi Dawud 1523). They are in \"Short Surahs for Salah (2)\" with Arabic and meaning."}}, {"type": "note", "tone": "info", "text": {"bn": "ফরজ নামাজের পর দোয়া কবুলের আশাব্যঞ্জক সময় বলে হাদিসে এসেছে (সুনান তিরমিযি), তাই নিজের ভাষায় আল্লাহর কাছে চাইতে পারেন। ফরজের পর ইমাম-মুক্তাদি সবাই মিলে নিয়মিত হাত তুলে সম্মিলিত মুনাজাত করা নিয়ে আলেমদের মধ্যে মতপার্থক্য আছে; ব্যক্তিগতভাবে দোয়া করা সবার মতেই জায়েজ।", "en": "The hadith mentions the end of obligatory prayers as a time when dua is hoped to be answered (Jami at-Tirmidhi), so ask Allah in your own words. Scholars differ on a regular collective dua with raised hands by imam and congregation after every fard; individual dua is permitted by all."}, "check": true}]', 'in_review', 100 FROM is_guide_topics WHERE slug = 'salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '97892482-552a-5fa8-b888-3fb2556d4498', id, 'salah-women', '{"bn": "নারীদের নামাজ", "en": "Women''s Salah"}', '{"bn": "নারী-পুরুষের নামাজ মূলত এক; যেসব বিষয়ে পার্থক্য আছে এবং যেসব বিষয়ে আলেমদের মতপার্থক্য — নিরপেক্ষভাবে।", "en": "Men''s and women''s salah are essentially the same; the points that differ, and where scholars hold different views, presented neutrally."}', 'detail', '[{"type": "text", "text": {"bn": "নারী ও পুরুষের নামাজের ফরজ, ওয়াজিব, রাকাত সংখ্যা এবং পড়ার দোয়া-সূরা সব এক। \"দুই রাকাত নামাজ\" অংশে যা আছে, নারীরাও তা-ই পড়বেন। পার্থক্য মূলত সতর ঢাকা ও পর্দা সংক্রান্ত, আর কিছু দাঁড়ানো-বসার ভঙ্গিতে — যেখানে আলেমদের মতপার্থক্য আছে।", "en": "The fard and wajib acts, the number of rakats and the recitations are the same for men and women; women pray what is in \"How to Pray Two Rakats\". The differences concern covering and modesty, and some postures, where scholars differ."}}, {"type": "heading", "text": {"bn": "যেসব বিষয়ে আলেমরা একমত", "en": "Points that are agreed"}}, {"type": "list", "items": [{"bn": "নামাজে নারীর সতর: মুখমণ্ডল ও দুই হাত ছাড়া পুরো শরীর (হানাফি মতে দুই পা-ও সতরের বাইরে)। মাথার চুল ঢাকা জরুরি।", "en": "A woman''s awrah in salah is the whole body except the face and hands (Hanafis also exclude the feet). The hair must be covered."}, {"bn": "নারীদের জন্য ঘরে নামাজ পড়া উত্তম, তবে মসজিদে যাওয়া নিষেধ নয়।", "en": "Praying at home is better for women, but they are not forbidden from the mosque."}, {"bn": "জামাতে নারীদের কাতার পুরুষদের পেছনে।", "en": "In congregation, women''s rows are behind the men''s."}, {"bn": "ইমাম ভুল করলে পুরুষরা \"সুবহানাল্লাহ\" বলবে, নারীরা হাতের উপর হাত মেরে শব্দ করবে।", "en": "To alert the imam to a mistake, men say \"Subhanallah\" and women clap one hand on the other."}, {"bn": "জুমার নামাজ নারীদের উপর ফরজ নয়; তারা ঘরে জোহর পড়বেন (জুমায় অংশ নিলে তা-ও আদায় হয়ে যায়)।", "en": "Jumu''ah is not obligatory for women; they pray Zuhr at home (if they attend Jumu''ah, it counts)."}, {"bn": "হায়েজ-নিফাসের সময় নামাজ মাফ, পরে কাজা করতে হয় না।", "en": "Prayer is excused during menses and post-natal bleeding and is not made up."}]}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ ৬৪১ (ওড়না ছাড়া প্রাপ্তবয়স্ক নারীর নামাজ কবুল হয় না); সুনান আবু দাউদ ৫৬৭ ও সহিহ বুখারি ৯০০ (মসজিদে যাওয়া); সহিহ মুসলিম ৪৪০ (কাতার); সহিহ বুখারি ১২০৩ (তাসবিহ ও হাততালি); সুনান আবু দাউদ ১০৬৭ (জুমা)", "en": "Sunan Abi Dawud 641 (no prayer of an adult woman without a head covering); Sunan Abi Dawud 567 and Sahih al-Bukhari 900 (the mosque); Sahih Muslim 440 (rows); Sahih al-Bukhari 1203 (tasbih and clapping); Sunan Abi Dawud 1067 (Jumu''ah)"}}, {"type": "differ", "title": {"bn": "নামাজের ভঙ্গিতে নারী-পুরুষের পার্থক্য আছে কি?", "en": "Do women''s postures in salah differ from men''s?"}, "views": [{"label": {"bn": "হানাফি (এবং চার মাযহাবের অনেক ফকিহ — বিস্তারিত ভিন্নতাসহ)", "en": "Hanafi (and many jurists of the four madhhabs, with differing details)"}, "text": {"bn": "নারীরা পর্দা ও সংযমের জন্য শরীর গুটিয়ে নামাজ পড়বেন। হানাফি পদ্ধতি: তাকবিরে তাহরিমায় হাত কাঁধ পর্যন্ত ওঠানো; বুকের উপর হাত রাখা; রুকুতে সামান্য ঝোঁকা, আঙুল মিলিয়ে রাখা; সিজদায় পেট উরুর সাথে ও বাহু পাঁজরের সাথে মিলিয়ে, কনুইসহ হাত মাটিতে বিছিয়ে জড়োসড়ো হয়ে থাকা; বৈঠকে দুই পা ডান দিকে বের করে বাম নিতম্বের উপর বসা।", "en": "Women pray in a more compact way for modesty. The Hanafi method: raising the hands to the shoulders at the opening takbir; placing the hands on the chest; bending less in ruku with fingers together; in sujud keeping the belly against the thighs and the arms against the sides, forearms on the ground, body drawn together; in the sitting, both feet out to the right, sitting on the left hip."}, "evidence": {"bn": "রাসুলুল্লাহ ﷺ নামাজরত দুই নারীকে সিজদায় শরীর মাটির সাথে মিলিয়ে রাখতে বলেছেন — ইয়াযিদ ইবনে আবি হাবিবের মুরসাল বর্ণনা (মারাসিলে আবু দাউদ; সুনানুল কুবরা, বায়হাকি); আলি ও ইবনে আব্বাস (রা.)-সহ কয়েকজন সাহাবি ও তাবেয়ির বক্তব্য (মুসান্নাফ ইবনে আবি শাইবা); নারীর জন্য পর্দার সাধারণ নীতি, যাতে সবাই একমত।", "en": "The Prophet ﷺ told two women praying to draw their bodies to the ground in sujud: a mursal report of Yazid ibn Abi Habib (Marasil Abi Dawud; al-Bayhaqi''s as-Sunan al-Kubra); statements of Ali, Ibn Abbas (RA) and other early authorities (Musannaf Ibn Abi Shaybah); and the agreed general principle of modesty for women."}}, {"label": {"bn": "অনেক মুহাদ্দিস ও আহলে হাদিস আলেম", "en": "Many hadith scholars and Ahl al-Hadith scholars"}, "text": {"bn": "সতর ও আওয়াজ সংক্রান্ত প্রমাণিত পার্থক্য ছাড়া নারী-পুরুষের নামাজের ভঙ্গি একই; নারীরাও পুরুষদের মতো হাত ওঠাবেন, বাঁধবেন, রুকু-সিজদা করবেন ও বসবেন।", "en": "Apart from the established differences in covering and voice, the postures are the same: women raise and place the hands, bow, prostrate and sit as men do."}, "evidence": {"bn": "\"তোমরা আমাকে যেভাবে নামাজ পড়তে দেখেছ, সেভাবে পড়ো\" — সহিহ বুখারি ৬৩১, যা নারী-পুরুষ সবার জন্য সাধারণ; উম্মুদ দারদা (রহ.) পুরুষের মতো বসতেন, আর তিনি ফকিহ ছিলেন — সহিহ বুখারি (তাশাহহুদে বসার অধ্যায়ে মুআল্লাক বর্ণনা); তারা পার্থক্যের বর্ণনাগুলোকে মুরসাল বা দুর্বল মনে করেন।", "en": "\"Pray as you have seen me praying\" (Sahih al-Bukhari 631), addressed to all; Umm ad-Darda, a jurist, sat in prayer as men sit (Sahih al-Bukhari, an unconnected report in the chapter on sitting in the tashahhud); they regard the reports of difference as mursal or weak."}}], "check": true}, {"type": "note", "tone": "tip", "text": {"bn": "যে মতই অনুসরণ করুন, নামাজ সহিহ হবে। আপনার আস্থাভাজন আলেম যেভাবে শেখান সেভাবে পড়ুন, এবং এ নিয়ে অন্যের সাথে বিবাদে জড়াবেন না। মনোযোগ, সময়মতো আদায় ও সতর ঠিক রাখা — এগুলোই বেশি গুরুত্বপূর্ণ।", "en": "Whichever view you follow, your prayer is valid. Pray as your trusted scholar teaches and do not quarrel with others over it. Focus, praying on time and proper covering matter far more."}}, {"type": "note", "tone": "info", "text": {"bn": "যেখানে গায়রে মাহরাম পুরুষ শুনতে পায়, সেখানে নারীরা কিরাত শব্দ করে পড়বেন না — এটাই অধিকাংশ আলেমের মত। নারীরা নারীদের জামাত করলে ইমাম সামনে না দাঁড়িয়ে প্রথম কাতারের মাঝখানে দাঁড়াবেন।", "en": "Women do not recite aloud where non-mahram men can hear; this is the view of most scholars. When women pray in a women-only congregation, the woman leading stands in the middle of the first row rather than in front."}}]', 'in_review', 110 FROM is_guide_topics WHERE slug = 'salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '45e3cce3-bacf-5944-baa8-990c74627445', id, 'salah-points-of-difference', '{"bn": "নামাজে মতপার্থক্যের বিষয়গুলো", "en": "Points of Difference in Salah"}', '{"bn": "হাত ওঠানো (রাফয়ে ইয়াদাইন), হাত বাঁধার জায়গা, আমিন জোরে না আস্তে, ইমামের পেছনে ফাতিহা পড়া ও সিজদায় যাওয়ার ভঙ্গি — প্রতিটি মত দলিলসহ।", "en": "Raising the hands, where to place them, Amin aloud or quietly, reciting Al-Fatihah behind the imam, and how to go down to sujud: each view with its evidence."}', 'detail', '[{"type": "text", "text": {"bn": "নিচের বিষয়গুলোতে প্রতিটি মতের পক্ষেই হাদিস ও সাহাবিদের আমল রয়েছে। এগুলো সুন্নাহর ভেতরের পার্থক্য — কোনো মত অনুসরণ করলে নামাজ বাতিল হয় না। তাই এগুলোকে বিভেদের কারণ বানানো উচিত নয়।", "en": "On each of the points below, every view rests on hadith and the practice of Companions. These are differences within the Sunnah; following any of them does not invalidate the prayer, and they should never become a cause of division."}}, {"type": "differ", "title": {"bn": "রাফয়ে ইয়াদাইন: রুকুর আগে-পরে হাত ওঠানো", "en": "Raf'' al-yadayn: raising the hands before and after ruku"}, "views": [{"label": {"bn": "হানাফি ও মালেকি (প্রসিদ্ধ মত)", "en": "Hanafi and Maliki (well-known view)"}, "text": {"bn": "শুধু তাকবিরে তাহরিমার সময় হাত ওঠানো হবে; রুকুতে যাওয়া বা রুকু থেকে ওঠার সময় নয়।", "en": "The hands are raised only at the opening takbir, not when going into or rising from ruku."}, "evidence": {"bn": "ইবনে মাসউদ (রা.) রাসুলুল্লাহ ﷺ-এর নামাজ দেখিয়ে শুধু প্রথমবার হাত তুলেছেন — সুনান তিরমিযি ২৫৭ (তিরমিযি হাসান বলেছেন); সুনান আবু দাউদ ৭৪৮; বারা ইবনে আযিব (রা.)-এর বর্ণনা — সুনান আবু দাউদ ৭৪৯; কুফার সাহাবিদের আমল।", "en": "Ibn Mas''ud (RA) demonstrated the Prophet''s prayer and raised his hands only the first time (Jami at-Tirmidhi 257, graded hasan by at-Tirmidhi; Sunan Abi Dawud 748); the report of al-Bara'' ibn ''Azib (RA) (Sunan Abi Dawud 749); the practice of the Companions in Kufa."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি (এবং আহলে হাদিস)", "en": "Shafi''i and Hanbali (and Ahl al-Hadith)"}, "text": {"bn": "তাকবিরে তাহরিমা ছাড়াও রুকুতে যাওয়ার সময় ও রুকু থেকে ওঠার সময় হাত ওঠানো সুন্নত; অনেকের মতে দ্বিতীয় রাকাত শেষে তৃতীয় রাকাতের জন্য দাঁড়ানোর সময়ও।", "en": "Besides the opening takbir, the hands are raised when going into ruku and when rising from it; many add when standing up for the third rakat."}, "evidence": {"bn": "ইবনে উমর (রা.): রাসুলুল্লাহ ﷺ নামাজ শুরু, রুকুতে যাওয়া ও রুকু থেকে ওঠার সময় কাঁধ পর্যন্ত হাত তুলতেন — সহিহ বুখারি ৭৩৫; সহিহ মুসলিম ৩৯০; দুই রাকাতের পর দাঁড়ানোর সময়ও — সহিহ বুখারি ৭৩৯।", "en": "Ibn Umar (RA): the Prophet ﷺ raised his hands to his shoulders when starting the prayer, going into ruku and rising from it (Sahih al-Bukhari 735; Sahih Muslim 390), and also on standing after two rakats (Sahih al-Bukhari 739)."}}]}, {"type": "differ", "title": {"bn": "হাত কোথায় বাঁধবেন", "en": "Where to place the hands"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "পুরুষরা ডান হাত বাম হাতের উপর রেখে নাভির নিচে বাঁধবেন; নারীরা বুকের উপর।", "en": "Men place the right hand over the left below the navel; women on the chest."}, "evidence": {"bn": "আলি (রা.)-এর বক্তব্য: \"নামাজে হাতের উপর হাত নাভির নিচে রাখা সুন্নত\" — সুনান আবু দাউদ ৭৫৬ (এর সনদ দুর্বল বলা হয়েছে); মুসান্নাফ ইবনে আবি শাইবায় তাবেয়িদের বর্ণনা। হাম্বলি মাযহাবের প্রসিদ্ধ মতও নাভির নিচে।", "en": "Ali (RA): \"It is sunnah to place hand on hand below the navel in prayer\" (Sunan Abi Dawud 756, whose chain has been called weak); reports from the Successors in Musannaf Ibn Abi Shaybah. The well-known Hanbali view is also below the navel."}}, {"label": {"bn": "শাফেয়ি ও কিছু মুহাদ্দিস", "en": "Shafi''i and some hadith scholars"}, "text": {"bn": "বুকের নিচে, নাভির উপরে (শাফেয়ি); কিছু মুহাদ্দিসের মতে বুকের উপর।", "en": "Below the chest and above the navel (Shafi''i); some hadith scholars say on the chest."}, "evidence": {"bn": "ওয়ায়েল ইবনে হুজর (রা.): রাসুলুল্লাহ ﷺ বুকের উপর হাত রেখেছেন — সহিহ ইবনে খুযাইমা ৪৭৯; হুলব আত-তায়ি (রা.)-এর বর্ণনা — মুসনাদে আহমাদ।", "en": "Wa''il ibn Hujr (RA): the Prophet ﷺ placed his hands on his chest (Sahih Ibn Khuzaymah 479); the report of Hulb at-Ta''i (RA) (Musnad Ahmad)."}}, {"label": {"bn": "মালেকি (প্রসিদ্ধ মত)", "en": "Maliki (well-known view)"}, "text": {"bn": "ফরজ নামাজে হাত না বেঁধে দুই পাশে ছেড়ে রাখা (সাদল); নফলে বাঁধা যায়।", "en": "In fard prayers the hands are left at the sides (sadl); they may be folded in voluntary prayers."}, "evidence": {"bn": "ইমাম মালিকের সময়ে মদিনাবাসীর আমল বলে মালেকিরা উল্লেখ করেন (আল-মুদাওয়ানা)।", "en": "Malikis cite the practice of the people of Madinah in Imam Malik''s time (al-Mudawwanah)."}}], "check": true}, {"type": "ref", "text": {"bn": "ডান হাত বাম হাতের উপর রাখার মূল বিধান (যা অধিকাংশের মত): সহিহ বুখারি ৭৪০ (সাহল ইবনে সাদ রা.)", "en": "The basic practice of placing the right hand over the left (the majority view): Sahih al-Bukhari 740 (Sahl ibn Sa''d RA)"}}, {"type": "differ", "title": {"bn": "আমিন জোরে বলবেন না আস্তে", "en": "Saying Amin aloud or quietly"}, "views": [{"label": {"bn": "হানাফি (মালেকিরাও আস্তে)", "en": "Hanafi (Malikis also say it quietly)"}, "text": {"bn": "ইমাম ও মুক্তাদি সবাই আমিন আস্তে বলবেন, শব্দ করে নয়।", "en": "Imam and followers all say Amin quietly."}, "evidence": {"bn": "আমিন একটি দোয়া, আর দোয়ার মূলনীতি নিচু স্বরে: \"তোমাদের রবকে ডাকো বিনয়ের সাথে ও গোপনে\" — সূরা আরাফ ৭:৫৫; ওয়ায়েল (রা.)-এর হাদিসের শুবার বর্ণনায় \"আওয়াজ নিচু করলেন\" (মুসনাদে আহমাদ; তিরমিযি ২৪৮-এর আলোচনায় উল্লিখিত); উমর ও ইবনে মাসউদ (রা.)-এর আমল।", "en": "Amin is a dua, and the principle in dua is quietness: \"Call upon your Lord humbly and privately\" (Al-A''raf 7:55); in Shu''bah''s version of Wa''il''s hadith, \"he lowered his voice\" (Musnad Ahmad; mentioned in at-Tirmidhi''s discussion under 248); the practice of Umar and Ibn Mas''ud (RA)."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি (এবং আহলে হাদিস)", "en": "Shafi''i and Hanbali (and Ahl al-Hadith)"}, "text": {"bn": "যেসব নামাজে কিরাত শব্দ করে পড়া হয়, সেখানে ইমাম ও মুক্তাদি আমিন শব্দ করে বলবেন।", "en": "In prayers recited aloud, the imam and followers say Amin aloud."}, "evidence": {"bn": "ওয়ায়েল ইবনে হুজর (রা.): রাসুলুল্লাহ ﷺ \"ওয়ালাদ্দাল্লিন\" বলে আওয়াজ টেনে আমিন বললেন — সুনান তিরমিযি ২৪৮; সুনান আবু দাউদ ৯৩২; \"ইমাম আমিন বললে তোমরাও আমিন বলো; যার আমিন ফেরেশতাদের আমিনের সাথে মিলে যায়, তার আগের গুনাহ মাফ\" — সহিহ বুখারি ৭৮০।", "en": "Wa''il ibn Hujr (RA): after \"wa lad-dallin\" the Prophet ﷺ said Amin, drawing out his voice (Jami at-Tirmidhi 248; Sunan Abi Dawud 932); \"When the imam says Amin, say Amin; whoever''s Amin coincides with the angels'', his past sins are forgiven\" (Sahih al-Bukhari 780)."}}], "check": true}, {"type": "differ", "title": {"bn": "ইমামের পেছনে সূরা ফাতিহা পড়া", "en": "Reciting Al-Fatihah behind the imam"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "মুক্তাদি কোনো নামাজেই — জোরে বা আস্তে কিরাতের নামাজে — ফাতিহা পড়বেন না; চুপ থেকে শুনবেন। ইমামের কিরাতই মুক্তাদির কিরাত।", "en": "The follower does not recite Al-Fatihah in any prayer, loud or quiet; he listens silently. The imam''s recitation counts for him."}, "evidence": {"bn": "\"যখন কুরআন পড়া হয়, মনোযোগ দিয়ে শোনো এবং চুপ থাকো\" — সূরা আরাফ ৭:২০৪; \"ইমাম যখন কিরাত পড়েন, তোমরা চুপ থাকো\" — সহিহ মুসলিম ৪০৪; \"যার ইমাম আছে, ইমামের কিরাতই তার কিরাত\" — সুনান ইবনে মাজাহ ৮৫০ (এর মান নিয়ে মুহাদ্দিসদের মতভেদ আছে)।", "en": "\"When the Quran is recited, listen to it and be silent\" (Al-A''raf 7:204); \"When he (the imam) recites, be silent\" (Sahih Muslim 404); \"Whoever has an imam, the imam''s recitation is his recitation\" (Sunan Ibn Majah 850, whose grading is disputed)."}}, {"label": {"bn": "শাফেয়ি (এবং আহলে হাদিস)", "en": "Shafi''i (and Ahl al-Hadith)"}, "text": {"bn": "মুক্তাদির জন্যও প্রতি রাকাতে ফাতিহা পড়া ফরজ — জোরে কিরাতের নামাজেও, ইমামের থামার ফাঁকে বা নিচু স্বরে।", "en": "Al-Fatihah is obligatory on the follower too, in every rakat, even in loud prayers: in the imam''s pauses or quietly."}, "evidence": {"bn": "\"যে ফাতিহা পড়ে না তার নামাজ হয় না\" — সহিহ বুখারি ৭৫৬; \"ইমামের পেছনে থাকলেও তা মনে মনে পড়ো\" — সহিহ মুসলিম ৩৯৫; \"উম্মুল কুরআন ছাড়া আর কিছু পড়ো না\" — সুনান আবু দাউদ (উবাদা রা.)।", "en": "\"There is no prayer for one who does not recite Al-Fatihah\" (Sahih al-Bukhari 756); \"Recite it to yourself\" even behind the imam (Sahih Muslim 395); \"Do not recite anything except Umm al-Quran\" (Sunan Abi Dawud, from Ubadah RA)."}}, {"label": {"bn": "মালেকি ও হাম্বলি", "en": "Maliki and Hanbali"}, "text": {"bn": "আস্তে কিরাতের নামাজে (জোহর, আসর এবং অন্য নামাজের নিচু স্বরের রাকাত) মুক্তাদি ফাতিহা পড়বেন; জোরে কিরাতের সময় চুপ থেকে শুনবেন।", "en": "In quiet prayers (Zuhr, Asr, and the quiet rakats of others) the follower recites Al-Fatihah; when the imam recites aloud, he listens."}, "evidence": {"bn": "সূরা আরাফ ৭:২০৪ ও সহিহ বুখারি ৭৫৬ — দুটোর সমন্বয়; সাহাবিরা জোরে কিরাতের নামাজে রাসুলুল্লাহ ﷺ-এর পেছনে কিরাত পড়া ছেড়ে দিয়েছিলেন — সুনান আবু দাউদ।", "en": "Combining Al-A''raf 7:204 with Sahih al-Bukhari 756; the Companions stopped reciting behind the Prophet ﷺ in loud prayers (Sunan Abi Dawud)."}}], "check": true}, {"type": "differ", "title": {"bn": "সিজদায় যাওয়ার সময় আগে হাঁটু না আগে হাত", "en": "Going down to sujud: knees first or hands first"}, "views": [{"label": {"bn": "হানাফি, শাফেয়ি ও হাম্বলি (প্রসিদ্ধ মত)", "en": "Hanafi, Shafi''i and Hanbali (well-known view)"}, "text": {"bn": "প্রথমে হাঁটু, তারপর হাত মাটিতে রাখা; ওঠার সময় আগে হাত, পরে হাঁটু।", "en": "Knees first, then hands; when rising, hands first, then knees."}, "evidence": {"bn": "ওয়ায়েল ইবনে হুজর (রা.): রাসুলুল্লাহ ﷺ সিজদায় যেতে হাতের আগে হাঁটু রাখতেন — সুনান আবু দাউদ; সুনান তিরমিযি।", "en": "Wa''il ibn Hujr (RA): the Prophet ﷺ placed his knees before his hands when going into sujud (Sunan Abi Dawud; Jami at-Tirmidhi)."}}, {"label": {"bn": "মালেকি (এবং হাম্বলিদের একটি মত)", "en": "Maliki (and one Hanbali view)"}, "text": {"bn": "প্রথমে হাত, তারপর হাঁটু।", "en": "Hands first, then knees."}, "evidence": {"bn": "\"তোমাদের কেউ যেন উটের মতো না বসে; সে যেন হাঁটুর আগে হাত রাখে\" — আবু হুরায়রা (রা.), সুনান আবু দাউদ।", "en": "\"None of you should kneel as a camel kneels; let him put his hands before his knees\" (Abu Hurayrah RA, Sunan Abi Dawud)."}}], "check": true}, {"type": "differ", "title": {"bn": "বিতরের পদ্ধতি", "en": "How witr is prayed"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "বিতর সবসময় তিন রাকাত, এক সালামে, দ্বিতীয় রাকাতে বৈঠকসহ — মাগরিবের মতো। তৃতীয় রাকাতে রুকুর আগে তাকবির দিয়ে কুনুত, সারা বছর।", "en": "Witr is always three rakats with one salam and a sitting after the second, like Maghrib. Qunut is in the third rakat before ruku, after a takbir, all year round."}, "evidence": {"bn": "আয়েশা (রা.): রাসুলুল্লাহ ﷺ চার রাকাত, তারপর চার রাকাত, তারপর তিন রাকাত পড়তেন — সহিহ বুখারি ১১৪৭; সহিহ মুসলিম ৭৩৮। রুকুর আগে কুনুত — উবাই ইবনে কাব (রা.)-এর বর্ণনা (সুনান নাসায়ি) এবং ইবনে মাসউদ (রা.)-এর আমল।", "en": "Aisha (RA): the Prophet ﷺ prayed four, then four, then three (Sahih al-Bukhari 1147; Sahih Muslim 738). Qunut before ruku: the report of Ubayy ibn Ka''b (RA) (Sunan an-Nasa''i) and the practice of Ibn Mas''ud (RA)."}}, {"label": {"bn": "শাফেয়ি, হাম্বলি ও মালেকি", "en": "Shafi''i, Hanbali and Maliki"}, "text": {"bn": "বিতর এক রাকাতও হতে পারে, আবার তিন, পাঁচ, সাত বা তার বেশি বেজোড় রাকাতও। তিন রাকাত পড়লে সাধারণত দুই রাকাতে সালাম ফিরিয়ে আলাদা এক রাকাত, অথবা মাঝে না বসে একটানা তিন রাকাত। কুনুত সাধারণত রুকুর পরে হাত তুলে; শাফেয়ি মতে শুধু রমজানের শেষ অর্ধেকে।", "en": "Witr may be one rakat, or three, five, seven or more odd rakats. Three are usually prayed as two with a salam and then one, or three straight through without the middle sitting. Qunut is usually after ruku with raised hands; for Shafi''is only in the second half of Ramadan."}, "evidence": {"bn": "\"রাতের নামাজ দুই দুই রাকাত; ফজর হয়ে যাওয়ার ভয় হলে এক রাকাত বিতর পড়ে নাও\" — সহিহ বুখারি ৯৯০; সহিহ মুসলিম ৭৪৯; \"বিতর শেষ রাতের এক রাকাত\" — সহিহ মুসলিম ৭৫২; \"যে চায় পাঁচ, যে চায় তিন, যে চায় এক রাকাত বিতর পড়ুক\" — সুনান আবু দাউদ ১৪২২।", "en": "\"Night prayer is in twos; if you fear dawn, pray one rakat of witr\" (Sahih al-Bukhari 990; Sahih Muslim 749); \"Witr is one rakat at the end of the night\" (Sahih Muslim 752); \"Whoever wishes may pray witr with five, three or one\" (Sunan Abi Dawud 1422)."}}], "check": true}, {"type": "note", "tone": "info", "text": {"bn": "বিতরের বিস্তারিত নিয়ম ও দোয়া কুনুত \"বিশেষ নামাজ\" বিভাগে, আর নারীদের নামাজের ভঙ্গি নিয়ে মতপার্থক্য \"নারীদের নামাজ\" অংশে দেখুন।", "en": "The full method of witr and the dua qunut are in the Special Prayers section; for women''s postures see \"Women''s Salah\"."}}]', 'in_review', 120 FROM is_guide_topics WHERE slug = 'salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '0f4c431e-25d1-5c29-be99-5122518cfb45', id, 'salah-jamaat-masbuq', '{"bn": "জামাতে নামাজ ও মাসবুক", "en": "Congregational Prayer and Joining Late (Masbuq)"}', '{"bn": "জামাতের গুরুত্ব ও হুকুম, কাতার ও ইমামের অনুসরণের নিয়ম, এবং দেরিতে জামাতে শরিক হলে ছুটে যাওয়া রাকাত কীভাবে পূরণ করবেন।", "en": "The importance and ruling of congregation, rows and following the imam, and how to make up rakats when you join late."}', 'detail', '[{"type": "text", "text": {"bn": "জামাতে নামাজ একা নামাজের চেয়ে সাতাশ গুণ বেশি মর্যাদাপূর্ণ। পুরুষদের জন্য ফরজ নামাজ মসজিদে জামাতে পড়ার ব্যাপারে রাসুলুল্লাহ ﷺ খুব জোর দিয়েছেন; এমনকি এক অন্ধ সাহাবিকেও আজান শুনতে পেলে আসতে বলেছেন।", "en": "Prayer in congregation is twenty-seven times more rewarding than praying alone. The Prophet ﷺ strongly stressed that men pray the fard prayers in congregation in the mosque; he told even a blind Companion who could hear the adhan to come."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৬৪৫; সহিহ মুসলিম ৬৫০ (২৭ গুণ); সহিহ মুসলিম ৬৫৩ (অন্ধ সাহাবি)", "en": "Sahih al-Bukhari 645; Sahih Muslim 650 (27 times); Sahih Muslim 653 (the blind Companion)"}}, {"type": "differ", "title": {"bn": "পুরুষদের জন্য জামাতের হুকুম", "en": "The ruling on congregation for men"}, "views": [{"label": {"bn": "হানাফি ও মালেকি", "en": "Hanafi and Maliki"}, "text": {"bn": "সুন্নতে মুয়াক্কাদা — ওয়াজিবের কাছাকাছি; অনেক হানাফি আলেম একে ওয়াজিব বলেছেন। বিনা ওজরে নিয়মিত ছেড়ে দেওয়া গুনাহ।", "en": "An emphasised sunnah, close to wajib; many Hanafi scholars call it wajib. Habitually leaving it without excuse is sinful."}, "evidence": {"bn": "একা নামাজও সহিহ, তবে জামাতের মর্যাদা ২৭ গুণ — সহিহ বুখারি ৬৪৫; এতে বোঝা যায় একা নামাজ বাতিল নয়।", "en": "Praying alone is valid, while congregation is 27 times greater (Sahih al-Bukhari 645), which shows the individual prayer is not void."}}, {"label": {"bn": "শাফেয়ি", "en": "Shafi''i"}, "text": {"bn": "ফরজে কিফায়া — এলাকায় কিছু লোক জামাত কায়েম করলে বাকিদের দায় আদায় হয়।", "en": "A communal obligation: if some in the area establish it, the rest are relieved."}, "evidence": {"bn": "জনপদে জামাত কায়েম না হলে শয়তান প্রভাব বিস্তার করে — এ অর্থের হাদিস (সুনান আবু দাউদ)।", "en": "The hadith that Satan prevails over a settlement where congregational prayer is not established (Sunan Abi Dawud)."}}, {"label": {"bn": "হাম্বলি", "en": "Hanbali"}, "text": {"bn": "প্রত্যেক সক্ষম পুরুষের উপর ওয়াজিব (ফরজে আইন), তবে একা পড়লেও নামাজ হয়ে যায়।", "en": "Obligatory on every able man, though a prayer prayed alone is still valid."}, "evidence": {"bn": "জামাতে না আসা লোকদের ঘর জ্বালিয়ে দেওয়ার ইচ্ছা প্রকাশ — সহিহ বুখারি ৬৪৪; অন্ধ সাহাবিকেও ছাড় দেননি — সহিহ মুসলিম ৬৫৩।", "en": "The Prophet ﷺ expressed the wish to burn the houses of those who stay away (Sahih al-Bukhari 644); he did not excuse even the blind Companion (Sahih Muslim 653)."}}], "check": true}, {"type": "heading", "text": {"bn": "জামাতের মূল নিয়ম", "en": "Basic rules of congregation"}}, {"type": "list", "items": [{"bn": "কাতার সোজা ও মিলিত রাখা — কাঁধে কাঁধ, ফাঁক না রাখা; আগে সামনের কাতার পূর্ণ করা। (সহিহ বুখারি ৭২৩)", "en": "Keep the rows straight and close, shoulder to shoulder with no gaps; fill the front rows first. (Sahih al-Bukhari 723)"}, {"bn": "একজন মুক্তাদি হলে ইমামের ডান পাশে দাঁড়াবেন; দুই বা তার বেশি হলে পেছনে কাতার করবেন।", "en": "A single follower stands at the imam''s right; two or more form a row behind."}, {"bn": "ইমাম হওয়ার বেশি হকদার যিনি কুরআন বেশি ভালো পড়েন ও জানেন। (সহিহ মুসলিম ৬৭৩)", "en": "The one most entitled to lead is the one who best knows and recites the Quran. (Sahih Muslim 673)"}, {"bn": "ইমামের অনুসরণ করুন — ইমামের আগে রুকু-সিজদায় যাবেন না বা উঠবেন না; ইমামের আগে মাথা তোলার ব্যাপারে কঠোর সতর্কবাণী আছে। (সহিহ বুখারি ৭২২, ৬৯১)", "en": "Follow the imam: never go down or rise before him; there is a stern warning for raising the head before the imam. (Sahih al-Bukhari 722, 691)"}, {"bn": "ইমাম ভুল করলে পুরুষরা \"সুবহানাল্লাহ\" বলবেন, নারীরা হাততালি দেবেন। (সহিহ বুখারি ১২০৩)", "en": "If the imam errs, men say \"Subhanallah\" and women clap. (Sahih al-Bukhari 1203)"}, {"bn": "ইকামত হয়ে গেলে নতুন করে সুন্নত শুরু না করে জামাতে শরিক হোন; তাড়াহুড়া না করে শান্তভাবে হেঁটে আসুন। (সহিহ বুখারি ৬৩৬)", "en": "Once the iqamah is called, join the congregation rather than starting a sunnah; walk calmly, do not rush. (Sahih al-Bukhari 636)"}]}, {"type": "note", "tone": "info", "text": {"bn": "হানাফি মতে মুক্তাদি তাকবিরে তাহরিমার পর সানা পড়বেন, তারপর চুপ থাকবেন (কিরাত পড়বেন না); রুকু-সিজদার তাসবিহ, \"রাব্বানা লাকাল হামদ\", তাশাহহুদ, দরুদ ও দোয়া নিজে পড়বেন। ইমামের পেছনে ফাতিহা পড়ার মতপার্থক্য \"নামাজে মতপার্থক্যের বিষয়গুলো\" অংশে আছে।", "en": "In the Hanafi view the follower recites the thana after the opening takbir and then stays silent (no recitation); he says the ruku and sujud tasbih, \"Rabbana lakal-hamd\", the tashahhud, durood and dua himself. For the difference on reciting Al-Fatihah behind the imam see \"Points of Difference in Salah\"."}}, {"type": "heading", "text": {"bn": "মাসবুক: দেরিতে জামাতে শরিক হলে", "en": "Masbuq: joining the congregation late"}}, {"type": "text", "text": {"bn": "যে ব্যক্তি এক বা একাধিক রাকাত ছুটে যাওয়ার পর জামাতে শরিক হন, তাকে মাসবুক বলে। রাসুলুল্লাহ ﷺ বলেছেন: \"যতটুকু পাও পড়ো, আর যা ছুটে গেছে পূর্ণ করো।\"", "en": "One who joins after one or more rakats have passed is called masbuq. The Prophet ﷺ said: \"Pray what you catch, and complete what you missed.\""}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৬৩৬; সহিহ মুসলিম ৬০২", "en": "Sahih al-Bukhari 636; Sahih Muslim 602"}}, {"type": "step", "title": {"bn": "দাঁড়িয়ে তাকবিরে তাহরিমা", "en": "Opening takbir while standing"}, "text": {"bn": "ইমাম যে অবস্থায়ই থাকুন, সোজা দাঁড়ানো অবস্থায় তাকবিরে তাহরিমা বলে নিয়ত বাঁধুন। তারপর আরেকবার \"আল্লাহু আকবার\" বলে ইমাম যে অবস্থায় আছেন (রুকু, সিজদা বা বৈঠক) সে অবস্থায় চলে যান।", "en": "Whatever position the imam is in, say the opening takbir standing upright. Then say \"Allahu akbar\" again and join the imam in his position (ruku, sujud or sitting)."}}, {"type": "step", "title": {"bn": "রাকাত কখন গণ্য হয়", "en": "When a rakat counts"}, "text": {"bn": "ইমাম রুকু থেকে ওঠার আগে আপনি রুকুতে শরিক হতে পারলে সেই রাকাত পেয়েছেন বলে গণ্য হবে (অধিকাংশ আলেমের মত)। রুকুর পরে শরিক হলে সেই রাকাত গণ্য হবে না, পরে পূরণ করতে হবে।", "en": "If you join the imam in ruku before he rises from it, you have caught that rakat (the majority view). If you join after the ruku, that rakat does not count and must be made up."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ — \"যে রুকু পেল সে রাকাত পেল\"", "en": "Sunan Abi Dawud: \"Whoever catches the ruku has caught the rakat\""}, "check": true}, {"type": "step", "title": {"bn": "ইমামের সালামের সময়", "en": "At the imam''s salam"}, "text": {"bn": "শেষ বৈঠকে শুধু তাশাহহুদ ধীরে ধীরে পড়ুন (হানাফি মত)। ইমামের সাথে সালাম ফেরাবেন না; ইমাম দুই দিকে সালাম ফেরানোর পর \"আল্লাহু আকবার\" বলে দাঁড়িয়ে যান।", "en": "In the final sitting recite only the tashahhud, slowly (Hanafi view). Do not give salam with the imam; after he has given both salams, say \"Allahu akbar\" and stand up."}}, {"type": "step", "title": {"bn": "ছুটে যাওয়া রাকাত পূরণ", "en": "Make up the missed rakats"}, "text": {"bn": "হানাফি মতে ছুটে যাওয়া রাকাতগুলো কিরাতের দিক থেকে নামাজের শুরুর রাকাত হিসেবে পড়বেন — অর্থাৎ ফাতিহার সাথে সূরা মেলাবেন; আর বৈঠকের হিসাব হবে মোট রাকাত গুনে।", "en": "In the Hanafi view, the missed rakats are prayed as the beginning of the prayer for recitation (so a surah is added after Al-Fatihah), while the sittings follow the overall count of rakats."}}, {"type": "table", "head": [{"bn": "অবস্থা", "en": "Situation"}, {"bn": "কীভাবে পূরণ করবেন (হানাফি মত)", "en": "How to make up (Hanafi view)"}], "rows": [[{"bn": "চার রাকাতের নামাজে ১ রাকাত ছুটেছে", "en": "Missed 1 rakat of a 4-rakat prayer"}, {"bn": "দাঁড়িয়ে ফাতিহা + সূরা পড়ে রুকু-সিজদা করে শেষ বৈঠক ও সালাম।", "en": "Stand, recite Al-Fatihah + surah, ruku and sujud, then the final sitting and salam."}], [{"bn": "চার রাকাতের নামাজে ২ রাকাত ছুটেছে", "en": "Missed 2 rakats of a 4-rakat prayer"}, {"bn": "দুই রাকাতই ফাতিহা + সূরা দিয়ে, মাঝে না বসে; তারপর শেষ বৈঠক।", "en": "Both rakats with Al-Fatihah + surah, no sitting between; then the final sitting."}], [{"bn": "চার রাকাতের নামাজে ৩ রাকাত ছুটেছে", "en": "Missed 3 rakats of a 4-rakat prayer"}, {"bn": "প্রথম রাকাত ফাতিহা + সূরা, তারপর বসে তাশাহহুদ; দ্বিতীয় রাকাত ফাতিহা + সূরা; তৃতীয় রাকাত শুধু ফাতিহা; তারপর শেষ বৈঠক।", "en": "First rakat Al-Fatihah + surah, then sit for the tashahhud; second rakat Al-Fatihah + surah; third rakat Al-Fatihah only; then the final sitting."}], [{"bn": "মাগরিবে ২ রাকাত ছুটেছে", "en": "Missed 2 rakats of Maghrib"}, {"bn": "প্রথম রাকাত ফাতিহা + সূরা, তারপর বসে তাশাহহুদ; দ্বিতীয় রাকাত ফাতিহা + সূরা; তারপর শেষ বৈঠক।", "en": "First rakat Al-Fatihah + surah, then sit for the tashahhud; second rakat Al-Fatihah + surah; then the final sitting."}], [{"bn": "ইমামকে শেষ বৈঠকে পেয়েছেন", "en": "Joined the imam in the final sitting"}, {"bn": "ইমামের সালামের পর দাঁড়িয়ে পুরো নামাজ সাধারণ নিয়মে পড়বেন; জামাতের সওয়াব পাওয়ার আশা আছে।", "en": "After the imam''s salam, stand and pray the whole prayer normally; you may hope for the reward of the congregation."}]]}, {"type": "note", "tone": "info", "text": {"bn": "শাফেয়ি মাযহাবসহ কিছু আলেমের মতে ইমামের সাথে যে রাকাতগুলো পেয়েছেন সেগুলোই আপনার নামাজের শুরু, আর পরে যা পড়বেন তা শেষ অংশ; তাই পরের রাকাতগুলোর কিরাতের নিয়ম ভিন্ন হয়। ইমাম সাহু সিজদা দিলে মাসবুকও তাঁর সাথে সিজদা করবেন, কিন্তু সালাম ফেরাবেন না।", "en": "In the Shafi''i view and others, the rakats caught with the imam are the start of your prayer and what you pray afterwards is its end, so the recitation rules for the later rakats differ. If the imam does sajdah sahw, the masbuq prostrates with him but does not give salam."}}]', 'in_review', 130 FROM is_guide_topics WHERE slug = 'salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'ecbc8c6e-1856-5921-8b35-bc7991280594', id, 'sajdah-sahw', '{"bn": "সাহু সিজদা (ভুলের সিজদা)", "en": "Sajdah Sahw (Prostration of Forgetfulness)"}', '{"bn": "নামাজে ভুল হলে কখন সাহু সিজদা লাগে, কখন লাগে না, হানাফি পদ্ধতি, অন্য মাযহাবের মত এবং রাকাত নিয়ে সন্দেহ হলে কী করবেন।", "en": "When a mistake in salah calls for sajdah sahw and when it does not, the Hanafi method, other views, and what to do when unsure how many rakats you prayed."}', 'detail', '[{"type": "text", "text": {"bn": "নামাজে ভুলবশত কিছু বাদ পড়লে বা বেড়ে গেলে নামাজের শেষে দুটি অতিরিক্ত সিজদা দিয়ে তা পূরণ করা হয় — একে সাহু সিজদা বলে। রাসুলুল্লাহ ﷺ নিজেও নামাজে ভুল করে সাহু সিজদা দিয়ে উম্মতকে শিখিয়েছেন।", "en": "When something is left out or added by mistake in salah, it is repaired with two extra prostrations at the end: sajdah sahw. The Prophet ﷺ himself made such mistakes and taught the Ummah by performing sajdah sahw."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১২২৪; সহিহ মুসলিম ৫৭০ (প্রথম বৈঠক ভুলে যাওয়া); সহিহ বুখারি ১২২৯; সহিহ মুসলিম ৫৭৩ (যুল-ইয়াদাইনের ঘটনা)", "en": "Sahih al-Bukhari 1224; Sahih Muslim 570 (forgetting the first sitting); Sahih al-Bukhari 1229; Sahih Muslim 573 (the incident of Dhul-Yadayn)"}}, {"type": "heading", "text": {"bn": "কখন সাহু সিজদা লাগে (হানাফি মত)", "en": "When sajdah sahw is needed (Hanafi view)"}}, {"type": "list", "items": [{"bn": "কোনো ওয়াজিব ভুলে ছুটে গেলে — যেমন প্রথম বৈঠক, ফাতিহা, সূরা মেলানো, দোয়া কুনুত", "en": "A wajib is missed by mistake, e.g. the first sitting, Al-Fatihah, adding a surah, or the qunut"}, {"bn": "কোনো ফরজ বা ওয়াজিব আদায়ে দেরি হলে — যেমন প্রথম বৈঠকে তাশাহহুদের পর দরুদের অংশ পড়ে ফেলা", "en": "A fard or wajib is delayed, e.g. adding part of the durood after the tashahhud in the first sitting"}, {"bn": "কোনো রুকন ভুলে দুবার করলে — যেমন তিনটি সিজদা বা দুটি রুকু", "en": "A pillar is repeated by mistake, e.g. three sujud or two ruku"}, {"bn": "ক্রম উল্টে গেলে — যেমন ফাতিহার আগে সূরা পড়া", "en": "The order is reversed, e.g. reciting the surah before Al-Fatihah"}, {"bn": "জোরে পড়ার জায়গায় আস্তে বা আস্তে পড়ার জায়গায় জোরে পড়লে (ইমামের জন্য)", "en": "Reciting quietly where it should be aloud, or aloud where it should be quiet (for the imam)"}]}, {"type": "note", "tone": "warn", "text": {"bn": "কোনো ফরজ (রুকন) বাদ পড়লে — যেমন একটি সিজদা একেবারেই না করা — সাহু সিজদায় নামাজ পূর্ণ হয় না; নামাজ শেষ হওয়ার আগে মনে পড়লে তা আদায় করে শেষে সাহু সিজদা দেবেন, নইলে নামাজ আবার পড়তে হবে। শুধু সুন্নত ছুটলে (যেমন সানা) সাহু সিজদা লাগে না। ইচ্ছাকৃত ভুলে সাহু সিজদা যথেষ্ট নয়।", "en": "If a pillar is missed, e.g. a sujud left out entirely, sajdah sahw alone does not repair it: if remembered before the prayer ends, perform it and do sahw at the end; otherwise repeat the prayer. Missing only a sunnah (such as the thana) needs no sahw. Sahw does not cover deliberate omissions."}}, {"type": "heading", "text": {"bn": "হানাফি পদ্ধতি", "en": "The Hanafi method"}}, {"type": "step", "title": {"bn": "তাশাহহুদ পড়া", "en": "Recite the tashahhud"}, "text": {"bn": "শেষ বৈঠকে শুধু আত্তাহিয়্যাতু পড়ুন।", "en": "In the final sitting recite only the tashahhud."}}, {"type": "step", "title": {"bn": "ডান দিকে এক সালাম", "en": "One salam to the right"}, "text": {"bn": "শুধু ডান দিকে একবার সালাম ফেরান।", "en": "Give one salam, to the right only."}}, {"type": "step", "title": {"bn": "দুটি সিজদা", "en": "Two prostrations"}, "text": {"bn": "\"আল্লাহু আকবার\" বলে সাধারণ নিয়মে দুটি সিজদা করুন, প্রতিটিতে \"সুবহানা রাব্বিয়াল আ''লা\" পড়ুন, মাঝে বসুন।", "en": "Say \"Allahu akbar\" and make two ordinary prostrations, saying \"Subhana rabbiyal-a''la\" in each, sitting between them."}}, {"type": "step", "title": {"bn": "আবার বৈঠক ও সালাম", "en": "Sit again and finish"}, "text": {"bn": "সিজদার পর বসে আবার আত্তাহিয়্যাতু, দরুদ ও দোয়া পড়ে দুই দিকে সালাম ফেরান।", "en": "After the prostrations, sit, recite the tashahhud, durood and dua again, and give salam to both sides."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৪০১ — \"…তারপর সালাম ফেরাবে, তারপর দুটি সিজদা করবে\" (ইবনে মাসউদ রা.)", "en": "Sahih al-Bukhari 401: \"…then let him give salam, then make two prostrations\" (Ibn Mas''ud RA)"}}, {"type": "differ", "title": {"bn": "সাহু সিজদা সালামের আগে না পরে", "en": "Sajdah sahw before or after the salam"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "সব ক্ষেত্রে সালামের পরে — ডান দিকে এক সালাম দিয়ে, তারপর তাশাহহুদ ও সালাম।", "en": "Always after the salam: one salam to the right, then the prostrations, then tashahhud and salam."}, "evidence": {"bn": "ইবনে মাসউদ (রা.)-এর হাদিস — সহিহ বুখারি ৪০১; \"প্রত্যেক ভুলের জন্য সালামের পর দুটি সিজদা\" — সাওবান (রা.), সুনান আবু দাউদ।", "en": "The hadith of Ibn Mas''ud (RA) (Sahih al-Bukhari 401); \"For every mistake, two prostrations after the salam\" (Thawban RA, Sunan Abi Dawud)."}}, {"label": {"bn": "শাফেয়ি", "en": "Shafi''i"}, "text": {"bn": "সব ক্ষেত্রে সালামের আগে — শেষ বৈঠকের দোয়ার পর দুটি সিজদা, তারপর সালাম।", "en": "Always before the salam: two prostrations after the final sitting''s dua, then salam."}, "evidence": {"bn": "প্রথম বৈঠক ভুলে যাওয়ার পর রাসুলুল্লাহ ﷺ সালামের আগে সিজদা করেছেন — সহিহ বুখারি ১২২৪; রাকাত নিয়ে সন্দেহ হলে সালামের আগে সিজদা — সহিহ মুসলিম ৫৭১।", "en": "After forgetting the first sitting the Prophet ﷺ prostrated before the salam (Sahih al-Bukhari 1224); in doubt about rakats, prostrate before the salam (Sahih Muslim 571)."}}, {"label": {"bn": "মালেকি ও হাম্বলি", "en": "Maliki and Hanbali"}, "text": {"bn": "মালেকি: কিছু কম হলে সালামের আগে, বেশি হলে পরে। হাম্বলি: যে ঘটনায় রাসুলুল্লাহ ﷺ যেভাবে করেছেন সেভাবে, বাকিগুলোতে সাধারণত সালামের আগে।", "en": "Maliki: before the salam for an omission, after it for an addition. Hanbali: as the Prophet ﷺ did in each specific case, otherwise generally before the salam."}, "evidence": {"bn": "উভয় ধরনের হাদিসের সমন্বয়: সালামের আগে — সহিহ বুখারি ১২২৪; সালামের পরে — সহিহ বুখারি ১২২৯ (যুল-ইয়াদাইন) ও ৪০১।", "en": "Reconciling both sets of hadith: before the salam (Sahih al-Bukhari 1224); after it (Sahih al-Bukhari 1229, Dhul-Yadayn, and 401)."}}]}, {"type": "note", "tone": "info", "text": {"bn": "সব মতেই নামাজ সহিহ হয়ে যায়; পার্থক্য শুধু উত্তম পদ্ধতি নিয়ে।", "en": "In every view the prayer is valid; the difference is only about the preferred method."}}, {"type": "heading", "text": {"bn": "রাকাত নিয়ে সন্দেহ হলে", "en": "If unsure how many rakats you prayed"}}, {"type": "text", "text": {"bn": "রাসুলুল্লাহ ﷺ বলেছেন, সন্দেহ হলে নিশ্চিত সংখ্যার উপর ভিত্তি করবে (অর্থাৎ কম সংখ্যা ধরবে) এবং সালামের আগে দুটি সিজদা করবে (সহিহ মুসলিম ৫৭১)। আরেক হাদিসে আছে, যেটা সঠিক মনে হয় সেটা খুঁজে নিয়ে তার উপর পূর্ণ করবে, তারপর দুটি সিজদা করবে (সহিহ বুখারি ৪০১)।", "en": "The Prophet ﷺ said that when in doubt one should build on what is certain (i.e. the lower number) and prostrate twice before the salam (Sahih Muslim 571). Another hadith says to strive for what seems correct, complete the prayer on that basis, then make two prostrations (Sahih al-Bukhari 401)."}}, {"type": "list", "items": [{"bn": "হানাফি মত: জীবনে প্রথমবার বা কদাচিৎ এমন সন্দেহ হলে নামাজ নতুন করে পড়বেন।", "en": "Hanafi view: if such doubt is a first or rare occurrence, restart the prayer."}, {"bn": "প্রায়ই সন্দেহ হলে যেদিকে মনের প্রবল ধারণা, সেটা ধরবেন; কোনো দিকে ধারণা না থাকলে কম সংখ্যা ধরে নামাজ পূর্ণ করে সাহু সিজদা দেবেন।", "en": "If it happens often, go with your strongest impression; if you have none, take the lower number, complete the prayer and do sajdah sahw."}, {"bn": "নামাজ শেষ হওয়ার পর সন্দেহ হলে তা গুরুত্ব দেবেন না, যদি না নিশ্চিত হন যে কিছু বাদ পড়েছে।", "en": "Doubts that arise after the prayer has ended are ignored, unless you are certain something was missed."}]}, {"type": "note", "tone": "info", "text": {"bn": "জামাতে ইমামের পেছনে নিজের ভুলের জন্য মুক্তাদিকে সাহু সিজদা দিতে হয় না। ইমাম সাহু সিজদা দিলে মুক্তাদিরা তাঁর অনুসরণ করবেন।", "en": "A follower behind the imam does not do sajdah sahw for his own mistakes. When the imam does sajdah sahw, the followers follow him."}}]', 'in_review', 140 FROM is_guide_topics WHERE slug = 'salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '9790e45e-2f4f-51bc-9504-2163762671fe', id, 'jumuah-prayer', '{"bn": "জুমার নামাজ", "en": "Jumu''ah (Friday) Prayer"}', '{"bn": "জুমার নামাজ কার ওপর ফরজ, কত রাকাত, খুতবার আদব আর জুমার দিনের সুন্নতগুলো এক জায়গায়।", "en": "Who must pray Jumu''ah, its rak''ahs, the khutbah, and the sunnahs of Friday."}', 'basic', '[{"type": "text", "text": {"bn": "জুমার দিন সপ্তাহের শ্রেষ্ঠ দিন। জুমার নামাজ সেদিনের জোহরের জায়গায় পড়া হয়: আগে খুতবা, তারপর জামাতের সাথে দুই রাকাত ফরজ। যার ওপর জুমা ফরজ, জুমা পড়লে তাকে আর জোহর পড়তে হয় না।", "en": "Friday is the best day of the week. Jumu''ah replaces Dhuhr on Friday: a khutbah, then two fard rak''ahs in congregation. Whoever prays Jumu''ah does not also pray Dhuhr."}}, {"type": "arabic", "label": {"bn": "কুরআনের নির্দেশ", "en": "The Quranic command"}, "ar": "يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نُودِيَ لِلصَّلَاةِ مِنْ يَوْمِ الْجُمُعَةِ فَاسْعَوْا إِلَىٰ ذِكْرِ اللَّهِ وَذَرُوا الْبَيْعَ ۚ ذَٰلِكُمْ خَيْرٌ لَكُمْ إِنْ كُنْتُمْ تَعْلَمُونَ", "pron": {"bn": "ইয়া আইয়ুহাল্লাযীনা আমানূ ইযা নূদিয়া লিসসালাতি মিই ইয়াওমিল জুমু''আতি ফাসআও ইলা যিকরিল্লাহি ওয়া যারুল বাই''। যালিকুম খাইরুল লাকুম ইন কুনতুম তা''লামূন।", "en": "Ya ayyuhalladhina amanu idha nudiya lis-salati min yawmil-jumu''ati fas''aw ila dhikrillahi wa dharul-bay''. Dhalikum khayrul lakum in kuntum ta''lamun."}, "meaning": {"bn": "হে মুমিনগণ, জুমার দিন যখন নামাজের জন্য আহ্বান করা হয়, তখন তোমরা আল্লাহর স্মরণের দিকে ধাবিত হও এবং বেচাকেনা ছেড়ে দাও। এটাই তোমাদের জন্য উত্তম, যদি তোমরা জানতে।", "en": "O you who believe, when the call is made for prayer on Friday, hasten to the remembrance of Allah and leave off trade. That is better for you, if you only knew."}, "ref": {"bn": "সূরা জুমু''আ ৬২:৯", "en": "Al-Jumu''ah 62:9"}}, {"type": "heading", "text": {"bn": "কার ওপর জুমা ফরজ", "en": "Who must attend"}}, {"type": "list", "items": [{"bn": "প্রাপ্তবয়স্ক ও সুস্থ মস্তিষ্কের মুসলিম পুরুষ", "en": "An adult, sane Muslim man"}, {"bn": "মুকিম, অর্থাৎ যিনি সফরে নেই", "en": "Resident (not travelling)"}, {"bn": "সুস্থ, যার মসজিদে যেতে বাধা নেই", "en": "Healthy, with nothing preventing him from going"}]}, {"type": "text", "text": {"bn": "নারী, শিশু, অসুস্থ ব্যক্তি ও মুসাফিরের ওপর জুমা ফরজ নয়; তারা ঘরে চার রাকাত জোহর পড়বেন। তবে তারা মসজিদে গিয়ে জুমা পড়লে সেটাই যথেষ্ট, আলাদা জোহর লাগবে না।", "en": "Women, children, the sick and travellers are exempt; they pray four rak''ahs of Dhuhr. If they do attend Jumu''ah, it counts and no Dhuhr is needed."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ ১০৬৭ (তারিক ইবনে শিহাব রা.: চার শ্রেণি ছাড়া প্রত্যেক মুসলিমের ওপর জামাতে জুমা ফরজ)", "en": "Sunan Abi Dawud 1067 (Jumu''ah is a duty on every Muslim in congregation except four)"}}, {"type": "note", "tone": "warn", "text": {"bn": "অবহেলা করে পরপর তিন জুমা ছেড়ে দিলে আল্লাহ তার অন্তরে মোহর মেরে দেন। (সুনান আবু দাউদ ১০৫২)", "en": "Whoever leaves three Jumu''ahs out of negligence, Allah seals his heart. (Sunan Abi Dawud 1052)"}}, {"type": "heading", "text": {"bn": "জুমার দিনের নামাজের ক্রম", "en": "Order of prayers on Friday"}}, {"type": "table", "head": [{"bn": "নামাজ", "en": "Prayer"}, {"bn": "রাকাত", "en": "Rak''ahs"}, {"bn": "হুকুম", "en": "Ruling"}], "rows": [[{"bn": "জুমার আগের সুন্নত", "en": "Sunnah before Jumu''ah"}, {"bn": "৪", "en": "4"}, {"bn": "হানাফি মতে সুন্নতে মুয়াক্কাদা (নিচে মতভেদ দেখুন)", "en": "Sunnah mu''akkadah in the Hanafi school (see the difference below)"}], [{"bn": "খুতবা (দুইটি)", "en": "Khutbah (two parts)"}, {"bn": "—", "en": "—"}, {"bn": "জুমা সহিহ হওয়ার শর্ত", "en": "A condition for Jumu''ah to be valid"}], [{"bn": "জুমার ফরজ", "en": "Jumu''ah fard"}, {"bn": "২", "en": "2"}, {"bn": "ফরজ, জামাতের সাথে; ইমাম জোরে কিরাত পড়েন", "en": "Fard, in congregation; the imam recites aloud"}], [{"bn": "জুমার পরের সুন্নত", "en": "Sunnah after Jumu''ah"}, {"bn": "৪ (কেউ কেউ এরপর আরও ২)", "en": "4 (some add 2 more)"}, {"bn": "সুন্নত", "en": "Sunnah"}]]}, {"type": "differ", "title": {"bn": "জুমার আগে ও পরে সুন্নত কত রাকাত", "en": "Sunnah prayers before and after Jumu''ah"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "জুমার আগে চার রাকাত ও পরে চার রাকাত সুন্নতে মুয়াক্কাদা। ইমাম আবু ইউসুফ (রহ.)-এর মতে পরে মোট ছয় রাকাত (চার, তারপর দুই)।", "en": "Four rak''ahs before and four after, both sunnah mu''akkadah. Imam Abu Yusuf held six after (four, then two)."}, "evidence": {"bn": "পরের চার রাকাত: সহিহ মুসলিম ৮৮১ (জুমার পরে চার রাকাত পড়ার নির্দেশ)। আগের চার রাকাত: ইবনে মাসউদ (রা.) জুমার আগে চার ও পরে চার রাকাত পড়তেন, ইমাম তিরমিজি তা উল্লেখ করেছেন (জামে তিরমিজি ৫২৩-এর আলোচনা); আলী (রা.) পরে দুই তারপর চার পড়তে বলেছেন।", "en": "After: Sahih Muslim 881 (pray four after Jumu''ah). Before: Ibn Mas''ud prayed four before and four after, as al-Tirmidhi notes (discussion under Jami'' al-Tirmidhi 523); ''Ali instructed two then four after."}}, {"label": {"bn": "শাফেয়ি, হাম্বলি ও অন্যান্য অনেকে", "en": "Shafi''i, Hanbali and many others"}, "text": {"bn": "জুমার আগে নির্দিষ্ট সংখ্যার সুন্নত নেই; ইমাম খুতবার জন্য বের হওয়া পর্যন্ত যত রাকাত ইচ্ছা নফল পড়া যায়। পরে মসজিদে চার রাকাত, অথবা ঘরে গিয়ে দুই রাকাত।", "en": "No fixed sunnah before Jumu''ah; pray as many voluntary rak''ahs as one likes until the imam comes out. After: four in the mosque or two at home."}, "evidence": {"bn": "সহিহ বুখারি ৮৮৩ (‘তারপর তার জন্য যা লেখা আছে তা পড়ে’); সহিহ মুসলিম ৮৮১ (পরে চার); সহিহ বুখারি ৯৩৭ (নবীজি সা. জুমার পরে ঘরে দুই রাকাত পড়তেন)।", "en": "Sahih al-Bukhari 883 (''then prays what was written for him''); Sahih Muslim 881 (four after); Sahih al-Bukhari 937 (the Prophet prayed two at home after Jumu''ah)."}}]}, {"type": "heading", "text": {"bn": "খুতবা ও তার আদব", "en": "The khutbah and its etiquette"}}, {"type": "list", "items": [{"bn": "ইমাম দুইটি খুতবা দেন, মাঝে অল্প সময় বসেন; খুতবায় কুরআন পড়া হয় ও উপদেশ দেওয়া হয় (সহিহ মুসলিম ৮৬২)।", "en": "The imam gives two khutbahs with a short sitting between them, reciting Quran and admonishing (Sahih Muslim 862)."}, {"bn": "খুতবা চুপ করে মনোযোগ দিয়ে শুনতে হয়। খুতবার সময় পাশের জনকে ‘চুপ করো’ বলাও অনর্থক কাজ (লাগব) বলে গণ্য (সহিহ বুখারি ৯৩৪)।", "en": "Listen silently. Even telling a neighbour ''be quiet'' during the khutbah is idle talk (Sahih al-Bukhari 934)."}, {"bn": "খুতবার সময় কথা বলা, মোবাইল দেখা, খাওয়া-দাওয়া ইত্যাদি থেকে বিরত থাকুন।", "en": "Do not talk, use the phone or eat during the khutbah."}, {"bn": "দেরিতে এলে মানুষের ঘাড় ডিঙিয়ে সামনে যাবেন না; নবীজি (সা.) এমন একজনকে বলেছিলেন, ‘বসে পড়ো, তুমি কষ্ট দিয়েছ’ (সুনান আবু দাউদ ১১১৮)।", "en": "If late, do not step over people''s necks; the Prophet told such a man, ''Sit down, you have caused harm'' (Sunan Abi Dawud 1118)."}]}, {"type": "differ", "title": {"bn": "খুতবা চলাকালে মসজিদে ঢুকলে দুই রাকাত পড়বে কি", "en": "Praying two rak''ahs on entering during the khutbah"}, "views": [{"label": {"bn": "হানাফি ও মালেকি", "en": "Hanafi and Maliki"}, "text": {"bn": "ইমাম খুতবার জন্য বের হয়ে গেলে আর নামাজ শুরু করবে না; বসে খুতবা শুনবে।", "en": "Once the imam has come out for the khutbah, do not start a prayer; sit and listen."}, "evidence": {"bn": "খুতবা শোনার নির্দেশ ও খুতবার সময় সামান্য কথাও নিষেধ হওয়া (সহিহ বুখারি ৯৩৪); ঘাড় ডিঙানো ব্যক্তিকে নবীজি (সা.) বসে যেতে বলেছিলেন (সুনান আবু দাউদ ১১১৮)।", "en": "The command to listen and the ban on even small talk (Sahih al-Bukhari 934); the Prophet told the man who stepped over people to sit (Sunan Abi Dawud 1118)."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি", "en": "Shafi''i and Hanbali"}, "text": {"bn": "সংক্ষেপে দুই রাকাত তাহিয়্যাতুল মসজিদ পড়ে বসবে।", "en": "Pray two short rak''ahs of tahiyyat al-masjid, then sit."}, "evidence": {"bn": "খুতবার সময় এক সাহাবি এসে বসে পড়লে নবীজি (সা.) তাকে দুই রাকাত সংক্ষেপে পড়তে বলেন (সহিহ বুখারি ৯৩০; সহিহ মুসলিম ৮৭৫)।", "en": "A man came during the khutbah and sat; the Prophet told him to pray two short rak''ahs (Sahih al-Bukhari 930; Sahih Muslim 875)."}}]}, {"type": "differ", "title": {"bn": "খুতবার ভাষা", "en": "Language of the khutbah"}, "views": [{"label": {"bn": "আরবিতে খুতবা (বাংলাদেশে প্রচলিত হানাফি আমল)", "en": "Khutbah in Arabic (common Hanafi practice in Bangladesh)"}, "text": {"bn": "মূল দুই খুতবা আরবিতেই দিতে হবে। মানুষকে বোঝানোর জন্য আজানের আগে বা খুতবার আগে মাতৃভাষায় আলাদা বয়ান করা হয়।", "en": "The two khutbahs themselves are given in Arabic; a talk in the local language is given separately before the adhan/khutbah."}, "evidence": {"bn": "নবীজি (সা.) ও সাহাবিরা সবসময় আরবিতে খুতবা দিয়েছেন, অনারব দেশে গিয়েও; খুতবা একটি ইবাদত, যা সুন্নাহর পদ্ধতিতে আদায় করা হয়।", "en": "The Prophet and the Companions always gave the khutbah in Arabic, even in non-Arab lands; the khutbah is an act of worship done in the sunnah way."}}, {"label": {"bn": "স্থানীয় ভাষায় খুতবা জায়েজ (কিছু আলেমের মত)", "en": "Local language allowed (view of some scholars)"}, "text": {"bn": "আরবিতে হামদ, দরুদ ও কুরআনের আয়াত পড়ে বাকি উপদেশ শ্রোতাদের ভাষায় দেওয়া যায়।", "en": "After praise, durood and Quran in Arabic, the admonition may be in the listeners'' language."}, "evidence": {"bn": "খুতবার উদ্দেশ্য উপদেশ দেওয়া (সহিহ মুসলিম ৮৬২); আল্লাহ প্রত্যেক রাসুলকে তার জাতির ভাষায় পাঠিয়েছেন (সূরা ইবরাহিম ১৪:৪)।", "en": "The khutbah''s purpose is admonition (Sahih Muslim 862); Allah sent every messenger in his people''s language (Ibrahim 14:4)."}}]}, {"type": "heading", "text": {"bn": "জুমা ছুটে গেলে বা দেরিতে পেলে", "en": "If you miss or join late"}}, {"type": "text", "text": {"bn": "জুমার জামাত পুরো ছুটে গেলে জুমা একা পড়া যায় না; চার রাকাত জোহর পড়তে হবে।", "en": "If you miss the Jumu''ah congregation entirely, you cannot pray Jumu''ah alone; pray four rak''ahs of Dhuhr."}}, {"type": "differ", "title": {"bn": "কতটুকু পেলে জুমা পাওয়া গণ্য হবে", "en": "How much must be caught to count as Jumu''ah"}, "views": [{"label": {"bn": "ইমাম আবু হানিফা ও আবু ইউসুফ (রহ.)", "en": "Imam Abu Hanifah and Abu Yusuf"}, "text": {"bn": "ইমামকে সালামের আগে যেকোনো অবস্থায়, এমনকি শেষ বৈঠকে পেলেও, দুই রাকাত জুমাই পূর্ণ করবে।", "en": "Joining the imam at any point before the salam, even in the last sitting, you complete two rak''ahs of Jumu''ah."}, "evidence": {"bn": "‘যতটুকু পাও পড়ো, আর যা ছুটে গেছে তা পূর্ণ করো’ (সহিহ বুখারি ৬৩৬)।", "en": "''Pray what you catch and complete what you missed'' (Sahih al-Bukhari 636)."}}, {"label": {"bn": "ইমাম মুহাম্মাদ (রহ.) ও শাফেয়ি, মালেকি, হাম্বলি", "en": "Imam Muhammad, and the Shafi''i, Maliki, Hanbali schools"}, "text": {"bn": "দ্বিতীয় রাকাতের রুকু পেলে জুমা পেয়েছে, আরেক রাকাত মিলিয়ে নেবে; রুকুর পরে যোগ দিলে চার রাকাত জোহর পড়বে।", "en": "If you catch the ruku'' of the second rak''ah, add one rak''ah for Jumu''ah; if you join after it, pray four of Dhuhr."}, "evidence": {"bn": "‘যে জুমার এক রাকাত পেল, সে যেন তার সাথে আরেক রাকাত মিলায়’ (সুনান ইবনে মাজাহ ১১২১; সুনান নাসায়ি ৫৫৭)।", "en": "''Whoever catches one rak''ah of Jumu''ah, let him add another to it'' (Sunan Ibn Majah 1121; Sunan al-Nasa''i 557)."}}]}, {"type": "heading", "text": {"bn": "জুমার দিনের সুন্নত ও আমল", "en": "Sunnahs and good deeds of Friday"}}, {"type": "list", "items": [{"bn": "গোসল করা (সহিহ বুখারি ৮৭৭, ৮৭৯)", "en": "Take a bath (ghusl) (Sahih al-Bukhari 877, 879)"}, {"bn": "পরিচ্ছন্ন ও ভালো কাপড় পরা, তেল বা সুগন্ধি লাগানো, যথাসাধ্য পবিত্রতা অর্জন (সহিহ বুখারি ৮৮৩)", "en": "Wear clean, good clothes, use oil or perfume, purify yourself as you can (Sahih al-Bukhari 883)"}, {"bn": "আগে আগে মসজিদে যাওয়া এবং ইমামের কাছাকাছি বসা", "en": "Go to the mosque early and sit near the imam"}, {"bn": "দুজনের মাঝে ফাঁক করে না বসা, চুপ করে খুতবা শোনা (সহিহ বুখারি ৮৮৩)", "en": "Do not squeeze between two people; listen quietly (Sahih al-Bukhari 883)"}, {"bn": "বেশি বেশি দরুদ পড়া (সুনান আবু দাউদ ১০৪৭)", "en": "Send abundant durood on the Prophet (Sunan Abi Dawud 1047)"}, {"bn": "দোয়া করা: জুমার দিনে একটি সময় আছে, তখন মুমিন যা চায় আল্লাহ দেন (সহিহ বুখারি ৯৩৫)", "en": "Make dua: there is an hour on Friday when Allah grants what a believer asks (Sahih al-Bukhari 935)"}, {"bn": "সূরা কাহফ তিলাওয়াত করা", "en": "Recite Surah al-Kahf"}, {"bn": "আজান হলে বেচাকেনা ও কাজ বন্ধ করে মসজিদে যাওয়া (সূরা জুমু''আ ৬২:৯)", "en": "Stop trade and work at the adhan and go to the mosque (Al-Jumu''ah 62:9)"}]}, {"type": "note", "tone": "info", "text": {"bn": "জুমার দিনে সূরা কাহফ পড়ার ফজিলতের হাদিস (আবু সাইদ খুদরি রা. থেকে) মুস্তাদরাকে হাকিম ও বায়হাকিতে আছে; অনেক মুহাদ্দিস একে সহিহ বলেছেন, কেউ কেউ মারফু হওয়া নিয়ে আপত্তি করেছেন।", "en": "The hadith on reading al-Kahf on Friday (from Abu Sa''id al-Khudri) is in al-Hakim''s Mustadrak and al-Bayhaqi; many scholars graded it sahih, some questioned whether it is the Prophet''s own words."}, "check": true}]', 'in_review', 10 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'e079fbc8-d1ce-54be-b7ae-d12312ba9b31', id, 'eid-prayer', '{"bn": "ঈদের নামাজ", "en": "Eid Prayer"}', '{"bn": "ঈদুল ফিতর ও ঈদুল আজহার নামাজ দুই রাকাত, অতিরিক্ত তাকবিরসহ। নিয়ম, তাকবিরের সংখ্যা নিয়ে মতভেদ ও ঈদের সুন্নত।", "en": "Eid al-Fitr and Eid al-Adha prayer: two rak''ahs with extra takbirs, the views on their number, and the sunnahs of Eid."}', 'basic', '[{"type": "text", "text": {"bn": "ঈদের নামাজ দুই রাকাত, জামাতের সাথে, আজান ও ইকামত ছাড়া (সহিহ মুসলিম ৮৮৭)। নামাজ আগে, খুতবা পরে (সহিহ বুখারি ৯৬৩)। সময়: সূর্য উঠে কিছুটা ওপরে ওঠার পর থেকে দুপুরের (জাওয়াল) আগ পর্যন্ত।", "en": "Eid prayer is two rak''ahs in congregation, without adhan or iqamah (Sahih Muslim 887). The prayer comes first, then the khutbah (Sahih al-Bukhari 963). Time: from when the sun has risen a little until just before noon (zawal)."}}, {"type": "differ", "title": {"bn": "ঈদের নামাজের হুকুম", "en": "Ruling of the Eid prayer"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "যাদের ওপর জুমা ফরজ, তাদের ওপর ঈদের নামাজ ওয়াজিব।", "en": "Wajib on those for whom Jumu''ah is obligatory."}, "evidence": {"bn": "নবীজি (সা.) কখনো ঈদের নামাজ ছাড়েননি; নারীদেরও ঈদগাহে যেতে বলেছেন (সহিহ বুখারি ৯৭৪; সহিহ মুসলিম ৮৯০)।", "en": "The Prophet never left it and told even women to come out (Sahih al-Bukhari 974; Sahih Muslim 890)."}}, {"label": {"bn": "শাফেয়ি ও মালেকি", "en": "Shafi''i and Maliki"}, "text": {"bn": "সুন্নতে মুয়াক্কাদা।", "en": "A confirmed sunnah."}, "evidence": {"bn": "দিনে-রাতে পাঁচ ওয়াক্ত ছাড়া আর কোনো নামাজ ফরজ নয় (সহিহ বুখারি ৪৬)।", "en": "No prayer is obligatory beyond the five daily prayers (Sahih al-Bukhari 46)."}}, {"label": {"bn": "হাম্বলি", "en": "Hanbali"}, "text": {"bn": "ফরজে কিফায়া (সমাজের কিছু লোক আদায় করলে সবার পক্ষ থেকে আদায় হয়)।", "en": "A communal obligation (fard kifayah)."}, "evidence": {"bn": "নবীজি (সা.)-এর নিয়মিত আমল এবং এটি ইসলামের প্রকাশ্য নিদর্শন।", "en": "The Prophet''s constant practice, and it is a public symbol of Islam."}}]}, {"type": "note", "tone": "tip", "text": {"bn": "নিয়ত মনে মনে করাই যথেষ্ট, মুখে বলা জরুরি নয়। উদাহরণ (প্রচলিত বাংলা): ‘আমি ঈদুল ফিতরের দুই রাকাত ওয়াজিব নামাজ, অতিরিক্ত ছয় তাকবিরসহ, এই ইমামের পেছনে আদায় করছি।’", "en": "Niyyah is the intention in the heart; saying it aloud is not required. Example (common Bangla phrasing): ''I am praying the two wajib rak''ahs of Eid al-Fitr with six extra takbirs behind this imam.''"}}, {"type": "heading", "text": {"bn": "হানাফি পদ্ধতি (বাংলাদেশে প্রচলিত)", "en": "Hanafi method (common in Bangladesh)"}}, {"type": "step", "title": {"bn": "তাকবিরে তাহরিমা", "en": "Opening takbir"}, "text": {"bn": "নিয়ত করে ‘আল্লাহু আকবার’ বলে হাত বাঁধুন এবং সানা পড়ুন।", "en": "Make the intention, say ''Allahu Akbar'', fold your hands and recite the thana."}}, {"type": "step", "title": {"bn": "প্রথম রাকাতে তিন অতিরিক্ত তাকবির", "en": "Three extra takbirs in the first rak''ah"}, "text": {"bn": "ইমামের সাথে তিনবার ‘আল্লাহু আকবার’ বলুন। প্রথম ও দ্বিতীয় তাকবিরে কান পর্যন্ত হাত তুলে ছেড়ে দিন; তৃতীয় তাকবিরে হাত তুলে বেঁধে নিন। প্রতি দুই তাকবিরের মাঝে প্রায় তিন তাসবিহ পরিমাণ থামুন।", "en": "Say ''Allahu Akbar'' three times with the imam. On the first and second, raise your hands to the ears and let them hang; on the third, raise them and fold them. Pause about three tasbihs between takbirs."}}, {"type": "step", "title": {"bn": "কিরাত", "en": "Recitation"}, "text": {"bn": "ইমাম সূরা ফাতিহা ও আরেকটি সূরা জোরে পড়বেন; মুক্তাদি চুপ করে শুনবেন। তারপর স্বাভাবিকভাবে রুকু ও দুই সিজদা।", "en": "The imam recites al-Fatihah and a surah aloud; followers listen silently. Then ruku'' and two sajdahs as usual."}}, {"type": "step", "title": {"bn": "দ্বিতীয় রাকাতে কিরাতের পর তিন তাকবির", "en": "Second rak''ah: three takbirs after recitation"}, "text": {"bn": "দ্বিতীয় রাকাতে ইমাম আগে কিরাত পড়বেন। তারপর তিনবার তাকবির, প্রতিবার কান পর্যন্ত হাত তুলে ছেড়ে দেবেন।", "en": "In the second rak''ah the imam recites first. Then three takbirs, each time raising the hands and letting them hang."}}, {"type": "step", "title": {"bn": "চতুর্থ তাকবিরে রুকু", "en": "Fourth takbir into ruku''"}, "text": {"bn": "চতুর্থবার হাত না তুলে ‘আল্লাহু আকবার’ বলে রুকুতে যান; তারপর সিজদা, বৈঠক ও সালাম দিয়ে নামাজ শেষ করুন।", "en": "On the fourth takbir go into ruku'' without raising the hands; then complete the sajdahs, sitting and salam."}}, {"type": "step", "title": {"bn": "খুতবা শোনা", "en": "Listen to the khutbah"}, "text": {"bn": "নামাজের পর ইমাম খুতবা দেবেন; চুপ করে শুনুন। ঈদের খুতবা শোনা সুন্নত।", "en": "After the prayer the imam gives the khutbah; listen quietly."}}, {"type": "note", "tone": "info", "text": {"bn": "সুন্নত হলো প্রথম রাকাতে সূরা আ''লা ও দ্বিতীয় রাকাতে সূরা গাশিয়া (সহিহ মুসলিম ৮৭৮), অথবা সূরা কাফ ও সূরা কামার (সহিহ মুসলিম ৮৯১) পড়া।", "en": "It is sunnah to recite al-A''la and al-Ghashiyah (Sahih Muslim 878), or Qaf and al-Qamar (Sahih Muslim 891)."}}, {"type": "differ", "title": {"bn": "অতিরিক্ত তাকবিরের সংখ্যা", "en": "Number of extra takbirs"}, "views": [{"label": {"bn": "হানাফি: মোট ছয়", "en": "Hanafi: six in total"}, "text": {"bn": "প্রথম রাকাতে সানার পর কিরাতের আগে তিন; দ্বিতীয় রাকাতে কিরাতের পর রুকুর আগে তিন।", "en": "Three in the first rak''ah after the thana and before recitation; three in the second after recitation and before ruku''."}, "evidence": {"bn": "আবু মুসা আশআরি ও হুযাইফা (রা.) বলেন, নবীজি (সা.) ঈদে জানাযার তাকবিরের মতো চার তাকবির দিতেন (তাকবিরে তাহরিমা/রুকুর তাকবিরসহ) (সুনান আবু দাউদ ১১৫৩); ইবনে মাসউদ (রা.)-এর আমলও এমন বর্ণিত।", "en": "Abu Musa and Hudhayfah said the Prophet made four takbirs on Eid like the funeral takbirs (counting the opening/ruku'' takbir) (Sunan Abi Dawud 1153); the same is reported from Ibn Mas''ud."}}, {"label": {"bn": "শাফেয়ি, মালেকি ও হাম্বলি: মোট বারো", "en": "Shafi''i, Maliki, Hanbali: twelve"}, "text": {"bn": "প্রথম রাকাতে কিরাতের আগে সাত (মালেকি ও হাম্বলিদের হিসাবে তাকবিরে তাহরিমাসহ, শাফেয়িদের হিসাবে তা বাদে), দ্বিতীয় রাকাতে কিরাতের আগে পাঁচ।", "en": "Seven before recitation in the first rak''ah (including the opening takbir for Maliki/Hanbali, excluding it for Shafi''i) and five before recitation in the second."}, "evidence": {"bn": "সুনান আবু দাউদ ১১৪৯ (আয়েশা রা.), ১১৫১ (আবদুল্লাহ ইবনে আমর রা.); জামে তিরমিজি ৫৩৬; সুনান ইবনে মাজাহ ১২৭৯।", "en": "Sunan Abi Dawud 1149 (''A''ishah), 1151 (''Abdullah ibn ''Amr); Jami'' al-Tirmidhi 536; Sunan Ibn Majah 1279."}}]}, {"type": "note", "tone": "tip", "text": {"bn": "যে ইমামের পেছনে পড়ছেন, তাকবিরের সংখ্যায় তাকে অনুসরণ করুন। দুটি পদ্ধতিই সাহাবিদের থেকে বর্ণিত।", "en": "Follow your imam in the number of takbirs; both ways are reported from the Companions."}}, {"type": "heading", "text": {"bn": "ঈদের দিনের সুন্নত", "en": "Sunnahs of Eid day"}}, {"type": "list", "items": [{"bn": "গোসল করা, সবচেয়ে ভালো কাপড় পরা, সুগন্ধি লাগানো", "en": "Bathe, wear your best clothes, use perfume"}, {"bn": "ঈদুল ফিতরে নামাজে যাওয়ার আগে বেজোড় সংখ্যক খেজুর বা কিছু খাওয়া (সহিহ বুখারি ৯৫৩)", "en": "On Eid al-Fitr, eat an odd number of dates before going (Sahih al-Bukhari 953)"}, {"bn": "ঈদুল আজহায় নামাজের আগে না খেয়ে নামাজের পর খাওয়া (জামে তিরমিজি ৫৪২)", "en": "On Eid al-Adha, eat after the prayer (Jami'' al-Tirmidhi 542)"}, {"bn": "ঈদুল ফিতরের নামাজের আগে সদকাতুল ফিতর আদায় করা", "en": "Pay zakat al-fitr before the Eid al-Fitr prayer"}, {"bn": "এক পথে যাওয়া, অন্য পথে ফেরা (সহিহ বুখারি ৯৮৬)", "en": "Go by one route and return by another (Sahih al-Bukhari 986)"}, {"bn": "ঈদগাহে যাওয়ার পথে তাকবির বলা; ইমাম আবু হানিফা (রহ.)-এর মতে ঈদুল ফিতরে নিচু স্বরে ও ঈদুল আজহায় উঁচু স্বরে, অন্য অনেক আলেমের মতে দুই ঈদেই উঁচু স্বরে", "en": "Say takbir on the way: per Imam Abu Hanifah quietly on Eid al-Fitr and aloud on Eid al-Adha; many other scholars say aloud on both"}]}, {"type": "heading", "text": {"bn": "তাকবিরে তাশরিক", "en": "Takbir al-tashriq"}}, {"type": "arabic", "label": {"bn": "তাকবিরে তাশরিক", "en": "Takbir al-tashriq"}, "ar": "اللّٰهُ أَكْبَرُ اللّٰهُ أَكْبَرُ، لَا إِلٰهَ إِلَّا اللّٰهُ، وَاللّٰهُ أَكْبَرُ اللّٰهُ أَكْبَرُ، وَلِلّٰهِ الْحَمْدُ", "pron": {"bn": "আল্লাহু আকবার আল্লাহু আকবার, লা ইলাহা ইল্লাল্লাহু, ওয়াল্লাহু আকবার আল্লাহু আকবার, ওয়া লিল্লাহিল হামদ।", "en": "Allahu akbar, Allahu akbar, la ilaha illallah, wallahu akbar, Allahu akbar, wa lillahil-hamd."}, "meaning": {"bn": "আল্লাহ সবচেয়ে বড়, আল্লাহ সবচেয়ে বড়; আল্লাহ ছাড়া কোনো ইলাহ নেই; আল্লাহ সবচেয়ে বড়, আল্লাহ সবচেয়ে বড়; আর সকল প্রশংসা আল্লাহরই।", "en": "Allah is the Greatest, Allah is the Greatest; there is no god but Allah; Allah is the Greatest, Allah is the Greatest, and all praise is for Allah."}, "ref": {"bn": "ইবনে মাসউদ (রা.) থেকে বর্ণিত, মুসান্নাফ ইবনে আবি শাইবা", "en": "Reported from Ibn Mas''ud, Musannaf Ibn Abi Shaybah"}, "check": true}, {"type": "text", "text": {"bn": "হানাফি মতে ৯ জিলহজের ফজর থেকে ১৩ জিলহজের আসর পর্যন্ত প্রত্যেক ফরজ নামাজের পর একবার এই তাকবির বলা ওয়াজিব; পুরুষেরা জোরে, নারীরা নিচু স্বরে বলবেন। অন্য মাজহাবে এটি সুন্নত, এবং সময়সীমা নিয়েও কিছু ভিন্নতা আছে।", "en": "In the Hanafi school it is wajib to say it once after every fard prayer from Fajr of 9 Dhul-Hijjah to ''Asr of the 13th; men aloud, women quietly. Other schools hold it sunnah, with some differences in the period."}}, {"type": "ref", "text": {"bn": "সূরা বাকারা ২:১৮৫, ২:২০৩ (নির্দিষ্ট দিনগুলোতে আল্লাহর জিকির)", "en": "Al-Baqarah 2:185, 2:203 (remember Allah on the appointed days)"}}]', 'in_review', 20 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'f48a3402-e858-5dd4-ae74-7c0d7c3a3df5', id, 'witr-prayer', '{"bn": "বিতরের নামাজ ও দোয়া কুনুত", "en": "Witr Prayer and Du''a Qunut"}', '{"bn": "ইশার পর থেকে ফজর পর্যন্ত সময়ের বিতর নামাজ: হুকুম, পড়ার পদ্ধতি নিয়ে মতভেদ, আর দুই রকম দোয়া কুনুত।", "en": "Witr, prayed between ''Isha and Fajr: its ruling, the different methods, and the two forms of du''a qunut."}', 'basic', '[{"type": "text", "text": {"bn": "বিতর মানে বেজোড়। রাতের নামাজ বিতর দিয়ে শেষ করতে নবীজি (সা.) বলেছেন: ‘রাতে তোমাদের শেষ নামাজ বিতর বানাও’ (সহিহ বুখারি ৯৯৮)। সময়: ইশার নামাজের পর থেকে সুবহে সাদিক পর্যন্ত।", "en": "Witr means ''odd''. The Prophet said: ''Make witr your last prayer at night'' (Sahih al-Bukhari 998). Time: after ''Isha until dawn."}}, {"type": "differ", "title": {"bn": "বিতরের হুকুম", "en": "Ruling of witr"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "বিতর ওয়াজিব; ছুটে গেলে কাজা করতে হয়।", "en": "Witr is wajib; if missed it must be made up."}, "evidence": {"bn": "‘বিতর প্রত্যেক মুসলিমের ওপর হক’ (সুনান আবু দাউদ ১৪২২); নবীজি (সা.) সফরেও বিতর ছাড়তেন না।", "en": "''Witr is a duty (haqq) on every Muslim'' (Sunan Abi Dawud 1422); the Prophet kept it even when travelling."}}, {"label": {"bn": "শাফেয়ি, মালেকি ও হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "বিতর সুন্নতে মুয়াক্কাদা, খুব গুরুত্বপূর্ণ সুন্নত।", "en": "A strongly emphasised sunnah."}, "evidence": {"bn": "পাঁচ ওয়াক্তের বাইরে আর কিছু ফরজ কি না জিজ্ঞেস করলে নবীজি (সা.) বললেন, ‘না, তবে নফল হিসেবে করতে পারো’ (সহিহ বুখারি ৪৬)।", "en": "Asked if anything beyond the five prayers was obligatory, the Prophet said, ''No, unless you do it voluntarily'' (Sahih al-Bukhari 46)."}}]}, {"type": "heading", "text": {"bn": "হানাফি পদ্ধতি: তিন রাকাত, এক সালাম", "en": "Hanafi method: three rak''ahs, one salam"}}, {"type": "step", "title": {"bn": "প্রথম দুই রাকাত", "en": "First two rak''ahs"}, "text": {"bn": "সাধারণ নামাজের মতো দুই রাকাত পড়ুন; প্রতি রাকাতে সূরা ফাতিহার সাথে আরেকটি সূরা। দ্বিতীয় রাকাতের পর বসে শুধু আত্তাহিয়্যাতু পড়ে দাঁড়িয়ে যান।", "en": "Pray two rak''ahs like any prayer, with al-Fatihah and a surah in each. After the second, sit for tashahhud only and stand up."}}, {"type": "step", "title": {"bn": "তৃতীয় রাকাতে কিরাত", "en": "Third rak''ah recitation"}, "text": {"bn": "তৃতীয় রাকাতেও সূরা ফাতিহা ও আরেকটি সূরা পড়ুন।", "en": "Recite al-Fatihah and a surah in the third rak''ah too."}}, {"type": "step", "title": {"bn": "কুনুতের তাকবির", "en": "Takbir for qunut"}, "text": {"bn": "কিরাত শেষে রুকুতে না গিয়ে কান পর্যন্ত হাত তুলে ‘আল্লাহু আকবার’ বলুন, তারপর আবার হাত বাঁধুন।", "en": "After the recitation, before ruku'', raise your hands to the ears saying ''Allahu Akbar'', then fold them again."}}, {"type": "step", "title": {"bn": "দোয়া কুনুত", "en": "Du''a qunut"}, "text": {"bn": "নিচের দোয়া কুনুত চুপে চুপে পড়ুন। তারপর রুকু, সিজদা, শেষ বৈঠক ও সালাম দিয়ে শেষ করুন।", "en": "Recite the du''a qunut below quietly, then ruku'', sajdahs, the final sitting and salam."}}, {"type": "note", "tone": "tip", "text": {"bn": "দোয়া কুনুত মুখস্থ না থাকলে শেখা পর্যন্ত ‘রাব্বানা আতিনা ফিদ্দুনইয়া হাসানাতাও ওয়া ফিল আখিরাতি হাসানাতাও ওয়া কিনা আযাবান নার’ বা ‘আল্লাহুম্মাগফির লী’ তিনবার পড়া যায়। হানাফি মতে কুনুত ভুলে রুকুতে চলে গেলে আর ফিরে আসবেন না; শেষে সাহু সিজদা দেবেন।", "en": "Until you learn it, you may say ''Rabbana atina fid-dunya hasanah...'' or ''Allahummaghfir li'' three times. In the Hanafi school, if you forget qunut and go into ruku'', do not return; make sajdah al-sahw at the end."}}, {"type": "arabic", "label": {"bn": "দোয়া কুনুত (হানাফি আমলে প্রচলিত)", "en": "Du''a qunut (used in Hanafi practice)"}, "ar": "اللّٰهُمَّ إِنَّا نَسْتَعِينُكَ وَنَسْتَغْفِرُكَ، وَنُؤْمِنُ بِكَ وَنَتَوَكَّلُ عَلَيْكَ، وَنُثْنِي عَلَيْكَ الْخَيْرَ، وَنَشْكُرُكَ وَلَا نَكْفُرُكَ، وَنَخْلَعُ وَنَتْرُكُ مَنْ يَفْجُرُكَ. اللّٰهُمَّ إِيَّاكَ نَعْبُدُ، وَلَكَ نُصَلِّي وَنَسْجُدُ، وَإِلَيْكَ نَسْعَىٰ وَنَحْفِدُ، وَنَرْجُو رَحْمَتَكَ، وَنَخْشَىٰ عَذَابَكَ، إِنَّ عَذَابَكَ بِالْكُفَّارِ مُلْحِقٌ", "pron": {"bn": "আল্লাহুম্মা ইন্না নাসতাঈনুকা ওয়া নাসতাগফিরুকা, ওয়া নু''মিনু বিকা ওয়া নাতাওয়াক্কালু আলাইকা, ওয়া নুসনী আলাইকাল খাইর, ওয়া নাশকুরুকা ওয়া লা নাকফুরুকা, ওয়া নাখলাউ ওয়া নাতরুকু মাই ইয়াফজুরুক। আল্লাহুম্মা ইয়্যাকা না''বুদু, ওয়া লাকা নুসাল্লী ওয়া নাসজুদু, ওয়া ইলাইকা নাস''আ ওয়া নাহফিদু, ওয়া নারজূ রাহমাতাকা, ওয়া নাখশা আযাবাকা, ইন্না আযাবাকা বিলকুফফারি মুলহিক।", "en": "Allahumma inna nasta''inuka wa nastaghfiruka, wa nu''minu bika wa natawakkalu ''alayka, wa nuthni ''alaykal-khayr, wa nashkuruka wa la nakfuruka, wa nakhla''u wa natruku man yafjuruk. Allahumma iyyaka na''budu, wa laka nusalli wa nasjudu, wa ilayka nas''a wa nahfidu, wa narju rahmataka, wa nakhsha ''adhabaka, inna ''adhabaka bil-kuffari mulhiq."}, "meaning": {"bn": "হে আল্লাহ, আমরা তোমার কাছে সাহায্য চাই ও ক্ষমা চাই, তোমার প্রতি ঈমান আনি ও তোমার ওপর ভরসা করি, তোমার উত্তম প্রশংসা করি, তোমার শোকর করি, অকৃতজ্ঞ হই না; যে তোমার অবাধ্যতা করে, তার থেকে আমরা সম্পর্ক ছিন্ন করি ও তাকে ছেড়ে দিই। হে আল্লাহ, আমরা কেবল তোমারই ইবাদত করি, তোমারই জন্য নামাজ পড়ি ও সিজদা করি, তোমারই দিকে ছুটে যাই ও তৎপর থাকি; তোমার রহমতের আশা করি ও তোমার শাস্তিকে ভয় করি। নিশ্চয়ই তোমার শাস্তি কাফেরদের পেয়ে বসবে।", "en": "O Allah, we seek Your help and Your forgiveness, we believe in You and rely on You, we praise You with all good, we thank You and are not ungrateful, and we cast off and leave whoever disobeys You. O Allah, You alone we worship, to You we pray and prostrate, to You we hasten and strive; we hope for Your mercy and fear Your punishment. Surely Your punishment will overtake the disbelievers."}, "ref": {"bn": "উমর (রা.) থেকে বর্ণিত: মুসান্নাফ ইবনে আবি শাইবা; আস-সুনানুল কুবরা, বায়হাকি", "en": "Reported from ''Umar: Musannaf Ibn Abi Shaybah; al-Sunan al-Kubra of al-Bayhaqi"}, "check": true}, {"type": "arabic", "label": {"bn": "দোয়া কুনুত (হাসান ইবনে আলী রা.-কে শেখানো)", "en": "Du''a qunut (taught to al-Hasan ibn ''Ali)"}, "ar": "اللّٰهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ، وَعَافِنِي فِيمَنْ عَافَيْتَ، وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لِي فِيمَا أَعْطَيْتَ، وَقِنِي شَرَّ مَا قَضَيْتَ، إِنَّكَ تَقْضِي وَلَا يُقْضَىٰ عَلَيْكَ، وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ، تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ", "pron": {"bn": "আল্লাহুম্মাহদিনী ফীমান হাদাইতা, ওয়া আফিনী ফীমান আফাইতা, ওয়া তাওয়াল্লানী ফীমান তাওয়াল্লাইতা, ওয়া বারিক লী ফীমা আ''তাইতা, ওয়া কিনী শাররা মা কাদাইতা, ইন্নাকা তাকদী ওয়া লা ইউকদা আলাইকা, ওয়া ইন্নাহু লা ইয়াযিল্লু মাও ওয়ালাইতা, ওয়া লা ইয়াইযযু মান আদাইতা, তাবারাকতা রাব্বানা ওয়া তাআলাইতা।", "en": "Allahummahdini fiman hadayta, wa ''afini fiman ''afayta, wa tawallani fiman tawallayta, wa barik li fima a''tayta, wa qini sharra ma qadayta, innaka taqdi wa la yuqda ''alayka, wa innahu la yadhillu man walayta, wa la ya''izzu man ''adayta, tabarakta Rabbana wa ta''alayta."}, "meaning": {"bn": "হে আল্লাহ, যাদের তুমি হেদায়াত দিয়েছ, তাদের সাথে আমাকেও হেদায়াত দাও; যাদের নিরাপত্তা দিয়েছ, তাদের সাথে আমাকেও নিরাপত্তা দাও; যাদের অভিভাবকত্ব নিয়েছ, তাদের সাথে আমারও অভিভাবক হও; যা দিয়েছ তাতে বরকত দাও; আর তোমার ফয়সালার মন্দ থেকে আমাকে রক্ষা করো। তুমিই ফয়সালা করো, তোমার ওপর কেউ ফয়সালা করতে পারে না। তুমি যার বন্ধু হও সে অপমানিত হয় না, আর যার শত্রু হও সে সম্মানিত হয় না। হে আমাদের রব, তুমি বরকতময় ও সুউচ্চ।", "en": "O Allah, guide me among those You have guided, grant me well-being among those You have granted well-being, take me into Your care among those You have taken into Your care, bless me in what You have given, and protect me from the evil of what You have decreed. You decree and none decrees over You. Whoever You befriend is never humbled, and whoever You oppose is never honoured. Blessed are You, our Lord, and Exalted."}, "ref": {"bn": "সুনান আবু দাউদ ১৪২৫; জামে তিরমিজি ৪৬৪; সুনান নাসায়ি ১৭৪৫", "en": "Sunan Abi Dawud 1425; Jami'' al-Tirmidhi 464; Sunan al-Nasa''i 1745"}}, {"type": "text", "text": {"bn": "দুটি দোয়াই পড়া যায়। হানাফিরা সাধারণত প্রথমটি পড়েন; শাফেয়ি ও হাম্বলিরা সাধারণত দ্বিতীয়টি।", "en": "Either may be recited. Hanafis usually recite the first; Shafi''is and Hanbalis usually the second."}}, {"type": "differ", "title": {"bn": "বিতরের রাকাত সংখ্যা ও পদ্ধতি", "en": "Number of rak''ahs and method"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "বিতর তিন রাকাত, দ্বিতীয় রাকাতে বৈঠক, শেষে এক সালাম (মাগরিবের মতো, তবে তিন রাকাতেই সূরা মেলাতে হয়)। কুনুত তৃতীয় রাকাতে রুকুর আগে, সারা বছর।", "en": "Three rak''ahs with a sitting after the second and one salam at the end (like Maghrib, but with a surah in all three). Qunut in the third rak''ah before ruku'', all year."}, "evidence": {"bn": "উবাই ইবনে কা''ব (রা.): নবীজি (সা.) তিন রাকাত বিতর পড়তেন, রুকুর আগে কুনুত পড়তেন (সুনান নাসায়ি ১৬৯৯); আয়েশা (রা.)-এর বর্ণনায় ‘তারপর তিন রাকাত’ (সহিহ বুখারি ১১৪৭)।", "en": "Ubayy ibn Ka''b: the Prophet prayed three rak''ahs of witr and made qunut before ruku'' (Sunan al-Nasa''i 1699); ''A''ishah: ''then he prayed three'' (Sahih al-Bukhari 1147)."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি", "en": "Shafi''i and Hanbali"}, "text": {"bn": "সর্বনিম্ন এক রাকাত; তিন, পাঁচ, সাত, নয় বা এগারোও পড়া যায়। তিন রাকাত পড়লে উত্তম হলো দুই রাকাত পড়ে সালাম ফিরিয়ে আলাদা এক রাকাত পড়া, অথবা তিন রাকাত একটানা শেষে এক বৈঠকে। শাফেয়ি মতে কুনুত রমজানের শেষ অর্ধেকে রুকুর পরে; হাম্বলি মতে সারা বছর রুকুর পরে।", "en": "Minimum one rak''ah; also 3, 5, 7, 9 or 11. For three, preferably two then salam then one, or three together with one sitting at the end. Shafi''i: qunut after ruku'' in the second half of Ramadan; Hanbali: after ruku'' all year."}, "evidence": {"bn": "‘রাতের নামাজ দুই দুই রাকাত; ফজরের আশঙ্কা হলে এক রাকাত বিতর পড়ো’ (সহিহ বুখারি ৯৯০); ‘বিতর শেষ রাতে এক রাকাত’ (সহিহ মুসলিম ৭৫২); ‘কেউ চাইলে পাঁচ, তিন বা এক রাকাত বিতর পড়ুক’ (সুনান আবু দাউদ ১৪২২)।", "en": "''Night prayer is two by two; if you fear dawn, pray one as witr'' (Sahih al-Bukhari 990); ''Witr is one rak''ah at the end of the night'' (Sahih Muslim 752); ''whoever wishes, five, three or one'' (Sunan Abi Dawud 1422)."}}, {"label": {"bn": "মালেকি", "en": "Maliki"}, "text": {"bn": "দুই রাকাত (শাফা'') পড়ে সালাম ফিরিয়ে তারপর এক রাকাত বিতর।", "en": "Two rak''ahs (shaf''), salam, then one rak''ah of witr."}, "evidence": {"bn": "সহিহ বুখারি ৯৯০; সহিহ মুসলিম ৭৫২।", "en": "Sahih al-Bukhari 990; Sahih Muslim 752."}}]}, {"type": "heading", "text": {"bn": "বিতরের সুন্নত", "en": "Sunnahs of witr"}}, {"type": "list", "items": [{"bn": "তিন রাকাতে পর্যায়ক্রমে সূরা আ''লা, সূরা কাফিরুন ও সূরা ইখলাস পড়া (জামে তিরমিজি ৪৬২; সুনান নাসায়ি ১৬৯৯)", "en": "Recite al-A''la, al-Kafirun and al-Ikhlas in the three rak''ahs (Jami'' al-Tirmidhi 462; Sunan al-Nasa''i 1699)"}, {"bn": "শেষ রাতে উঠতে পারার ভরসা থাকলে তাহাজ্জুদের পরে বিতর পড়া উত্তম; না থাকলে ঘুমানোর আগে পড়ে নেওয়া (সহিহ মুসলিম ৭৫৫)", "en": "If you trust you will wake, pray witr at the end of the night after tahajjud; otherwise before sleeping (Sahih Muslim 755)"}, {"bn": "সালামের পর তিনবার ‘সুবহানাল মালিকিল কুদ্দুস’ বলা, তৃতীয়বার একটু টেনে (সুনান নাসায়ি ১৬৯৯)", "en": "After salam say ''Subhanal-Malikil-Quddus'' three times, lengthening the third (Sunan al-Nasa''i 1699)"}]}, {"type": "arabic", "label": {"bn": "বিতরের পর", "en": "After witr"}, "ar": "سُبْحَانَ الْمَلِكِ الْقُدُّوسِ", "pron": {"bn": "সুবহানাল মালিকিল কুদ্দুস (তিনবার)", "en": "Subhanal-Malikil-Quddus (three times)"}, "meaning": {"bn": "পবিত্র মহান সেই অধিপতি, যিনি সব দোষ থেকে মুক্ত।", "en": "Glory be to the King, the Most Holy."}, "ref": {"bn": "সুনান আবু দাউদ ১৪৩০; সুনান নাসায়ি ১৬৯৯", "en": "Sunan Abi Dawud 1430; Sunan al-Nasa''i 1699"}}]', 'in_review', 30 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'f4c7a4de-3f76-5693-9fb1-f8a04cc35cc0', id, 'tarawih-prayer', '{"bn": "তারাবির নামাজ", "en": "Tarawih Prayer"}', '{"bn": "রমজানের রাতের বিশেষ নামাজ তারাবি: ফজিলত, পড়ার নিয়ম এবং রাকাত সংখ্যা নিয়ে আলেমদের মত।", "en": "The special night prayer of Ramadan: its virtue, how to pray it, and the scholarly views on its number of rak''ahs."}', 'basic', '[{"type": "text", "text": {"bn": "তারাবি রমজানের রাতে ইশার ফরজ ও সুন্নতের পর এবং বিতরের আগে পড়া হয়। এটি সুন্নতে মুয়াক্কাদা; জামাতে পড়া উত্তম। দুই দুই রাকাত করে পড়া হয়, আর প্রতি চার রাকাত পর একটু বিশ্রাম (তারবিহা) নেওয়া হয়; এ থেকেই নাম ‘তারাবি’।", "en": "Tarawih is prayed in Ramadan after ''Isha (fard and sunnah) and before witr. It is a confirmed sunnah, best in congregation, prayed two rak''ahs at a time with a short rest (tarwihah) after every four, hence the name."}}, {"type": "arabic", "label": {"bn": "ফজিলত", "en": "Virtue"}, "ar": "مَنْ قَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ", "pron": {"bn": "মান কামা রামাদানা ঈমানান ওয়াহতিসাবান গুফিরা লাহু মা তাকাদ্দামা মিন যামবিহ।", "en": "Man qama Ramadana imanan wahtisaban ghufira lahu ma taqaddama min dhanbih."}, "meaning": {"bn": "যে ব্যক্তি ঈমানের সাথে ও সওয়াবের আশায় রমজানের রাতে নামাজে দাঁড়ায়, তার আগের গুনাহ ক্ষমা করে দেওয়া হয়।", "en": "Whoever stands (in prayer) in Ramadan with faith and seeking reward, his previous sins are forgiven."}, "ref": {"bn": "সহিহ বুখারি ৩৭", "en": "Sahih al-Bukhari 37"}}, {"type": "heading", "text": {"bn": "ইতিহাস", "en": "History"}}, {"type": "text", "text": {"bn": "নবীজি (সা.) কয়েক রাত মসজিদে জামাতে রাতের নামাজ পড়েছেন, তারপর ফরজ হয়ে যাওয়ার আশঙ্কায় আর বের হননি (সহিহ বুখারি ২০১২)। পরে উমর (রা.) সবাইকে উবাই ইবনে কা''ব (রা.)-এর পেছনে এক জামাতে একত্র করেন (সহিহ বুখারি ২০১০)।", "en": "The Prophet led the night prayer in congregation for a few nights, then stopped, fearing it would be made obligatory (Sahih al-Bukhari 2012). Later ''Umar gathered the people behind Ubayy ibn Ka''b in one congregation (Sahih al-Bukhari 2010)."}}, {"type": "differ", "title": {"bn": "তারাবি কত রাকাত", "en": "How many rak''ahs"}, "views": [{"label": {"bn": "২০ রাকাত (হানাফি, শাফেয়ি, হাম্বলি)", "en": "20 rak''ahs (Hanafi, Shafi''i, Hanbali)"}, "text": {"bn": "বিতর ছাড়া ২০ রাকাত, দুই দুই করে দশ সালামে। বাংলাদেশের মসজিদগুলোতে এটিই প্রচলিত।", "en": "Twenty rak''ahs besides witr, in ten pairs. This is the common practice in Bangladesh''s mosques."}, "evidence": {"bn": "উমর (রা.)-এর যুগে মানুষ ২০ রাকাত পড়তেন বলে সাইব ইবনে ইয়াজিদ (রা.) থেকে বায়হাকি বর্ণনা করেছেন; মুয়াত্তা মালিকে ইয়াজিদ ইবনে রুমান থেকে ২৩ রাকাত (বিতরসহ) বর্ণিত। পরবর্তী উম্মাহর ব্যাপক আমল।", "en": "Al-Bayhaqi reports from al-Sa''ib ibn Yazid that people prayed 20 in ''Umar''s time; the Muwatta'' reports 23 (with witr) from Yazid ibn Ruman. Widespread later practice of the ummah."}}, {"label": {"bn": "৮ রাকাত", "en": "8 rak''ahs"}, "text": {"bn": "বিতর ছাড়া ৮ রাকাত (বিতরসহ ১১)।", "en": "Eight rak''ahs plus witr (eleven in total)."}, "evidence": {"bn": "আয়েশা (রা.): নবীজি (সা.) রমজানে ও অন্য সময়ে রাতে এগারো রাকাতের বেশি পড়তেন না (সহিহ বুখারি ১১৪৭); মুয়াত্তা মালিকে উমর (রা.) উবাই ও তামিম দারি (রা.)-কে এগারো রাকাত পড়াতে বলেছিলেন।", "en": "''A''ishah: the Prophet did not exceed eleven rak''ahs at night, in Ramadan or otherwise (Sahih al-Bukhari 1147); the Muwatta'' reports ''Umar telling Ubayy and Tamim al-Dari to lead eleven."}}, {"label": {"bn": "নির্দিষ্ট সংখ্যা নেই", "en": "No fixed number"}, "text": {"bn": "ইমাম মালিক (রহ.)-এর মতে মদিনাবাসীর আমলে ৩৬ রাকাত। অনেক আলেমের মতে রাতের নফল নামাজের নির্দিষ্ট সীমা নেই; কেউ কম রাকাত লম্বা করে, কেউ বেশি রাকাত ছোট করে পড়তে পারে।", "en": "Imam Malik reported 36 as the practice of Madinah. Many scholars say night prayer has no fixed limit: fewer long rak''ahs or more short ones."}, "evidence": {"bn": "‘রাতের নামাজ দুই দুই রাকাত’ (সহিহ বুখারি ৯৯০), এখানে কোনো সংখ্যা বেঁধে দেওয়া হয়নি।", "en": "''Night prayer is two by two'' (Sahih al-Bukhari 990), with no number fixed."}}], "check": true}, {"type": "note", "tone": "tip", "text": {"bn": "যে মসজিদে যে নিয়ম, সেখানে ইমামের সাথে শেষ পর্যন্ত পড়াই উত্তম। নবীজি (সা.) বলেছেন, যে ইমামের সাথে তিনি শেষ করা পর্যন্ত দাঁড়ায়, তার জন্য পুরো রাত নামাজের সওয়াব লেখা হয় (জামে তিরমিজি ৮০৬)। তারাবির রাকাত নিয়ে বিবাদ করা উচিত নয়।", "en": "Pray with your mosque''s imam until he finishes. The Prophet said whoever stands with the imam until he finishes gets the reward of the whole night (Jami'' al-Tirmidhi 806). Do not quarrel over the number."}}, {"type": "heading", "text": {"bn": "নিয়ম", "en": "How to pray"}}, {"type": "step", "title": {"bn": "নিয়ত", "en": "Intention"}, "text": {"bn": "মনে মনে নিয়ত করুন যে তারাবির দুই রাকাত সুন্নত পড়ছি; মুখে বলা জরুরি নয়।", "en": "Intend in your heart to pray two rak''ahs of tarawih; saying it aloud is not required."}}, {"type": "step", "title": {"bn": "দুই দুই রাকাত", "en": "Two by two"}, "text": {"bn": "সাধারণ দুই রাকাত সুন্নতের মতো পড়ে সালাম ফেরান।", "en": "Pray like any two-rak''ah sunnah and end with salam."}}, {"type": "step", "title": {"bn": "প্রতি চার রাকাত পর বিশ্রাম", "en": "Rest after every four"}, "text": {"bn": "চার রাকাত পরপর একটু বসে বিশ্রাম নিন; এ সময় তাসবিহ, দরুদ, ইস্তিগফার বা কুরআন পড়তে পারেন।", "en": "Sit and rest after every four rak''ahs; you may make tasbih, durood, istighfar or recite Quran."}}, {"type": "step", "title": {"bn": "শেষে বিতর", "en": "Witr at the end"}, "text": {"bn": "রমজানে বিতর জামাতের সাথে পড়া যায়।", "en": "In Ramadan, witr may be prayed in congregation."}}, {"type": "note", "tone": "info", "text": {"bn": "চার রাকাত পরপর পড়ার জন্য ‘সুবহানা যিল মুলকি ওয়াল মালাকুত...’ নামে যে দোয়া প্রচলিত, তা কোনো হাদিসে তারাবির জন্য নির্দিষ্ট করে বর্ণিত হয়নি। এই বিরতিতে যেকোনো জিকির করা যায়; নির্দিষ্ট দোয়াকে জরুরি মনে করবেন না।", "en": "The popular ''Subhana dhil-mulki wal-malakut...'' recited between sets is not narrated specifically for tarawih in any hadith. Any dhikr is fine in the pause; do not treat a particular one as required."}}, {"type": "text", "text": {"bn": "হানাফি মতে রমজানে তারাবিতে অন্তত একবার পুরো কুরআন খতম করা সুন্নত। জামাতে না পারলে ঘরে একা বা পরিবারের সাথে তারাবি পড়া যায়।", "en": "In the Hanafi school, completing the whole Quran once in tarawih during Ramadan is sunnah. If you cannot attend the mosque, pray it at home alone or with family."}}]', 'in_review', 40 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '46afea9c-9492-56ab-842d-61fec65e7d32', id, 'tahajjud-prayer', '{"bn": "তাহাজ্জুদের নামাজ", "en": "Tahajjud (Night) Prayer"}', '{"bn": "ফরজের পর সবচেয়ে মর্যাদাপূর্ণ নামাজ তাহাজ্জুদ: সময়, রাকাত, নিয়ম ও শেষ রাতের দোয়া।", "en": "The most virtuous prayer after the obligatory ones: its time, rak''ahs, method and the value of the last third of the night."}', 'basic', '[{"type": "arabic", "ar": "وَمِنَ اللَّيْلِ فَتَهَجَّدْ بِهِ نَافِلَةً لَكَ عَسَىٰ أَنْ يَبْعَثَكَ رَبُّكَ مَقَامًا مَحْمُودًا", "pron": {"bn": "ওয়া মিনাল লাইলি ফাতাহাজ্জাদ বিহী নাফিলাতাল লাক, আসা আই ইয়াবআসাকা রাব্বুকা মাকামাম মাহমূদা।", "en": "Wa minal-layli fatahajjad bihi nafilatal lak, ''asa ay yab''athaka Rabbuka maqamam mahmuda."}, "meaning": {"bn": "আর রাতের কিছু অংশে তাহাজ্জুদ পড়ো; এটি তোমার জন্য অতিরিক্ত। আশা করা যায়, তোমার রব তোমাকে প্রশংসিত স্থানে পৌঁছাবেন।", "en": "And in part of the night, pray tahajjud as an extra for you; perhaps your Lord will raise you to a praised station."}, "ref": {"bn": "সূরা ইসরা ১৭:৭৯", "en": "Al-Isra 17:79"}}, {"type": "list", "items": [{"bn": "‘রমজানের পর সর্বোত্তম রোজা মুহাররমের রোজা, আর ফরজের পর সর্বোত্তম নামাজ রাতের নামাজ’ (সহিহ মুসলিম ১১৬৩)।", "en": "''The best prayer after the obligatory is the night prayer'' (Sahih Muslim 1163)."}, {"bn": "প্রতি রাতের শেষ তৃতীয়াংশে আল্লাহ নিকটতম আসমানে নেমে বলেন: কে আমাকে ডাকবে, আমি সাড়া দেব; কে চাইবে, আমি দেব; কে ক্ষমা চাইবে, আমি ক্ষমা করব (সহিহ বুখারি ১১৪৫)।", "en": "In the last third of every night Allah descends to the lowest heaven and says: who calls Me that I may answer, who asks Me that I may give, who seeks forgiveness that I may forgive (Sahih al-Bukhari 1145)."}]}, {"type": "heading", "text": {"bn": "সময়", "en": "Time"}}, {"type": "text", "text": {"bn": "ইশার পর থেকে সুবহে সাদিক পর্যন্ত যেকোনো সময় পড়া যায়। ঘুম থেকে উঠে পড়া এবং রাতের শেষ তৃতীয়াংশে পড়া সবচেয়ে উত্তম। উঠতে না পারার আশঙ্কা থাকলে ঘুমানোর আগে কিছু নফল পড়ে বিতর পড়ে নিন।", "en": "Any time after ''Isha until dawn. Best after sleeping and in the last third of the night. If you fear not waking, pray some nafl and witr before sleeping."}}, {"type": "heading", "text": {"bn": "রাকাত সংখ্যা", "en": "Number of rak''ahs"}}, {"type": "text", "text": {"bn": "সর্বনিম্ন দুই রাকাত। নবীজি (সা.) সাধারণত বিতরসহ এগারো রাকাত (সহিহ বুখারি ১১৪৭), কখনো তেরো রাকাত (সহিহ বুখারি ১১৩৮) পড়তেন। নির্দিষ্ট কোনো সীমা নেই; সামর্থ্য অনুযায়ী পড়ুন।", "en": "Minimum two rak''ahs. The Prophet usually prayed eleven including witr (Sahih al-Bukhari 1147), sometimes thirteen (Sahih al-Bukhari 1138). There is no fixed limit; pray as you are able."}}, {"type": "heading", "text": {"bn": "নিয়ম", "en": "Method"}}, {"type": "step", "title": {"bn": "ওযু ও নিয়ত", "en": "Wudu and intention"}, "text": {"bn": "ওযু করে মনে মনে তাহাজ্জুদের নিয়ত করুন।", "en": "Make wudu and intend tahajjud in your heart."}}, {"type": "step", "title": {"bn": "হালকা দুই রাকাত দিয়ে শুরু", "en": "Begin with two light rak''ahs"}, "text": {"bn": "নবীজি (সা.) রাতের নামাজ দুই হালকা রাকাত দিয়ে শুরু করতে বলেছেন (সহিহ মুসলিম ৭৬৮)।", "en": "The Prophet advised starting the night prayer with two light rak''ahs (Sahih Muslim 768)."}}, {"type": "step", "title": {"bn": "দুই দুই রাকাত করে", "en": "Two at a time"}, "text": {"bn": "সাধারণ নফল নামাজের মতো দুই দুই রাকাত করে পড়ুন; যেকোনো সূরা পড়া যায়, লম্বা কিরাত ও লম্বা সিজদা উত্তম (সহিহ বুখারি ৯৯০)।", "en": "Pray two rak''ahs at a time like any nafl; any surah is fine; long recitation and sajdah are better (Sahih al-Bukhari 990)."}}, {"type": "step", "title": {"bn": "বিতর দিয়ে শেষ", "en": "End with witr"}, "text": {"bn": "আগে বিতর না পড়ে থাকলে শেষে বিতর পড়ুন (সহিহ বুখারি ৯৯৮)।", "en": "If you have not yet prayed witr, end with it (Sahih al-Bukhari 998)."}}, {"type": "step", "title": {"bn": "দোয়া ও ইস্তিগফার", "en": "Dua and istighfar"}, "text": {"bn": "এ সময় দোয়া কবুলের আশা বেশি; নিজের ভাষায় মন খুলে দোয়া ও ক্ষমা চান।", "en": "This is a time of hope for acceptance; ask and seek forgiveness in your own words."}}, {"type": "note", "tone": "tip", "text": {"bn": "মুখে নিয়ত বলা জরুরি নয়। উদাহরণ (প্রচলিত বাংলা): ‘আমি আল্লাহর জন্য দুই রাকাত তাহাজ্জুদ নামাজ পড়ছি।’ নিয়মিত অল্প পড়া, মাঝে মাঝে বেশি পড়ার চেয়ে ভালো।", "en": "Saying the niyyah aloud is not required. Example (common Bangla phrasing): ''I am praying two rak''ahs of tahajjud for Allah.'' A little done regularly is better than a lot occasionally."}}, {"type": "ref", "text": {"bn": "আরও দেখুন: সূরা মুজ্জাম্মিল ৭৩:১–৬; সূরা সাজদা ৩২:১৬; সূরা যারিয়াত ৫১:১৭–১৮", "en": "See also: Al-Muzzammil 73:1–6; As-Sajdah 32:16; Adh-Dhariyat 51:17–18"}}]', 'in_review', 50 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '9aa54139-ead5-5352-9122-a889379b5f42', id, 'ishraq-duha-prayer', '{"bn": "ইশরাক ও চাশতের নামাজ", "en": "Ishraq and Duha Prayer"}', '{"bn": "সূর্য ওঠার পর থেকে দুপুরের আগ পর্যন্ত পড়া নফল নামাজ: ইশরাক, চাশত (দুহা) ও আওয়াবিন।", "en": "Voluntary prayer between sunrise and noon: ishraq, duha and salat al-awwabin."}', 'basic', '[{"type": "text", "text": {"bn": "সালাতুদ দুহা (চাশতের নামাজ) সূর্য ওঠার পর থেকে দুপুরে সূর্য মাথার ওপর আসার (জাওয়াল) একটু আগ পর্যন্ত পড়া যায়। অনেক আলেমের মতে এই সময়ের শুরুর দিকে, সূর্য ওঠার প্রায় ১৫–২০ মিনিট পর পড়া নামাজকেই ‘ইশরাক’ বলা হয়।", "en": "Salat al-duha is prayed from after sunrise until just before the sun reaches its zenith (zawal). Many scholars say the prayer at the start of this period, about 15–20 minutes after sunrise, is what is called ''ishraq''."}}, {"type": "heading", "text": {"bn": "ফজিলত", "en": "Virtue"}}, {"type": "list", "items": [{"bn": "মানুষের শরীরের প্রতিটি জোড়ার জন্য প্রতিদিন সদকা দেওয়া কর্তব্য; চাশতের দুই রাকাত নামাজ এর জন্য যথেষ্ট (সহিহ মুসলিম ৭২০)।", "en": "Every joint owes a charity each day, and two rak''ahs of duha suffice for it (Sahih Muslim 720)."}, {"bn": "আবু হুরায়রা (রা.)-কে নবীজি (সা.) তিনটি বিষয়ের ওসিয়ত করেছেন: প্রতি মাসে তিন রোজা, চাশতের দুই রাকাত এবং ঘুমের আগে বিতর (সহিহ বুখারি ১১৭৮)।", "en": "The Prophet advised Abu Hurayrah: three fasts a month, two rak''ahs of duha, and witr before sleeping (Sahih al-Bukhari 1178)."}, {"bn": "মক্কা বিজয়ের দিন নবীজি (সা.) চাশতের সময় আট রাকাত পড়েছেন (সহিহ বুখারি ১১৭৬; সহিহ মুসলিম ৩৩৬)।", "en": "On the day of the conquest of Makkah the Prophet prayed eight rak''ahs at duha time (Sahih al-Bukhari 1176; Sahih Muslim 336)."}]}, {"type": "heading", "text": {"bn": "রাকাত ও সময়", "en": "Rak''ahs and time"}}, {"type": "table", "head": [{"bn": "বিষয়", "en": "Item"}, {"bn": "বিবরণ", "en": "Details"}], "rows": [[{"bn": "রাকাত", "en": "Rak''ahs"}, {"bn": "সর্বনিম্ন ২; ৪, ৬ বা ৮ রাকাতও পড়া যায়, দুই দুই করে", "en": "Minimum 2; 4, 6 or 8 also, two at a time"}], [{"bn": "শুরুর সময়", "en": "Starts"}, {"bn": "সূর্য ওঠার প্রায় ১৫–২০ মিনিট পর (মাকরুহ সময় শেষ হলে)", "en": "About 15–20 minutes after sunrise (when the disliked time ends)"}], [{"bn": "উত্তম সময়", "en": "Best time"}, {"bn": "রোদ কিছুটা তেতে উঠলে, অর্থাৎ সকাল ও দুপুরের মাঝামাঝি", "en": "When the sun has grown hot, around mid-morning"}], [{"bn": "শেষ সময়", "en": "Ends"}, {"bn": "জাওয়ালের (ঠিক দুপুর) কিছুক্ষণ আগে", "en": "A little before zawal (true noon)"}]]}, {"type": "text", "text": {"bn": "‘আওয়াবিনের নামাজ হলো যখন উটের বাচ্চার পা গরম বালুতে পুড়তে থাকে’ (সহিহ মুসলিম ৭৪৮)। অর্থাৎ চাশতের সবচেয়ে উত্তম সময় হলো সকাল গড়িয়ে রোদ বেশ চড়া হলে।", "en": "''The prayer of the awwabin is when the young camels feel the heat of the sand'' (Sahih Muslim 748), i.e. the best duha time is mid-morning when the sun is hot."}}, {"type": "note", "tone": "info", "text": {"bn": "বাংলাদেশে অনেকে মাগরিবের পর ছয় রাকাত নফলকে ‘আওয়াবিন’ বলেন। মাগরিবের পর নফল পড়া ভালো কাজ, তবে এর বিশেষ ফজিলতের হাদিসগুলো দুর্বল; আর সহিহ হাদিসে ‘আওয়াবিনের নামাজ’ বলা হয়েছে চাশতের নামাজকে (সহিহ মুসলিম ৭৪৮)।", "en": "In Bangladesh many call six nafl rak''ahs after Maghrib ''awwabin''. Nafl after Maghrib is good, but the hadiths on its special reward are weak, and the sahih hadith uses ''prayer of the awwabin'' for duha (Sahih Muslim 748)."}}, {"type": "heading", "text": {"bn": "ইশরাকের ফজিলতের হাদিস", "en": "The hadith on ishraq"}}, {"type": "text", "text": {"bn": "আনাস (রা.) থেকে বর্ণিত: যে ব্যক্তি জামাতে ফজর পড়ে সূর্য ওঠা পর্যন্ত বসে আল্লাহর জিকির করে, তারপর দুই রাকাত নামাজ পড়ে, সে পূর্ণ হজ ও উমরার সওয়াব পায় (জামে তিরমিজি ৫৮৬)।", "en": "Anas reported: whoever prays Fajr in congregation, sits remembering Allah until sunrise, then prays two rak''ahs, has the reward of a complete Hajj and ''Umrah (Jami'' al-Tirmidhi 586)."}}, {"type": "note", "tone": "info", "text": {"bn": "ইমাম তিরমিজি এই হাদিসকে ‘হাসান গরিব’ বলেছেন। শাইখ আলবানিসহ কেউ কেউ একে হাসান বলেছেন, আবার কিছু মুহাদ্দিস সনদকে দুর্বল বলেছেন। আমলটি নিজে ভালো; তবে ফজিলত বর্ণনায় এই মতভেদ মনে রাখুন।", "en": "Al-Tirmidhi called it hasan gharib; al-Albani and others graded it hasan, while some scholars judged its chain weak. The practice itself is good; keep this grading difference in mind."}}, {"type": "note", "tone": "tip", "text": {"bn": "নিয়ত মনে মনে করাই যথেষ্ট। উদাহরণ (প্রচলিত বাংলা): ‘আমি আল্লাহর জন্য দুই রাকাত চাশতের নফল নামাজ পড়ছি।’", "en": "The intention in the heart is enough. Example (common Bangla phrasing): ''I am praying two rak''ahs of duha for Allah.''"}}]', 'in_review', 60 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '9dfc6cb5-b4df-534d-8fc7-4221275a1718', id, 'istikhara-prayer', '{"bn": "ইস্তিখারার নামাজ ও দোয়া", "en": "Istikhara Prayer and Du''a"}', '{"bn": "কোনো বৈধ কাজে সিদ্ধান্ত নিতে আল্লাহর কাছে কল্যাণ চাওয়ার সুন্নত পদ্ধতি: দুই রাকাত নামাজ ও পূর্ণ দোয়া।", "en": "The sunnah way to ask Allah for what is best before a permissible decision: two rak''ahs and the full du''a."}', 'basic', '[{"type": "text", "text": {"bn": "ইস্তিখারা মানে আল্লাহর কাছে কল্যাণ চাওয়া। বিয়ে, চাকরি, ব্যবসা, সফর ইত্যাদি যেকোনো বৈধ বিষয়ে কোনটি ভালো বুঝতে না পারলে ইস্তিখারা করা সুন্নত। জাবির (রা.) বলেন, নবীজি (সা.) আমাদের সব বিষয়ে ইস্তিখারা এমনভাবে শেখাতেন, যেমন কুরআনের সূরা শেখাতেন।", "en": "Istikhara means asking Allah for good. It is sunnah for any permissible matter you are unsure about: marriage, a job, business, travel. Jabir said the Prophet taught it for all matters as he taught a surah of the Quran."}}, {"type": "heading", "text": {"bn": "পদ্ধতি", "en": "Method"}}, {"type": "step", "title": {"bn": "ওযু", "en": "Wudu"}, "text": {"bn": "ভালোভাবে ওযু করুন।", "en": "Make wudu properly."}}, {"type": "step", "title": {"bn": "দুই রাকাত নফল", "en": "Two rak''ahs of nafl"}, "text": {"bn": "ফরজ ছাড়া দুই রাকাত নফল নামাজ পড়ুন। যেকোনো সূরা পড়া যায়; নির্দিষ্ট সূরা হাদিসে বর্ণিত নেই। মাকরুহ সময় এড়িয়ে চলুন।", "en": "Pray two non-obligatory rak''ahs. Any surah may be recited; no specific surah is narrated. Avoid the disliked times."}}, {"type": "step", "title": {"bn": "দোয়া", "en": "The du''a"}, "text": {"bn": "সালাম ফিরিয়ে আল্লাহর প্রশংসা ও দরুদ পড়ে নিচের দোয়াটি পড়ুন। ‘হাযাল আমরা’ (এই বিষয়টি) বলার সময় মনে মনে আপনার বিষয়টি স্মরণ করুন বা নাম উল্লেখ করুন।", "en": "After salam, praise Allah, send durood, then recite the du''a below. At ''hadhal-amra'' (this matter), name or bring to mind your matter."}}, {"type": "arabic", "label": {"bn": "ইস্তিখারার দোয়া", "en": "Du''a of istikhara"}, "ar": "اللّٰهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ، فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ، وَتَعْلَمُ وَلَا أَعْلَمُ، وَأَنْتَ عَلَّامُ الْغُيُوبِ. اللّٰهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هٰذَا الْأَمْرَ خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي، فَاقْدُرْهُ لِي وَيَسِّرْهُ لِي، ثُمَّ بَارِكْ لِي فِيهِ. وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هٰذَا الْأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي، فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ، وَاقْدُرْ لِيَ الْخَيْرَ حَيْثُ كَانَ، ثُمَّ أَرْضِنِي بِهِ", "pron": {"bn": "আল্লাহুম্মা ইন্নী আসতাখীরুকা বিইলমিকা, ওয়া আসতাকদিরুকা বিকুদরাতিকা, ওয়া আসআলুকা মিন ফাদলিকাল আযীম। ফাইন্নাকা তাকদিরু ওয়া লা আকদিরু, ওয়া তা''লামু ওয়া লা আ''লামু, ওয়া আনতা আল্লামুল গুয়ূব। আল্লাহুম্মা ইন কুনতা তা''লামু আন্না হাযাল আমরা খাইরুল লী ফী দীনী ওয়া মাআশী ওয়া আকিবাতি আমরী, ফাকদুরহু লী ওয়া ইয়াসসিরহু লী, সুম্মা বারিক লী ফীহ। ওয়া ইন কুনতা তা''লামু আন্না হাযাল আমরা শাররুল লী ফী দীনী ওয়া মাআশী ওয়া আকিবাতি আমরী, ফাসরিফহু আন্নী ওয়াসরিফনী আনহু, ওয়াকদুর লিয়াল খাইরা হাইসু কানা, সুম্মা আরদিনী বিহ।", "en": "Allahumma inni astakhiruka bi''ilmika, wa astaqdiruka biqudratika, wa as''aluka min fadlikal-''azim, fa innaka taqdiru wa la aqdiru, wa ta''lamu wa la a''lamu, wa anta ''allamul-ghuyub. Allahumma in kunta ta''lamu anna hadhal-amra khayrun li fi dini wa ma''ashi wa ''aqibati amri, faqdurhu li wa yassirhu li, thumma barik li fih. Wa in kunta ta''lamu anna hadhal-amra sharrun li fi dini wa ma''ashi wa ''aqibati amri, fasrifhu ''anni wasrifni ''anhu, waqdur liyal-khayra haythu kana, thumma ardini bih."}, "meaning": {"bn": "হে আল্লাহ, আমি তোমার জ্ঞানের ওসিলায় তোমার কাছে কল্যাণ চাই, তোমার কুদরতের ওসিলায় তোমার কাছে শক্তি চাই এবং তোমার মহান অনুগ্রহ প্রার্থনা করি। কারণ তুমি ক্ষমতা রাখো, আমি রাখি না; তুমি জানো, আমি জানি না; আর তুমি সকল অদৃশ্য বিষয়ে সম্যক জ্ঞাত। হে আল্লাহ, যদি তুমি জানো যে এই কাজটি আমার দ্বীন, আমার জীবন-জীবিকা ও আমার পরিণামের জন্য কল্যাণকর, তবে এটি আমার জন্য নির্ধারণ করো, সহজ করে দাও, তারপর এতে বরকত দাও। আর যদি জানো যে এই কাজটি আমার দ্বীন, জীবন-জীবিকা ও পরিণামের জন্য অকল্যাণকর, তবে এটিকে আমার থেকে ফিরিয়ে দাও এবং আমাকেও এ থেকে ফিরিয়ে রাখো; আর যেখানেই কল্যাণ থাকুক, তা আমার জন্য নির্ধারণ করো, তারপর তাতে আমাকে সন্তুষ্ট রাখো।", "en": "O Allah, I ask You for good through Your knowledge, and ask You for ability through Your power, and I ask You of Your great bounty; for You are able and I am not, You know and I do not, and You are the Knower of the unseen. O Allah, if You know this matter is good for me in my religion, my livelihood and the outcome of my affairs, then decree it for me, make it easy for me, and bless me in it. And if You know this matter is bad for me in my religion, my livelihood and the outcome of my affairs, then turn it away from me and turn me away from it, and decree for me the good wherever it may be, then make me content with it."}, "ref": {"bn": "সহিহ বুখারি ৬৩৮২ (জাবির রা.); একই হাদিস তাহাজ্জুদ অধ্যায়েও আছে", "en": "Sahih al-Bukhari 6382 (Jabir); also in the chapter on tahajjud"}, "check": true}, {"type": "note", "tone": "info", "text": {"bn": "হাদিসে বর্ণনাকারী ‘ওয়া আকিবাতি আমরী’-এর জায়গায় ‘আজিলি আমরী ওয়া আজিলিহ’ (আমার কাজের নিকট ও দূর ভবিষ্যৎ) বলারও উল্লেখ করেছেন। কোনো কোনো আলেম দুটোই বলতে বলেন। বুখারির আরেক বর্ণনায় শেষে ‘সুম্মা রাদ্দিনী বিহ’ আছে; অর্থ একই।", "en": "The narrator also mentions ''in the near and far future of my affairs'' instead of ''the outcome of my affairs''; some scholars advise saying both. Another narration in al-Bukhari ends ''thumma raddini bih'', with the same meaning."}}, {"type": "heading", "text": {"bn": "মনে রাখার বিষয়", "en": "Points to remember"}}, {"type": "list", "items": [{"bn": "ইস্তিখারা কেবল বৈধ (হালাল) বিষয়ে; ফরজ পালন বা হারাম বর্জনের জন্য ইস্তিখারা নেই।", "en": "Istikhara is only for permissible matters, not for doing a duty or avoiding a sin."}, {"bn": "হাদিসে ইস্তিখারার পর ঘুমানো বা স্বপ্ন দেখার কথা নেই। স্বপ্নের অপেক্ষা জরুরি নয়।", "en": "The hadith says nothing about sleeping or seeing a dream afterwards; waiting for a dream is not required."}, {"bn": "দোয়ার পর বিষয়টি ভেবে দেখুন, অভিজ্ঞ ও বিশ্বস্ত মানুষের পরামর্শ নিন, তারপর যেদিকে মন স্থির হয় ও পথ সহজ হয়, আল্লাহর ওপর ভরসা করে এগিয়ে যান।", "en": "After the du''a, think, consult experienced and trustworthy people, then proceed with what your heart settles on and what becomes easy, trusting Allah."}, {"bn": "বিষয়টি পরিষ্কার না হলে একাধিকবার ইস্তিখারা করা যায়।", "en": "You may repeat istikhara if the matter is still unclear."}, {"bn": "নারীরা ঋতুস্রাবের সময় নামাজ ছাড়া শুধু দোয়াটি পড়তে পারেন।", "en": "A woman in her period may recite the du''a without the prayer."}]}, {"type": "note", "tone": "tip", "text": {"bn": "নিয়ত মনে মনে করাই যথেষ্ট। উদাহরণ (প্রচলিত বাংলা): ‘আমি আল্লাহর জন্য দুই রাকাত ইস্তিখারার নামাজ পড়ছি।’", "en": "The intention in the heart is enough. Example (common Bangla phrasing): ''I am praying two rak''ahs of istikhara for Allah.''"}}]', 'in_review', 70 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '03d04b56-de79-5535-b575-1b15ad3dca02', id, 'salatut-tasbih', '{"bn": "সালাতুত তাসবিহ", "en": "Salat al-Tasbih"}', '{"bn": "চার রাকাতে মোট ৩০০ বার তাসবিহ পড়ার বিশেষ নফল নামাজ: পদ্ধতি, গণনার ছক এবং হাদিসটির মান নিয়ে আলোচনা।", "en": "A special voluntary prayer of four rak''ahs with 300 tasbihs: the method, a counting table, and the discussion on the hadith''s grading."}', 'detail', '[{"type": "text", "text": {"bn": "নবীজি (সা.) তাঁর চাচা আব্বাস (রা.)-কে এই নামাজ শিখিয়েছিলেন এবং বলেছিলেন, পারলে প্রতিদিন, না পারলে সপ্তাহে একবার, না পারলে মাসে একবার, না পারলে বছরে একবার, না পারলে জীবনে অন্তত একবার পড়তে।", "en": "The Prophet taught this prayer to his uncle al-''Abbas and said to pray it daily if possible, otherwise weekly, monthly, yearly, or at least once in a lifetime."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ ১২৯৭; সুনান ইবনে মাজাহ ১৩৮৭ (ইবনে আব্বাস রা.); জামে তিরমিজি ৪৮২ (আবু রাফে রা.)", "en": "Sunan Abi Dawud 1297; Sunan Ibn Majah 1387 (Ibn ''Abbas); Jami'' al-Tirmidhi 482 (Abu Rafi'')"}}, {"type": "note", "tone": "info", "text": {"bn": "হাদিসটির মান নিয়ে মুহাদ্দিসদের মতভেদ আছে। একাধিক সনদের কারণে ইমাম আবু দাউদ, ইবনে হাজার আসকালানি (তাঁর কিছু লেখায়) ও শাইখ আলবানিসহ অনেকে একে হাসান বা সহিহ বলেছেন; আবদুল্লাহ ইবনুল মুবারক (রহ.) এ নামাজ পড়তেন। অন্যদিকে ইবনুল জাওযি একে জাল হাদিসের তালিকায় রেখেছেন এবং আরও কিছু আলেম দুর্বল বলেছেন। তাই কেউ পড়লে তাকে বাধা দেওয়া বা কেউ না পড়লে তাকে দোষ দেওয়া উচিত নয়।", "en": "Scholars differ on this hadith''s grading. Because of its several chains, many (including Abu Dawud, Ibn Hajar in some works, and al-Albani) graded it hasan or sahih, and ''Abdullah ibn al-Mubarak practised it. Ibn al-Jawzi listed it among fabrications and some others called it weak. So neither criticise one who prays it nor blame one who does not."}, "check": true}, {"type": "arabic", "label": {"bn": "যে তাসবিহ পড়া হয়", "en": "The tasbih"}, "ar": "سُبْحَانَ اللّٰهِ وَالْحَمْدُ لِلّٰهِ وَلَا إِلٰهَ إِلَّا اللّٰهُ وَاللّٰهُ أَكْبَرُ", "pron": {"bn": "সুবহানাল্লাহি ওয়াল হামদু লিল্লাহি ওয়া লা ইলাহা ইল্লাল্লাহু ওয়াল্লাহু আকবার।", "en": "Subhanallahi wal-hamdu lillahi wa la ilaha illallahu wallahu akbar."}, "meaning": {"bn": "আল্লাহ পবিত্র, সকল প্রশংসা আল্লাহর, আল্লাহ ছাড়া কোনো ইলাহ নেই, আল্লাহ সবচেয়ে বড়।", "en": "Glory be to Allah, all praise is for Allah, there is no god but Allah, and Allah is the Greatest."}, "ref": {"bn": "সুনান আবু দাউদ ১২৯৭", "en": "Sunan Abi Dawud 1297"}}, {"type": "heading", "text": {"bn": "চার রাকাত, প্রতি রাকাতে ৭৫ বার", "en": "Four rak''ahs, 75 per rak''ah"}}, {"type": "text", "text": {"bn": "চার রাকাত নফলের নিয়ত করুন (এক সালামে চার রাকাত, অথবা দুই দুই রাকাত করে)। প্রতি রাকাতে সূরা ফাতিহা ও আরেকটি সূরা পড়ুন। নিচের দুটি পদ্ধতির যেকোনোটিতে প্রতি রাকাতে ৭৫ বার, চার রাকাতে মোট ৩০০ বার তাসবিহ হয়। রুকু ও সিজদায় আগে স্বাভাবিক তাসবিহ (সুবহানা রাব্বিয়াল আযীম / আ''লা) পড়ে তারপর এই তাসবিহ পড়বেন।", "en": "Intend four rak''ahs of nafl (all four with one salam, or two and two). Recite al-Fatihah and a surah in each. Either method below gives 75 per rak''ah and 300 in total. In ruku'' and sajdah say the usual tasbih first, then this one."}}, {"type": "differ", "title": {"bn": "দুটি প্রচলিত পদ্ধতি", "en": "The two known methods"}, "views": [{"label": {"bn": "পদ্ধতি ১: ইবনে আব্বাস (রা.)-এর হাদিস অনুযায়ী", "en": "Method 1: per the hadith of Ibn ''Abbas"}, "text": {"bn": "কিরাতের পর দাঁড়িয়ে ১৫, রুকুতে ১০, রুকু থেকে উঠে ১০, প্রথম সিজদায় ১০, দুই সিজদার মাঝে বসে ১০, দ্বিতীয় সিজদায় ১০, দ্বিতীয় সিজদার পর দাঁড়ানোর আগে বসে ১০ = ৭৫।", "en": "After recitation standing 15; ruku'' 10; rising 10; first sajdah 10; sitting between 10; second sajdah 10; sitting after the second sajdah before standing 10 = 75."}, "evidence": {"bn": "সুনান আবু দাউদ ১২৯৭; জামে তিরমিজি ৪৮২।", "en": "Sunan Abi Dawud 1297; Jami'' al-Tirmidhi 482."}}, {"label": {"bn": "পদ্ধতি ২: আবদুল্লাহ ইবনুল মুবারক (রহ.)-এর পদ্ধতি (বাংলাদেশে বেশি প্রচলিত)", "en": "Method 2: of ''Abdullah ibn al-Mubarak (more common in Bangladesh)"}, "text": {"bn": "সানার পর কিরাতের আগে ১৫, কিরাতের পর ১০, রুকুতে ১০, রুকু থেকে উঠে ১০, প্রথম সিজদায় ১০, দুই সিজদার মাঝে ১০, দ্বিতীয় সিজদায় ১০ = ৭৫। দ্বিতীয় সিজদার পর বসে কোনো তাসবিহ নেই।", "en": "After thana before recitation 15; after recitation 10; ruku'' 10; rising 10; first sajdah 10; between sajdahs 10; second sajdah 10 = 75. Nothing in the sitting after the second sajdah."}, "evidence": {"bn": "জামে তিরমিজি ৪৮১ (ইবনুল মুবারকের বর্ণনা)।", "en": "Jami'' al-Tirmidhi 481 (Ibn al-Mubarak''s description)."}}]}, {"type": "table", "head": [{"bn": "অবস্থান", "en": "Position"}, {"bn": "পদ্ধতি ১", "en": "Method 1"}, {"bn": "পদ্ধতি ২", "en": "Method 2"}], "rows": [[{"bn": "সানার পর, কিরাতের আগে", "en": "After thana, before recitation"}, {"bn": "—", "en": "—"}, {"bn": "১৫", "en": "15"}], [{"bn": "কিরাতের পর", "en": "After recitation"}, {"bn": "১৫", "en": "15"}, {"bn": "১০", "en": "10"}], [{"bn": "রুকু", "en": "Ruku''"}, {"bn": "১০", "en": "10"}, {"bn": "১০", "en": "10"}], [{"bn": "রুকু থেকে উঠে", "en": "Standing after ruku''"}, {"bn": "১০", "en": "10"}, {"bn": "১০", "en": "10"}], [{"bn": "প্রথম সিজদা", "en": "First sajdah"}, {"bn": "১০", "en": "10"}, {"bn": "১০", "en": "10"}], [{"bn": "দুই সিজদার মাঝে", "en": "Between sajdahs"}, {"bn": "১০", "en": "10"}, {"bn": "১০", "en": "10"}], [{"bn": "দ্বিতীয় সিজদা", "en": "Second sajdah"}, {"bn": "১০", "en": "10"}, {"bn": "১০", "en": "10"}], [{"bn": "দ্বিতীয় সিজদার পর বসে", "en": "Sitting after second sajdah"}, {"bn": "১০", "en": "10"}, {"bn": "—", "en": "—"}], [{"bn": "প্রতি রাকাতে মোট", "en": "Total per rak''ah"}, {"bn": "৭৫", "en": "75"}, {"bn": "৭৫", "en": "75"}]]}, {"type": "note", "tone": "tip", "text": {"bn": "আঙুল চেপে মনে মনে গুনুন; মুখে গোনা বা তাসবিহদানা হাতে নেওয়া এড়িয়ে চলুন। কোনো জায়গায় কিছু তাসবিহ ছুটে গেলে পরের অবস্থানে তা যোগ করে নেওয়ার কথা আলেমরা বলেছেন; অনেকে বলেন, রুকু থেকে ওঠা ও দুই সিজদার মাঝের বৈঠক ছোট রাখতে সেখানে যোগ না করে পরের সিজদায় যোগ করবেন। ইবনুল মুবারক (রহ.) বলেছেন, সাহু সিজদায় এই তাসবিহ পড়তে হয় না।", "en": "Count silently by pressing your fingers; avoid counting aloud or holding beads. If you miss some in one position, scholars say to add them in the next; many say not to add them while rising or in the short sitting, but in the next sajdah. Ibn al-Mubarak said these tasbihs are not said in sajdah al-sahw."}}]', 'in_review', 80 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '885d627e-ab20-5763-afe0-38addc84ec3a', id, 'qasr-travel-prayer', '{"bn": "কসর: মুসাফিরের নামাজ", "en": "Qasr: The Traveller''s Prayer"}', '{"bn": "সফরে চার রাকাতের ফরজ নামাজ দুই রাকাত পড়ার বিধান: কত দূরত্বে, কত দিন, সুন্নত ও জামাতের মাসআলা, দুই ওয়াক্ত একসাথে পড়া।", "en": "Shortening four-rak''ah prayers to two when travelling: distance, duration, sunnahs, praying behind an imam, and combining prayers."}', 'basic', '[{"type": "arabic", "ar": "وَإِذَا ضَرَبْتُمْ فِي الْأَرْضِ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَقْصُرُوا مِنَ الصَّلَاةِ", "pron": {"bn": "ওয়া ইযা দারাবতুম ফিল আরদি ফালাইসা আলাইকুম জুনাহুন আন তাকসুরূ মিনাস সালাহ।", "en": "Wa idha darabtum fil-ardi falaysa ''alaykum junahun an taqsuru minas-salah."}, "meaning": {"bn": "আর যখন তোমরা জমিনে সফর করো, তখন নামাজ সংক্ষিপ্ত করলে তোমাদের কোনো গুনাহ নেই।", "en": "When you travel in the land, there is no blame on you for shortening the prayer."}, "ref": {"bn": "সূরা নিসা ৪:১০১ (আয়াতের অংশ)", "en": "An-Nisa 4:101 (part of the verse)"}}, {"type": "text", "text": {"bn": "সফরে জোহর, আসর ও ইশার চার রাকাত ফরজ দুই রাকাত পড়তে হয়। ফজর (২) ও মাগরিব (৩) অপরিবর্তিত থাকে। বিতর পূর্ণ তিন রাকাতই পড়তে হয়।", "en": "On a journey, the four-rak''ah fard of Dhuhr, ''Asr and ''Isha become two. Fajr (2) and Maghrib (3) stay the same. Witr stays three."}}, {"type": "table", "head": [{"bn": "নামাজ", "en": "Prayer"}, {"bn": "বাড়িতে ফরজ", "en": "At home (fard)"}, {"bn": "সফরে ফরজ", "en": "Travelling (fard)"}], "rows": [[{"bn": "ফজর", "en": "Fajr"}, {"bn": "২", "en": "2"}, {"bn": "২", "en": "2"}], [{"bn": "জোহর", "en": "Dhuhr"}, {"bn": "৪", "en": "4"}, {"bn": "২", "en": "2"}], [{"bn": "আসর", "en": "''Asr"}, {"bn": "৪", "en": "4"}, {"bn": "২", "en": "2"}], [{"bn": "মাগরিব", "en": "Maghrib"}, {"bn": "৩", "en": "3"}, {"bn": "৩", "en": "3"}], [{"bn": "ইশা", "en": "''Isha"}, {"bn": "৪", "en": "4"}, {"bn": "২", "en": "2"}]]}, {"type": "text", "text": {"bn": "নিজের এলাকা (শহর বা গ্রামের বসতি) পার হওয়ার পর থেকে কসর শুরু হয়, আর ফিরে নিজের এলাকায় ঢুকলে শেষ হয়। আনাস (রা.) বলেন, আমরা নবীজি (সা.)-এর সাথে মদিনা থেকে মক্কা গিয়েছি; ফেরা পর্যন্ত তিনি দুই রাকাত করে পড়েছেন (সহিহ বুখারি ১০৮১)।", "en": "Qasr begins once you leave the built-up area of your town and ends when you re-enter it. Anas said: we travelled with the Prophet from Madinah to Makkah and he prayed two rak''ahs until we returned (Sahih al-Bukhari 1081)."}}, {"type": "differ", "title": {"bn": "কতটুকু দূরত্বে মুসাফির হয়", "en": "Distance that makes one a traveller"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "তিন দিনের পায়ে হাঁটা পথ; বাংলাদেশের আলেমরা সাধারণত ৪৮ মাইল, প্রায় ৭৭–৭৮ কিলোমিটার ধরেন। যানবাহনে অল্প সময়ে গেলেও একই হুকুম।", "en": "Three days'' walking; scholars in Bangladesh usually take this as 48 miles, about 77–78 km, regardless of how fast the vehicle is."}, "evidence": {"bn": "মুসাফিরকে তিন দিন-তিন রাত মোজার ওপর মাসেহ করার অনুমতি (সহিহ মুসলিম ২৭৬), অর্থাৎ সফরের সর্বনিম্ন সময় তিন দিন ধরা হয়েছে।", "en": "Travellers may wipe over socks for three days and nights (Sahih Muslim 276), taken to indicate that travel is at least three days."}}, {"label": {"bn": "শাফেয়ি, মালেকি ও হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "চার ‘বারিদ’ (১৬ ফারসাখ), আধুনিক হিসাবে প্রায় ৮০–৮৯ কিলোমিটার (হিসাবে কিছু ভিন্নতা আছে)।", "en": "Four burud (16 farsakh), roughly 80–89 km by modern estimates (estimates vary)."}, "evidence": {"bn": "ইবনে উমর ও ইবনে আব্বাস (রা.) চার বারিদ দূরত্বে কসর করতেন (সহিহ বুখারিতে অধ্যায়ের শিরোনামে উল্লেখিত)।", "en": "Ibn ''Umar and Ibn ''Abbas shortened at four burud (mentioned in a chapter heading of Sahih al-Bukhari)."}}, {"label": {"bn": "কিছু আলেম (যেমন ইবনে তাইমিয়া)", "en": "Some scholars (e.g. Ibn Taymiyyah)"}, "text": {"bn": "নির্দিষ্ট দূরত্ব নেই; প্রচলিত অর্থে যাকে সফর বলা হয়, তাতেই কসর।", "en": "No fixed distance; whatever is customarily called a journey."}, "evidence": {"bn": "কুরআন সফরের কোনো দূরত্ব নির্ধারণ করেনি (সূরা নিসা ৪:১০১)।", "en": "The Quran sets no distance (An-Nisa 4:101)."}}], "check": true}, {"type": "differ", "title": {"bn": "কত দিন থাকলে আর মুসাফির থাকে না", "en": "How long a stay ends traveller status"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "কোনো এক জায়গায় ১৫ দিন বা তার বেশি থাকার নিয়ত করলে পূর্ণ নামাজ পড়বে; ১৫ দিনের কম হলে কসর। কবে ফিরবে ঠিক না থাকলে (আজ-কাল করে) যত দিনই থাকুক, কসর চলবে।", "en": "Intending to stay 15 days or more in one place means full prayers; less than 15 means qasr. If the return date is uncertain, qasr continues however long it lasts."}, "evidence": {"bn": "ইবনে উমর ও ইবনে আব্বাস (রা.)-এর ফতোয়া (১৫ দিন); নবীজি (সা.) এক সফরে ১৯ দিন থেকে কসর করেছেন (সহিহ বুখারি ১০৮০)।", "en": "Fatwa of Ibn ''Umar and Ibn ''Abbas (15 days); the Prophet stayed 19 days on a journey and shortened (Sahih al-Bukhari 1080)."}}, {"label": {"bn": "শাফেয়ি, মালেকি ও হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "চার দিন বা তার বেশি থাকার নিয়ত করলে পূর্ণ নামাজ (আসা-যাওয়ার দিন বাদে হিসাব; হাম্বলি মতে ২০ ওয়াক্তের বেশি)।", "en": "Intending to stay four days or more means full prayers (excluding arrival/departure days; Hanbali: more than 20 prayers)."}, "evidence": {"bn": "হজের পর মুহাজিরদের মক্কায় তিন দিন থাকার অনুমতি দেওয়া হয়েছিল (সহিহ মুসলিম ১৩৫২), অর্থাৎ তিন দিন পর্যন্ত সফরের হুকুম।", "en": "Emigrants were allowed to stay three days in Makkah after Hajj (Sahih Muslim 1352), implying up to three days is still travel."}}], "check": true}, {"type": "differ", "title": {"bn": "কসর বাধ্যতামূলক না ঐচ্ছিক", "en": "Is shortening required or optional"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "কসর ওয়াজিব। মুসাফির ইচ্ছা করে চার রাকাত পড়লে গুনাহগার হবে; দ্বিতীয় রাকাতে বৈঠক করলে প্রথম দুই রাকাত ফরজ ও বাকি দুই নফল গণ্য হবে।", "en": "Qasr is wajib. A traveller who deliberately prays four does wrong; if he sat after two, the first two count as fard and the rest as nafl."}, "evidence": {"bn": "আয়েশা (রা.): নামাজ প্রথমে দুই রাকাত করে ফরজ হয়েছিল; সফরের নামাজ সেভাবেই রাখা হয়েছে, আর মুকিমের নামাজ বাড়ানো হয়েছে (সহিহ বুখারি ৩৫০; সহিহ মুসলিম ৬৮৫)।", "en": "''A''ishah: prayer was first prescribed as two rak''ahs; the travel prayer was kept so and the resident''s prayer increased (Sahih al-Bukhari 350; Sahih Muslim 685)."}}, {"label": {"bn": "শাফেয়ি, মালেকি ও হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "কসর একটি ছাড় (রুখসত) ও সুন্নত; পূর্ণ পড়লেও নামাজ হয়ে যায়, তবে কসর উত্তম।", "en": "Qasr is a concession and sunnah; full prayer is valid, but shortening is better."}, "evidence": {"bn": "আয়াতে ‘কোনো গুনাহ নেই’ বলা হয়েছে, যা অনুমতি বোঝায় (সূরা নিসা ৪:১০১)।", "en": "The verse says ''no blame on you'', which indicates permission (An-Nisa 4:101)."}}]}, {"type": "heading", "text": {"bn": "জামাত ও সুন্নতের মাসআলা", "en": "Congregation and sunnah rulings"}}, {"type": "list", "items": [{"bn": "মুসাফির যদি মুকিম ইমামের পেছনে পড়ে, তবে ইমামের সাথে পূর্ণ চার রাকাত পড়বে।", "en": "A traveller behind a resident imam prays the full four with him."}, {"bn": "মুকিম যদি মুসাফির ইমামের পেছনে পড়ে, ইমাম দুই রাকাতে সালাম ফেরাবেন; মুকিমরা দাঁড়িয়ে বাকি দুই রাকাত নিজে নিজে পূর্ণ করবেন (কিরাত ছাড়া, হানাফি মত)। ইমাম আগেই জানিয়ে দেবেন যে তিনি মুসাফির।", "en": "Residents behind a travelling imam: he ends after two; they stand and complete the remaining two themselves (without recitation, Hanafi view). The imam should tell them he is travelling."}, {"bn": "সফরে সুন্নত নামাজ: তাড়াহুড়া থাকলে ছেড়ে দেওয়া যায়; স্থির ও নিরাপদ অবস্থায় পড়া ভালো। ফজরের সুন্নত ও বিতর নবীজি (সা.) সফরেও ছাড়তেন না। ইবনে উমর (রা.) বলেন, তিনি সফরে (ফরজের আগে-পরে) নফল পড়তে দেখেননি (সহিহ বুখারি ১১০১)।", "en": "Sunnah prayers when travelling: may be left if in a hurry, better prayed when settled. The Prophet kept the Fajr sunnah and witr even when travelling. Ibn ''Umar said he did not see him pray the regular sunnahs on journeys (Sahih al-Bukhari 1101)."}, {"bn": "সফরে ছুটে যাওয়া নামাজ বাড়িতে কাজা করলেও দুই রাকাত; বাড়িতে ছুটে যাওয়া নামাজ সফরে কাজা করলে চার রাকাত।", "en": "A prayer missed while travelling is made up as two even at home; one missed at home is made up as four even while travelling."}]}, {"type": "differ", "title": {"bn": "সফরে দুই ওয়াক্ত একসাথে পড়া (জমা)", "en": "Combining two prayers when travelling"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "হজে আরাফা ও মুজদালিফা ছাড়া এক ওয়াক্তের নামাজ অন্য ওয়াক্তে পড়া যায় না। তবে জোহর তার শেষ ওয়াক্তে আর আসর তার প্রথম ওয়াক্তে পড়া যায়, যাতে দেখতে একসাথে মনে হয় (জমায়ে সুরি)।", "en": "Apart from ''Arafah and Muzdalifah in Hajj, no prayer may be moved into another''s time. But Dhuhr may be prayed at the end of its time and ''Asr at the start of its time, so they appear joined."}, "evidence": {"bn": "‘নিশ্চয়ই নামাজ মুমিনদের ওপর নির্দিষ্ট সময়ে ফরজ’ (সূরা নিসা ৪:১০৩); ইবনে মাসউদ (রা.): মুজদালিফা ছাড়া নবীজি (সা.)-কে কখনো নামাজ তার সময় ছাড়া পড়তে দেখিনি (সহিহ বুখারি ১৬৮২)।", "en": "''Prayer is prescribed for the believers at fixed times'' (An-Nisa 4:103); Ibn Mas''ud: I never saw the Prophet pray outside its time except at Muzdalifah (Sahih al-Bukhari 1682)."}}, {"label": {"bn": "শাফেয়ি, হাম্বলি ও মালেকি", "en": "Shafi''i, Hanbali, Maliki"}, "text": {"bn": "সফরে জোহর-আসর এবং মাগরিব-ইশা একটির ওয়াক্তে একসাথে পড়া জায়েজ (আগে বা পরে নিয়ে)।", "en": "When travelling, Dhuhr with ''Asr and Maghrib with ''Isha may be joined in the time of either."}, "evidence": {"bn": "তাড়া থাকলে নবীজি (সা.) সফরে মাগরিব ও ইশা একসাথে পড়তেন (সহিহ বুখারি ১১০৬); সহিহ মুসলিম ৭০৫।", "en": "When in a hurry on a journey, the Prophet combined Maghrib and ''Isha (Sahih al-Bukhari 1106); Sahih Muslim 705."}}]}]', 'in_review', 90 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '3bcd21e8-8f0e-5a98-b83a-2b4ff0eaf7f7', id, 'qada-prayer', '{"bn": "কাজা নামাজ", "en": "Making Up Missed Prayers (Qada)"}', '{"bn": "ঘুম, ভুল বা অন্য কারণে ছুটে যাওয়া নামাজ কীভাবে আদায় করবেন: ধারাবাহিকতা, অনেক দিনের কাজা ও কিছু মতভেদ।", "en": "How to make up prayers missed through sleep, forgetfulness or otherwise: order, many years of missed prayers, and points of difference."}', 'basic', '[{"type": "arabic", "ar": "مَنْ نَسِيَ صَلَاةً فَلْيُصَلِّ إِذَا ذَكَرَهَا، لَا كَفَّارَةَ لَهَا إِلَّا ذٰلِكَ", "pron": {"bn": "মান নাসিয়া সালাতান ফালইউসাল্লি ইযা যাকারাহা, লা কাফফারাতা লাহা ইল্লা যালিক।", "en": "Man nasiya salatan falyusalli idha dhakaraha, la kaffarata laha illa dhalik."}, "meaning": {"bn": "যে কোনো নামাজ ভুলে যায়, সে যেন মনে পড়লেই তা পড়ে নেয়; এ ছাড়া এর আর কোনো কাফফারা নেই।", "en": "Whoever forgets a prayer, let him pray it when he remembers; there is no expiation for it except that."}, "ref": {"bn": "সহিহ বুখারি ৫৯৭; সহিহ মুসলিম ৬৮৪", "en": "Sahih al-Bukhari 597; Sahih Muslim 684"}}, {"type": "text", "text": {"bn": "ফরজ নামাজ ছুটে গেলে কাজা করা ফরজ, আর বিতর ছুটে গেলে হানাফি মতে কাজা করা ওয়াজিব। ঘুম বা ভুলের কারণে ছুটে গেলে গুনাহ নেই, তবে মনে পড়ামাত্র পড়ে নিতে হবে। ঋতুস্রাব ও প্রসবোত্তর রক্তস্রাবের সময়ের নামাজের কাজা নেই (সহিহ মুসলিম ৩৩৫)।", "en": "Making up a missed fard prayer is obligatory, and in the Hanafi school also witr. Missing through sleep or forgetfulness is not sinful, but pray as soon as you remember. Prayers during menstruation and post-natal bleeding are not made up (Sahih Muslim 335)."}}, {"type": "heading", "text": {"bn": "কীভাবে কাজা পড়বেন", "en": "How to make up"}}, {"type": "step", "title": {"bn": "নিয়ত", "en": "Intention"}, "text": {"bn": "যে নামাজ কাজা করছেন, মনে মনে সেটি নির্দিষ্ট করুন, যেমন ‘আজকের ছুটে যাওয়া ফজরের দুই রাকাত ফরজ’। মুখে বলা জরুরি নয়।", "en": "Specify in your heart which prayer you are making up, e.g. ''today''s missed two rak''ahs of Fajr fard''. Saying it aloud is not required."}}, {"type": "step", "title": {"bn": "যেভাবে ছুটেছে সেভাবে", "en": "As it was missed"}, "text": {"bn": "নামাজ যেমন ছিল তেমনই পড়ুন: ফজর দুই, মাগরিব তিন। সফরে ছুটে যাওয়া চার রাকাতের নামাজ দুই রাকাত।", "en": "Pray it as it was: Fajr two, Maghrib three; a four-rak''ah prayer missed while travelling is two."}}, {"type": "step", "title": {"bn": "সাধারণত শুধু ফরজ ও বিতর", "en": "Usually only fard and witr"}, "text": {"bn": "কাজা হয় ফরজ ও বিতরের। হানাফি মতে ফজর ফরজসহ ছুটে গেলে সেদিন জাওয়ালের আগে কাজা করলে সুন্নতসহ পড়বে; অন্য সুন্নতের কাজা নেই।", "en": "Qada is for fard and witr. In the Hanafi school, if Fajr is missed with its sunnah and made up before noon the same day, the sunnah is included; other sunnahs are not made up."}}, {"type": "step", "title": {"bn": "সময়", "en": "When"}, "text": {"bn": "যেকোনো সময় কাজা পড়া যায়, তবে সূর্যোদয়, ঠিক দুপুর ও সূর্যাস্তের সময় (হানাফি মতে) নয়। ফজরের পর ও আসরের পর কাজা পড়া যায়, যদিও তখন নফল পড়া যায় না।", "en": "Any time, except (in the Hanafi school) at sunrise, true noon and sunset. Qada may be prayed after Fajr and after ''Asr, though nafl may not."}}, {"type": "differ", "title": {"bn": "কাজা ও ওয়াক্তিয়া নামাজের ধারাবাহিকতা (তারতিব)", "en": "Keeping the order between missed and current prayers"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "যার জিম্মায় ছয় ওয়াক্তের কম কাজা আছে (সাহিবে তারতিব), তাকে আগে কাজা পরে ওয়াক্তিয়া পড়তে হবে; তবে ওয়াক্ত সংকীর্ণ হলে, ভুলে গেলে বা কাজা ছয় ওয়াক্ত বা বেশি হলে এই ধারাবাহিকতা বাধ্যতামূলক নয়।", "en": "Someone with fewer than six missed prayers must pray them before the current one, unless time is short, he forgot, or the missed prayers are six or more."}, "evidence": {"bn": "খন্দকের যুদ্ধে ছুটে যাওয়া নামাজগুলো নবীজি (সা.) ক্রমানুসারে আদায় করেছেন (জামে তিরমিজি; সুনান নাসায়ি)।", "en": "At the Battle of the Trench the Prophet made up the missed prayers in order (Jami'' al-Tirmidhi; Sunan al-Nasa''i)."}}, {"label": {"bn": "হাম্বলি ও মালেকি", "en": "Hanbali and Maliki"}, "text": {"bn": "ধারাবাহিকতা রক্ষা করা ওয়াজিব (বিস্তারিত শর্তে কিছু ভিন্নতা আছে)।", "en": "Order is required (with some differences in the details)."}, "evidence": {"bn": "একই হাদিস।", "en": "The same hadith."}}, {"label": {"bn": "শাফেয়ি", "en": "Shafi''i"}, "text": {"bn": "ধারাবাহিকতা রক্ষা করা সুন্নত, বাধ্যতামূলক নয়।", "en": "Order is recommended, not required."}, "evidence": {"bn": "হাদিসে কেবল নবীজি (সা.)-এর আমল বর্ণিত, স্পষ্ট নির্দেশ নয়।", "en": "The hadith reports the Prophet''s practice, not an explicit command."}}], "check": true}, {"type": "heading", "text": {"bn": "অনেক বছরের কাজা (উমরি কাজা)", "en": "Many years of missed prayers"}}, {"type": "text", "text": {"bn": "যদি দীর্ঘদিন নামাজ না পড়ে থাকেন, আন্তরিক তওবা করুন এবং আনুমানিক হিসাব করুন কত ওয়াক্ত ছুটেছে; সন্দেহ হলে বেশির দিকে ধরুন। তারপর প্রতিদিন সাধ্যমতো কাজা পড়তে থাকুন, যেমন প্রতি ওয়াক্তের সাথে এক ওয়াক্ত কাজা। নিয়তে বলবেন (মনে মনে), ‘আমার জিম্মায় থাকা প্রথম (বা শেষ) ফজরের কাজা’।", "en": "If you did not pray for a long time, repent sincerely and estimate how many prayers were missed, erring on the higher side. Then make them up steadily, e.g. one with each daily prayer. Intend ''the first (or last) Fajr I owe''."}}, {"type": "differ", "title": {"bn": "ইচ্ছাকৃতভাবে ছেড়ে দেওয়া নামাজের কাজা", "en": "Prayers left deliberately"}, "views": [{"label": {"bn": "চার মাজহাব (অধিকাংশ আলেম)", "en": "The four schools (majority)"}, "text": {"bn": "ইচ্ছা করে ছেড়ে দিলেও কাজা করা ফরজ, সাথে তওবা করতে হবে।", "en": "They must be made up, along with repentance."}, "evidence": {"bn": "ভুলে যাওয়া ব্যক্তিকেও কাজা করতে বলা হয়েছে (সহিহ বুখারি ৫৯৭); ইচ্ছাকৃত ত্যাগকারী আরও বেশি দায়বদ্ধ। ‘আল্লাহর ঋণ পরিশোধের বেশি উপযুক্ত’ (সহিহ বুখারি ১৯৫৩)।", "en": "Even the forgetful must make up (Sahih al-Bukhari 597), so the deliberate omitter all the more. ''The debt of Allah is more deserving to be paid'' (Sahih al-Bukhari 1953)."}}, {"label": {"bn": "কিছু আলেম (যেমন ইবনে হাযম, ইবনে তাইমিয়া)", "en": "Some scholars (e.g. Ibn Hazm, Ibn Taymiyyah)"}, "text": {"bn": "ইচ্ছাকৃত ছেড়ে দেওয়া নামাজ কাজা করে আদায় হয় না; খাঁটি তওবা ও বেশি বেশি নফল পড়তে হবে।", "en": "Deliberately abandoned prayers cannot be validly made up; sincere repentance and abundant nafl are required."}, "evidence": {"bn": "হাদিসে কাজার নির্দেশ এসেছে কেবল ঘুম ও ভুলের ক্ষেত্রে (সহিহ বুখারি ৫৯৭)।", "en": "The hadith commands qada only for sleep and forgetfulness (Sahih al-Bukhari 597)."}}]}, {"type": "note", "tone": "tip", "text": {"bn": "নিরাপদ পথ হলো অধিকাংশ আলেমের মত অনুযায়ী কাজা করে যাওয়া। কাজার বোঝা যেন নতুন নামাজ ছাড়ার কারণ না হয়; আজ থেকে প্রতিটি ওয়াক্ত সময়মতো পড়ুন।", "en": "The safe course is to follow the majority and make them up. Do not let the backlog stop you praying today''s prayers on time."}}]', 'in_review', 100 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '9e55ea4c-cc2c-5d4f-89c6-fb1c3ff5525c', id, 'salatul-hajah', '{"bn": "সালাতুল হাজত", "en": "Salat al-Hajah (Prayer of Need)"}', '{"bn": "বিপদে বা কোনো প্রয়োজনে আল্লাহর কাছে চাওয়ার জন্য দুই রাকাত নামাজ ও দোয়া, হাদিসের মানসহ।", "en": "Two rak''ahs and a du''a when in need or distress, with an honest note on the narrations."}', 'basic', '[{"type": "arabic", "ar": "وَاسْتَعِينُوا بِالصَّبْرِ وَالصَّلَاةِ ۚ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى الْخَاشِعِينَ", "pron": {"bn": "ওয়াসতাঈনূ বিসসাবরি ওয়াস সালাহ, ওয়া ইন্নাহা লাকাবীরাতুন ইল্লা আলাল খাশিঈন।", "en": "Wasta''inu bis-sabri was-salah, wa innaha lakabiratun illa ''alal-khashi''in."}, "meaning": {"bn": "তোমরা ধৈর্য ও নামাজের মাধ্যমে সাহায্য চাও; আর নিশ্চয়ই তা কঠিন, তবে বিনয়ীদের জন্য নয়।", "en": "Seek help through patience and prayer; it is hard except for the humble."}, "ref": {"bn": "সূরা বাকারা ২:৪৫", "en": "Al-Baqarah 2:45"}}, {"type": "text", "text": {"bn": "হুযাইফা (রা.) বলেন, কোনো বিষয় নবীজি (সা.)-কে চিন্তিত করলে তিনি নামাজে দাঁড়াতেন (সুনান আবু দাউদ ১৩১৯)। তাই প্রয়োজন বা বিপদে নামাজ পড়ে আল্লাহর কাছে চাওয়া সুন্নাহসম্মত।", "en": "Hudhayfah said that when something worried the Prophet, he would pray (Sunan Abi Dawud 1319). So praying and then asking Allah in need is in line with the sunnah."}}, {"type": "heading", "text": {"bn": "পদ্ধতি", "en": "Method"}}, {"type": "step", "title": {"bn": "ওযু", "en": "Wudu"}, "text": {"bn": "সুন্দরভাবে ওযু করুন।", "en": "Make wudu well."}}, {"type": "step", "title": {"bn": "দুই রাকাত নফল", "en": "Two rak''ahs of nafl"}, "text": {"bn": "মাকরুহ সময় ছাড়া দুই রাকাত নফল নামাজ পড়ুন; যেকোনো সূরা পড়া যায়।", "en": "Pray two rak''ahs of nafl outside the disliked times; any surah may be recited."}}, {"type": "step", "title": {"bn": "প্রশংসা ও দরুদ", "en": "Praise and durood"}, "text": {"bn": "সালামের পর আল্লাহর প্রশংসা করুন ও নবীজি (সা.)-এর ওপর দরুদ পড়ুন।", "en": "After salam, praise Allah and send durood on the Prophet."}}, {"type": "step", "title": {"bn": "দোয়া", "en": "Ask"}, "text": {"bn": "নিচের দোয়া বা নিজের ভাষায় মন খুলে আপনার প্রয়োজন আল্লাহর কাছে চান।", "en": "Recite the du''a below or ask for your need in your own words."}}, {"type": "arabic", "label": {"bn": "সালাতুল হাজতের প্রচলিত দোয়া", "en": "The commonly used du''a of need"}, "ar": "لَا إِلٰهَ إِلَّا اللّٰهُ الْحَلِيمُ الْكَرِيمُ، سُبْحَانَ اللّٰهِ رَبِّ الْعَرْشِ الْعَظِيمِ، الْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِينَ، أَسْأَلُكَ مُوجِبَاتِ رَحْمَتِكَ، وَعَزَائِمَ مَغْفِرَتِكَ، وَالْغَنِيمَةَ مِنْ كُلِّ بِرٍّ، وَالسَّلَامَةَ مِنْ كُلِّ إِثْمٍ، لَا تَدَعْ لِي ذَنْبًا إِلَّا غَفَرْتَهُ، وَلَا هَمًّا إِلَّا فَرَّجْتَهُ، وَلَا حَاجَةً هِيَ لَكَ رِضًا إِلَّا قَضَيْتَهَا، يَا أَرْحَمَ الرَّاحِمِينَ", "pron": {"bn": "লা ইলাহা ইল্লাল্লাহুল হালীমুল কারীম, সুবহানাল্লাহি রাব্বিল আরশিল আযীম, আলহামদু লিল্লাহি রাব্বিল আলামীন। আসআলুকা মূজিবাতি রাহমাতিকা, ওয়া আযাইমা মাগফিরাতিকা, ওয়াল গানীমাতা মিন কুল্লি বিররিন, ওয়াস সালামাতা মিন কুল্লি ইসমিন। লা তাদা'' লী যামবান ইল্লা গাফারতাহু, ওয়া লা হাম্মান ইল্লা ফাররাজতাহু, ওয়া লা হাজাতান হিয়া লাকা রিদান ইল্লা কাদাইতাহা, ইয়া আরহামার রাহিমীন।", "en": "La ilaha illallahul-Halimul-Karim, subhanallahi Rabbil-''arshil-''azim, al-hamdu lillahi Rabbil-''alamin. As''aluka mujibati rahmatika, wa ''aza''ima maghfiratika, wal-ghanimata min kulli birr, was-salamata min kulli ithm. La tada'' li dhanban illa ghafartahu, wa la hamman illa farrajtahu, wa la hajatan hiya laka ridan illa qadaytaha, ya Arhamar-rahimin."}, "meaning": {"bn": "আল্লাহ ছাড়া কোনো ইলাহ নেই, যিনি সহনশীল ও মহানুভব। মহান আরশের রব আল্লাহ পবিত্র। সকল প্রশংসা জগতসমূহের রব আল্লাহর। (হে আল্লাহ,) আমি তোমার কাছে চাই সেসব কাজ যা তোমার রহমত নিশ্চিত করে, যা তোমার ক্ষমা অবধারিত করে, প্রতিটি নেক কাজের অংশ এবং প্রতিটি গুনাহ থেকে নিরাপত্তা। আমার কোনো গুনাহ ক্ষমা না করে রেখো না, কোনো দুশ্চিন্তা দূর না করে রেখো না, আর তোমার পছন্দনীয় কোনো প্রয়োজন পূরণ না করে রেখো না, হে সর্বশ্রেষ্ঠ দয়ালু।", "en": "There is no god but Allah, the Forbearing, the Generous. Glory be to Allah, Lord of the Mighty Throne. Praise be to Allah, Lord of the worlds. I ask You for what makes Your mercy certain and Your forgiveness assured, a share of every good and safety from every sin. Leave me no sin unforgiven, no worry unrelieved, and no need that pleases You unfulfilled, O Most Merciful of the merciful."}, "ref": {"bn": "জামে তিরমিজি ৪৭৯ (আবদুল্লাহ ইবনে আবি আওফা রা.)", "en": "Jami'' al-Tirmidhi 479 (''Abdullah ibn Abi Awfa)"}}, {"type": "note", "tone": "warn", "text": {"bn": "এই নির্দিষ্ট পদ্ধতি ও দোয়ার হাদিসটি দুর্বল। ইমাম তিরমিজি নিজেই বলেছেন, এর সনদে আপত্তি আছে; বর্ণনাকারী ফায়েদ ইবনে আবদুর রহমান দুর্বল। শাইখ আলবানি একে খুব দুর্বল বলেছেন। তাই দোয়াটি পড়া যায় (এর অর্থ ভালো), কিন্তু এটিকে নবীজি (সা.)-এর নিশ্চিত শিক্ষা বা নির্দিষ্ট ফজিলতের প্রমাণ মনে করবেন না। নিজের ভাষায় দোয়াও সম্পূর্ণ সঠিক।", "en": "The hadith with this specific method and du''a is weak. Al-Tirmidhi himself noted a problem in its chain (the narrator Fa''id ibn ''Abd al-Rahman is weak); al-Albani graded it very weak. You may say the du''a (its meaning is good), but do not treat it as a confirmed teaching with a fixed reward. Asking in your own words is entirely valid."}}, {"type": "note", "tone": "tip", "text": {"bn": "নিয়ত মনে মনে করাই যথেষ্ট। উদাহরণ (প্রচলিত বাংলা): ‘আমি আল্লাহর জন্য দুই রাকাত সালাতুল হাজত পড়ছি।’", "en": "The intention in the heart is enough. Example (common Bangla phrasing): ''I am praying two rak''ahs of salat al-hajah for Allah.''"}}, {"type": "ref", "text": {"bn": "আরও দেখুন: সূরা বাকারা ২:১৮৬ (‘আমি নিকটে, ডাকলে সাড়া দিই’)", "en": "See also: Al-Baqarah 2:186 (''I am near; I answer the caller'')"}}]', 'in_review', 110 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '580c8f39-81c3-5dd7-9520-9bb18dd2655a', id, 'eclipse-prayer', '{"bn": "সূর্যগ্রহণ ও চন্দ্রগ্রহণের নামাজ", "en": "Eclipse Prayer (Kusuf and Khusuf)"}', '{"bn": "সূর্যগ্রহণ (কুসুফ) ও চন্দ্রগ্রহণের (খুসুফ) সময় নামাজ, দোয়া ও সদকা; পদ্ধতি নিয়ে মাজহাবের মত।", "en": "Prayer, du''a and charity during solar and lunar eclipses, and the schools'' methods."}', 'detail', '[{"type": "text", "text": {"bn": "নবীজি (সা.)-এর পুত্র ইবরাহিমের মৃত্যুর দিন সূর্যগ্রহণ হলে মানুষ বলাবলি করছিল যে তাঁর মৃত্যুর কারণে গ্রহণ হয়েছে। নবীজি (সা.) এই ধারণা নাকচ করে নামাজ পড়েন এবং বলেন:", "en": "When the sun eclipsed on the day the Prophet''s son Ibrahim died, people said it was because of his death. The Prophet rejected this, prayed, and said:"}}, {"type": "arabic", "ar": "إِنَّ الشَّمْسَ وَالْقَمَرَ آيَتَانِ مِنْ آيَاتِ اللّٰهِ، لَا يَنْخَسِفَانِ لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ، فَإِذَا رَأَيْتُمْ ذٰلِكَ فَادْعُوا اللّٰهَ وَكَبِّرُوا، وَصَلُّوا وَتَصَدَّقُوا", "pron": {"bn": "ইন্নাশ শামসা ওয়াল কামারা আয়াতানি মিন আয়াতিল্লাহ, লা ইয়ানখাসিফানি লিমাওতি আহাদিন ওয়া লা লিহায়াতিহ; ফাইযা রাআইতুম যালিকা ফাদউল্লাহা ওয়া কাব্বিরূ, ওয়া সাল্লূ ওয়া তাসাদ্দাকূ।", "en": "Innash-shamsa wal-qamara ayatani min ayatillah, la yankhasifani limawti ahadin wa la lihayatih; fa idha ra''aytum dhalika fad''ullaha wa kabbiru, wa sallu wa tasaddaqu."}, "meaning": {"bn": "সূর্য ও চাঁদ আল্লাহর নিদর্শনসমূহের দুটি নিদর্শন; কারও মৃত্যু বা জন্মের কারণে এদের গ্রহণ হয় না। যখন তোমরা তা দেখবে, তখন আল্লাহর কাছে দোয়া করো, তাকবির বলো, নামাজ পড়ো ও সদকা করো।", "en": "The sun and moon are two of Allah''s signs; they do not eclipse for anyone''s death or life. When you see that, call upon Allah, say takbir, pray and give charity."}, "ref": {"bn": "সহিহ বুখারি ১০৪৪", "en": "Sahih al-Bukhari 1044"}}, {"type": "text", "text": {"bn": "গ্রহণের নামাজ সুন্নতে মুয়াক্কাদা। আজান বা ইকামত নেই; মানুষকে ডাকতে ‘আস-সালাতু জামি''আহ’ (নামাজ জামাতে হচ্ছে) বলা যায় (সহিহ বুখারি ১০৪৫)। গ্রহণ শুরু হলে থেকে শেষ হওয়া পর্যন্ত নামাজ, দোয়া ও জিকিরে থাকুন।", "en": "The eclipse prayer is a confirmed sunnah. There is no adhan or iqamah; people may be called with ''as-salatu jami''ah'' (Sahih al-Bukhari 1045). Stay in prayer, du''a and dhikr from the start of the eclipse until it clears."}}, {"type": "differ", "title": {"bn": "নামাজের পদ্ধতি", "en": "Method of the prayer"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "সাধারণ নফলের মতো দুই রাকাত, প্রতি রাকাতে একটি রুকু, তবে কিরাত, রুকু ও সিজদা লম্বা। সূর্যগ্রহণে জামাতে (ইমাম আবু হানিফার মতে চুপে কিরাত), চন্দ্রগ্রহণে সাধারণত প্রত্যেকে আলাদাভাবে নিজ নিজ ঘরে। নামাজের পর গ্রহণ শেষ না হওয়া পর্যন্ত দোয়া; নির্ধারিত খুতবা নেই।", "en": "Two rak''ahs like normal nafl with one ruku'' each, but with long recitation, ruku'' and sajdah. Solar eclipse in congregation (quiet recitation per Abu Hanifah); lunar eclipse usually individually at home. Du''a afterwards until it clears; no formal khutbah."}, "evidence": {"bn": "আবু বাকরা (রা.): নবীজি (সা.) আমাদের নিয়ে দুই রাকাত পড়লেন, এর মধ্যে সূর্য পরিষ্কার হয়ে গেল (সহিহ বুখারি ১০৪০); সাধারণ নামাজের মতো এক রুকুর বর্ণনাও কিছু সাহাবি থেকে এসেছে।", "en": "Abu Bakrah: the Prophet prayed two rak''ahs with us until the sun cleared (Sahih al-Bukhari 1040); some Companions'' reports describe one ruku'' per rak''ah like a normal prayer."}}, {"label": {"bn": "শাফেয়ি, মালেকি ও হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "দুই রাকাত, প্রতি রাকাতে দুইবার কিয়াম ও দুইবার রুকু: লম্বা কিরাত, লম্বা রুকু, উঠে আবার কিরাত (আগেরটির চেয়ে ছোট), আবার রুকু (আগেরটির চেয়ে ছোট), তারপর দুই সিজদা। সূর্য ও চন্দ্রগ্রহণ দুটিতেই জামাতে; শাফেয়ি মতে পরে খুতবা।", "en": "Two rak''ahs, each with two standings and two ruku''s: long recitation, long ruku'', rise and recite again (shorter), ruku'' again (shorter), then two sajdahs. Both eclipses in congregation; Shafi''is add a khutbah after."}, "evidence": {"bn": "আয়েশা (রা.)-এর বর্ণনা (সহিহ বুখারি ১০৪৪, ১০৪৬); সহিহ মুসলিম ৯০১। নবীজি (সা.) নামাজের পর খুতবা দিয়েছেন (সহিহ বুখারি ১০৪৪)।", "en": "The report of ''A''ishah (Sahih al-Bukhari 1044, 1046); Sahih Muslim 901. The Prophet addressed the people after the prayer (Sahih al-Bukhari 1044)."}}], "check": true}, {"type": "heading", "text": {"bn": "গ্রহণের সময় যা করবেন", "en": "What to do during an eclipse"}}, {"type": "list", "items": [{"bn": "নামাজ পড়া, বেশি বেশি দোয়া, তাকবির ও ইস্তিগফার", "en": "Pray, and make abundant du''a, takbir and istighfar"}, {"bn": "সদকা করা (সহিহ বুখারি ১০৪৪)", "en": "Give charity (Sahih al-Bukhari 1044)"}, {"bn": "গ্রহণকে কারও জন্ম-মৃত্যু বা ভাগ্যের সাথে জড়িয়ে কুসংস্কার না করা", "en": "Do not tie the eclipse to anyone''s birth, death or fortune"}, {"bn": "মাকরুহ সময়ে গ্রহণ হলে হানাফি মতে নামাজ না পড়ে দোয়া ও জিকির করা", "en": "If it falls in a disliked time, Hanafis make du''a and dhikr instead of praying"}]}, {"type": "note", "tone": "info", "text": {"bn": "গর্ভবতী নারীর খাওয়া-দাওয়া বা কাজকর্ম বন্ধ রাখার মতো প্রচলিত ধারণার কোনো ভিত্তি কুরআন-হাদিসে নেই।", "en": "Popular beliefs such as pregnant women having to stop eating or working during an eclipse have no basis in the Quran or hadith."}}]', 'in_review', 120 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '8294b2c5-a7c7-5ad7-be46-637318834293', id, 'istisqa-prayer', '{"bn": "ইসতিসকা: বৃষ্টির জন্য নামাজ", "en": "Istisqa: Prayer for Rain"}', '{"bn": "খরা ও অনাবৃষ্টিতে আল্লাহর কাছে বৃষ্টি চাওয়ার পদ্ধতি: ইস্তিগফার, দোয়া, নামাজ ও খুতবা।", "en": "Asking Allah for rain in drought: repentance, du''a, prayer and khutbah."}', 'detail', '[{"type": "arabic", "ar": "فَقُلْتُ اسْتَغْفِرُوا رَبَّكُمْ إِنَّهُ كَانَ غَفَّارًا ۝ يُرْسِلِ السَّمَاءَ عَلَيْكُمْ مِدْرَارًا", "pron": {"bn": "ফাকুলতুস তাগফিরূ রাব্বাকুম ইন্নাহূ কানা গাফফারা, ইউরসিলিস সামাআ আলাইকুম মিদরারা।", "en": "Faqultustaghfiru Rabbakum innahu kana ghaffara, yursilis-sama''a ''alaykum midrara."}, "meaning": {"bn": "আমি বললাম, তোমাদের রবের কাছে ক্ষমা চাও, নিশ্চয়ই তিনি অতি ক্ষমাশীল। তিনি তোমাদের ওপর প্রচুর বৃষ্টি বর্ষণ করবেন।", "en": "I said: seek forgiveness of your Lord, He is ever Forgiving. He will send the sky upon you in abundant rain."}, "ref": {"bn": "সূরা নূহ ৭১:১০–১১", "en": "Nuh 71:10–11"}}, {"type": "text", "text": {"bn": "নবীজি (সা.) খরার সময় ঈদগাহের মতো খোলা মাঠে বের হয়ে কিবলামুখী হয়ে দোয়া করেছেন, চাদর উল্টে নিয়েছেন এবং দুই রাকাত নামাজ পড়েছেন (সহিহ বুখারি ১০১২)। আবার জুমার খুতবায় হাত তুলে বৃষ্টির দোয়াও করেছেন (সহিহ বুখারি ১০১৩, ১০১৪)।", "en": "In drought the Prophet went out to the open prayer ground, faced the qiblah, made du''a, turned his cloak inside out and prayed two rak''ahs (Sahih al-Bukhari 1012). He also raised his hands in the Friday khutbah asking for rain (Sahih al-Bukhari 1013, 1014)."}}, {"type": "differ", "title": {"bn": "ইসতিসকায় নামাজ আছে কি", "en": "Is there a set prayer for istisqa"}, "views": [{"label": {"bn": "ইমাম আবু হানিফা (রহ.)", "en": "Imam Abu Hanifah"}, "text": {"bn": "ইসতিসকার মূল হলো দোয়া ও ইস্তিগফার; নির্দিষ্ট জামাতের নামাজ সুন্নত নয়, তবে কেউ একা নামাজ পড়লে ভালো।", "en": "Istisqa is essentially du''a and istighfar; a congregational prayer is not a set sunnah, though praying individually is good."}, "evidence": {"bn": "নবীজি (সা.) জুমার খুতবায় শুধু দোয়া করেছেন, তাতেই বৃষ্টি হয়েছে (সহিহ বুখারি ১০১৩); সূরা নূহ ৭১:১০–১১-এ ইস্তিগফারের কথা।", "en": "The Prophet only made du''a in the Friday khutbah and rain came (Sahih al-Bukhari 1013); Nuh 71:10–11 mentions istighfar."}}, {"label": {"bn": "ইমাম আবু ইউসুফ ও মুহাম্মাদ (রহ.) এবং শাফেয়ি, মালেকি, হাম্বলি", "en": "Abu Yusuf, Muhammad, and the Shafi''i, Maliki, Hanbali schools"}, "text": {"bn": "জামাতে দুই রাকাত নামাজ সুন্নত, জোরে কিরাত, সাথে খুতবা ও দোয়া। শাফেয়ি ও হাম্বলি মতে ঈদের মতো অতিরিক্ত তাকবিরসহ।", "en": "Two rak''ahs in congregation are sunnah, recited aloud, with a khutbah and du''a; Shafi''is and Hanbalis add the Eid takbirs."}, "evidence": {"bn": "আবদুল্লাহ ইবনে যায়েদ (রা.)-এর বর্ণনা (সহিহ বুখারি ১০১২)।", "en": "The report of ''Abdullah ibn Zayd (Sahih al-Bukhari 1012)."}}]}, {"type": "heading", "text": {"bn": "আদব ও প্রস্তুতি", "en": "Etiquette and preparation"}}, {"type": "list", "items": [{"bn": "আগে থেকে তওবা, জুলুম ও হারাম উপার্জন ছেড়ে দেওয়া, অন্যের হক ফিরিয়ে দেওয়া", "en": "Repent beforehand, stop injustice and unlawful earnings, return others'' rights"}, {"bn": "সদকা করা এবং সম্ভব হলে রোজা রাখা", "en": "Give charity and fast if possible"}, {"bn": "সাধারণ পোশাকে বিনয়ের সাথে মাঠে যাওয়া; বয়স্ক, শিশু ও দুর্বলদের সাথে নেওয়া", "en": "Go out humbly in plain clothes; bring elders, children and the weak"}, {"bn": "দোয়ার সময় হাত ভালোভাবে ওপরে তোলা", "en": "Raise the hands well in du''a"}, {"bn": "খুতবা বা দোয়ার শেষে ইমামের চাদর উল্টে নেওয়া (অবস্থা পরিবর্তনের আশার প্রতীক) (সহিহ বুখারি ১০১২)", "en": "The imam turns his cloak at the end (symbolising hope for change) (Sahih al-Bukhari 1012)"}]}, {"type": "arabic", "label": {"bn": "বৃষ্টির দোয়া", "en": "Du''a for rain"}, "ar": "اللّٰهُمَّ اسْقِنَا غَيْثًا مُغِيثًا، مَرِيئًا مَرِيعًا، نَافِعًا غَيْرَ ضَارٍّ، عَاجِلًا غَيْرَ آجِلٍ", "pron": {"bn": "আল্লাহুম্মাসকিনা গাইসান মুগীসান, মারীআন মারীআন, নাফিআন গাইরা দাররিন, আজিলান গাইরা আজিল।", "en": "Allahummasqina ghaythan mughithan, mari''an mari''an, nafi''an ghayra darr, ''ajilan ghayra ajil."}, "meaning": {"bn": "হে আল্লাহ, আমাদের এমন বৃষ্টি দাও, যা সাহায্যকারী, সুপেয় ও ফসল উৎপাদনকারী, উপকারী, ক্ষতিকর নয়, দ্রুত আসে, দেরিতে নয়।", "en": "O Allah, give us rain that relieves, wholesome and fertile, beneficial not harmful, soon and not delayed."}, "ref": {"bn": "সুনান আবু দাউদ ১১৬৯ (জাবির রা.)", "en": "Sunan Abi Dawud 1169 (Jabir)"}}, {"type": "arabic", "label": {"bn": "সংক্ষিপ্ত দোয়া", "en": "Short du''a"}, "ar": "اللّٰهُمَّ أَغِثْنَا، اللّٰهُمَّ أَغِثْنَا، اللّٰهُمَّ أَغِثْنَا", "pron": {"bn": "আল্লাহুম্মা আগিসনা, আল্লাহুম্মা আগিসনা, আল্লাহুম্মা আগিসনা।", "en": "Allahumma aghithna, Allahumma aghithna, Allahumma aghithna."}, "meaning": {"bn": "হে আল্লাহ, আমাদের বৃষ্টি দিয়ে সাহায্য করো (তিনবার)।", "en": "O Allah, relieve us with rain (three times)."}, "ref": {"bn": "সহিহ বুখারি ১০১৪", "en": "Sahih al-Bukhari 1014"}}]', 'in_review', 130 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '7572c7d2-6daf-539d-924a-9d162c2ed557', id, 'tahiyyatul-masjid-wudu', '{"bn": "তাহিয়্যাতুল মসজিদ ও তাহিয়্যাতুল ওযু", "en": "Tahiyyat al-Masjid and Tahiyyat al-Wudu"}', '{"bn": "মসজিদে ঢুকে বসার আগে দুই রাকাত, আর ওযুর পর দুই রাকাত নফল: ফজিলত ও নিয়ম।", "en": "Two rak''ahs on entering the mosque before sitting, and two after wudu: their virtue and rules."}', 'basic', '[{"type": "heading", "text": {"bn": "তাহিয়্যাতুল মসজিদ", "en": "Tahiyyat al-masjid (greeting the mosque)"}}, {"type": "arabic", "ar": "إِذَا دَخَلَ أَحَدُكُمُ الْمَسْجِدَ فَلْيَرْكَعْ رَكْعَتَيْنِ قَبْلَ أَنْ يَجْلِسَ", "pron": {"bn": "ইযা দাখালা আহাদুকুমুল মাসজিদা ফালইয়ারকা'' রাকআতাইনি কাবলা আই ইয়াজলিস।", "en": "Idha dakhala ahadukumul-masjida falyarka'' rak''atayni qabla ay yajlis."}, "meaning": {"bn": "তোমাদের কেউ মসজিদে প্রবেশ করলে বসার আগে যেন দুই রাকাত নামাজ পড়ে নেয়।", "en": "When one of you enters the mosque, let him pray two rak''ahs before sitting."}, "ref": {"bn": "সহিহ বুখারি ৪৪৪", "en": "Sahih al-Bukhari 444"}}, {"type": "list", "items": [{"bn": "হুকুম: অধিকাংশ আলেমের মতে সুন্নত (মুস্তাহাব)।", "en": "Ruling: sunnah (recommended) according to most scholars."}, {"bn": "মসজিদে ঢুকে বসার আগে পড়বেন। ঢুকেই কোনো ফরজ বা সুন্নত নামাজ পড়লে তাতেই তাহিয়্যাতুল মসজিদ আদায় হয়ে যায়; আলাদা পড়তে হয় না।", "en": "Pray before sitting. If you start a fard or sunnah prayer on entering, it counts; no separate prayer is needed."}, {"bn": "হানাফি মতে মাকরুহ সময়ে (সূর্যোদয়, ঠিক দুপুর, সূর্যাস্ত, এবং ফজর ও আসরের পর) পড়বেন না; তখন জিকির করুন। শাফেয়ি মতে এটি কারণযুক্ত নামাজ বলে সেই সময়েও পড়া যায়।", "en": "Hanafis do not pray it in the disliked times (sunrise, noon, sunset, after Fajr and ''Asr) but make dhikr instead; Shafi''is allow it then since it has a cause."}, {"bn": "জুমার খুতবা চলাকালে ঢুকলে কী করবেন, তা নিয়ে মতভেদ আছে; ‘জুমার নামাজ’ অধ্যায় দেখুন।", "en": "On entering during the Friday khutbah, scholars differ; see the Jumu''ah guide."}, {"bn": "ইকামত হয়ে গেলে তাহিয়্যাতুল মসজিদ না পড়ে জামাতে শরিক হবেন।", "en": "If the iqamah has been called, join the congregation instead."}]}, {"type": "heading", "text": {"bn": "তাহিয়্যাতুল ওযু", "en": "Tahiyyat al-wudu (prayer after wudu)"}}, {"type": "text", "text": {"bn": "ওযু করার পর দুই রাকাত নফল পড়া সুন্নত। নবীজি (সা.) বলেছেন, যে মুসলিম সুন্দরভাবে ওযু করে, তারপর মন ও মুখ পুরোপুরি নামাজে নিবদ্ধ রেখে দুই রাকাত পড়ে, তার জন্য জান্নাত অবধারিত হয়ে যায় (সহিহ মুসলিম ২৩৪)।", "en": "Praying two rak''ahs after wudu is sunnah. The Prophet said: any Muslim who performs wudu well, then prays two rak''ahs with heart and face devoted to them, Paradise becomes due for him (Sahih Muslim 234)."}}, {"type": "text", "text": {"bn": "নবীজি (সা.) বিলাল (রা.)-কে জিজ্ঞেস করলেন, ইসলামে তাঁর সবচেয়ে আশাব্যঞ্জক আমল কী, কারণ জান্নাতে তিনি বিলালের জুতার আওয়াজ শুনেছেন। বিলাল (রা.) বললেন, দিনে বা রাতে যখনই ওযু করেছি, সেই ওযু দিয়ে যতটুকু তাওফিক হয়েছে নামাজ পড়েছি (সহিহ বুখারি ১১৪৯)।", "en": "The Prophet asked Bilal about his most hopeful deed, as he had heard his footsteps in Paradise. Bilal said: whenever I made wudu, day or night, I prayed with it as much as was written for me (Sahih al-Bukhari 1149)."}}, {"type": "list", "items": [{"bn": "ওযুর অঙ্গ শুকানোর আগেই পড়া উত্তম বলে আলেমরা উল্লেখ করেছেন।", "en": "Scholars mention it is best to pray before the limbs dry."}, {"bn": "হানাফি মতে মাকরুহ সময়ে পড়বেন না।", "en": "Hanafis do not pray it in the disliked times."}, {"bn": "ওযুর পর কোনো ফরজ বা সুন্নত পড়লেও এর সওয়াব পাওয়ার আশা করা যায়।", "en": "One may hope for its reward even when praying a fard or sunnah right after wudu."}]}, {"type": "note", "tone": "tip", "text": {"bn": "নিয়ত মনে মনে করাই যথেষ্ট। উদাহরণ (প্রচলিত বাংলা): ‘আমি আল্লাহর জন্য দুই রাকাত তাহিয়্যাতুল মসজিদ (বা তাহিয়্যাতুল ওযু) নামাজ পড়ছি।’", "en": "The intention in the heart is enough. Example (common Bangla phrasing): ''I am praying two rak''ahs of tahiyyat al-masjid (or al-wudu) for Allah.''"}}]', 'in_review', 140 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'ca0d0339-e193-5ad5-a740-3f884431db8f', id, 'sajdah-tilawah', '{"bn": "সিজদায়ে তিলাওয়াত", "en": "Sajdah al-Tilawah (Prostration of Recitation)"}', '{"bn": "কুরআনের নির্দিষ্ট আয়াত পড়লে বা শুনলে যে সিজদা দিতে হয়: হুকুম, পদ্ধতি, দোয়া এবং সিজদার ১৫টি আয়াতের তালিকা।", "en": "The prostration made on reciting or hearing certain verses: ruling, method, du''a, and the list of the 15 places."}', 'basic', '[{"type": "text", "text": {"bn": "কুরআনের কিছু আয়াত পড়লে বা শুনলে একটি সিজদা দিতে হয়; একে সিজদায়ে তিলাওয়াত বলে। মুসহাফে এসব আয়াতের পাশে সাধারণত ‘۩’ চিহ্ন বা ‘সিজদা’ লেখা থাকে। নবীজি (সা.) বলেছেন, আদম সন্তান সিজদার আয়াত পড়ে সিজদা করলে শয়তান কাঁদতে কাঁদতে সরে যায় (সহিহ মুসলিম ৮১)।", "en": "Certain verses call for a prostration when recited or heard; this is sajdah al-tilawah. In the Mushaf they are usually marked with ''۩'' or the word ''sajdah''. The Prophet said that when the son of Adam recites a verse of prostration and prostrates, Shaytan withdraws weeping (Sahih Muslim 81)."}}, {"type": "differ", "title": {"bn": "হুকুম", "en": "Ruling"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "যে পড়ে এবং যে শোনে, উভয়ের ওপর ওয়াজিব।", "en": "Wajib on both the reciter and the listener."}, "evidence": {"bn": "কয়েকটি সিজদার আয়াতে সরাসরি সিজদার নির্দেশ আছে, যেমন ‘ফাসজুদূ লিল্লাহি ওয়া''বুদূ’ (সূরা নাজম ৫৩:৬২), ‘ওয়াসজুদ ওয়াকতারিব’ (সূরা আলাক ৯৬:১৯); সহিহ মুসলিম ৮১।", "en": "Some of these verses command prostration, e.g. An-Najm 53:62 and Al-''Alaq 96:19; Sahih Muslim 81."}}, {"label": {"bn": "শাফেয়ি, মালেকি ও হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "সুন্নতে মুয়াক্কাদা, ওয়াজিব নয়।", "en": "A confirmed sunnah, not obligatory."}, "evidence": {"bn": "উমর (রা.) জুমার খুতবায় সিজদার আয়াত পড়ে একবার সিজদা করেন, আরেক জুমায় করেননি এবং বলেন, আল্লাহ এটি ফরজ করেননি, তবে আমরা চাইলে করি (সহিহ বুখারি ১০৭৭); যায়েদ ইবনে সাবিত (রা.) নবীজি (সা.)-এর সামনে সূরা নাজম পড়লেন, তিনি সিজদা করেননি (সহিহ বুখারি ১০৭২)।", "en": "''Umar prostrated on the minbar one Friday and not the next, saying Allah had not made it obligatory (Sahih al-Bukhari 1077); Zayd ibn Thabit recited An-Najm before the Prophet and he did not prostrate (Sahih al-Bukhari 1072)."}}]}, {"type": "heading", "text": {"bn": "পদ্ধতি (হানাফি)", "en": "Method (Hanafi)"}}, {"type": "step", "title": {"bn": "পবিত্রতা ও কিবলা", "en": "Purity and qiblah"}, "text": {"bn": "নামাজের মতোই ওযু, পবিত্র কাপড় ও জায়গা, সতর ঢাকা ও কিবলামুখী হওয়া শর্ত (অধিকাংশ আলেমের মত)।", "en": "As for prayer: wudu, clean clothes and place, covered awrah, facing the qiblah (view of most scholars)."}}, {"type": "step", "title": {"bn": "নিয়ত", "en": "Intention"}, "text": {"bn": "মনে মনে সিজদায়ে তিলাওয়াতের নিয়ত করুন। দাঁড়িয়ে থেকে সিজদায় যাওয়া মুস্তাহাব, বসে থেকেও যাওয়া যায়।", "en": "Intend the prostration of recitation in your heart. Going down from standing is preferred; from sitting is also fine."}}, {"type": "step", "title": {"bn": "তাকবির বলে সিজদা", "en": "Takbir and prostrate"}, "text": {"bn": "হাত না তুলে ‘আল্লাহু আকবার’ বলে একটি সিজদা করুন; সিজদায় অন্তত তিনবার ‘সুবহানা রাব্বিয়াল আ''লা’ পড়ুন বা নিচের দোয়াটি পড়ুন।", "en": "Without raising your hands, say ''Allahu Akbar'' and make one sajdah; say ''Subhana Rabbiyal-A''la'' at least three times or the du''a below."}}, {"type": "step", "title": {"bn": "তাকবির বলে উঠা", "en": "Rise with takbir"}, "text": {"bn": "‘আল্লাহু আকবার’ বলে উঠে যান। হানাফি মতে নামাজের বাইরে এই সিজদায় তাশাহহুদ বা সালাম নেই।", "en": "Rise saying ''Allahu Akbar''. In the Hanafi school there is no tashahhud or salam for it outside prayer."}}, {"type": "arabic", "label": {"bn": "সিজদায়ে তিলাওয়াতের দোয়া", "en": "Du''a in the prostration of recitation"}, "ar": "سَجَدَ وَجْهِيَ لِلَّذِي خَلَقَهُ، وَشَقَّ سَمْعَهُ وَبَصَرَهُ بِحَوْلِهِ وَقُوَّتِهِ", "pron": {"bn": "সাজাদা ওয়াজহিয়া লিল্লাযী খালাকাহূ, ওয়া শাক্কা সাম''আহূ ওয়া বাসারাহূ বিহাওলিহী ওয়া কুওয়াতিহ।", "en": "Sajada wajhiya lilladhi khalaqahu, wa shaqqa sam''ahu wa basarahu bihawlihi wa quwwatih."}, "meaning": {"bn": "আমার মুখমণ্ডল সিজদা করল সেই সত্তার জন্য, যিনি একে সৃষ্টি করেছেন এবং নিজ শক্তি ও সামর্থ্যে এর কান ও চোখ খুলে দিয়েছেন।", "en": "My face prostrates to the One who created it and brought forth its hearing and sight by His might and power."}, "ref": {"bn": "জামে তিরমিজি ৫৮০; সুনান আবু দাউদ ১৪১৪", "en": "Jami'' al-Tirmidhi 580; Sunan Abi Dawud 1414"}}, {"type": "note", "tone": "info", "text": {"bn": "এই দোয়ার হাদিসকে শাইখ আলবানিসহ অনেকে সহিহ বলেছেন, তবে আবু দাউদের সনদে একজন অজ্ঞাত বর্ণনাকারী থাকায় কেউ কেউ দুর্বল বলেছেন। ‘সুবহানা রাব্বিয়াল আ''লা’ পড়াই যথেষ্ট।", "en": "Many, including al-Albani, graded this du''a''s hadith sahih, though some called it weak because Abu Dawud''s chain has an unnamed narrator. Saying ''Subhana Rabbiyal-A''la'' is enough."}}, {"type": "heading", "text": {"bn": "কিছু মাসআলা", "en": "Some rulings"}}, {"type": "list", "items": [{"bn": "নামাজের মধ্যে সিজদার আয়াত পড়লে সাথে সাথে (তিন আয়াত পরিমাণ দেরির আগে) সিজদা করে দাঁড়িয়ে বাকি কিরাত পড়বেন। ইমাম পড়লে মুক্তাদিরাও ইমামের সাথে সিজদা করবেন।", "en": "If recited in prayer, prostrate promptly (before about three verses'' delay), then stand and continue. Followers prostrate with the imam."}, {"bn": "নামাজের বাইরে পড়লে সাথে সাথে করা উত্তম; পরে করলেও আদায় হয়ে যায় (হানাফি)।", "en": "Outside prayer, it is best done at once, but may be done later (Hanafi)."}, {"bn": "একই বৈঠকে একই আয়াত বারবার পড়লে বা শুনলে একটি সিজদাই যথেষ্ট (হানাফি)।", "en": "Repeating the same verse in one sitting needs only one prostration (Hanafi)."}, {"bn": "সিজদার আয়াতের শুধু অনুবাদ পড়লে বা রেকর্ড করা তিলাওয়াত শুনলে সিজদা ওয়াজিব হয় কি না, তা নিয়ে আলেমদের মতভেদ আছে; অনেকের মতে রেকর্ডিং শুনলে ওয়াজিব হয় না।", "en": "Scholars differ on whether reading only a translation or hearing a recording requires it; many say a recording does not."}, {"bn": "ঋতুস্রাব বা নিফাস অবস্থায় শুনলে নারীর ওপর সিজদা ওয়াজিব হয় না (হানাফি)।", "en": "A woman in menstruation or post-natal bleeding who hears it owes no prostration (Hanafi)."}], "check": true}, {"type": "heading", "text": {"bn": "কুরআনে সিজদার আয়াতসমূহ", "en": "The verses of prostration"}}, {"type": "table", "head": [{"bn": "ক্রম", "en": "No."}, {"bn": "সূরা", "en": "Surah"}, {"bn": "আয়াত", "en": "Ayah"}, {"bn": "পারা", "en": "Juz''"}, {"bn": "মন্তব্য", "en": "Note"}], "rows": [[{"bn": "১", "en": "1"}, {"bn": "আ''রাফ (৭)", "en": "Al-A''raf (7)"}, {"bn": "২০৬", "en": "206"}, {"bn": "৯", "en": "9"}, {"bn": "সর্বসম্মত", "en": "Agreed"}], [{"bn": "২", "en": "2"}, {"bn": "রা''দ (১৩)", "en": "Ar-Ra''d (13)"}, {"bn": "১৫", "en": "15"}, {"bn": "১৩", "en": "13"}, {"bn": "সর্বসম্মত", "en": "Agreed"}], [{"bn": "৩", "en": "3"}, {"bn": "নাহল (১৬)", "en": "An-Nahl (16)"}, {"bn": "৫০", "en": "50"}, {"bn": "১৪", "en": "14"}, {"bn": "সর্বসম্মত", "en": "Agreed"}], [{"bn": "৪", "en": "4"}, {"bn": "বনি ইসরাঈল / ইসরা (১৭)", "en": "Al-Isra (17)"}, {"bn": "১০৯", "en": "109"}, {"bn": "১৫", "en": "15"}, {"bn": "সর্বসম্মত", "en": "Agreed"}], [{"bn": "৫", "en": "5"}, {"bn": "মারইয়াম (১৯)", "en": "Maryam (19)"}, {"bn": "৫৮", "en": "58"}, {"bn": "১৬", "en": "16"}, {"bn": "সর্বসম্মত", "en": "Agreed"}], [{"bn": "৬", "en": "6"}, {"bn": "হজ (২২)", "en": "Al-Hajj (22)"}, {"bn": "১৮", "en": "18"}, {"bn": "১৭", "en": "17"}, {"bn": "সর্বসম্মত", "en": "Agreed"}], [{"bn": "৭", "en": "7"}, {"bn": "হজ (২২)", "en": "Al-Hajj (22)"}, {"bn": "৭৭", "en": "77"}, {"bn": "১৭", "en": "17"}, {"bn": "শাফেয়ি ও হাম্বলি মতে সিজদা; হানাফি ও মালেকি মতে এটি নামাজের সিজদার নির্দেশ, তিলাওয়াতের সিজদা নয়", "en": "A prostration for Shafi''is and Hanbalis; Hanafis and Malikis see it as about the prayer''s sajdah, not a sajdah of recitation"}], [{"bn": "৮", "en": "8"}, {"bn": "ফুরকান (২৫)", "en": "Al-Furqan (25)"}, {"bn": "৬০", "en": "60"}, {"bn": "১৯", "en": "19"}, {"bn": "সর্বসম্মত", "en": "Agreed"}], [{"bn": "৯", "en": "9"}, {"bn": "নামল (২৭)", "en": "An-Naml (27)"}, {"bn": "২৬", "en": "26"}, {"bn": "১৯", "en": "19"}, {"bn": "সর্বসম্মত", "en": "Agreed"}], [{"bn": "১০", "en": "10"}, {"bn": "সাজদা (৩২)", "en": "As-Sajdah (32)"}, {"bn": "১৫", "en": "15"}, {"bn": "২১", "en": "21"}, {"bn": "সর্বসম্মত", "en": "Agreed"}], [{"bn": "১১", "en": "11"}, {"bn": "সোয়াদ (৩৮)", "en": "Sad (38)"}, {"bn": "২৪", "en": "24"}, {"bn": "২৩", "en": "23"}, {"bn": "হানাফি ও মালেকি মতে তিলাওয়াতের সিজদা; শাফেয়ি ও হাম্বলি মতে শুকরের সিজদা (নামাজের ভেতরে নয়)", "en": "A sajdah of recitation for Hanafis and Malikis; for Shafi''is and Hanbalis a prostration of thanks (not inside prayer)"}], [{"bn": "১২", "en": "12"}, {"bn": "হা-মিম সাজদা / ফুসসিলাত (৪১)", "en": "Fussilat (41)"}, {"bn": "৩৮", "en": "38"}, {"bn": "২৪", "en": "24"}, {"bn": "সর্বসম্মত (মালেকি মতে আয়াত ৩৭-এ)", "en": "Agreed (Maliki: at ayah 37)"}], [{"bn": "১৩", "en": "13"}, {"bn": "নাজম (৫৩)", "en": "An-Najm (53)"}, {"bn": "৬২", "en": "62"}, {"bn": "২৭", "en": "27"}, {"bn": "মালেকি প্রসিদ্ধ মতে নয়, অন্যদের মতে সিজদা", "en": "Not in the well-known Maliki view; a sajdah for the others"}], [{"bn": "১৪", "en": "14"}, {"bn": "ইনশিকাক (৮৪)", "en": "Al-Inshiqaq (84)"}, {"bn": "২১", "en": "21"}, {"bn": "৩০", "en": "30"}, {"bn": "মালেকি প্রসিদ্ধ মতে নয়, অন্যদের মতে সিজদা", "en": "Not in the well-known Maliki view; a sajdah for the others"}], [{"bn": "১৫", "en": "15"}, {"bn": "আলাক (৯৬)", "en": "Al-''Alaq (96)"}, {"bn": "১৯", "en": "19"}, {"bn": "৩০", "en": "30"}, {"bn": "মালেকি প্রসিদ্ধ মতে নয়, অন্যদের মতে সিজদা", "en": "Not in the well-known Maliki view; a sajdah for the others"}]]}, {"type": "text", "text": {"bn": "হানাফি মতে সিজদার আয়াত মোট ১৪টি (তালিকার ৭ নম্বর বাদে)। শাফেয়ি ও হাম্বলি মতেও ১৪টি (১১ নম্বর বাদে)। আয়াত নম্বর প্রচলিত মুসহাফ (হাফস) অনুযায়ী।", "en": "Hanafis count 14 (all except no. 7). Shafi''is and Hanbalis also count 14 (all except no. 11). Ayah numbers follow the common (Hafs) Mushaf."}}, {"type": "note", "tone": "info", "text": {"bn": "সূরা নাজমের সিজদা নবীজি (সা.) মক্কায় করেছেন এবং সাথের সবাই সিজদা করেছিল (সহিহ বুখারি ১০৬৭)।", "en": "The Prophet prostrated at An-Najm in Makkah and those with him did too (Sahih al-Bukhari 1067)."}}]', 'in_review', 150 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '48df6e66-b152-518c-bc7d-d246bcb9653e', id, 'six-kalimas', '{"bn": "ছয় কালিমা", "en": "The Six Kalimas"}', '{"bn": "বাংলাদেশে প্রচলিতভাবে শেখানো ছয় কালিমা: আরবি, উচ্চারণ ও অর্থ, এবং প্রতিটির উৎস সম্পর্কে সংক্ষিপ্ত তথ্য।", "en": "The six kalimas as commonly taught in Bangladesh: Arabic, pronunciation and meaning, with a note on each one''s source."}', 'basic', '[{"type": "note", "tone": "info", "text": {"bn": "‘ছয় কালিমা’ নামে এই তালিকা উপমহাদেশে শিশুদের ঈমানের মৌলিক কথা শেখানোর একটি প্রচলিত পদ্ধতি; কুরআন বা হাদিসে এই ছয়টিকে একসাথে ‘ছয় কালিমা’ বলা হয়নি। প্রথম দুটির শব্দ কুরআন-হাদিসে সরাসরি আছে; বাকিগুলোর কিছু অংশ হাদিস বা কুরআন থেকে নেওয়া, আর কিছু অংশ শিক্ষার উদ্দেশ্যে সাজানো, যার অর্থ ইসলামি আকিদার সাথে সামঞ্জস্যপূর্ণ। অঞ্চলভেদে ক্রম ও শব্দেও ভিন্নতা আছে (যেমন পাকিস্তান-ভারতে ‘তামজীদ’ হিসেবে ‘সুবহানাল্লাহি ওয়াল হামদু লিল্লাহ...’ পড়ানো হয়)।", "en": "The ''six kalimas'' list is a teaching tradition in the subcontinent for teaching children the basics of faith; the Quran and hadith do not group these six together. The first two are found directly in the Quran and hadith; the others combine phrases from the Quran or hadith with wording arranged for teaching, whose meanings agree with Islamic belief. The order and wording vary by region (e.g. in Pakistan and India ''Tamjid'' is ''Subhanallahi wal-hamdu lillah...'')."}}, {"type": "heading", "text": {"bn": "১. কালিমা তাইয়্যেবা", "en": "1. Kalima Tayyibah (the pure word)"}}, {"type": "arabic", "label": {"bn": "কালিমা তাইয়্যেবা", "en": "Kalima Tayyibah"}, "ar": "لَا إِلٰهَ إِلَّا اللّٰهُ مُحَمَّدٌ رَسُولُ اللّٰهِ", "pron": {"bn": "লা ইলাহা ইল্লাল্লাহু মুহাম্মাদুর রাসূলুল্লাহ।", "en": "La ilaha illallahu Muhammadur Rasulullah."}, "meaning": {"bn": "আল্লাহ ছাড়া কোনো ইলাহ (সত্য উপাস্য) নেই, মুহাম্মাদ (সা.) আল্লাহর রাসুল।", "en": "There is no god (worthy of worship) but Allah; Muhammad is the Messenger of Allah."}, "ref": {"bn": "দুই অংশ কুরআনে: সূরা মুহাম্মাদ ৪৭:১৯ ও সূরা ফাতহ ৪৮:২৯", "en": "Both parts in the Quran: Muhammad 47:19 and Al-Fath 48:29"}}, {"type": "heading", "text": {"bn": "২. কালিমা শাহাদাত", "en": "2. Kalima Shahadah (testimony)"}}, {"type": "arabic", "label": {"bn": "কালিমা শাহাদাত", "en": "Kalima Shahadah"}, "ar": "أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ", "pron": {"bn": "আশহাদু আল লা ইলাহা ইল্লাল্লাহু ওয়াহদাহূ লা শারীকা লাহূ, ওয়া আশহাদু আন্না মুহাম্মাদান আবদুহূ ওয়া রাসূলুহ।", "en": "Ashhadu al la ilaha illallahu wahdahu la sharika lah, wa ashhadu anna Muhammadan ''abduhu wa rasuluh."}, "meaning": {"bn": "আমি সাক্ষ্য দিচ্ছি যে আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি এক, তাঁর কোনো শরিক নেই; এবং আমি সাক্ষ্য দিচ্ছি যে মুহাম্মাদ (সা.) তাঁর বান্দা ও রাসুল।", "en": "I bear witness that there is no god but Allah, alone, without partner, and I bear witness that Muhammad is His servant and Messenger."}, "ref": {"bn": "সহিহ মুসলিম ২৩৪ (ওযুর পর এই শাহাদাত পড়ার ফজিলত)", "en": "Sahih Muslim 234 (virtue of saying it after wudu)"}}, {"type": "heading", "text": {"bn": "৩. কালিমা তাওহীদ", "en": "3. Kalima Tawhid (oneness)"}}, {"type": "arabic", "label": {"bn": "কালিমা তাওহীদ (বাংলাদেশে প্রচলিত পাঠ)", "en": "Kalima Tawhid (as taught in Bangladesh)"}, "ar": "لَا إِلٰهَ إِلَّا أَنْتَ وَاحِدًا لَا ثَانِيَ لَكَ، مُحَمَّدٌ رَسُولُ اللّٰهِ إِمَامُ الْمُتَّقِينَ رَسُولُ رَبِّ الْعَالَمِينَ", "pron": {"bn": "লা ইলাহা ইল্লা আনতা ওয়াহিদাল লা সানিয়া লাকা, মুহাম্মাদুর রাসূলুল্লাহি ইমামুল মুত্তাকীনা রাসূলু রাব্বিল আলামীন।", "en": "La ilaha illa anta wahidan la thaniya lak, Muhammadur Rasulullahi imamul-muttaqina rasulu Rabbil-''alamin."}, "meaning": {"bn": "(হে আল্লাহ,) তুমি ছাড়া কোনো ইলাহ নেই, তুমি এক, তোমার কোনো দ্বিতীয় নেই। মুহাম্মাদ (সা.) আল্লাহর রাসুল, মুত্তাকিদের ইমাম, জগতসমূহের রবের রাসুল।", "en": "There is no god but You, One, with no second to You. Muhammad is the Messenger of Allah, leader of the God-fearing, messenger of the Lord of the worlds."}, "ref": {"bn": "শিক্ষার উদ্দেশ্যে সাজানো পাঠ; হুবহু এই শব্দে কোনো হাদিস জানা নেই", "en": "A teaching text; no hadith with this exact wording is known"}, "check": true}, {"type": "heading", "text": {"bn": "৪. কালিমা তামজীদ", "en": "4. Kalima Tamjid (glorification)"}}, {"type": "arabic", "label": {"bn": "কালিমা তামজীদ (বাংলাদেশে প্রচলিত পাঠ)", "en": "Kalima Tamjid (as taught in Bangladesh)"}, "ar": "لَا إِلٰهَ إِلَّا أَنْتَ نُورًا يَهْدِي اللّٰهُ لِنُورِهِ مَنْ يَشَاءُ، مُحَمَّدٌ رَسُولُ اللّٰهِ إِمَامُ الْمُرْسَلِينَ خَاتَمُ النَّبِيِّينَ", "pron": {"bn": "লা ইলাহা ইল্লা আনতা নূরাই ইয়াহদিয়াল্লাহু লিনূরিহী মাই ইয়াশাউ, মুহাম্মাদুর রাসূলুল্লাহি ইমামুল মুরসালীনা খাতামুন নাবিয়্যীন।", "en": "La ilaha illa anta nuran yahdillahu linurihi man yasha'', Muhammadur Rasulullahi imamul-mursalina khatamun-nabiyyin."}, "meaning": {"bn": "(হে আল্লাহ,) তুমি ছাড়া কোনো ইলাহ নেই, তুমি নূর (আলো); আল্লাহ যাকে চান তাঁর নূরের দিকে পথ দেখান। মুহাম্মাদ (সা.) আল্লাহর রাসুল, রাসুলদের ইমাম, সর্বশেষ নবী।", "en": "There is no god but You, the Light; Allah guides to His light whom He wills. Muhammad is the Messenger of Allah, leader of the messengers, the last of the prophets."}, "ref": {"bn": "শিক্ষার উদ্দেশ্যে সাজানো পাঠ; ‘ইয়াহদিল্লাহু লিনূরিহী মাই ইয়াশা’ অংশ সূরা নূর ২৪:৩৫ থেকে, ‘খাতামুন নাবিয়্যীন’ সূরা আহযাব ৩৩:৪০ থেকে", "en": "A teaching text; ''Allah guides to His light whom He wills'' is from An-Nur 24:35 and ''last of the prophets'' from Al-Ahzab 33:40"}, "check": true}, {"type": "heading", "text": {"bn": "৫. কালিমা রদ্দে কুফর", "en": "5. Kalima Radd al-Kufr (rejecting disbelief)"}}, {"type": "arabic", "label": {"bn": "কালিমা রদ্দে কুফর", "en": "Kalima Radd al-Kufr"}, "ar": "اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ أَنْ أُشْرِكَ بِكَ شَيْئًا وَأَنَا أَعْلَمُ بِهِ، وَأَسْتَغْفِرُكَ لِمَا لَا أَعْلَمُ بِهِ، تُبْتُ عَنْهُ، وَتَبَرَّأْتُ مِنَ الْكُفْرِ وَالشِّرْكِ وَالْمَعَاصِي كُلِّهَا، وَأَسْلَمْتُ وَآمَنْتُ، وَأَقُولُ: لَا إِلٰهَ إِلَّا اللّٰهُ مُحَمَّدٌ رَسُولُ اللّٰهِ", "pron": {"bn": "আল্লাহুম্মা ইন্নী আঊযুবিকা মিন আন উশরিকা বিকা শাইআও ওয়া আনা আ''লামু বিহী, ওয়া আসতাগফিরুকা লিমা লা আ''লামু বিহী, তুবতু আনহু, ওয়া তাবাররা''তু মিনাল কুফরি ওয়াশ শিরকি ওয়াল মাআসী কুল্লিহা, ওয়া আসলামতু ওয়া আমানতু, ওয়া আকূলু লা ইলাহা ইল্লাল্লাহু মুহাম্মাদুর রাসূলুল্লাহ।", "en": "Allahumma inni a''udhu bika min an ushrika bika shay''an wa ana a''lamu bih, wa astaghfiruka lima la a''lamu bih, tubtu ''anhu, wa tabarra''tu minal-kufri wash-shirki wal-ma''asi kulliha, wa aslamtu wa amantu, wa aqulu la ilaha illallahu Muhammadur Rasulullah."}, "meaning": {"bn": "হে আল্লাহ, জেনে-বুঝে তোমার সাথে কিছু শরিক করা থেকে আমি তোমার আশ্রয় চাই, আর না জেনে যা করে ফেলি তার জন্য তোমার কাছে ক্ষমা চাই; আমি তা থেকে তওবা করলাম। আমি কুফর, শিরক ও সকল গুনাহ থেকে সম্পর্কমুক্ত হলাম। আমি ইসলাম গ্রহণ করলাম ও ঈমান আনলাম, এবং বলছি: আল্লাহ ছাড়া কোনো ইলাহ নেই, মুহাম্মাদ (সা.) আল্লাহর রাসুল।", "en": "O Allah, I seek refuge in You from knowingly associating anything with You, and I seek Your forgiveness for what I do unknowingly; I repent from it. I disown disbelief, shirk and all sins. I submit and I believe, and I say: there is no god but Allah, Muhammad is the Messenger of Allah."}, "ref": {"bn": "প্রথম অংশের কাছাকাছি দোয়া (শিরক থেকে আশ্রয়) ইমাম বুখারির আল-আদাবুল মুফরাদে বর্ণিত; বাকি অংশ শিক্ষার উদ্দেশ্যে সাজানো", "en": "A du''a close to the first part (refuge from shirk) is in al-Bukhari''s al-Adab al-Mufrad; the rest is arranged for teaching"}, "check": true}, {"type": "heading", "text": {"bn": "৬. কালিমা ইস্তেগফার", "en": "6. Kalima Istighfar (seeking forgiveness)"}}, {"type": "arabic", "label": {"bn": "কালিমা ইস্তেগফার", "en": "Kalima Istighfar"}, "ar": "أَسْتَغْفِرُ اللّٰهَ رَبِّي مِنْ كُلِّ ذَنْبٍ أَذْنَبْتُهُ عَمْدًا أَوْ خَطَأً، سِرًّا أَوْ عَلَانِيَةً، وَأَتُوبُ إِلَيْهِ مِنَ الذَّنْبِ الَّذِي أَعْلَمُ، وَمِنَ الذَّنْبِ الَّذِي لَا أَعْلَمُ، إِنَّكَ أَنْتَ عَلَّامُ الْغُيُوبِ، وَسَتَّارُ الْعُيُوبِ، وَغَفَّارُ الذُّنُوبِ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللّٰهِ الْعَلِيِّ الْعَظِيمِ", "pron": {"bn": "আসতাগফিরুল্লাহা রাব্বী মিন কুল্লি যামবিন আযনাবতুহূ আমদান আও খাতাআন, সিররান আও আলানিয়াতান, ওয়া আতূবু ইলাইহি মিনায যামবিল্লাযী আ''লামু, ওয়া মিনায যামবিল্লাযী লা আ''লামু, ইন্নাকা আনতা আল্লামুল গুয়ূবি, ওয়া সাত্তারুল উয়ূবি, ওয়া গাফফারুয যুনূবি, ওয়া লা হাওলা ওয়া লা কুওয়াতা ইল্লা বিল্লাহিল আলিয়্যিল আযীম।", "en": "Astaghfirullaha Rabbi min kulli dhanbin adhnabtuhu ''amdan aw khata''an, sirran aw ''alaniyah, wa atubu ilayhi minadh-dhanbil-ladhi a''lamu, wa minadh-dhanbil-ladhi la a''lamu, innaka anta ''allamul-ghuyubi, wa sattarul-''uyubi, wa ghaffarudh-dhunubi, wa la hawla wa la quwwata illa billahil-''aliyyil-''azim."}, "meaning": {"bn": "আমি আমার রব আল্লাহর কাছে ক্ষমা চাই সেই সব গুনাহের জন্য, যা আমি ইচ্ছায় বা ভুলে, গোপনে বা প্রকাশ্যে করেছি; আর তাঁর কাছে তওবা করি সেই গুনাহ থেকে যা আমি জানি এবং যা আমি জানি না। নিশ্চয়ই তুমি অদৃশ্য বিষয়ে সর্বজ্ঞ, দোষ গোপনকারী ও গুনাহ ক্ষমাকারী। মহান ও সুউচ্চ আল্লাহর সাহায্য ছাড়া গুনাহ থেকে বাঁচার ও নেক কাজ করার কোনো শক্তি নেই।", "en": "I seek forgiveness from Allah, my Lord, for every sin I committed, deliberately or by mistake, secretly or openly, and I turn to Him in repentance from the sin I know and the sin I do not know. You are the Knower of the unseen, the Concealer of faults, the Forgiver of sins. There is no power or strength except with Allah, the Most High, the Most Great."}, "ref": {"bn": "শিক্ষার উদ্দেশ্যে সাজানো পাঠ; ‘লা হাওলা ওয়া লা কুওয়াতা ইল্লা বিল্লাহ’ সহিহ হাদিসে প্রমাণিত", "en": "A teaching text; ''la hawla wa la quwwata illa billah'' is established in sahih hadith"}, "check": true}, {"type": "note", "tone": "tip", "text": {"bn": "ইস্তিগফারের জন্য সহিহ হাদিসে সবচেয়ে শ্রেষ্ঠ দোয়া হলো ‘সাইয়্যিদুল ইস্তিগফার’ (সহিহ বুখারি ৬৩০৬)। কালিমাগুলো মুখস্থ করার পাশাপাশি অর্থ বোঝা এবং জীবনে তাওহীদ মেনে চলাই আসল উদ্দেশ্য।", "en": "The best istighfar in sahih hadith is ''Sayyid al-Istighfar'' (Sahih al-Bukhari 6306). Beyond memorising, the real aim is to understand the meaning and live by tawhid."}}]', 'in_review', 10 FROM is_guide_topics WHERE slug = 'kalima' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'c6ff5b70-7cc4-58d9-a5ed-3f1b5535b00b', id, 'iman-mujmal-mufassal', '{"bn": "ঈমানে মুজমাল ও ঈমানে মুফাসসাল", "en": "Iman Mujmal and Iman Mufassal"}', '{"bn": "ঈমানের সংক্ষিপ্ত (মুজমাল) ও বিস্তারিত (মুফাসসাল) ঘোষণা: আরবি, উচ্চারণ, অর্থ ও কুরআন-হাদিসে এর ভিত্তি।", "en": "The brief (mujmal) and detailed (mufassal) declarations of faith: Arabic, pronunciation, meaning and their basis in the Quran and hadith."}', 'basic', '[{"type": "text", "text": {"bn": "ঈমানে মুজমাল ও ঈমানে মুফাসসাল ঈমানের মূল বিষয়গুলো সংক্ষেপে মনে রাখার জন্য সাজানো দুটি ঘোষণা। হুবহু এই শব্দে কোনো হাদিস নেই, তবে এর প্রতিটি বিষয় কুরআন ও হাদিসে জিবরিলে (সহিহ মুসলিম ৮) প্রমাণিত।", "en": "Iman mujmal and iman mufassal are two declarations arranged to help remember the essentials of faith. No hadith has this exact wording, but every item is established in the Quran and the Hadith of Jibril (Sahih Muslim 8)."}}, {"type": "heading", "text": {"bn": "ঈমানে মুজমাল (সংক্ষিপ্ত ঈমান)", "en": "Iman Mujmal (faith in brief)"}}, {"type": "arabic", "label": {"bn": "ঈমানে মুজমাল", "en": "Iman Mujmal"}, "ar": "آمَنْتُ بِاللّٰهِ كَمَا هُوَ بِأَسْمَائِهِ وَصِفَاتِهِ، وَقَبِلْتُ جَمِيعَ أَحْكَامِهِ وَأَرْكَانِهِ", "pron": {"bn": "আমানতু বিল্লাহি কামা হুয়া বিআসমায়িহী ওয়া সিফাতিহী, ওয়া কাবিলতু জামীআ আহকামিহী ওয়া আরকানিহ।", "en": "Amantu billahi kama huwa bi-asma''ihi wa sifatihi, wa qabiltu jami''a ahkamihi wa arkanih."}, "meaning": {"bn": "আমি আল্লাহর প্রতি ঈমান আনলাম, তিনি যেমন আছেন তাঁর সব নাম ও গুণাবলিসহ; এবং আমি তাঁর সকল বিধান ও রুকন (মৌলিক বিষয়) মেনে নিলাম।", "en": "I believe in Allah as He is, with His names and attributes, and I accept all His commands and pillars."}, "ref": {"bn": "শিক্ষার উদ্দেশ্যে সাজানো ঘোষণা", "en": "A declaration arranged for teaching"}, "check": true}, {"type": "heading", "text": {"bn": "ঈমানে মুফাসসাল (বিস্তারিত ঈমান)", "en": "Iman Mufassal (faith in detail)"}}, {"type": "arabic", "label": {"bn": "ঈমানে মুফাসসাল", "en": "Iman Mufassal"}, "ar": "آمَنْتُ بِاللّٰهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ وَالْيَوْمِ الْآخِرِ وَالْقَدْرِ خَيْرِهِ وَشَرِّهِ مِنَ اللّٰهِ تَعَالَىٰ وَالْبَعْثِ بَعْدَ الْمَوْتِ", "pron": {"bn": "আমানতু বিল্লাহি ওয়া মালাইকাতিহী ওয়া কুতুবিহী ওয়া রুসুলিহী ওয়াল ইয়াওমিল আখিরি ওয়াল কাদরি খাইরিহী ওয়া শাররিহী মিনাল্লাহি তাআলা ওয়াল বা''সি বা''দাল মাওত।", "en": "Amantu billahi wa mala''ikatihi wa kutubihi wa rusulihi wal-yawmil-akhiri wal-qadri khayrihi wa sharrihi minallahi ta''ala wal-ba''thi ba''dal-mawt."}, "meaning": {"bn": "আমি ঈমান আনলাম আল্লাহর প্রতি, তাঁর ফেরেশতাদের প্রতি, তাঁর কিতাবসমূহের প্রতি, তাঁর রাসুলদের প্রতি, আখেরাতের দিনের প্রতি, তাকদিরের প্রতি যে ভালো-মন্দ সবই আল্লাহর পক্ষ থেকে, এবং মৃত্যুর পর পুনরুত্থানের প্রতি।", "en": "I believe in Allah, His angels, His books, His messengers, the Last Day, the decree, its good and its bad being from Allah the Exalted, and resurrection after death."}, "ref": {"bn": "মূল বিষয়গুলো: সূরা বাকারা ২:২৮৫; সূরা নিসা ৪:১৩৬; সহিহ মুসলিম ৮ (হাদিসে জিবরিল)", "en": "Its contents: Al-Baqarah 2:285; An-Nisa 4:136; Sahih Muslim 8 (Hadith of Jibril)"}}, {"type": "text", "text": {"bn": "ঈমানে মুফাসসালে সাতটি বিষয় বলা হয়। হাদিসে জিবরিলে ছয়টি বিষয় এসেছে; ‘মৃত্যুর পর পুনরুত্থান’ মূলত আখেরাতের প্রতি ঈমানেরই অংশ, স্পষ্ট করার জন্য আলাদা বলা হয়েছে।", "en": "Iman mufassal names seven items. The Hadith of Jibril names six; ''resurrection after death'' is part of belief in the Last Day, stated separately for emphasis."}}, {"type": "arabic", "label": {"bn": "কুরআনের ঘোষণা", "en": "The Quranic declaration"}, "ar": "آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ ۚ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ ۚ وَقَالُوا سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ", "pron": {"bn": "আমানার রাসূলু বিমা উনযিলা ইলাইহি মির রাব্বিহী ওয়াল মু''মিনূন, কুল্লুন আমানা বিল্লাহি ওয়া মালাইকাতিহী ওয়া কুতুবিহী ওয়া রুসুলিহ, লা নুফাররিকু বাইনা আহাদিম মির রুসুলিহ, ওয়া কালূ সামি''না ওয়া আতা''না, গুফরানাকা রাব্বানা ওয়া ইলাইকাল মাসীর।", "en": "Amanar-rasulu bima unzila ilayhi mir-Rabbihi wal-mu''minun, kullun amana billahi wa mala''ikatihi wa kutubihi wa rusulih, la nufarriqu bayna ahadim mir-rusulih, wa qalu sami''na wa ata''na, ghufranaka Rabbana wa ilaykal-masir."}, "meaning": {"bn": "রাসুল ঈমান এনেছেন তাঁর রবের পক্ষ থেকে তাঁর প্রতি যা নাজিল হয়েছে তার প্রতি, এবং মুমিনরাও। সবাই ঈমান এনেছে আল্লাহ, তাঁর ফেরেশতা, তাঁর কিতাব ও তাঁর রাসুলদের প্রতি। (তারা বলে,) আমরা তাঁর রাসুলদের কারও মধ্যে পার্থক্য করি না। আর তারা বলে, আমরা শুনলাম ও মানলাম; হে আমাদের রব, আমরা তোমার ক্ষমা চাই, আর তোমার দিকেই প্রত্যাবর্তন।", "en": "The Messenger believes in what was sent down to him from his Lord, and so do the believers. Each believes in Allah, His angels, His books and His messengers: ''We make no distinction between any of His messengers.'' And they say: ''We hear and obey. Your forgiveness, our Lord; to You is the return.''"}, "ref": {"bn": "সূরা বাকারা ২:২৮৫", "en": "Al-Baqarah 2:285"}}]', 'in_review', 20 FROM is_guide_topics WHERE slug = 'kalima' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'f6ffc93b-7862-50eb-aedf-54e2fbf35f0c', id, 'six-articles-of-faith', '{"bn": "ঈমানের ছয়টি রুকন", "en": "The Six Articles of Faith"}', '{"bn": "হাদিসে জিবরিলের আলোকে ঈমানের ছয়টি মূল বিষয় সহজভাবে, কুরআন-হাদিসের রেফারেন্সসহ।", "en": "The six articles of faith from the Hadith of Jibril, explained simply with Quran and hadith references."}', 'basic', '[{"type": "text", "text": {"bn": "একদিন সাদা পোশাক ও কালো চুলের এক ব্যক্তি নবীজি (সা.)-এর কাছে এসে ইসলাম, ঈমান, ইহসান ও কিয়ামত সম্পর্কে প্রশ্ন করেন। পরে নবীজি (সা.) জানান, তিনি ছিলেন জিবরিল (আ.), মানুষকে দ্বীন শেখাতে এসেছিলেন। এই হাদিসকে ‘হাদিসে জিবরিল’ বলা হয়।", "en": "One day a man in white clothes with black hair came to the Prophet and asked about Islam, iman, ihsan and the Hour. The Prophet later said it was Jibril, who came to teach people their religion. This is the ''Hadith of Jibril''."}}, {"type": "arabic", "label": {"bn": "ঈমানের সংজ্ঞা (হাদিসে জিবরিল)", "en": "Definition of iman (Hadith of Jibril)"}, "ar": "أَنْ تُؤْمِنَ بِاللّٰهِ، وَمَلَائِكَتِهِ، وَكُتُبِهِ، وَرُسُلِهِ، وَالْيَوْمِ الْآخِرِ، وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ", "pron": {"bn": "আন তু''মিনা বিল্লাহি, ওয়া মালাইকাতিহী, ওয়া কুতুবিহী, ওয়া রুসুলিহী, ওয়াল ইয়াওমিল আখিরি, ওয়া তু''মিনা বিলকাদারি খাইরিহী ওয়া শাররিহ।", "en": "An tu''mina billahi, wa mala''ikatihi, wa kutubihi, wa rusulihi, wal-yawmil-akhiri, wa tu''mina bil-qadari khayrihi wa sharrih."}, "meaning": {"bn": "(ঈমান হলো) তুমি ঈমান আনবে আল্লাহর প্রতি, তাঁর ফেরেশতাদের প্রতি, তাঁর কিতাবসমূহের প্রতি, তাঁর রাসুলদের প্রতি, আখেরাতের দিনের প্রতি, এবং ঈমান আনবে তাকদিরের ভালো-মন্দের প্রতি।", "en": "(Iman is) that you believe in Allah, His angels, His books, His messengers and the Last Day, and that you believe in the decree, its good and its bad."}, "ref": {"bn": "সহিহ মুসলিম ৮; সহিহ বুখারি ৫০", "en": "Sahih Muslim 8; Sahih al-Bukhari 50"}}, {"type": "step", "title": {"bn": "আল্লাহর প্রতি ঈমান", "en": "Belief in Allah"}, "text": {"bn": "আল্লাহ এক, তাঁর কোনো শরিক নেই; তিনিই সৃষ্টিকর্তা, প্রতিপালক ও একমাত্র উপাস্য। তাঁর সুন্দর নাম ও গুণাবলি আছে, কোনো কিছুই তাঁর মতো নয়। ইবাদত কেবল তাঁরই জন্য। (সূরা ইখলাস ১১২:১–৪; সূরা শূরা ৪২:১১)", "en": "Allah is One, without partner; He alone creates, sustains and deserves worship. He has beautiful names and attributes, and nothing is like Him. Worship is for Him alone. (Al-Ikhlas 112:1–4; Ash-Shura 42:11)"}}, {"type": "step", "title": {"bn": "ফেরেশতাদের প্রতি ঈমান", "en": "Belief in the angels"}, "text": {"bn": "ফেরেশতারা নূরের তৈরি আল্লাহর সম্মানিত সৃষ্টি; তারা আল্লাহর অবাধ্য হয় না, যা আদেশ করা হয় তা-ই করে (সূরা তাহরিম ৬৬:৬)। যেমন জিবরিল (আ.) ওহি নিয়ে আসেন (সূরা বাকারা ২:৯৭), আর দুই ফেরেশতা আমাদের কথা ও কাজ লিখে রাখেন (সূরা কাফ ৫০:১৭–১৮)।", "en": "Angels are honoured creations of Allah; they never disobey Him and do as they are commanded (At-Tahrim 66:6). Jibril brings revelation (Al-Baqarah 2:97), and two angels record our words and deeds (Qaf 50:17–18)."}}, {"type": "step", "title": {"bn": "কিতাবসমূহের প্রতি ঈমান", "en": "Belief in the books"}, "text": {"bn": "আল্লাহ নবীদের ওপর কিতাব নাজিল করেছেন: মুসা (আ.)-এর ওপর তাওরাত, দাউদ (আ.)-এর ওপর যাবুর (সূরা নিসা ৪:১৬৩), ঈসা (আ.)-এর ওপর ইনজিল (সূরা মায়িদা ৫:৪৬), আর মুহাম্মাদ (সা.)-এর ওপর কুরআন। ইবরাহিম ও মুসা (আ.)-কে সহিফাও দেওয়া হয়েছিল (সূরা আ''লা ৮৭:১৮–১৯)। কুরআন সর্বশেষ কিতাব, আল্লাহ নিজেই এর হেফাজতকারী (সূরা হিজর ১৫:৯)।", "en": "Allah revealed books to prophets: the Torah to Musa, the Zabur to Dawud (An-Nisa 4:163), the Injil to ''Isa (Al-Ma''idah 5:46), and the Quran to Muhammad. Ibrahim and Musa were also given scriptures (Al-A''la 87:18–19). The Quran is the final book, preserved by Allah (Al-Hijr 15:9)."}}, {"type": "step", "title": {"bn": "রাসুলদের প্রতি ঈমান", "en": "Belief in the messengers"}, "text": {"bn": "আল্লাহ প্রত্যেক জাতির কাছে রাসুল পাঠিয়েছেন, যারা এক আল্লাহর ইবাদতের দিকে ডেকেছেন (সূরা নাহল ১৬:৩৬)। কারও কথা আমাদের জানানো হয়েছে, কারও কথা জানানো হয়নি (সূরা নিসা ৪:১৬৪)। আমরা সবার প্রতি ঈমান রাখি, কারও মধ্যে পার্থক্য করি না (সূরা বাকারা ২:২৮৫)। মুহাম্মাদ (সা.) সর্বশেষ নবী, তাঁর পরে আর কোনো নবী নেই (সূরা আহযাব ৩৩:৪০)।", "en": "Allah sent a messenger to every nation calling to worship Him alone (An-Nahl 16:36). Some are told to us, some not (An-Nisa 4:164). We believe in all of them without distinction (Al-Baqarah 2:285). Muhammad is the last prophet; there is none after him (Al-Ahzab 33:40)."}}, {"type": "step", "title": {"bn": "আখেরাতের প্রতি ঈমান", "en": "Belief in the Last Day"}, "text": {"bn": "মৃত্যুর পর কবরের জীবন, কিয়ামত, পুনরুত্থান, হিসাব, মিজান (পাল্লা), জান্নাত ও জাহান্নাম সত্য। প্রত্যেকে তার অণু পরিমাণ ভালো ও মন্দ কাজও দেখতে পাবে (সূরা যিলযাল ৯৯:৭–৮)। প্রত্যেক প্রাণ মৃত্যুর স্বাদ গ্রহণ করবে, আর কিয়ামতের দিন পূর্ণ প্রতিদান দেওয়া হবে (সূরা আলে ইমরান ৩:১৮৫)।", "en": "Life in the grave, the Hour, resurrection, reckoning, the scale, Paradise and Hell are true. Everyone will see even an atom''s weight of good or evil (Az-Zalzalah 99:7–8). Every soul will taste death and be paid in full on the Day of Resurrection (Al ''Imran 3:185)."}}, {"type": "step", "title": {"bn": "তাকদিরের প্রতি ঈমান", "en": "Belief in the decree (qadr)"}, "text": {"bn": "যা কিছু ঘটে, সবই আল্লাহর জ্ঞান, লিখন, ইচ্ছা ও সৃষ্টির অধীন: ‘আমি সবকিছু সৃষ্টি করেছি নির্ধারিত পরিমাপে’ (সূরা কামার ৫৪:৪৯)। আসমান-জমিন সৃষ্টির পঞ্চাশ হাজার বছর আগে আল্লাহ সৃষ্টির তাকদির লিখে রেখেছেন (সহিহ মুসলিম ২৬৫৩)। তাকদিরে বিশ্বাস চেষ্টা ছেড়ে দেওয়া নয়; মানুষ নিজের পছন্দে কাজ করে এবং সে অনুযায়ী প্রতিদান পায় (সূরা লাইল ৯২:৫–১০)।", "en": "Everything happens within Allah''s knowledge, writing, will and creation: ''We created everything according to a measure'' (Al-Qamar 54:49). Allah wrote the decrees fifty thousand years before creating the heavens and earth (Sahih Muslim 2653). Belief in qadr does not mean giving up effort; people act by choice and are rewarded accordingly (Al-Layl 92:5–10)."}}, {"type": "ref", "text": {"bn": "ছয়টি রুকন একসাথে কুরআনে: সূরা বাকারা ২:১৭৭, ২:২৮৫; সূরা নিসা ৪:১৩৬; তাকদির: সূরা কামার ৫৪:৪৯", "en": "The articles together in the Quran: Al-Baqarah 2:177, 2:285; An-Nisa 4:136; decree: Al-Qamar 54:49"}}]', 'in_review', 30 FROM is_guide_topics WHERE slug = 'kalima' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '60db2333-53a8-543c-9939-ee25e3356e02', id, 'five-pillars-of-islam', '{"bn": "ইসলামের পাঁচটি স্তম্ভ", "en": "The Five Pillars of Islam"}', '{"bn": "যে পাঁচটি ভিত্তির ওপর ইসলাম দাঁড়িয়ে আছে: শাহাদাত, নামাজ, যাকাত, রোজা ও হজ; সাথে ইসলাম, ঈমান ও ইহসানের সম্পর্ক।", "en": "The five foundations of Islam: shahadah, prayer, zakat, fasting and Hajj, and how Islam, iman and ihsan relate."}', 'basic', '[{"type": "arabic", "label": {"bn": "ইসলামের পাঁচ ভিত্তি", "en": "The five foundations"}, "ar": "بُنِيَ الْإِسْلَامُ عَلَىٰ خَمْسٍ: شَهَادَةِ أَنْ لَا إِلٰهَ إِلَّا اللّٰهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللّٰهِ، وَإِقَامِ الصَّلَاةِ، وَإِيتَاءِ الزَّكَاةِ، وَالْحَجِّ، وَصَوْمِ رَمَضَانَ", "pron": {"bn": "বুনিয়াল ইসলামু আলা খামস: শাহাদাতি আল লা ইলাহা ইল্লাল্লাহু ওয়া আন্না মুহাম্মাদার রাসূলুল্লাহ, ওয়া ইকামিস সালাহ, ওয়া ঈতায়িয যাকাহ, ওয়াল হাজ্জ, ওয়া সাওমি রামাদান।", "en": "Buniyal-Islamu ''ala khams: shahadati al la ilaha illallahu wa anna Muhammadar Rasulullah, wa iqamis-salah, wa ita''iz-zakah, wal-hajj, wa sawmi Ramadan."}, "meaning": {"bn": "ইসলাম পাঁচটি ভিত্তির ওপর প্রতিষ্ঠিত: এই সাক্ষ্য দেওয়া যে আল্লাহ ছাড়া কোনো ইলাহ নেই এবং মুহাম্মাদ (সা.) আল্লাহর রাসুল; নামাজ কায়েম করা; যাকাত দেওয়া; হজ করা; এবং রমজানের রোজা রাখা।", "en": "Islam is built on five: testifying that there is no god but Allah and that Muhammad is the Messenger of Allah, establishing prayer, giving zakat, Hajj, and fasting Ramadan."}, "ref": {"bn": "সহিহ বুখারি ৮; সহিহ মুসলিম ১৬", "en": "Sahih al-Bukhari 8; Sahih Muslim 16"}}, {"type": "step", "title": {"bn": "শাহাদাত (কালিমার সাক্ষ্য)", "en": "Shahadah (testimony of faith)"}, "text": {"bn": "অন্তরে বিশ্বাস করে মুখে সাক্ষ্য দেওয়া যে আল্লাহ ছাড়া কোনো সত্য ইলাহ নেই এবং মুহাম্মাদ (সা.) আল্লাহর রাসুল; আর সেই অনুযায়ী জীবন চালানো। এটিই ইসলামের প্রবেশদ্বার (সূরা মুহাম্মাদ ৪৭:১৯)।", "en": "To believe in the heart and declare that there is no true god but Allah and that Muhammad is His Messenger, and to live by it. It is the door of Islam (Muhammad 47:19)."}}, {"type": "step", "title": {"bn": "নামাজ", "en": "Salah (prayer)"}, "text": {"bn": "প্রতিদিন পাঁচ ওয়াক্ত ফরজ নামাজ নির্দিষ্ট সময়ে আদায় করা (সূরা নিসা ৪:১০৩)। ঈমানের পর সবচেয়ে গুরুত্বপূর্ণ আমল; প্রাপ্তবয়স্ক ও সুস্থ মস্তিষ্কের প্রত্যেক মুসলিমের ওপর ফরজ।", "en": "Five obligatory prayers each day at their fixed times (An-Nisa 4:103). The most important deed after faith, obligatory on every adult sane Muslim."}}, {"type": "step", "title": {"bn": "যাকাত", "en": "Zakat"}, "text": {"bn": "নিসাব পরিমাণ সম্পদ এক বছর থাকলে নির্দিষ্ট অংশ (সাধারণত আড়াই শতাংশ) নির্ধারিত হকদারদের দেওয়া (সূরা বাকারা ২:৪৩; হকদারদের তালিকা: সূরা তাওবা ৯:৬০)। এটি সম্পদকে পবিত্র করে।", "en": "Giving a set share (usually 2.5%) of wealth above the nisab held for a year to the eligible recipients (Al-Baqarah 2:43; recipients: At-Tawbah 9:60). It purifies wealth."}}, {"type": "step", "title": {"bn": "রোজা", "en": "Sawm (fasting)"}, "text": {"bn": "রমজান মাসে সুবহে সাদিক থেকে সূর্যাস্ত পর্যন্ত পানাহার ও স্ত্রী-সহবাস থেকে বিরত থাকা, তাকওয়া অর্জনের জন্য (সূরা বাকারা ২:১৮৩)।", "en": "Abstaining from food, drink and marital relations from dawn to sunset during Ramadan, to attain taqwa (Al-Baqarah 2:183)."}}, {"type": "step", "title": {"bn": "হজ", "en": "Hajj"}, "text": {"bn": "শারীরিক ও আর্থিকভাবে সামর্থ্যবান মুসলিমের ওপর জীবনে একবার কাবা ঘরের হজ করা ফরজ (সূরা আলে ইমরান ৩:৯৭)।", "en": "Pilgrimage to the Ka''bah once in a lifetime for every Muslim who is physically and financially able (Al ''Imran 3:97)."}}, {"type": "heading", "text": {"bn": "ইসলাম, ঈমান ও ইহসান", "en": "Islam, iman and ihsan"}}, {"type": "text", "text": {"bn": "হাদিসে জিবরিলে দ্বীনের তিনটি স্তর বলা হয়েছে: ইসলাম (বাহ্যিক আমল, যেমন এই পাঁচ স্তম্ভ), ঈমান (অন্তরের বিশ্বাস, ছয় রুকন), এবং ইহসান (সর্বোচ্চ স্তর)।", "en": "The Hadith of Jibril describes three levels of the religion: Islam (outward deeds, such as these five pillars), iman (belief in the heart, the six articles), and ihsan (the highest level)."}}, {"type": "arabic", "label": {"bn": "ইসলামের সংজ্ঞা", "en": "Definition of Islam"}, "ar": "الْإِسْلَامُ أَنْ تَشْهَدَ أَنْ لَا إِلٰهَ إِلَّا اللّٰهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللّٰهِ، وَتُقِيمَ الصَّلَاةَ، وَتُؤْتِيَ الزَّكَاةَ، وَتَصُومَ رَمَضَانَ، وَتَحُجَّ الْبَيْتَ إِنِ اسْتَطَعْتَ إِلَيْهِ سَبِيلًا", "pron": {"bn": "আল ইসলামু আন তাশহাদা আল লা ইলাহা ইল্লাল্লাহু ওয়া আন্না মুহাম্মাদার রাসূলুল্লাহ, ওয়া তুকীমাস সালাতা, ওয়া তু''তিয়ায যাকাতা, ওয়া তাসূমা রামাদানা, ওয়া তাহুজ্জাল বাইতা ইনিসতাতা''তা ইলাইহি সাবীলা।", "en": "Al-Islamu an tashhada al la ilaha illallahu wa anna Muhammadar Rasulullah, wa tuqimas-salata, wa tu''tiyaz-zakata, wa tasuma Ramadana, wa tahujjal-bayta inistata''ta ilayhi sabila."}, "meaning": {"bn": "ইসলাম হলো: তুমি সাক্ষ্য দেবে যে আল্লাহ ছাড়া কোনো ইলাহ নেই ও মুহাম্মাদ (সা.) আল্লাহর রাসুল, নামাজ কায়েম করবে, যাকাত দেবে, রমজানের রোজা রাখবে, এবং সামর্থ্য থাকলে কাবা ঘরের হজ করবে।", "en": "Islam is that you testify there is no god but Allah and Muhammad is the Messenger of Allah, establish prayer, give zakat, fast Ramadan, and make Hajj to the House if you are able."}, "ref": {"bn": "সহিহ মুসলিম ৮", "en": "Sahih Muslim 8"}}, {"type": "arabic", "label": {"bn": "ইহসানের সংজ্ঞা", "en": "Definition of ihsan"}, "ar": "أَنْ تَعْبُدَ اللّٰهَ كَأَنَّكَ تَرَاهُ، فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ", "pron": {"bn": "আন তা''বুদাল্লাহা কাআন্নাকা তারাহ, ফাইল লাম তাকুন তারাহু ফাইন্নাহূ ইয়ারাক।", "en": "An ta''budallaha ka-annaka tarah, fa il lam takun tarahu fa innahu yarak."}, "meaning": {"bn": "(ইহসান হলো) তুমি আল্লাহর ইবাদত এমনভাবে করবে যেন তুমি তাঁকে দেখছ; আর যদি তুমি তাঁকে না দেখো, তবে (জেনে রাখো) তিনি তোমাকে দেখছেন।", "en": "(Ihsan is) that you worship Allah as though you see Him; and if you do not see Him, He surely sees you."}, "ref": {"bn": "সহিহ মুসলিম ৮; সহিহ বুখারি ৫০", "en": "Sahih Muslim 8; Sahih al-Bukhari 50"}}, {"type": "note", "tone": "tip", "text": {"bn": "পাঁচ স্তম্ভের প্রতিটির বিস্তারিত নিয়ম এই অ্যাপের নামাজ, রোজা, যাকাত ও হজ অংশে দেখুন।", "en": "See the prayer, fasting, zakat and Hajj sections of this app for the details of each pillar."}}]', 'in_review', 40 FROM is_guide_topics WHERE slug = 'kalima' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '4c0a3cd4-525f-5439-8dc3-3889a0c19c76', id, 'sawm-basics', '{"bn": "রোজা: কার ওপর ফরজ ও কেন", "en": "Fasting: who must fast and why"}', '{"bn": "রমজানের রোজা ইসলামের পাঁচ স্তম্ভের একটি। কার ওপর রোজা ফরজ, রোজার ফজিলত ও আদব এখানে সংক্ষেপে।", "en": "Fasting Ramadan is one of the five pillars of Islam. Who must fast, its virtues and its manners in brief."}', 'basic', '[{"type": "arabic", "label": {"bn": "রোজা ফরজ হওয়ার আয়াত", "en": "The verse of fasting"}, "ar": "يَا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيَامُ كَمَا كُتِبَ عَلَى الَّذِينَ مِنْ قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ", "pron": {"bn": "ইয়া আইয়ুহাল্লাযীনা আমানূ কুতিবা আলাইকুমুস সিয়ামু কামা কুতিবা আলাল্লাযীনা মিন কাবলিকুম লাআল্লাকুম তাত্তাকূন", "en": "Ya ayyuhal-ladhina amanu kutiba ''alaykumus-siyamu kama kutiba ''alal-ladhina min qablikum la''allakum tattaqun"}, "meaning": {"bn": "হে ঈমানদারগণ! তোমাদের ওপর রোজা ফরজ করা হয়েছে, যেমন ফরজ করা হয়েছিল তোমাদের পূর্ববর্তীদের ওপর, যাতে তোমরা তাকওয়া অর্জন করতে পারো।", "en": "O you who believe, fasting is prescribed for you as it was prescribed for those before you, so that you may become mindful of Allah."}, "ref": {"bn": "সূরা বাকারা ২:১৮৩", "en": "Al-Baqarah 2:183"}}, {"type": "text", "text": {"bn": "রোজা মানে সুবহে সাদিক (ফজরের সময় শুরু) থেকে সূর্যাস্ত পর্যন্ত আল্লাহর সন্তুষ্টির নিয়তে খাওয়া, পান করা ও স্ত্রী-সহবাস থেকে বিরত থাকা। রমজান মাসের রোজা প্রত্যেক প্রাপ্তবয়স্ক মুসলিমের ওপর ফরজ।", "en": "Fasting (sawm) means refraining from food, drink and marital relations from true dawn (start of Fajr) until sunset, with the intention of pleasing Allah. Fasting the month of Ramadan is obligatory on every adult Muslim."}}, {"type": "heading", "text": {"bn": "কার ওপর রোজা ফরজ", "en": "Who must fast"}}, {"type": "list", "items": [{"bn": "মুসলিম", "en": "A Muslim"}, {"bn": "বালেগ বা প্রাপ্তবয়স্ক (ছেলে-মেয়ের বয়ঃসন্ধির লক্ষণ দেখা দিলে, নয়তো চাঁদের হিসাবে ১৫ বছর হলে)", "en": "Adult (has reached puberty, or otherwise 15 lunar years of age)"}, {"bn": "সুস্থ মস্তিষ্কের অধিকারী", "en": "Of sound mind"}, {"bn": "রোজা রাখতে সক্ষম; গুরুতর অসুস্থ নয়", "en": "Able to fast, not seriously ill"}, {"bn": "মুকিম, অর্থাৎ শরিয়তসম্মত সফরে নেই", "en": "Resident, i.e. not on a journey by the Shariah definition"}, {"bn": "নারীর ক্ষেত্রে: হায়েজ (মাসিক) ও নিফাস (প্রসব-পরবর্তী রক্তস্রাব) থেকে পবিত্র", "en": "For women: free of menstruation (hayd) and post-natal bleeding (nifas)"}]}, {"type": "note", "tone": "info", "text": {"bn": "অসুস্থ, মুসাফির, গর্ভবতী-দুগ্ধদানকারী মা ও বৃদ্ধদের বিধান আলাদা গাইডে দেওয়া আছে। তাদের অনেকের জন্য পরে কাজা বা ফিদইয়া আছে, রোজা পুরোপুরি মাফ নয়।", "en": "The rulings for the sick, travellers, pregnant and nursing mothers and the elderly are in a separate guide. For most of them the fast is made up later or compensated with fidya; it is not simply cancelled."}}, {"type": "text", "text": {"bn": "ছোট শিশুদের ওপর রোজা ফরজ নয়, তবে সাহাবিরা অভ্যাস করানোর জন্য শিশুদের রোজা রাখাতেন এবং ক্ষুধায় কাঁদলে খেলনা দিয়ে ভুলিয়ে রাখতেন।", "en": "Fasting is not obligatory on young children, but the Companions trained their children to fast and gave them toys to distract them when they cried from hunger."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৯৬০", "en": "Sahih al-Bukhari 1960"}}, {"type": "heading", "text": {"bn": "রোজার কিছু ফজিলত", "en": "Some virtues of fasting"}}, {"type": "list", "items": [{"bn": "যে ব্যক্তি ঈমানের সাথে ও সওয়াবের আশায় রমজানের রোজা রাখে, তার আগের গুনাহ ক্ষমা করা হয়।", "en": "Whoever fasts Ramadan with faith and hoping for reward, his past sins are forgiven."}, {"bn": "রোজা ঢালস্বরূপ, গুনাহ ও জাহান্নাম থেকে রক্ষা করে।", "en": "Fasting is a shield, protecting from sin and the Fire."}, {"bn": "জান্নাতে ''রাইয়ান'' নামে একটি দরজা আছে, শুধু রোজাদাররা সেখান দিয়ে প্রবেশ করবে।", "en": "Paradise has a gate called Ar-Rayyan through which only those who fast will enter."}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৩৮; সহিহ বুখারি ১৮৯৪; সহিহ বুখারি ১৮৯৬", "en": "Sahih al-Bukhari 38; Sahih al-Bukhari 1894; Sahih al-Bukhari 1896"}}, {"type": "heading", "text": {"bn": "রোজার আদব", "en": "Manners of the fast"}}, {"type": "text", "text": {"bn": "রোজা শুধু না খেয়ে থাকা নয়। মিথ্যা কথা, গালিগালাজ, গিবত ও ঝগড়া থেকেও বাঁচতে হবে। নবী (সা.) বলেছেন, যে মিথ্যা কথা ও মিথ্যা অনুযায়ী কাজ ছাড়ে না, তার খাবার-পানীয় ত্যাগ করায় আল্লাহর কোনো প্রয়োজন নেই। কেউ ঝগড়া করতে এলে বলবে: ''আমি রোজাদার।''", "en": "Fasting is not only going without food. One must also avoid lies, abuse, backbiting and quarrels. The Prophet (peace be upon him) said that whoever does not give up false speech and acting on it, Allah has no need of his leaving food and drink. If someone picks a fight, say: ''I am fasting.''"}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৯০৩; সহিহ বুখারি ১৯০৪", "en": "Sahih al-Bukhari 1903; Sahih al-Bukhari 1904"}}]', 'in_review', 10 FROM is_guide_topics WHERE slug = 'sawm' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '82d71d49-a2c2-5659-9854-50a38bf180d5', id, 'sawm-niyyah-sehri-iftar', '{"bn": "নিয়ত, সেহরি ও ইফতার", "en": "Niyyah, sehri and iftar"}', '{"bn": "রোজার নিয়ত কীভাবে করবেন, সেহরি ও ইফতারের সুন্নত এবং ইফতারের সহিহ দোয়া।", "en": "How to make the intention, the sunnahs of sehri and iftar, and the authentic iftar dua."}', 'basic', '[{"type": "heading", "text": {"bn": "নিয়ত", "en": "Niyyah (intention)"}}, {"type": "text", "text": {"bn": "নিয়ত মানে মনের ইচ্ছা। আপনি যে আগামীকাল রোজা রাখবেন বলে মনে মনে ঠিক করেছেন, সেটাই নিয়ত। সেহরি খেতে ওঠাও নিয়তের প্রমাণ। মুখে উচ্চারণ করা জরুরি নয়, আর নির্দিষ্ট কোনো আরবি বাক্য বলাও শর্ত নয়।", "en": "Niyyah is the intention in the heart. Having decided in your heart that you will fast tomorrow is the intention; getting up for sehri itself shows it. Saying it aloud is not required, and no particular Arabic wording is a condition."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১; সহিহ মুসলিম ১৯০৭", "en": "Sahih al-Bukhari 1; Sahih Muslim 1907"}}, {"type": "note", "tone": "tip", "text": {"bn": "উদাহরণ (মুখে বলা জরুরি নয়): ''আমি আগামীকাল আল্লাহর সন্তুষ্টির জন্য রমজানের ফরজ রোজা রাখার নিয়ত করছি।'' এটি শুধু একটি প্রচলিত বাংলা উদাহরণ; মনে এই ইচ্ছা থাকলেই যথেষ্ট।", "en": "Example (saying it is not required): ''I intend to keep tomorrow''s obligatory Ramadan fast for the sake of Allah.'' This is only a common example phrasing; having this intention in the heart is enough."}}, {"type": "differ", "title": {"bn": "নিয়ত কখন করতে হবে", "en": "When must the intention be made"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "রমজানের রোজা, নির্দিষ্ট দিনের মানতের রোজা ও নফল রোজার নিয়ত রাত থেকে শুরু করে পরদিন দুপুরের আগে (শরয়ি অর্ধদিবসের আগে) পর্যন্ত করা যায়, যদি এর মধ্যে কিছু খাওয়া না হয়। তবে রাতেই নিয়ত করা উত্তম। কাজা, কাফফারা ও অনির্দিষ্ট মানতের রোজার নিয়ত রাতেই করতে হয়।", "en": "For Ramadan, a vow for a fixed day and voluntary fasts, the intention may be made from the night until before midday (the Shariah half-day) if nothing has been eaten; making it at night is better. Make-up, kaffarah and unfixed vow fasts need the intention at night."}, "evidence": {"bn": "নবী (সা.) দিনের বেলায় ঘরে খাবার না পেয়ে বলেছেন, ''তাহলে আমি রোজা রাখলাম'' (নফল); আশুরার দিনে দিনের বেলায় রোজা রাখার ঘোষণা দেওয়া হয়েছিল।", "en": "The Prophet, finding no food at home during the day, said ''Then I am fasting'' (voluntary); and on Ashura it was announced during the day that people should fast."}}, {"label": {"bn": "শাফেয়ি, মালেকি, হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "ফরজ রোজার (রমজান, কাজা, মানত) নিয়ত ফজরের আগে রাতেই করতে হবে। নফল রোজার নিয়ত দিনের বেলায়ও করা যায় (মালেকিদের মতে নফলেও রাতে)।", "en": "For obligatory fasts (Ramadan, make-up, vows) the intention must be made at night before Fajr. For voluntary fasts it may be made during the day (Malikis require night for these too)."}, "evidence": {"bn": "হাদিস: ''যে ফজরের আগে রোজার নিয়ত করে না, তার রোজা হয় না।'' (হাফসা রা. থেকে বর্ণিত)", "en": "Hadith: ''Whoever does not resolve to fast before Fajr has no fast.'' (narrated from Hafsah)"}}]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১১৫৪; সুনান আবু দাউদ ২৪৫৪", "en": "Sahih Muslim 1154; Sunan Abi Dawud 2454"}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি (আশুরার দিনে দিনের বেলায় রোজার ঘোষণা)", "en": "Sahih al-Bukhari (the daytime announcement to fast on Ashura)"}, "check": true}, {"type": "heading", "text": {"bn": "সেহরি", "en": "Sehri (pre-dawn meal)"}}, {"type": "list", "items": [{"bn": "সেহরি খাওয়া সুন্নত; এতে বরকত আছে। অল্প কিছু, এমনকি এক ঢোক পানি হলেও খাবেন।", "en": "Eating sehri is sunnah and has blessing; eat something, even a sip of water."}, {"bn": "সেহরি দেরিতে, অর্থাৎ ফজরের সময় শুরু হওয়ার কিছু আগে খাওয়া সুন্নত। নবী (সা.)-এর সেহরি ও ফজরের নামাজের মাঝে প্রায় পঞ্চাশ আয়াত পড়ার সময় থাকত।", "en": "Delaying sehri to shortly before Fajr is sunnah; between the Prophet''s sehri and the Fajr prayer was about the time of reciting fifty verses."}, {"bn": "ফজরের সময় শুরু হয়ে গেলে খাওয়া বন্ধ করতে হবে। আজান শুনে খাওয়া চালিয়ে না গিয়ে স্থানীয় নির্ভরযোগ্য সময়সূচি দেখে কয়েক মিনিট আগেই থামা নিরাপদ।", "en": "Stop eating once Fajr time begins. Rather than eating on through the adhan, it is safer to stop a few minutes early by a reliable local timetable."}, {"bn": "সেহরিই আমাদের রোজা ও আহলে কিতাবের রোজার পার্থক্য।", "en": "Sehri is the difference between our fasting and that of the People of the Book."}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৯২৩; সহিহ বুখারি ১৯২১; সহিহ মুসলিম ১০৯৬", "en": "Sahih al-Bukhari 1923; Sahih al-Bukhari 1921; Sahih Muslim 1096"}}, {"type": "arabic", "ar": "وَكُلُوا وَاشْرَبُوا حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الْأَبْيَضُ مِنَ الْخَيْطِ الْأَسْوَدِ مِنَ الْفَجْرِ", "pron": {"bn": "ওয়া কুলূ ওয়াশরাবূ হাত্তা ইয়াতাবাইয়ানা লাকুমুল খাইতুল আবইয়াদু মিনাল খাইতিল আসওয়াদি মিনাল ফাজর", "en": "Wa kulu washrabu hatta yatabayyana lakumul-khaytul-abyadu minal-khaytil-aswadi minal-fajr"}, "meaning": {"bn": "আর খাও ও পান করো, যতক্ষণ না রাতের কালো রেখা থেকে ভোরের সাদা রেখা স্পষ্ট হয়।", "en": "And eat and drink until the white thread of dawn becomes distinct to you from the black thread."}, "ref": {"bn": "সূরা বাকারা ২:১৮৭", "en": "Al-Baqarah 2:187"}}, {"type": "heading", "text": {"bn": "ইফতার", "en": "Iftar (breaking the fast)"}}, {"type": "list", "items": [{"bn": "সূর্য ডোবার সঙ্গে সঙ্গে দেরি না করে ইফতার করা সুন্নত। মানুষ যতদিন তাড়াতাড়ি ইফতার করবে, ততদিন কল্যাণে থাকবে।", "en": "Breaking the fast promptly at sunset is sunnah; people will remain in good as long as they hasten the iftar."}, {"bn": "তাজা খেজুর দিয়ে ইফতার করা সুন্নত; না পেলে শুকনো খেজুর, তাও না পেলে কয়েক ঢোক পানি।", "en": "Break the fast with fresh dates, if not then dried dates, and if not then a few sips of water."}, {"bn": "ইফতারের সময় দোয়া করুন; রোজাদারকে ইফতার করানোরও বড় সওয়াব আছে।", "en": "Make dua at iftar; feeding a fasting person also carries great reward."}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৯৫৭; সহিহ মুসলিম ১০৯৮; সুনান আবু দাউদ ২৩৫৬", "en": "Sahih al-Bukhari 1957; Sahih Muslim 1098; Sunan Abi Dawud 2356"}}, {"type": "arabic", "label": {"bn": "ইফতারের দোয়া (সহিহ সনদে বর্ণিত)", "en": "Iftar dua (authentic)"}, "ar": "ذَهَبَ الظَّمَأُ، وَابْتَلَّتِ الْعُرُوقُ، وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ", "pron": {"bn": "যাহাবায যামাউ, ওয়াবতাল্লাতিল উরূকু, ওয়া সাবাতাল আজরু ইনশাআল্লাহ", "en": "Dhahabaz-zama''u, wabtallatil-''uruqu, wa thabatal-ajru in sha Allah"}, "meaning": {"bn": "পিপাসা দূর হয়েছে, শিরাগুলো সিক্ত হয়েছে, আর আল্লাহ চাইলে প্রতিদান নিশ্চিত হয়েছে।", "en": "The thirst is gone, the veins are moistened, and the reward is certain, if Allah wills."}, "ref": {"bn": "সুনান আবু দাউদ ২৩৫৭", "en": "Sunan Abi Dawud 2357"}}, {"type": "note", "tone": "info", "text": {"bn": "এই দোয়াটি নবী (সা.) ইফতার করার পরে পড়তেন, তাই প্রথমে ''বিসমিল্লাহ'' বলে ইফতার শুরু করুন, তারপর এটি পড়ুন। হাদিসবিশারদদের অনেকে এর সনদকে হাসান (গ্রহণযোগ্য) বলেছেন।", "en": "The Prophet said this after breaking the fast, so start eating with ''Bismillah'' and then say it. Many hadith scholars graded its chain hasan (acceptable)."}}, {"type": "arabic", "label": {"bn": "প্রচলিত দোয়া (সনদ দুর্বল)", "en": "Common dua (weak chain)"}, "ar": "اللَّهُمَّ لَكَ صُمْتُ، وَعَلَى رِزْقِكَ أَفْطَرْتُ", "pron": {"bn": "আল্লাহুম্মা লাকা সুমতু, ওয়া আলা রিযক্বিকা আফতারতু", "en": "Allahumma laka sumtu, wa ''ala rizqika aftartu"}, "meaning": {"bn": "হে আল্লাহ! তোমার জন্যই রোজা রেখেছি এবং তোমার দেওয়া রিজিক দিয়েই ইফতার করছি।", "en": "O Allah, for You I fasted and with Your provision I break my fast."}, "ref": {"bn": "সুনান আবু দাউদ ২৩৫৮", "en": "Sunan Abi Dawud 2358"}}, {"type": "note", "tone": "warn", "text": {"bn": "এই দোয়াটি মুরসাল সূত্রে বর্ণিত, তাই সনদ দুর্বল; অর্থ সুন্দর বলে পড়া যায়, তবে সহিহ দোয়া হিসেবে প্রথমটিই অগ্রাধিকার পাবে। বাংলাদেশে প্রচলিত ''ওয়া বিকা আমানতু ওয়া আলাইকা তাওয়াক্কালতু'' অংশটুকু কোনো হাদিসে পাওয়া যায় না।", "en": "This dua comes through a mursal chain and is weak; its meaning is fine, but the first dua is the authentic one to prefer. The addition ''wa bika amantu wa ''alayka tawakkaltu'' common in Bangladesh is not found in any hadith."}}]', 'in_review', 20 FROM is_guide_topics WHERE slug = 'sawm' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '6b8fe835-3994-5468-b106-194fcad2cd49', id, 'sawm-what-breaks', '{"bn": "যেসব কারণে রোজা ভাঙে, যেসবে ভাঙে না", "en": "What breaks the fast and what does not"}', '{"bn": "কোন কাজে রোজা ভেঙে যায় আর কোনটায় ভাঙে না, একনজরে টেবিলে। যেসব বিষয়ে আলেমদের মতভেদ আছে, তা আলাদা দেখানো হয়েছে।", "en": "At a glance: what breaks the fast and what does not, with the points scholars differ on shown separately."}', 'basic', '[{"type": "text", "text": {"bn": "মূলনীতি: ইচ্ছাকৃতভাবে খাওয়া, পান করা, স্ত্রী-সহবাস, আর এ জাতীয় কিছু দিয়ে রোজা ভাঙে। ভুলে গিয়ে খেলে বা অনিচ্ছায় কিছু হলে রোজা ভাঙে না।", "en": "The principle: the fast is broken by deliberate eating, drinking, marital relations and things of that kind. Eating by mistake or anything that happens unintentionally does not break it."}}, {"type": "heading", "text": {"bn": "যেসব কারণে রোজা ভেঙে যায়", "en": "What breaks the fast"}}, {"type": "table", "head": [{"bn": "কাজ", "en": "Act"}, {"bn": "করণীয়", "en": "What is due"}], "rows": [[{"bn": "ইচ্ছাকৃতভাবে খাওয়া বা পান করা", "en": "Deliberately eating or drinking"}, {"bn": "কাজা; হানাফি ও মালেকি মতে কাফফারাও", "en": "Make-up; also kaffarah in the Hanafi and Maliki view"}], [{"bn": "রোজা অবস্থায় ইচ্ছাকৃত স্ত্রী-সহবাস", "en": "Deliberate intercourse while fasting"}, {"bn": "কাজা ও কাফফারা (সব মাজহাবে একমত)", "en": "Make-up and kaffarah (agreed)"}], [{"bn": "ইচ্ছা করে বমি করা (হানাফি মতে মুখভর্তি হলে)", "en": "Deliberately making oneself vomit (Hanafi: a mouthful)"}, {"bn": "কাজা", "en": "Make-up"}], [{"bn": "হায়েজ বা নিফাস শুরু হওয়া, দিনের যেকোনো সময়ে", "en": "Menstruation or post-natal bleeding starting, at any time of the day"}, {"bn": "কাজা", "en": "Make-up"}], [{"bn": "ধূমপান বা ইচ্ছা করে ধোঁয়া টেনে নেওয়া", "en": "Smoking or deliberately inhaling smoke"}, {"bn": "কাজা", "en": "Make-up"}], [{"bn": "পুষ্টিকর ইনজেকশন বা স্যালাইন (খাবারের বিকল্প)", "en": "Nutritive injection or IV drip (a substitute for food)"}, {"bn": "কাজা (সমকালীন আলেমদের অধিকাংশের মত)", "en": "Make-up (view of most contemporary scholars)"}], [{"bn": "ইচ্ছাকৃত হস্তমৈথুন বা স্পর্শে বীর্যপাত", "en": "Deliberate ejaculation by masturbation or touching"}, {"bn": "কাজা", "en": "Make-up"}], [{"bn": "নাক বা কানে ওষুধ দিয়ে তা গলা পর্যন্ত পৌঁছানো", "en": "Nose or ear drops that reach the throat"}, {"bn": "কাজা", "en": "Make-up"}], [{"bn": "ফজর শুরু হয়ে গেছে বা সূর্য ডুবেছে ভেবে ভুল সময়ে খাওয়া", "en": "Eating at the wrong time thinking Fajr had not begun or the sun had set"}, {"bn": "কাজা (অধিকাংশ আলেমের মত)", "en": "Make-up (majority view)"}]]}, {"type": "ref", "text": {"bn": "জামে তিরমিজি ৭২০; সুনান আবু দাউদ ২৩৮০; সহিহ মুসলিম ৩৩৫", "en": "Jami'' at-Tirmidhi 720; Sunan Abi Dawud 2380; Sahih Muslim 335"}}, {"type": "heading", "text": {"bn": "যেসব কারণে রোজা ভাঙে না", "en": "What does not break the fast"}}, {"type": "table", "head": [{"bn": "কাজ", "en": "Act"}, {"bn": "হুকুম", "en": "Ruling"}], "rows": [[{"bn": "ভুলে গিয়ে খাওয়া বা পান করা", "en": "Eating or drinking forgetfully"}, {"bn": "ভাঙে না; মনে পড়লেই থামবেন", "en": "Does not break; stop as soon as you remember"}], [{"bn": "অনিচ্ছায় বমি হওয়া", "en": "Vomiting unintentionally"}, {"bn": "ভাঙে না", "en": "Does not break"}], [{"bn": "স্বপ্নদোষ, বা গোসল ফরজ অবস্থায় ফজর হয়ে যাওয়া", "en": "A wet dream, or being in a state of janabah at Fajr"}, {"bn": "ভাঙে না; গোসল করে নেবেন", "en": "Does not break; take the ghusl"}], [{"bn": "মিসওয়াক বা পেস্ট ছাড়া ব্রাশ করা", "en": "Miswak, or brushing without toothpaste"}, {"bn": "ভাঙে না; পেস্ট ব্যবহার মাকরুহ, গিলে ফেললে ভেঙে যাবে", "en": "Does not break; toothpaste is disliked and breaks the fast if swallowed"}], [{"bn": "গোসল করা, গায়ে পানি ঢালা", "en": "Bathing, pouring water over oneself"}, {"bn": "ভাঙে না, যদি পানি গলায় না যায়", "en": "Does not break if water does not go down the throat"}], [{"bn": "রক্ত পরীক্ষার জন্য রক্ত দেওয়া", "en": "Giving blood for a test"}, {"bn": "ভাঙে না", "en": "Does not break"}], [{"bn": "পুষ্টিহীন ইনজেকশন (যেমন ইনসুলিন, টিকা) মাংসে বা চামড়ায়", "en": "Non-nutritive injections (e.g. insulin, vaccines) into muscle or skin"}, {"bn": "ভাঙে না (অধিকাংশ সমকালীন আলেম)", "en": "Does not break (most contemporary scholars)"}], [{"bn": "নিজের থুথু গিলে ফেলা", "en": "Swallowing one''s own saliva"}, {"bn": "ভাঙে না", "en": "Does not break"}], [{"bn": "অনিচ্ছায় ধুলা, ধোঁয়া বা মাছি গলায় ঢুকে যাওয়া", "en": "Dust, smoke or a fly entering the throat unintentionally"}, {"bn": "ভাঙে না", "en": "Does not break"}], [{"bn": "সুগন্ধি লাগানো, তেল বা মলম মাখা", "en": "Applying perfume, oil or ointment"}, {"bn": "ভাঙে না", "en": "Does not break"}], [{"bn": "প্রয়োজনে রান্নার স্বাদ জিভে দেখে ফেলে দেওয়া", "en": "Tasting food on the tongue when needed and spitting it out"}, {"bn": "ভাঙে না; বিনা প্রয়োজনে মাকরুহ", "en": "Does not break; disliked without need"}]]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৯৩৩; সহিহ মুসলিম ১১৫৫", "en": "Sahih al-Bukhari 1933; Sahih Muslim 1155"}}, {"type": "note", "tone": "tip", "text": {"bn": "ভুলে খেয়ে ফেললে নবী (সা.) বলেছেন: সে যেন রোজা পূর্ণ করে, কেননা আল্লাহই তাকে খাইয়েছেন ও পান করিয়েছেন।", "en": "If you eat by mistake, the Prophet said: let him complete his fast, for it is Allah who fed him and gave him drink."}}, {"type": "heading", "text": {"bn": "যেসব বিষয়ে মতভেদ আছে", "en": "Points of difference"}}, {"type": "differ", "title": {"bn": "চোখে ড্রপ ও সুরমা", "en": "Eye drops and kohl"}, "views": [{"label": {"bn": "হানাফি ও শাফেয়ি", "en": "Hanafi and Shafi''i"}, "text": {"bn": "চোখে ড্রপ বা সুরমা দিলে রোজা ভাঙে না, গলায় স্বাদ পেলেও।", "en": "Eye drops or kohl do not break the fast, even if a taste is felt in the throat."}, "evidence": {"bn": "চোখ খাদ্য প্রবেশের স্বাভাবিক পথ নয়।", "en": "The eye is not a normal passage for food to enter."}}, {"label": {"bn": "মালেকি ও হাম্বলি", "en": "Maliki and Hanbali"}, "text": {"bn": "গলায় স্বাদ পৌঁছালে রোজা ভেঙে যায়; সতর্কতার জন্য দিনের বেলা না দিয়ে রাতে দেওয়া ভালো।", "en": "If the taste reaches the throat the fast is broken; to be careful, use them at night rather than in the day."}, "evidence": {"bn": "যা গলা পর্যন্ত পৌঁছায় তা ভেতরে প্রবেশ করেছে বলে গণ্য।", "en": "What reaches the throat is counted as having entered the body."}}]}, {"type": "differ", "title": {"bn": "হাঁপানির ইনহেলার", "en": "Asthma inhaler"}, "views": [{"label": {"bn": "রোজা ভাঙে (দেশের হানাফি ফতোয়া বোর্ডসহ অনেকের মত)", "en": "Breaks the fast (many, incl. Hanafi fatwa bodies in the subcontinent)"}, "text": {"bn": "ইনহেলারের ওষুধের কণা গলা হয়ে ভেতরে যায়, তাই রোজা ভেঙে যায়; প্রয়োজন হলে ব্যবহার করবেন এবং পরে কাজা করবেন।", "en": "The medicine particles of an inhaler pass down the throat, so the fast is broken; use it if needed and make the day up later."}, "evidence": {"bn": "ইচ্ছাকৃতভাবে কোনো বস্তু মুখ দিয়ে ভেতরে নেওয়ার বিধানের ওপর কিয়াস।", "en": "Analogy with deliberately taking any substance in through the mouth."}}, {"label": {"bn": "রোজা ভাঙে না (সৌদি স্থায়ী ফতোয়া কমিটিসহ অনেকের মত)", "en": "Does not break (many, incl. the Saudi Permanent Committee)"}, "text": {"bn": "ইনহেলারের ওষুধ খুব সামান্য ও মূলত ফুসফুসে যায়; এটি খাবার বা পানীয় নয়।", "en": "The amount is tiny and goes mainly to the lungs; it is neither food nor drink."}, "evidence": {"bn": "কুলি করার পর মুখে যে সামান্য আর্দ্রতা থাকে তার সঙ্গে তুলনা।", "en": "Compared to the slight moisture left in the mouth after rinsing it."}}]}, {"type": "differ", "title": {"bn": "শিঙ্গা লাগানো বা রক্তদান", "en": "Cupping or donating blood"}, "views": [{"label": {"bn": "হানাফি, মালেকি, শাফেয়ি", "en": "Hanafi, Maliki, Shafi''i"}, "text": {"bn": "রোজা ভাঙে না, তবে দুর্বল হয়ে পড়ার আশঙ্কা থাকলে মাকরুহ।", "en": "Does not break the fast, but is disliked if it may weaken the person."}, "evidence": {"bn": "নবী (সা.) রোজা অবস্থায় শিঙ্গা লাগিয়েছেন বলে সহিহ বুখারিতে বর্ণিত।", "en": "Sahih al-Bukhari reports that the Prophet was cupped while fasting."}}, {"label": {"bn": "হাম্বলি", "en": "Hanbali"}, "text": {"bn": "শিঙ্গা লাগালে বা লাগিয়ে দিলে রোজা ভেঙে যায়।", "en": "Cupping breaks the fast of both the one cupped and the one cupping."}, "evidence": {"bn": "হাদিস: ''শিঙ্গা লাগানো ও যাকে লাগানো হলো, দুজনেরই রোজা ভেঙে গেল।'' (আবু দাউদ ও অন্যান্য)", "en": "Hadith: ''The one who cups and the one cupped have broken their fast.'' (Abu Dawud and others)"}}], "check": true}, {"type": "note", "tone": "info", "text": {"bn": "চিকিৎসা-সংক্রান্ত নতুন প্রশ্নে (এন্ডোস্কপি, ডায়ালাইসিস ইত্যাদি) নির্ভরযোগ্য মুফতির কাছ থেকে জেনে নিন।", "en": "For new medical questions (endoscopy, dialysis and so on), ask a reliable mufti."}}]', 'in_review', 30 FROM is_guide_topics WHERE slug = 'sawm' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'c6c88280-80f5-5413-8b83-f0a127d5d424', id, 'sawm-qaza-kaffarah-fidya', '{"bn": "কাজা, কাফফারা ও ফিদইয়া", "en": "Qaza, kaffarah and fidya"}', '{"bn": "ভাঙা বা ছুটে যাওয়া রোজার কাজা, কাফফারা কখন লাগে, আর ফিদইয়া কার জন্য।", "en": "Making up missed fasts, when kaffarah is due, and who pays fidya."}', 'detail', '[{"type": "heading", "text": {"bn": "কাজা", "en": "Qaza (make-up)"}}, {"type": "text", "text": {"bn": "কাজা মানে ছুটে যাওয়া বা ভেঙে যাওয়া প্রতিটি রোজার বদলে পরে একটি করে রোজা রাখা। অসুস্থতা, সফর, হায়েজ-নিফাস বা অন্য কোনো কারণে রোজা ছুটে গেলে কাজা করতে হয়।", "en": "Qaza means keeping one fast later for each fast missed or broken. Fasts missed through illness, travel, menstruation, post-natal bleeding or other reasons must be made up."}}, {"type": "arabic", "ar": "فَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ", "pron": {"bn": "ফামান কানা মিনকুম মারীদান আও আলা সাফারিন ফাইদ্দাতুম মিন আইয়ামিন উখার", "en": "Faman kana minkum maridan aw ''ala safarin fa''iddatum min ayyamin ukhar"}, "meaning": {"bn": "তোমাদের মধ্যে কেউ অসুস্থ হলে বা সফরে থাকলে অন্য দিনগুলোতে সেই সংখ্যা পূরণ করবে।", "en": "Whoever of you is ill or on a journey, then an equal number of other days."}, "ref": {"bn": "সূরা বাকারা ২:১৮৪", "en": "Al-Baqarah 2:184"}}, {"type": "list", "items": [{"bn": "পরবর্তী রমজানের আগেই কাজা করে নেওয়া উত্তম; একটানা রাখা জরুরি নয়।", "en": "It is best to make up before the next Ramadan; the days need not be consecutive."}, {"bn": "কোনো ওজর ছাড়া দেরি করা ঠিক নয়। শাফেয়ি ও হাম্বলি মতে বিনা ওজরে পরের রমজান পার হয়ে গেলে কাজার সাথে প্রতিদিনের জন্য ফিদইয়াও দিতে হয়; হানাফি মতে শুধু কাজা।", "en": "Do not delay without excuse. In the Shafi''i and Hanbali view, if the next Ramadan passes without excuse, a fidya per day is due with the make-up; in the Hanafi view only the make-up."}, {"bn": "নিয়ত রাতেই করবেন: ''আমি রমজানের একটি কাজা রোজা রাখছি'' এমন ইচ্ছা মনে রাখাই যথেষ্ট।", "en": "Make the intention at night; the intention in the heart that ''I am keeping a missed Ramadan fast'' is enough."}]}, {"type": "heading", "text": {"bn": "কাফফারা", "en": "Kaffarah (expiation)"}}, {"type": "text", "text": {"bn": "রমজানের রোজা অবস্থায় ইচ্ছাকৃতভাবে স্ত্রী-সহবাস করলে কাজার সাথে কাফফারাও দিতে হয়। এক ব্যক্তি এমন করে নবী (সা.)-এর কাছে এলে তিনি তাকে ক্রমানুসারে এই তিনটির কথা বলেন:", "en": "Deliberate intercourse while fasting in Ramadan requires kaffarah in addition to the make-up. When a man who had done this came to the Prophet, he told him these three, in order:"}}, {"type": "step", "title": {"bn": "দাস মুক্ত করা", "en": "Free a slave"}, "text": {"bn": "বর্তমানে এর সুযোগ নেই, তাই পরের ধাপ প্রযোজ্য।", "en": "This is not possible today, so the next option applies."}}, {"type": "step", "title": {"bn": "একটানা ৬০ দিন রোজা", "en": "Fast 60 consecutive days"}, "text": {"bn": "মাঝে এক দিনও বাদ পড়লে (নারীর হায়েজ ছাড়া) নতুন করে শুরু করতে হবে।", "en": "If even one day is missed (except a woman''s menstruation), it must be started again."}}, {"type": "step", "title": {"bn": "৬০ জন মিসকিনকে খাওয়ানো", "en": "Feed 60 poor people"}, "text": {"bn": "অসুস্থতা বা বার্ধক্যের কারণে ৬০ রোজা রাখতে অক্ষম হলে ৬০ জন মিসকিনকে দুই বেলা পেট ভরে খাওয়াবেন, অথবা (হানাফি মতে) প্রত্যেককে একটি ফিতরা পরিমাণ দেবেন।", "en": "If unable to fast 60 days due to illness or old age, feed 60 poor people two full meals each, or (Hanafi view) give each the amount of one sadaqatul fitr."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৯৩৬; সহিহ মুসলিম ১১১১", "en": "Sahih al-Bukhari 1936; Sahih Muslim 1111"}}, {"type": "differ", "title": {"bn": "ইচ্ছাকৃত খাওয়া-দাওয়ায় কাফফারা আছে কি না", "en": "Is kaffarah due for deliberate eating and drinking"}, "views": [{"label": {"bn": "হানাফি ও মালেকি", "en": "Hanafi and Maliki"}, "text": {"bn": "বিনা ওজরে রমজানের রোজা ইচ্ছাকৃতভাবে খেয়ে বা পান করে ভাঙলেও কাজা ও কাফফারা দুটোই লাগবে।", "en": "Deliberately breaking a Ramadan fast by eating or drinking without excuse also requires both make-up and kaffarah."}, "evidence": {"bn": "কাফফারার কারণ রমজানের পবিত্রতা ইচ্ছাকৃতভাবে নষ্ট করা, যা খাওয়া-দাওয়াতেও পাওয়া যায়।", "en": "The cause of kaffarah is deliberately violating the sanctity of Ramadan, which also happens by eating."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি", "en": "Shafi''i and Hanbali"}, "text": {"bn": "কাফফারা শুধু সহবাসের ক্ষেত্রে; খাওয়া-দাওয়ায় শুধু কাজা এবং তওবা।", "en": "Kaffarah is only for intercourse; for eating and drinking only make-up and repentance."}, "evidence": {"bn": "হাদিসে কাফফারা শুধু সহবাসের ঘটনায় এসেছে; অন্য কিছুকে এর সাথে মেলানো যায় না।", "en": "The hadith mentions kaffarah only for intercourse; other cases are not joined to it."}}]}, {"type": "heading", "text": {"bn": "ফিদইয়া", "en": "Fidya (compensation)"}}, {"type": "text", "text": {"bn": "যে ব্যক্তি বার্ধক্য বা আরোগ্যের আশা নেই এমন রোগের কারণে রোজা রাখতে পারেন না এবং পরে কাজা করারও সম্ভাবনা নেই, তিনি প্রতিটি রোজার বদলে একজন মিসকিনকে খাবার দেবেন। একে ফিদইয়া বলে।", "en": "A person who cannot fast because of old age or an illness with no hope of recovery, and who has no prospect of making it up later, feeds one poor person for each day missed. This is called fidya."}}, {"type": "arabic", "ar": "وَعَلَى الَّذِينَ يُطِيقُونَهُ فِدْيَةٌ طَعَامُ مِسْكِينٍ", "pron": {"bn": "ওয়া আলাল্লাযীনা ইউতীকূনাহূ ফিদইয়াতুন তাআমু মিসকীন", "en": "Wa ''alal-ladhina yutiqunahu fidyatun ta''amu miskin"}, "meaning": {"bn": "আর যাদের জন্য এটা অত্যন্ত কষ্টকর, তাদের ওপর ফিদইয়া: একজন মিসকিনকে খাওয়ানো।", "en": "And upon those who can only do it with great hardship, a compensation: feeding a poor person."}, "ref": {"bn": "সূরা বাকারা ২:১৮৪", "en": "Al-Baqarah 2:184"}}, {"type": "differ", "title": {"bn": "ফিদইয়ার পরিমাণ", "en": "Amount of fidya"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "প্রতি রোজার জন্য একটি সদকাতুল ফিতরের সমান (অর্ধ সা'' গম বা এক সা'' খেজুর/যব), অথবা তার বাজারমূল্য; কিংবা একজন মিসকিনকে দুই বেলা পেট ভরে খাওয়ানো।", "en": "For each fast, the amount of one sadaqatul fitr (half a sa'' of wheat or a sa'' of dates/barley) or its market value; or two full meals for one poor person."}, "evidence": {"bn": "সদকাতুল ফিতরের পরিমাণের ওপর কিয়াস; হানাফি মতে মূল্য দেওয়াও জায়েজ।", "en": "Analogy with sadaqatul fitr; Hanafis allow giving the value."}}, {"label": {"bn": "শাফেয়ি, মালেকি, হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "প্রতি রোজার জন্য এক মুদ (প্রায় ৫০০–৬০০ গ্রাম) খাদ্যশস্য; হাম্বলি মতে গম হলে এক মুদ, অন্য শস্য হলে অর্ধ সা''। টাকা দিলে আদায় হবে না।", "en": "One mudd (about 500–600 g) of staple food per fast; Hanbalis: a mudd of wheat or half a sa'' of other grain. Money does not count."}, "evidence": {"bn": "সাহাবিদের আমল, যেমন ইবনে আব্বাস (রা.) ও আনাস (রা.)-এর ফতোয়া।", "en": "Practice of the Companions, e.g. the fatwas of Ibn Abbas and Anas."}}]}, {"type": "note", "tone": "warn", "text": {"bn": "সুস্থ মানুষ, যিনি পরে কাজা করতে পারবেন, তার জন্য ফিদইয়া দিয়ে রোজা ছেড়ে দেওয়া জায়েজ নয়। ফিদইয়া দেওয়ার পর আল্লাহর রহমতে সুস্থ হয়ে গেলে হানাফি মতে কাজা করতে হবে।", "en": "A healthy person who can make up later may not skip fasts by paying fidya. If someone pays fidya and later recovers, in the Hanafi view he must make up the fasts."}}]', 'in_review', 40 FROM is_guide_topics WHERE slug = 'sawm' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '3b72a95f-8b60-524e-b519-bbe73b272a75', id, 'sawm-excused', '{"bn": "যাদের জন্য রোজা না রাখার অনুমতি আছে", "en": "Who is excused from fasting"}', '{"bn": "অসুস্থ, মুসাফির, গর্ভবতী ও দুগ্ধদানকারী মা, বৃদ্ধ, আর হায়েজ-নিফাস অবস্থায় নারীর বিধান।", "en": "Rulings for the sick, travellers, pregnant and nursing mothers, the elderly, and women in menstruation or post-natal bleeding."}', 'basic', '[{"type": "arabic", "ar": "يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ وَلَا يُرِيدُ بِكُمُ الْعُسْرَ", "pron": {"bn": "ইউরীদুল্লাহু বিকুমুল ইউসরা ওয়ালা ইউরীদু বিকুমুল উসর", "en": "Yuridullahu bikumul-yusra wa la yuridu bikumul-''usr"}, "meaning": {"bn": "আল্লাহ তোমাদের জন্য সহজ চান, কঠিন চান না।", "en": "Allah intends ease for you and does not intend hardship."}, "ref": {"bn": "সূরা বাকারা ২:১৮৫", "en": "Al-Baqarah 2:185"}}, {"type": "table", "head": [{"bn": "কে", "en": "Who"}, {"bn": "রোজা", "en": "Fasting"}, {"bn": "পরে করণীয়", "en": "Afterwards"}], "rows": [[{"bn": "অসুস্থ (রোজায় রোগ বাড়ার বা দেরিতে সারার আশঙ্কা)", "en": "Sick (fasting may worsen or prolong the illness)"}, {"bn": "না রাখার অনুমতি", "en": "May leave it"}, {"bn": "সুস্থ হলে কাজা", "en": "Make up when well"}], [{"bn": "মুসাফির (শরিয়তসম্মত সফর)", "en": "Traveller (Shariah-defined journey)"}, {"bn": "রাখা বা না রাখা দুটোই জায়েজ", "en": "May fast or not"}, {"bn": "না রাখলে কাজা", "en": "Make up if not fasted"}], [{"bn": "গর্ভবতী বা দুগ্ধদানকারী মা (নিজের বা সন্তানের ক্ষতির আশঙ্কা)", "en": "Pregnant or nursing mother (fears harm to herself or the child)"}, {"bn": "না রাখার অনুমতি", "en": "May leave it"}, {"bn": "কাজা; ফিদইয়া নিয়ে মতভেদ নিচে", "en": "Make up; fidya is differed on, see below"}], [{"bn": "অতি বৃদ্ধ বা চিরস্থায়ী রোগী", "en": "Very elderly or chronically ill"}, {"bn": "না রাখার অনুমতি", "en": "May leave it"}, {"bn": "প্রতিদিনের জন্য ফিদইয়া", "en": "Fidya for each day"}], [{"bn": "হায়েজ বা নিফাস অবস্থায় নারী", "en": "Woman in menstruation or post-natal bleeding"}, {"bn": "রাখা নিষেধ", "en": "Must not fast"}, {"bn": "পরে কাজা", "en": "Make up later"}]]}, {"type": "heading", "text": {"bn": "অসুস্থ ব্যক্তি", "en": "The sick"}}, {"type": "text", "text": {"bn": "শুধু সামান্য অসুবিধা নয়, বরং অভিজ্ঞ চিকিৎসকের মতামত বা নিজের অভিজ্ঞতা থেকে যদি প্রবল ধারণা হয় যে রোজা রাখলে রোগ বাড়বে, দেরিতে সারবে বা মারাত্মক ক্ষতি হবে, তাহলে রোজা না রেখে পরে কাজা করবেন। প্রাণের আশঙ্কা থাকলে রোজা ভেঙে ফেলাই আবশ্যক।", "en": "Not a minor discomfort, but when an experienced doctor''s opinion or one''s own experience strongly suggests that fasting will worsen the illness, delay recovery or cause serious harm, one does not fast and makes it up later. If life is at risk, breaking the fast is required."}}, {"type": "heading", "text": {"bn": "মুসাফির", "en": "The traveller"}}, {"type": "text", "text": {"bn": "শরিয়তসম্মত সফরে (হানাফি মতে প্রায় ৪৮ মাইল বা ৭৭–৭৮ কিলোমিটার বা তার বেশি দূরত্বের সফর) রোজা না রাখার অনুমতি আছে। কষ্ট না হলে রাখাই উত্তম, কষ্ট হলে না রাখা উত্তম। সফর শুরুর দিন সকালে বাড়িতে রোজা শুরু করলে হানাফি মতে সেদিনের রোজা পূর্ণ করাই উচিত।", "en": "On a Shariah journey (Hanafi: about 48 miles / 77–78 km or more) one may leave the fast. If it is not hard, fasting is better; if it is hard, not fasting is better. If you began the fast at home on the morning you set out, Hanafis say you should complete that day."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৯৪৩; সহিহ মুসলিম ১১২১", "en": "Sahih al-Bukhari 1943; Sahih Muslim 1121"}}, {"type": "heading", "text": {"bn": "গর্ভবতী ও দুগ্ধদানকারী মা", "en": "Pregnant and nursing mothers"}}, {"type": "text", "text": {"bn": "নিজের বা সন্তানের স্বাস্থ্যের ক্ষতির আশঙ্কা থাকলে তারা রোজা না রেখে পরে রাখতে পারেন। নবী (সা.) বলেছেন, আল্লাহ মুসাফির, গর্ভবতী ও দুগ্ধদানকারী মায়ের জন্য রোজায় ছাড় দিয়েছেন।", "en": "If they fear harm to their own health or the child''s, they may leave the fast and keep it later. The Prophet said that Allah has relieved the traveller, the pregnant and the nursing woman of fasting."}}, {"type": "ref", "text": {"bn": "জামে তিরমিজি; সুনান আবু দাউদ (আনাস ইবনে মালিক আল-কা''বি রা.-এর বর্ণনা)", "en": "Jami'' at-Tirmidhi; Sunan Abi Dawud (narration of Anas ibn Malik al-Ka''bi)"}, "check": true}, {"type": "differ", "title": {"bn": "কাজার সঙ্গে ফিদইয়াও লাগবে কি না", "en": "Is fidya due along with the make-up"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "শুধু কাজা; ফিদইয়া লাগবে না, ক্ষতির আশঙ্কা নিজের জন্য হোক বা সন্তানের জন্য।", "en": "Only make-up, no fidya, whether the fear was for herself or the child."}, "evidence": {"bn": "তারা অসুস্থ ব্যক্তির মতো, যার জন্য কুরআনে শুধু কাজার কথা বলা হয়েছে।", "en": "They are like the sick person, for whom the Quran mentions only make-up."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি", "en": "Shafi''i and Hanbali"}, "text": {"bn": "শুধু নিজের জন্য ভয় হলে কাজা; সন্তানের জন্য ভয়ে রোজা না রাখলে কাজার সাথে প্রতিদিন এক মুদ ফিদইয়াও।", "en": "If she feared only for herself, make-up; if she left it fearing for the child, make-up plus one mudd of fidya per day."}, "evidence": {"bn": "ইবনে আব্বাস (রা.) ও ইবনে উমর (রা.)-এর ফতোয়া।", "en": "Fatwas of Ibn Abbas and Ibn Umar."}}, {"label": {"bn": "মালেকি", "en": "Maliki"}, "text": {"bn": "গর্ভবতী শুধু কাজা করবেন; দুগ্ধদানকারী মা কাজা ও ফিদইয়া দুটোই।", "en": "The pregnant woman only makes up; the nursing mother makes up and pays fidya."}, "evidence": {"bn": "গর্ভাবস্থাকে অসুস্থতার মতো ধরা হয়, দুধ খাওয়ানোকে নয়।", "en": "Pregnancy is treated like illness, nursing is not."}}]}, {"type": "heading", "text": {"bn": "বৃদ্ধ ও স্থায়ী রোগী", "en": "The elderly and chronically ill"}}, {"type": "text", "text": {"bn": "যে বৃদ্ধ রোজা রাখার শক্তি রাখেন না, বা যার রোগ সারার আশা নেই, তিনি প্রতিটি রোজার বদলে ফিদইয়া দেবেন। বিস্তারিত ''কাজা, কাফফারা ও ফিদইয়া'' গাইডে।", "en": "An elderly person without the strength to fast, or someone with no hope of recovery, gives fidya for each day. Details are in the ''Qaza, kaffarah and fidya'' guide."}}, {"type": "heading", "text": {"bn": "হায়েজ ও নিফাস", "en": "Menstruation and post-natal bleeding"}}, {"type": "list", "items": [{"bn": "হায়েজ বা নিফাস অবস্থায় রোজা রাখা জায়েজ নয়; পরে কাজা করতে হবে। নামাজের কাজা নেই, রোজার কাজা আছে।", "en": "Fasting is not allowed during menstruation or post-natal bleeding; the fasts are made up later. Prayers are not made up, fasts are."}, {"bn": "দিনের বেলায় রক্ত শুরু হলে সেদিনের রোজা ভেঙে যায়, ইফতারের এক মিনিট আগে হলেও।", "en": "If bleeding starts during the day, that day''s fast is broken, even a minute before sunset."}, {"bn": "ফজরের আগে পবিত্র হয়ে গেলে রোজা রাখবেন, গোসল ফজরের পরে করলেও সমস্যা নেই।", "en": "If she becomes pure before Fajr she fasts, even if she takes the ghusl after Fajr."}, {"bn": "দিনের বেলায় পবিত্র হলে হানাফি মতে সন্ধ্যা পর্যন্ত খাওয়া-দাওয়া থেকে বিরত থাকা উচিত, তবে সেদিনের কাজা করতে হবে।", "en": "If she becomes pure during the day, Hanafis say she should refrain from eating until sunset, but still make up that day."}, {"bn": "ওষুধ খেয়ে মাসিক পিছিয়ে দেওয়া স্বাস্থ্যের ক্ষতি না হলে অনেক আলেমের মতে জায়েজ, তবে স্বাভাবিক নিয়মে চলাই উত্তম।", "en": "Delaying the period with pills is allowed by many scholars if it causes no harm, though following the natural course is better."}]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৩৩৫", "en": "Sahih Muslim 335"}}]', 'in_review', 50 FROM is_guide_topics WHERE slug = 'sawm' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '5891afe3-03f2-5fb7-bea1-0c36aba5b830', id, 'sawm-laylatul-qadr-itikaf', '{"bn": "লাইলাতুল কদর ও ইতিকাফ", "en": "Laylatul Qadr and i''tikaf"}', '{"bn": "হাজার মাসের চেয়ে উত্তম রাত খোঁজা, এ রাতের দোয়া এবং শেষ দশকের ইতিকাফের নিয়ম।", "en": "Seeking the night better than a thousand months, its dua, and i''tikaf in the last ten nights."}', 'basic', '[{"type": "heading", "text": {"bn": "লাইলাতুল কদর (শবে কদর)", "en": "Laylatul Qadr"}}, {"type": "arabic", "ar": "لَيْلَةُ الْقَدْرِ خَيْرٌ مِنْ أَلْفِ شَهْرٍ", "pron": {"bn": "লাইলাতুল কাদরি খাইরুম মিন আলফি শাহর", "en": "Laylatul-qadri khayrum min alfi shahr"}, "meaning": {"bn": "কদরের রাত হাজার মাসের চেয়েও উত্তম।", "en": "The Night of Decree is better than a thousand months."}, "ref": {"bn": "সূরা কদর ৯৭:৩", "en": "Al-Qadr 97:3"}}, {"type": "text", "text": {"bn": "এই রাতে কুরআন নাজিল হয়েছে। যে ব্যক্তি ঈমানের সাথে ও সওয়াবের আশায় এ রাতে ইবাদত করে, তার আগের গুনাহ ক্ষমা করা হয়। নির্দিষ্ট তারিখ জানানো হয়নি; রমজানের শেষ দশকের বেজোড় রাতগুলোতে খুঁজতে বলা হয়েছে (২১, ২৩, ২৫, ২৭, ২৯-এর রাত)। ২৭-এর রাতের কথা অনেক সাহাবি বলেছেন, তবে শুধু এক রাতে সীমাবদ্ধ না থেকে পুরো শেষ দশকে চেষ্টা করুন।", "en": "The Quran was revealed on this night. Whoever stands in worship on it with faith and hoping for reward has his past sins forgiven. Its date was not fixed; we are told to seek it in the odd nights of the last ten of Ramadan (the nights before the 21st, 23rd, 25th, 27th, 29th). Many Companions held it to be the 27th, but strive through all of the last ten rather than one night."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৯০১; সহিহ বুখারি ২০১৭; সহিহ মুসলিম ৭৬২", "en": "Sahih al-Bukhari 1901; Sahih al-Bukhari 2017; Sahih Muslim 762"}}, {"type": "arabic", "label": {"bn": "লাইলাতুল কদরের দোয়া", "en": "Dua for Laylatul Qadr"}, "ar": "اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي", "pron": {"bn": "আল্লাহুম্মা ইন্নাকা আফুওউন তুহিব্বুল আফওয়া ফা''ফু আন্নি", "en": "Allahumma innaka ''afuwwun tuhibbul-''afwa fa''fu ''anni"}, "meaning": {"bn": "হে আল্লাহ! তুমি ক্ষমাশীল, ক্ষমা করতে ভালোবাসো, অতএব আমাকে ক্ষমা করো।", "en": "O Allah, You are Pardoning and love to pardon, so pardon me."}, "ref": {"bn": "জামে তিরমিজি ৩৫১৩; সুনান ইবনে মাজাহ ৩৮৫০", "en": "Jami'' at-Tirmidhi 3513; Sunan Ibn Majah 3850"}}, {"type": "note", "tone": "info", "text": {"bn": "আয়েশা (রা.) জিজ্ঞেস করেছিলেন, কদরের রাত পেলে কী বলবেন; নবী (সা.) এই দোয়াটি শিখিয়ে দেন। কিছু ছাপা বইয়ে ''আফুওউন''-এর পরে ''কারীম'' শব্দটি আছে, তবে নির্ভরযোগ্য বর্ণনায় এটি নেই।", "en": "Aishah asked what she should say if she found the Night of Decree, and the Prophet taught her this dua. Some printed editions add ''karim'' after ''''afuwwun'', but the reliable narrations do not have it."}}, {"type": "list", "items": [{"bn": "নফল নামাজ, কুরআন তিলাওয়াত, জিকির, দোয়া ও ইস্তিগফার করুন।", "en": "Pray voluntary prayers, recite the Quran, do dhikr, make dua and seek forgiveness."}, {"bn": "এ রাতের জন্য নির্দিষ্ট রাকাত সংখ্যা বা বিশেষ সূরা দিয়ে নির্দিষ্ট পদ্ধতির নামাজ হাদিসে নেই; প্রচলিত এমন পদ্ধতিগুলো ভিত্তিহীন।", "en": "No hadith sets a particular number of rakats or special surahs for a ''Qadr prayer''; such popular methods have no basis."}, {"bn": "ভোরে সূর্য আলোকরশ্মি ছাড়া স্নিগ্ধভাবে ওঠা এ রাতের একটি আলামত হিসেবে বর্ণিত।", "en": "One reported sign is that the sun rises the next morning soft, without strong rays."}]}, {"type": "heading", "text": {"bn": "ইতিকাফ", "en": "I''tikaf"}}, {"type": "text", "text": {"bn": "ইতিকাফ মানে ইবাদতের নিয়তে মসজিদে অবস্থান করা। নবী (সা.) ইন্তেকাল পর্যন্ত প্রতি রমজানের শেষ দশ দিন ইতিকাফ করেছেন। হানাফি মতে রমজানের শেষ দশকের ইতিকাফ সুন্নতে মুয়াক্কাদা আলাল কিফায়া: মহল্লার কেউ একজন করলে সবার পক্ষ থেকে আদায় হয়।", "en": "I''tikaf means staying in the masjid with the intention of worship. The Prophet did i''tikaf in the last ten days of every Ramadan until he passed away. For Hanafis the i''tikaf of the last ten of Ramadan is a communal emphasised sunnah: if one person of the locality does it, the duty is fulfilled for all."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ২০২৬; সহিহ মুসলিম ১১৭২", "en": "Sahih al-Bukhari 2026; Sahih Muslim 1172"}}, {"type": "arabic", "ar": "وَلَا تُبَاشِرُوهُنَّ وَأَنْتُمْ عَاكِفُونَ فِي الْمَسَاجِدِ", "pron": {"bn": "ওয়ালা তুবাশিরূহুন্না ওয়া আনতুম আকিফূনা ফিল মাসাজিদ", "en": "Wa la tubashiruhunna wa antum ''akifuna fil-masajid"}, "meaning": {"bn": "আর মসজিদে ইতিকাফ অবস্থায় তোমরা স্ত্রীদের সঙ্গে মেলামেশা করো না।", "en": "And do not have relations with them while you are in i''tikaf in the masjids."}, "ref": {"bn": "সূরা বাকারা ২:১৮৭", "en": "Al-Baqarah 2:187"}}, {"type": "step", "title": {"bn": "শুরু", "en": "Start"}, "text": {"bn": "২০ রমজান সূর্যাস্তের আগে ইতিকাফের নিয়তে মসজিদে প্রবেশ করুন (মনে মনে নিয়তই যথেষ্ট)।", "en": "Enter the masjid before sunset on the 20th of Ramadan with the intention of i''tikaf (an intention in the heart is enough)."}}, {"type": "step", "title": {"bn": "অবস্থান", "en": "Stay"}, "text": {"bn": "শেষ দশ দিন মসজিদেই থাকবেন; ঘুম, খাওয়া সব মসজিদে। সময় কাটান নামাজ, তিলাওয়াত, জিকির, দোয়া ও দ্বীনি পড়াশোনায়।", "en": "Stay in the masjid for the last ten days, sleeping and eating there. Spend the time in prayer, recitation, dhikr, dua and religious study."}}, {"type": "step", "title": {"bn": "বের হওয়া", "en": "Going out"}, "text": {"bn": "শুধু প্রয়োজনে বের হওয়া যায়: প্রস্রাব-পায়খানা, ফরজ গোসল, খাবার এনে দেওয়ার কেউ না থাকলে খাবার আনা, আর মসজিদে জুমা না হলে জুমার জন্য। প্রয়োজন শেষ হলেই ফিরে আসবেন।", "en": "Leave only for needs: the toilet, an obligatory ghusl, fetching food if no one can bring it, and Jumu''ah if it is not held in that masjid. Return as soon as the need is done."}}, {"type": "step", "title": {"bn": "শেষ", "en": "End"}, "text": {"bn": "শাওয়ালের চাঁদ দেখা গেলে (ঈদের আগের সন্ধ্যায়) ইতিকাফ শেষ।", "en": "I''tikaf ends when the Shawwal moon is sighted (the evening before Eid)."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ২০২৯", "en": "Sahih al-Bukhari 2029"}}, {"type": "note", "tone": "warn", "text": {"bn": "বিনা প্রয়োজনে মসজিদ থেকে বের হলে বা স্ত্রী-সহবাস করলে ইতিকাফ ভেঙে যায়। অপ্রয়োজনীয় গল্প, মোবাইল ঘাঁটা ও অনর্থক কাজ থেকে দূরে থাকুন।", "en": "Leaving the masjid without need or marital relations break the i''tikaf. Avoid idle chatter, endless phone scrolling and pointless activity."}}, {"type": "differ", "title": {"bn": "নারীদের ইতিকাফ কোথায়", "en": "Where women do i''tikaf"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "নারীরা ঘরের নামাজের জন্য নির্দিষ্ট স্থানে (মসজিদে বাইত) ইতিকাফ করবেন; এটাই তাদের জন্য উত্তম।", "en": "Women do i''tikaf in the place set aside for prayer in the home (masjid al-bayt); this is better for them."}, "evidence": {"bn": "নারীদের নামাজ ঘরে উত্তম হওয়ার হাদিসগুলোর ওপর কিয়াস।", "en": "Analogy with the hadiths that a woman''s prayer at home is better."}}, {"label": {"bn": "শাফেয়ি, মালেকি, হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "নারী-পুরুষ সবার ইতিকাফ মসজিদেই হতে হবে, যদি নিরাপদ ব্যবস্থা থাকে।", "en": "I''tikaf for men and women alike must be in a masjid, where it is safe and suitable."}, "evidence": {"bn": "আয়াতে ''মসজিদে'' বলা হয়েছে, আর নবীপত্নীগণ মসজিদে ইতিকাফ করেছেন।", "en": "The verse says ''in the masjids'', and the Prophet''s wives did i''tikaf in the masjid."}}]}]', 'in_review', 60 FROM is_guide_topics WHERE slug = 'sawm' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '4d92f55d-3e37-5f12-83f3-12dda2e9ccfb', id, 'sawm-sadaqatul-fitr', '{"bn": "সদকাতুল ফিতর (ফিতরা)", "en": "Sadaqatul fitr (fitrah)"}', '{"bn": "ঈদুল ফিতরের আগে আদায় করা ওয়াজিব দান: কার ওপর, কত, কখন এবং কাকে দেবেন।", "en": "The charity due before Eid al-Fitr: who pays, how much, when and to whom."}', 'basic', '[{"type": "text", "text": {"bn": "সদকাতুল ফিতর রোজার ভুলত্রুটি থেকে রোজাদারকে পবিত্র করে এবং গরিবদের ঈদের দিনের খাবারের ব্যবস্থা করে। নবী (সা.) প্রত্যেক মুসলিম নারী-পুরুষ, ছোট-বড়, স্বাধীন-দাস সবার পক্ষ থেকে ঈদের নামাজে যাওয়ার আগে এক সা'' খেজুর বা এক সা'' যব দেওয়ার নির্দেশ দিয়েছেন।", "en": "Sadaqatul fitr purifies the fasting person from idle and indecent talk and provides food for the poor on Eid. The Prophet ordered one sa'' of dates or one sa'' of barley on behalf of every Muslim, male and female, young and old, free and slave, to be given before people go out to the Eid prayer."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৫০৩; সুনান আবু দাউদ ১৬০৯", "en": "Sahih al-Bukhari 1503; Sunan Abi Dawud 1609"}}, {"type": "heading", "text": {"bn": "কার ওপর ওয়াজিব", "en": "Who must pay"}}, {"type": "differ", "title": {"bn": "ফিতরা কার ওপর ওয়াজিব", "en": "On whom fitrah is due"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "ঈদের দিন সুবহে সাদিকের সময় যে মুসলিম মৌলিক প্রয়োজনের অতিরিক্ত নিসাব পরিমাণ সম্পদের মালিক, তার ওপর ওয়াজিব (এক বছর পূর্ণ হওয়া শর্ত নয়)। নিজের ও নাবালেগ সন্তানের পক্ষ থেকে দেবেন।", "en": "Due on a Muslim who, at dawn on Eid day, owns wealth of nisab value beyond basic needs (a full year is not required). He pays for himself and his minor children."}, "evidence": {"bn": "হাদিস: ''সদকা কেবল সচ্ছলতা থেকেই।''", "en": "Hadith: ''Charity is only from surplus wealth.''"}}, {"label": {"bn": "শাফেয়ি, মালেকি, হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "ঈদের দিন ও রাতের খাবারের অতিরিক্ত এক সা'' খাদ্য যার কাছে আছে, তার ওপরই ওয়াজিব; নিসাব শর্ত নয়। পরিবারের যাদের ভরণপোষণ তার দায়িত্বে, তাদের পক্ষ থেকেও দেবেন।", "en": "Due on anyone who has one sa'' of food beyond what he needs for Eid day and night; nisab is not required. He also pays for those he must support."}, "evidence": {"bn": "হাদিসে ''প্রত্যেক মুসলিমের ওপর'' বলা হয়েছে, ধনী হওয়ার শর্ত নেই।", "en": "The hadith says ''on every Muslim'' without a condition of wealth."}}]}, {"type": "note", "tone": "tip", "text": {"bn": "রোজা রাখতে না পারলেও ফিতরা দিতে হবে। ঈদের দিন ফজরের আগে জন্ম নেওয়া শিশুর পক্ষ থেকেও দিতে হয়।", "en": "Fitrah is due even from someone who could not fast, and also for a child born before Fajr on Eid day."}}, {"type": "heading", "text": {"bn": "পরিমাণ", "en": "Amount"}}, {"type": "table", "head": [{"bn": "খাদ্য", "en": "Food"}, {"bn": "হানাফি মতে পরিমাণ", "en": "Hanafi amount"}, {"bn": "অন্য তিন মাজহাব", "en": "Other three madhhabs"}], "rows": [[{"bn": "গম বা আটা", "en": "Wheat or flour"}, {"bn": "অর্ধ সা'' (প্রায় ১ কেজি ৬৫০ গ্রাম)", "en": "Half a sa'' (about 1.65 kg)"}, {"bn": "এক সা''", "en": "One sa''"}], [{"bn": "খেজুর", "en": "Dates"}, {"bn": "এক সা'' (প্রায় ৩ কেজি ৩০০ গ্রাম)", "en": "One sa'' (about 3.3 kg)"}, {"bn": "এক সা''", "en": "One sa''"}], [{"bn": "যব", "en": "Barley"}, {"bn": "এক সা''", "en": "One sa''"}, {"bn": "এক সা''", "en": "One sa''"}], [{"bn": "কিশমিশ", "en": "Raisins"}, {"bn": "এক সা'' (এক বর্ণনায় অর্ধ সা'')", "en": "One sa'' (half in one report)"}, {"bn": "এক সা''", "en": "One sa''"}], [{"bn": "পনির", "en": "Dried cheese (aqit)"}, {"bn": "এক সা''", "en": "One sa''"}, {"bn": "এক সা''", "en": "One sa''"}], [{"bn": "চাল বা অন্য প্রধান খাদ্য", "en": "Rice or other staple"}, {"bn": "মূল্য হিসেবে ওপরের কোনোটির সমান", "en": "Equal in value to one of the above"}, {"bn": "এক সা'' (প্রায় ২.৫–৩ কেজি; সা''-এর ওজন নিয়ে মতভেদ আছে)", "en": "One sa'' (about 2.5–3 kg; the weight of a sa'' is differed on)"}]]}, {"type": "differ", "title": {"bn": "টাকা দিয়ে ফিতরা দেওয়া যাবে কি না", "en": "Can fitrah be paid in money"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "খাদ্য বা তার বাজারমূল্য দুটোই দেওয়া যায়; গরিবের প্রয়োজন বিবেচনায় টাকা দেওয়া অনেক সময় উত্তম। বাংলাদেশে প্রতি বছর ইসলামিক ফাউন্ডেশন গম, যব, খেজুর, কিশমিশ ও পনিরের দাম ধরে সর্বনিম্ন ও সর্বোচ্চ পরিমাণ ঘোষণা করে; সামর্থ্য অনুযায়ী উচ্চতর খাদ্যের মূল্যে দেওয়া উত্তম।", "en": "Food or its market value may be given; money is often better given the needs of the poor. In Bangladesh the Islamic Foundation announces each year the amounts based on wheat, barley, dates, raisins and cheese; giving at the rate of a higher food is better for those who can."}, "evidence": {"bn": "উদ্দেশ্য গরিবের প্রয়োজন পূরণ; উমর ইবনে আবদুল আজিজসহ কিছু তাবেয়ির আমল এবং মুয়াজ (রা.) থেকে যাকাতে পণ্যের বদলে মূল্য গ্রহণের বর্ণনা।", "en": "The aim is to meet the needs of the poor; the practice of some Successors such as Umar ibn Abd al-Aziz, and reports from Mu''adh of taking value in zakat."}}, {"label": {"bn": "শাফেয়ি, মালেকি, হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "নির্ধারিত খাদ্যই দিতে হবে (দেশের প্রধান খাদ্য, যেমন চাল); টাকা দিলে আদায় হবে না।", "en": "It must be given as food (the local staple, such as rice); money does not discharge it."}, "evidence": {"bn": "নবী (সা.) ও সাহাবিরা দিনার-দিরহাম থাকা সত্ত্বেও খাদ্য দিয়েছেন, এবং হাদিসে খাদ্যের নাম উল্লেখ করা হয়েছে।", "en": "The Prophet and Companions gave food although coins existed, and the hadith names foods."}}]}, {"type": "heading", "text": {"bn": "কখন ও কাকে", "en": "When and to whom"}}, {"type": "list", "items": [{"bn": "ঈদের নামাজে যাওয়ার আগে দেওয়া উত্তম। সাহাবিরা ঈদের এক-দুই দিন আগেও দিতেন। গরিবরা যাতে ঈদের প্রস্তুতি নিতে পারে, তাই কয়েক দিন আগে দেওয়াও ভালো (হানাফি মতে রমজানের যেকোনো সময় দেওয়া যায়)।", "en": "Best before the Eid prayer. The Companions gave it a day or two before Eid. Giving a few days early helps the poor prepare (Hanafis allow any time in Ramadan)."}, {"bn": "ঈদের নামাজের পর পর্যন্ত দেরি করা ঠিক নয়; দেরি হলেও দায়িত্ব শেষ হয় না, আদায় করতেই হবে।", "en": "Do not delay it past the Eid prayer; if delayed, it is still owed and must be paid."}, {"bn": "যাকাতের যারা হকদার, ফিতরাও তাদেরই দেবেন, বিশেষ করে গরিব-মিসকিন। নিজের মা-বাবা, সন্তান ও স্ত্রীকে দেওয়া যায় না।", "en": "Give it to those eligible for zakat, especially the poor and needy; not to one''s own parents, children or spouse."}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি (ইবনে উমর রা. ঈদের এক-দুই দিন আগে ফিতরা দিতেন)", "en": "Sahih al-Bukhari (Ibn Umar gave it a day or two before Eid)"}, "check": true}]', 'in_review', 70 FROM is_guide_topics WHERE slug = 'sawm' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '8498d3a7-f68f-5632-9fe6-a0a1fd3e4c5f', id, 'sawm-nafl-and-forbidden', '{"bn": "নফল রোজা ও যেসব দিনে রোজা নিষেধ", "en": "Voluntary fasts and forbidden fasting days"}', '{"bn": "শাওয়ালের ছয় রোজা, আরাফা, আশুরা, সোম-বৃহস্পতিবার, আইয়ামে বিজ এবং যেদিন রোজা রাখা নিষেধ।", "en": "Six of Shawwal, Arafah, Ashura, Mondays and Thursdays, the White Days, and the days fasting is forbidden."}', 'basic', '[{"type": "heading", "text": {"bn": "সুন্নত ও নফল রোজা", "en": "Sunnah and voluntary fasts"}}, {"type": "table", "head": [{"bn": "রোজা", "en": "Fast"}, {"bn": "ফজিলত", "en": "Virtue"}, {"bn": "সূত্র", "en": "Source"}], "rows": [[{"bn": "শাওয়ালের ছয় রোজা", "en": "Six days of Shawwal"}, {"bn": "রমজানের পর ছয়টি রাখলে সারা বছর রোজার সমান; একটানা বা আলাদা দুইভাবেই রাখা যায়", "en": "With Ramadan, like fasting the whole year; may be kept consecutively or spread out"}, {"bn": "সহিহ মুসলিম ১১৬৪", "en": "Sahih Muslim 1164"}], [{"bn": "আরাফার দিন (৯ জিলহজ)", "en": "Day of Arafah (9 Dhul Hijjah)"}, {"bn": "আগের ও পরের এক বছরের গুনাহের কাফফারা হওয়ার আশা", "en": "Hoped to expiate the sins of the year before and the year after"}, {"bn": "সহিহ মুসলিম ১১৬২", "en": "Sahih Muslim 1162"}], [{"bn": "আশুরা (১০ মুহাররম)", "en": "Ashura (10 Muharram)"}, {"bn": "আগের এক বছরের গুনাহের কাফফারা হওয়ার আশা; সঙ্গে ৯ তারিখও রাখা সুন্নত", "en": "Hoped to expiate the previous year; fasting the 9th with it is sunnah"}, {"bn": "সহিহ মুসলিম ১১৬২, ১১৩৪", "en": "Sahih Muslim 1162, 1134"}], [{"bn": "সোমবার ও বৃহস্পতিবার", "en": "Mondays and Thursdays"}, {"bn": "এ দুই দিনে আমল আল্লাহর কাছে পেশ করা হয়; সোমবার নবী (সা.)-এর জন্মদিন", "en": "Deeds are presented to Allah on these days; Monday is the day the Prophet was born"}, {"bn": "সহিহ মুসলিম ১১৬২; জামে তিরমিজি ৭৪৭", "en": "Sahih Muslim 1162; Jami'' at-Tirmidhi 747"}], [{"bn": "আইয়ামে বিজ (চান্দ্রমাসের ১৩, ১৪, ১৫)", "en": "White Days (13th, 14th, 15th of each lunar month)"}, {"bn": "প্রতি মাসে তিন রোজা সারা বছর রোজার মতো", "en": "Three days each month are like fasting all year"}, {"bn": "সহিহ বুখারি ১৯৮১; জামে তিরমিজি ৭৬১", "en": "Sahih al-Bukhari 1981; Jami'' at-Tirmidhi 761"}], [{"bn": "মুহাররম মাস", "en": "The month of Muharram"}, {"bn": "রমজানের পর সর্বোত্তম রোজা আল্লাহর মাস মুহাররমের রোজা", "en": "The best fasting after Ramadan is in Allah''s month, Muharram"}, {"bn": "সহিহ মুসলিম ১১৬৩", "en": "Sahih Muslim 1163"}], [{"bn": "শাবান মাস", "en": "The month of Sha''ban"}, {"bn": "নবী (সা.) রমজানের পর শাবানেই সবচেয়ে বেশি রোজা রাখতেন", "en": "After Ramadan the Prophet fasted most in Sha''ban"}, {"bn": "সহিহ বুখারি ১৯৬৯", "en": "Sahih al-Bukhari 1969"}]]}, {"type": "note", "tone": "info", "text": {"bn": "হজে থাকা ব্যক্তির জন্য আরাফার দিনে রোজা না রাখাই সুন্নত; নবী (সা.) আরাফায় রোজা রাখেননি, যাতে দোয়া ও ইবাদতে শক্তি থাকে।", "en": "For someone performing hajj, not fasting on the day of Arafah is the sunnah; the Prophet did not fast at Arafah, keeping his strength for dua and worship."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি (উম্মুল ফজল রা.-এর বর্ণনা: আরাফায় নবী সা.-কে দুধ পাঠানো)", "en": "Sahih al-Bukhari (Umm al-Fadl''s report of sending milk to the Prophet at Arafah)"}, "check": true}, {"type": "note", "tone": "tip", "text": {"bn": "নফল রোজা রেখে কোনো কারণে ভেঙে ফেললে হানাফি মতে পরে একটি কাজা করতে হয়; শাফেয়ি ও হাম্বলি মতে কাজা জরুরি নয়, তবে উত্তম।", "en": "If a voluntary fast is broken for some reason, Hanafis require one make-up day; Shafi''is and Hanbalis say it is not required but recommended."}}, {"type": "heading", "text": {"bn": "যেসব দিনে রোজা রাখা নিষেধ", "en": "Days on which fasting is forbidden"}}, {"type": "table", "head": [{"bn": "দিন", "en": "Day"}, {"bn": "হুকুম", "en": "Ruling"}], "rows": [[{"bn": "ঈদুল ফিতরের দিন (১ শাওয়াল)", "en": "Eid al-Fitr (1 Shawwal)"}, {"bn": "হারাম", "en": "Forbidden (haram)"}], [{"bn": "ঈদুল আজহার দিন (১০ জিলহজ)", "en": "Eid al-Adha (10 Dhul Hijjah)"}, {"bn": "হারাম", "en": "Forbidden (haram)"}], [{"bn": "আইয়ামে তাশরিক (১১, ১২, ১৩ জিলহজ)", "en": "Days of Tashriq (11, 12, 13 Dhul Hijjah)"}, {"bn": "নিষেধ; এগুলো খাওয়া-দাওয়া ও আল্লাহর জিকিরের দিন (হাদি জোগাড় করতে না পারা তামাত্তু হাজির জন্য কিছু মাজহাবে ছাড় আছে)", "en": "Forbidden; these are days of eating, drinking and remembering Allah (some madhhabs make an exception for a tamattu'' pilgrim who finds no sacrificial animal)"}], [{"bn": "শুধু জুমার দিনকে আলাদা করে রোজা", "en": "Singling out Friday alone for fasting"}, {"bn": "মাকরুহ; আগের বা পরের দিনসহ রাখলে সমস্যা নেই", "en": "Disliked; fine if joined with the day before or after"}], [{"bn": "সন্দেহের দিন (শাবানের ৩০ তারিখ, চাঁদ নিয়ে সন্দেহ হলে) রমজানের সতর্কতায়", "en": "The day of doubt (30 Sha''ban when the moon is unclear) as a precaution for Ramadan"}, {"bn": "মাকরুহ / নিষেধ; রমজানের এক-দুই দিন আগে থেকে রোজা শুরু করবেন না, তবে নিয়মিত অভ্যাসের রোজা হলে ভিন্ন কথা", "en": "Disliked / forbidden; do not start fasting a day or two before Ramadan, unless it is a regular habitual fast"}], [{"bn": "সারা বছর বিরতিহীন রোজা", "en": "Fasting every day of the year without break"}, {"bn": "নিষেধ", "en": "Forbidden"}], [{"bn": "স্বামী উপস্থিত থাকলে তার অনুমতি ছাড়া স্ত্রীর নফল রোজা", "en": "A wife''s voluntary fast without her husband''s permission when he is present"}, {"bn": "নিষেধ", "en": "Forbidden"}]]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৯৯০; সহিহ মুসলিম ১১৩৭; সহিহ মুসলিম ১১৪১; সহিহ বুখারি ১৯৮৫; সহিহ মুসলিম ১১৪৪; সহিহ বুখারি ১৯১৪; সহিহ বুখারি ১৯৭৭; সহিহ বুখারি ৫১৯৫", "en": "Sahih al-Bukhari 1990; Sahih Muslim 1137; Sahih Muslim 1141; Sahih al-Bukhari 1985; Sahih Muslim 1144; Sahih al-Bukhari 1914; Sahih al-Bukhari 1977; Sahih al-Bukhari 5195"}}]', 'in_review', 80 FROM is_guide_topics WHERE slug = 'sawm' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '5d1955e8-d8f8-5f41-9de3-c7d40af47f17', id, 'zakat-basics', '{"bn": "যাকাত: কার ওপর ফরজ", "en": "Zakat: who must pay"}', '{"bn": "যাকাত ইসলামের তৃতীয় স্তম্ভ। কোন শর্তে যাকাত ফরজ হয় এবং কেন এটি সম্পদকে পবিত্র করে।", "en": "Zakat is the third pillar of Islam. The conditions that make it due and how it purifies wealth."}', 'basic', '[{"type": "arabic", "ar": "وَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ", "pron": {"bn": "ওয়া আকীমুস সালাতা ওয়া আতুয যাকাহ", "en": "Wa aqimus-salata wa atuz-zakah"}, "meaning": {"bn": "আর নামাজ কায়েম করো এবং যাকাত দাও।", "en": "And establish the prayer and give the zakat."}, "ref": {"bn": "সূরা বাকারা ২:৪৩", "en": "Al-Baqarah 2:43"}}, {"type": "text", "text": {"bn": "যাকাত মানে পবিত্রতা ও বৃদ্ধি। নির্দিষ্ট পরিমাণ সম্পদ এক বছর মালিকানায় থাকলে তার একটি নির্ধারিত অংশ (সাধারণত ২.৫%) কুরআনে বর্ণিত হকদারদের দিয়ে দেওয়াই যাকাত। নবী (সা.) বলেছেন, ইসলাম পাঁচটি স্তম্ভের ওপর প্রতিষ্ঠিত, তার একটি যাকাত দেওয়া।", "en": "Zakat means purification and growth. When a set amount of wealth has been owned for a year, a fixed share of it (usually 2.5%) is given to the recipients named in the Quran. The Prophet said Islam is built on five pillars, one of which is giving zakat."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৮; সহিহ মুসলিম ১৬", "en": "Sahih al-Bukhari 8; Sahih Muslim 16"}}, {"type": "arabic", "ar": "خُذْ مِنْ أَمْوَالِهِمْ صَدَقَةً تُطَهِّرُهُمْ وَتُزَكِّيهِمْ بِهَا", "pron": {"bn": "খুয মিন আমওয়ালিহিম সাদাকাতান তুতাহহিরুহুম ওয়া তুযাক্কীহিম বিহা", "en": "Khudh min amwalihim sadaqatan tutahhiruhum wa tuzakkihim biha"}, "meaning": {"bn": "তাদের সম্পদ থেকে সদকা গ্রহণ করো, যা দিয়ে তুমি তাদের পবিত্র ও পরিশুদ্ধ করবে।", "en": "Take from their wealth a charity by which you purify them and cause them to grow."}, "ref": {"bn": "সূরা তাওবা ৯:১০৩", "en": "At-Tawbah 9:103"}}, {"type": "heading", "text": {"bn": "যাকাত ফরজ হওয়ার শর্ত", "en": "Conditions for zakat to be due"}}, {"type": "list", "items": [{"bn": "মুসলিম হওয়া", "en": "Being Muslim"}, {"bn": "নিসাব পরিমাণ যাকাতযোগ্য সম্পদের মালিক হওয়া (নিসাবের বিস্তারিত পরের গাইডে)", "en": "Owning zakatable wealth of at least the nisab (details in the next guide)"}, {"bn": "সম্পদের পূর্ণ মালিকানা থাকা", "en": "Full ownership of the wealth"}, {"bn": "সম্পদ মৌলিক প্রয়োজন (থাকার ঘর, পরিধেয় কাপড়, ব্যবহারের আসবাব, যানবাহন ইত্যাদি) ও আদায়যোগ্য ঋণের অতিরিক্ত হওয়া", "en": "The wealth being beyond basic needs (home, clothes, household items, personal vehicle) and debts due"}, {"bn": "নিসাব পরিমাণ সম্পদের ওপর চান্দ্রবছর (হাওল) পূর্ণ হওয়া", "en": "A full lunar year (hawl) passing on the nisab amount"}, {"bn": "প্রাপ্তবয়স্ক ও সুস্থ মস্তিষ্কের হওয়া (হানাফি মতে)", "en": "Being adult and sane (Hanafi view)"}]}, {"type": "differ", "title": {"bn": "শিশু ও মানসিক প্রতিবন্ধীর সম্পদে যাকাত", "en": "Zakat on the wealth of children and the insane"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "নাবালেগ ও পাগলের সম্পদে যাকাত ফরজ নয় (তবে তাদের জমির ফসলে উশর আছে)।", "en": "No zakat is due on the wealth of a minor or an insane person (though ushr is due on their crops)."}, "evidence": {"bn": "যাকাত একটি ইবাদত, আর তারা ইবাদতের জন্য দায়িত্বপ্রাপ্ত নয়।", "en": "Zakat is an act of worship and they are not legally responsible for worship."}}, {"label": {"bn": "শাফেয়ি, মালেকি, হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "তাদের সম্পদেও যাকাত ফরজ; অভিভাবক আদায় করবেন।", "en": "Zakat is due on their wealth too; the guardian pays it."}, "evidence": {"bn": "যাকাত সম্পদের হক; উমর (রা.) ও আয়েশা (রা.) ইয়াতিমের সম্পদ থেকে যাকাত দিতেন বলে বর্ণিত।", "en": "Zakat is a right on the wealth; Umar and Aishah are reported to have paid zakat from orphans'' wealth."}}]}, {"type": "note", "tone": "warn", "text": {"bn": "যাকাত না দেওয়ার পরিণতি ভয়াবহ। যারা সোনা-রূপা জমিয়ে রাখে আর আল্লাহর পথে খরচ করে না, কুরআনে তাদের যন্ত্রণাদায়ক শাস্তির কথা বলা হয়েছে।", "en": "The consequence of withholding zakat is severe. The Quran warns those who hoard gold and silver and do not spend it in the way of Allah of a painful punishment."}}, {"type": "ref", "text": {"bn": "সূরা তাওবা ৯:৩৪; সূরা তাওবা ৯:৩৫", "en": "At-Tawbah 9:34; At-Tawbah 9:35"}}, {"type": "note", "tone": "tip", "text": {"bn": "এই অ্যাপে একটি যাকাত ক্যালকুলেটর আছে। নিচের গাইডগুলো পড়ে নিয়ম বুঝে নিন, তারপর ক্যালকুলেটরে নিজের সম্পদের হিসাব বসান।", "en": "This app has a zakat calculator. Read these guides to understand the rules, then enter your own figures in the calculator."}}]', 'in_review', 10 FROM is_guide_topics WHERE slug = 'zakat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'af60c109-647d-50a8-9de4-57300a2dd79a', id, 'zakat-nisab-hawl', '{"bn": "নিসাব ও এক বছর (হাওল)", "en": "Nisab and the zakat year (hawl)"}', '{"bn": "কতটুকু সম্পদ থাকলে যাকাত ফরজ হয়, সোনা না রূপার নিসাব ধরবেন, আর বছর কীভাবে গণনা করবেন।", "en": "How much wealth makes zakat due, whether to use the gold or silver nisab, and how the year is counted."}', 'basic', '[{"type": "heading", "text": {"bn": "নিসাব কী", "en": "What is nisab"}}, {"type": "text", "text": {"bn": "নিসাব হলো সম্পদের সেই ন্যূনতম পরিমাণ, যার মালিক হলে যাকাত ফরজ হয়। হাদিসে সোনার নিসাব ২০ দিনার (মিসকাল) এবং রূপার নিসাব ২০০ দিরহাম (৫ উকিয়া) নির্ধারিত হয়েছে।", "en": "Nisab is the minimum amount of wealth that makes zakat due. The hadith sets the nisab of gold at 20 dinars (mithqal) and of silver at 200 dirhams (5 awqiyah)."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৯৭৯", "en": "Sahih Muslim 979"}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ (আলী রা.-এর বর্ণনা: ২০ দিনার ও এক বছর)", "en": "Sunan Abi Dawud (narration of Ali: 20 dinars and one year)"}, "check": true}, {"type": "table", "head": [{"bn": "সম্পদ", "en": "Asset"}, {"bn": "নিসাব (গ্রাম)", "en": "Nisab (grams)"}, {"bn": "ভরি/তোলা হিসাবে", "en": "In bhori/tola"}], "rows": [[{"bn": "সোনা", "en": "Gold"}, {"bn": "প্রায় ৮৫ গ্রাম", "en": "About 85 g"}, {"bn": "সাড়ে ৭ ভরি (প্রায় ৮৭.৪৮ গ্রাম)", "en": "7.5 bhori (about 87.48 g)"}], [{"bn": "রূপা", "en": "Silver"}, {"bn": "প্রায় ৫৯৫ গ্রাম", "en": "About 595 g"}, {"bn": "সাড়ে ৫২ ভরি (প্রায় ৬১২.৩৬ গ্রাম)", "en": "52.5 bhori (about 612.36 g)"}], [{"bn": "নগদ টাকা, ব্যবসায়িক পণ্য ও মিশ্র সম্পদ", "en": "Cash, trade goods and mixed assets"}, {"bn": "সোনা বা রূপার নিসাবের সমমূল্য (নিচের মতভেদ দেখুন)", "en": "The value of the gold or silver nisab (see the difference below)"}, {"bn": "—", "en": "—"}]]}, {"type": "note", "tone": "info", "text": {"bn": "গ্রামের হিসাবে সামান্য পার্থক্য আছে: আন্তর্জাতিকভাবে সাধারণত ৮৫ গ্রাম ও ৫৯৫ গ্রাম ধরা হয়, আর বাংলাদেশ-ভারতে প্রচলিত হিসাব সাড়ে ৭ ভরি ও সাড়ে ৫২ ভরি। যাকাতের তারিখে স্থানীয় বাজারদর দেখে টাকায় নিসাব নির্ণয় করুন।", "en": "The gram figures differ slightly: internationally 85 g and 595 g are common, while the usual reckoning in Bangladesh and India is 7.5 and 52.5 bhori. Work out the nisab in taka from the local market price on your zakat date."}}, {"type": "differ", "title": {"bn": "নগদ ও মিশ্র সম্পদে কোন নিসাব ধরবেন", "en": "Which nisab to use for cash and mixed wealth"}, "views": [{"label": {"bn": "রূপার নিসাব", "en": "Silver nisab"}, "text": {"bn": "টাকা, ব্যবসার পণ্য বা কয়েক ধরনের সম্পদ মিলে রূপার নিসাবের মূল্যে পৌঁছালেই যাকাত ফরজ। হানাফি মাজহাব ও বাংলাদেশের অধিকাংশ মুফতি এ মত দেন। এতে গরিবদের উপকার বেশি এবং সতর্কতাও বেশি।", "en": "Zakat is due once cash, trade goods or a mix of assets reach the value of the silver nisab. This is the Hanafi view and that of most muftis in Bangladesh; it benefits the poor more and is more cautious."}, "evidence": {"bn": "দুটি নিসাবের মধ্যে যেটি গরিবের জন্য বেশি উপকারী সেটিই ধরা উচিত; হানাফি মতে বিভিন্ন সম্পদ মূল্যের ভিত্তিতে একসাথে যোগ হয়।", "en": "Of the two nisabs, the one more beneficial to the poor should be used; Hanafis combine different assets by value."}}, {"label": {"bn": "সোনার নিসাব", "en": "Gold nisab"}, "text": {"bn": "বর্তমানে রূপার দাম অনেক কমে যাওয়ায় সমকালীন অনেক আলেম (যেমন ইউসুফ আল-কারযাভি) বলেন, টাকার নিসাব সোনার মূল্যে ধরা উচিত, যাতে সত্যিকারের সচ্ছল ব্যক্তির ওপরই যাকাত আসে।", "en": "Because silver has lost much of its value, many contemporary scholars (e.g. Yusuf al-Qaradawi) say the cash nisab should be set by gold, so that zakat falls on the genuinely well-off."}, "evidence": {"bn": "নবী (সা.)-এর যুগে ২০ দিনার ও ২০০ দিরহামের মূল্য প্রায় সমান ছিল; এখন সোনা সম্পদের স্থিতিশীল মাপকাঠি।", "en": "In the Prophet''s time 20 dinars and 200 dirhams were roughly equal in value; today gold is the more stable measure of wealth."}}]}, {"type": "note", "tone": "tip", "text": {"bn": "শুধু সোনা থাকলে (অন্য কোনো যাকাতযোগ্য সম্পদ, এমনকি সামান্য নগদও নেই) তাহলে সোনার নিসাবই প্রযোজ্য। কিন্তু সোনার সাথে কিছু নগদ টাকা বা রূপা থাকলেই হানাফি মতে সব মিলিয়ে রূপার নিসাবে হিসাব হবে।", "en": "If you own only gold (no other zakatable asset, not even a little cash), the gold nisab applies. But in the Hanafi view, once there is some cash or silver with the gold, everything is combined and measured against the silver nisab."}}, {"type": "heading", "text": {"bn": "এক বছর (হাওল)", "en": "The year (hawl)"}}, {"type": "list", "items": [{"bn": "যেদিন প্রথম নিসাব পরিমাণ সম্পদের মালিক হয়েছেন, চান্দ্রমাসের সেই তারিখই আপনার যাকাতের তারিখ। পরের বছর ওই তারিখে হিসাব করবেন।", "en": "The lunar date on which you first owned the nisab is your zakat date; calculate on that date each following year."}, {"bn": "যাকাতের বছর চান্দ্রবছর (হিজরি)। ইংরেজি বছর ধরে হিসাব করলে অনেক আলেম ২.৫%-এর বদলে প্রায় ২.৫৭৭% দিতে বলেন।", "en": "The zakat year is lunar (Hijri). If you calculate on the solar year, many scholars advise about 2.577% instead of 2.5%."}, {"bn": "ফসল, ফল ও খনিজে বছর লাগে না; তোলার সময়ই দিতে হয়।", "en": "Crops, fruit and minerals need no year; their due is paid at harvest."}]}, {"type": "differ", "title": {"bn": "বছরের মাঝে সম্পদ কমে গেলে বা নতুন আয় হলে", "en": "When wealth drops or new income arrives during the year"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "বছরের শুরু ও শেষে নিসাব পূর্ণ থাকলেই যথেষ্ট; মাঝে কমে গেলেও (একেবারে শূন্য না হলে) ক্ষতি নেই। বছরের মাঝে যে নতুন টাকা আসে (বেতন, লাভ, উপহার), তার জন্য আলাদা বছর লাগে না; যাকাতের তারিখে যা আছে, সবকিছুর যাকাত দেবেন।", "en": "It is enough that the nisab is complete at the start and end of the year; dropping below it in between does not matter (unless it falls to nothing). New money during the year (salary, profit, gifts) needs no separate year; pay on everything you hold on the zakat date."}, "evidence": {"bn": "প্রতিটি আয়ের আলাদা বছর হিসাব করা মানুষের জন্য কঠিন; একই জাতের সম্পদ মূল সম্পদের সঙ্গে যুক্ত হয়।", "en": "Tracking a separate year for every receipt would be a hardship; wealth of the same kind joins the original holding."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি", "en": "Shafi''i and Hanbali"}, "text": {"bn": "পুরো বছর জুড়ে নিসাব থাকতে হবে; মাঝে নিসাবের নিচে নামলে নতুন করে বছর শুরু। নতুন আয়ের প্রতিটির জন্য আলাদা বছর গণনা হবে (ব্যবসার লাভ ছাড়া), তবে সহজতার জন্য আগেভাগে সবটার যাকাত দিয়ে দেওয়া যায়।", "en": "The nisab must be held throughout the year; if it falls below, the year restarts. Each new receipt has its own year (except trading profit), though one may pay on everything early for simplicity."}, "evidence": {"bn": "হাদিস: ''বছর পূর্ণ না হওয়া পর্যন্ত কোনো সম্পদে যাকাত নেই।''", "en": "Hadith: ''No zakat is due on wealth until a year has passed over it.''"}}]}, {"type": "note", "tone": "tip", "text": {"bn": "বছর পূর্ণ হওয়ার আগে অগ্রিম যাকাত দেওয়া হানাফি, শাফেয়ি ও হাম্বলি মতে জায়েজ; নবী (সা.) আব্বাস (রা.)-এর কাছ থেকে অগ্রিম যাকাত নিয়েছিলেন বলে বর্ণিত।", "en": "Paying zakat in advance before the year ends is allowed by the Hanafi, Shafi''i and Hanbali schools; the Prophet is reported to have accepted Abbas''s zakat in advance."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ; জামে তিরমিজি (আব্বাস রা.-এর অগ্রিম যাকাত)", "en": "Sunan Abi Dawud; Jami'' at-Tirmidhi (Abbas paying zakat in advance)"}, "check": true}]', 'in_review', 20 FROM is_guide_topics WHERE slug = 'zakat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '2e39a327-58bb-5551-b19e-0590ce80832a', id, 'zakat-assets', '{"bn": "কোন কোন সম্পদে যাকাত", "en": "Which assets are zakatable"}', '{"bn": "নগদ টাকা, সোনা-রূপা, ব্যবসার পণ্য, শেয়ার, পাওনা টাকা, ফসলের উশর ও গবাদিপশু; আর কোন সম্পদে যাকাত নেই।", "en": "Cash, gold and silver, trade goods, shares, money owed to you, ushr on crops and livestock; and what is not zakatable."}', 'detail', '[{"type": "heading", "text": {"bn": "নগদ টাকা ও সঞ্চয়", "en": "Cash and savings"}}, {"type": "text", "text": {"bn": "হাতের নগদ, ব্যাংক হিসাব, মোবাইল ব্যাংকিং, এফডিআর, সঞ্চয়পত্র, বিদেশি মুদ্রা, ডিপিএস-এ জমা টাকা — সবই যাকাতের হিসাবে আসবে। সুদ বা অবৈধ আয়ের টাকা যাকাতের অংশ নয়; সেটি সওয়াবের নিয়ত ছাড়া পুরোটাই গরিবকে দিয়ে দিতে হবে।", "en": "Cash in hand, bank accounts, mobile wallets, fixed deposits, savings certificates, foreign currency and deposit schemes all count. Interest or unlawful income is not part of zakat; all of it must be given away to the poor without expecting reward."}}, {"type": "heading", "text": {"bn": "সোনা ও রূপা", "en": "Gold and silver"}}, {"type": "text", "text": {"bn": "সোনা-রূপার গয়না, বার বা কয়েনের যাকাত দিতে হবে যাকাতের তারিখের বাজারদর (বিক্রয়মূল্য) অনুযায়ী। পাথর বা অন্য ধাতু বাদ দিয়ে শুধু সোনা-রূপার ওজন ধরবেন। হীরা, মুক্তা বা প্ল্যাটিনামের গয়না ব্যক্তিগত ব্যবহারের হলে যাকাত নেই; ব্যবসার জন্য হলে আছে।", "en": "Gold and silver jewellery, bars and coins are zakatable at the market (sale) value on the zakat date. Count only the gold or silver weight, excluding stones and other metals. Diamond, pearl or platinum jewellery for personal use is not zakatable; if held for trade, it is."}}, {"type": "differ", "title": {"bn": "ব্যবহারের গয়নায় যাকাত", "en": "Zakat on jewellery that is worn"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "নারীর ব্যবহারের সোনা-রূপার গয়নাতেও যাকাত ফরজ।", "en": "Zakat is due even on gold and silver jewellery a woman wears."}, "evidence": {"bn": "এক নারীর মেয়ের হাতে সোনার মোটা কাঁকন দেখে নবী (সা.) জিজ্ঞেস করেন তার যাকাত দেওয়া হয় কি না (আবু দাউদ); এবং সোনা-রূপা জমানোর আয়াতের ব্যাপকতা।", "en": "The Prophet, seeing thick gold bangles on a woman''s daughter, asked whether their zakat was paid (Abu Dawud); and the general verse on hoarding gold and silver."}}, {"label": {"bn": "শাফেয়ি, মালেকি, হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "স্বাভাবিক পরিমাণে ব্যবহারের জন্য রাখা জায়েজ গয়নায় যাকাত নেই; সঞ্চয় বা বিনিয়োগের জন্য রাখা গয়নায় আছে।", "en": "No zakat on lawful jewellery kept in normal amounts for wearing; jewellery kept as savings or investment is zakatable."}, "evidence": {"bn": "আয়েশা (রা.), জাবির (রা.), ইবনে উমর (রা.)সহ কয়েকজন সাহাবির আমল: তারা পরিবারের ব্যবহারের গয়নার যাকাত দিতেন না।", "en": "The practice of Companions such as Aishah, Jabir and Ibn Umar, who did not pay zakat on the jewellery their families wore."}}], "check": true}, {"type": "heading", "text": {"bn": "ব্যবসার পণ্য", "en": "Trade goods"}}, {"type": "text", "text": {"bn": "বিক্রির উদ্দেশ্যে রাখা সব পণ্য (দোকানের মাল, গুদামের স্টক, বিক্রির জন্য কেনা জমি বা ফ্ল্যাট) যাকাতের তারিখের বাজারদরে হিসাব করে যাকাত দেবেন। দোকানঘর, আসবাব, মেশিন ও গাড়ির মতো স্থায়ী সম্পদে যাকাত নেই, তবে সেগুলো থেকে আসা আয় জমা থাকলে তাতে আছে।", "en": "All goods held for sale (shop stock, warehouse inventory, land or flats bought to resell) are valued at the market price on the zakat date. Fixed assets such as the shop premises, furniture, machines and vehicles are not zakatable, though the income from them is once saved."}}, {"type": "heading", "text": {"bn": "শেয়ার ও বিনিয়োগ", "en": "Shares and investments"}}, {"type": "differ", "title": {"bn": "শেয়ারের যাকাত", "en": "Zakat on shares"}, "views": [{"label": {"bn": "কেনাবেচার জন্য রাখা শেয়ার", "en": "Shares held for trading"}, "text": {"bn": "দাম বাড়লে বিক্রির উদ্দেশ্যে কেনা শেয়ার ব্যবসার পণ্যের মতো; যাকাতের তারিখে পুরো বাজারমূল্যের ২.৫% দিতে হবে। এ বিষয়ে সমকালীন আলেমরা প্রায় একমত।", "en": "Shares bought to sell at a profit are like trade goods: 2.5% of the full market value on the zakat date. Contemporary scholars broadly agree on this."}, "evidence": {"bn": "ব্যবসার পণ্যে যাকাতের সাধারণ বিধান।", "en": "The general ruling on trade goods."}}, {"label": {"bn": "দীর্ঘমেয়াদি বিনিয়োগ (লভ্যাংশের জন্য)", "en": "Long-term investment (for dividends)"}, "text": {"bn": "এক মত: কোম্পানির নগদ, পাওনা ও পণ্যের মতো যাকাতযোগ্য সম্পদে আপনার অংশ হিসাব করে তার যাকাত দেবেন (জানা না গেলে বাজারমূল্যের ওপর দেওয়াই সতর্কতা)। আরেক মত: পুরো বাজারমূল্যের ওপরই যাকাত। লভ্যাংশ হাতে এলে তা নগদের সঙ্গে যোগ হবে।", "en": "One view: pay on your share of the company''s zakatable assets (cash, receivables, inventory); if that is unknown, paying on market value is the safe course. Another view: pay on the full market value. Dividends received join your cash."}, "evidence": {"bn": "শেয়ার কোম্পানির সম্পদের মালিকানার অংশ; স্থায়ী সম্পদে যাকাত নেই — ইসলামিক ফিকহ একাডেমির মতো সংস্থার আলোচনা।", "en": "A share is part-ownership of the company''s assets, and fixed assets are not zakatable — as discussed by bodies such as the Islamic Fiqh Academy."}}]}, {"type": "heading", "text": {"bn": "পাওনা টাকা ও ঋণ", "en": "Money owed to you and your debts"}}, {"type": "list", "items": [{"bn": "যে পাওনা ফেরত পাওয়ার আশা আছে, তার যাকাতও দিতে হবে; প্রতি বছর দিয়ে দেওয়া সহজ। হানাফি মতে চাইলে টাকা হাতে পাওয়ার পর বিগত বছরগুলোর যাকাত একসাথে দেওয়া যায়।", "en": "Money owed to you that you expect to recover is zakatable; paying each year is simplest. Hanafis allow paying for the past years together once it is received."}, {"bn": "যে পাওনা ফেরত পাওয়ার আশা নেই, তাতে যাকাত নেই; পরে পেলে হানাফি মতে পাওয়ার পর থেকে হিসাব।", "en": "Money you do not expect to recover is not zakatable; if later recovered, Hanafis count from receipt."}, {"bn": "আপনার নিজের যে ঋণ এখন পরিশোধ করতে হবে (বা এ বছরের কিস্তি), হানাফি ও হাম্বলি মতে তা বাদ দিয়ে হিসাব করবেন; দীর্ঘমেয়াদি ঋণের পুরোটা একবারে বাদ দেওয়া যায় না। শাফেয়ি মতে ঋণ বাদ যায় না।", "en": "Debts you must pay now (or this year''s instalments) are deducted in the Hanafi and Hanbali view; the whole of a long-term loan is not deducted at once. Shafi''is do not deduct debts."}, {"bn": "প্রভিডেন্ট ফান্ড: যে অংশ এখনও তোলার অধিকার নেই, অনেক আলেমের মতে তা হাতে পাওয়ার পর থেকে হিসাব হবে; স্বেচ্ছায় জমা অংশ ও তোলার অধিকার আছে এমন অংশে যাকাত দেওয়াই সতর্কতা।", "en": "Provident fund: many scholars say the part you cannot yet withdraw is counted from when you receive it; voluntary contributions and withdrawable balances should be included to be safe."}]}, {"type": "heading", "text": {"bn": "যেসব সম্পদে যাকাত নেই", "en": "What is not zakatable"}}, {"type": "list", "items": [{"bn": "বসবাসের বাড়ি, ব্যবহারের গাড়ি, আসবাব, পোশাক ও গৃহস্থালি জিনিস", "en": "The home you live in, personal car, furniture, clothes and household goods"}, {"bn": "ভাড়া দেওয়া বাড়ি-দোকান (তবে ভাড়ার জমানো টাকায় যাকাত আছে)", "en": "Property rented out (but saved rental income is zakatable)"}, {"bn": "নিজে বাড়ি করার জন্য কেনা জমি (বিক্রির নিয়তে কিনলে যাকাত আছে)", "en": "Land bought to build your own home (land bought to resell is zakatable)"}, {"bn": "পেশার যন্ত্রপাতি ও কাজের বই", "en": "Tools of one''s trade and working books"}]}, {"type": "heading", "text": {"bn": "ফসলের যাকাত (উশর)", "en": "Zakat on crops (ushr)"}}, {"type": "text", "text": {"bn": "বৃষ্টি বা প্রাকৃতিক পানিতে উৎপন্ন ফসলে উৎপাদনের ১০% (উশর), আর সেচ দিয়ে উৎপন্ন ফসলে ৫% (নিসফে উশর) দিতে হয়। এতে বছর পূর্ণ হওয়া লাগে না; ফসল তোলার সময়ই দেবেন।", "en": "Crops watered by rain or natural sources owe 10% of the harvest (ushr); crops watered by irrigation owe 5%. No year is needed; it is paid at harvest."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৪৮৩", "en": "Sahih al-Bukhari 1483"}}, {"type": "differ", "title": {"bn": "উশরের নিসাব", "en": "Nisab for ushr"}, "views": [{"label": {"bn": "ইমাম আবু হানিফা", "en": "Imam Abu Hanifa"}, "text": {"bn": "কম-বেশি যে পরিমাণ ফসলই হোক, উশর দিতে হবে; কোনো নিসাব নেই।", "en": "Ushr is due on any amount of produce, however small; there is no nisab."}, "evidence": {"bn": "''যা বৃষ্টিতে সিক্ত হয় তাতে উশর'' হাদিসটি ব্যাপক, পরিমাণের শর্ত নেই।", "en": "The hadith ''what is watered by rain owes a tenth'' is general, with no minimum."}}, {"label": {"bn": "অধিকাংশ আলেম (আবু ইউসুফ, মুহাম্মদসহ)", "en": "Majority (incl. Abu Yusuf and Muhammad)"}, "text": {"bn": "পাঁচ ওয়াসাক (প্রায় ৬৫০ কেজি) বা তার বেশি সংরক্ষণযোগ্য শস্য হলেই উশর।", "en": "Ushr is due only once storable grain reaches five awsuq (about 650 kg)."}, "evidence": {"bn": "হাদিস: ''পাঁচ ওয়াসাকের কম শস্যে সদকা নেই।''", "en": "Hadith: ''There is no charity on less than five awsuq.''"}}]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৯৭৯", "en": "Sahih Muslim 979"}}, {"type": "heading", "text": {"bn": "গবাদিপশু (সংক্ষেপে)", "en": "Livestock (briefly)"}}, {"type": "text", "text": {"bn": "যে গরু, মহিষ, উট, ছাগল ও ভেড়া বছরের বেশির ভাগ সময় মুক্ত চারণভূমিতে চরে খায় (সায়িমা), তাতে যাকাত আছে। যেমন: ৪০–১২০টি ছাগল/ভেড়ায় ১টি; ৩০টি গরু/মহিষে এক বছর বয়সী ১টি বাছুর, ৪০টিতে দুই বছর বয়সী ১টি; ৫টি উটে ১টি ছাগল। খামারে কিনে খাওয়ানো পশু ব্যবসার জন্য হলে ব্যবসার পণ্য হিসেবে মূল্যের ২.৫% দিতে হবে।", "en": "Cattle, buffalo, camels, goats and sheep that graze freely for most of the year (sa''imah) owe zakat. For example: 1 for 40–120 goats/sheep; a one-year calf for 30 cattle and a two-year one for 40; a goat for 5 camels. Farm animals fed on bought fodder and raised for sale are trade goods at 2.5% of value."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি (আবু বকর রা.-এর যাকাত-পত্র); সুনান আবু দাউদ (মুয়াজ রা.-এর বর্ণনা)", "en": "Sahih al-Bukhari (Abu Bakr''s letter on zakat); Sunan Abi Dawud (narration of Mu''adh)"}, "check": true}, {"type": "note", "tone": "info", "text": {"bn": "পশুর যাকাতের পূর্ণ তালিকা দীর্ঘ; এমন খামার থাকলে নির্ভরযোগ্য আলেমের কাছ থেকে বিস্তারিত জেনে নিন।", "en": "The full livestock tables are long; if you own such herds, get the details from a reliable scholar."}}]', 'in_review', 30 FROM is_guide_topics WHERE slug = 'zakat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '2a51f1ae-181b-5481-b2d8-b4c41f536007', id, 'zakat-calculation', '{"bn": "যাকাত হিসাব করার নিয়ম", "en": "How to calculate zakat"}', '{"bn": "ধাপে ধাপে যাকাতের হিসাব এবং টাকায় একটি উদাহরণ।", "en": "Step-by-step zakat calculation with a worked example in taka."}', 'basic', '[{"type": "step", "title": {"bn": "যাকাতের তারিখ ঠিক করুন", "en": "Fix your zakat date"}, "text": {"bn": "যে হিজরি তারিখে প্রথম নিসাবের মালিক হয়েছিলেন, সেটিই আপনার যাকাতের তারিখ। মনে না থাকলে আনুমানিক একটি তারিখ (যেমন রমজানের কোনো দিন) ঠিক করে প্রতি বছর সেদিন হিসাব করুন।", "en": "Your zakat date is the Hijri date you first owned the nisab. If you do not remember, fix a reasonable date (e.g. a day in Ramadan) and calculate on it every year."}}, {"type": "step", "title": {"bn": "যাকাতযোগ্য সম্পদ যোগ করুন", "en": "Add up zakatable assets"}, "text": {"bn": "ওই দিনের হিসাবে নগদ, ব্যাংক, সঞ্চয়, সোনা-রূপার বাজারমূল্য, ব্যবসার পণ্যের মূল্য, শেয়ার ও ফেরতযোগ্য পাওনা যোগ করুন।", "en": "On that date add cash, bank balances, savings, the market value of gold and silver, the value of trade stock, shares and recoverable money owed to you."}}, {"type": "step", "title": {"bn": "আদায়যোগ্য ঋণ বাদ দিন", "en": "Deduct debts now due"}, "text": {"bn": "এখন পরিশোধ করতে হবে এমন ঋণ, বকেয়া বিল ও এ বছরের কিস্তি বাদ দিন (হানাফি মত)।", "en": "Deduct debts you must pay now, unpaid bills and this year''s instalments (Hanafi view)."}}, {"type": "step", "title": {"bn": "নিসাবের সাথে মিলান", "en": "Compare with the nisab"}, "text": {"bn": "বাকি অঙ্ক যদি নিসাবের মূল্যের (আজকের দামে) সমান বা বেশি হয়, তাহলে যাকাত ফরজ।", "en": "If what remains is equal to or above the nisab value (at today''s price), zakat is due."}}, {"type": "step", "title": {"bn": "২.৫% বের করুন", "en": "Take 2.5%"}, "text": {"bn": "নিট সম্পদকে ৪০ দিয়ে ভাগ করুন, অথবা ২.৫% হিসাব করুন। যাকাত নিসাবের ওপরের অংশে নয়, পুরো নিট সম্পদের ওপর।", "en": "Divide net wealth by 40, i.e. take 2.5%. Zakat is on the whole net amount, not only the part above the nisab."}}, {"type": "step", "title": {"bn": "নিয়ত করে আদায় করুন", "en": "Pay with intention"}, "text": {"bn": "যাকাতের নিয়তে (মনে মনে) হকদারকে দিন। প্রাপককে ''যাকাত'' বলে জানানো জরুরি নয়। হিসাব লিখে রাখুন।", "en": "Give it to eligible recipients with the intention of zakat in your heart. You need not tell the recipient it is zakat. Keep a record."}}, {"type": "heading", "text": {"bn": "উদাহরণ", "en": "Worked example"}}, {"type": "text", "text": {"bn": "রহিম সাহেবের যাকাতের তারিখে সম্পদ নিচের মতো। (দামগুলো শুধু উদাহরণের জন্য; আসল হিসাবে সেদিনের বাজারদর বসাবেন।)", "en": "Mr Rahim''s assets on his zakat date are below. (Values are only for illustration; use the actual market prices on your date.)"}}, {"type": "table", "head": [{"bn": "খাত", "en": "Item"}, {"bn": "টাকা", "en": "Taka"}], "rows": [[{"bn": "হাতে ও ব্যাংকে নগদ", "en": "Cash in hand and bank"}, {"bn": "১,৫০,০০০", "en": "150,000"}], [{"bn": "সঞ্চয়পত্র ও এফডিআর", "en": "Savings certificates and FDR"}, {"bn": "২,০০,০০০", "en": "200,000"}], [{"bn": "স্ত্রীর গয়নার সোনা, সেদিনের বিক্রয়মূল্যে (ধরা যাক; মালিক স্ত্রী হলে হিসাব তার নামে হবে)", "en": "Gold jewellery at sale value that day (assumed; if it belongs to his wife, it is counted in her name)"}, {"bn": "৪,০০,০০০", "en": "400,000"}], [{"bn": "দোকানের বিক্রয়যোগ্য মাল", "en": "Shop stock for sale"}, {"bn": "৩,০০,০০০", "en": "300,000"}], [{"bn": "ফেরত পাওয়ার আশা আছে এমন পাওনা", "en": "Money owed to him, expected back"}, {"bn": "৫০,০০০", "en": "50,000"}], [{"bn": "মোট যাকাতযোগ্য সম্পদ", "en": "Total zakatable assets"}, {"bn": "১১,০০,০০০", "en": "1,100,000"}], [{"bn": "বাদ: এখন পরিশোধযোগ্য ঋণ ও এ বছরের কিস্তি", "en": "Less: debts and instalments due now"}, {"bn": "− ১,০০,০০০", "en": "− 100,000"}], [{"bn": "বাদ: বকেয়া বিল", "en": "Less: unpaid bills"}, {"bn": "− ২০,০০০", "en": "− 20,000"}], [{"bn": "নিট যাকাতযোগ্য সম্পদ", "en": "Net zakatable wealth"}, {"bn": "৯,৮০,০০০", "en": "980,000"}], [{"bn": "যাকাত (৯,৮০,০০০ × ২.৫%)", "en": "Zakat (980,000 × 2.5%)"}, {"bn": "২৪,৫০০", "en": "24,500"}]]}, {"type": "text", "text": {"bn": "নিট সম্পদ ৯,৮০,০০০ টাকা যদি সেদিনের নিসাবের মূল্যের চেয়ে বেশি হয় (রূপার নিসাবে সাধারণত হবে), তাহলে রহিম সাহেবের যাকাত ২৪,৫০০ টাকা।", "en": "If the net 980,000 taka is above that day''s nisab value (with the silver nisab it usually will be), Mr Rahim''s zakat is 24,500 taka."}}, {"type": "note", "tone": "info", "text": {"bn": "গয়না যার মালিকানায়, যাকাত তারই। স্ত্রীর গয়না স্ত্রীর সম্পদ; স্বামী চাইলে তার পক্ষ থেকে (তার অনুমতিতে) দিয়ে দিতে পারেন।", "en": "Zakat is on whoever owns the jewellery. A wife''s jewellery is her wealth; the husband may pay it for her with her permission."}}, {"type": "note", "tone": "tip", "text": {"bn": "এই অ্যাপের যাকাত ক্যালকুলেটরে খাতগুলো আলাদা করে বসালে হিসাব সহজ হবে। ক্যালকুলেটরের ফল একটি সহায়ক হিসাব; জটিল ব্যবসা বা সম্পদের ক্ষেত্রে আলেমের পরামর্শ নিন।", "en": "Entering each item separately in this app''s zakat calculator makes it easy. The calculator gives a helpful estimate; for complex businesses or holdings, consult a scholar."}}]', 'in_review', 40 FROM is_guide_topics WHERE slug = 'zakat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'f4f40b12-938a-54a9-ae1c-f90075105432', id, 'zakat-recipients', '{"bn": "যাকাত কাকে দেবেন, কাকে দেবেন না", "en": "Who receives zakat and who cannot"}', '{"bn": "কুরআনে বর্ণিত যাকাতের আট খাত এবং যাদের যাকাত দেওয়া যায় না।", "en": "The eight categories of zakat recipients in the Quran, and those who may not receive it."}', 'basic', '[{"type": "arabic", "label": {"bn": "যাকাতের আট খাত", "en": "The eight categories"}, "ar": "إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِمِينَ وَفِي سَبِيلِ اللَّهِ وَابْنِ السَّبِيلِ ۖ فَرِيضَةً مِنَ اللَّهِ ۗ وَاللَّهُ عَلِيمٌ حَكِيمٌ", "pron": {"bn": "ইন্নামাস সাদাকাতু লিল ফুকারাই ওয়াল মাসাকীনি ওয়াল আমিলীনা আলাইহা ওয়াল মুআল্লাফাতি কুলূবুহুম ওয়া ফির রিকাবি ওয়াল গারিমীনা ওয়া ফী সাবীলিল্লাহি ওয়াবনিস সাবীল, ফারীদাতাম মিনাল্লাহ, ওয়াল্লাহু আলীমুন হাকীম", "en": "Innamas-sadaqatu lil-fuqara''i wal-masakini wal-''amilina ''alayha wal-mu''allafati qulubuhum wa fir-riqabi wal-gharimina wa fi sabilillahi wabnis-sabil, faridatam minallah, wallahu ''alimun hakim"}, "meaning": {"bn": "সদকা (যাকাত) কেবল ফকির, মিসকিন, যাকাত আদায়ের কাজে নিযুক্ত কর্মী, যাদের মন জয় করা উদ্দেশ্য, দাসমুক্তি, ঋণগ্রস্ত, আল্লাহর পথে এবং মুসাফিরের জন্য। এটা আল্লাহর নির্ধারিত বিধান; আল্লাহ সর্বজ্ঞ, প্রজ্ঞাময়।", "en": "Zakat is only for the poor, the needy, those employed to administer it, those whose hearts are to be reconciled, freeing captives, those in debt, in the cause of Allah, and the stranded traveller: an obligation from Allah. Allah is All-Knowing, All-Wise."}, "ref": {"bn": "সূরা তাওবা ৯:৬০", "en": "At-Tawbah 9:60"}}, {"type": "table", "head": [{"bn": "খাত", "en": "Category"}, {"bn": "কারা", "en": "Who they are"}], "rows": [[{"bn": "ফকির", "en": "Al-fuqara'' (the poor)"}, {"bn": "যার নিসাব পরিমাণ সম্পদ নেই; প্রয়োজনের চেয়ে অনেক কম আছে", "en": "Those without nisab-level wealth, having far less than their needs"}], [{"bn": "মিসকিন", "en": "Al-masakin (the needy)"}, {"bn": "যার কিছুই নেই বা যা আছে তাতে চলে না (দুটির পার্থক্য নিয়ে মতভেদ আছে, তবে দুজনই হকদার)", "en": "Those with nothing or not enough to live on (the exact difference is debated; both are eligible)"}], [{"bn": "আমিলিন", "en": "Al-''amilin (zakat workers)"}, {"bn": "সরকার বা প্রতিষ্ঠানের পক্ষ থেকে যাকাত সংগ্রহ ও বণ্টনের দায়িত্বপ্রাপ্ত কর্মী, ধনী হলেও পারিশ্রমিক হিসেবে", "en": "Those appointed by the state or an institution to collect and distribute zakat, paid even if wealthy"}], [{"bn": "মুআল্লাফাতুল কুলূব", "en": "Mu''allafat al-qulub"}, {"bn": "ইসলামের প্রতি মন আকৃষ্ট করা বা নওমুসলিমকে দৃঢ় করা যাদের উদ্দেশ্য (হানাফি মতে এ খাতটি এখন প্রযোজ্য নয়; অন্যরা প্রয়োজনে প্রযোজ্য বলেন)", "en": "Those whose hearts are to be won or new Muslims to be strengthened (Hanafis hold this no longer applies; others say it applies when needed)"}], [{"bn": "রিকাব", "en": "Ar-riqab (captives)"}, {"bn": "দাস বা বন্দিকে মুক্ত করা", "en": "Freeing slaves or captives"}], [{"bn": "গারিমিন", "en": "Al-gharimin (debtors)"}, {"bn": "বৈধ প্রয়োজনে ঋণগ্রস্ত, যে ঋণ শোধ করতে অক্ষম", "en": "Those in debt for a lawful need who cannot repay"}], [{"bn": "ফী সাবীলিল্লাহ", "en": "Fi sabilillah"}, {"bn": "আল্লাহর পথে: হানাফি মতে আল্লাহর পথে নিয়োজিত অভাবী ব্যক্তি (যেমন অভাবী দ্বীনি ছাত্র); এর পরিধি নিয়ে আলেমদের মতভেদ আছে", "en": "In Allah''s cause: for Hanafis, needy people engaged in it (e.g. poor students of religious knowledge); its scope is debated"}], [{"bn": "ইবনুস সাবীল", "en": "Ibn as-sabil"}, {"bn": "সফরে গিয়ে অর্থসংকটে পড়া মুসাফির, বাড়িতে ধনী হলেও", "en": "A traveller stranded without funds, even if wealthy at home"}]]}, {"type": "note", "tone": "tip", "text": {"bn": "নিকটাত্মীয়দের মধ্যে যারা হকদার (ভাই-বোন, চাচা-মামা, খালা-ফুফু ইত্যাদি), তাদের দেওয়া উত্তম; এতে যাকাত ও আত্মীয়তার হক দুটোই আদায় হয়।", "en": "It is best to give to eligible relatives (siblings, uncles, aunts, etc.); it fulfils both zakat and the rights of kinship."}}, {"type": "heading", "text": {"bn": "যাদের যাকাত দেওয়া যায় না", "en": "Those who cannot receive zakat"}}, {"type": "list", "items": [{"bn": "নিজের মা-বাবা, দাদা-দাদি, নানা-নানি (ঊর্ধ্বতন)", "en": "One''s own parents and grandparents (ascendants)"}, {"bn": "নিজের সন্তান, নাতি-নাতনি (অধস্তন)", "en": "One''s own children and grandchildren (descendants)"}, {"bn": "নিজের স্ত্রী (স্বামী স্ত্রীকে যাকাত দিতে পারেন না)", "en": "One''s own wife (a husband cannot give zakat to his wife)"}, {"bn": "নিসাব পরিমাণ সম্পদের মালিক ধনী ব্যক্তি", "en": "A wealthy person who owns nisab"}, {"bn": "নবী (সা.)-এর বংশধর বনু হাশিম", "en": "The Prophet''s family, Banu Hashim"}, {"bn": "অমুসলিমকে ফরজ যাকাত দেওয়া যায় না (নফল সদকা দেওয়া যায়)", "en": "Non-Muslims cannot receive obligatory zakat (they may receive voluntary charity)"}, {"bn": "হানাফি মতে যাকাতে কোনো ব্যক্তিকে মালিক বানিয়ে দিতে হয়; তাই সরাসরি মসজিদ নির্মাণ, রাস্তা তৈরি বা মৃতের কাফনে যাকাতের টাকা খরচ করা যায় না", "en": "Hanafis require zakat to be handed into a person''s ownership, so it cannot be spent directly on building masjids, roads or shrouding the dead"}]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১০৭২", "en": "Sahih Muslim 1072"}}, {"type": "differ", "title": {"bn": "স্ত্রী কি স্বামীকে যাকাত দিতে পারবেন", "en": "Can a wife give zakat to her husband"}, "views": [{"label": {"bn": "ইমাম আবু হানিফা", "en": "Imam Abu Hanifa"}, "text": {"bn": "না; স্বামী-স্ত্রীর সম্পদ ও উপকার পরস্পর জড়িত, তাই যাকাত নিজের কাছেই ফিরে আসে।", "en": "No; spouses share benefit from each other''s wealth, so the zakat effectively returns to the giver."}, "evidence": {"bn": "মা-বাবা ও সন্তানের ক্ষেত্রে নিষেধের ওপর কিয়াস।", "en": "Analogy with the prohibition for parents and children."}}, {"label": {"bn": "শাফেয়ি, হাম্বলি (এক বর্ণনা), আবু ইউসুফ ও মুহাম্মদ", "en": "Shafi''i, Hanbali (one report), Abu Yusuf and Muhammad"}, "text": {"bn": "হ্যাঁ, স্বামী হকদার হলে স্ত্রী তাকে যাকাত দিতে পারেন।", "en": "Yes, a wife may give her zakat to her husband if he is eligible."}, "evidence": {"bn": "ইবনে মাসউদ (রা.)-এর স্ত্রী জয়নব (রা.) স্বামী ও ইয়াতিমদের দান করা সম্পর্কে জিজ্ঞেস করলে নবী (সা.) বলেন, তার জন্য দুটি সওয়াব: আত্মীয়তার ও সদকার (সহিহ বুখারি)।", "en": "When Zaynab, wife of Ibn Mas''ud, asked about giving to her husband and orphans, the Prophet said she would have two rewards, for kinship and for charity (Sahih al-Bukhari)."}}], "check": true}, {"type": "note", "tone": "info", "text": {"bn": "ভালোভাবে খোঁজ নিয়ে যাকে হকদার মনে করে দিয়েছেন, পরে সে ধনী প্রমাণিত হলেও হানাফি মতে যাকাত আদায় হয়ে যাবে।", "en": "If you gave to someone after reasonable checking and they later turn out to be wealthy, in the Hanafi view the zakat is still valid."}}]', 'in_review', 50 FROM is_guide_topics WHERE slug = 'zakat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'af354431-da57-5509-8cec-3f3319423958', id, 'zakat-sadaqah', '{"bn": "সদকা ও তার ফজিলত", "en": "Sadaqah and its virtues"}', '{"bn": "ফরজ যাকাতের বাইরে নফল দান, সদকায়ে জারিয়া এবং দানের আদব।", "en": "Voluntary charity beyond zakat, ongoing charity, and the manners of giving."}', 'basic', '[{"type": "arabic", "ar": "مَثَلُ الَّذِينَ يُنْفِقُونَ أَمْوَالَهُمْ فِي سَبِيلِ اللَّهِ كَمَثَلِ حَبَّةٍ أَنْبَتَتْ سَبْعَ سَنَابِلَ فِي كُلِّ سُنْبُلَةٍ مِائَةُ حَبَّةٍ", "pron": {"bn": "মাসালুল্লাযীনা ইউনফিকূনা আমওয়ালাহুম ফী সাবীলিল্লাহি কামাসালি হাব্বাতিন আমবাতাত সাবআ সানাবিলা ফী কুল্লি সুমবুলাতিম মিআতু হাব্বাহ", "en": "Mathalul-ladhina yunfiquna amwalahum fi sabilillahi kamathali habbatin ambatat sab''a sanabila fi kulli sumbulatim mi''atu habbah"}, "meaning": {"bn": "যারা আল্লাহর পথে সম্পদ ব্যয় করে, তাদের উপমা একটি শস্যদানার মতো, যা থেকে সাতটি শীষ জন্মায়, প্রতিটি শীষে একশ দানা।", "en": "The example of those who spend their wealth in the way of Allah is that of a grain that grows seven ears, in each ear a hundred grains."}, "ref": {"bn": "সূরা বাকারা ২:২৬১", "en": "Al-Baqarah 2:261"}}, {"type": "heading", "text": {"bn": "সদকার কিছু ফজিলত", "en": "Some virtues of charity"}}, {"type": "list", "items": [{"bn": "সদকা সম্পদ কমায় না।", "en": "Charity does not decrease wealth."}, {"bn": "অর্ধেক খেজুর দিয়ে হলেও জাহান্নাম থেকে বাঁচো।", "en": "Protect yourself from the Fire, even with half a date."}, {"bn": "আল্লাহ হালাল উপার্জনের দান গ্রহণ করেন এবং তা বাড়িয়ে পাহাড়সম করে দেন।", "en": "Allah accepts charity from lawful earnings and grows it until it becomes like a mountain."}, {"bn": "যে এত গোপনে দান করে যে ডান হাত কী দিল বাম হাত জানে না, সে কিয়ামতের দিন আল্লাহর আরশের ছায়া পাবে।", "en": "One who gives so secretly that his left hand does not know what his right hand gave will be shaded by Allah on the Day of Judgement."}, {"bn": "প্রত্যেক ভালো কাজই সদকা; ভাইয়ের সাথে হাসিমুখে দেখা করাও সদকা।", "en": "Every good deed is charity; meeting your brother with a smile is charity."}]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৫৮৮; সহিহ বুখারি ১৪১৭; সহিহ বুখারি ১৪১০; সহিহ বুখারি ১৪২৩; সহিহ বুখারি ৬০২১; জামে তিরমিজি ১৯৫৬", "en": "Sahih Muslim 2588; Sahih al-Bukhari 1417; Sahih al-Bukhari 1410; Sahih al-Bukhari 1423; Sahih al-Bukhari 6021; Jami'' at-Tirmidhi 1956"}}, {"type": "heading", "text": {"bn": "সদকায়ে জারিয়া", "en": "Ongoing charity (sadaqah jariyah)"}}, {"type": "text", "text": {"bn": "মানুষ মারা গেলে তার আমল বন্ধ হয়ে যায়, তিনটি ছাড়া: সদকায়ে জারিয়া, উপকারী জ্ঞান এবং নেক সন্তান যে তার জন্য দোয়া করে। মসজিদ, মাদরাসা, নলকূপ, হাসপাতাল, গাছ লাগানো, কুরআন বিতরণ — এগুলো চলমান সদকার উদাহরণ (এসব খাতে নফল সদকা দেবেন; হানাফি মতে ফরজ যাকাত নয়)।", "en": "When a person dies his deeds end except three: ongoing charity, beneficial knowledge, and a righteous child who prays for him. Masjids, schools, wells, hospitals, planting trees and distributing Qurans are examples (give voluntary charity for these; in the Hanafi view not obligatory zakat)."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১৬৩১", "en": "Sahih Muslim 1631"}}, {"type": "heading", "text": {"bn": "দানের আদব", "en": "Manners of giving"}}, {"type": "list", "items": [{"bn": "হালাল ও ভালো জিনিস দান করুন; নিজে যা নিতে চান না তা দেবেন না।", "en": "Give from lawful and good things; do not give what you yourself would not accept."}, {"bn": "খোঁটা দিয়ে বা কষ্ট দিয়ে দান নষ্ট করবেন না।", "en": "Do not ruin charity with reminders of your favour or with hurt."}, {"bn": "লোক দেখানোর জন্য নয়, আল্লাহর সন্তুষ্টির জন্য দিন; গোপনে দেওয়া উত্তম, তবে অন্যকে উৎসাহিত করতে প্রকাশ্যে দেওয়াও জায়েজ।", "en": "Give for Allah, not for show; secret giving is better, though open giving to encourage others is allowed."}, {"bn": "প্রাপকের সম্মান রক্ষা করুন; ছবি তুলে প্রচার করা থেকে বিরত থাকুন।", "en": "Preserve the recipient''s dignity; avoid photographing and publicising them."}]}, {"type": "ref", "text": {"bn": "সূরা বাকারা ২:২৬৪; সূরা বাকারা ২:২৬৭; সূরা বাকারা ২:২৭১", "en": "Al-Baqarah 2:264; Al-Baqarah 2:267; Al-Baqarah 2:271"}}]', 'in_review', 60 FROM is_guide_topics WHERE slug = 'zakat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '0db15e08-cc83-54e0-9d4b-1e7b4ffe2cff', id, 'zakat-common-mistakes', '{"bn": "যাকাতে প্রচলিত ভুল", "en": "Common mistakes in zakat"}', '{"bn": "যাকাত দিতে গিয়ে মানুষ সাধারণত যে ভুলগুলো করে।", "en": "Mistakes people commonly make when paying zakat."}', 'basic', '[{"type": "list", "items": [{"bn": "হিসাব না করে আন্দাজে একটা অঙ্ক দিয়ে দেওয়া। প্রতি বছর লিখে হিসাব করুন।", "en": "Giving a rough amount without calculating. Calculate and write it down every year."}, {"bn": "শুধু রমজানে যাকাত দিতে হবে ভাবা। যাকাতের তারিখ আপনার নিসাবের বছর অনুযায়ী; চাইলে রমজানকে তারিখ বানাতে পারেন, কিন্তু পরে দেরি করা ঠিক নয়।", "en": "Thinking zakat must be paid in Ramadan. The date follows your nisab year; you may choose a Ramadan date, but do not delay beyond it."}, {"bn": "স্ত্রীর গয়না, ব্যবসার মাল বা পাওনা টাকা হিসাব থেকে বাদ দেওয়া।", "en": "Leaving out the wife''s jewellery, business stock or money owed."}, {"bn": "ইংরেজি বছর ধরে ২.৫% দেওয়া; সৌরবছরে হিসাব করলে প্রায় ২.৫৭৭% দিন।", "en": "Paying 2.5% on a solar year; on a solar year pay about 2.577%."}, {"bn": "মা-বাবা, সন্তান বা স্ত্রীকে যাকাত দেওয়া।", "en": "Giving zakat to parents, children or one''s wife."}, {"bn": "যাচাই না করে পেশাদার ভিক্ষুক বা ধনী ব্যক্তিকে দেওয়া।", "en": "Giving without checking to professional beggars or the well-off."}, {"bn": "নিম্নমানের শাড়ি-লুঙ্গির দাম বাজারমূল্যের চেয়ে বেশি ধরে যাকাত হিসাবে দেওয়া; জিনিস দিলে তার প্রকৃত মূল্যই ধরবেন।", "en": "Giving cheap clothes valued above their real price; when giving goods, count only their true value."}, {"bn": "যাকাতের টাকায় সরাসরি মসজিদ বানানো বা ওয়াজ মাহফিলের খরচ চালানো (হানাফি মতে আদায় হয় না)।", "en": "Using zakat directly to build masjids or fund events (not valid in the Hanafi view)."}, {"bn": "কর্মচারীর বেতন বা উপহার যাকাতের নামে দেওয়া; প্রাপ্য পারিশ্রমিক যাকাত নয়।", "en": "Paying an employee''s salary or a gift as zakat; wages owed are not zakat."}, {"bn": "যাকাতের নিয়ত ছাড়া দান করে পরে তাকে যাকাত ধরা; দেওয়ার সময় বা আলাদা করে রাখার সময় নিয়ত থাকতে হবে।", "en": "Giving without the intention of zakat and counting it later; the intention must be there when giving or when setting it aside."}, {"bn": "সুদের টাকা দিয়ে যাকাত দেওয়া। সুদের টাকা সওয়াবের নিয়ত ছাড়া গরিবকে দিয়ে দিতে হবে; যাকাত হালাল সম্পদ থেকে দিতে হবে।", "en": "Paying zakat from interest money. Interest must be given away without seeking reward; zakat is paid from lawful wealth."}, {"bn": "মাসিক বেতনের প্রতিটির জন্য আলাদা বছর গুনতে গিয়ে হিসাব জটিল করে ফেলা; হানাফি মতে যাকাতের তারিখে যা আছে, সবকিছুর যাকাত একসাথে দিলেই হয়।", "en": "Over-complicating by counting a separate year for every salary; for Hanafis, pay on everything you hold on the zakat date."}]}, {"type": "note", "tone": "tip", "text": {"bn": "অ্যাপের যাকাত ক্যালকুলেটর ব্যবহার করে প্রতি বছরের হিসাব সংরক্ষণ করুন, যাতে পরের বছর তুলনা করা সহজ হয়।", "en": "Use the app''s zakat calculator and keep each year''s calculation so next year''s comparison is easy."}}]', 'in_review', 70 FROM is_guide_topics WHERE slug = 'zakat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'bc8edbf2-aa93-542e-baaf-012e269acde7', id, 'hajj-basics', '{"bn": "হজ: কার ওপর ফরজ", "en": "Hajj: who must perform it"}', '{"bn": "হজ জীবনে একবার ফরজ, যদি সামর্থ্য থাকে। হজ ফরজ হওয়ার শর্ত, ফজিলত ও হজের মাসগুলো।", "en": "Hajj is obligatory once in a lifetime for those able. Its conditions, virtues and months."}', 'basic', '[{"type": "arabic", "ar": "وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا", "pron": {"bn": "ওয়া লিল্লাহি আলান নাসি হিজ্জুল বাইতি মানিসতাতাআ ইলাইহি সাবীলা", "en": "Wa lillahi ''alan-nasi hijjul-bayti manistata''a ilayhi sabila"}, "meaning": {"bn": "আর আল্লাহর জন্য মানুষের ওপর এই ঘরের হজ করা ফরজ, যে সেখানে যাওয়ার সামর্থ্য রাখে।", "en": "Pilgrimage to the House is a duty owed to Allah by people who are able to make their way there."}, "ref": {"bn": "সূরা আলে ইমরান ৩:৯৭", "en": "Aal-Imran 3:97"}}, {"type": "text", "text": {"bn": "হজ ইসলামের পঞ্চম স্তম্ভ। সামর্থ্যবান মুসলিমের ওপর জীবনে একবার হজ করা ফরজ; এর বেশি করলে তা নফল।", "en": "Hajj is the fifth pillar of Islam. It is obligatory once in a lifetime on a Muslim who is able; more than that is voluntary."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১৩৩৭", "en": "Sahih Muslim 1337"}}, {"type": "heading", "text": {"bn": "হজ ফরজ হওয়ার শর্ত", "en": "Conditions that make hajj obligatory"}}, {"type": "list", "items": [{"bn": "মুসলিম হওয়া", "en": "Being Muslim"}, {"bn": "প্রাপ্তবয়স্ক ও সুস্থ মস্তিষ্কের হওয়া", "en": "Being adult and of sound mind"}, {"bn": "স্বাধীন হওয়া", "en": "Being free"}, {"bn": "আর্থিক সামর্থ্য: যাতায়াত, থাকা-খাওয়ার খরচ এবং ফেরা পর্যন্ত পরিবারের ভরণপোষণের খরচের অতিরিক্ত অর্থ থাকা", "en": "Financial ability: money for travel, lodging and food, beyond what the family needs until return"}, {"bn": "শারীরিক সামর্থ্য ও পথের নিরাপত্তা", "en": "Physical ability and a safe route"}, {"bn": "নারীর জন্য মাহরাম বা স্বামী সঙ্গে থাকা (মতভেদ আছে; নারীদের গাইডে বিস্তারিত)", "en": "For a woman, a mahram or husband accompanying her (differed on; see the women''s guide)"}]}, {"type": "note", "tone": "info", "text": {"bn": "সামর্থ্য হওয়ার পর বিনা কারণে দেরি না করে হজ করা উচিত। হানাফি মাজহাবে (ইমাম আবু ইউসুফের মত অনুযায়ী) সামর্থ্য হলে প্রথম সুযোগেই হজ করা ওয়াজিব; দেরি করলে গুনাহ হয়, যদিও পরে করলে হজ আদায় হয়ে যায়।", "en": "Once able, one should not delay hajj without reason. In the Hanafi school (per Imam Abu Yusuf) it must be done at the first opportunity; delaying is sinful, though hajj done later is still valid."}}, {"type": "heading", "text": {"bn": "ফজিলত", "en": "Virtues"}}, {"type": "list", "items": [{"bn": "যে আল্লাহর জন্য হজ করে, অশ্লীল কথা ও গুনাহ থেকে বেঁচে থাকে, সে সদ্য জন্ম নেওয়া শিশুর মতো নিষ্পাপ হয়ে ফেরে।", "en": "Whoever performs hajj for Allah, avoiding obscenity and sin, returns as sinless as the day his mother bore him."}, {"bn": "কবুল হজের (হজে মাবরুর) প্রতিদান জান্নাত ছাড়া কিছু নয়।", "en": "The reward of an accepted hajj (hajj mabrur) is nothing less than Paradise."}, {"bn": "আরাফার দিনের চেয়ে বেশি মানুষকে আল্লাহ অন্য কোনো দিন জাহান্নাম থেকে মুক্তি দেন না।", "en": "There is no day on which Allah frees more people from the Fire than the day of Arafah."}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৫২১; সহিহ বুখারি ১৭৭৩; সহিহ মুসলিম ১৩৪৮", "en": "Sahih al-Bukhari 1521; Sahih al-Bukhari 1773; Sahih Muslim 1348"}}, {"type": "heading", "text": {"bn": "হজের মাস ও আদব", "en": "The months and manners of hajj"}}, {"type": "arabic", "ar": "الْحَجُّ أَشْهُرٌ مَعْلُومَاتٌ ۚ فَمَنْ فَرَضَ فِيهِنَّ الْحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي الْحَجِّ", "pron": {"bn": "আল হাজ্জু আশহুরুম মা''লূমাত, ফামান ফারাদা ফীহিন্নাল হাজ্জা ফালা রাফাসা ওয়ালা ফুসূকা ওয়ালা জিদালা ফিল হাজ্জ", "en": "Al-hajju ashhurum ma''lumat, faman farada fihinnal-hajja fala rafatha wa la fusuqa wa la jidala fil-hajj"}, "meaning": {"bn": "হজের মাসগুলো সুবিদিত। যে এসব মাসে হজ নিজের ওপর অপরিহার্য করে নেয়, তার জন্য হজে অশ্লীলতা, পাপাচার ও ঝগড়া-বিবাদ নেই।", "en": "Hajj is in well-known months. Whoever undertakes hajj in them, there is to be no obscenity, no wrongdoing and no quarrelling during hajj."}, "ref": {"bn": "সূরা বাকারা ২:১৯৭", "en": "Al-Baqarah 2:197"}}, {"type": "text", "text": {"bn": "হজের মাস: শাওয়াল, জিলকদ ও জিলহজের প্রথম দশ দিন। এর আগে হজের ইহরাম বাঁধা হানাফি মতে মাকরুহ এবং শাফেয়ি মতে তা উমরাহ হয়ে যায়। মূল হজের কাজগুলো হয় ৮ থেকে ১৩ জিলহজ।", "en": "The months of hajj are Shawwal, Dhul Qa''dah and the first ten days of Dhul Hijjah. Entering ihram for hajj before them is disliked for Hanafis, and for Shafi''is it becomes an umrah. The main rites take place from 8 to 13 Dhul Hijjah."}}, {"type": "note", "tone": "tip", "text": {"bn": "হজের আগে টাকা হালাল কি না নিশ্চিত হোন, কারও কাছে ঋণ বা হক থাকলে মিটিয়ে নিন, খাঁটি তওবা করুন এবং হজের নিয়মগুলো আগে থেকে ভালোভাবে শিখে নিন।", "en": "Before hajj, make sure your money is lawful, settle debts and rights owed to others, repent sincerely, and learn the rites well in advance."}}]', 'in_review', 10 FROM is_guide_topics WHERE slug = 'hajj' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'a160a7c4-b1e8-59a8-816b-d8def37d5148', id, 'hajj-types-miqat', '{"bn": "হজের প্রকার ও মিকাত", "en": "Types of hajj and the miqat"}', '{"bn": "ইফরাদ, কিরান ও তামাত্তু হজের পার্থক্য এবং কোথা থেকে ইহরাম বাঁধতে হয়।", "en": "The difference between ifrad, qiran and tamattu'', and where ihram must be entered."}', 'basic', '[{"type": "heading", "text": {"bn": "হজের তিন প্রকার", "en": "The three types of hajj"}}, {"type": "table", "head": [{"bn": "প্রকার", "en": "Type"}, {"bn": "কীভাবে", "en": "How"}, {"bn": "কুরবানি (হাদি)", "en": "Sacrifice (hady)"}], "rows": [[{"bn": "ইফরাদ", "en": "Ifrad"}, {"bn": "শুধু হজের ইহরাম; উমরাহ ছাড়া কেবল হজ", "en": "Ihram for hajj alone, without umrah"}, {"bn": "ওয়াজিব নয় (চাইলে নফল)", "en": "Not required (optional)"}], [{"bn": "কিরান", "en": "Qiran"}, {"bn": "উমরাহ ও হজ একই ইহরামে; উমরাহর পর ইহরাম খোলা যায় না, হজ শেষে খোলা হয়", "en": "Umrah and hajj in one ihram; ihram is not removed after umrah, only after hajj"}, {"bn": "ওয়াজিব", "en": "Required"}], [{"bn": "তামাত্তু", "en": "Tamattu''"}, {"bn": "হজের মাসে প্রথমে উমরাহ করে ইহরাম খুলে ফেলা, তারপর ৮ জিলহজ মক্কা থেকে নতুন করে হজের ইহরাম", "en": "Umrah in the hajj months, leave ihram, then a new ihram for hajj from Makkah on 8 Dhul Hijjah"}, {"bn": "ওয়াজিব", "en": "Required"}]]}, {"type": "arabic", "ar": "فَمَنْ تَمَتَّعَ بِالْعُمْرَةِ إِلَى الْحَجِّ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ", "pron": {"bn": "ফামান তামাত্তাআ বিল উমরাতি ইলাল হাজ্জি ফামাসতাইসারা মিনাল হাদই", "en": "Faman tamatta''a bil-''umrati ilal-hajji famastaysara minal-hady"}, "meaning": {"bn": "যে ব্যক্তি উমরাহকে হজের সাথে মিলিয়ে উপকৃত হয়, সে যা সহজলভ্য তা কুরবানি করবে।", "en": "Whoever benefits by combining umrah with hajj must offer whatever sacrifice is easily obtainable."}, "ref": {"bn": "সূরা বাকারা ২:১৯৬", "en": "Al-Baqarah 2:196"}}, {"type": "note", "tone": "info", "text": {"bn": "বাংলাদেশ থেকে যাওয়া হাজিদের বেশির ভাগ তামাত্তু হজ করেন, কারণ তারা কয়েক সপ্তাহ আগে পৌঁছান এবং দীর্ঘ সময় ইহরামে থাকা কঠিন। মক্কার স্থায়ী বাসিন্দাদের জন্য তামাত্তু ও কিরান নেই (হানাফি মত)।", "en": "Most pilgrims from Bangladesh perform tamattu'', since they arrive weeks early and staying long in ihram is hard. Residents of Makkah do not perform tamattu'' or qiran (Hanafi view)."}}, {"type": "differ", "title": {"bn": "কোন হজ উত্তম", "en": "Which type is best"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "কিরান সর্বোত্তম, তারপর তামাত্তু, তারপর ইফরাদ।", "en": "Qiran is best, then tamattu'', then ifrad."}, "evidence": {"bn": "নবী (সা.) কিরান হজ করেছিলেন বলে আনাস (রা.)-এর বর্ণনা; এতে কষ্ট ও ইবাদত বেশি।", "en": "Anas''s report that the Prophet performed qiran; it involves more effort and worship."}}, {"label": {"bn": "শাফেয়ি ও মালেকি", "en": "Shafi''i and Maliki"}, "text": {"bn": "ইফরাদ উত্তম (সেই বছরই উমরাহ করলে)।", "en": "Ifrad is best (if umrah is done the same year)."}, "evidence": {"bn": "জাবির (রা.) ও আয়েশা (রা.)-এর কিছু বর্ণনায় নবী (সা.) ইফরাদ করেছিলেন বলে এসেছে; খুলাফায়ে রাশেদিনের আমল।", "en": "Some reports from Jabir and Aishah say the Prophet performed ifrad; practice of the rightly-guided caliphs."}}, {"label": {"bn": "হাম্বলি", "en": "Hanbali"}, "text": {"bn": "তামাত্তু উত্তম।", "en": "Tamattu'' is best."}, "evidence": {"bn": "নবী (সা.) কুরবানির পশু সঙ্গে না থাকা সাহাবিদের তামাত্তু করতে বলেন এবং বলেন, আগে জানলে তিনি নিজেও পশু সঙ্গে আনতেন না।", "en": "The Prophet told Companions without sacrificial animals to make it tamattu'', saying that had he known beforehand he would not have brought his animal."}}]}, {"type": "heading", "text": {"bn": "মিকাত", "en": "The miqat"}}, {"type": "text", "text": {"bn": "মিকাত হলো সেই নির্ধারিত সীমা, যেখান থেকে হজ বা উমরাহর নিয়তে আসা ব্যক্তিকে ইহরাম বাঁধতে হয়। ইহরাম ছাড়া মিকাত পার হলে ফিরে এসে ইহরাম বাঁধতে হবে, নয়তো দম (একটি পশু কুরবানি) দিতে হবে।", "en": "The miqat is the fixed boundary at which anyone intending hajj or umrah must enter ihram. Crossing it without ihram means returning to enter ihram there, or else a dam (one animal sacrifice) is due."}}, {"type": "table", "head": [{"bn": "মিকাত", "en": "Miqat"}, {"bn": "কাদের জন্য", "en": "For whom"}, {"bn": "বর্তমান নাম/অবস্থান", "en": "Today"}], "rows": [[{"bn": "যুল হুলাইফা", "en": "Dhul Hulayfah"}, {"bn": "মদিনা থেকে আসা ব্যক্তি", "en": "Those coming from Madinah"}, {"bn": "আবইয়ার আলী (মদিনার কাছে)", "en": "Abyar Ali (near Madinah)"}], [{"bn": "জুহফা", "en": "Al-Juhfah"}, {"bn": "সিরিয়া, মিসর ও পশ্চিম দিক থেকে", "en": "From Syria, Egypt and the west"}, {"bn": "রাবিগের কাছে", "en": "Near Rabigh"}], [{"bn": "কারনুল মানাযিল", "en": "Qarn al-Manazil"}, {"bn": "নজদ ও পূর্ব দিক থেকে", "en": "From Najd and the east"}, {"bn": "আস-সাইল আল-কাবির", "en": "As-Sayl al-Kabir"}], [{"bn": "ইয়ালামলাম", "en": "Yalamlam"}, {"bn": "ইয়েমেন ও দক্ষিণ দিক থেকে; উপমহাদেশ থেকে সমুদ্রপথে আসা যাত্রী", "en": "From Yemen and the south; travellers by sea from the subcontinent"}, {"bn": "আস-সাদিয়া", "en": "As-Sa''diyyah"}], [{"bn": "যাতু ইরক", "en": "Dhat ''Irq"}, {"bn": "ইরাক থেকে", "en": "From Iraq"}, {"bn": "বর্তমানে সড়কপথে খুব কম ব্যবহৃত", "en": "Rarely used by road today"}]]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৫২৪; সহিহ মুসলিম ১১৮১", "en": "Sahih al-Bukhari 1524; Sahih Muslim 1181"}}, {"type": "note", "tone": "warn", "text": {"bn": "বাংলাদেশ থেকে সরাসরি জেদ্দাগামী বিমানের যাত্রীদের বিমান মিকাতের সীমা পার হয় জেদ্দায় নামার আগেই। তাই ঢাকা থেকেই ইহরামের কাপড় পরে নিন (বা বিমানে পরুন) এবং মিকাত কাছে আসার ঘোষণা হলে নিয়ত করে তালবিয়া পড়ুন। জেদ্দায় নেমে ইহরাম বাঁধার অপেক্ষা করবেন না।", "en": "On direct flights from Bangladesh to Jeddah, the plane crosses the miqat line before landing. So put on the ihram clothes in Dhaka (or on the plane) and make the intention and talbiyah when the miqat is announced. Do not wait to enter ihram in Jeddah."}}, {"type": "note", "tone": "info", "text": {"bn": "যারা প্রথমে মদিনা যাবেন, তারা বিমানে ইহরাম বাঁধবেন না; পরে মদিনা থেকে মক্কা যাওয়ার পথে যুল হুলাইফায় ইহরাম বাঁধবেন। মিকাতের ভেতরে বসবাসকারীরা নিজের অবস্থান থেকেই ইহরাম বাঁধেন; আর মক্কায় অবস্থানকারী হজের ইহরাম মক্কা থেকে এবং উমরাহর ইহরাম হারামের সীমার বাইরে (যেমন তানঈম) থেকে বাঁধেন।", "en": "Those going to Madinah first do not enter ihram on the plane; they enter it at Dhul Hulayfah on the way from Madinah to Makkah. People living inside the miqat enter ihram from where they are; someone in Makkah enters hajj ihram in Makkah and umrah ihram outside the Haram boundary (e.g. at Tan''im)."}}]', 'in_review', 20 FROM is_guide_topics WHERE slug = 'hajj' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '0865c935-d037-5964-8a65-33f1862807fb', id, 'hajj-ihram', '{"bn": "ইহরাম: নিয়ম ও নিষেধ", "en": "Ihram: rules and prohibitions"}', '{"bn": "ইহরামের প্রস্তুতি, পোশাক, নিয়ত, তালবিয়া এবং ইহরাম অবস্থায় যা নিষেধ।", "en": "Preparing for ihram, the clothing, the intention, the talbiyah and what is forbidden in ihram."}', 'basic', '[{"type": "text", "text": {"bn": "ইহরাম মানে হজ বা উমরাহর নিয়ত করে তালবিয়া পড়ার মাধ্যমে এমন অবস্থায় প্রবেশ করা, যেখানে কিছু হালাল কাজও সাময়িকভাবে নিষিদ্ধ হয়ে যায়। শুধু সাদা কাপড় পরলেই ইহরাম হয় না; নিয়ত ও তালবিয়াই মূল।", "en": "Ihram is entering, by intention and the talbiyah, a sacred state in which some normally lawful things become temporarily forbidden. Wearing white sheets alone is not ihram; the intention and talbiyah are what count."}}, {"type": "step", "title": {"bn": "পরিচ্ছন্নতা", "en": "Cleanliness"}, "text": {"bn": "নখ কাটা, অবাঞ্ছিত লোম পরিষ্কার করা, তারপর গোসল করা (সুন্নত; গোসল সম্ভব না হলে ওজু)। হায়েজ-নিফাস অবস্থায় নারীরাও গোসল করবেন।", "en": "Trim nails, remove unwanted hair, then take a ghusl (sunnah; wudu if ghusl is not possible). Women in menstruation or post-natal bleeding also take this ghusl."}}, {"type": "step", "title": {"bn": "সুগন্ধি", "en": "Perfume"}, "text": {"bn": "পুরুষ ইহরামের আগে শরীরে (কাপড়ে নয়) সুগন্ধি লাগাতে পারেন; ইহরামের পরে তার ঘ্রাণ থেকে গেলে সমস্যা নেই।", "en": "Men may apply perfume to the body (not the ihram cloth) before ihram; its lingering scent afterwards is fine."}}, {"type": "step", "title": {"bn": "পোশাক", "en": "Clothing"}, "text": {"bn": "পুরুষ: সেলাইবিহীন দুটি চাদর, একটি লুঙ্গির মতো (ইজার), একটি গায়ে (রিদা); সাদা হওয়া উত্তম। মাথা খোলা, আর এমন জুতা/স্যান্ডেল যাতে পায়ের পাতার মাঝখানের উঁচু হাড় খোলা থাকে। নারী: সাধারণ শালীন পোশাক, যেকোনো রঙের; শুধু মুখে নিকাব ও হাতে মোজা পরবেন না।", "en": "Men: two unstitched sheets, one wrapped round the waist (izar) and one over the shoulders (rida), preferably white; head uncovered; sandals that leave the raised middle of the foot exposed. Women: ordinary modest clothes of any colour; only no face veil (niqab) and no gloves."}}, {"type": "step", "title": {"bn": "দুই রাকাত নামাজ", "en": "Two rakats"}, "text": {"bn": "মাকরুহ সময় না হলে ইহরামের নিয়তে দুই রাকাত নামাজ পড়া সুন্নত (হানাফি মত); অন্যদের মতে কোনো ফরজ নামাজের পরে ইহরাম বাঁধা উত্তম।", "en": "If it is not a disliked time, pray two rakats for ihram (Hanafi view); others say it is best to enter ihram after an obligatory prayer."}}, {"type": "step", "title": {"bn": "নিয়ত ও তালবিয়া", "en": "Intention and talbiyah"}, "text": {"bn": "মিকাতে বা তার আগে মনে মনে হজ/উমরাহর নিয়ত করুন এবং তালবিয়া পড়ুন। তালবিয়া পড়ার সঙ্গে সঙ্গে ইহরাম শুরু।", "en": "At or before the miqat, make the intention for hajj/umrah in your heart and say the talbiyah. Ihram begins with it."}}, {"type": "note", "tone": "tip", "text": {"bn": "নিয়ত মনের বিষয়। প্রচলিত মৌখিক উদাহরণ: ইফরাদে ''লাব্বাইকা হাজ্জান'', তামাত্তুতে প্রথমে ''লাব্বাইকা উমরাতান'', কিরানে ''লাব্বাইকা উমরাতান ওয়া হাজ্জান''। মুখে বলা শর্ত নয়, তবে এভাবে বলা সাহাবিদের থেকে বর্ণিত।", "en": "The intention is in the heart. Common spoken examples: for ifrad ''Labbayka hajjan'', for tamattu'' first ''Labbayka ''umratan'', for qiran ''Labbayka ''umratan wa hajjan''. Saying it is not a condition, though Companions are reported to have said it."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম (আনাস রা.: ''লাব্বাইকা উমরাতান ওয়া হাজ্জান'')", "en": "Sahih Muslim (Anas: ''Labbayka ''umratan wa hajjan'')"}, "check": true}, {"type": "arabic", "label": {"bn": "তালবিয়া", "en": "Talbiyah"}, "ar": "لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لَا شَرِيكَ لَكَ", "pron": {"bn": "লাব্বাইকা আল্লাহুম্মা লাব্বাইক, লাব্বাইকা লা শারীকা লাকা লাব্বাইক, ইন্নাল হামদা ওয়ান নি''মাতা লাকা ওয়াল মুলক, লা শারীকা লাক", "en": "Labbayka Allahumma labbayk, labbayka la sharika laka labbayk, innal-hamda wan-ni''mata laka wal-mulk, la sharika lak"}, "meaning": {"bn": "আমি হাজির, হে আল্লাহ! আমি হাজির। আমি হাজির, তোমার কোনো শরিক নেই, আমি হাজির। নিশ্চয়ই সব প্রশংসা, সব নিয়ামত তোমারই, আর রাজত্বও তোমার; তোমার কোনো শরিক নেই।", "en": "Here I am, O Allah, here I am. Here I am, You have no partner, here I am. Surely all praise and blessings are Yours, and the dominion; You have no partner."}, "ref": {"bn": "সহিহ বুখারি ১৫৪৯; সহিহ মুসলিম ১১৮৪", "en": "Sahih al-Bukhari 1549; Sahih Muslim 1184"}}, {"type": "note", "tone": "info", "text": {"bn": "পুরুষরা উচ্চস্বরে, নারীরা নিচু স্বরে তালবিয়া পড়বেন। ইহরাম থেকে শুরু করে উমরাহয় তাওয়াফ শুরু পর্যন্ত, আর হজে ১০ জিলহজ জামরাতুল আকাবায় প্রথম কংকর মারা পর্যন্ত বেশি বেশি তালবিয়া পড়ুন।", "en": "Men say the talbiyah aloud, women quietly. Say it often from ihram until starting tawaf in umrah, and in hajj until the first pebble at Jamrat al-Aqabah on 10 Dhul Hijjah."}}, {"type": "heading", "text": {"bn": "ইহরাম অবস্থায় যা নিষেধ", "en": "What is forbidden in ihram"}}, {"type": "list", "items": [{"bn": "চুল, দাড়ি বা শরীরের কোনো লোম কাটা বা ওঠানো; নখ কাটা", "en": "Cutting or removing hair from the head, beard or body; cutting nails"}, {"bn": "শরীর, কাপড় বা খাবারে সুগন্ধি ব্যবহার; সুগন্ধিযুক্ত সাবান", "en": "Using perfume on the body, clothes or food; scented soap"}, {"bn": "পুরুষের জন্য সেলাই করা পোশাক (জামা, প্যান্ট, গেঞ্জি, মোজা) পরা এবং মাথা ঢাকা", "en": "For men: wearing sewn, body-shaped garments (shirts, trousers, vests, socks) and covering the head"}, {"bn": "মুখ ঢাকা (পুরুষের জন্য সব মাজহাবে; নারীর জন্য মুখের সঙ্গে লেগে থাকা নিকাব)", "en": "Covering the face (for men in all schools; for women, a niqab fitted to the face)"}, {"bn": "স্থলের প্রাণী শিকার করা বা শিকারে সাহায্য করা", "en": "Hunting land animals or helping to hunt"}, {"bn": "বিয়ে করা বা বিয়ের প্রস্তাব দেওয়া", "en": "Marrying or proposing marriage"}, {"bn": "স্ত্রী-সহবাস, কামভাবের সাথে স্পর্শ বা অশ্লীল কথা", "en": "Marital relations, touching with desire, or obscene talk"}, {"bn": "ঝগড়া-বিবাদ ও সব ধরনের গুনাহ (এগুলো সবসময় নিষেধ, ইহরামে আরও কঠোরভাবে)", "en": "Quarrelling and all sins (always forbidden, more so in ihram)"}, {"bn": "হারামের সীমার ভেতরের গাছ কাটা বা ঘাস ওপড়ানো (ইহরাম ছাড়াও হারামে নিষেধ)", "en": "Cutting trees or uprooting plants within the Haram (forbidden there even without ihram)"}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৫৪২; সহিহ বুখারি ১৮৩৮", "en": "Sahih al-Bukhari 1542; Sahih al-Bukhari 1838"}}, {"type": "heading", "text": {"bn": "যা করা যায়", "en": "What is allowed"}}, {"type": "list", "items": [{"bn": "গোসল করা, সুগন্ধিহীন সাবান ব্যবহার", "en": "Bathing and using unscented soap"}, {"bn": "ঘড়ি, চশমা, বেল্ট বা টাকার থলে ব্যবহার", "en": "Wearing a watch, glasses, a belt or money pouch"}, {"bn": "ছাতা বা তাঁবুর ছায়া নেওয়া", "en": "Shade of an umbrella or tent"}, {"bn": "ইহরামের কাপড় বদলানো বা ধোয়া", "en": "Changing or washing the ihram sheets"}, {"bn": "প্রয়োজনে ওষুধ খাওয়া, ইনজেকশন নেওয়া", "en": "Taking medicine or injections when needed"}]}, {"type": "heading", "text": {"bn": "নিষিদ্ধ কাজ হয়ে গেলে", "en": "If a prohibition is broken"}}, {"type": "text", "text": {"bn": "ভুলে বা অজ্ঞতায় কিংবা জেনেশুনে নিষিদ্ধ কাজ হয়ে গেলে কাজের ধরন অনুযায়ী দম (মক্কার হারামে একটি ছাগল/ভেড়া বা গরু-উটের সাত ভাগের এক ভাগ কুরবানি) বা সদকা দিতে হয়। আরাফায় অবস্থানের আগে সহবাস করলে হজ নষ্ট হয়ে যায়। নির্দিষ্ট ক্ষেত্রে কী দিতে হবে, কাফেলার আলেম বা মুয়াল্লিমের কাছে জেনে নিন।", "en": "If a prohibition is broken, by mistake, ignorance or deliberately, a dam (sacrificing a sheep/goat or a seventh of a cow/camel in the Haram) or a charity is due depending on the act. Intercourse before standing at Arafah invalidates the hajj. Ask your group''s scholar what is due in a specific case."}}, {"type": "ref", "text": {"bn": "সূরা বাকারা ২:১৯৬", "en": "Al-Baqarah 2:196"}}]', 'in_review', 30 FROM is_guide_topics WHERE slug = 'hajj' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '6ced096e-e4b1-5edf-9b47-396271fc015d', id, 'hajj-days-8-9', '{"bn": "হজের দিন: ৮ ও ৯ জিলহজ (মিনা, আরাফা, মুজদালিফা)", "en": "Hajj days 8–9: Mina, Arafah, Muzdalifah"}', '{"bn": "তারবিয়ার দিন মিনায় যাওয়া, আরাফার দিনের অবস্থান ও দোয়া, তারপর মুজদালিফায় রাত যাপন।", "en": "Going to Mina on the day of Tarwiyah, standing at Arafah with its dua, then the night at Muzdalifah."}', 'detail', '[{"type": "table", "head": [{"bn": "তারিখ", "en": "Date"}, {"bn": "স্থান", "en": "Place"}, {"bn": "প্রধান কাজ", "en": "Main acts"}], "rows": [[{"bn": "৮ জিলহজ", "en": "8 Dhul Hijjah"}, {"bn": "মিনা", "en": "Mina"}, {"bn": "ইহরাম (তামাত্তু হলে), মিনায় পাঁচ ওয়াক্ত নামাজ", "en": "Ihram (for tamattu''), five prayers in Mina"}], [{"bn": "৯ জিলহজ", "en": "9 Dhul Hijjah"}, {"bn": "আরাফা → মুজদালিফা", "en": "Arafah → Muzdalifah"}, {"bn": "আরাফায় অবস্থান (হজের প্রধান রুকন), রাতে মুজদালিফা", "en": "Standing at Arafah (the main pillar), night at Muzdalifah"}], [{"bn": "১০ জিলহজ", "en": "10 Dhul Hijjah"}, {"bn": "মুজদালিফা → মিনা → মক্কা", "en": "Muzdalifah → Mina → Makkah"}, {"bn": "বড় জামরায় কংকর, কুরবানি, মাথা মুণ্ডন, তাওয়াফে জিয়ারত", "en": "Stoning the big jamrah, sacrifice, shaving, tawaf al-ifadah"}], [{"bn": "১১–১২ জিলহজ", "en": "11–12 Dhul Hijjah"}, {"bn": "মিনা", "en": "Mina"}, {"bn": "তিন জামরায় কংকর", "en": "Stoning the three jamarat"}], [{"bn": "১৩ জিলহজ (ঐচ্ছিক)", "en": "13 Dhul Hijjah (optional)"}, {"bn": "মিনা", "en": "Mina"}, {"bn": "তিন জামরায় কংকর, তারপর বিদায়", "en": "Stoning the three jamarat, then departure"}]]}, {"type": "heading", "text": {"bn": "৮ জিলহজ: ইয়াওমুত তারবিয়া", "en": "8 Dhul Hijjah: the day of Tarwiyah"}}, {"type": "step", "title": {"bn": "ইহরাম", "en": "Ihram"}, "text": {"bn": "তামাত্তু হাজিরা মক্কায় নিজের অবস্থানস্থল থেকে গোসল করে হজের ইহরাম বাঁধবেন ও তালবিয়া পড়বেন। কিরান ও ইফরাদ হাজিরা আগে থেকেই ইহরামে আছেন।", "en": "Tamattu'' pilgrims take a ghusl and enter hajj ihram from their lodging in Makkah and say the talbiyah. Qiran and ifrad pilgrims are already in ihram."}}, {"type": "step", "title": {"bn": "মিনায় যাওয়া", "en": "Go to Mina"}, "text": {"bn": "সকালে মিনায় গিয়ে জোহর, আসর, মাগরিব, এশা এবং ৯ তারিখের ফজর মিনায় আদায় করা ও রাত যাপন সুন্নত। নামাজ নিজ নিজ ওয়াক্তে পড়বেন।", "en": "Go to Mina in the morning; praying Zuhr, Asr, Maghrib, Isha and the Fajr of the 9th there and spending the night is sunnah. Pray each prayer in its own time."}}, {"type": "note", "tone": "info", "text": {"bn": "মিনায় চার রাকাতের নামাজ কসর হবে কি না, তা নিয়ে মতভেদ আছে: হানাফি মতে মক্কায় ১৫ দিন বা তার বেশি অবস্থানের নিয়ত করে থাকা হাজিরা পুরো নামাজ পড়বেন; অন্য অনেক আলেমের মতে সব হাজি মিনা-আরাফা-মুজদালিফায় কসর করবেন। নিজের কাফেলার আলেমের নির্দেশনা মানুন।", "en": "Scholars differ on shortening four-rakat prayers in Mina: in the Hanafi view pilgrims who intended to stay 15 days or more in Makkah pray in full; many others say all pilgrims shorten in Mina, Arafah and Muzdalifah. Follow your group''s scholar."}}, {"type": "heading", "text": {"bn": "৯ জিলহজ: আরাফার দিন", "en": "9 Dhul Hijjah: the day of Arafah"}}, {"type": "step", "title": {"bn": "আরাফায় যাওয়া", "en": "Go to Arafah"}, "text": {"bn": "সূর্যোদয়ের পর তালবিয়া পড়তে পড়তে আরাফার দিকে রওনা হোন। আরাফার সীমানা নির্দেশক বোর্ড দেখে নিশ্চিত হোন যে আপনি সীমার ভেতরে আছেন; উরানা উপত্যকা আরাফার অংশ নয়।", "en": "After sunrise set off for Arafah saying the talbiyah. Check the boundary signs to be sure you are inside Arafah; the valley of ''Uranah is not part of it."}}, {"type": "step", "title": {"bn": "অবস্থান (উকুফ)", "en": "The standing (wuquf)"}, "text": {"bn": "জাওয়াল (দুপুরে সূর্য হেলে পড়া) থেকে সূর্যাস্ত পর্যন্ত আরাফায় অবস্থান করুন। দাঁড়িয়ে, বসে, শুয়ে যেকোনোভাবে থাকা যায়; সময়টা কাটান দোয়া, জিকির, ইস্তিগফার, তালবিয়া ও কুরআন তিলাওয়াতে, কিবলামুখী হয়ে হাত তুলে দোয়া করুন।", "en": "Stay at Arafah from zawal (just after midday) until sunset. You may stand, sit or lie down; spend the time in dua, dhikr, seeking forgiveness, talbiyah and Quran, facing the qiblah with hands raised in dua."}}, {"type": "step", "title": {"bn": "জোহর ও আসর", "en": "Zuhr and Asr"}, "text": {"bn": "মসজিদে নামিরায় ইমামের সঙ্গে জোহর ও আসর জোহরের ওয়াক্তে একসাথে পড়া হয়।", "en": "At Masjid Namirah, Zuhr and Asr are prayed together in Zuhr time with the imam."}}, {"type": "note", "tone": "info", "text": {"bn": "তাঁবুতে আলাদা জামাতে জোহর-আসর একসাথে পড়া যাবে কি না, তা নিয়ে মতভেদ আছে: ইমাম আবু হানিফার মতে একসাথে পড়ার শর্ত হজের ইমামের সঙ্গে পড়া, নইলে প্রতিটি নিজ ওয়াক্তে; অন্য মাজহাব ও হানাফি সাহিবাইনের মতে তাঁবুতেও একসাথে পড়া যায়।", "en": "Scholars differ on combining Zuhr and Asr in separate congregations in the tents: for Imam Abu Hanifa combining requires praying with the hajj imam, otherwise each is prayed in its time; the other schools and Abu Hanifa''s two students allow combining in the tents."}}, {"type": "arabic", "label": {"bn": "আরাফার দিনের শ্রেষ্ঠ দোয়া", "en": "The best dua on the day of Arafah"}, "ar": "لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ", "pron": {"bn": "লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারীকা লাহু, লাহুল মুলকু ওয়া লাহুল হামদু, ওয়া হুয়া আলা কুল্লি শাইয়িন কাদীর", "en": "La ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamd, wa huwa ''ala kulli shay''in qadir"}, "meaning": {"bn": "আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি এক, তাঁর কোনো শরিক নেই। রাজত্ব তাঁরই, প্রশংসাও তাঁর, তিনি সবকিছুর ওপর ক্ষমতাবান।", "en": "There is no god but Allah alone, without partner. His is the dominion and His is the praise, and He has power over all things."}, "ref": {"bn": "জামে তিরমিজি ৩৫৮৫", "en": "Jami'' at-Tirmidhi 3585"}}, {"type": "note", "tone": "tip", "text": {"bn": "নবী (সা.) বলেছেন, সর্বোত্তম দোয়া আরাফার দিনের দোয়া, আর তিনি ও পূর্ববর্তী নবীগণ যা বলেছেন তার মধ্যে শ্রেষ্ঠ এই বাক্য। নিজের ভাষায় নিজের, পরিবারের ও উম্মাহর জন্য মন খুলে দোয়া করুন। জাবালে রহমত পাহাড়ে ওঠা জরুরি নয়; আরাফার যেকোনো স্থানে অবস্থানই যথেষ্ট।", "en": "The Prophet said the best dua is the dua of the day of Arafah, and the best words he and the prophets before him said are these. Pray from the heart in your own language for yourself, your family and the ummah. Climbing Jabal ar-Rahmah is not required; anywhere within Arafah is enough."}}, {"type": "ref", "text": {"bn": "জামে তিরমিজি ৮৮৯; সহিহ মুসলিম ১২১৮", "en": "Jami'' at-Tirmidhi 889; Sahih Muslim 1218"}}, {"type": "note", "tone": "warn", "text": {"bn": "সূর্যাস্তের আগে আরাফার সীমা থেকে বের হবেন না। হানাফি মতে দিনে আরাফায় পৌঁছালে সূর্যাস্ত পর্যন্ত থাকা ওয়াজিব; আগে বের হয়ে গেলে দম দিতে হয়।", "en": "Do not leave Arafah before sunset. For Hanafis, someone who reaches Arafah in the day must stay until sunset; leaving earlier requires a dam."}}, {"type": "heading", "text": {"bn": "৯ জিলহজের রাত: মুজদালিফা", "en": "The night of the 9th: Muzdalifah"}}, {"type": "step", "title": {"bn": "মুজদালিফায় যাওয়া", "en": "Go to Muzdalifah"}, "text": {"bn": "সূর্যাস্তের পর মাগরিব না পড়ে শান্তভাবে তালবিয়া ও জিকির করতে করতে মুজদালিফায় যান।", "en": "After sunset, go calmly to Muzdalifah saying the talbiyah and dhikr, without praying Maghrib at Arafah."}}, {"type": "step", "title": {"bn": "মাগরিব ও এশা", "en": "Maghrib and Isha"}, "text": {"bn": "মুজদালিফায় পৌঁছে এশার ওয়াক্তে মাগরিব ও এশা একসাথে আদায় করুন (মাগরিব তিন রাকাত, এশা দুই বা চার রাকাত, কসরের বিধান অনুযায়ী)।", "en": "At Muzdalifah pray Maghrib and Isha together in Isha time (Maghrib three rakats, Isha two or four depending on the rule of shortening)."}}, {"type": "step", "title": {"bn": "রাত যাপন ও কংকর", "en": "Night and pebbles"}, "text": {"bn": "এখানে খোলা আকাশের নিচে রাত কাটানো সুন্নত। ১০ তারিখের জন্য ৭টি (বা সব দিনের জন্য ৪৯/৭০টি) ছোলার দানার মতো ছোট কংকর এখান থেকে বা মিনা থেকে সংগ্রহ করা যায়।", "en": "Spending the night here in the open is sunnah. Pebbles the size of a chickpea, 7 for the 10th (or 49/70 for all days), may be collected here or in Mina."}}, {"type": "step", "title": {"bn": "ফজর ও উকুফ", "en": "Fajr and the standing"}, "text": {"bn": "ফজরের ওয়াক্ত শুরু হলেই ফজর পড়ে মাশআরুল হারামের কাছে বা মুজদালিফার যেকোনো স্থানে কিবলামুখী হয়ে আকাশ বেশ ফরসা হওয়া পর্যন্ত দোয়া-জিকির করুন, তারপর সূর্যোদয়ের আগে মিনার দিকে রওনা দিন।", "en": "Pray Fajr as soon as its time begins, then at Al-Mash''ar al-Haram or anywhere in Muzdalifah face the qiblah and make dua and dhikr until it is quite light, then set off for Mina before sunrise."}}, {"type": "arabic", "ar": "فَإِذَا أَفَضْتُمْ مِنْ عَرَفَاتٍ فَاذْكُرُوا اللَّهَ عِنْدَ الْمَشْعَرِ الْحَرَامِ", "pron": {"bn": "ফাইযা আফাদতুম মিন আরাফাতিন ফাযকুরুল্লাহা ইনদাল মাশআরিল হারাম", "en": "Fa idha afadtum min ''arafatin fadhkurullaha ''indal-mash''aril-haram"}, "meaning": {"bn": "যখন তোমরা আরাফা থেকে ফিরে আসবে, তখন মাশআরুল হারামের কাছে আল্লাহকে স্মরণ করো।", "en": "When you pour down from Arafat, remember Allah at Al-Mash''ar al-Haram."}, "ref": {"bn": "সূরা বাকারা ২:১৯৮", "en": "Al-Baqarah 2:198"}}, {"type": "differ", "title": {"bn": "মুজদালিফায় অবস্থানের ওয়াজিব অংশ", "en": "The obligatory part of Muzdalifah"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "সুবহে সাদিক থেকে সূর্যোদয়ের মধ্যে অল্প সময় হলেও মুজদালিফায় থাকা ওয়াজিব; রাত যাপন সুন্নত। দুর্বল, অসুস্থ ও নারীরা ভিড়ের ভয়ে আগে চলে গেলে দম লাগে না।", "en": "Being in Muzdalifah for any time between true dawn and sunrise is obligatory; spending the night is sunnah. The weak, sick and women who leave early for fear of crowds owe no dam."}, "evidence": {"bn": "নবী (সা.) ফজরের পর মাশআরুল হারামে অবস্থান করেছেন; দুর্বলদের রাতেই পাঠিয়ে দিয়েছেন।", "en": "The Prophet stood at Al-Mash''ar al-Haram after Fajr and sent the weak ahead at night."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি", "en": "Shafi''i and Hanbali"}, "text": {"bn": "মধ্যরাতের পর কিছু সময় মুজদালিফায় থাকা ওয়াজিব; মধ্যরাতের পর চলে যাওয়া জায়েজ, বিশেষ করে দুর্বলদের জন্য।", "en": "Being in Muzdalifah for some time after midnight is obligatory; leaving after midnight is allowed, especially for the weak."}, "evidence": {"bn": "সাওদা (রা.) ও আসমা (রা.)-কে রাতেই মুজদালিফা ছাড়ার অনুমতি দেওয়ার বর্ণনা।", "en": "Reports that Sawdah and Asma'' were allowed to leave Muzdalifah during the night."}}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি; সহিহ মুসলিম (সাওদা রা.-কে রাতেই মুজদালিফা ছাড়ার অনুমতি)", "en": "Sahih al-Bukhari; Sahih Muslim (Sawdah allowed to leave Muzdalifah at night)"}, "check": true}]', 'in_review', 40 FROM is_guide_topics WHERE slug = 'hajj' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'a25de849-edc5-5a9e-a4c6-7781ebc14365', id, 'hajj-days-10-13', '{"bn": "হজের দিন: ১০ থেকে ১৩ জিলহজ", "en": "Hajj days 10–13 Dhul Hijjah"}', '{"bn": "ঈদের দিনের চার কাজ (কংকর, কুরবানি, মুণ্ডন, তাওয়াফ), মিনার দিনগুলো এবং বিদায়ী তাওয়াফ।", "en": "The four acts of Eid day (stoning, sacrifice, shaving, tawaf), the days in Mina and the farewell tawaf."}', 'detail', '[{"type": "heading", "text": {"bn": "১০ জিলহজ: ইয়াওমুন নাহর (কুরবানির দিন)", "en": "10 Dhul Hijjah: Yawm an-Nahr (day of sacrifice)"}}, {"type": "step", "title": {"bn": "জামরাতুল আকাবায় কংকর", "en": "Stone Jamrat al-Aqabah"}, "text": {"bn": "মিনায় পৌঁছে শুধু বড় জামরায় (জামরাতুল আকাবা) একে একে সাতটি কংকর মারুন; প্রতিটির সাথে ''আল্লাহু আকবার'' বলুন। প্রথম কংকর মারার সঙ্গে সঙ্গে তালবিয়া বন্ধ। এদিনের কংকর মারার সুন্নত সময় সূর্যোদয় থেকে জাওয়াল পর্যন্ত, তবে পরেও জায়েজ।", "en": "In Mina stone only the big jamrah (Jamrat al-Aqabah) with seven pebbles one by one, saying ''Allahu akbar'' with each. Talbiyah stops with the first pebble. The sunnah time for this day is from sunrise to zawal, though later is permitted."}}, {"type": "arabic", "label": {"bn": "প্রতিটি কংকর মারার সময়", "en": "With each pebble"}, "ar": "اللَّهُ أَكْبَرُ", "pron": {"bn": "আল্লাহু আকবার", "en": "Allahu akbar"}, "meaning": {"bn": "আল্লাহ সবচেয়ে মহান।", "en": "Allah is the Greatest."}, "ref": {"bn": "সহিহ বুখারি (ইবনে উমর রা.-এর বর্ণনা)", "en": "Sahih al-Bukhari (narration of Ibn Umar)"}, "check": true}, {"type": "step", "title": {"bn": "কুরবানি (হাদি)", "en": "Sacrifice (hady)"}, "text": {"bn": "তামাত্তু ও কিরান হাজির জন্য কুরবানি ওয়াজিব; ইফরাদ হাজির জন্য ঐচ্ছিক। সাধারণত ব্যাংক বা অনুমোদিত সংস্থার মাধ্যমে কুপন কেনা হয়; কুরবানি কখন হলো, তা নিশ্চিত হয়ে নিন, কারণ এরপরই মাথা মুণ্ডন করবেন।", "en": "The sacrifice is required for tamattu'' and qiran pilgrims and optional for ifrad. It is usually arranged by buying a voucher through a bank or approved body; confirm when it is done, since you shave after it."}}, {"type": "step", "title": {"bn": "মাথা মুণ্ডন বা চুল ছোট করা", "en": "Shave or shorten the hair"}, "text": {"bn": "পুরুষের জন্য পুরো মাথা মুণ্ডন (হলক) উত্তম, অথবা চুল ছোট করা (কসর)। নারীরা চুলের আগা থেকে আঙুলের এক কর পরিমাণ কাটবেন। এরপর স্ত্রী-সংক্রান্ত বিষয় ছাড়া ইহরামের সব নিষেধ উঠে যায় (প্রথম হালাল)।", "en": "For men, shaving the whole head (halq) is better, or shortening (qasr). Women cut a fingertip''s length from the ends. After this everything forbidden by ihram becomes lawful except marital matters (first release)."}}, {"type": "step", "title": {"bn": "তাওয়াফে জিয়ারত (ইফাদা)", "en": "Tawaf al-Ifadah (ziyarah)"}, "text": {"bn": "মক্কায় গিয়ে হজের ফরজ তাওয়াফ করুন। ১০ তারিখে করা উত্তম; হানাফি মতে ১২ জিলহজের সূর্যাস্তের আগে করতে হবে, বিনা ওজরে দেরি করলে দম। তামাত্তু হাজিরা এরপর সাফা-মারওয়ায় সাঈ করবেন; কিরান/ইফরাদ হাজি আগে তাওয়াফে কুদুমের পর সাঈ করে থাকলে আবার লাগবে না।", "en": "Go to Makkah and perform the obligatory tawaf of hajj. The 10th is best; for Hanafis it must be done before sunset on the 12th, otherwise a dam is due without excuse. Tamattu'' pilgrims then do sa''i; qiran/ifrad pilgrims who did sa''i after tawaf al-qudum need not repeat it."}}, {"type": "note", "tone": "info", "text": {"bn": "তাওয়াফে জিয়ারতের পর স্বামী-স্ত্রীর সম্পর্কসহ ইহরামের সব নিষেধ উঠে যায় (দ্বিতীয় হালাল)। তারপর মিনায় ফিরে রাত কাটাবেন।", "en": "After tawaf al-ifadah all ihram restrictions, including marital relations, are lifted (second release). Then return to Mina for the night."}}, {"type": "differ", "title": {"bn": "১০ তারিখের কাজগুলোর ধারাবাহিকতা", "en": "The order of the acts of the 10th"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "তামাত্তু ও কিরান হাজির জন্য কংকর → কুরবানি → মুণ্ডন এই ধারাবাহিকতা ওয়াজিব; উল্টাপাল্টা হলে ইমাম আবু হানিফার মতে দম দিতে হবে। (ইফরাদ হাজির কুরবানি নেই; তার জন্য কংকরের পর মুণ্ডন।)", "en": "For tamattu'' and qiran pilgrims the order stoning → sacrifice → shaving is obligatory; breaking it requires a dam per Imam Abu Hanifa. (Ifrad has no sacrifice; stoning then shaving.)"}, "evidence": {"bn": "নবী (সা.) এই ক্রমে করেছেন এবং বলেছেন, ''তোমাদের হজের নিয়ম আমার কাছ থেকে শিখে নাও।''", "en": "The Prophet did them in this order and said, ''Take your rites from me.''"}}, {"label": {"bn": "শাফেয়ি, হাম্বলি, হানাফি সাহিবাইন", "en": "Shafi''i, Hanbali, Abu Hanifa''s two students"}, "text": {"bn": "ক্রম মানা সুন্নত; আগে-পরে হয়ে গেলে কোনো দম নেই।", "en": "Keeping the order is sunnah; doing them out of order requires no dam."}, "evidence": {"bn": "১০ তারিখে আগে-পরে করার প্রশ্ন এলে নবী (সা.) বলতেন, ''করে ফেলো, কোনো সমস্যা নেই।''", "en": "On the 10th, when asked about doing things out of order, the Prophet said, ''Do it, there is no harm.''"}}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৭৩৬; সহিহ মুসলিম ১৩০৬; সহিহ মুসলিম ১২৯৭", "en": "Sahih al-Bukhari 1736; Sahih Muslim 1306; Sahih Muslim 1297"}}, {"type": "heading", "text": {"bn": "১১ ও ১২ জিলহজ: আইয়ামে তাশরিক", "en": "11 and 12 Dhul Hijjah: days of Tashriq"}}, {"type": "step", "title": {"bn": "মিনায় রাত যাপন", "en": "Nights in Mina"}, "text": {"bn": "১১ ও ১২ তারিখের রাত (অধিকাংশ সময়) মিনায় কাটাবেন।", "en": "Spend (most of) the nights of the 11th and 12th in Mina."}}, {"type": "step", "title": {"bn": "তিন জামরায় কংকর", "en": "Stone the three jamarat"}, "text": {"bn": "জাওয়ালের (দুপুরের) পর প্রথমে ছোট জামরা (জামরাতুল উলা), তারপর মধ্যম (উসতা), তারপর বড় (আকাবা) — প্রতিটিতে সাতটি করে কংকর, প্রতিবার ''আল্লাহু আকবার''।", "en": "After zawal (midday), stone first the small jamrah (Ula), then the middle (Wusta), then the big (Aqabah), seven pebbles each, saying ''Allahu akbar'' each time."}}, {"type": "step", "title": {"bn": "দোয়া", "en": "Dua"}, "text": {"bn": "ছোট ও মধ্যম জামরায় কংকর মারার পর একটু সরে কিবলামুখী হয়ে হাত তুলে দীর্ঘ সময় দোয়া করুন। বড় জামরার পর দোয়ার জন্য না দাঁড়িয়ে চলে যান।", "en": "After the small and middle jamrah, step aside, face the qiblah, raise your hands and make a long dua. After the big jamrah, leave without stopping for dua."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি (ইবনে উমর রা.-এর বর্ণনা: প্রতি কংকরে তাকবির ও প্রথম দুই জামরার পর দোয়া)", "en": "Sahih al-Bukhari (Ibn Umar: takbir with each pebble and dua after the first two jamarat)"}, "check": true}, {"type": "differ", "title": {"bn": "মিনায় রাত যাপনের হুকুম", "en": "Ruling on staying the nights in Mina"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "সুন্নত; ছেড়ে দিলে দম নেই, তবে বিনা কারণে ছাড়া মাকরুহ।", "en": "Sunnah; no dam if missed, but missing it without reason is disliked."}, "evidence": {"bn": "নবী (সা.) আব্বাস (রা.)-কে হাজিদের পানি পান করানোর জন্য মক্কায় রাত কাটানোর অনুমতি দিয়েছিলেন।", "en": "The Prophet allowed Abbas to spend the nights in Makkah to provide water for the pilgrims."}}, {"label": {"bn": "শাফেয়ি, মালেকি, হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "ওয়াজিব; বিনা ওজরে ছাড়লে দম বা সদকা।", "en": "Obligatory; missing it without excuse requires a dam or charity."}, "evidence": {"bn": "আব্বাস (রা.)-কে আলাদাভাবে অনুমতি দেওয়াই প্রমাণ করে যে অন্যদের জন্য এটি জরুরি।", "en": "Giving Abbas a special permission shows it is required of others."}}]}, {"type": "heading", "text": {"bn": "১২ বা ১৩ তারিখে মিনা ত্যাগ", "en": "Leaving Mina on the 12th or 13th"}}, {"type": "arabic", "ar": "فَمَنْ تَعَجَّلَ فِي يَوْمَيْنِ فَلَا إِثْمَ عَلَيْهِ وَمَنْ تَأَخَّرَ فَلَا إِثْمَ عَلَيْهِ لِمَنِ اتَّقَىٰ", "pron": {"bn": "ফামান তাআজ্জালা ফী ইয়াওমাইনি ফালা ইসমা আলাইহি, ওয়া মান তাআখখারা ফালা ইসমা আলাইহি লিমানিত্তাকা", "en": "Faman ta''ajjala fi yawmayni fala ithma ''alayh, wa man ta''akhkhara fala ithma ''alayh, limanittaqa"}, "meaning": {"bn": "যে দুই দিনে তাড়াতাড়ি চলে যায়, তার কোনো গুনাহ নেই; আর যে দেরি করে, তারও কোনো গুনাহ নেই — যে তাকওয়া অবলম্বন করে তার জন্য।", "en": "Whoever hastens in two days, there is no sin on him; and whoever delays, there is no sin on him — for one who is mindful of Allah."}, "ref": {"bn": "সূরা বাকারা ২:২০৩", "en": "Al-Baqarah 2:203"}}, {"type": "text", "text": {"bn": "১২ তারিখে কংকর মারার পর সূর্যাস্তের আগে মিনা ছেড়ে যেতে পারেন। মিনায় থাকা অবস্থায় সূর্য ডুবে গেলে ১৩ তারিখও থেকে তিন জামরায় কংকর মারা উত্তম (হানাফি মতে ১৩ তারিখের সুবহে সাদিকের আগে চলে যাওয়া জায়েজ, তবে মাকরুহ; অন্য মাজহাবে সূর্যাস্তের পর থেকে যাওয়া আবশ্যক)।", "en": "After stoning on the 12th you may leave Mina before sunset. If the sun sets while you are still in Mina, it is better to stay the 13th and stone the three jamarat (Hanafis allow leaving before dawn of the 13th, though disliked; the other schools require staying once the sun has set)."}}, {"type": "note", "tone": "warn", "text": {"bn": "কংকর মারা নিজেকেই করতে হবে। অসুস্থ, অতি বৃদ্ধ বা প্রকৃত অক্ষম হলে অন্য কাউকে প্রতিনিধি বানানো যায়, যিনি আগে নিজের কংকর মেরে তারপর তার পক্ষ থেকে মারবেন। শুধু ভিড় এড়াতে সুস্থ ব্যক্তির প্রতিনিধি দেওয়া জায়েজ নয়।", "en": "You must do the stoning yourself. The sick, very elderly or truly unable may appoint someone, who first stones for himself and then for them. A healthy person may not delegate just to avoid the crowd."}}, {"type": "heading", "text": {"bn": "বিদায়ী তাওয়াফ (তাওয়াফুল বিদা)", "en": "The farewell tawaf (tawaf al-wada'')"}}, {"type": "text", "text": {"bn": "মক্কা ছেড়ে নিজ দেশে ফেরার আগে বাইরের হাজিদের শেষ কাজ হবে বায়তুল্লাহর তাওয়াফ। এটি হানাফি, শাফেয়ি ও হাম্বলি মতে ওয়াজিব (মালেকি মতে সুন্নত)। হায়েজ-নিফাস অবস্থায় থাকা নারীদের জন্য এটি মাফ।", "en": "Before leaving Makkah for home, the last act of pilgrims from outside is a tawaf of the House. It is obligatory for Hanafis, Shafi''is and Hanbalis (sunnah for Malikis). Women in menstruation or post-natal bleeding are excused from it."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৭৫৫; সহিহ মুসলিম ১৩২৮", "en": "Sahih al-Bukhari 1755; Sahih Muslim 1328"}}]', 'in_review', 50 FROM is_guide_topics WHERE slug = 'hajj' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'fc704b4d-be52-5855-b12a-8ea631437225', id, 'hajj-farz-wajib-sunnah', '{"bn": "হজের ফরজ, ওয়াজিব ও সুন্নত", "en": "Farz, wajib and sunnah acts of hajj"}', '{"bn": "কোন কাজ ছুটলে হজ হবে না, কোনটায় দম লাগবে, আর কোনটা সুন্নত; মাজহাবগুলোর পার্থক্যসহ।", "en": "Which omissions invalidate hajj, which need a dam, and which are sunnah; with the differences between schools."}', 'detail', '[{"type": "text", "text": {"bn": "হজের কাজগুলো তিন স্তরের। ফরজ বা রুকন ছুটে গেলে হজ হবে না। ওয়াজিব ছুটে গেলে হজ হবে, তবে দম (একটি পশু কুরবানি) দিতে হবে। সুন্নত ছুটলে দম নেই, তবে সওয়াব কমে।", "en": "The acts of hajj have three levels. If a farz (pillar) is missed, the hajj is not valid. If a wajib is missed, the hajj is valid but a dam (animal sacrifice) is due. If a sunnah is missed, there is no penalty but reward is lost."}}, {"type": "heading", "text": {"bn": "হানাফি মাজহাব অনুযায়ী", "en": "According to the Hanafi school"}}, {"type": "table", "head": [{"bn": "স্তর", "en": "Level"}, {"bn": "কাজ", "en": "Acts"}], "rows": [[{"bn": "ফরজ", "en": "Farz"}, {"bn": "১. ইহরাম (শর্ত) ২. ৯ জিলহজ জাওয়াল থেকে ১০ তারিখের সুবহে সাদিকের মধ্যে আরাফায় অবস্থান ৩. তাওয়াফে জিয়ারত", "en": "1. Ihram (a condition) 2. Being at Arafah between zawal on the 9th and dawn on the 10th 3. Tawaf al-ziyarah"}], [{"bn": "ওয়াজিব", "en": "Wajib"}, {"bn": "মিকাত থেকে ইহরাম; দিনে পৌঁছালে সূর্যাস্ত পর্যন্ত আরাফায় থাকা; মুজদালিফায় অবস্থান; সাফা-মারওয়ার সাঈ; কংকর মারা; মুণ্ডন বা চুল ছোট করা; তামাত্তু-কিরানে কুরবানি ও ১০ তারিখের ক্রম; নির্দিষ্ট সময়ে তাওয়াফে জিয়ারত; বাইরের হাজির জন্য বিদায়ী তাওয়াফ", "en": "Ihram from the miqat; staying at Arafah till sunset if arrived by day; Muzdalifah; sa''i between Safa and Marwah; stoning; shaving or shortening; sacrifice and the order of the 10th for tamattu''/qiran; tawaf al-ziyarah in its time; farewell tawaf for those from outside"}], [{"bn": "সুন্নত (কয়েকটি)", "en": "Sunnah (some)"}, {"bn": "ইহরামের গোসল; ইফরাদ ও কিরানে তাওয়াফে কুদুম; ৮ তারিখ মিনায় রাত যাপন; মুজদালিফায় রাত যাপন; মিনায় তাশরিকের রাতগুলো কাটানো; প্রথম তিন চক্করে রমল ও ইজতিবা (পুরুষ)", "en": "Ghusl for ihram; tawaf al-qudum in ifrad and qiran; the night of the 8th in Mina; the night in Muzdalifah; the nights of Tashriq in Mina; ramal and idtiba'' in the first three rounds (men)"}]]}, {"type": "differ", "title": {"bn": "হজের রুকন কয়টি", "en": "How many pillars does hajj have"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "রুকন দুটি: আরাফায় অবস্থান ও তাওয়াফে জিয়ারত; ইহরাম শর্ত। সাঈ ওয়াজিব।", "en": "Two pillars: standing at Arafah and tawaf al-ziyarah; ihram is a condition. Sa''i is wajib."}, "evidence": {"bn": "হাদিস: ''হজ হলো আরাফা''; আয়াত: ''তারা যেন প্রাচীন ঘরের তাওয়াফ করে'' (২২:২৯)। সাঈর আয়াতে ''কোনো দোষ নেই'' বলা হয়েছে, যা রুকন হওয়ার ইঙ্গিত দেয় না।", "en": "Hadith: ''Hajj is Arafah''; verse: ''let them circle the Ancient House'' (22:29). The sa''i verse says ''there is no blame'', which does not indicate a pillar."}}, {"label": {"bn": "শাফেয়ি", "en": "Shafi''i"}, "text": {"bn": "রুকন ছয়টি: ইহরাম, আরাফায় অবস্থান, তাওয়াফে ইফাদা, সাঈ, মুণ্ডন/চুল ছোট করা, এবং বেশির ভাগ রুকনে ক্রম।", "en": "Six pillars: ihram, Arafah, tawaf al-ifadah, sa''i, shaving/shortening, and order among most of them."}, "evidence": {"bn": "নবী (সা.)-এর আমল ও নির্দেশ, এবং মুসনাদে আহমাদের হাদিস: ''আল্লাহ তোমাদের ওপর সাঈ নির্ধারণ করেছেন, তাই সাঈ করো।''", "en": "The Prophet''s practice and command, and the hadith in Musnad Ahmad: ''Allah has prescribed sa''i for you, so do sa''i.''"}}, {"label": {"bn": "মালেকি ও হাম্বলি", "en": "Maliki and Hanbali"}, "text": {"bn": "রুকন চারটি: ইহরাম, আরাফায় অবস্থান, তাওয়াফে ইফাদা ও সাঈ।", "en": "Four pillars: ihram, Arafah, tawaf al-ifadah and sa''i."}, "evidence": {"bn": "একই দলিল; মুণ্ডনকে তারা ওয়াজিব গণ্য করেন, রুকন নয়।", "en": "The same evidence; they count shaving as wajib, not a pillar."}}]}, {"type": "ref", "text": {"bn": "জামে তিরমিজি ৮৮৯; সূরা হজ ২২:২৯; সূরা বাকারা ২:১৫৮", "en": "Jami'' at-Tirmidhi 889; Al-Hajj 22:29; Al-Baqarah 2:158"}}, {"type": "note", "tone": "tip", "text": {"bn": "কোনো কাজ ছুটে গেছে বা ভুল হয়েছে মনে হলে অনুমান করবেন না; সঙ্গে সঙ্গে কাফেলার আলেমকে জিজ্ঞেস করুন। দম অবশ্যই হারামের সীমার ভেতরে দিতে হয়।", "en": "If you think you missed or got something wrong, do not guess; ask your group''s scholar at once. A dam must be slaughtered within the Haram."}}]', 'in_review', 60 FROM is_guide_topics WHERE slug = 'hajj' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '5feb6ec9-fa69-5abb-af16-7dd4811b1816', id, 'hajj-women', '{"bn": "নারীদের হজ: বিশেষ বিধান", "en": "Women''s hajj: special rulings"}', '{"bn": "মাহরাম, ইহরামের পোশাক, হায়েজ অবস্থায় হজ এবং নারীদের জন্য আলাদা নিয়মগুলো।", "en": "Mahram, ihram clothing, hajj during menstruation and the rules that differ for women."}', 'basic', '[{"type": "heading", "text": {"bn": "মাহরাম", "en": "Mahram"}}, {"type": "differ", "title": {"bn": "মাহরাম ছাড়া নারীর ফরজ হজ", "en": "A woman''s obligatory hajj without a mahram"}, "views": [{"label": {"bn": "হানাফি ও হাম্বলি", "en": "Hanafi and Hanbali"}, "text": {"bn": "সফরের দূরত্বে স্বামী বা মাহরাম সঙ্গে থাকা হজ ফরজ হওয়ার (বা আদায়ের) শর্ত; মাহরাম না পেলে তার ওপর নিজে যাওয়া আবশ্যক নয়।", "en": "A husband or mahram accompanying her over the travel distance is a condition for hajj; if she finds none she is not required to go herself."}, "evidence": {"bn": "হাদিস: ''কোনো নারী মাহরাম ছাড়া সফর করবে না।'' এক সাহাবি বললেন, আমার স্ত্রী হজে যাচ্ছে; নবী (সা.) বললেন, ''যাও, তোমার স্ত্রীর সাথে হজ করো।''", "en": "Hadith: ''A woman must not travel except with a mahram.'' A man said his wife was going for hajj; the Prophet said, ''Go and perform hajj with your wife.''"}}, {"label": {"bn": "শাফেয়ি ও মালেকি", "en": "Shafi''i and Maliki"}, "text": {"bn": "ফরজ হজের জন্য নির্ভরযোগ্য নারীদের দল বা নিরাপদ কাফেলা থাকলে মাহরাম ছাড়াও যাওয়া জায়েজ।", "en": "For the obligatory hajj, she may go without a mahram in a trustworthy group of women or a safe caravan."}, "evidence": {"bn": "উমর (রা.) নবীপত্নীদের উসমান (রা.) ও আবদুর রহমান ইবনে আওফ (রা.)-এর তত্ত্বাবধানে হজে পাঠিয়েছিলেন; এবং নিরাপত্তা প্রতিষ্ঠিত হলে নারী একা হিরা থেকে কাবা পর্যন্ত সফর করবে — এ ভবিষ্যদ্বাণীর হাদিস (সহিহ বুখারি)।", "en": "Umar sent the Prophet''s wives for hajj under the care of Uthman and Abd al-Rahman ibn Awf; and the hadith foretelling that a woman would travel safely alone from Hira to the Ka''bah (Sahih al-Bukhari)."}}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৮৬২; সহিহ মুসলিম ১৩৪১", "en": "Sahih al-Bukhari 1862; Sahih Muslim 1341"}}, {"type": "heading", "text": {"bn": "ইহরামের পোশাক", "en": "Clothing in ihram"}}, {"type": "list", "items": [{"bn": "যেকোনো রঙের শালীন, ঢিলেঢালা সাধারণ পোশাক পরবেন; সাদা হওয়া জরুরি নয়।", "en": "Wear ordinary modest, loose clothes of any colour; white is not required."}, {"bn": "মুখে নিকাব (মুখের সাথে লাগানো নেকাব) ও হাতে মোজা পরবেন না; পায়ে মোজা ও জুতা পরা যায়।", "en": "Do not wear a niqab fitted to the face or gloves; socks and shoes are allowed."}, {"bn": "পরপুরুষ কাছে এলে মাথার ওপর থেকে কাপড় ঝুলিয়ে মুখ আড়াল করতে পারেন, যেমন সাহাবি নারীরা করতেন; কাপড় মুখে লেগে থাকা থেকে যথাসম্ভব বাঁচবেন।", "en": "When unrelated men come near, you may let cloth hang from the head to screen the face, as the women Companions did; try to keep it from clinging to the face."}, {"bn": "মাথার চুল সবসময় ঢাকা থাকবে; ইহরামে নারীর মাথা খোলা রাখার কোনো বিধান নেই।", "en": "The hair stays covered at all times; there is no rule for a woman to uncover her head in ihram."}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৮৩৮", "en": "Sahih al-Bukhari 1838"}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ (আয়েশা রা.-এর বর্ণনা: কাফেলা কাছে এলে মুখের ওপর কাপড় ঝুলিয়ে দেওয়া)", "en": "Sunan Abi Dawud (Aishah: lowering cloth over the face when riders passed)"}, "check": true}, {"type": "heading", "text": {"bn": "হায়েজ বা নিফাস অবস্থায়", "en": "During menstruation or post-natal bleeding"}}, {"type": "list", "items": [{"bn": "ইহরাম বাঁধা যায় (গোসল করে নিয়ত ও তালবিয়া), শুধু ইহরামের নামাজ পড়বেন না।", "en": "She may enter ihram (ghusl, intention and talbiyah), only without the ihram prayer."}, {"bn": "আরাফা, মুজদালিফা, মিনা, কংকর মারা, দোয়া-জিকির সবই করবেন; শুধু পবিত্র না হওয়া পর্যন্ত তাওয়াফ করবেন না এবং মসজিদে প্রবেশ করবেন না।", "en": "She does everything — Arafah, Muzdalifah, Mina, stoning, dua and dhikr — except tawaf and entering the masjid until she is pure."}, {"bn": "তাওয়াফে জিয়ারত পবিত্র হওয়ার পর করবেন; এর জন্য দেরি হলে কোনো দম নেই।", "en": "She performs tawaf al-ifadah after becoming pure; there is no penalty for the delay."}, {"bn": "দেশে ফেরার আগে পবিত্র না হলে বিদায়ী তাওয়াফ তার জন্য মাফ।", "en": "If she is not pure before leaving for home, the farewell tawaf is waived for her."}, {"bn": "তামাত্তুর উমরাহ শেষ করার আগে হায়েজ শুরু হলে এবং ৮ তারিখের আগে পবিত্র না হলে আলেমের পরামর্শে হজের নিয়ত যোগ করবেন (কিরানে রূপান্তর বা অন্য বিধান মাজহাব অনুযায়ী ভিন্ন)।", "en": "If her period starts before finishing the tamattu'' umrah and she is not pure by the 8th, she adds the hajj intention on a scholar''s advice (converting to qiran or another ruling, depending on the school)."}, {"bn": "তাওয়াফে জিয়ারত না করে দেশে ফিরে যাওয়ার পরিস্থিতি হলে অবশ্যই আলেমের সাথে পরামর্শ করবেন; এটি হজের রুকন।", "en": "If she faces having to leave without tawaf al-ifadah, she must consult a scholar; it is a pillar of hajj."}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৩০৫; সহিহ বুখারি ১৭৫৫", "en": "Sahih al-Bukhari 305; Sahih al-Bukhari 1755"}}, {"type": "note", "tone": "info", "text": {"bn": "স্বাস্থ্যের ক্ষতি না হলে চিকিৎসকের পরামর্শে ওষুধ খেয়ে হজের সময় মাসিক পিছিয়ে রাখা অনেক আলেমের মতে জায়েজ।", "en": "Many scholars allow delaying the period during hajj with medicine on a doctor''s advice, if it causes no harm."}}, {"type": "heading", "text": {"bn": "অন্যান্য পার্থক্য", "en": "Other differences"}}, {"type": "list", "items": [{"bn": "তালবিয়া নিচু স্বরে পড়বেন, যাতে শুধু নিজে বা পাশের জন শোনে।", "en": "Say the talbiyah quietly, so only you or the person beside you hears."}, {"bn": "তাওয়াফে রমল (দ্রুত হাঁটা) ও ইজতিবা নেই; সাঈতে সবুজ বাতির মাঝে দৌড়াবেন না।", "en": "No ramal or idtiba'' in tawaf; do not jog between the green lights in sa''i."}, {"bn": "মাথা মুণ্ডন করবেন না; সব চুলের আগা থেকে আঙুলের এক কর (প্রায় এক ইঞ্চি) পরিমাণ কাটবেন।", "en": "Do not shave the head; cut about a fingertip''s length (about an inch) from the ends of the hair."}, {"bn": "ভিড়ের মধ্যে হাজরে আসওয়াদ চুম্বন করতে যাবেন না; দূর থেকে ইশারা করাই যথেষ্ট।", "en": "Do not push into crowds to kiss the Black Stone; pointing from a distance is enough."}, {"bn": "ইদ্দত পালনরত নারী সেই সময়ে হজে যাবেন না।", "en": "A woman in her ''iddah does not set out for hajj during it."}]}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ (নারীদের জন্য মুণ্ডন নয়, চুল ছোট করা)", "en": "Sunan Abi Dawud (women shorten the hair rather than shave)"}, "check": true}]', 'in_review', 70 FROM is_guide_topics WHERE slug = 'hajj' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'b56a8f63-7058-58e7-bc47-470a306539f8', id, 'hajj-mistakes', '{"bn": "হজে যে ভুলগুলো এড়িয়ে চলবেন", "en": "Mistakes to avoid in hajj"}', '{"bn": "হাজিদের মধ্যে প্রচলিত কিছু ভুল, যা হজের ক্ষতি করে বা অন্যকে কষ্ট দেয়।", "en": "Common mistakes among pilgrims that harm the hajj or hurt others."}', 'basic', '[{"type": "list", "items": [{"bn": "ইহরাম ছাড়া মিকাত পার হওয়া, যেমন জেদ্দায় পৌঁছে ইহরাম বাঁধা।", "en": "Crossing the miqat without ihram, e.g. entering ihram only on landing in Jeddah."}, {"bn": "পুরো ইহরামের সময় ডান কাঁধ খোলা রাখা। ইজতিবা শুধু সাঈযুক্ত তাওয়াফের সময়; নামাজে কাঁধ ঢেকে রাখবেন।", "en": "Keeping the right shoulder bare throughout ihram. Idtiba'' is only during a tawaf followed by sa''i; cover the shoulder in prayer."}, {"bn": "তাওয়াফের প্রতিটি চক্করের জন্য বই থেকে নির্দিষ্ট দোয়া পড়া জরুরি মনে করা; এমন নির্দিষ্ট দোয়া হাদিসে নেই। নিজের ভাষায় দোয়া করুন।", "en": "Believing a set dua from a booklet is required for each round of tawaf; no such set duas exist in the hadith. Pray in your own words."}, {"bn": "দলবদ্ধভাবে চিৎকার করে দোয়া পড়ে অন্যের মনোযোগ নষ্ট করা।", "en": "Reciting duas loudly in groups and disturbing others."}, {"bn": "হাজরে আসওয়াদ চুম্বনের জন্য ধাক্কাধাক্কি করা; এটি সুন্নত, কিন্তু মানুষকে কষ্ট দেওয়া হারাম।", "en": "Pushing to kiss the Black Stone; kissing it is sunnah, but hurting people is haram."}, {"bn": "হাতিম (হিজরে ইসমাইল)-এর ভেতর দিয়ে তাওয়াফ করা; এটি কাবার অংশ, তাই এর বাইরে দিয়ে ঘুরতে হবে।", "en": "Doing tawaf through the Hatim (Hijr Isma''il); it is part of the Ka''bah, so go around outside it."}, {"bn": "সূর্যাস্তের আগে আরাফা ত্যাগ করা বা আরাফার সীমার বাইরে অবস্থান করা।", "en": "Leaving Arafah before sunset or staying outside its boundary."}, {"bn": "জাবালে রহমতে ওঠা, পাথর স্পর্শ বা সেখানে নামাজ পড়াকে জরুরি মনে করা।", "en": "Thinking it necessary to climb Jabal ar-Rahmah, touch its rocks or pray there."}, {"bn": "বড় পাথর, জুতা বা স্যান্ডেল দিয়ে জামরায় মারা, বা জামরাকে শয়তান ভেবে গালি দেওয়া। ছোট কংকরই সুন্নত; উদ্দেশ্য আল্লাহর জিকির।", "en": "Throwing large stones, shoes or sandals at the jamarat, or cursing them as if they were Satan. Small pebbles are the sunnah; the purpose is remembrance of Allah."}, {"bn": "সুস্থ থাকা সত্ত্বেও কংকর মারার জন্য অন্যকে প্রতিনিধি বানানো।", "en": "Appointing someone else to stone while healthy."}, {"bn": "মাথার কয়েকটি চুল কেটে ইহরাম খুলে ফেলা। হানাফি মতে মাথার অন্তত এক-চতুর্থাংশের চুল ছোট করতে হয়, অন্যদের মতে পুরো বা বেশির ভাগ মাথার; পুরো মাথা মুণ্ডন বা পুরো মাথা থেকে ছোট করাই নিরাপদ।", "en": "Cutting a few hairs and leaving ihram. Hanafis require at least a quarter of the head, others the whole or most of it; shaving or shortening the whole head is safest."}, {"bn": "নামাজের সময় ছবি তোলা, ভিডিও করা ও সেলফিতে ব্যস্ত থাকা; এতে ইবাদতের একাগ্রতা নষ্ট হয়।", "en": "Being busy with photos, videos and selfies in worship; it destroys focus."}, {"bn": "ঝগড়া, গিবত ও অন্য হাজির সাথে খারাপ আচরণ; এগুলো হজের সওয়াব নষ্ট করে।", "en": "Quarrelling, backbiting and mistreating fellow pilgrims; these spoil the reward of hajj."}]}, {"type": "note", "tone": "tip", "text": {"bn": "সন্দেহ হলে অনুমান না করে নির্ভরযোগ্য আলেমকে জিজ্ঞেস করুন। ধৈর্য ও নম্রতা হজের বড় শিক্ষা।", "en": "When in doubt, ask a reliable scholar instead of guessing. Patience and gentleness are among the great lessons of hajj."}}]', 'in_review', 80 FROM is_guide_topics WHERE slug = 'hajj' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '127d1098-f307-5ec2-aade-6d67ce9ae0ae', id, 'hajj-madinah-visit', '{"bn": "মদিনা জিয়ারত ও তার আদব", "en": "Visiting Madinah and its etiquette"}', '{"bn": "মসজিদে নববী, রওজা মুবারকে সালাম, রিয়াজুল জান্নাহ, কুবা ও বাকি কবরস্থান জিয়ারতের নিয়ম।", "en": "Masjid an-Nabawi, greeting the Prophet at his grave, the Rawdah, Quba and the Baqi'' cemetery."}', 'basic', '[{"type": "text", "text": {"bn": "মদিনা জিয়ারত হজের অংশ নয়, হজের আগে বা পরে করা একটি বরকতময় সুন্নত আমল। সফরের নিয়ত হবে মসজিদে নববীতে নামাজ পড়া; সেখানে পৌঁছে নবী (সা.)-এর রওজায় সালাম দেবেন।", "en": "Visiting Madinah is not part of hajj; it is a blessed sunnah done before or after hajj. The intention of travel is to pray in the Prophet''s Masjid; once there, you greet the Prophet at his grave."}}, {"type": "list", "items": [{"bn": "তিনটি মসজিদ ছাড়া অন্য কোনো স্থানের উদ্দেশ্যে (ইবাদতের নিয়তে) বিশেষ সফর করা যায় না: মসজিদুল হারাম, মসজিদে নববী ও মসজিদুল আকসা।", "en": "Special journeys for worship are made only to three masjids: Al-Masjid al-Haram, the Prophet''s Masjid and Al-Masjid al-Aqsa."}, {"bn": "মসজিদে নববীতে এক নামাজ মসজিদুল হারাম ছাড়া অন্য মসজিদের এক হাজার নামাজের চেয়ে উত্তম।", "en": "One prayer in the Prophet''s Masjid is better than a thousand elsewhere, except Al-Masjid al-Haram."}, {"bn": "নবী (সা.)-এর ঘর ও মিম্বারের মাঝের অংশ জান্নাতের বাগানগুলোর একটি (রিয়াজুল জান্নাহ)।", "en": "The area between the Prophet''s house and his pulpit is one of the gardens of Paradise (the Rawdah)."}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১১৮৯; সহিহ বুখারি ১১৯০; সহিহ বুখারি ১১৯৬", "en": "Sahih al-Bukhari 1189; Sahih al-Bukhari 1190; Sahih al-Bukhari 1196"}}, {"type": "note", "tone": "info", "text": {"bn": "''মসজিদে নববীতে একটানা চল্লিশ ওয়াক্ত নামাজ'' সম্পর্কিত হাদিসটির সনদ দুর্বল; এটি জরুরি মনে করে সফরসূচি বানানোর দরকার নেই, তবে যত বেশি জামাতে নামাজ পড়তে পারেন ততই ভালো।", "en": "The hadith about praying forty consecutive prayers in the Prophet''s Masjid has a weak chain; there is no need to plan the trip around it, though praying as many congregational prayers there as you can is good."}}, {"type": "step", "title": {"bn": "মসজিদে প্রবেশ", "en": "Entering the masjid"}, "text": {"bn": "ডান পা দিয়ে প্রবেশ করে দোয়া পড়ুন, তারপর সম্ভব হলে রিয়াজুল জান্নাহয়, নইলে যেকোনো স্থানে দুই রাকাত তাহিয়্যাতুল মসজিদ পড়ুন।", "en": "Enter with the right foot and say the dua, then pray two rakats of greeting in the Rawdah if possible, otherwise anywhere."}}, {"type": "arabic", "label": {"bn": "মসজিদে প্রবেশের দোয়া", "en": "Dua on entering the masjid"}, "ar": "اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ", "pron": {"bn": "আল্লাহুম্মাফতাহ লী আবওয়াবা রাহমাতিক", "en": "Allahummaftah li abwaba rahmatik"}, "meaning": {"bn": "হে আল্লাহ! আমার জন্য তোমার রহমতের দরজাগুলো খুলে দাও।", "en": "O Allah, open for me the doors of Your mercy."}, "ref": {"bn": "সহিহ মুসলিম ৭১৩", "en": "Sahih Muslim 713"}}, {"type": "step", "title": {"bn": "রওজায় সালাম", "en": "Greeting at the grave"}, "text": {"bn": "ধীরে, আদবের সাথে রওজার সামনে গিয়ে নিচু স্বরে নবী (সা.)-কে সালাম দিন, তারপর একটু ডানে সরে আবু বকর (রা.)-কে এবং আরেকটু ডানে উমর (রা.)-কে সালাম দিন।", "en": "Approach the grave slowly and respectfully and greet the Prophet in a low voice, then move a little to the right to greet Abu Bakr, and a little further to greet Umar."}}, {"type": "arabic", "label": {"bn": "রওজায় সালাম (ইবনে উমর রা.-এর আমল থেকে)", "en": "Greeting at the grave (from Ibn Umar''s practice)"}, "ar": "السَّلَامُ عَلَيْكَ يَا رَسُولَ اللَّهِ، السَّلَامُ عَلَيْكَ يَا أَبَا بَكْرٍ، السَّلَامُ عَلَيْكَ يَا عُمَرُ", "pron": {"bn": "আসসালামু আলাইকা ইয়া রাসূলাল্লাহ, আসসালামু আলাইকা ইয়া আবা বাকর, আসসালামু আলাইকা ইয়া উমার", "en": "As-salamu ''alayka ya rasulallah, as-salamu ''alayka ya aba bakr, as-salamu ''alayka ya ''umar"}, "meaning": {"bn": "হে আল্লাহর রাসুল, আপনার ওপর শান্তি বর্ষিত হোক। হে আবু বকর, আপনার ওপর শান্তি। হে উমর, আপনার ওপর শান্তি।", "en": "Peace be upon you, O Messenger of Allah. Peace be upon you, O Abu Bakr. Peace be upon you, O Umar."}, "ref": {"bn": "মুয়াত্তা মালিক (ইবনে উমর রা.-এর আমল)", "en": "Muwatta Malik (practice of Ibn Umar)"}, "check": true}, {"type": "note", "tone": "warn", "text": {"bn": "আদব: কণ্ঠস্বর নিচু রাখুন (সূরা হুজুরাত ৪৯:২)। নিজের জন্য দোয়া করার সময় কবরের দিকে নয়, কিবলামুখী হোন। জালি বা দেয়াল স্পর্শ, চুম্বন, কবরের দিকে সিজদা বা তাওয়াফ করবেন না; নবী (সা.)-এর কাছে নয়, আল্লাহর কাছে চাইবেন। ভিড়ে ধাক্কাধাক্কি করবেন না।", "en": "Etiquette: keep your voice low (Al-Hujurat 49:2). When making dua for yourself, face the qiblah, not the grave. Do not touch or kiss the grille or walls, prostrate or circle towards the grave; ask Allah, not the Prophet. Do not push in the crowd."}}, {"type": "step", "title": {"bn": "দরুদ", "en": "Salawat"}, "text": {"bn": "মদিনায় অবস্থানকালে বেশি বেশি দরুদ পড়ুন; নামাজের দরুদে ইবরাহিম সর্বোত্তম।", "en": "While in Madinah send abundant blessings on the Prophet; the Ibrahimi salawat of the prayer is best."}}, {"type": "step", "title": {"bn": "মসজিদে কুবা", "en": "Masjid Quba"}, "text": {"bn": "ঘর থেকে ওজু করে মসজিদে কুবায় গিয়ে দুই রাকাত নামাজ পড়া সুন্নত; নবী (সা.) প্রতি শনিবার কুবায় যেতেন। কুবায় নামাজ একটি উমরাহর সমান সওয়াবের কথা হাদিসে এসেছে।", "en": "It is sunnah to make wudu at home, go to Masjid Quba and pray two rakats; the Prophet went to Quba every Saturday. A hadith says a prayer in Quba is like the reward of an umrah."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১১৯৩", "en": "Sahih al-Bukhari 1193"}}, {"type": "ref", "text": {"bn": "সুনান ইবনে মাজাহ; জামে তিরমিজি (কুবায় নামাজ উমরাহর সমতুল্য)", "en": "Sunan Ibn Majah; Jami'' at-Tirmidhi (prayer in Quba equal to an umrah)"}, "check": true}, {"type": "step", "title": {"bn": "জান্নাতুল বাকি ও উহুদ", "en": "Al-Baqi'' and Uhud"}, "text": {"bn": "জান্নাতুল বাকি কবরস্থান এবং উহুদের শহীদদের কবর জিয়ারত করে সালাম দিন ও তাদের জন্য দোয়া করুন। পুরুষরা কবর জিয়ারত করবেন; নারীদের কবর জিয়ারত নিয়ে মতভেদ আছে।", "en": "Visit the Baqi'' cemetery and the martyrs of Uhud, greet them and pray for them. Men visit graves; scholars differ on women visiting graves."}}, {"type": "arabic", "label": {"bn": "কবর জিয়ারতের দোয়া", "en": "Dua when visiting graves"}, "ar": "السَّلَامُ عَلَيْكُمْ أَهْلَ الدِّيَارِ مِنَ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ، وَإِنَّا إِنْ شَاءَ اللَّهُ لَلَاحِقُونَ، أَسْأَلُ اللَّهَ لَنَا وَلَكُمُ الْعَافِيَةَ", "pron": {"bn": "আসসালামু আলাইকুম আহলাদ দিয়ারি মিনাল মু''মিনীনা ওয়াল মুসলিমীন, ওয়া ইন্না ইনশাআল্লাহু লালাহিকূন, আসআলুল্লাহা লানা ওয়া লাকুমুল আফিয়াহ", "en": "As-salamu ''alaykum ahlad-diyari minal-mu''minina wal-muslimin, wa inna in sha Allahu lalahiqun, as''alullaha lana wa lakumul-''afiyah"}, "meaning": {"bn": "হে এই ঘরের অধিবাসী মুমিন ও মুসলিমগণ, তোমাদের ওপর শান্তি বর্ষিত হোক। আল্লাহ চাইলে আমরাও তোমাদের সাথে মিলিত হব। আমি আল্লাহর কাছে আমাদের ও তোমাদের জন্য নিরাপত্তা চাই।", "en": "Peace be upon you, people of these dwellings, of the believers and the Muslims. We will, if Allah wills, join you. I ask Allah for well-being for us and for you."}, "ref": {"bn": "সহিহ মুসলিম ৯৭৫", "en": "Sahih Muslim 975"}}, {"type": "note", "tone": "tip", "text": {"bn": "মদিনার বাসিন্দাদের সাথে নম্র আচরণ করুন, শহরের পবিত্রতা রক্ষা করুন এবং বেশি বেশি নফল নামাজ, কুরআন তিলাওয়াত ও দোয়ায় সময় কাটান।", "en": "Be gentle with the people of Madinah, respect the sanctity of the city, and spend your time in voluntary prayer, Quran and dua."}}]', 'in_review', 90 FROM is_guide_topics WHERE slug = 'hajj' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '20c65bb3-c154-588d-a1d2-1d890a537d0b', id, 'umrah-basics', '{"bn": "উমরাহ: হুকুম, ফজিলত ও এক নজরে", "en": "Umrah: ruling, virtues and overview"}', '{"bn": "উমরাহ কী, এর হুকুম ও ফজিলত, আর পুরো উমরাহ এক নজরে।", "en": "What umrah is, its ruling and virtues, and the whole umrah at a glance."}', 'basic', '[{"type": "text", "text": {"bn": "উমরাহ মানে নির্দিষ্ট নিয়মে বায়তুল্লাহর জিয়ারত: ইহরাম, তাওয়াফ, সাফা-মারওয়ার সাঈ এবং মাথা মুণ্ডন বা চুল ছোট করা। হজের মতো নির্দিষ্ট দিন নেই; বছরের যেকোনো সময় করা যায় (হানাফি মতে ৯ থেকে ১৩ জিলহজ উমরাহ করা মাকরুহ)।", "en": "Umrah is visiting the House of Allah in a set way: ihram, tawaf, sa''i between Safa and Marwah, and shaving or shortening the hair. Unlike hajj it has no fixed days and may be done any time of the year (Hanafis dislike umrah on 9–13 Dhul Hijjah)."}}, {"type": "arabic", "ar": "وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ", "pron": {"bn": "ওয়া আতিম্মুল হাজ্জা ওয়াল উমরাতা লিল্লাহ", "en": "Wa atimmul-hajja wal-''umrata lillah"}, "meaning": {"bn": "আর আল্লাহর জন্য হজ ও উমরাহ পূর্ণ করো।", "en": "And complete the hajj and umrah for Allah."}, "ref": {"bn": "সূরা বাকারা ২:১৯৬", "en": "Al-Baqarah 2:196"}}, {"type": "differ", "title": {"bn": "উমরাহর হুকুম", "en": "Ruling on umrah"}, "views": [{"label": {"bn": "হানাফি ও মালেকি", "en": "Hanafi and Maliki"}, "text": {"bn": "জীবনে একবার উমরাহ করা সুন্নতে মুয়াক্কাদা (জোরালো সুন্নত), ফরজ নয়।", "en": "Performing umrah once in a lifetime is an emphasised sunnah, not obligatory."}, "evidence": {"bn": "জাবির (রা.)-এর হাদিস: উমরাহ ওয়াজিব কি না জিজ্ঞেস করা হলে নবী (সা.) বললেন, না, তবে উমরাহ করা উত্তম (তিরমিজি)। আয়াতে ''পূর্ণ করো'' বলা হয়েছে শুরু করার পর, শুরু করা আবশ্যক এমন নয়।", "en": "Hadith of Jabir: asked whether umrah is obligatory, the Prophet said no, but doing it is better (Tirmidhi). The verse says ''complete'' once begun, not that beginning is required."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি", "en": "Shafi''i and Hanbali"}, "text": {"bn": "সামর্থ্যবানের ওপর জীবনে একবার উমরাহ করা ওয়াজিব (ফরজের মতো আবশ্যক)।", "en": "Umrah is obligatory once in a lifetime for those able."}, "evidence": {"bn": "আয়াতে হজের সাথে উমরাহকেও একই নির্দেশে রাখা হয়েছে; আয়েশা (রা.)-এর হাদিস: নারীদের জিহাদ হলো হজ ও উমরাহ (ইবনে মাজাহ)।", "en": "The verse joins umrah with hajj in one command; Aishah''s hadith: the jihad of women is hajj and umrah (Ibn Majah)."}}], "check": true}, {"type": "heading", "text": {"bn": "ফজিলত", "en": "Virtues"}}, {"type": "list", "items": [{"bn": "এক উমরাহ থেকে আরেক উমরাহ, এর মাঝের গুনাহের কাফফারা।", "en": "One umrah to the next is an expiation for what is between them."}, {"bn": "রমজানে উমরাহ একটি হজের সমান সওয়াব (তবে এটি ফরজ হজের বদলে যথেষ্ট নয়)।", "en": "An umrah in Ramadan equals a hajj in reward (though it does not replace the obligatory hajj)."}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৭৭৩; সহিহ বুখারি ১৭৮২; সহিহ মুসলিম ১২৫৬", "en": "Sahih al-Bukhari 1773; Sahih al-Bukhari 1782; Sahih Muslim 1256"}}, {"type": "heading", "text": {"bn": "উমরাহ এক নজরে", "en": "Umrah at a glance"}}, {"type": "table", "head": [{"bn": "ধাপ", "en": "Step"}, {"bn": "কাজ", "en": "What to do"}, {"bn": "হানাফি মতে হুকুম", "en": "Hanafi ruling"}], "rows": [[{"bn": "১", "en": "1"}, {"bn": "মিকাতে বা আগে ইহরাম: নিয়ত ও তালবিয়া", "en": "Ihram at or before the miqat: intention and talbiyah"}, {"bn": "শর্ত (ফরজ)", "en": "Condition (farz)"}], [{"bn": "২", "en": "2"}, {"bn": "মসজিদুল হারামে প্রবেশ ও কাবার তাওয়াফ, সাত চক্কর", "en": "Enter Al-Masjid al-Haram and circle the Ka''bah seven times"}, {"bn": "রুকন (ফরজ)", "en": "Pillar (farz)"}], [{"bn": "৩", "en": "3"}, {"bn": "মাকামে ইবরাহিমের পেছনে দুই রাকাত নামাজ", "en": "Two rakats behind Maqam Ibrahim"}, {"bn": "ওয়াজিব", "en": "Wajib"}], [{"bn": "৪", "en": "4"}, {"bn": "জমজমের পানি পান", "en": "Drink Zamzam"}, {"bn": "সুন্নত/মুস্তাহাব", "en": "Sunnah"}], [{"bn": "৫", "en": "5"}, {"bn": "সাফা থেকে মারওয়া, সাত চক্কর সাঈ", "en": "Sa''i: seven laps from Safa to Marwah"}, {"bn": "ওয়াজিব (অন্য তিন মাজহাবে রুকন)", "en": "Wajib (a pillar in the other three schools)"}], [{"bn": "৬", "en": "6"}, {"bn": "মাথা মুণ্ডন বা চুল ছোট করা", "en": "Shave or shorten the hair"}, {"bn": "ওয়াজিব", "en": "Wajib"}]]}, {"type": "note", "tone": "info", "text": {"bn": "ইহরাম, নিষিদ্ধ কাজ ও মিকাতের বিস্তারিত হজ বিভাগের ''ইহরাম'' ও ''মিকাত'' গাইডে আছে; উমরাহতেও একই বিধান।", "en": "Details of ihram, its prohibitions and the miqat are in the hajj section''s ihram and miqat guides; the same rules apply to umrah."}}]', 'in_review', 10 FROM is_guide_topics WHERE slug = 'umrah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '332947de-6569-5d03-9129-db5a4eaf5d48', id, 'umrah-ihram-to-masjid', '{"bn": "উমরাহ: ইহরাম থেকে মসজিদুল হারাম", "en": "Umrah: from ihram to Al-Masjid al-Haram"}', '{"bn": "ইহরামের প্রস্তুতি, নিয়ত, তালবিয়া, মক্কায় প্রবেশ এবং মসজিদুল হারামে প্রবেশের আদব।", "en": "Preparing ihram, the intention, the talbiyah, entering Makkah and entering Al-Masjid al-Haram."}', 'basic', '[{"type": "step", "title": {"bn": "প্রস্তুতি", "en": "Preparation"}, "text": {"bn": "নখ কাটা, অবাঞ্ছিত লোম পরিষ্কার, গোসল (না পারলে ওজু)। পুরুষ শরীরে সুগন্ধি লাগাতে পারেন, ইহরামের কাপড়ে নয়।", "en": "Trim nails, remove unwanted hair, take a ghusl (or wudu). Men may perfume the body, not the ihram sheets."}}, {"type": "step", "title": {"bn": "পোশাক", "en": "Clothing"}, "text": {"bn": "পুরুষ: সেলাইবিহীন দুটি সাদা চাদর ও খোলা স্যান্ডেল, মাথা খোলা। নারী: সাধারণ শালীন পোশাক, নিকাব ও হাতমোজা ছাড়া।", "en": "Men: two unstitched white sheets and open sandals, head uncovered. Women: ordinary modest clothes, without niqab or gloves."}}, {"type": "step", "title": {"bn": "দুই রাকাত (সুন্নত)", "en": "Two rakats (sunnah)"}, "text": {"bn": "মাকরুহ সময় না হলে ইহরামের আগে দুই রাকাত নামাজ পড়ুন (হানাফি মত); অন্যদের মতে কোনো ফরজ নামাজের পরে ইহরাম বাঁধা উত্তম।", "en": "If not a disliked time, pray two rakats before ihram (Hanafi view); others prefer entering ihram after an obligatory prayer."}}, {"type": "step", "title": {"bn": "নিয়ত", "en": "Intention"}, "text": {"bn": "মিকাতে পৌঁছানোর আগে মনে মনে উমরাহর নিয়ত করুন। এটি মনের ইচ্ছা; মুখে বলা জরুরি নয়।", "en": "Before reaching the miqat, intend umrah in your heart. It is an intention of the heart; saying it is not required."}}, {"type": "arabic", "label": {"bn": "মুখে বলার একটি উদাহরণ (জরুরি নয়)", "en": "An example to say aloud (not required)"}, "ar": "لَبَّيْكَ عُمْرَةً", "pron": {"bn": "লাব্বাইকা উমরাতান", "en": "Labbayka ''umratan"}, "meaning": {"bn": "আমি উমরাহর জন্য হাজির।", "en": "Here I am for umrah."}}, {"type": "note", "tone": "tip", "text": {"bn": "আরেকটি প্রচলিত উদাহরণ: ''হে আল্লাহ! আমি উমরাহর নিয়ত করছি, তুমি তা আমার জন্য সহজ করো এবং কবুল করো।'' এটি কোনো হাদিসের নির্দিষ্ট বাক্য নয়; নিজের ভাষায় মনে মনে নিয়তই যথেষ্ট।", "en": "Another common example: ''O Allah, I intend umrah; make it easy for me and accept it from me.'' This is not fixed wording from a hadith; the intention in your heart, in any language, is enough."}}, {"type": "step", "title": {"bn": "তালবিয়া", "en": "Talbiyah"}, "text": {"bn": "নিয়তের পর তালবিয়া পড়লেই ইহরাম শুরু। এরপর ইহরামের সব নিষেধ মেনে চলবেন এবং তাওয়াফ শুরু পর্যন্ত বেশি বেশি তালবিয়া পড়বেন (পুরুষ উচ্চস্বরে, নারী নিচু স্বরে)।", "en": "With the talbiyah after the intention, ihram begins. From then on observe all ihram prohibitions and repeat the talbiyah often until starting tawaf (men aloud, women quietly)."}}, {"type": "arabic", "label": {"bn": "তালবিয়া", "en": "Talbiyah"}, "ar": "لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لَا شَرِيكَ لَكَ", "pron": {"bn": "লাব্বাইকা আল্লাহুম্মা লাব্বাইক, লাব্বাইকা লা শারীকা লাকা লাব্বাইক, ইন্নাল হামদা ওয়ান নি''মাতা লাকা ওয়াল মুলক, লা শারীকা লাক", "en": "Labbayka Allahumma labbayk, labbayka la sharika laka labbayk, innal-hamda wan-ni''mata laka wal-mulk, la sharika lak"}, "meaning": {"bn": "আমি হাজির, হে আল্লাহ! আমি হাজির। আমি হাজির, তোমার কোনো শরিক নেই, আমি হাজির। নিশ্চয়ই সব প্রশংসা, সব নিয়ামত তোমারই, আর রাজত্বও তোমার; তোমার কোনো শরিক নেই।", "en": "Here I am, O Allah, here I am. Here I am, You have no partner, here I am. Surely all praise and blessings are Yours, and the dominion; You have no partner."}, "ref": {"bn": "সহিহ বুখারি ১৫৪৯; সহিহ মুসলিম ১১৮৪", "en": "Sahih al-Bukhari 1549; Sahih Muslim 1184"}}, {"type": "step", "title": {"bn": "মক্কায় প্রবেশ", "en": "Entering Makkah"}, "text": {"bn": "সম্ভব হলে মক্কায় প্রবেশের আগে গোসল করা সুন্নত। হোটেলে মালপত্র রেখে, বিশ্রাম নিয়ে, ওজু করে মসজিদুল হারামে যান।", "en": "If possible, take a ghusl before entering Makkah (sunnah). Leave your bags at the hotel, rest, make wudu and go to Al-Masjid al-Haram."}}, {"type": "step", "title": {"bn": "মসজিদে প্রবেশ", "en": "Entering the masjid"}, "text": {"bn": "ডান পা দিয়ে প্রবেশ করে মসজিদে প্রবেশের দোয়া পড়ুন।", "en": "Enter with the right foot and say the dua for entering the masjid."}}, {"type": "arabic", "label": {"bn": "মসজিদে প্রবেশের দোয়া", "en": "Dua on entering the masjid"}, "ar": "بِسْمِ اللَّهِ، وَالصَّلَاةُ وَالسَّلَامُ عَلَىٰ رَسُولِ اللَّهِ، اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ", "pron": {"bn": "বিসমিল্লাহি, ওয়াস সালাতু ওয়াস সালামু আলা রাসূলিল্লাহ, আল্লাহুম্মাফতাহ লী আবওয়াবা রাহমাতিক", "en": "Bismillahi, was-salatu was-salamu ''ala rasulillah, Allahummaftah li abwaba rahmatik"}, "meaning": {"bn": "আল্লাহর নামে; আল্লাহর রাসুলের ওপর দরুদ ও সালাম। হে আল্লাহ! আমার জন্য তোমার রহমতের দরজাগুলো খুলে দাও।", "en": "In the name of Allah, and blessings and peace on the Messenger of Allah. O Allah, open for me the doors of Your mercy."}, "ref": {"bn": "সহিহ মুসলিম ৭১৩", "en": "Sahih Muslim 713"}}, {"type": "note", "tone": "info", "text": {"bn": "সহিহ মুসলিমে মূল অংশ ''আল্লাহুম্মাফতাহ লী আবওয়াবা রাহমাতিক''; শুরুতে বিসমিল্লাহ ও দরুদ অন্য হাদিসগ্রন্থের বর্ণনায় এসেছে।", "en": "Sahih Muslim has the core ''Allahummaftah li abwaba rahmatik''; the Bismillah and salawat at the start come in other hadith collections."}}, {"type": "note", "tone": "tip", "text": {"bn": "কাবা প্রথম দেখার সময় নির্দিষ্ট কোনো সহিহ দোয়া প্রমাণিত নেই; এ সম্পর্কে প্রচলিত বর্ণনাগুলো দুর্বল। মন থেকে যেকোনো দোয়া করুন।", "en": "No specific authentic dua is established for first seeing the Ka''bah; the popular reports are weak. Make any dua from the heart."}}]', 'in_review', 20 FROM is_guide_topics WHERE slug = 'umrah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '702aa109-0a55-561c-a694-a1ad1079b5c9', id, 'umrah-tawaf', '{"bn": "উমরাহ: তাওয়াফ, দুই রাকাত ও জমজম", "en": "Umrah: tawaf, two rakats and Zamzam"}', '{"bn": "হাজরে আসওয়াদ থেকে সাত চক্কর তাওয়াফ, রুকনে ইয়ামানি ও হাজরে আসওয়াদের মাঝের দোয়া, মাকামে ইবরাহিমে নামাজ ও জমজম।", "en": "Seven rounds of tawaf from the Black Stone, the dua between the Yemeni corner and the Black Stone, prayer at Maqam Ibrahim and Zamzam."}', 'basic', '[{"type": "step", "title": {"bn": "ওজু ও প্রস্তুতি", "en": "Wudu and preparation"}, "text": {"bn": "ওজু অবস্থায় তাওয়াফ করবেন। পুরুষরা চাদরের মাঝখান ডান বগলের নিচ দিয়ে এনে বাম কাঁধে রাখবেন, ডান কাঁধ খোলা থাকবে (ইজতিবা) — শুধু এই তাওয়াফের সময়।", "en": "Perform tawaf in wudu. Men pass the middle of the upper sheet under the right arm and over the left shoulder, leaving the right shoulder bare (idtiba'') — only during this tawaf."}}, {"type": "differ", "title": {"bn": "তাওয়াফে ওজুর হুকুম", "en": "Wudu for tawaf"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "ওজু ওয়াজিব; ওজু ছাড়া তাওয়াফ করলে তাওয়াফ হয়ে যায়, তবে দম বা সদকা দিতে হয় (অথবা ওজু করে আবার তাওয়াফ করলে মাফ)।", "en": "Wudu is wajib; a tawaf without wudu counts, but a dam or charity is due (or it is waived by repeating the tawaf with wudu)."}, "evidence": {"bn": "কুরআনে শুধু তাওয়াফের নির্দেশ এসেছে; পবিত্রতা হাদিস থেকে প্রমাণিত, তাই ওয়াজিব স্তরে।", "en": "The Quran commands tawaf alone; purity is established by hadith, hence wajib."}}, {"label": {"bn": "শাফেয়ি, মালেকি, হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "ওজু তাওয়াফের শর্ত; ওজু ছাড়া তাওয়াফ সহিহ হবে না।", "en": "Wudu is a condition; tawaf without it is not valid."}, "evidence": {"bn": "হাদিস: ''বায়তুল্লাহর তাওয়াফ নামাজের মতো, তবে এতে কথা বলা বৈধ'' (তিরমিজি); নবী (সা.) তাওয়াফের আগে ওজু করেছেন।", "en": "Hadith: ''Tawaf around the House is like prayer, except that speaking is allowed'' (Tirmidhi); the Prophet made wudu before tawaf."}}]}, {"type": "step", "title": {"bn": "হাজরে আসওয়াদ থেকে শুরু", "en": "Start at the Black Stone"}, "text": {"bn": "হাজরে আসওয়াদ বরাবর (সবুজ বাতির দাগ) দাঁড়িয়ে কাবার দিকে মুখ করুন। সম্ভব হলে পাথরটি চুম্বন করুন, না হলে হাত দিয়ে স্পর্শ করে হাতে চুমু দিন, তাও না পারলে দূর থেকে ডান হাত তুলে ইশারা করুন (ইশারা করা হাতে চুমু খাবেন না) এবং বলুন:", "en": "Stand in line with the Black Stone (marked by a green light) facing the Ka''bah. Kiss the stone if possible; if not, touch it with your hand and kiss the hand; if not, raise your right hand towards it from a distance (do not kiss the hand after pointing) and say:"}}, {"type": "arabic", "label": {"bn": "হাজরে আসওয়াদের সামনে", "en": "At the Black Stone"}, "ar": "بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ", "pron": {"bn": "বিসমিল্লাহি ওয়াল্লাহু আকবার", "en": "Bismillahi wallahu akbar"}, "meaning": {"bn": "আল্লাহর নামে, আল্লাহ সবচেয়ে মহান।", "en": "In the name of Allah, and Allah is the Greatest."}, "ref": {"bn": "সহিহ বুখারি (তাকবির); বিসমিল্লাহ অংশ ইবনে উমর রা.-এর আমল", "en": "Sahih al-Bukhari (the takbir); the Bismillah is from Ibn Umar''s practice"}, "check": true}, {"type": "step", "title": {"bn": "সাত চক্কর", "en": "Seven rounds"}, "text": {"bn": "কাবাকে বাম দিকে রেখে ঘুরতে থাকুন। হাতিমের (অর্ধবৃত্তাকার দেয়াল) বাইরে দিয়ে ঘুরবেন, কারণ এটি কাবার অংশ। প্রতিবার হাজরে আসওয়াদ বরাবর এলে এক চক্কর পূর্ণ হয়; প্রতিবার ইশারা করে ''আল্লাহু আকবার'' বলুন।", "en": "Walk with the Ka''bah on your left, outside the Hatim (the semicircular wall), since it is part of the Ka''bah. Each time you reach the Black Stone line one round is complete; point to it and say ''Allahu akbar'' each time."}}, {"type": "step", "title": {"bn": "রমল (পুরুষ)", "en": "Ramal (men)"}, "text": {"bn": "প্রথম তিন চক্করে পুরুষরা কাঁধ দুলিয়ে ছোট ছোট কদমে একটু দ্রুত হাঁটবেন; বাকি চার চক্কর স্বাভাবিকভাবে। ভিড়ে সম্ভব না হলে ছেড়ে দিন।", "en": "In the first three rounds men walk briskly with short steps, moving the shoulders; the remaining four at a normal pace. Skip it if the crowd makes it impossible."}}, {"type": "step", "title": {"bn": "রুকনে ইয়ামানি", "en": "The Yemeni corner"}, "text": {"bn": "হাজরে আসওয়াদের আগের কোণ রুকনে ইয়ামানি। সহজে সম্ভব হলে ডান হাতে স্পর্শ করুন, চুম্বন করবেন না; ভিড়ে স্পর্শ করা না গেলে ইশারাও করতে হবে না।", "en": "The corner before the Black Stone is the Yemeni corner. Touch it with your right hand if easy, without kissing; if the crowd prevents it, no gesture is needed."}}, {"type": "arabic", "label": {"bn": "রুকনে ইয়ামানি ও হাজরে আসওয়াদের মাঝে", "en": "Between the Yemeni corner and the Black Stone"}, "ar": "رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ", "pron": {"bn": "রাব্বানা আতিনা ফিদ দুনইয়া হাসানাতাও ওয়া ফিল আখিরাতি হাসানাতাও ওয়া কিনা আযাবান নার", "en": "Rabbana atina fid-dunya hasanatan wa fil-akhirati hasanatan wa qina ''adhaban-nar"}, "meaning": {"bn": "হে আমাদের রব! আমাদের দুনিয়াতে কল্যাণ দাও, আখিরাতেও কল্যাণ দাও এবং আমাদের জাহান্নামের আজাব থেকে রক্ষা করো।", "en": "Our Lord, give us good in this world and good in the Hereafter, and protect us from the punishment of the Fire."}, "ref": {"bn": "সুনান আবু দাউদ ১৮৯২; সূরা বাকারা ২:২০১", "en": "Sunan Abi Dawud 1892; Al-Baqarah 2:201"}}, {"type": "note", "tone": "tip", "text": {"bn": "এই অংশ ছাড়া তাওয়াফের জন্য নির্দিষ্ট কোনো দোয়া নেই। বইয়ে ''প্রথম চক্করের দোয়া, দ্বিতীয় চক্করের দোয়া'' যা দেখা যায়, তা হাদিসে নেই। নিজের ভাষায় দোয়া, জিকির, ইস্তিগফার বা কুরআন তিলাওয়াত করুন।", "en": "Apart from this part, tawaf has no set duas. The ''dua of the first round, second round'' found in booklets is not from the hadith. Make dua in your own language, do dhikr, seek forgiveness or recite Quran."}}, {"type": "step", "title": {"bn": "তাওয়াফ শেষ", "en": "Finishing tawaf"}, "text": {"bn": "সপ্তম চক্কর শেষে হাজরে আসওয়াদ বরাবর এসে তাওয়াফ শেষ। এবার ডান কাঁধ ঢেকে নিন।", "en": "Tawaf ends on reaching the Black Stone line after the seventh round. Now cover the right shoulder."}}, {"type": "step", "title": {"bn": "মাকামে ইবরাহিমে দুই রাকাত", "en": "Two rakats at Maqam Ibrahim"}, "text": {"bn": "সম্ভব হলে মাকামে ইবরাহিমকে নিজের ও কাবার মাঝে রেখে দুই রাকাত নামাজ পড়ুন; ভিড় থাকলে মসজিদের যেকোনো স্থানে। প্রথম রাকাতে সূরা কাফিরুন, দ্বিতীয় রাকাতে সূরা ইখলাস পড়া সুন্নত। মাকরুহ সময় হলে পরে পড়বেন।", "en": "If possible pray two rakats with Maqam Ibrahim between you and the Ka''bah; in crowds, anywhere in the masjid. Reciting Al-Kafirun in the first and Al-Ikhlas in the second is sunnah. If it is a disliked time, pray later."}}, {"type": "arabic", "label": {"bn": "মাকামে ইবরাহিমের দিকে যাওয়ার সময়", "en": "When going to Maqam Ibrahim"}, "ar": "وَاتَّخِذُوا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى", "pron": {"bn": "ওয়াত্তাখিযূ মিম মাকামি ইবরাহীমা মুসাল্লা", "en": "Wattakhidhu mim maqami ibrahima musalla"}, "meaning": {"bn": "আর তোমরা মাকামে ইবরাহিমকে নামাজের স্থান বানাও।", "en": "And take the station of Ibrahim as a place of prayer."}, "ref": {"bn": "সূরা বাকারা ২:১২৫", "en": "Al-Baqarah 2:125"}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১২১৮", "en": "Sahih Muslim 1218"}}, {"type": "step", "title": {"bn": "জমজম", "en": "Zamzam"}, "text": {"bn": "এরপর জমজমের পানি তৃপ্তি সহকারে পান করুন এবং যা চান তার জন্য দোয়া করুন। নবী (সা.) জমজম দাঁড়িয়ে পান করেছেন; বসে পান করাও জায়েজ।", "en": "Then drink Zamzam to your fill and make dua for whatever you wish. The Prophet drank Zamzam standing; sitting is also fine."}}, {"type": "ref", "text": {"bn": "সুনান ইবনে মাজাহ (''জমজমের পানি যে উদ্দেশ্যে পান করা হয়, তার জন্যই'')", "en": "Sunan Ibn Majah (''The water of Zamzam is for whatever it is drunk for'')"}, "check": true}, {"type": "step", "title": {"bn": "আবার হাজরে আসওয়াদ (সুন্নত)", "en": "Back to the Black Stone (sunnah)"}, "text": {"bn": "সম্ভব হলে সাঈতে যাওয়ার আগে আবার হাজরে আসওয়াদ স্পর্শ বা ইশারা করুন; ভিড়ে এটি ছেড়ে দেওয়া যায়।", "en": "If possible, touch or point to the Black Stone again before going to sa''i; it may be left in crowds."}}]', 'in_review', 30 FROM is_guide_topics WHERE slug = 'umrah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '7b08e5b9-0a68-5419-96cc-07fee7a8262d', id, 'umrah-sai-halq', '{"bn": "উমরাহ: সাঈ ও মাথা মুণ্ডন", "en": "Umrah: sa''i and shaving the head"}', '{"bn": "সাফা থেকে মারওয়া সাত চক্কর সাঈ, সাফার দোয়া, তারপর মাথা মুণ্ডন বা চুল ছোট করে উমরাহ শেষ।", "en": "Seven laps of sa''i from Safa to Marwah, the dua at Safa, then shaving or shortening to complete umrah."}', 'basic', '[{"type": "step", "title": {"bn": "সাফায় যাওয়া", "en": "Go to Safa"}, "text": {"bn": "সাফা পাহাড়ের কাছে এসে (শুধু প্রথমবার) নিচের আয়াতাংশ পড়ুন, তারপর বলুন ''আবদাউ বিমা বাদাআল্লাহু বিহি'' — আল্লাহ যা দিয়ে শুরু করেছেন, আমিও তা দিয়ে শুরু করছি।", "en": "Approaching Safa (the first time only), recite the verse below, then say ''Abda''u bima bada''allahu bih'' — I begin with what Allah began with."}}, {"type": "arabic", "label": {"bn": "সাফার কাছে (প্রথমবার)", "en": "Near Safa (first time)"}, "ar": "إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ ۖ أَبْدَأُ بِمَا بَدَأَ اللَّهُ بِهِ", "pron": {"bn": "ইন্নাস সাফা ওয়াল মারওয়াতা মিন শাআইরিল্লাহ। আবদাউ বিমা বাদাআল্লাহু বিহি", "en": "Innas-safa wal-marwata min sha''a''irillah. Abda''u bima bada''allahu bih"}, "meaning": {"bn": "নিশ্চয়ই সাফা ও মারওয়া আল্লাহর নিদর্শনগুলোর অন্তর্ভুক্ত। আল্লাহ যা দিয়ে শুরু করেছেন, আমিও তা দিয়ে শুরু করছি।", "en": "Indeed Safa and Marwah are among the symbols of Allah. I begin with what Allah began with."}, "ref": {"bn": "সূরা বাকারা ২:১৫৮; সহিহ মুসলিম ১২১৮", "en": "Al-Baqarah 2:158; Sahih Muslim 1218"}}, {"type": "step", "title": {"bn": "সাফায় দোয়া", "en": "Dua at Safa"}, "text": {"bn": "সাফায় উঠে কাবার দিকে মুখ করুন, দুই হাত দোয়ার মতো তুলুন (নামাজের তাকবিরের মতো কান পর্যন্ত নয়), তিনবার ''আল্লাহু আকবার'' বলে নিচের জিকির পড়ুন, তারপর নিজের ভাষায় দোয়া করুন। এভাবে তিনবার জিকির ও দোয়া করা সুন্নত।", "en": "Climb Safa, face the Ka''bah, raise your hands as in dua (not to the ears as in prayer), say ''Allahu akbar'' three times and the dhikr below, then make your own dua. Doing the dhikr and dua three times is sunnah."}}, {"type": "arabic", "label": {"bn": "সাফা ও মারওয়ার জিকির", "en": "Dhikr at Safa and Marwah"}, "ar": "اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ. لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ، لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ، أَنْجَزَ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الْأَحْزَابَ وَحْدَهُ", "pron": {"bn": "আল্লাহু আকবার, আল্লাহু আকবার, আল্লাহু আকবার। লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারীকা লাহু, লাহুল মুলকু ওয়া লাহুল হামদু, ওয়া হুয়া আলা কুল্লি শাইয়িন কাদীর। লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু, আনজাযা ওয়া''দাহু, ওয়া নাসারা আবদাহু, ওয়া হাযামাল আহযাবা ওয়াহদাহু", "en": "Allahu akbar, Allahu akbar, Allahu akbar. La ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamd, wa huwa ''ala kulli shay''in qadir. La ilaha illallahu wahdah, anjaza wa''dah, wa nasara ''abdah, wa hazamal-ahzaba wahdah"}, "meaning": {"bn": "আল্লাহ সবচেয়ে মহান (তিনবার)। আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি এক, তাঁর কোনো শরিক নেই; রাজত্ব ও প্রশংসা তাঁরই, তিনি সবকিছুর ওপর ক্ষমতাবান। আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি এক; তিনি তাঁর ওয়াদা পূর্ণ করেছেন, তাঁর বান্দাকে সাহায্য করেছেন এবং একাই শত্রুদলগুলোকে পরাজিত করেছেন।", "en": "Allah is the Greatest (three times). There is no god but Allah alone, without partner; His is the dominion and the praise, and He has power over all things. There is no god but Allah alone; He fulfilled His promise, helped His servant and alone defeated the confederates."}, "ref": {"bn": "সহিহ মুসলিম ১২১৮", "en": "Sahih Muslim 1218"}}, {"type": "step", "title": {"bn": "মারওয়ার দিকে", "en": "Towards Marwah"}, "text": {"bn": "সাফা থেকে নেমে মারওয়ার দিকে হাঁটুন। দুই সবুজ বাতির মাঝখানে পুরুষরা মাঝারি গতিতে দৌড়াবেন; নারীরা স্বাভাবিকভাবে হাঁটবেন। পথে যেকোনো দোয়া-জিকির করুন।", "en": "Come down from Safa and walk towards Marwah. Between the two green lights men jog at a moderate pace; women walk normally. Make any dua and dhikr on the way."}}, {"type": "arabic", "label": {"bn": "সাঈর পথে (সাহাবিদের থেকে বর্ণিত)", "en": "During sa''i (reported from Companions)"}, "ar": "رَبِّ اغْفِرْ وَارْحَمْ، إِنَّكَ أَنْتَ الْأَعَزُّ الْأَكْرَمُ", "pron": {"bn": "রাব্বিগফির ওয়ারহাম, ইন্নাকা আনতাল আআযযুল আকরাম", "en": "Rabbighfir warham, innaka antal-a''azzul-akram"}, "meaning": {"bn": "হে আমার রব! ক্ষমা করো ও দয়া করো; নিশ্চয়ই তুমি সর্বাধিক পরাক্রমশালী, সর্বাধিক সম্মানিত।", "en": "My Lord, forgive and have mercy; You are the Most Mighty, the Most Generous."}, "ref": {"bn": "ইবনে মাসউদ ও ইবনে উমর রা. থেকে মাওকুফ বর্ণনা (মুসান্নাফ ইবনে আবি শাইবা)", "en": "Mawquf report from Ibn Mas''ud and Ibn Umar (Musannaf Ibn Abi Shaybah)"}, "check": true}, {"type": "note", "tone": "info", "text": {"bn": "এটি নবী (সা.)-এর হাদিস নয়, সাহাবিদের আমল হিসেবে বর্ণিত; পড়া যায়, তবে জরুরি নয়।", "en": "This is reported as the practice of Companions, not a hadith of the Prophet; it may be said but is not required."}}, {"type": "step", "title": {"bn": "মারওয়ায়", "en": "At Marwah"}, "text": {"bn": "মারওয়ায় উঠে কাবার দিকে মুখ করে সাফার মতোই জিকির ও দোয়া করুন। সাফা থেকে মারওয়া এক চক্কর, মারওয়া থেকে সাফা আরেক চক্কর।", "en": "At Marwah face the Ka''bah and do the same dhikr and dua as at Safa. Safa to Marwah is one lap, Marwah to Safa another."}}, {"type": "step", "title": {"bn": "সাত চক্কর", "en": "Seven laps"}, "text": {"bn": "এভাবে সাত চক্কর পূর্ণ করুন; সপ্তম চক্কর মারওয়ায় শেষ হবে। ক্লান্ত হলে বিশ্রাম নেওয়া যায়; প্রয়োজনে হুইলচেয়ার ব্যবহার করা যায়।", "en": "Complete seven laps this way; the seventh ends at Marwah. You may rest if tired, and use a wheelchair if needed."}}, {"type": "note", "tone": "tip", "text": {"bn": "সাঈর জন্য ওজু শর্ত নয়, তবে ওজু থাকা উত্তম। তাওয়াফের পর হায়েজ শুরু হলে নারী সাঈ করতে পারবেন, কারণ সাঈর স্থান মসজিদের মূল অংশের বাইরে বলে গণ্য।", "en": "Wudu is not a condition for sa''i, though better. If a woman''s period starts after tawaf she may still do sa''i, as the sa''i area is counted outside the masjid proper."}}, {"type": "step", "title": {"bn": "মাথা মুণ্ডন বা চুল ছোট করা", "en": "Shave or shorten the hair"}, "text": {"bn": "সাঈ শেষে পুরুষরা পুরো মাথা মুণ্ডন করবেন (উত্তম) বা পুরো মাথার চুল ছোট করবেন। নারীরা চুলের আগা থেকে আঙুলের এক কর পরিমাণ কাটবেন। হজের নিকটবর্তী সময়ে তামাত্তুর উমরাহ হলে পুরুষের জন্য চুল ছোট করে হজের মুণ্ডনের জন্য চুল রেখে দেওয়া ভালো।", "en": "After sa''i men shave the whole head (better) or shorten hair from the whole head. Women cut a fingertip''s length from the ends. For a tamattu'' umrah close to hajj, men may prefer to shorten, keeping hair to shave at hajj."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৭২৭; সহিহ মুসলিম ১৩০১", "en": "Sahih al-Bukhari 1727; Sahih Muslim 1301"}}, {"type": "note", "tone": "info", "text": {"bn": "নবী (সা.) মাথা মুণ্ডনকারীদের জন্য তিনবার এবং চুল ছোট করা ব্যক্তিদের জন্য একবার রহমতের দোয়া করেছেন। মুণ্ডন বা চুল ছোট করার মাধ্যমে উমরাহ পূর্ণ হয় এবং ইহরামের সব নিষেধ উঠে যায়।", "en": "The Prophet prayed for mercy for those who shave three times and for those who shorten once. With shaving or shortening the umrah is complete and all ihram restrictions end."}}, {"type": "arabic", "label": {"bn": "মসজিদ থেকে বের হওয়ার দোয়া (বাম পা দিয়ে)", "en": "Dua on leaving the masjid (left foot first)"}, "ar": "اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ", "pron": {"bn": "আল্লাহুম্মা ইন্নী আসআলুকা মিন ফাদলিক", "en": "Allahumma inni as''aluka min fadlik"}, "meaning": {"bn": "হে আল্লাহ! আমি তোমার অনুগ্রহ প্রার্থনা করি।", "en": "O Allah, I ask You of Your bounty."}, "ref": {"bn": "সহিহ মুসলিম ৭১৩", "en": "Sahih Muslim 713"}}]', 'in_review', 40 FROM is_guide_topics WHERE slug = 'umrah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '3fa02e01-7a2c-5a70-982b-9965affd0782', id, 'umrah-checklist', '{"bn": "উমরাহর চেকলিস্ট", "en": "Umrah checklist"}', '{"bn": "যাত্রার আগে কী নেবেন, কী শিখবেন, আর উমরাহর ধাপগুলো মিলিয়ে নেওয়ার তালিকা।", "en": "What to pack and learn before travelling, and a list to tick off the steps of umrah."}', 'basic', '[{"type": "heading", "text": {"bn": "যাত্রার আগে", "en": "Before travelling"}}, {"type": "list", "items": [{"bn": "পাসপোর্ট, ভিসা, টিকিট, হোটেল ও এজেন্সির কাগজ, টিকার সনদ (প্রযোজ্য হলে); সবকিছুর কপি ও ফোনে ছবি", "en": "Passport, visa, tickets, hotel and agency papers, vaccination certificate (if required); copies and photos on your phone"}, {"bn": "নিয়ত খাঁটি করা, তওবা, ঋণ ও মানুষের হক মিটিয়ে নেওয়া, পরিবারের কাছ থেকে বিদায় ও ক্ষমা চাওয়া", "en": "Purify the intention, repent, settle debts and others'' rights, say farewell and seek forgiveness from family"}, {"bn": "উমরাহর নিয়ম, তালবিয়া ও প্রয়োজনীয় দোয়াগুলো আগে থেকে শিখে নেওয়া", "en": "Learn the rites, the talbiyah and key duas beforehand"}, {"bn": "হালাল অর্থে খরচের ব্যবস্থা", "en": "Make sure the money is lawful"}]}, {"type": "heading", "text": {"bn": "সঙ্গে নেবেন", "en": "What to pack"}}, {"type": "list", "items": [{"bn": "পুরুষ: দুই সেট ইহরামের চাদর, ইহরামের বেল্ট/টাকার থলে, পায়ের পাতার মাঝখান খোলা স্যান্ডেল", "en": "Men: two sets of ihram sheets, an ihram belt/money pouch, sandals that leave the middle of the foot exposed"}, {"bn": "নারী: ঢিলেঢালা শালীন পোশাক, হিজাব, আরামদায়ক জুতা ও মোজা", "en": "Women: loose modest clothes, hijab, comfortable shoes and socks"}, {"bn": "সুগন্ধিহীন সাবান, শ্যাম্পু, টুথপেস্ট ও লোশন", "en": "Unscented soap, shampoo, toothpaste and lotion"}, {"bn": "নিয়মিত ওষুধ ও প্রেসক্রিপশন, ব্যথানাশক, ফোস্কার প্লাস্টার", "en": "Regular medicines and prescriptions, painkillers, blister plasters"}, {"bn": "জুতা রাখার ছোট ব্যাগ, পানির বোতল, ছাতা, পাওয়ার ব্যাংক", "en": "Small shoe bag, water bottle, umbrella, power bank"}, {"bn": "ছোট দোয়ার বই বা এই অ্যাপ (অফলাইনে চলে এমনভাবে)", "en": "A small dua book or this app (available offline)"}]}, {"type": "heading", "text": {"bn": "উমরাহর ধাপ মিলিয়ে নিন", "en": "Tick off the steps"}}, {"type": "list", "items": [{"bn": "গোসল/ওজু, ইহরামের পোশাক, (সম্ভব হলে) দুই রাকাত", "en": "Ghusl/wudu, ihram clothing, (if possible) two rakats"}, {"bn": "মিকাতের আগে নিয়ত ও তালবিয়া", "en": "Intention and talbiyah before the miqat"}, {"bn": "ইহরামের নিষেধগুলো মেনে চলা", "en": "Observe the prohibitions of ihram"}, {"bn": "ডান পা দিয়ে মসজিদুল হারামে প্রবেশ ও দোয়া", "en": "Enter Al-Masjid al-Haram with the right foot and the dua"}, {"bn": "ওজুসহ সাত চক্কর তাওয়াফ, হাজরে আসওয়াদ থেকে শুরু ও শেষ (পুরুষ: ইজতিবা ও প্রথম তিন চক্করে রমল)", "en": "Seven rounds of tawaf in wudu, starting and ending at the Black Stone (men: idtiba'' and ramal in the first three)"}, {"bn": "রুকনে ইয়ামানি ও হাজরে আসওয়াদের মাঝে ''রাব্বানা আতিনা''", "en": "''Rabbana atina'' between the Yemeni corner and the Black Stone"}, {"bn": "কাঁধ ঢেকে মাকামে ইবরাহিমের পেছনে বা মসজিদের যেকোনো স্থানে দুই রাকাত", "en": "Cover the shoulder and pray two rakats behind Maqam Ibrahim or anywhere in the masjid"}, {"bn": "জমজম পান ও দোয়া", "en": "Drink Zamzam and make dua"}, {"bn": "সাফা থেকে শুরু করে মারওয়ায় শেষ, সাত চক্কর সাঈ", "en": "Seven laps of sa''i, starting at Safa and ending at Marwah"}, {"bn": "মাথা মুণ্ডন বা চুল ছোট করা — উমরাহ সম্পন্ন", "en": "Shave or shorten the hair — umrah complete"}]}, {"type": "note", "tone": "tip", "text": {"bn": "উমরাহর পরে মক্কায় যত দিন থাকবেন, মসজিদুল হারামে জামাতে নামাজ ও নফল তাওয়াফে সময় দিন। মক্কা ছাড়ার আগে বিদায়ী তাওয়াফ শুধু উমরাহকারীর জন্য হানাফিসহ অনেক আলেমের মতে ওয়াজিব নয় (শাফেয়ি মতে মক্কা ত্যাগকারী সবার জন্য ওয়াজিব); তবে করে নেওয়াই উত্তম।", "en": "While you remain in Makkah after umrah, spend time in congregational prayer and voluntary tawaf at Al-Masjid al-Haram. For someone who came only for umrah, a farewell tawaf is not obligatory for Hanafis and many others (Shafi''is make it obligatory for anyone leaving Makkah); doing it is best."}}]', 'in_review', 50 FROM is_guide_topics WHERE slug = 'umrah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'e31869d6-bfbb-5592-b83d-689419b9490a', id, 'qurbani-ruling', '{"bn": "কুরবানি: হুকুম ও কার ওপর", "en": "Qurbani: ruling and who must offer it"}', '{"bn": "কুরবানির গুরুত্ব, এটি ওয়াজিব না সুন্নত — মাজহাবগুলোর মত, এবং কার ওপর আবশ্যক।", "en": "The importance of qurbani, whether it is wajib or sunnah in the different schools, and on whom it is due."}', 'basic', '[{"type": "arabic", "ar": "فَصَلِّ لِرَبِّكَ وَانْحَرْ", "pron": {"bn": "ফাসাল্লি লিরাব্বিকা ওয়ানহার", "en": "Fasalli lirabbika wanhar"}, "meaning": {"bn": "অতএব তোমার রবের উদ্দেশে নামাজ পড়ো এবং কুরবানি করো।", "en": "So pray to your Lord and sacrifice."}, "ref": {"bn": "সূরা কাওসার ১০৮:২", "en": "Al-Kawthar 108:2"}}, {"type": "arabic", "ar": "لَنْ يَنَالَ اللَّهَ لُحُومُهَا وَلَا دِمَاؤُهَا وَلَٰكِنْ يَنَالُهُ التَّقْوَىٰ مِنْكُمْ", "pron": {"bn": "লাই ইয়ানালাল্লাহা লুহূমুহা ওয়ালা দিমাউহা ওয়ালাকিই ইয়ানালুহুত তাকওয়া মিনকুম", "en": "Lay yanalallaha luhumuha wa la dima''uha wa lakiy yanaluhut-taqwa minkum"}, "meaning": {"bn": "আল্লাহর কাছে এগুলোর গোশত বা রক্ত পৌঁছায় না, বরং তাঁর কাছে পৌঁছায় তোমাদের তাকওয়া।", "en": "Neither their meat nor their blood reaches Allah; what reaches Him is your piety."}, "ref": {"bn": "সূরা হজ ২২:৩৭", "en": "Al-Hajj 22:37"}}, {"type": "text", "text": {"bn": "কুরবানি হলো ঈদুল আজহার দিনগুলোতে আল্লাহর সন্তুষ্টির জন্য নির্দিষ্ট পশু জবাই করা। এটি ইবরাহিম (আ.)-এর সুন্নত এবং নবী (সা.) মদিনায় প্রতি বছর কুরবানি করেছেন। উদ্দেশ্য গোশত খাওয়া নয়, বরং আল্লাহর জন্য ত্যাগ ও তাকওয়া।", "en": "Qurbani is slaughtering specified animals on the days of Eid al-Adha for the pleasure of Allah. It is the sunnah of Ibrahim, and the Prophet offered it every year in Madinah. Its purpose is not the meat but sacrifice and piety for Allah."}}, {"type": "differ", "title": {"bn": "কুরবানি ওয়াজিব না সুন্নত", "en": "Is qurbani wajib or sunnah"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "কুরবানির দিনগুলোতে নিসাব পরিমাণ সম্পদের মালিক প্রত্যেক প্রাপ্তবয়স্ক, সুস্থ মস্তিষ্কের, মুকিম (মুসাফির নয়) মুসলিমের ওপর কুরবানি ওয়াজিব।", "en": "Qurbani is wajib on every adult, sane, resident (not travelling) Muslim who owns the nisab during the days of sacrifice."}, "evidence": {"bn": "হাদিস: ''যার সামর্থ্য আছে অথচ কুরবানি করে না, সে যেন আমাদের ঈদগাহের কাছে না আসে'' (ইবনে মাজাহ); এবং ''ফাসাল্লি লিরাব্বিকা ওয়ানহার'' আয়াতের নির্দেশ।", "en": "Hadith: ''Whoever can afford it and does not sacrifice, let him not come near our place of prayer'' (Ibn Majah); and the command in the verse ''so pray to your Lord and sacrifice''."}}, {"label": {"bn": "শাফেয়ি, মালেকি, হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "সামর্থ্যবানের জন্য সুন্নতে মুয়াক্কাদা (জোরালো সুন্নত); সামর্থ্য থাকা সত্ত্বেও ছেড়ে দেওয়া মাকরুহ।", "en": "An emphasised sunnah for those able; leaving it while able is disliked."}, "evidence": {"bn": "উম্মে সালামা (রা.)-এর হাদিস: ''তোমাদের কেউ কুরবানি করতে চাইলে...'' — ''চাইলে'' শব্দ ইচ্ছাধীনতার ইঙ্গিত দেয় (মুসলিম); আবু বকর (রা.) ও উমর (রা.) কখনো কখনো কুরবানি করতেন না, যাতে মানুষ একে ওয়াজিব না ভাবে।", "en": "Umm Salamah''s hadith: ''If one of you wants to sacrifice...'' — ''wants'' implies choice (Muslim); Abu Bakr and Umar sometimes did not sacrifice so people would not think it obligatory."}}]}, {"type": "ref", "text": {"bn": "সুনান ইবনে মাজাহ ৩১২৩; সহিহ মুসলিম ১৯৭৭", "en": "Sunan Ibn Majah 3123; Sahih Muslim 1977"}}, {"type": "heading", "text": {"bn": "হানাফি মতে কার ওপর ওয়াজিব", "en": "On whom it is wajib (Hanafi)"}}, {"type": "list", "items": [{"bn": "মুসলিম, প্রাপ্তবয়স্ক ও সুস্থ মস্তিষ্কের", "en": "Muslim, adult and sane"}, {"bn": "মুকিম; শরিয়তসম্মত মুসাফিরের ওপর ওয়াজিব নয়", "en": "Resident; not obligatory on a Shariah traveller"}, {"bn": "১০ জিলহজ সুবহে সাদিক থেকে ১২ জিলহজ সূর্যাস্তের মধ্যে যেকোনো সময় মৌলিক প্রয়োজন ও ঋণের অতিরিক্ত নিসাব পরিমাণ সম্পদের মালিক (সদকাতুল ফিতরের নিসাবের মতো; বছর পূর্ণ হওয়া শর্ত নয়)", "en": "Owning, at any time between dawn on 10 and sunset on 12 Dhul Hijjah, the nisab beyond basic needs and debts (as for sadaqatul fitr; a full year is not required)"}]}, {"type": "note", "tone": "info", "text": {"bn": "নিসাবের হিসাবে যাকাতের মতো শুধু নগদ-সোনা-রূপা নয়, মৌলিক প্রয়োজনের অতিরিক্ত যেকোনো সম্পদ (অব্যবহৃত জমি, অতিরিক্ত বাড়ি, অপ্রয়োজনীয় জিনিস) হানাফি মতে যোগ হয়।", "en": "For this nisab, Hanafis count not only cash, gold and silver but any wealth beyond basic needs (unused land, an extra house, surplus goods)."}}, {"type": "note", "tone": "tip", "text": {"bn": "পরিবারের প্রত্যেক সদস্য, যিনি নিজে নিসাবের মালিক (যেমন গয়নার মালিক স্ত্রী বা উপার্জনক্ষম সন্তান), হানাফি মতে তার ওপর আলাদা কুরবানি ওয়াজিব। মৃত ব্যক্তির পক্ষ থেকে নফল কুরবানি করা যায়।", "en": "In the Hanafi view every family member who personally owns the nisab (e.g. a wife who owns jewellery, or an earning child) has a separate qurbani due. A voluntary qurbani may be offered on behalf of the deceased."}}]', 'in_review', 10 FROM is_guide_topics WHERE slug = 'qurbani' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '543b2036-9619-5049-a935-05fdc49dd384', id, 'qurbani-animals', '{"bn": "কুরবানির পশু: বয়স, ভাগ ও দোষত্রুটি", "en": "Qurbani animals: age, shares and defects"}', '{"bn": "কোন পশু, কত বয়সে, কয়জন শরিক হতে পারে, আর কোন দোষ থাকলে কুরবানি হবে না।", "en": "Which animals, at what age, how many may share, and which defects disqualify an animal."}', 'basic', '[{"type": "text", "text": {"bn": "কুরবানির পশু হতে হবে গৃহপালিত চতুষ্পদ পশুর (আনআম) মধ্য থেকে: উট, গরু, মহিষ, ছাগল, ভেড়া ও দুম্বা। নর-মাদি দুটোই চলবে। হরিণ, মুরগি বা অন্য প্রাণী দিয়ে কুরবানি হয় না।", "en": "The animal must be from the livestock (an''am): camels, cattle, buffalo, goats, sheep and rams. Male or female are both fine. Deer, chickens or other animals do not count."}}, {"type": "table", "head": [{"bn": "পশু", "en": "Animal"}, {"bn": "ন্যূনতম বয়স (হানাফি)", "en": "Minimum age (Hanafi)"}, {"bn": "কতজন শরিক", "en": "Shares"}], "rows": [[{"bn": "ছাগল", "en": "Goat"}, {"bn": "পূর্ণ ১ বছর", "en": "Full 1 year"}, {"bn": "১ জন", "en": "1 person"}], [{"bn": "ভেড়া, দুম্বা", "en": "Sheep, ram"}, {"bn": "পূর্ণ ১ বছর; তবে ৬ মাস পার হয়ে এত হৃষ্টপুষ্ট যে এক বছরের মতো দেখায়, তাহলেও চলবে", "en": "Full 1 year; or over 6 months if so well-grown it looks a year old"}, {"bn": "১ জন", "en": "1 person"}], [{"bn": "গরু, মহিষ", "en": "Cow, buffalo"}, {"bn": "পূর্ণ ২ বছর", "en": "Full 2 years"}, {"bn": "সর্বোচ্চ ৭ জন", "en": "Up to 7 people"}], [{"bn": "উট", "en": "Camel"}, {"bn": "পূর্ণ ৫ বছর", "en": "Full 5 years"}, {"bn": "সর্বোচ্চ ৭ জন", "en": "Up to 7 people"}]]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১৯৬৩; সহিহ মুসলিম ১৩১৮", "en": "Sahih Muslim 1963; Sahih Muslim 1318"}}, {"type": "note", "tone": "info", "text": {"bn": "অন্য মাজহাবে বয়সে সামান্য পার্থক্য আছে (যেমন শাফেয়ি মতে ছাগলের বয়স পূর্ণ ২ বছর)। বয়স নিশ্চিত হতে দাঁত দেখা বা বিক্রেতার নির্ভরযোগ্য তথ্য নিন; বয়স কম হলে কুরবানি হবে না।", "en": "Other schools differ slightly on ages (e.g. Shafi''is require a goat of a full 2 years). Check the teeth or rely on trustworthy information from the seller; an underage animal does not count."}}, {"type": "heading", "text": {"bn": "গরু-উটে ভাগে কুরবানি", "en": "Sharing a cow or camel"}}, {"type": "list", "items": [{"bn": "গরু, মহিষ বা উটে সর্বোচ্চ সাতজন শরিক হতে পারেন; সাতের কম (২, ৩, ৫ জন) হলেও চলবে।", "en": "Up to seven may share a cow, buffalo or camel; fewer (2, 3, 5) is also fine."}, {"bn": "কারও ভাগ সাত ভাগের এক ভাগের কম হতে পারবে না।", "en": "No one''s share may be less than one seventh."}, {"bn": "প্রত্যেক শরিকের নিয়ত আল্লাহর সন্তুষ্টি (কুরবানি বা আকিকা) হতে হবে। হানাফি মতে কোনো একজন শুধু গোশত খাওয়ার নিয়তে শরিক হলে কারও কুরবানি সহিহ হবে না।", "en": "Every partner''s intention must be for Allah (qurbani or aqiqah). In the Hanafi view, if even one joins only for meat, no one''s qurbani is valid."}, {"bn": "সব শরিকের টাকা হালাল হওয়া জরুরি; গোশত ওজন করে সমান ভাগ করবেন, অনুমানে নয়।", "en": "All partners'' money must be lawful; divide the meat equally by weight, not by guess."}]}, {"type": "differ", "title": {"bn": "একটি ছাগল কি পুরো পরিবারের পক্ষ থেকে যথেষ্ট", "en": "Does one goat suffice for a whole household"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "একটি ছাগল বা ভেড়া কেবল একজনের ওয়াজিব কুরবানি আদায় করে। পরিবারের যার যার ওপর কুরবানি ওয়াজিব, প্রত্যেককে আলাদা কুরবানি দিতে হবে; তবে সওয়াবে অন্যদের শরিক করা যায়।", "en": "One goat or sheep discharges the wajib qurbani of one person only. Each family member on whom it is wajib must offer separately, though others may be included in the reward."}, "evidence": {"bn": "কুরবানি প্রত্যেক সামর্থ্যবানের ব্যক্তিগত দায়িত্ব; নবী (সা.) কর্তৃক পরিবারের পক্ষ থেকে কুরবানি সওয়াবে শরিক করার অর্থে।", "en": "Qurbani is a personal duty of each person able; the Prophet''s sacrifice for his family is understood as sharing the reward."}}, {"label": {"bn": "শাফেয়ি, মালেকি, হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "একজন ব্যক্তি নিজের ও পুরো পরিবারের পক্ষ থেকে একটি ছাগল কুরবানি করলে সবার পক্ষ থেকে সুন্নত আদায় হয়ে যায়।", "en": "A man sacrificing one goat for himself and his household fulfils the sunnah for all of them."}, "evidence": {"bn": "আবু আইয়ুব (রা.): নবী (সা.)-এর যুগে একজন নিজের ও পরিবারের পক্ষ থেকে একটি ছাগল কুরবানি করত (তিরমিজি); নবী (সা.) কুরবানির সময় বলেছেন, ''মুহাম্মদ ও মুহাম্মদের পরিবারের পক্ষ থেকে'' (মুসলিম)।", "en": "Abu Ayyub: in the Prophet''s time a man would sacrifice one sheep for himself and his household (Tirmidhi); the Prophet said at his sacrifice, ''from Muhammad and the family of Muhammad'' (Muslim)."}}]}, {"type": "ref", "text": {"bn": "জামে তিরমিজি ১৫০৫; সহিহ মুসলিম ১৯৬৭", "en": "Jami'' at-Tirmidhi 1505; Sahih Muslim 1967"}}, {"type": "heading", "text": {"bn": "যেসব দোষ থাকলে কুরবানি হবে না", "en": "Defects that disqualify"}}, {"type": "text", "text": {"bn": "নবী (সা.) চার ধরনের পশু কুরবানি করতে নিষেধ করেছেন: স্পষ্ট কানা, স্পষ্ট অসুস্থ, স্পষ্ট খোঁড়া এবং এত শুকনো যে হাড়ে মজ্জা নেই।", "en": "The Prophet forbade four kinds of animals: one clearly blind in one eye, one clearly sick, one clearly lame, and one so emaciated it has no marrow."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ ২৮০২; জামে তিরমিজি ১৪৯৭", "en": "Sunan Abi Dawud 2802; Jami'' at-Tirmidhi 1497"}}, {"type": "list", "items": [{"bn": "এক বা দুই চোখ অন্ধ, বা এক চোখের বেশির ভাগ দৃষ্টি নেই", "en": "Blind in one or both eyes, or most of one eye''s sight gone"}, {"bn": "এমন খোঁড়া যে জবাইয়ের স্থান পর্যন্ত নিজে হেঁটে যেতে পারে না", "en": "So lame it cannot walk to the place of slaughter"}, {"bn": "এমন রোগা বা অসুস্থ যে চলাফেরা ও খাওয়া স্বাভাবিক নয়", "en": "So thin or sick that it cannot move or eat normally"}, {"bn": "হানাফি মতে: কান বা লেজের এক-তৃতীয়াংশের বেশি কাটা; শিং গোড়া থেকে ভেঙে মগজ পর্যন্ত ক্ষত; দাঁত না থাকায় ঘাস খেতে পারে না; জন্মগতভাবে কান নেই; ছাগলের একটি বা গরুর দুটি স্তনের বোঁটা কাটা বা শুকনো", "en": "Hanafi: more than a third of the ear or tail cut off; a horn broken at the root with injury reaching inside; toothless so it cannot graze; born without ears; one teat of a goat or two of a cow cut off or dry"}]}, {"type": "heading", "text": {"bn": "যেসব কারণে সমস্যা নেই", "en": "What does not disqualify"}}, {"type": "list", "items": [{"bn": "খাসি (বীজ কাটা) পশু; এটি বরং ভালো", "en": "A castrated animal; this is even preferred"}, {"bn": "জন্মগতভাবে শিং নেই, বা শিং সামান্য ভাঙা", "en": "Born without horns, or a slightly broken horn"}, {"bn": "কানে ছোট ছিদ্র বা সামান্য কাটা, এক-তৃতীয়াংশের কম", "en": "A small hole or cut in the ear, less than a third"}, {"bn": "জবাইয়ের জন্য শোয়ানোর সময় হঠাৎ আঘাত লেগে খুঁত হওয়া (হানাফি মত)", "en": "A defect that occurs suddenly while laying the animal down for slaughter (Hanafi view)"}]}, {"type": "note", "tone": "tip", "text": {"bn": "সবচেয়ে ভালো, হৃষ্টপুষ্ট ও সুন্দর পশু বাছাই করা উত্তম। নবী (সা.) দুটি সাদা-কালো রঙের শিংওয়ালা দুম্বা কুরবানি করেছেন।", "en": "Choosing the best, healthiest and finest animal is better. The Prophet sacrificed two horned rams, white with black markings."}}]', 'in_review', 20 FROM is_guide_topics WHERE slug = 'qurbani' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '9c73737b-7e1e-5ee7-90b6-06241c142dcc', id, 'qurbani-time-slaughter', '{"bn": "কুরবানির সময়, জবাইয়ের নিয়ম ও দোয়া", "en": "Time, method of slaughter and dua"}', '{"bn": "কখন থেকে কখন পর্যন্ত কুরবানি করা যায়, সুন্নত পদ্ধতিতে জবাই এবং জবাইয়ের দোয়া।", "en": "When qurbani may be offered, the sunnah method of slaughter and the dua."}', 'basic', '[{"type": "heading", "text": {"bn": "কুরবানির সময়", "en": "The time of qurbani"}}, {"type": "text", "text": {"bn": "ঈদুল আজহার নামাজের পর থেকে কুরবানির সময় শুরু। যেখানে ঈদের নামাজ হয়, সেখানে নামাজের আগে জবাই করলে তা কুরবানি হয় না, সাধারণ গোশত হয়; আবার কুরবানি দিতে হবে। (হানাফি মতে যে গ্রামে ঈদের নামাজ হয় না, সেখানে ১০ তারিখ সুবহে সাদিকের পরই জবাই করা যায়।) প্রথম দিন, অর্থাৎ ১০ জিলহজ কুরবানি করা উত্তম।", "en": "The time begins after the Eid al-Adha prayer. Where the Eid prayer is held, an animal slaughtered before it is ordinary meat, not qurbani, and must be replaced. (For Hanafis, in a village with no Eid prayer, slaughter is valid after dawn on the 10th.) The first day, the 10th, is best."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি; সহিহ মুসলিম (বারা ইবনে আযিব রা.: নামাজের আগে জবাই করা পশু সাধারণ গোশত)", "en": "Sahih al-Bukhari; Sahih Muslim (al-Bara'' ibn ''Azib: an animal slaughtered before the prayer is just meat)"}, "check": true}, {"type": "differ", "title": {"bn": "কুরবানির শেষ সময়", "en": "The last time for qurbani"}, "views": [{"label": {"bn": "হানাফি, মালেকি, হাম্বলি", "en": "Hanafi, Maliki, Hanbali"}, "text": {"bn": "১২ জিলহজ সূর্যাস্ত পর্যন্ত, অর্থাৎ ঈদের দিনসহ মোট তিন দিন।", "en": "Until sunset on 12 Dhul Hijjah: three days including Eid day."}, "evidence": {"bn": "উমর (রা.), আলী (রা.), ইবনে আব্বাস (রা.)সহ কয়েকজন সাহাবি থেকে বর্ণিত: কুরবানির দিন তিনটি।", "en": "Reported from Companions such as Umar, Ali and Ibn Abbas: the days of sacrifice are three."}}, {"label": {"bn": "শাফেয়ি", "en": "Shafi''i"}, "text": {"bn": "১৩ জিলহজ সূর্যাস্ত পর্যন্ত, অর্থাৎ আইয়ামে তাশরিকের শেষ দিন পর্যন্ত মোট চার দিন।", "en": "Until sunset on 13 Dhul Hijjah, the last day of Tashriq: four days."}, "evidence": {"bn": "হাদিস: ''আইয়ামে তাশরিকের সব দিনই জবাইয়ের দিন'' (মুসনাদে আহমাদ)।", "en": "Hadith: ''All the days of Tashriq are days of slaughter'' (Musnad Ahmad)."}}]}, {"type": "note", "tone": "info", "text": {"bn": "রাতে জবাই করা জায়েজ, তবে অন্ধকারে ভুল হওয়ার আশঙ্কায় হানাফি মতে মাকরুহ; দিনে করা উত্তম।", "en": "Slaughtering at night is permitted, but Hanafis dislike it for fear of mistakes in the dark; daytime is better."}}, {"type": "heading", "text": {"bn": "জবাইয়ের নিয়ম", "en": "The method of slaughter"}}, {"type": "step", "title": {"bn": "নিজে বা উপস্থিত থেকে", "en": "Yourself or present"}, "text": {"bn": "সম্ভব হলে নিজের কুরবানি নিজে জবাই করা উত্তম; না পারলে অন্যকে দিয়ে করানো এবং নিজে উপস্থিত থাকা ভালো। নারীরাও জবাই করতে পারেন।", "en": "It is best to slaughter your own animal if you can; otherwise have someone do it and be present. Women may also slaughter."}}, {"type": "step", "title": {"bn": "পশুর প্রতি দয়া", "en": "Kindness to the animal"}, "text": {"bn": "ছুরি খুব ধারালো করবেন, পশুর সামনে ধার দেবেন না, এক পশুর সামনে আরেকটি জবাই করবেন না, পানি খাওয়াবেন এবং টেনে-হিঁচড়ে কষ্ট দেবেন না।", "en": "Sharpen the knife well, not in front of the animal; do not slaughter one in sight of another; give it water and do not drag or hurt it."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১৯৫৫", "en": "Sahih Muslim 1955"}}, {"type": "step", "title": {"bn": "শোয়ানো", "en": "Laying it down"}, "text": {"bn": "পশুকে বাম কাতে কিবলামুখী করে শোয়ান; বড় পশুর জন্য কয়েকজন সাহায্যকারী রাখুন।", "en": "Lay the animal on its left side facing the qiblah; have helpers for large animals."}}, {"type": "step", "title": {"bn": "বিসমিল্লাহ বলে জবাই", "en": "Slaughter with Bismillah"}, "text": {"bn": "জবাইয়ের সময় ''বিসমিল্লাহি আল্লাহু আকবার'' বলে দ্রুত গলার সামনের দিকে ছুরি চালান। যিনি ছুরি চালাবেন এবং যিনি ছুরিতে হাত দিয়ে সাহায্য করবেন, দুজনকেই বিসমিল্লাহ বলতে হবে।", "en": "Say ''Bismillahi Allahu akbar'' and cut swiftly across the front of the throat. Whoever moves the knife, and anyone holding the knife with him, must both say Bismillah."}}, {"type": "step", "title": {"bn": "কী কাটতে হবে", "en": "What must be cut"}, "text": {"bn": "শ্বাসনালি, খাদ্যনালি এবং দুই পাশের দুটি বড় রক্তনালি (মোট চারটি)। হানাফি মতে এর যেকোনো তিনটি কাটা গেলে জবাই সহিহ। মাথা আলাদা করে ফেলা বা ঘাড়ের হাড় ভাঙা মাকরুহ।", "en": "The windpipe, the gullet and the two large blood vessels at the sides (four in all). For Hanafis cutting any three of these makes it valid. Cutting the head off or breaking the neck is disliked."}}, {"type": "step", "title": {"bn": "পুরো নিস্তেজ হওয়া পর্যন্ত অপেক্ষা", "en": "Wait until it is still"}, "text": {"bn": "পশু পুরোপুরি নিস্তেজ ও ঠান্ডা না হওয়া পর্যন্ত চামড়া ছাড়ানো বা কাটা শুরু করবেন না।", "en": "Do not begin skinning or cutting until the animal is completely still."}}, {"type": "note", "tone": "warn", "text": {"bn": "ইচ্ছা করে বিসমিল্লাহ ছেড়ে দিলে হানাফি ও অধিকাংশ আলেমের মতে সেই পশু খাওয়া হালাল নয় (সূরা আনআম ৬:১২১); ভুলে গেলে হালাল। শাফেয়ি মতে বিসমিল্লাহ সুন্নত।", "en": "If Bismillah is deliberately omitted, the meat is not lawful according to the Hanafis and most scholars (Al-An''am 6:121); if forgotten, it is lawful. For Shafi''is Bismillah is sunnah."}}, {"type": "heading", "text": {"bn": "জবাইয়ের দোয়া", "en": "Duas at slaughter"}}, {"type": "arabic", "label": {"bn": "জবাইয়ের সময় (জরুরি অংশ: বিসমিল্লাহ)", "en": "At the moment of slaughter (the essential part: Bismillah)"}, "ar": "بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ", "pron": {"bn": "বিসমিল্লাহি ওয়াল্লাহু আকবার", "en": "Bismillahi wallahu akbar"}, "meaning": {"bn": "আল্লাহর নামে, আর আল্লাহ সবচেয়ে মহান।", "en": "In the name of Allah, and Allah is the Greatest."}, "ref": {"bn": "সহিহ মুসলিম ১৯৬৬", "en": "Sahih Muslim 1966"}}, {"type": "arabic", "label": {"bn": "জবাইয়ের আগে পড়ার দোয়া (ঐচ্ছিক)", "en": "Dua before slaughter (optional)"}, "ar": "إِنِّي وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَاوَاتِ وَالْأَرْضَ عَلَىٰ مِلَّةِ إِبْرَاهِيمَ حَنِيفًا وَمَا أَنَا مِنَ الْمُشْرِكِينَ، إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ، لَا شَرِيكَ لَهُ وَبِذَٰلِكَ أُمِرْتُ وَأَنَا مِنَ الْمُسْلِمِينَ، اللَّهُمَّ مِنْكَ وَلَكَ", "pron": {"bn": "ইন্নী ওয়াজ্জাহতু ওয়াজহিয়া লিল্লাযী ফাতারাস সামাওয়াতি ওয়াল আরদা আলা মিল্লাতি ইবরাহীমা হানীফাও ওয়ামা আনা মিনাল মুশরিকীন, ইন্না সালাতী ওয়া নুসুকী ওয়া মাহইয়ায়া ওয়া মামাতী লিল্লাহি রাব্বিল আলামীন, লা শারীকা লাহু ওয়া বিযালিকা উমিরতু ওয়া আনা মিনাল মুসলিমীন, আল্লাহুম্মা মিনকা ওয়া লাকা", "en": "Inni wajjahtu wajhiya lilladhi fataras-samawati wal-arda ''ala millati ibrahima hanifan wa ma ana minal-mushrikin, inna salati wa nusuki wa mahyaya wa mamati lillahi rabbil-''alamin, la sharika lahu wa bidhalika umirtu wa ana minal-muslimin, Allahumma minka wa lak"}, "meaning": {"bn": "আমি একনিষ্ঠভাবে ইবরাহিমের দ্বীনের ওপর থেকে সেই সত্তার দিকে মুখ ফেরালাম, যিনি আসমান ও জমিন সৃষ্টি করেছেন; আমি মুশরিকদের অন্তর্ভুক্ত নই। নিশ্চয়ই আমার নামাজ, আমার কুরবানি, আমার জীবন ও মরণ জগৎসমূহের রব আল্লাহর জন্য; তাঁর কোনো শরিক নেই। আমাকে এরই নির্দেশ দেওয়া হয়েছে, আর আমি মুসলিমদের একজন। হে আল্লাহ! এটি তোমারই দান এবং তোমারই জন্য।", "en": "I turn my face to the One who created the heavens and the earth, upon the way of Ibrahim, inclining to truth, and I am not of the polytheists. My prayer, my sacrifice, my living and my dying are for Allah, Lord of the worlds; He has no partner. This I am commanded, and I am of the Muslims. O Allah, it is from You and for You."}, "ref": {"bn": "সুনান আবু দাউদ ২৭৯৫", "en": "Sunan Abi Dawud 2795"}, "check": true}, {"type": "note", "tone": "info", "text": {"bn": "এই দোয়াটি জাবির (রা.)-এর বর্ণনায় এসেছে; সনদ নিয়ে হাদিসবিশারদদের আলোচনা আছে। দোয়ার পরে ''বিসমিল্লাহি ওয়াল্লাহু আকবার'' বলে জবাই করবেন। মুখে নিয়ত বা অংশীদারদের নাম বলা জরুরি নয়; মনে নিয়ত থাকাই যথেষ্ট। চাইলে বলতে পারেন ''আল্লাহুম্মা তাকাব্বাল মিন্নী'' (হে আল্লাহ, আমার পক্ষ থেকে কবুল করো) — নবী (সা.) বলেছিলেন ''আল্লাহুম্মা তাকাব্বাল মিন মুহাম্মাদিন ওয়া আলি মুহাম্মাদ...''।", "en": "This dua comes in Jabir''s narration; hadith scholars discuss its chain. After it, slaughter saying ''Bismillahi wallahu akbar''. Saying the intention or the partners'' names aloud is not required; the intention in the heart is enough. You may say ''Allahumma taqabbal minni'' (O Allah, accept from me) — the Prophet said ''Allahumma taqabbal min Muhammadin wa ali Muhammad...''."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১৯৬৭", "en": "Sahih Muslim 1967"}}]', 'in_review', 30 FROM is_guide_topics WHERE slug = 'qurbani' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'e0d1f63c-8175-5469-b640-e48481121adf', id, 'qurbani-meat-skin', '{"bn": "কুরবানির গোশত ও চামড়া", "en": "Qurbani meat and skin"}', '{"bn": "গোশত কীভাবে ভাগ করবেন, চামড়া ও কসাইয়ের মজুরির বিধান।", "en": "How to divide the meat, and the rulings on the skin and the butcher''s wage."}', 'basic', '[{"type": "arabic", "ar": "فَكُلُوا مِنْهَا وَأَطْعِمُوا الْقَانِعَ وَالْمُعْتَرَّ", "pron": {"bn": "ফাকুলূ মিনহা ওয়া আতইমুল কানিআ ওয়াল মু''তার", "en": "Fakulu minha wa at''imul-qani''a wal-mu''tarr"}, "meaning": {"bn": "তোমরা তা থেকে খাও এবং যে চায় না ও যে চায় — উভয় অভাবীকে খাওয়াও।", "en": "Eat from them and feed both the one who does not ask and the one who asks."}, "ref": {"bn": "সূরা হজ ২২:৩৬", "en": "Al-Hajj 22:36"}}, {"type": "heading", "text": {"bn": "গোশত বণ্টন", "en": "Dividing the meat"}}, {"type": "table", "head": [{"bn": "ভাগ", "en": "Share"}, {"bn": "কাদের জন্য", "en": "For whom"}], "rows": [[{"bn": "এক-তৃতীয়াংশ", "en": "One third"}, {"bn": "নিজের ও পরিবারের জন্য", "en": "Yourself and your family"}], [{"bn": "এক-তৃতীয়াংশ", "en": "One third"}, {"bn": "আত্মীয়স্বজন, প্রতিবেশী ও বন্ধুদের জন্য (ধনী হলেও দেওয়া যায়)", "en": "Relatives, neighbours and friends (even if well-off)"}], [{"bn": "এক-তৃতীয়াংশ", "en": "One third"}, {"bn": "গরিব-মিসকিনদের জন্য", "en": "The poor and needy"}]]}, {"type": "note", "tone": "info", "text": {"bn": "তিন ভাগ করা মুস্তাহাব (উত্তম), বাধ্যতামূলক নয়। পরিবার বড় হলে বেশি রাখা যায়, আবার পুরোটা দান করাও যায়। গোশত সংরক্ষণ করে পরে খাওয়াও জায়েজ।", "en": "Dividing into thirds is recommended, not compulsory. A large family may keep more, and one may also give it all away. Storing the meat to eat later is allowed."}}, {"type": "ref", "text": {"bn": "সূরা হজ ২২:২৮", "en": "Al-Hajj 22:28"}}, {"type": "list", "items": [{"bn": "কুরবানির গোশত, চর্বি, হাড় বা কোনো অংশ বিক্রি করা জায়েজ নয়।", "en": "Selling any part of the qurbani animal — meat, fat or bones — is not allowed."}, {"bn": "কসাইয়ের মজুরি কুরবানির গোশত বা চামড়া দিয়ে দেওয়া যাবে না; আলাদা টাকা দিতে হবে। মজুরি দেওয়ার পর উপহার হিসেবে গোশত দেওয়া যায়।", "en": "The butcher''s wage must not be paid with meat or skin; pay separately. Meat may be given to him as a gift beyond the wage."}, {"bn": "মানতের কুরবানি হলে পুরো গোশত গরিবদের দিতে হবে; মানতকারী ও তার পরিবার খেতে পারবে না।", "en": "If the qurbani was vowed (nazr), all the meat goes to the poor; the person and his family may not eat it."}, {"bn": "হানাফি মতে অমুসলিম প্রতিবেশীকেও উপহার হিসেবে কুরবানির গোশত দেওয়া যায়।", "en": "Hanafis allow giving qurbani meat as a gift to non-Muslim neighbours too."}]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১৩১৭", "en": "Sahih Muslim 1317"}}, {"type": "heading", "text": {"bn": "চামড়া", "en": "The skin"}}, {"type": "text", "text": {"bn": "চামড়া নিজে ব্যবহার করা (যেমন জায়নামাজ বা মশক বানানো) বা কাউকে দান করা যায়। চামড়া বিক্রি করলে সেই টাকা নিজে ব্যবহার করা যাবে না; পুরো টাকা যাকাতের হকদার গরিবদের সদকা করে দিতে হবে। মাদরাসার লিল্লাহ বোর্ডিং বা গরিব ছাত্রদের দেওয়া প্রচলিত ও উত্তম খাত।", "en": "The skin may be used personally (e.g. as a prayer mat or water skin) or donated. If it is sold, the money may not be used by the owner; all of it must be given as charity to those eligible for zakat. Orphanage and poor-student funds of madrasahs are a common good choice."}}, {"type": "note", "tone": "warn", "text": {"bn": "চামড়ার টাকা দিয়ে মসজিদ নির্মাণ, ইমামের বেতন বা কর্মচারীর পারিশ্রমিক দেওয়া হানাফি মতে ঠিক নয়; এটি গরিবের হক।", "en": "Using the skin money for building a masjid, the imam''s salary or workers'' wages is not correct in the Hanafi view; it is the right of the poor."}}]', 'in_review', 40 FROM is_guide_topics WHERE slug = 'qurbani' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '92bbbe80-6de2-5a02-b109-7a0575cf49a7', id, 'qurbani-dhul-hijjah-takbir', '{"bn": "জিলহজের দশ দিন ও তাকবিরে তাশরিক", "en": "The ten days of Dhul Hijjah and takbir at-tashriq"}', '{"bn": "জিলহজের প্রথম দশ দিনের ফজিলত, নখ-চুল না কাটার সুন্নত, আরাফার রোজা এবং তাকবিরে তাশরিক।", "en": "The virtue of the first ten days of Dhul Hijjah, the sunnah of not cutting nails and hair, the Arafah fast and takbir at-tashriq."}', 'basic', '[{"type": "arabic", "ar": "وَالْفَجْرِ ۝ وَلَيَالٍ عَشْرٍ", "pron": {"bn": "ওয়াল ফাজর, ওয়া লায়ালিন আশর", "en": "Wal-fajr, wa layalin ''ashr"}, "meaning": {"bn": "শপথ ভোরের, শপথ দশ রাতের।", "en": "By the dawn, and by the ten nights."}, "ref": {"bn": "সূরা ফজর ৮৯:১–২", "en": "Al-Fajr 89:1–2"}}, {"type": "text", "text": {"bn": "অধিকাংশ মুফাসসিরের মতে এই দশ রাত জিলহজের প্রথম দশ রাত। নবী (সা.) বলেছেন, এমন কোনো দিন নেই যেদিনের নেক আমল আল্লাহর কাছে এই দশ দিনের আমলের চেয়ে বেশি প্রিয়।", "en": "Most commentators say these ten nights are the first ten of Dhul Hijjah. The Prophet said there are no days in which good deeds are more beloved to Allah than these ten days."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৯৬৯", "en": "Sahih al-Bukhari 969"}}, {"type": "list", "items": [{"bn": "বেশি বেশি তাকবির (আল্লাহু আকবার), তাহলিল (লা ইলাহা ইল্লাল্লাহ) ও তাহমিদ (আলহামদুলিল্লাহ) পড়া", "en": "Say takbir, tahlil and tahmid abundantly"}, {"bn": "নফল রোজা, বিশেষ করে ৯ জিলহজ আরাফার রোজা (হাজি ছাড়া অন্যদের জন্য); এটি আগের ও পরের এক বছরের গুনাহের কাফফারা হওয়ার আশা করা যায়", "en": "Voluntary fasting, especially the Arafah fast on the 9th (for non-pilgrims); it is hoped to expiate the year before and after"}, {"bn": "দান-সদকা, কুরআন তিলাওয়াত, তওবা ও সব ধরনের নেক কাজ", "en": "Charity, Quran, repentance and all good deeds"}]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১১৬২", "en": "Sahih Muslim 1162"}}, {"type": "heading", "text": {"bn": "নখ ও চুল না কাটা", "en": "Not cutting nails and hair"}}, {"type": "text", "text": {"bn": "উম্মে সালামা (রা.) বর্ণনা করেন, নবী (সা.) বলেছেন: জিলহজের দশক শুরু হলে তোমাদের যে কুরবানি করতে চায়, সে যেন তার চুল ও নখ থেকে কিছু না কাটে (কুরবানি করা পর্যন্ত)।", "en": "Umm Salamah reported that the Prophet said: when the ten days of Dhul Hijjah begin, whoever of you intends to sacrifice should not cut anything of his hair or nails (until he has sacrificed)."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১৯৭৭", "en": "Sahih Muslim 1977"}}, {"type": "differ", "title": {"bn": "এই নিষেধের হুকুম", "en": "Ruling of this prohibition"}, "views": [{"label": {"bn": "হাম্বলি", "en": "Hanbali"}, "text": {"bn": "কুরবানিদাতার জন্য চুল-নখ কাটা হারাম; কেটে ফেললে তওবা করবে, তবে কোনো কাফফারা নেই।", "en": "Cutting hair or nails is forbidden for the one sacrificing; if done, he repents, with no expiation."}, "evidence": {"bn": "হাদিসে সরাসরি নিষেধাজ্ঞা এসেছে, আর নিষেধের মূল অর্থ হারাম।", "en": "The hadith gives a direct prohibition, whose basic meaning is forbiddance."}}, {"label": {"bn": "শাফেয়ি ও মালেকি", "en": "Shafi''i and Maliki"}, "text": {"bn": "মাকরুহ তানযিহি (না কাটা সুন্নত, কাটলে গুনাহ নেই)।", "en": "Mildly disliked (not cutting is sunnah; cutting is not a sin)."}, "evidence": {"bn": "আয়েশা (রা.)-এর হাদিস: নবী (সা.) মদিনা থেকে কুরবানির পশু পাঠাতেন, কিন্তু ইহরামকারীর জন্য নিষিদ্ধ কোনো কিছু নিজের ওপর হারাম করতেন না।", "en": "Aishah''s hadith: the Prophet sent sacrificial animals from Madinah, yet did not make anything forbidden for himself that is forbidden to a pilgrim in ihram."}}, {"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "মুস্তাহাব; না কাটা উত্তম, কাটলে গুনাহ নেই। অনেক আলেম কুরবানি না দেওয়া ব্যক্তির জন্যও এতে শামিল হওয়া ভালো বলেছেন।", "en": "Recommended; not cutting is better and cutting is no sin. Many scholars say it is good for those not sacrificing to join in too."}, "evidence": {"bn": "দুটি হাদিসের সমন্বয়: নিষেধকে উত্তমতার অর্থে নেওয়া।", "en": "Reconciling the two hadiths by taking the prohibition as a recommendation."}}]}, {"type": "note", "tone": "info", "text": {"bn": "নিষেধটি কুরবানিদাতার নিজের জন্য, তার পরিবারের সবার জন্য নয়। ইহরামের মতো সুগন্ধি বা অন্য কিছু নিষেধ নয়।", "en": "The prohibition is for the person sacrificing, not his whole family. Nothing else, like perfume as in ihram, is forbidden."}}, {"type": "heading", "text": {"bn": "তাকবিরে তাশরিক", "en": "Takbir at-tashriq"}}, {"type": "arabic", "label": {"bn": "তাকবিরে তাশরিক", "en": "Takbir at-tashriq"}, "ar": "اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، لَا إِلَٰهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، وَلِلَّهِ الْحَمْدُ", "pron": {"bn": "আল্লাহু আকবার আল্লাহু আকবার, লা ইলাহা ইল্লাল্লাহু, ওয়াল্লাহু আকবার আল্লাহু আকবার, ওয়া লিল্লাহিল হামদ", "en": "Allahu akbar Allahu akbar, la ilaha illallah, wallahu akbar Allahu akbar, wa lillahil-hamd"}, "meaning": {"bn": "আল্লাহ সবচেয়ে মহান, আল্লাহ সবচেয়ে মহান; আল্লাহ ছাড়া কোনো ইলাহ নেই; আল্লাহ সবচেয়ে মহান, আল্লাহ সবচেয়ে মহান, আর সব প্রশংসা আল্লাহর।", "en": "Allah is the Greatest, Allah is the Greatest; there is no god but Allah; Allah is the Greatest, Allah is the Greatest, and to Allah belongs all praise."}, "ref": {"bn": "ইবনে মাসউদ রা. থেকে বর্ণিত (মুসান্নাফ ইবনে আবি শাইবা)", "en": "Reported from Ibn Mas''ud (Musannaf Ibn Abi Shaybah)"}, "check": true}, {"type": "arabic", "ar": "وَاذْكُرُوا اللَّهَ فِي أَيَّامٍ مَعْدُودَاتٍ", "pron": {"bn": "ওয়াযকুরুল্লাহা ফী আইয়ামিম মা''দূদাত", "en": "Wadhkurullaha fi ayyamim ma''dudat"}, "meaning": {"bn": "আর নির্দিষ্ট দিনগুলোতে আল্লাহকে স্মরণ করো।", "en": "And remember Allah during the appointed days."}, "ref": {"bn": "সূরা বাকারা ২:২০৩", "en": "Al-Baqarah 2:203"}}, {"type": "differ", "title": {"bn": "তাকবিরে তাশরিকের হুকুম ও দিন", "en": "Ruling and days of takbir at-tashriq"}, "views": [{"label": {"bn": "হানাফি (ফতোয়া: ইমাম আবু ইউসুফ ও মুহাম্মদের মত)", "en": "Hanafi (fatwa: the view of Abu Yusuf and Muhammad)"}, "text": {"bn": "৯ জিলহজ ফজর থেকে ১৩ জিলহজ আসর পর্যন্ত মোট ২৩ ওয়াক্ত ফরজ নামাজের পর একবার করে পড়া ওয়াজিব; পুরুষ উচ্চস্বরে, নারী নিচু স্বরে। একা বা জামাতে, মুকিম বা মুসাফির সবার জন্য। শুরুতে দুবার ''আল্লাহু আকবার''।", "en": "Wajib once after each of the 23 obligatory prayers from Fajr on the 9th to Asr on the 13th; men aloud, women quietly; alone or in congregation, resident or traveller. Two takbirs at the start."}, "evidence": {"bn": "আলী (রা.) আরাফার দিন ফজর থেকে আইয়ামে তাশরিকের শেষ দিনের আসর পর্যন্ত তাকবির বলতেন; শব্দ ইবনে মাসউদ (রা.) থেকে। (ইমাম আবু হানিফার মূল মত ছিল ইবনে মাসউদ রা.-এর অনুসরণে ১০ তারিখের আসর পর্যন্ত।)", "en": "Ali said the takbir from Fajr on the day of Arafah to Asr on the last day of Tashriq; the wording is from Ibn Mas''ud. (Abu Hanifa''s own view, following Ibn Mas''ud, was until Asr on the 10th.)"}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি", "en": "Shafi''i and Hanbali"}, "text": {"bn": "সুন্নত। হাজি নন এমন ব্যক্তির জন্য ৯ জিলহজ ফজর থেকে ১৩ জিলহজ আসর পর্যন্ত ফরজ নামাজের পর (মুকাইয়াদ); এ ছাড়া জিলহজের প্রথম থেকে সব সময় যেকোনো স্থানে তাকবির বলা (মুতলাক)। শাফেয়ি মতে শুরুতে তিনবার ''আল্লাহু আকবার''।", "en": "Sunnah. For non-pilgrims, after obligatory prayers from Fajr on the 9th to Asr on the 13th (restricted takbir), plus takbir at any time and place from the start of Dhul Hijjah (unrestricted). Shafi''is begin with three takbirs."}, "evidence": {"bn": "আলী (রা.) ও অন্যান্য সাহাবির আমল; ইবনে উমর (রা.) ও আবু হুরাইরা (রা.) এই দশ দিনে বাজারে তাকবির বলতেন (সহিহ বুখারিতে তালিক হিসেবে)।", "en": "Practice of Ali and other Companions; Ibn Umar and Abu Hurayrah said the takbir in the markets in these ten days (reported without chain in Sahih al-Bukhari)."}}, {"label": {"bn": "মালেকি", "en": "Maliki"}, "text": {"bn": "সুন্নত; ১০ জিলহজ জোহর থেকে ১৩ জিলহজ ফজর পর্যন্ত ১৫ ওয়াক্ত ফরজ নামাজের পর।", "en": "Sunnah; after 15 obligatory prayers from Zuhr on the 10th to Fajr on the 13th."}, "evidence": {"bn": "হাজিদের তালবিয়া শেষ হয়ে তাকবির শুরু হয় ১০ তারিখে; অন্যরা তাদের অনুসরণ করবে।", "en": "The pilgrims'' talbiyah ends and their takbir begins on the 10th; others follow them."}}]}, {"type": "note", "tone": "tip", "text": {"bn": "ঈদুল আজহার নামাজে যাওয়ার পথে উচ্চস্বরে তাকবির বলা সুন্নত।", "en": "Saying the takbir aloud on the way to the Eid al-Adha prayer is sunnah."}}]', 'in_review', 50 FROM is_guide_topics WHERE slug = 'qurbani' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '9f16b3e2-cd66-5676-8ea7-a15441515ef3', id, 'qurbani-aqiqah', '{"bn": "আকিকা: নিয়ম, পশু, নাম রাখা ও মাথা মুণ্ডন", "en": "Aqiqah: method, animals, naming and shaving the head"}', '{"bn": "সন্তান জন্মের পর আকিকা কখন ও কীভাবে করবেন, ছেলে ও মেয়ের জন্য কয়টি পশু, নাম রাখা, মাথা মুণ্ডন ও অন্যান্য সুন্নত।", "en": "When and how to do aqiqah after a birth, how many animals for a boy and a girl, naming, shaving the head and related sunnahs."}', 'basic', '[{"type": "text", "text": {"bn": "আকিকা মানে সন্তান জন্মের শুকরিয়া হিসেবে আল্লাহর জন্য পশু জবাই করা। নবী (সা.) বলেছেন: প্রত্যেক শিশু তার আকিকার সঙ্গে বন্ধক থাকে; সপ্তম দিনে তার পক্ষ থেকে পশু জবাই করা হবে, তার মাথা মুণ্ডন করা হবে এবং নাম রাখা হবে।", "en": "Aqiqah is slaughtering an animal for Allah in gratitude for a child''s birth. The Prophet said: every child is held in pledge by his aqiqah; an animal is slaughtered for him on the seventh day, his head is shaved and he is named."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ ২৮৩৮; জামে তিরমিজি ১৫২২", "en": "Sunan Abi Dawud 2838; Jami'' at-Tirmidhi 1522"}}, {"type": "differ", "title": {"bn": "আকিকার হুকুম", "en": "Ruling on aqiqah"}, "views": [{"label": {"bn": "শাফেয়ি, মালেকি, হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "সুন্নতে মুয়াক্কাদা; সাধারণত বাবা বা যার ওপর সন্তানের ভরণপোষণের দায়িত্ব, তিনি করবেন।", "en": "An emphasised sunnah, usually done by the father or whoever supports the child."}, "evidence": {"bn": "ওপরের হাদিস এবং নবী (সা.) কর্তৃক হাসান ও হুসাইন (রা.)-এর আকিকা।", "en": "The hadith above and the Prophet''s aqiqah for Al-Hasan and Al-Husayn."}}, {"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "মুস্তাহাব (শুকরিয়া হিসেবে উত্তম আমল); না করলে গুনাহ নেই।", "en": "Recommended (a good act of gratitude); no sin if not done."}, "evidence": {"bn": "কিছু বর্ণনায় নবী (সা.) বলেছেন, ''যে সন্তানের পক্ষ থেকে কুরবানি (আকিকা) করতে চায়, সে করুক'' — এতে ইচ্ছাধীনতা বোঝায় (আবু দাউদ, নাসায়ি)।", "en": "In some reports the Prophet said, ''Whoever wishes to sacrifice for his child, let him do so'' — indicating choice (Abu Dawud, an-Nasa''i)."}}], "check": true}, {"type": "heading", "text": {"bn": "কখন", "en": "When"}}, {"type": "list", "items": [{"bn": "জন্মের সপ্তম দিনে আকিকা করা সুন্নত (জন্মের দিনসহ গণনা; যেমন শুক্রবার জন্ম হলে পরের বৃহস্পতিবার)।", "en": "The sunnah is the seventh day (counting the day of birth; e.g. born on Friday, aqiqah on the next Thursday)."}, {"bn": "সপ্তম দিনে না পারলে কিছু আলেম ১৪ বা ২১ তম দিনের কথা বলেন (এ সম্পর্কিত বর্ণনা দুর্বল); না পারলে পরে যেকোনো সময় করা যায়।", "en": "If not possible on the seventh day, some scholars suggest the 14th or 21st (the report on this is weak); otherwise any time later."}, {"bn": "সন্তান সপ্তম দিনের আগে মারা গেলেও অনেক আলেমের মতে আকিকা করা যায়।", "en": "Many scholars allow aqiqah even if the child died before the seventh day."}]}, {"type": "heading", "text": {"bn": "কয়টি পশু", "en": "How many animals"}}, {"type": "table", "head": [{"bn": "সন্তান", "en": "Child"}, {"bn": "সুন্নত পরিমাণ", "en": "Sunnah amount"}, {"bn": "ন্যূনতম", "en": "Minimum"}], "rows": [[{"bn": "ছেলে", "en": "Boy"}, {"bn": "সমান মানের দুটি ছাগল/ভেড়া", "en": "Two comparable goats/sheep"}, {"bn": "একটি ছাগল/ভেড়াও যথেষ্ট", "en": "One goat/sheep also suffices"}], [{"bn": "মেয়ে", "en": "Girl"}, {"bn": "একটি ছাগল/ভেড়া", "en": "One goat/sheep"}, {"bn": "একটি", "en": "One"}]]}, {"type": "ref", "text": {"bn": "জামে তিরমিজি ১৫১৩", "en": "Jami'' at-Tirmidhi 1513"}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ (হাসান ও হুসাইন রা.-এর পক্ষ থেকে একটি করে দুম্বা)", "en": "Sunan Abi Dawud (one ram each for Al-Hasan and Al-Husayn)"}, "check": true}, {"type": "differ", "title": {"bn": "গরু বা উটের ভাগে আকিকা", "en": "Aqiqah as a share of a cow or camel"}, "views": [{"label": {"bn": "হানাফি ও শাফেয়ি", "en": "Hanafi and Shafi''i"}, "text": {"bn": "গরু বা উটের সাত ভাগের এক ভাগ দিয়ে আকিকা করা যায় (ছেলের জন্য দুই ভাগ); কুরবানির পশুতে আকিকার ভাগ রাখাও জায়েজ।", "en": "Aqiqah may be done with one seventh of a cow or camel (two sevenths for a boy); an aqiqah share in a qurbani animal is also allowed."}, "evidence": {"bn": "কুরবানির ওপর কিয়াস, যেখানে গরু-উট সাতজনের পক্ষ থেকে যথেষ্ট।", "en": "Analogy with qurbani, where a cow or camel suffices for seven."}}, {"label": {"bn": "মালেকি ও হাম্বলি", "en": "Maliki and Hanbali"}, "text": {"bn": "ভাগে আকিকা হয় না; পুরো একটি পশু লাগবে (গরু বা উট পুরোটা দিলে চলবে)।", "en": "Shares do not count for aqiqah; a whole animal is needed (a whole cow or camel is fine)."}, "evidence": {"bn": "আকিকা একটি জীবনের বিনিময়ে একটি পূর্ণ প্রাণ উৎসর্গ; হাদিসে ছাগল/ভেড়ার কথা এসেছে।", "en": "Aqiqah offers one whole life for a life; the hadith speaks of sheep and goats."}}]}, {"type": "note", "tone": "info", "text": {"bn": "আকিকার পশুর বয়স ও দোষত্রুটির শর্ত কুরবানির পশুর মতোই। জবাইয়ের নিয়মও একই।", "en": "The age and defect conditions for the aqiqah animal are the same as for qurbani, and so is the method of slaughter."}}, {"type": "arabic", "label": {"bn": "আকিকার জবাইয়ের সময় (ঐচ্ছিক)", "en": "At the aqiqah slaughter (optional)"}, "ar": "بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ، اللَّهُمَّ لَكَ وَإِلَيْكَ، هَٰذِهِ عَقِيقَةُ فُلَانٍ", "pron": {"bn": "বিসমিল্লাহি ওয়াল্লাহু আকবার, আল্লাহুম্মা লাকা ওয়া ইলাইকা, হাযিহি আকীকাতু (সন্তানের নাম)", "en": "Bismillahi wallahu akbar, Allahumma laka wa ilayk, hadhihi ''aqiqatu (child''s name)"}, "meaning": {"bn": "আল্লাহর নামে, আল্লাহ সবচেয়ে মহান। হে আল্লাহ! তোমারই জন্য এবং তোমারই কাছে। এটি অমুকের আকিকা।", "en": "In the name of Allah, Allah is the Greatest. O Allah, for You and to You. This is the aqiqah of (name)."}, "ref": {"bn": "আয়েশা রা. থেকে বর্ণিত (সুনানুল কুবরা, বায়হাকি)", "en": "Reported from Aishah (as-Sunan al-Kubra, al-Bayhaqi)"}, "check": true}, {"type": "note", "tone": "tip", "text": {"bn": "জরুরি শুধু ''বিসমিল্লাহ'' বলা; বাকিটা ঐচ্ছিক। সন্তানের নাম মুখে বলা শর্ত নয়, মনে নিয়ত থাকাই যথেষ্ট।", "en": "Only ''Bismillah'' is essential; the rest is optional. Saying the child''s name aloud is not a condition; the intention in the heart is enough."}}, {"type": "heading", "text": {"bn": "গোশত", "en": "The meat"}}, {"type": "text", "text": {"bn": "আকিকার গোশত কুরবানির মতো তিন ভাগ করা যায়, রান্না করে আত্মীয়-প্রতিবেশী ও গরিবদের খাওয়ানো যায়, কাঁচাও বিতরণ করা যায়। মা-বাবা ও পরিবারের সবাই খেতে পারেন। চামড়ার বিধান কুরবানির মতো।", "en": "The aqiqah meat may be divided in thirds like qurbani, cooked to feed relatives, neighbours and the poor, or given raw. Parents and the whole family may eat from it. The skin follows the qurbani ruling."}}, {"type": "heading", "text": {"bn": "নাম রাখা", "en": "Naming"}}, {"type": "list", "items": [{"bn": "জন্মের দিন বা সপ্তম দিনে নাম রাখা যায়; দুটোই হাদিসে এসেছে।", "en": "The child may be named on the day of birth or the seventh day; both are in the hadith."}, {"bn": "আল্লাহর কাছে সবচেয়ে প্রিয় নাম আবদুল্লাহ ও আবদুর রহমান। নবী-রাসুল ও সাহাবিদের নাম এবং সুন্দর অর্থের নাম রাখুন।", "en": "The names most beloved to Allah are Abdullah and Abdur-Rahman. Choose names of prophets and Companions and names with good meanings."}, {"bn": "আল্লাহ ছাড়া অন্য কারও দাসত্ব বোঝায় এমন নাম (যেমন আবদুন নবী, গোলাম রসুল) বা খারাপ অর্থের নাম রাখা যাবে না; নবী (সা.) খারাপ অর্থের নাম বদলে দিতেন।", "en": "Do not use names implying servitude to other than Allah (e.g. Abdun-Nabi, Ghulam Rasul) or with bad meanings; the Prophet used to change such names."}]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২১৩২", "en": "Sahih Muslim 2132"}}, {"type": "note", "tone": "tip", "text": {"bn": "এই অ্যাপের ''ইসলামিক নাম'' অংশ থেকে অর্থসহ নাম বাছাই করতে পারেন।", "en": "You can choose names with their meanings from this app''s Islamic Names section."}}, {"type": "heading", "text": {"bn": "মাথা মুণ্ডন ও অন্যান্য সুন্নত", "en": "Shaving the head and other sunnahs"}}, {"type": "step", "title": {"bn": "মাথা মুণ্ডন", "en": "Shave the head"}, "text": {"bn": "সপ্তম দিনে শিশুর (ছেলে-মেয়ে উভয়ের) মাথার চুল মুণ্ডন করা সুন্নত।", "en": "On the seventh day shaving the baby''s head (boy or girl) is sunnah."}}, {"type": "step", "title": {"bn": "চুলের ওজনে রূপা সদকা", "en": "Silver equal to the hair''s weight"}, "text": {"bn": "মুণ্ডিত চুলের ওজনের সমপরিমাণ রূপা (বা তার মূল্য) সদকা করা মুস্তাহাব; নবী (সা.) হাসান (রা.)-এর ক্ষেত্রে ফাতিমা (রা.)-কে এমন করতে বলেছিলেন।", "en": "Giving in charity silver equal to the weight of the shaved hair (or its value) is recommended; the Prophet told Fatimah to do this for Al-Hasan."}}, {"type": "ref", "text": {"bn": "জামে তিরমিজি (আলী রা.-এর বর্ণনা: হাসান রা.-এর চুলের ওজনে রূপা সদকা)", "en": "Jami'' at-Tirmidhi (Ali: silver equal to the weight of Al-Hasan''s hair)"}, "check": true}, {"type": "step", "title": {"bn": "তাহনিক", "en": "Tahnik"}, "text": {"bn": "কোনো নেককার ব্যক্তি খেজুর চিবিয়ে নরম করে শিশুর তালুতে সামান্য লাগিয়ে দেওয়া এবং বরকতের দোয়া করা সুন্নত; নবী (সা.) নবজাতকদের তাহনিক করতেন।", "en": "It is sunnah for a righteous person to chew a date until soft, rub a little on the baby''s palate and pray for blessing; the Prophet did tahnik for newborns."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি; সহিহ মুসলিম (আবু মুসা রা.-এর পুত্র ইবরাহিমের তাহনিক)", "en": "Sahih al-Bukhari; Sahih Muslim (tahnik of Abu Musa''s son Ibrahim)"}, "check": true}, {"type": "step", "title": {"bn": "কানে আজান", "en": "Adhan in the ear"}, "text": {"bn": "জন্মের পর শিশুর ডান কানে আজান দেওয়ার প্রচলন আছে। আবু রাফে (রা.) বর্ণনা করেন যে নবী (সা.) হাসান (রা.)-এর কানে আজান দিয়েছেন; তিরমিজি একে সহিহ বলেছেন, তবে অনেক হাদিসবিশারদ সনদকে দুর্বল বলেছেন। বাম কানে ইকামতের বর্ণনা আরও দুর্বল।", "en": "Giving the adhan in the newborn''s right ear is common practice. Abu Rafi'' reported that the Prophet gave the adhan in Al-Hasan''s ear; at-Tirmidhi graded it sound, but many hadith scholars consider the chain weak. The report of iqamah in the left ear is weaker still."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ; জামে তিরমিজি (আবু রাফে রা.-এর বর্ণনা)", "en": "Sunan Abi Dawud; Jami'' at-Tirmidhi (narration of Abu Rafi'')"}, "check": true}, {"type": "note", "tone": "warn", "text": {"bn": "শিশুর জন্মে কুসংস্কারমূলক রীতি (যেমন নির্দিষ্ট দিনে ঘর থেকে বের না হওয়া, তাবিজ ঝোলানো) থেকে বিরত থাকুন। মেয়ে সন্তানের জন্মে আনন্দ ও কৃতজ্ঞতা ছেলের মতোই।", "en": "Avoid superstitious customs around birth (such as not leaving the house on certain days, or hanging amulets). The birth of a daughter calls for the same joy and gratitude as a son."}}]', 'in_review', 60 FROM is_guide_topics WHERE slug = 'qurbani' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '5188e8f9-d532-5d8d-ac1f-a0c10b44deab', id, 'janazah-near-death', '{"bn": "মৃত্যুর সময় করণীয় ও তালকিন", "en": "Near Death: Care and Talqin"}', '{"bn": "মৃত্যুপথযাত্রী মানুষের পাশে কী করবেন: কালিমার তালকিন, দোয়া, আশা জাগানো এবং যা এড়িয়ে চলবেন।", "en": "What to do beside a dying person: gently prompting the kalimah, du''as, giving hope, and what to avoid."}', 'basic', '[{"type": "text", "text": {"bn": "মৃত্যু প্রত্যেকের জন্য নির্ধারিত। প্রিয়জনের শেষ সময়ে পাশে থাকা, তাকে আল্লাহর কথা মনে করিয়ে দেওয়া এবং শান্ত রাখা একটি বড় খেদমত।", "en": "Death comes to everyone. Being beside a loved one at the end, reminding them of Allah and keeping them calm is a great service."}}, {"type": "heading", "text": {"bn": "তালকিন: কালিমা মনে করিয়ে দেওয়া", "en": "Talqin: prompting the kalimah"}}, {"type": "arabic", "label": {"bn": "নবীজি (সা.)-এর নির্দেশ", "en": "The Prophet''s instruction"}, "ar": "لَقِّنُوا مَوْتَاكُمْ لَا إِلٰهَ إِلَّا اللّٰهُ", "pron": {"bn": "লাক্কিনূ মাওতাকুম লা ইলাহা ইল্লাল্লাহ।", "en": "Laqqinu mawtakum la ilaha illallah."}, "meaning": {"bn": "তোমাদের মৃত্যুপথযাত্রীদের ‘লা ইলাহা ইল্লাল্লাহ’-এর তালকিন দাও (মনে করিয়ে দাও)।", "en": "Prompt your dying ones with ''La ilaha illallah''."}, "ref": {"bn": "সহিহ মুসলিম ৯১৬", "en": "Sahih Muslim 916"}}, {"type": "text", "text": {"bn": "নবীজি (সা.) বলেছেন, যার শেষ কথা হবে ‘লা ইলাহা ইল্লাল্লাহ’, সে জান্নাতে প্রবেশ করবে (সুনান আবু দাউদ ৩১১৬)।", "en": "The Prophet said: whoever''s last words are ''La ilaha illallah'' will enter Paradise (Sunan Abi Dawud 3116)."}}, {"type": "list", "items": [{"bn": "রোগীর পাশে শান্ত স্বরে ‘লা ইলাহা ইল্লাল্লাহ’ বলুন, যাতে তিনি শুনে নিজেও বলেন। তাকে ‘বলুন, বলুন’ বলে চাপ দেবেন না।", "en": "Say ''La ilaha illallah'' softly near them so they hear and say it; do not pressure them with ''say it, say it''."}, {"bn": "একবার বলে ফেললে বারবার বলাবেন না; তবে এরপর অন্য কোনো কথা বললে আবার আস্তে করে মনে করিয়ে দিন।", "en": "Once they say it, do not keep repeating; if they speak of other things afterwards, gently remind them again."}, {"bn": "সম্ভব হলে তাকে কিবলামুখী করে শোয়ান, হানাফি মতে ডান কাতে; কষ্ট হলে যেভাবে আরাম পান সেভাবেই রাখুন।", "en": "If possible lay them facing the qiblah, on the right side in the Hanafi view; if uncomfortable, leave them as is."}, {"bn": "আল্লাহর রহমতের আশা জাগান। নবীজি (সা.) বলেছেন, তোমাদের কেউ যেন আল্লাহর প্রতি সুধারণা নিয়েই মৃত্যুবরণ করে (সহিহ মুসলিম ২৮৭৭)।", "en": "Give hope in Allah''s mercy. ''Let none of you die except thinking well of Allah'' (Sahih Muslim 2877)."}, {"bn": "শুধু ভালো কথা বলুন; নবীজি (সা.) বলেছেন, এ সময় ফেরেশতারা তোমাদের কথায় আমিন বলেন (সহিহ মুসলিম ৯২০)।", "en": "Speak only good; the Prophet said the angels say amin to what you say (Sahih Muslim 920)."}, {"bn": "ঋণ, আমানত, ওসিয়ত বা কারও হক থাকলে সময় থাকতে জেনে নিন ও লিখে রাখুন।", "en": "If there are debts, trusts, a will or others'' rights, find out and write them down while there is time."}]}, {"type": "heading", "text": {"bn": "মৃত্যুপথযাত্রীর নিজের দোয়া", "en": "The dying person''s own du''a"}}, {"type": "arabic", "label": {"bn": "নবীজি (সা.)-এর শেষ সময়ের দোয়া", "en": "The Prophet''s du''a in his final moments"}, "ar": "اللّٰهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَأَلْحِقْنِي بِالرَّفِيقِ الْأَعْلَى", "pron": {"bn": "আল্লাহুম্মাগফির লী ওয়ারহামনী ওয়া আলহিকনী বিররাফীকিল আ''লা।", "en": "Allahummaghfir li warhamni wa alhiqni bir-rafiqil-a''la."}, "meaning": {"bn": "হে আল্লাহ, আমাকে ক্ষমা করো, আমার প্রতি দয়া করো এবং আমাকে সর্বোচ্চ সঙ্গীর সাথে মিলিত করো।", "en": "O Allah, forgive me, have mercy on me, and join me with the highest companion."}, "ref": {"bn": "সহিহ বুখারি ৫৬৭৪", "en": "Sahih al-Bukhari 5674"}}, {"type": "arabic", "label": {"bn": "কষ্টে মৃত্যু কামনা না করে এই দোয়া", "en": "Instead of wishing for death in hardship"}, "ar": "اللّٰهُمَّ أَحْيِنِي مَا كَانَتِ الْحَيَاةُ خَيْرًا لِي، وَتَوَفَّنِي إِذَا كَانَتِ الْوَفَاةُ خَيْرًا لِي", "pron": {"bn": "আল্লাহুম্মা আহয়িনী মা কানাতিল হায়াতু খাইরাল লী, ওয়া তাওয়াফফানী ইযা কানাতিল ওয়াফাতু খাইরাল লী।", "en": "Allahumma ahyini ma kanatil-hayatu khayran li, wa tawaffani idha kanatil-wafatu khayran li."}, "meaning": {"bn": "হে আল্লাহ, যতদিন বেঁচে থাকা আমার জন্য কল্যাণকর, ততদিন আমাকে বাঁচিয়ে রাখো; আর যখন মৃত্যু আমার জন্য কল্যাণকর, তখন আমাকে মৃত্যু দাও।", "en": "O Allah, keep me alive as long as life is better for me, and take me when death is better for me."}, "ref": {"bn": "সহিহ বুখারি ৫৬৭১", "en": "Sahih al-Bukhari 5671"}}, {"type": "note", "tone": "warn", "text": {"bn": "রোগ বা কষ্টের কারণে মৃত্যু কামনা করা নিষেধ (সহিহ বুখারি ৫৬৭১); প্রয়োজনে উপরের দোয়াটি পড়ুন।", "en": "Wishing for death because of illness or hardship is forbidden (Sahih al-Bukhari 5671); say the du''a above instead."}}, {"type": "note", "tone": "info", "text": {"bn": "মৃত্যুপথযাত্রীর কাছে সূরা ইয়াসিন পড়ার হাদিস (সুনান আবু দাউদ ৩১২১) সনদের দিক থেকে দুর্বল বলে অনেক মুহাদ্দিস উল্লেখ করেছেন। তবু অনেক আলেম কুরআন পড়াকে ভালো বলেছেন; পড়লে আস্তে পড়ুন, যাতে রোগীর কষ্ট না হয়।", "en": "The hadith on reciting Ya-Sin to the dying (Sunan Abi Dawud 3121) is graded weak by many scholars. Many still consider reciting Quran good; if you do, recite softly so as not to disturb the person."}}]', 'in_review', 10 FROM is_guide_topics WHERE slug = 'janazah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'cf0821ad-8aeb-526f-be82-fee282d3df5a', id, 'janazah-after-death', '{"bn": "মৃত্যুর পর তাৎক্ষণিক করণীয়", "en": "Immediately After Death"}', '{"bn": "মৃত্যুর পর চোখ বন্ধ করা, দোয়া, শরীর ঢেকে রাখা, দ্রুত দাফনের প্রস্তুতি, ঋণ পরিশোধ ও শোক প্রকাশের সীমা।", "en": "Closing the eyes, du''as, covering the body, hastening the funeral, settling debts, and the limits of grief."}', 'basic', '[{"type": "arabic", "label": {"bn": "মৃত্যুর খবর শুনে", "en": "On hearing of a death"}, "ar": "إِنَّا لِلّٰهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، اللّٰهُمَّ أْجُرْنِي فِي مُصِيبَتِي وَأَخْلِفْ لِي خَيْرًا مِنْهَا", "pron": {"bn": "ইন্না লিল্লাহি ওয়া ইন্না ইলাইহি রাজিউন, আল্লাহুম্মা''জুরনী ফী মুসীবাতী ওয়া আখলিফ লী খাইরাম মিনহা।", "en": "Inna lillahi wa inna ilayhi raji''un, Allahumma''jurni fi musibati wa akhlif li khayran minha."}, "meaning": {"bn": "আমরা আল্লাহরই এবং তাঁর কাছেই ফিরে যাব। হে আল্লাহ, আমার এই বিপদে আমাকে প্রতিদান দাও এবং এর চেয়ে উত্তম কিছু আমাকে দান করো।", "en": "We belong to Allah and to Him we return. O Allah, reward me in my affliction and give me something better in its place."}, "ref": {"bn": "সূরা বাকারা ২:১৫৬; সহিহ মুসলিম ৯১৮", "en": "Al-Baqarah 2:156; Sahih Muslim 918"}}, {"type": "step", "title": {"bn": "চোখ বন্ধ করা", "en": "Close the eyes"}, "text": {"bn": "আস্তে করে চোখ বন্ধ করে দিন। নবীজি (সা.) আবু সালামা (রা.)-এর চোখ বন্ধ করে বলেছিলেন, রুহ কবজ হলে দৃষ্টি তার পিছু নেয় (সহিহ মুসলিম ৯২০)।", "en": "Gently close the eyes. The Prophet closed Abu Salamah''s eyes and said the sight follows the soul when it is taken (Sahih Muslim 920)."}}, {"type": "step", "title": {"bn": "দোয়া করা", "en": "Make du''a"}, "text": {"bn": "মৃত ব্যক্তির জন্য দোয়া করুন; নিচের দোয়ায় ‘ফুলান’-এর জায়গায় তার নাম বলুন।", "en": "Make du''a for the deceased; say their name in place of ''fulan'' below."}}, {"type": "arabic", "label": {"bn": "চোখ বন্ধ করার পর", "en": "After closing the eyes"}, "ar": "اللّٰهُمَّ اغْفِرْ لِفُلَانٍ، وَارْفَعْ دَرَجَتَهُ فِي الْمَهْدِيِّينَ، وَاخْلُفْهُ فِي عَقِبِهِ فِي الْغَابِرِينَ، وَاغْفِرْ لَنَا وَلَهُ يَا رَبَّ الْعَالَمِينَ، وَافْسَحْ لَهُ فِي قَبْرِهِ، وَنَوِّرْ لَهُ فِيهِ", "pron": {"bn": "আল্লাহুম্মাগফির লি(ফুলান), ওয়ারফা'' দারাজাতাহূ ফিল মাহদিয়্যীন, ওয়াখলুফহু ফী আকিবিহী ফিল গাবিরীন, ওয়াগফির লানা ওয়া লাহূ ইয়া রাব্বাল আলামীন, ওয়াফসাহ লাহূ ফী কাবরিহী, ওয়া নাওয়ির লাহূ ফীহ।", "en": "Allahummaghfir li-(fulan), warfa'' darajatahu fil-mahdiyyin, wakhlufhu fi ''aqibihi fil-ghabirin, waghfir lana wa lahu ya Rabbal-''alamin, wafsah lahu fi qabrihi, wa nawwir lahu fih."}, "meaning": {"bn": "হে আল্লাহ, অমুককে ক্ষমা করো, হেদায়াতপ্রাপ্তদের মধ্যে তার মর্যাদা বাড়িয়ে দাও, তার রেখে যাওয়া পরিবারের তুমি অভিভাবক হও; হে জগতসমূহের রব, আমাদের ও তাকে ক্ষমা করো, তার কবর প্রশস্ত করো এবং তার জন্য কবর আলোকিত করো।", "en": "O Allah, forgive (name), raise his rank among the guided, be the guardian of those he left behind, forgive us and him, O Lord of the worlds, widen his grave and give him light in it."}, "ref": {"bn": "সহিহ মুসলিম ৯২০", "en": "Sahih Muslim 920"}}, {"type": "step", "title": {"bn": "শরীর ঠিক করে ঢেকে দেওয়া", "en": "Straighten and cover the body"}, "text": {"bn": "চোয়াল একটি কাপড় দিয়ে মাথার সাথে আলতো বেঁধে দিন, হাত-পা সোজা করে দিন, পরনের কাপড় খুলে একটি চাদর দিয়ে পুরো শরীর ঢেকে দিন। পেটের ওপর ভারী কিছু রাখার প্রয়োজন নেই।", "en": "Tie the jaw gently with a strip of cloth, straighten the limbs, remove the clothes and cover the whole body with a sheet."}}, {"type": "step", "title": {"bn": "দ্রুত গোসল, কাফন ও দাফন", "en": "Hasten washing, shrouding and burial"}, "text": {"bn": "দেরি না করে গোসল, কাফন, জানাযা ও দাফনের ব্যবস্থা করুন। নবীজি (সা.) বলেছেন, জানাযা দ্রুত নিয়ে যাও (সহিহ বুখারি ১৩১৫)। দূরের আত্মীয়দের জন্য অযথা দীর্ঘ অপেক্ষা করবেন না।", "en": "Arrange washing, shrouding, prayer and burial without delay. ''Hasten with the funeral'' (Sahih al-Bukhari 1315). Do not wait unduly for distant relatives."}}, {"type": "step", "title": {"bn": "মানুষকে জানানো", "en": "Inform people"}, "text": {"bn": "আত্মীয়, প্রতিবেশী ও মসজিদে মৃত্যুর খবর ও জানাযার সময় জানানো জায়েজ, যাতে বেশি মানুষ জানাযায় আসে; নবীজি (সা.) নাজাশির মৃত্যুর খবর জানিয়েছিলেন (সহিহ বুখারি ১২৪৫)।", "en": "It is permissible to announce the death and funeral time so more people attend; the Prophet announced the death of the Negus (Sahih al-Bukhari 1245)."}}, {"type": "step", "title": {"bn": "ঋণ পরিশোধ ও ওসিয়ত", "en": "Pay debts and carry out the will"}, "text": {"bn": "মৃতের সম্পদ থেকে ক্রমানুসারে: কাফন-দাফনের খরচ, তারপর ঋণ পরিশোধ, তারপর ওসিয়ত (অনাত্মীয়দের জন্য সম্পদের সর্বোচ্চ এক-তৃতীয়াংশ), তারপর বাকিটা উত্তরাধিকারীদের মধ্যে ফারায়েজ অনুযায়ী বণ্টন। নবীজি (সা.) বলেছেন, মুমিনের রুহ তার ঋণের সাথে ঝুলে থাকে, যতক্ষণ না তা পরিশোধ করা হয় (জামে তিরমিজি ১০৭৮)।", "en": "From the estate, in order: funeral costs, then debts, then the will (at most one third, not for heirs), then the rest divided among the heirs by the shares of inheritance. ''The believer''s soul is held by his debt until it is paid'' (Jami'' al-Tirmidhi 1078)."}}, {"type": "ref", "text": {"bn": "ওসিয়ত এক-তৃতীয়াংশ: সহিহ বুখারি ২৭৪২", "en": "Will limited to one third: Sahih al-Bukhari 2742"}}, {"type": "heading", "text": {"bn": "শোক প্রকাশের সীমা", "en": "Limits of grief"}}, {"type": "text", "text": {"bn": "কান্না করা, চোখের পানি ফেলা স্বাভাবিক ও জায়েজ। পুত্র ইবরাহিমের মৃত্যুতে নবীজি (সা.)-এর চোখে পানি এসেছিল; তিনি বলেছিলেন, চোখ অশ্রু ঝরায়, হৃদয় ব্যথিত হয়, কিন্তু আমরা কেবল তা-ই বলি যাতে আমাদের রব সন্তুষ্ট (সহিহ বুখারি ১৩০৩)।", "en": "Crying and tears are natural and allowed. The Prophet wept at his son Ibrahim''s death and said: the eye weeps and the heart grieves, but we say only what pleases our Lord (Sahih al-Bukhari 1303)."}}, {"type": "note", "tone": "warn", "text": {"bn": "বিলাপ করে চিৎকার, গালে চড় মারা, কাপড় ছেঁড়া, বুক চাপড়ানো ও জাহেলি যুগের মতো কথা বলা নিষেধ: ‘সে আমাদের দলভুক্ত নয়, যে গালে আঘাত করে, কাপড় ছেঁড়ে এবং জাহেলি যুগের মতো আহাজারি করে’ (সহিহ বুখারি ১২৯৪)।", "en": "Wailing, slapping the cheeks, tearing clothes, beating the chest and words of the Jahiliyyah are forbidden: ''He is not of us who slaps his cheeks, tears his clothes and calls with the call of the Jahiliyyah'' (Sahih al-Bukhari 1294)."}}]', 'in_review', 20 FROM is_guide_topics WHERE slug = 'janazah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'ae28428a-f5e4-5552-8d19-ba14f77d1fa7', id, 'janazah-ghusl', '{"bn": "মৃতের গোসল", "en": "Washing the Deceased (Ghusl)"}', '{"bn": "মৃত ব্যক্তিকে গোসল দেওয়ার ধাপগুলো, কে গোসল দেবেন, এবং প্রয়োজনীয় সামগ্রী।", "en": "Step-by-step washing of the deceased, who should wash, and what you need."}', 'detail', '[{"type": "text", "text": {"bn": "মৃত মুসলিমকে গোসল দেওয়া ফরজে কিফায়া: কিছু মানুষ করলে সবার দায়িত্ব আদায় হয়। নবীজি (সা.) তাঁর কন্যার গোসলের সময় বলেছিলেন, তাকে বরই পাতার পানি দিয়ে তিন, পাঁচ বা প্রয়োজনে আরও বেশি বার গোসল দাও, শেষবার কর্পূর দাও (সহিহ বুখারি ১২৫৩), এবং ডান দিক ও ওযুর অঙ্গগুলো থেকে শুরু করো (সহিহ বুখারি ১২৫৫)।", "en": "Washing a deceased Muslim is a communal obligation. At his daughter''s washing the Prophet said: wash her three, five or more times with water and lote leaves, with camphor in the last (Sahih al-Bukhari 1253), and begin with the right side and the parts of wudu (Sahih al-Bukhari 1255)."}}, {"type": "heading", "text": {"bn": "কে গোসল দেবেন", "en": "Who washes"}}, {"type": "list", "items": [{"bn": "পুরুষকে পুরুষ, নারীকে নারী গোসল দেবেন; পরিবারের নিকটজন ও যারা নিয়ম জানেন, তারা অগ্রাধিকার পাবেন।", "en": "Men wash men and women wash women; close family and those who know the method come first."}, {"bn": "ছোট শিশুকে (যে এখনো কামনার বয়সে পৌঁছেনি) পুরুষ বা নারী যে কেউ গোসল দিতে পারেন।", "en": "A young child may be washed by a man or a woman."}, {"bn": "গোসলদাতা বিশ্বস্ত হবেন; মৃতের শরীরে কোনো খারাপ কিছু দেখলে তা গোপন রাখবেন।", "en": "The washer should be trustworthy and keep private anything unpleasant they see."}]}, {"type": "differ", "title": {"bn": "স্বামী-স্ত্রী একে অপরকে গোসল দিতে পারবেন কি", "en": "May spouses wash each other"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "স্ত্রী মৃত স্বামীকে গোসল দিতে পারেন (ইদ্দত চলাকালে বিবাহের কিছু বিধান বহাল থাকে)। কিন্তু স্বামী মৃত স্ত্রীকে গোসল দিতে পারবেন না; মৃত্যুতে বিবাহের সম্পর্ক শেষ হয়ে যায়। তবে দেখতে ও কাফনের ওপর দিয়ে স্পর্শ করতে পারবেন।", "en": "A wife may wash her deceased husband (some marriage rulings continue during her ''iddah), but a husband may not wash his deceased wife, as the marriage ends with her death; he may see her and touch her over the shroud."}, "evidence": {"bn": "আয়েশা (রা.) বলেছেন, যা পরে জেনেছি তা আগে জানলে নবীজি (সা.)-কে তাঁর স্ত্রীরাই গোসল দিতেন (সুনান আবু দাউদ); স্ত্রীর ইদ্দত পালন বিবাহের প্রভাব বহাল থাকার প্রমাণ।", "en": "''A''ishah said that had she known earlier what she later knew, only his wives would have washed the Prophet (Sunan Abi Dawud); the widow''s ''iddah shows the marriage''s effects continue."}}, {"label": {"bn": "শাফেয়ি, মালেকি ও হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "স্বামী-স্ত্রী পরস্পরকে গোসল দিতে পারেন।", "en": "Spouses may wash each other."}, "evidence": {"bn": "নবীজি (সা.) আয়েশা (রা.)-কে বলেছিলেন, তুমি আমার আগে মারা গেলে আমি তোমাকে গোসল দিতাম ও কাফন পরাতাম (সুনান ইবনে মাজাহ ১৪৬৫); আলী (রা.) ফাতিমা (রা.)-কে গোসল দিয়েছিলেন বলে বর্ণিত।", "en": "The Prophet told ''A''ishah that if she died before him he would wash and shroud her (Sunan Ibn Majah 1465); ''Ali is reported to have washed Fatimah."}}], "check": true}, {"type": "heading", "text": {"bn": "প্রয়োজনীয় সামগ্রী", "en": "What you need"}}, {"type": "list", "items": [{"bn": "গোসলের খাটিয়া বা উঁচু তক্তা, পর্দা দেওয়া আড়াল", "en": "A washing board or raised bed, and a screened area"}, {"bn": "কুসুম গরম পানি, সাবান বা বরই পাতা মেশানো পানি, কর্পূর", "en": "Lukewarm water, soap or water with lote (boroi) leaves, camphor"}, {"bn": "সতর ঢাকার কাপড় (নাভি থেকে হাঁটু পর্যন্ত), হাতমোজা বা হাতে জড়ানোর কাপড়", "en": "A cloth to cover the awrah (navel to knee), gloves or hand cloths"}, {"bn": "তুলা, তোয়ালে, আতর বা সুগন্ধি, আগে থেকে প্রস্তুত কাফন", "en": "Cotton, towels, perfume, and the shroud ready beforehand"}]}, {"type": "heading", "text": {"bn": "গোসলের ধাপ", "en": "Steps of the ghusl"}}, {"type": "step", "title": {"bn": "খাটিয়ায় রাখা ও সতর ঢাকা", "en": "Place on the board and cover"}, "text": {"bn": "মৃতকে খাটিয়ায় রাখুন, সতর (নাভি থেকে হাঁটু) কাপড়ে ঢেকে পরনের কাপড় খুলে নিন। সতরের দিকে তাকাবেন না।", "en": "Lay the body on the board, cover the awrah (navel to knee), then remove the clothes. Do not look at the awrah."}}, {"type": "step", "title": {"bn": "পেট হালকা চেপে ইস্তিঞ্জা", "en": "Press the stomach and clean"}, "text": {"bn": "প্রাপ্তবয়স্ক হলে আস্তে করে পেটে চাপ দিন, যাতে ময়লা বের হয়ে যায়। হাতে কাপড় বা গ্লাভস পরে ঢাকা অবস্থায় লজ্জাস্থান পরিষ্কার করুন।", "en": "For an adult, gently press the stomach to expel waste. Wearing a glove or cloth, wash the private parts under the cover."}}, {"type": "step", "title": {"bn": "ওযু করানো", "en": "Give wudu"}, "text": {"bn": "নামাজের ওযুর মতো ওযু করান: চেহারা, হাত কনুই পর্যন্ত, মাথা মাসেহ, পা। হানাফি মতে কুলি ও নাকে পানি দেওয়া হয় না; ভেজা কাপড় বা তুলা দিয়ে দাঁত, মাড়ি ও নাকের ছিদ্র মুছে দিন, যাতে ভেতরে পানি না ঢোকে।", "en": "Perform wudu as for prayer: face, arms to the elbows, wipe the head, feet. Hanafis do not rinse the mouth and nose; wipe the teeth, gums and nostrils with wet cloth or cotton so water does not enter."}}, {"type": "step", "title": {"bn": "মাথা ও দাড়ি ধোয়া", "en": "Wash head and beard"}, "text": {"bn": "সাবান বা বরই পাতার পানি দিয়ে মাথা ও দাড়ি (বা চুল) ধুয়ে দিন।", "en": "Wash the head and beard (or hair) with soap or lote-leaf water."}}, {"type": "step", "title": {"bn": "বাম কাতে শুইয়ে ডান পাশ ধোয়া", "en": "Right side first"}, "text": {"bn": "মৃতকে বাম কাতে শুইয়ে মাথা থেকে পা পর্যন্ত ডান পাশে পানি ঢালুন, যতক্ষণ না পানি নিচ পর্যন্ত পৌঁছায় (সাধারণত তিনবার)।", "en": "Turn the body onto the left side and pour water over the right side from head to foot until it reaches underneath (usually three times)."}}, {"type": "step", "title": {"bn": "ডান কাতে শুইয়ে বাম পাশ ধোয়া", "en": "Then the left side"}, "text": {"bn": "এবার ডান কাতে শুইয়ে একইভাবে বাম পাশ ধুয়ে দিন।", "en": "Turn onto the right side and wash the left side the same way."}}, {"type": "step", "title": {"bn": "আবার পেট চেপে দেখা", "en": "Press the stomach again"}, "text": {"bn": "মৃতকে নিজের গায়ে হেলান দিয়ে একটু বসিয়ে আস্তে পেটে চাপ দিন। কিছু বের হলে শুধু সেই জায়গা ধুয়ে দিন; গোসল বা ওযু আবার করাতে হবে না (হানাফি)।", "en": "Sit the body up slightly against you and gently press the stomach. If anything comes out, wash only that area; the ghusl or wudu need not be repeated (Hanafi)."}}, {"type": "step", "title": {"bn": "শেষবার কর্পূর মেশানো পানি", "en": "Last wash with camphor"}, "text": {"bn": "শেষে কর্পূর মেশানো পানি পুরো শরীরে ঢালুন। মোট ধোয়া বেজোড় সংখ্যক হওয়া সুন্নত (তিন, পাঁচ বা সাত)।", "en": "Finally pour camphor water over the whole body. An odd number of washes is sunnah (three, five or seven)."}}, {"type": "step", "title": {"bn": "শুকানো ও সুগন্ধি", "en": "Dry and perfume"}, "text": {"bn": "তোয়ালে দিয়ে আস্তে মুছে দিন। মাথা ও দাড়িতে আতর, আর সিজদার অঙ্গগুলোতে (কপাল, নাক, দুই হাত, দুই হাঁটু, দুই পা) কর্পূর লাগান। তারপর কাফন পরান।", "en": "Pat dry with a towel. Apply perfume to the head and beard and camphor to the places of sajdah (forehead, nose, hands, knees, feet). Then shroud."}}, {"type": "note", "tone": "info", "text": {"bn": "হানাফি মতে মৃতের চুল আঁচড়ানো, নখ বা চুল কাটা হয় না। যুদ্ধক্ষেত্রে শহিদ হলে তাকে গোসল দেওয়া হয় না, পরনের কাপড়েই দাফন করা হয়; এর বিস্তারিত বিধান আলেমদের কাছে জেনে নিন।", "en": "In the Hanafi school the hair is not combed and nails and hair are not cut. A martyr killed in battle is not washed and is buried in his clothes; ask scholars for the details."}}, {"type": "note", "tone": "tip", "text": {"bn": "গোসলদাতার জন্য পরে নিজে গোসল করা মুস্তাহাব (সুনান আবু দাউদ ৩১৬১; এই হাদিসের মান নিয়ে মতভেদ আছে)।", "en": "It is recommended for the washer to bathe afterwards (Sunan Abi Dawud 3161; its grading is disputed)."}}]', 'in_review', 30 FROM is_guide_topics WHERE slug = 'janazah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '42081037-41f1-5482-82c5-2ed9fe3866bf', id, 'janazah-kafan', '{"bn": "কাফন: পুরুষ ও নারীর জন্য", "en": "The Shroud (Kafan) for Men and Women"}', '{"bn": "সুন্নত কাফনের কাপড়, পুরুষের তিন ও নারীর পাঁচ কাপড়, এবং কাফন পরানোর ধাপ।", "en": "The sunnah shroud: three pieces for men, five for women, and how to wrap."}', 'detail', '[{"type": "text", "text": {"bn": "কাফন সাদা কাপড়ের হওয়া উত্তম: ‘তোমরা সাদা কাপড় পরো, কারণ তা তোমাদের উত্তম পোশাক, আর এতে তোমাদের মৃতদের কাফন দাও’ (সুনান আবু দাউদ ৩৮৭৮; জামে তিরমিজি ৯৯৪)। নবীজি (সা.)-কে তিনটি সাদা ইয়েমেনি সুতি কাপড়ে কাফন দেওয়া হয়েছিল, তাতে জামা বা পাগড়ি ছিল না (সহিহ বুখারি ১২৬৪)। কাফনের খরচ মৃতের সম্পদ থেকে সবার আগে দেওয়া হয়; সাধ্যের বাইরে দামি কাফন জরুরি নয়।", "en": "White is best: ''Wear white, for it is among your best clothes, and shroud your dead in it'' (Sunan Abi Dawud 3878; Jami'' al-Tirmidhi 994). The Prophet was shrouded in three white Yemeni cotton sheets, with no shirt or turban (Sahih al-Bukhari 1264). The shroud is paid from the estate first; an expensive shroud is not needed."}}, {"type": "table", "head": [{"bn": "কাপড়", "en": "Piece"}, {"bn": "বিবরণ (হানাফি পরিভাষা)", "en": "Description (Hanafi terms)"}, {"bn": "পুরুষ", "en": "Men"}, {"bn": "নারী", "en": "Women"}], "rows": [[{"bn": "লিফাফা (চাদর)", "en": "Lifafah (outer sheet)"}, {"bn": "মাথার ওপর থেকে পায়ের নিচ পর্যন্ত, দুই প্রান্তে বাঁধার মতো বাড়তি", "en": "From above the head to below the feet, with extra to tie at both ends"}, {"bn": "✓", "en": "✓"}, {"bn": "✓", "en": "✓"}], [{"bn": "ইজার", "en": "Izar (inner sheet)"}, {"bn": "মাথা থেকে পা পর্যন্ত", "en": "From head to feet"}, {"bn": "✓", "en": "✓"}, {"bn": "✓", "en": "✓"}], [{"bn": "কামিস (কোর্তা)", "en": "Qamis (shirt)"}, {"bn": "কাঁধ থেকে হাঁটুর নিচ পর্যন্ত, হাতা ও কলি ছাড়া, মাথা ঢোকানোর ফাঁক থাকে", "en": "Shoulders to below the knees, without sleeves or side panels, with a slit for the head"}, {"bn": "✓", "en": "✓"}, {"bn": "✓", "en": "✓"}], [{"bn": "ওড়না (খিমার)", "en": "Khimar (head cover)"}, {"bn": "মাথা ও চুল ঢাকার কাপড়", "en": "Covers the head and hair"}, {"bn": "—", "en": "—"}, {"bn": "✓", "en": "✓"}], [{"bn": "সিনাবন্দ", "en": "Sinaband (chest wrap)"}, {"bn": "বুক থেকে উরু পর্যন্ত", "en": "From the chest to the thighs"}, {"bn": "—", "en": "—"}, {"bn": "✓", "en": "✓"}]]}, {"type": "text", "text": {"bn": "পুরুষের সুন্নত কাফন তিন কাপড়; প্রয়োজনে দুই কাপড়ও যথেষ্ট (কিফায়া)। নারীর সুন্নত কাফন পাঁচ কাপড়; প্রয়োজনে তিন কাপড় (লিফাফা, ইজার, ওড়না) যথেষ্ট। নিরুপায় অবস্থায় যতটুকু পাওয়া যায়, তাতেই শরীর ঢেকে দেওয়া হবে।", "en": "The sunnah shroud for men is three pieces; two suffice if needed. For women it is five; three (lifafah, izar, khimar) suffice if needed. In necessity, cover the body with whatever is available."}}, {"type": "note", "tone": "info", "text": {"bn": "নারীর পাঁচ কাপড়ের হাদিস (সুনান আবু দাউদ ৩১৫৭) সনদের দিক থেকে দুর্বল বলে মুহাদ্দিসরা উল্লেখ করেছেন; তবে চার মাজহাবেই নারীর জন্য পাঁচ কাপড় সুন্নত বলা হয়েছে (কাপড়ের ধরনে কিছু ভিন্নতাসহ)।", "en": "The hadith on five pieces for women (Sunan Abi Dawud 3157) is graded weak, but all four schools hold five pieces sunnah for women (with some differences in the pieces)."}}, {"type": "heading", "text": {"bn": "পুরুষের কাফন পরানো", "en": "Shrouding a man"}}, {"type": "step", "title": {"bn": "কাপড় বিছানো", "en": "Lay out the sheets"}, "text": {"bn": "প্রথমে লিফাফা বিছান, তার ওপর ইজার, তার ওপর কামিসের নিচের অংশ (ওপরের অংশ মাথার দিকে গুটিয়ে রাখুন)। চাইলে কাপড়ে বেজোড় সংখ্যায় সুগন্ধির ধোঁয়া দিতে পারেন।", "en": "Spread the lifafah, then the izar on it, then the lower half of the qamis (fold the upper half towards the head)."}}, {"type": "step", "title": {"bn": "কামিস পরানো", "en": "Put on the qamis"}, "text": {"bn": "মৃতকে শুইয়ে কামিসের ওপরের অংশ মাথা গলিয়ে বুক ও শরীরের ওপর টেনে দিন; সতরের কাপড় সরিয়ে নিন।", "en": "Lay the body down, pass the qamis over the head and draw it down over the body; remove the awrah cloth."}}, {"type": "step", "title": {"bn": "ইজার মোড়ানো", "en": "Wrap the izar"}, "text": {"bn": "ইজারের বাম পাশ আগে শরীরের ওপর ভাঁজ করুন, তারপর ডান পাশ ওপরে দিন।", "en": "Fold the left side of the izar over the body first, then the right side over it."}}, {"type": "step", "title": {"bn": "লিফাফা মোড়ানো ও বাঁধা", "en": "Wrap and tie the lifafah"}, "text": {"bn": "একইভাবে লিফাফার বাম পাশ, তারপর ডান পাশ ভাঁজ করুন। খুলে যাওয়ার আশঙ্কা থাকলে মাথা, কোমর ও পায়ের দিকে কাপড়ের ফিতা দিয়ে বেঁধে দিন; কবরে রাখার পর বাঁধনগুলো খুলে দেবেন।", "en": "Fold the lifafah left then right in the same way. Tie strips at the head, waist and feet if it may open; untie them in the grave."}}, {"type": "heading", "text": {"bn": "নারীর কাফন পরানো", "en": "Shrouding a woman"}}, {"type": "step", "title": {"bn": "কাপড় বিছানো", "en": "Lay out the sheets"}, "text": {"bn": "প্রথমে লিফাফা, তার ওপর সিনাবন্দ (কেউ কেউ শেষে ওপরে বাঁধেন), তার ওপর ইজার, তার ওপর কামিস বিছান।", "en": "Spread the lifafah, then the sinaband (some tie it last, on top), then the izar, then the qamis."}}, {"type": "step", "title": {"bn": "কামিস ও চুল", "en": "Qamis and hair"}, "text": {"bn": "কামিস পরিয়ে দিন। চুল দুই ভাগ করে কামিসের ওপর বুকের দুই পাশে রেখে দিন।", "en": "Put on the qamis. Divide the hair into two parts and place them on the chest over the qamis."}}, {"type": "step", "title": {"bn": "ওড়না", "en": "Khimar"}, "text": {"bn": "ওড়না দিয়ে মাথা ও চুল ঢেকে দিন; বাঁধবেন না, পেঁচাবেন না।", "en": "Cover the head and hair with the khimar, without tying or twisting it."}}, {"type": "step", "title": {"bn": "ইজার, সিনাবন্দ ও লিফাফা", "en": "Izar, sinaband and lifafah"}, "text": {"bn": "ইজার বাম তারপর ডান পাশ থেকে মোড়ান, তারপর সিনাবন্দ বুক থেকে উরু পর্যন্ত বেঁধে দিন, সবশেষে লিফাফা বাম তারপর ডান পাশ থেকে মুড়িয়ে প্রয়োজনে মাথা, কোমর ও পায়ের দিকে বেঁধে দিন।", "en": "Wrap the izar left then right, tie the sinaband from chest to thighs, then wrap the lifafah left then right and tie at the head, waist and feet if needed."}}, {"type": "note", "tone": "warn", "text": {"bn": "কাফনে কালিমা, আয়াত বা দোয়া লেখার প্রথা কুরআন-সুন্নাহয় নেই; কাপড় নাপাক হওয়ার আশঙ্কায় অনেক আলেম এ থেকে নিষেধ করেছেন।", "en": "Writing the kalimah, verses or du''as on the shroud has no basis in the Quran or sunnah; many scholars forbid it since the cloth may become impure."}}]', 'in_review', 40 FROM is_guide_topics WHERE slug = 'janazah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '2e749364-1451-5174-b322-2853dd48c913', id, 'janazah-prayer', '{"bn": "জানাযার নামাজ: ধাপে ধাপে", "en": "Janazah Prayer Step by Step"}', '{"bn": "চার তাকবিরের জানাযার নামাজ: প্রতিটি তাকবিরের পর কী পড়বেন, প্রাপ্তবয়স্ক নারী-পুরুষ ও শিশুর জন্য দোয়া, এবং মতভেদের বিষয়গুলো।", "en": "The four-takbir funeral prayer: what to recite after each takbir, du''as for adults (male and female) and children, and points of difference."}', 'basic', '[{"type": "text", "text": {"bn": "জানাযার নামাজ ফরজে কিফায়া। এতে রুকু-সিজদা নেই; দাঁড়িয়ে চার তাকবিরে পড়া হয়। নবীজি (সা.) নাজাশির জানাযায় চার তাকবির দিয়েছিলেন (সহিহ বুখারি ১২৪৫)। নামাজের মতোই ওযু, পবিত্রতা, সতর ঢাকা ও কিবলামুখী হওয়া শর্ত।", "en": "The funeral prayer is a communal obligation. It has no ruku'' or sajdah; it is prayed standing with four takbirs. The Prophet made four takbirs over the Negus (Sahih al-Bukhari 1245). Wudu, purity, covered awrah and facing the qiblah are required as for prayer."}}, {"type": "arabic", "label": {"bn": "ফজিলত", "en": "Virtue"}, "ar": "مَنْ شَهِدَ الْجَنَازَةَ حَتَّى يُصَلَّى عَلَيْهَا فَلَهُ قِيرَاطٌ، وَمَنْ شَهِدَهَا حَتَّى تُدْفَنَ فَلَهُ قِيرَاطَانِ", "pron": {"bn": "মান শাহিদাল জানাযাতা হাত্তা ইউসাল্লা আলাইহা ফালাহূ কীরাত, ওয়া মান শাহিদাহা হাত্তা তুদফানা ফালাহূ কীরাতান।", "en": "Man shahidal-janazata hatta yusalla ''alayha falahu qirat, wa man shahidaha hatta tudfana falahu qiratan."}, "meaning": {"bn": "যে জানাযায় উপস্থিত থেকে নামাজ পড়ে, তার জন্য এক কিরাত সওয়াব; আর যে দাফন পর্যন্ত থাকে, তার জন্য দুই কিরাত। জিজ্ঞেস করা হলো, দুই কিরাত কী? তিনি বললেন, দুটি বিশাল পাহাড়ের সমান।", "en": "Whoever attends a funeral until the prayer gets one qirat of reward; whoever stays until burial gets two qirats, like two great mountains."}, "ref": {"bn": "সহিহ বুখারি ১৩২৫", "en": "Sahih al-Bukhari 1325"}}, {"type": "heading", "text": {"bn": "প্রস্তুতি", "en": "Preparation"}}, {"type": "list", "items": [{"bn": "লাশ ইমামের সামনে কিবলার দিকে রাখা হবে, মাথা উত্তর দিকে (বাংলাদেশে) থাকে।", "en": "The body is placed in front of the imam towards the qiblah, with the head to the north (in Bangladesh)."}, {"bn": "কাতার বেজোড় সংখ্যায় করা মুস্তাহাব বলে অনেকে উল্লেখ করেন; তিন কাতারের ফজিলতের হাদিস (সুনান আবু দাউদ ৩১৬৬) দুর্বল।", "en": "Many prefer an odd number of rows; the hadith on three rows (Sunan Abi Dawud 3166) is weak."}, {"bn": "নিয়ত মনে মনে। উদাহরণ (প্রচলিত বাংলা): ‘আমি এই মাইয়্যেতের জানাযার নামাজ চার তাকবিরের সাথে আল্লাহর জন্য, মাইয়্যেতের জন্য দোয়া হিসেবে, এই ইমামের পেছনে আদায় করছি।’ মুখে বলা জরুরি নয়।", "en": "Niyyah in the heart. Example (common Bangla phrasing): ''I am praying the funeral prayer for this deceased with four takbirs, for Allah, as a du''a for the deceased, behind this imam.'' Saying it is not required."}]}, {"type": "differ", "title": {"bn": "ইমাম লাশের কোন বরাবর দাঁড়াবেন", "en": "Where the imam stands"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "পুরুষ ও নারী উভয়ের ক্ষেত্রে বুক বরাবর।", "en": "At the chest, for both men and women."}, "evidence": {"bn": "বুক ঈমানের স্থান; সাহাবিদের কিছু আমল থেকে নেওয়া।", "en": "The chest is the seat of faith; based on some Companions'' practice."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি", "en": "Shafi''i and Hanbali"}, "text": {"bn": "পুরুষের মাথা বরাবর, নারীর কোমর (মাঝখান) বরাবর।", "en": "At the head of a man and the middle of a woman."}, "evidence": {"bn": "নবীজি (সা.) প্রসবকালে মৃত এক নারীর জানাযায় তার মাঝখান বরাবর দাঁড়িয়েছিলেন (সহিহ বুখারি ১৩৩২); আনাস (রা.) পুরুষের মাথা ও নারীর মাঝখান বরাবর দাঁড়াতেন (সুনান আবু দাউদ ৩১৯৪; জামে তিরমিজি ১০৩৪)।", "en": "The Prophet stood at the middle of a woman who died in childbirth (Sahih al-Bukhari 1332); Anas stood at a man''s head and a woman''s middle (Sunan Abi Dawud 3194; Jami'' al-Tirmidhi 1034)."}}]}, {"type": "heading", "text": {"bn": "প্রথম তাকবির ও সানা", "en": "First takbir and thana"}}, {"type": "step", "title": {"bn": "প্রথম তাকবির", "en": "First takbir"}, "text": {"bn": "কান পর্যন্ত হাত তুলে ‘আল্লাহু আকবার’ বলে নাভির নিচে (নারীরা বুকে) হাত বাঁধুন। ইমাম জোরে তাকবির বলবেন, মুক্তাদিরা আস্তে।", "en": "Raise the hands to the ears saying ''Allahu Akbar'' and fold them. The imam says the takbirs aloud, followers quietly."}}, {"type": "arabic", "label": {"bn": "তাকবির", "en": "Takbir"}, "ar": "اللّٰهُ أَكْبَرُ", "pron": {"bn": "আল্লাহু আকবার", "en": "Allahu Akbar"}, "meaning": {"bn": "আল্লাহ সবচেয়ে বড়।", "en": "Allah is the Greatest."}}, {"type": "arabic", "label": {"bn": "সানা (প্রথম তাকবিরের পর, হানাফি)", "en": "Thana (after the first takbir, Hanafi)"}, "ar": "سُبْحَانَكَ اللّٰهُمَّ وَبِحَمْدِكَ، وَتَبَارَكَ اسْمُكَ، وَتَعَالَىٰ جَدُّكَ، وَجَلَّ ثَنَاؤُكَ، وَلَا إِلٰهَ غَيْرُكَ", "pron": {"bn": "সুবহানাকা আল্লাহুম্মা ওয়া বিহামদিকা, ওয়া তাবারাকাসমুকা, ওয়া তাআলা জাদ্দুকা, ওয়া জাল্লা সানাউকা, ওয়া লা ইলাহা গাইরুক।", "en": "Subhanakallahumma wa bihamdika, wa tabarakasmuka, wa ta''ala jadduka, wa jalla thana''uka, wa la ilaha ghayruk."}, "meaning": {"bn": "হে আল্লাহ, তুমি পবিত্র, সকল প্রশংসা তোমার; তোমার নাম বরকতময়, তোমার মর্যাদা সুউচ্চ, তোমার প্রশংসা মহান; আর তুমি ছাড়া কোনো ইলাহ নেই।", "en": "Glory be to You, O Allah, and praise; blessed is Your name, exalted is Your majesty, great is Your praise, and there is no god besides You."}, "ref": {"bn": "মূল সানা: সুনান আবু দাউদ ৭৭৬", "en": "Base thana: Sunan Abi Dawud 776"}}, {"type": "note", "tone": "info", "text": {"bn": "‘ওয়া জাল্লা সানাউকা’ অংশটি সাধারণ নামাজের সানার হাদিসে (আবু দাউদ ৭৭৬) নেই; হানাফি ফিকহের কিতাবে জানাযার সানায় এটি যোগ করার কথা বলা হয়েছে। না বললেও নামাজ হয়ে যাবে।", "en": "The phrase ''wa jalla thana''uka'' is not in the hadith of the regular thana (Abu Dawud 776); Hanafi fiqh books add it in the funeral thana. The prayer is valid without it."}}, {"type": "differ", "title": {"bn": "প্রথম তাকবিরের পর সানা না সূরা ফাতিহা", "en": "Thana or al-Fatihah after the first takbir"}, "views": [{"label": {"bn": "হানাফি ও মালেকি", "en": "Hanafi and Maliki"}, "text": {"bn": "সানা পড়বে; জানাযায় কিরাত হিসেবে সূরা ফাতিহা পড়া জরুরি নয়। (হানাফি মতে কেউ সানা ও প্রশংসার নিয়তে ফাতিহা পড়লে সমস্যা নেই।)", "en": "Recite the thana; al-Fatihah is not required as recitation (Hanafis allow it with the intention of praise)."}, "evidence": {"bn": "জানাযা মূলত মৃতের জন্য দোয়া; ইবনে মাসউদ (রা.) প্রমুখ সাহাবি থেকে জানাযায় নির্দিষ্ট কিরাত না থাকার কথা বর্ণিত।", "en": "The funeral prayer is essentially du''a; reports from Ibn Mas''ud and others that it has no fixed recitation."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি", "en": "Shafi''i and Hanbali"}, "text": {"bn": "প্রথম তাকবিরের পর সূরা ফাতিহা পড়া ফরজ/রুকন।", "en": "Reciting al-Fatihah after the first takbir is obligatory."}, "evidence": {"bn": "ইবনে আব্বাস (রা.) জানাযায় সূরা ফাতিহা পড়ে বললেন, যাতে তোমরা জানো এটি সুন্নত (সহিহ বুখারি ১৩৩৫)।", "en": "Ibn ''Abbas recited al-Fatihah in a funeral prayer and said, ''so that you know it is the sunnah'' (Sahih al-Bukhari 1335)."}}]}, {"type": "heading", "text": {"bn": "দ্বিতীয় তাকবির ও দরুদ", "en": "Second takbir and durood"}}, {"type": "step", "title": {"bn": "দ্বিতীয় তাকবির", "en": "Second takbir"}, "text": {"bn": "হাত না তুলে (হানাফি) ‘আল্লাহু আকবার’ বলুন এবং দরুদে ইবরাহিম পড়ুন।", "en": "Say ''Allahu Akbar'' without raising the hands (Hanafi) and recite the durood Ibrahim."}}, {"type": "arabic", "label": {"bn": "দরুদে ইবরাহিম", "en": "Durood Ibrahim"}, "ar": "اللّٰهُمَّ صَلِّ عَلَىٰ مُحَمَّدٍ وَعَلَىٰ آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَىٰ إِبْرَاهِيمَ وَعَلَىٰ آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ. اللّٰهُمَّ بَارِكْ عَلَىٰ مُحَمَّدٍ وَعَلَىٰ آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَىٰ إِبْرَاهِيمَ وَعَلَىٰ آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ", "pron": {"bn": "আল্লাহুম্মা সাল্লি আলা মুহাম্মাদিও ওয়া আলা আলি মুহাম্মাদ, কামা সাল্লাইতা আলা ইবরাহীমা ওয়া আলা আলি ইবরাহীম, ইন্নাকা হামীদুম মাজীদ। আল্লাহুম্মা বারিক আলা মুহাম্মাদিও ওয়া আলা আলি মুহাম্মাদ, কামা বারাকতা আলা ইবরাহীমা ওয়া আলা আলি ইবরাহীম, ইন্নাকা হামীদুম মাজীদ।", "en": "Allahumma salli ''ala Muhammadin wa ''ala ali Muhammad, kama sallayta ''ala Ibrahima wa ''ala ali Ibrahim, innaka Hamidum Majid. Allahumma barik ''ala Muhammadin wa ''ala ali Muhammad, kama barakta ''ala Ibrahima wa ''ala ali Ibrahim, innaka Hamidum Majid."}, "meaning": {"bn": "হে আল্লাহ, মুহাম্মাদ ও মুহাম্মাদের পরিবারের ওপর রহমত বর্ষণ করো, যেমন ইবরাহিম ও ইবরাহিমের পরিবারের ওপর করেছ; নিশ্চয়ই তুমি প্রশংসিত, মহিমান্বিত। হে আল্লাহ, মুহাম্মাদ ও মুহাম্মাদের পরিবারের ওপর বরকত দাও, যেমন ইবরাহিম ও ইবরাহিমের পরিবারের ওপর দিয়েছ; নিশ্চয়ই তুমি প্রশংসিত, মহিমান্বিত।", "en": "O Allah, send blessings on Muhammad and the family of Muhammad as You sent blessings on Ibrahim and the family of Ibrahim; You are Praiseworthy, Glorious. O Allah, bless Muhammad and the family of Muhammad as You blessed Ibrahim and the family of Ibrahim; You are Praiseworthy, Glorious."}, "ref": {"bn": "সহিহ বুখারি ৩৩৭০", "en": "Sahih al-Bukhari 3370"}}, {"type": "heading", "text": {"bn": "তৃতীয় তাকবির ও মৃতের জন্য দোয়া", "en": "Third takbir and du''a for the deceased"}}, {"type": "step", "title": {"bn": "তৃতীয় তাকবির", "en": "Third takbir"}, "text": {"bn": "‘আল্লাহু আকবার’ বলে মৃতের জন্য দোয়া পড়ুন। প্রাপ্তবয়স্কের জন্য প্রথম দোয়াটি (নারী-পুরুষ সবার জন্য) পড়া যায়; সাথে বা এর বদলে পুরুষ/নারীর আলাদা দোয়াটিও পড়া যায়। নাবালেগ শিশুর জন্য শিশুর দোয়া।", "en": "Say ''Allahu Akbar'' and make du''a for the deceased. For an adult, the first du''a (for men and women) may be said, and/or the separate male/female du''a. For a child, the child''s du''a."}}, {"type": "arabic", "label": {"bn": "প্রাপ্তবয়স্কের জন্য দোয়া (নারী-পুরুষ উভয়ের জন্য)", "en": "Du''a for an adult (male or female)"}, "ar": "اللّٰهُمَّ اغْفِرْ لِحَيِّنَا وَمَيِّتِنَا، وَشَاهِدِنَا وَغَائِبِنَا، وَصَغِيرِنَا وَكَبِيرِنَا، وَذَكَرِنَا وَأُنْثَانَا. اللّٰهُمَّ مَنْ أَحْيَيْتَهُ مِنَّا فَأَحْيِهِ عَلَى الْإِسْلَامِ، وَمَنْ تَوَفَّيْتَهُ مِنَّا فَتَوَفَّهُ عَلَى الْإِيمَانِ", "pron": {"bn": "আল্লাহুম্মাগফির লিহাইয়িনা ওয়া মাইয়িতিনা, ওয়া শাহিদিনা ওয়া গাইবিনা, ওয়া সাগীরিনা ওয়া কাবীরিনা, ওয়া যাকারিনা ওয়া উনসানা। আল্লাহুম্মা মান আহইয়াইতাহূ মিন্না ফাআহয়িহী আলাল ইসলাম, ওয়া মান তাওয়াফফাইতাহূ মিন্না ফাতাওয়াফফাহূ আলাল ঈমান।", "en": "Allahummaghfir lihayyina wa mayyitina, wa shahidina wa gha''ibina, wa saghirina wa kabirina, wa dhakarina wa unthana. Allahumma man ahyaytahu minna fa-ahyihi ''alal-Islam, wa man tawaffaytahu minna fatawaffahu ''alal-iman."}, "meaning": {"bn": "হে আল্লাহ, আমাদের জীবিত ও মৃত, উপস্থিত ও অনুপস্থিত, ছোট ও বড়, পুরুষ ও নারী সবাইকে ক্ষমা করো। হে আল্লাহ, আমাদের মধ্যে যাকে তুমি জীবিত রাখো, তাকে ইসলামের ওপর জীবিত রাখো; আর যাকে মৃত্যু দাও, তাকে ঈমানের সাথে মৃত্যু দাও।", "en": "O Allah, forgive our living and our dead, those present and absent, our young and old, our males and females. O Allah, whoever of us You keep alive, keep him alive upon Islam, and whoever of us You take, take him upon faith."}, "ref": {"bn": "জামে তিরমিজি ১০২৪; সুনান আবু দাউদ ৩২০১; সুনান ইবনে মাজাহ ১৪৯৮", "en": "Jami'' al-Tirmidhi 1024; Sunan Abi Dawud 3201; Sunan Ibn Majah 1498"}}, {"type": "note", "tone": "info", "text": {"bn": "আবু দাউদের বর্ণনায় ‘ইসলাম’ ও ‘ঈমান’ শব্দ দুটির স্থান উল্টো, এবং শেষে আছে: ‘আল্লাহুম্মা লা তাহরিমনা আজরাহূ ওয়া লা তুদিল্লানা বা''দাহূ’ (হে আল্লাহ, আমাদের তার প্রতিদান থেকে বঞ্চিত কোরো না এবং তার পরে আমাদের পথভ্রষ্ট কোরো না)। এটি যোগ করে পড়া যায়।", "en": "Abu Dawud''s narration swaps ''Islam'' and ''iman'' and adds: ''Allahumma la tahrimna ajrahu wa la tudillana ba''dah'' (O Allah, do not deprive us of his reward or lead us astray after him). It may be added."}}, {"type": "arabic", "label": {"bn": "পুরুষের জন্য দোয়া", "en": "Du''a for a man"}, "ar": "اللّٰهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ، وَعَافِهِ وَاعْفُ عَنْهُ، وَأَكْرِمْ نُزُلَهُ، وَوَسِّعْ مُدْخَلَهُ، وَاغْسِلْهُ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ، وَنَقِّهِ مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنَ الدَّنَسِ، وَأَبْدِلْهُ دَارًا خَيْرًا مِنْ دَارِهِ، وَأَهْلًا خَيْرًا مِنْ أَهْلِهِ، وَزَوْجًا خَيْرًا مِنْ زَوْجِهِ، وَأَدْخِلْهُ الْجَنَّةَ، وَأَعِذْهُ مِنْ عَذَابِ الْقَبْرِ وَعَذَابِ النَّارِ", "pron": {"bn": "আল্লাহুম্মাগফির লাহূ ওয়ারহামহু, ওয়া আফিহী ওয়া''ফু আনহু, ওয়া আকরিম নুযুলাহূ, ওয়া ওয়াসসি'' মুদখালাহূ, ওয়াগসিলহু বিলমায়ি ওয়াসসালজি ওয়াল বারাদ, ওয়া নাক্কিহী মিনাল খাতায়া কামা নাক্কাইতাস সাওবাল আবইয়াদা মিনাদ দানাস, ওয়া আবদিলহু দারান খাইরাম মিন দারিহী, ওয়া আহলান খাইরাম মিন আহলিহী, ওয়া যাওজান খাইরাম মিন যাওজিহী, ওয়া আদখিলহুল জান্নাতা, ওয়া আইযহু মিন আযাবিল কাবরি ওয়া আযাবিন নার।", "en": "Allahummaghfir lahu warhamhu, wa ''afihi wa''fu ''anhu, wa akrim nuzulahu, wa wassi'' mudkhalahu, waghsilhu bil-ma''i wath-thalji wal-barad, wa naqqihi minal-khataya kama naqqaytath-thawbal-abyada minad-danas, wa abdilhu daran khayran min darihi, wa ahlan khayran min ahlihi, wa zawjan khayran min zawjihi, wa adkhilhul-jannata, wa a''idhhu min ''adhabil-qabri wa ''adhabin-nar."}, "meaning": {"bn": "হে আল্লাহ, তাকে ক্ষমা করো, তার প্রতি দয়া করো, তাকে নিরাপদ রাখো ও মাফ করে দাও; তার আতিথেয়তা সম্মানজনক করো, তার প্রবেশস্থল (কবর) প্রশস্ত করো; তাকে পানি, বরফ ও শিলা দিয়ে ধুয়ে দাও; তাকে গুনাহ থেকে এমনভাবে পরিষ্কার করো, যেমন সাদা কাপড় ময়লা থেকে পরিষ্কার করা হয়; তাকে তার ঘরের চেয়ে উত্তম ঘর, পরিবারের চেয়ে উত্তম পরিবার ও সঙ্গীর চেয়ে উত্তম সঙ্গী দাও; তাকে জান্নাতে প্রবেশ করাও এবং কবরের আজাব ও জাহান্নামের আজাব থেকে রক্ষা করো।", "en": "O Allah, forgive him and have mercy on him, keep him safe and pardon him, honour his reception and widen his entry, wash him with water, snow and hail, cleanse him of sins as a white garment is cleansed of dirt, give him a home better than his home, a family better than his family and a spouse better than his spouse, admit him to Paradise and protect him from the punishment of the grave and of the Fire."}, "ref": {"bn": "সহিহ মুসলিম ৯৬৩ (আওফ ইবনে মালিক রা.)", "en": "Sahih Muslim 963 (''Awf ibn Malik)"}}, {"type": "arabic", "label": {"bn": "নারীর জন্য দোয়া", "en": "Du''a for a woman"}, "ar": "اللّٰهُمَّ اغْفِرْ لَهَا وَارْحَمْهَا، وَعَافِهَا وَاعْفُ عَنْهَا، وَأَكْرِمْ نُزُلَهَا، وَوَسِّعْ مُدْخَلَهَا، وَاغْسِلْهَا بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ، وَنَقِّهَا مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنَ الدَّنَسِ، وَأَبْدِلْهَا دَارًا خَيْرًا مِنْ دَارِهَا، وَأَهْلًا خَيْرًا مِنْ أَهْلِهَا، وَزَوْجًا خَيْرًا مِنْ زَوْجِهَا، وَأَدْخِلْهَا الْجَنَّةَ، وَأَعِذْهَا مِنْ عَذَابِ الْقَبْرِ وَعَذَابِ النَّارِ", "pron": {"bn": "আল্লাহুম্মাগফির লাহা ওয়ারহামহা, ওয়া আফিহা ওয়া''ফু আনহা, ওয়া আকরিম নুযুলাহা, ওয়া ওয়াসসি'' মুদখালাহা, ওয়াগসিলহা বিলমায়ি ওয়াসসালজি ওয়াল বারাদ, ওয়া নাক্কিহা মিনাল খাতায়া কামা নাক্কাইতাস সাওবাল আবইয়াদা মিনাদ দানাস, ওয়া আবদিলহা দারান খাইরাম মিন দারিহা, ওয়া আহলান খাইরাম মিন আহলিহা, ওয়া যাওজান খাইরাম মিন যাওজিহা, ওয়া আদখিলহাল জান্নাতা, ওয়া আইযহা মিন আযাবিল কাবরি ওয়া আযাবিন নার।", "en": "Allahummaghfir laha warhamha, wa ''afiha wa''fu ''anha, wa akrim nuzulaha, wa wassi'' mudkhalaha, waghsilha bil-ma''i wath-thalji wal-barad, wa naqqiha minal-khataya kama naqqaytath-thawbal-abyada minad-danas, wa abdilha daran khayran min dariha, wa ahlan khayran min ahliha, wa zawjan khayran min zawjiha, wa adkhilhal-jannata, wa a''idhha min ''adhabil-qabri wa ''adhabin-nar."}, "meaning": {"bn": "একই দোয়া নারীর জন্য (সর্বনাম স্ত্রীলিঙ্গে): হে আল্লাহ, তাকে ক্ষমা করো, তার প্রতি দয়া করো ... তাকে জান্নাতে প্রবেশ করাও এবং কবর ও জাহান্নামের আজাব থেকে রক্ষা করো।", "en": "The same du''a for a woman (feminine pronouns): O Allah, forgive her and have mercy on her ... admit her to Paradise and protect her from the punishment of the grave and of the Fire."}, "ref": {"bn": "সহিহ মুসলিম ৯৬৩-এর দোয়া, স্ত্রীলিঙ্গে", "en": "The du''a of Sahih Muslim 963 in the feminine"}}, {"type": "note", "tone": "info", "text": {"bn": "মুসলিমের বর্ণনায় শেষ অংশে বর্ণনাকারী বলেছেন ‘কবরের আজাব থেকে অথবা জাহান্নামের আজাব থেকে’; তাই এখানে দুটোই রাখা হয়েছে। নারীর ক্ষেত্রে ‘ওয়া যাওজান খাইরাম মিন যাওজিহা’ অংশ বলা নিয়ে আলেমদের ভিন্নমত আছে; কেউ কেউ এ অংশ বাদ দিয়ে পড়েন।", "en": "In Muslim''s narration the narrator says ''from the punishment of the grave or of the Fire'', so both are kept here. For a woman, scholars differ on saying ''a spouse better than her spouse''; some omit it."}}, {"type": "arabic", "label": {"bn": "নাবালেগ ছেলে শিশুর জন্য", "en": "For a boy (not yet adult)"}, "ar": "اللّٰهُمَّ اجْعَلْهُ لَنَا فَرَطًا، وَاجْعَلْهُ لَنَا أَجْرًا وَذُخْرًا، وَاجْعَلْهُ لَنَا شَافِعًا وَمُشَفَّعًا", "pron": {"bn": "আল্লাহুম্মাজ আলহু লানা ফারাতাও, ওয়াজ আলহু লানা আজরাও ওয়া যুখরাও, ওয়াজ আলহু লানা শাফিআও ওয়া মুশাফফাআ।", "en": "Allahummaj''alhu lana faratan, waj''alhu lana ajran wa dhukhran, waj''alhu lana shafi''an wa mushaffa''a."}, "meaning": {"bn": "হে আল্লাহ, তাকে আমাদের জন্য অগ্রগামী (আমাদের আগে পৌঁছে অপেক্ষাকারী) বানাও, তাকে আমাদের জন্য প্রতিদান ও সঞ্চয় বানাও, এবং তাকে আমাদের জন্য সুপারিশকারী ও এমন বানাও যার সুপারিশ কবুল হয়।", "en": "O Allah, make him a forerunner for us, a reward and a treasure for us, and an intercessor for us whose intercession is accepted."}, "ref": {"bn": "হানাফি ফিকহের কিতাবে বর্ণিত; সহিহ বুখারির জানাযা অধ্যায়ে হাসান বসরি (রহ.)-এর উক্তিতে ‘আল্লাহুম্মাজ আলহু লানা ফারাতান ওয়া সালাফান ওয়া আজরান’ আছে", "en": "Given in Hanafi fiqh books; Sahih al-Bukhari''s funerals chapter cites al-Hasan al-Basri saying ''Allahummaj''alhu lana faratan wa salafan wa ajra''"}, "check": true}, {"type": "arabic", "label": {"bn": "নাবালেগ মেয়ে শিশুর জন্য", "en": "For a girl (not yet adult)"}, "ar": "اللّٰهُمَّ اجْعَلْهَا لَنَا فَرَطًا، وَاجْعَلْهَا لَنَا أَجْرًا وَذُخْرًا، وَاجْعَلْهَا لَنَا شَافِعَةً وَمُشَفَّعَةً", "pron": {"bn": "আল্লাহুম্মাজ আলহা লানা ফারাতাও, ওয়াজ আলহা লানা আজরাও ওয়া যুখরাও, ওয়াজ আলহা লানা শাফিআতাও ওয়া মুশাফফাআহ।", "en": "Allahummaj''alha lana faratan, waj''alha lana ajran wa dhukhran, waj''alha lana shafi''atan wa mushaffa''ah."}, "meaning": {"bn": "হে আল্লাহ, তাকে (মেয়েটিকে) আমাদের জন্য অগ্রগামী বানাও, আমাদের জন্য প্রতিদান ও সঞ্চয় বানাও, এবং আমাদের জন্য সুপারিশকারিণী ও এমন বানাও যার সুপারিশ কবুল হয়।", "en": "O Allah, make her a forerunner for us, a reward and a treasure for us, and an intercessor for us whose intercession is accepted."}, "ref": {"bn": "হানাফি ফিকহের কিতাবে বর্ণিত (ছেলে শিশুর দোয়ার স্ত্রীলিঙ্গ রূপ)", "en": "Given in Hanafi fiqh books (feminine of the boy''s du''a)"}, "check": true}, {"type": "note", "tone": "tip", "text": {"bn": "কোনো দোয়া মুখস্থ না থাকলে যতটুকু জানেন বা নিজের ভাষায় মৃতের জন্য ক্ষমা ও রহমতের দোয়া করুন; জানাযার মূল উদ্দেশ্য মৃতের জন্য আন্তরিক দোয়া।", "en": "If you do not know these by heart, make du''a for forgiveness and mercy for the deceased with what you know or in your own words; sincere du''a is the heart of this prayer."}}, {"type": "heading", "text": {"bn": "চতুর্থ তাকবির ও সালাম", "en": "Fourth takbir and salam"}}, {"type": "step", "title": {"bn": "চতুর্থ তাকবির", "en": "Fourth takbir"}, "text": {"bn": "‘আল্লাহু আকবার’ বলুন। এরপর কোনো নির্দিষ্ট দোয়া জরুরি নয় (হানাফি মতে সরাসরি সালাম)।", "en": "Say ''Allahu Akbar''. No particular du''a is required after it (Hanafis proceed to salam)."}}, {"type": "step", "title": {"bn": "সালাম", "en": "Salam"}, "text": {"bn": "প্রথমে ডান দিকে, তারপর বাম দিকে সালাম ফেরান (হানাফি)। কিছু আলেমের মতে ডান দিকে এক সালামই যথেষ্ট।", "en": "Turn the salam to the right, then to the left (Hanafi). Some scholars hold a single salam to the right suffices."}}, {"type": "arabic", "label": {"bn": "সালাম", "en": "Salam"}, "ar": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللّٰهِ", "pron": {"bn": "আসসালামু আলাইকুম ওয়া রাহমাতুল্লাহ।", "en": "As-salamu ''alaykum wa rahmatullah."}, "meaning": {"bn": "তোমাদের ওপর শান্তি ও আল্লাহর রহমত বর্ষিত হোক।", "en": "Peace and the mercy of Allah be upon you."}}, {"type": "differ", "title": {"bn": "প্রতি তাকবিরে হাত তোলা", "en": "Raising the hands at each takbir"}, "views": [{"label": {"bn": "হানাফি ও মালেকি (প্রসিদ্ধ মত)", "en": "Hanafi and Maliki (well-known view)"}, "text": {"bn": "শুধু প্রথম তাকবিরে হাত তোলা; বাকি তিনটিতে নয়।", "en": "Raise the hands only at the first takbir."}, "evidence": {"bn": "দারাকুতনিতে ইবনে আব্বাস (রা.) থেকে এ মর্মে বর্ণনা আছে (সনদ নিয়ে আলোচনা আছে)।", "en": "A report from Ibn ''Abbas in al-Daraqutni (its chain is discussed)."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি", "en": "Shafi''i and Hanbali"}, "text": {"bn": "প্রতিটি তাকবিরে হাত তোলা।", "en": "Raise the hands at every takbir."}, "evidence": {"bn": "ইবনে উমর (রা.) জানাযার প্রতিটি তাকবিরে হাত তুলতেন (সহিহ বুখারিতে অধ্যায়ের শিরোনামে উল্লেখিত)।", "en": "Ibn ''Umar raised his hands at every funeral takbir (cited in a chapter heading of Sahih al-Bukhari)."}}], "check": true}, {"type": "heading", "text": {"bn": "দেরিতে এলে (মাসবুক)", "en": "If you join late"}}, {"type": "text", "text": {"bn": "ইমাম কয়েক তাকবির দিয়ে ফেললে, হানাফি মতে পরবর্তী তাকবিরের জন্য অপেক্ষা করুন এবং ইমামের সাথে তাকবির বলে যোগ দিন। ইমাম সালাম ফেরালে লাশ তুলে নেওয়ার আগেই ছুটে যাওয়া তাকবিরগুলো দোয়া ছাড়া দ্রুত বলে সালাম ফেরান।", "en": "If the imam has already made some takbirs, Hanafis wait for his next takbir and join with it. After the imam''s salam, say the missed takbirs quickly (without the du''as) before the body is lifted, then give salam."}}, {"type": "differ", "title": {"bn": "গায়েবানা জানাযা (লাশ অনুপস্থিত থাকলে)", "en": "Funeral prayer in absentia"}, "views": [{"label": {"bn": "হানাফি ও মালেকি", "en": "Hanafi and Maliki"}, "text": {"bn": "গায়েবানা জানাযা জায়েজ নয়; নাজাশির ঘটনা বিশেষ ক্ষেত্র ছিল।", "en": "Not prescribed; the Negus''s case was special."}, "evidence": {"bn": "নবীজি (সা.)-এর যুগে অনেক সাহাবি দূরে ইন্তেকাল করেছেন, কিন্তু সবার গায়েবানা জানাযা পড়ার বর্ণনা নেই।", "en": "Many Companions died far away in the Prophet''s time, with no report of absentee prayers for them all."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি", "en": "Shafi''i and Hanbali"}, "text": {"bn": "জায়েজ।", "en": "Permissible."}, "evidence": {"bn": "নবীজি (সা.) মদিনায় থেকে নাজাশির গায়েবানা জানাযা পড়েছেন (সহিহ বুখারি ১২৪৫)।", "en": "The Prophet prayed in Madinah over the Negus who died in Abyssinia (Sahih al-Bukhari 1245)."}}, {"label": {"bn": "কিছু আলেম (যেমন ইবনে তাইমিয়া)", "en": "Some scholars (e.g. Ibn Taymiyyah)"}, "text": {"bn": "যার জানাযা কোথাও পড়া হয়নি, শুধু তার জন্য গায়েবানা জানাযা।", "en": "Only for someone over whom no funeral prayer was offered."}, "evidence": {"bn": "নাজাশির দেশে তাঁর জানাযা পড়ার মতো কেউ ছিল না বলে ধারণা করা হয়।", "en": "It is understood that no one in his land prayed over the Negus."}}]}]', 'in_review', 50 FROM is_guide_topics WHERE slug = 'janazah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '123642e3-dcfe-5d13-bfea-c89db101e991', id, 'janazah-carrying-burial', '{"bn": "লাশ বহন ও দাফন", "en": "Carrying and Burial"}', '{"bn": "খাটিয়া বহনের আদব, কবরের ধরন, কবরে রাখার দোয়া, মাটি দেওয়া ও দাফনের পর দোয়া।", "en": "Etiquette of carrying the bier, the grave, the du''a when placing the body, soil, and du''a after burial."}', 'basic', '[{"type": "heading", "text": {"bn": "খাটিয়া বহন", "en": "Carrying the bier"}}, {"type": "list", "items": [{"bn": "দ্রুত পায়ে (দৌড়ে নয়) লাশ নিয়ে যাওয়া সুন্নত (সহিহ বুখারি ১৩১৫)।", "en": "Carry it at a brisk pace, not running (Sahih al-Bukhari 1315)."}, {"bn": "চারজনে খাটিয়ার চার পায়া ধরা এবং পালাক্রমে কাঁধ দেওয়া উত্তম; মাথা সামনের দিকে থাকবে।", "en": "Four people take the four handles and take turns; the head goes in front."}, {"bn": "জানাযার সাথে যারা যাবেন, লাশ মাটিতে রাখার আগে বসবেন না (সহিহ বুখারি ১৩১০)।", "en": "Those following should not sit until the bier is put down (Sahih al-Bukhari 1310)."}, {"bn": "চুপচাপ চলা ও মৃত্যুর কথা ভাবা উত্তম; জোরে জিকির, কালিমা বা স্লোগান দিতে দিতে চলাকে হানাফিসহ অনেক আলেম মাকরুহ বলেছেন।", "en": "Walk quietly reflecting on death; many scholars including Hanafis disliked loud dhikr or chanting while walking."}, {"bn": "নারীদের জন্য জানাযার সাথে কবরস্থানে যাওয়া নিরুৎসাহিত।", "en": "Women are discouraged from following the bier to the graveyard."}]}, {"type": "heading", "text": {"bn": "কবর", "en": "The grave"}}, {"type": "text", "text": {"bn": "কবর যথেষ্ট গভীর হবে, যাতে গন্ধ বের না হয় এবং পশুপাখি ক্ষতি করতে না পারে। লাহদ (কবরের কিবলার দিকের দেয়ালে খোঁড়া খাঁজ) উত্তম; সা''দ (রা.) ওসিয়ত করেছিলেন, তাঁর জন্য লাহদ করা হোক, যেমন নবীজি (সা.)-এর জন্য করা হয়েছিল (সহিহ মুসলিম ৯৬৬)। মাটি নরম হলে (বাংলাদেশের অনেক জায়গায়) মাঝখানে খাদ করা ‘শাক’ কবর করা হয়, যা জায়েজ।", "en": "The grave should be deep enough to contain smell and protect from animals. The lahd (a niche in the qiblah-side wall) is best; Sa''d asked for a lahd as was made for the Prophet (Sahih Muslim 966). In soft soil (as in much of Bangladesh) a shaqq (trench in the middle) is used, which is permissible."}}, {"type": "heading", "text": {"bn": "কবরে রাখা", "en": "Placing in the grave"}}, {"type": "step", "title": {"bn": "কবরে নামানো", "en": "Lower the body"}, "text": {"bn": "সম্ভব হলে কিবলার দিক থেকে লাশ কবরে নামান। মাহরাম ও নিকটজনরা নামাবেন; নারীর লাশ নামানোর সময় চাদর দিয়ে আড়াল করা উত্তম।", "en": "Lower the body, from the qiblah side if possible. Close relatives do this; for a woman, screen the grave with a sheet."}}, {"type": "step", "title": {"bn": "দোয়া পড়া", "en": "Say the du''a"}, "text": {"bn": "কবরে রাখার সময় নিচের দোয়া পড়ুন।", "en": "Say the du''a below while placing the body."}}, {"type": "arabic", "label": {"bn": "কবরে রাখার দোয়া", "en": "Du''a when placing in the grave"}, "ar": "بِسْمِ اللّٰهِ وَعَلَىٰ سُنَّةِ رَسُولِ اللّٰهِ", "pron": {"bn": "বিসমিল্লাহি ওয়া আলা সুন্নাতি রাসূলিল্লাহ।", "en": "Bismillahi wa ''ala sunnati Rasulillah."}, "meaning": {"bn": "আল্লাহর নামে এবং আল্লাহর রাসুলের সুন্নাতের ওপর (তোমাকে রাখছি)।", "en": "In the name of Allah and upon the sunnah of the Messenger of Allah."}, "ref": {"bn": "সুনান আবু দাউদ ৩২১৩", "en": "Sunan Abi Dawud 3213"}}, {"type": "arabic", "label": {"bn": "আরেকটি বর্ণনা", "en": "Another narration"}, "ar": "بِسْمِ اللّٰهِ وَبِاللّٰهِ وَعَلَىٰ مِلَّةِ رَسُولِ اللّٰهِ", "pron": {"bn": "বিসমিল্লাহি ওয়া বিল্লাহি ওয়া আলা মিল্লাতি রাসূলিল্লাহ।", "en": "Bismillahi wa billahi wa ''ala millati Rasulillah."}, "meaning": {"bn": "আল্লাহর নামে, আল্লাহর সাহায্যে এবং আল্লাহর রাসুলের মিল্লাতের (দ্বীনের) ওপর।", "en": "In the name of Allah, by Allah, and upon the religion of the Messenger of Allah."}, "ref": {"bn": "জামে তিরমিজি ১০৪৬", "en": "Jami'' al-Tirmidhi 1046"}}, {"type": "step", "title": {"bn": "কিবলামুখী করে শোয়ানো", "en": "Lay facing the qiblah"}, "text": {"bn": "লাশকে ডান কাতে কিবলামুখী করে শুইয়ে দিন; পিঠের দিকে মাটি বা ইট দিয়ে ঠেস দিন। কাফনের বাঁধনগুলো খুলে দিন।", "en": "Lay the body on its right side facing the qiblah, supported at the back with earth or bricks. Untie the knots of the shroud."}}, {"type": "step", "title": {"bn": "বাঁশ বা তক্তা দিয়ে ঢাকা", "en": "Cover with planks"}, "text": {"bn": "লাহদ বা শাকের মুখ কাঁচা ইট, বাঁশ বা তক্তা দিয়ে বন্ধ করে দিন, যাতে মাটি সরাসরি লাশের ওপর না পড়ে।", "en": "Close the lahd or shaqq with mud bricks, bamboo or planks so soil does not fall directly on the body."}}, {"type": "step", "title": {"bn": "তিন মুঠ মাটি", "en": "Three handfuls of soil"}, "text": {"bn": "উপস্থিতরা মাথার দিক থেকে দুই হাতে তিন মুঠ করে মাটি দেবেন। নবীজি (সা.) এক জানাযার পর কবরের মাথার দিক থেকে তিন মুঠ মাটি দিয়েছিলেন (সুনান ইবনে মাজাহ ১৫৬৫)।", "en": "Those present throw three handfuls of soil from the head side. The Prophet threw three handfuls at the head of a grave (Sunan Ibn Majah 1565)."}}, {"type": "arabic", "label": {"bn": "কুরআনের আয়াত", "en": "Quranic verse"}, "ar": "مِنْهَا خَلَقْنَاكُمْ وَفِيهَا نُعِيدُكُمْ وَمِنْهَا نُخْرِجُكُمْ تَارَةً أُخْرَىٰ", "pron": {"bn": "মিনহা খালাকনাকুম, ওয়া ফীহা নুঈদুকুম, ওয়া মিনহা নুখরিজুকুম তারাতান উখরা।", "en": "Minha khalaqnakum, wa fiha nu''idukum, wa minha nukhrijukum taratan ukhra."}, "meaning": {"bn": "এ (মাটি) থেকেই আমি তোমাদের সৃষ্টি করেছি, এতেই তোমাদের ফিরিয়ে দেব এবং এ থেকেই তোমাদের আবার বের করব।", "en": "From it (the earth) We created you, into it We return you, and from it We will bring you out once again."}, "ref": {"bn": "সূরা ত্বহা ২০:৫৫", "en": "Ta-Ha 20:55"}}, {"type": "note", "tone": "info", "text": {"bn": "তিন মুঠ মাটি দেওয়ার সময় এই আয়াতের তিন অংশ পড়ার প্রচলন আছে; এ বিষয়ে মুসনাদে আহমাদে একটি বর্ণনা আছে, যার সনদ দুর্বল বলে মুহাদ্দিসরা উল্লেখ করেছেন। আয়াতটি পড়া যায়, তবে জরুরি মনে করবেন না।", "en": "Reciting the three parts of this verse with the three handfuls is common; a narration in Musnad Ahmad mentions it but its chain is graded weak. You may recite it, but do not treat it as required."}, "check": true}, {"type": "step", "title": {"bn": "কবর উঁচু করা", "en": "Raise the mound"}, "text": {"bn": "কবর মাটি দিয়ে ভরে প্রায় এক বিঘত উঁচু ও উটের কুঁজের মতো করে দিন; পানি ছিটিয়ে দেওয়া যায়।", "en": "Fill the grave and raise it about a hand-span in a hump shape; it may be sprinkled with water."}}, {"type": "heading", "text": {"bn": "দাফনের পর", "en": "After burial"}}, {"type": "text", "text": {"bn": "দাফন শেষ হলে নবীজি (সা.) কবরের পাশে দাঁড়িয়ে বলতেন: ‘তোমাদের ভাইয়ের জন্য ক্ষমা চাও এবং তার জন্য দৃঢ়তা চাও, কারণ এখন তাকে প্রশ্ন করা হচ্ছে’ (সুনান আবু দাউদ ৩২২১)।", "en": "After burial the Prophet would stand at the grave and say: ''Seek forgiveness for your brother and ask for him firmness, for he is now being questioned'' (Sunan Abi Dawud 3221)."}}, {"type": "arabic", "label": {"bn": "দাফনের পর দোয়ার উদাহরণ (নারীর জন্য: লাহা / সাব্বিতহা)", "en": "Example du''a after burial (for a woman: laha / thabbitha)"}, "ar": "اللّٰهُمَّ اغْفِرْ لَهُ، اللّٰهُمَّ ثَبِّتْهُ", "pron": {"bn": "আল্লাহুম্মাগফির লাহূ, আল্লাহুম্মা সাব্বিতহু।", "en": "Allahummaghfir lahu, Allahumma thabbithu."}, "meaning": {"bn": "হে আল্লাহ, তাকে ক্ষমা করো; হে আল্লাহ, তাকে (প্রশ্নের উত্তরে) দৃঢ় রাখো।", "en": "O Allah, forgive him; O Allah, make him firm."}, "ref": {"bn": "সুনান আবু দাউদ ৩২২১-এর নির্দেশনা অনুযায়ী", "en": "Following the instruction in Sunan Abi Dawud 3221"}}, {"type": "list", "items": [{"bn": "প্রত্যেকে নিজে নিজে দোয়া করবেন; কিছুক্ষণ কবরের কাছে থেকে দোয়া করা ভালো।", "en": "Each person makes du''a individually; staying a little while at the grave is good."}, {"bn": "কবর পাকা করা, তার ওপর ঘর বা স্থাপনা বানানো ও কবরের ওপর বসা নিষেধ (সহিহ মুসলিম ৯৭০)।", "en": "Plastering graves, building over them and sitting on them is forbidden (Sahih Muslim 970)."}, {"bn": "চেনার জন্য মাথার দিকে একটি পাথর বা চিহ্ন রাখা যায়।", "en": "A stone or marker may be placed at the head for recognition."}]}, {"type": "note", "tone": "info", "text": {"bn": "দাফনের পর মৃতকে সম্বোধন করে তালকিন করা (যেমন ‘হে অমুক, বলো তোমার রব আল্লাহ...’) নিয়ে আলেমদের মতভেদ আছে: কিছু শাফেয়ি ও হাম্বলি আলেম একে মুস্তাহাব বলেছেন; অন্যরা বলেছেন এর হাদিস দুর্বল, তাই করা হবে না। এর বদলে ক্ষমা ও দৃঢ়তার দোয়া সহিহ হাদিসে প্রমাণিত।", "en": "Addressing the deceased with talqin after burial (''O so-and-so, say your Lord is Allah...'') is disputed: some Shafi''i and Hanbali scholars recommended it; others say its hadith is weak and it should not be done. Du''a for forgiveness and firmness is established in sahih hadith."}}]', 'in_review', 60 FROM is_guide_topics WHERE slug = 'janazah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'c07be002-1b3c-525a-82c0-af6c95c656e7', id, 'janazah-visiting-graves', '{"bn": "কবর জিয়ারত", "en": "Visiting Graves"}', '{"bn": "কবর জিয়ারতের উদ্দেশ্য, সুন্নত দোয়া, নারীদের জিয়ারত নিয়ে মত, মৃতের কাছে কী পৌঁছে এবং যা থেকে বিরত থাকতে হবে।", "en": "The purpose of visiting graves, the sunnah greeting, views on women visiting, what benefits the dead, and what to avoid."}', 'basic', '[{"type": "text", "text": {"bn": "নবীজি (সা.) বলেছেন: ‘আমি তোমাদের কবর জিয়ারত করতে নিষেধ করেছিলাম; এখন জিয়ারত করো’ (সহিহ মুসলিম ৯৭৭), ‘কারণ তা আখেরাতের কথা মনে করিয়ে দেয়’ (জামে তিরমিজি ১০৫৪)। জিয়ারতের উদ্দেশ্য দুটি: নিজের মৃত্যু ও আখেরাত স্মরণ করা, এবং মৃতদের জন্য দোয়া করা।", "en": "The Prophet said: ''I had forbidden you from visiting graves; now visit them'' (Sahih Muslim 977), ''for it reminds of the Hereafter'' (Jami'' al-Tirmidhi 1054). The purposes are to remember death and the Hereafter, and to pray for the dead."}}, {"type": "arabic", "label": {"bn": "কবর জিয়ারতের দোয়া", "en": "Du''a when visiting graves"}, "ar": "السَّلَامُ عَلَيْكُمْ أَهْلَ الدِّيَارِ مِنَ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ، وَإِنَّا إِنْ شَاءَ اللّٰهُ لَلَاحِقُونَ، أَسْأَلُ اللّٰهَ لَنَا وَلَكُمُ الْعَافِيَةَ", "pron": {"bn": "আসসালামু আলাইকুম আহলাদ দিয়ারি মিনাল মু''মিনীনা ওয়াল মুসলিমীন, ওয়া ইন্না ইনশাআল্লাহু লালাহিকূন, আসআলুল্লাহা লানা ওয়া লাকুমুল আফিয়াহ।", "en": "As-salamu ''alaykum ahlad-diyari minal-mu''minina wal-muslimin, wa inna in sha'' Allahu lalahiqun, as''alullaha lana wa lakumul-''afiyah."}, "meaning": {"bn": "হে এই ঘরগুলোর মুমিন ও মুসলিম বাসিন্দারা, তোমাদের ওপর শান্তি বর্ষিত হোক। আল্লাহ চাইলে আমরাও তোমাদের সাথে মিলিত হব। আমি আমাদের ও তোমাদের জন্য আল্লাহর কাছে নিরাপত্তা চাই।", "en": "Peace be upon you, O believing and Muslim dwellers of these abodes. We shall, if Allah wills, join you. I ask Allah for well-being for us and for you."}, "ref": {"bn": "সহিহ মুসলিম ৯৭৫", "en": "Sahih Muslim 975"}}, {"type": "arabic", "label": {"bn": "আরেকটি দোয়া (আয়েশা রা.-এর বর্ণনা)", "en": "Another du''a (narrated by ''A''ishah)"}, "ar": "السَّلَامُ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِينَ، وَأَتَاكُمْ مَا تُوعَدُونَ، غَدًا مُؤَجَّلُونَ، وَإِنَّا إِنْ شَاءَ اللّٰهُ بِكُمْ لَاحِقُونَ", "pron": {"bn": "আসসালামু আলাইকুম দারা কাওমিম মু''মিনীন, ওয়া আতাকুম মা তূআদূন, গাদাম মুআজ্জালূন, ওয়া ইন্না ইনশাআল্লাহু বিকুম লাহিকূন।", "en": "As-salamu ''alaykum dara qawmin mu''minin, wa atakum ma tu''adun, ghadan mu''ajjalun, wa inna in sha'' Allahu bikum lahiqun."}, "meaning": {"bn": "হে মুমিন সম্প্রদায়ের আবাসের বাসিন্দারা, তোমাদের ওপর শান্তি। তোমাদের যে প্রতিশ্রুতি দেওয়া হয়েছিল তা তোমাদের কাছে এসেছে, আগামীর জন্য তোমাদের অবকাশ দেওয়া হয়েছে; আর আল্লাহ চাইলে আমরাও তোমাদের সাথে মিলিত হব।", "en": "Peace be upon you, abode of believing people. What you were promised has come to you, deferred until tomorrow, and we shall, if Allah wills, join you."}, "ref": {"bn": "সহিহ মুসলিম ৯৭৪", "en": "Sahih Muslim 974"}}, {"type": "heading", "text": {"bn": "জিয়ারতের আদব", "en": "Etiquette"}}, {"type": "list", "items": [{"bn": "কবরের দিকে মুখ করে সালাম দিন; দোয়ার সময় কিবলামুখী হওয়া উত্তম।", "en": "Face the grave when greeting; face the qiblah for du''a."}, {"bn": "হাত তুলে দোয়া করা যায়; আয়েশা (রা.) বলেন, নবীজি (সা.) বাকি কবরস্থানে গিয়ে দাঁড়িয়ে তিনবার হাত তুলে দোয়া করেছেন (সহিহ মুসলিম ৯৭৪)।", "en": "You may raise your hands in du''a; the Prophet raised his hands three times at al-Baqi'' (Sahih Muslim 974)."}, {"bn": "কবরের ওপর বসবেন না, কবরের দিকে ফিরে নামাজ পড়বেন না (সহিহ মুসলিম ৯৭২)।", "en": "Do not sit on graves or pray facing them (Sahih Muslim 972)."}, {"bn": "কবরে হাঁটবেন না; কবরের মাঝ দিয়ে সাবধানে চলুন।", "en": "Do not walk on graves; move carefully between them."}]}, {"type": "note", "tone": "warn", "text": {"bn": "কবরে সিজদা করা, কবর তাওয়াফ করা, কবরবাসীর কাছে সন্তান, রোগমুক্তি বা প্রয়োজন চাওয়া, কবরে মানত করা: এগুলো ইবাদত, যা কেবল আল্লাহর জন্য। এসব থেকে কঠোরভাবে বিরত থাকুন। দোয়া চাইবেন আল্লাহর কাছে, মৃতের জন্য।", "en": "Prostrating to graves, circling them, asking the dead for children, cures or needs, or making vows to them are acts of worship due to Allah alone; avoid them strictly. Ask Allah, for the dead."}}, {"type": "differ", "title": {"bn": "নারীদের কবর জিয়ারত", "en": "Women visiting graves"}, "views": [{"label": {"bn": "জায়েজ, শর্তসাপেক্ষে (অনেক হানাফি ও অন্য আলেম)", "en": "Permissible with conditions (many Hanafi and other scholars)"}, "text": {"bn": "পর্দা রক্ষা করে, বিলাপ ও উচ্চস্বরে কান্না ছাড়া মাঝে মাঝে জিয়ারত করা যায়।", "en": "Occasionally, with proper covering and without wailing."}, "evidence": {"bn": "নবীজি (সা.) আয়েশা (রা.)-কে কবর জিয়ারতের দোয়া শিখিয়েছেন (সহিহ মুসলিম ৯৭৪); কবরের পাশে কাঁদতে থাকা এক নারীকে নবীজি (সা.) ধৈর্য ধরতে বলেছেন, জিয়ারত থেকে নিষেধ করেননি (সহিহ বুখারি ১২৫২)।", "en": "The Prophet taught ''A''ishah the du''a for visiting graves (Sahih Muslim 974), and told a woman weeping at a grave to be patient without forbidding the visit (Sahih al-Bukhari 1252)."}}, {"label": {"bn": "মাকরুহ বা নিষেধ (কিছু আলেম)", "en": "Disliked or forbidden (some scholars)"}, "text": {"bn": "নারীদের কবর জিয়ারত মাকরুহ, বিশেষ করে ঘন ঘন যাওয়া।", "en": "Disliked, especially frequent visits."}, "evidence": {"bn": "‘নবীজি (সা.) অধিক কবর জিয়ারতকারী নারীদের অভিশাপ দিয়েছেন’ (জামে তিরমিজি ১০৫৬)।", "en": "''The Messenger of Allah cursed women who frequently visit graves'' (Jami'' al-Tirmidhi 1056)."}}]}, {"type": "heading", "text": {"bn": "মৃতের জন্য কী উপকারে আসে", "en": "What benefits the dead"}}, {"type": "text", "text": {"bn": "মৃত্যুর পর মানুষের আমল বন্ধ হয়ে যায়, তিনটি ছাড়া: চলমান সদকা, উপকারী জ্ঞান এবং নেক সন্তান যে তার জন্য দোয়া করে (সহিহ মুসলিম ১৬৩১)।", "en": "When a person dies his deeds end except three: ongoing charity, beneficial knowledge, and a righteous child who prays for him (Sahih Muslim 1631)."}}, {"type": "list", "items": [{"bn": "দোয়া ও ইস্তিগফার: সর্বসম্মতভাবে পৌঁছে (সূরা হাশর ৫৯:১০)।", "en": "Du''a and istighfar: agreed to reach (Al-Hashr 59:10)."}, {"bn": "সদকা: মৃত মায়ের পক্ষ থেকে সদকা করলে সওয়াব পাবেন কি না জিজ্ঞেস করলে নবীজি (সা.) বললেন, হ্যাঁ (সহিহ বুখারি ১৩৮৮)।", "en": "Charity: asked about giving charity for a deceased mother, the Prophet said yes (Sahih al-Bukhari 1388)."}, {"bn": "মৃতের ঋণ পরিশোধ, তার পক্ষ থেকে বদলি হজ এবং মানতের/কাজা রোজা (সহিহ বুখারি ১৯৫২, ১৯৫৩)।", "en": "Paying the deceased''s debts, Hajj on their behalf, and owed fasts (Sahih al-Bukhari 1952, 1953)."}]}, {"type": "differ", "title": {"bn": "কুরআন তিলাওয়াতের সওয়াব মৃতের কাছে পৌঁছে কি", "en": "Does the reward of Quran recitation reach the dead"}, "views": [{"label": {"bn": "হানাফি ও হাম্বলি", "en": "Hanafi and Hanbali"}, "text": {"bn": "হ্যাঁ, কেউ কুরআন পড়ে বা নফল ইবাদত করে সওয়াব মৃতকে দান করলে তা পৌঁছে।", "en": "Yes, the reward of recitation and voluntary worship gifted to the dead reaches them."}, "evidence": {"bn": "সদকা, হজ ও রোজার সওয়াব পৌঁছানোর সহিহ হাদিসগুলোর ওপর কিয়াস (সহিহ বুখারি ১৩৮৮, ১৯৫২)।", "en": "By analogy with the sahih hadiths on charity, Hajj and fasting (Sahih al-Bukhari 1388, 1952)."}}, {"label": {"bn": "শাফেয়ি (প্রসিদ্ধ পুরনো মত) ও মালেকি", "en": "Shafi''i (well-known classical view) and Maliki"}, "text": {"bn": "তিলাওয়াতের সওয়াব সরাসরি পৌঁছে না; তবে তিলাওয়াতের পর মৃতের জন্য দোয়া করলে দোয়ার মাধ্যমে উপকার পৌঁছে (পরবর্তী অনেক শাফেয়ি আলেম এভাবে বলেছেন)।", "en": "The reward of recitation does not reach directly, but du''a for the dead after reciting benefits them (as many later Shafi''is put it)."}, "evidence": {"bn": "‘মানুষ তা-ই পায়, যার জন্য সে চেষ্টা করে’ (সূরা নাজম ৫৩:৩৯); হাদিসে কেবল নির্দিষ্ট কিছু আমলের কথা এসেছে।", "en": "''Man will have only what he strives for'' (An-Najm 53:39); hadiths name only specific deeds."}}]}]', 'in_review', 70 FROM is_guide_topics WHERE slug = 'janazah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'fa405e7c-d96e-546c-9d0c-12088bb9ebe4', id, 'janazah-condolence', '{"bn": "শোকাহত পরিবারকে সান্ত্বনা (তা''জিয়াহ)", "en": "Condolence (Ta''ziyah)"}', '{"bn": "শোকাহত পরিবারকে সান্ত্বনা দেওয়ার সুন্নত, কী বলবেন, খাবার পাঠানো এবং শোক পালনের সময়সীমা।", "en": "Comforting the bereaved: what to say, sending food, and the period of mourning."}', 'basic', '[{"type": "text", "text": {"bn": "মৃতের পরিবারকে সান্ত্বনা দেওয়া সুন্নত। তাদের ধৈর্য ধরতে উৎসাহ দিন, মৃতের জন্য দোয়া করুন, এবং বাস্তব সাহায্য করুন। সাধারণত দাফনের আগে-পরে তিন দিনের মধ্যে তা''জিয়াহ করা হয়; দূরে থাকলে পরেও করা যায়।", "en": "Comforting the family is sunnah: encourage patience, pray for the deceased, and help practically. It is usually within three days; someone far away may do it later."}}, {"type": "arabic", "label": {"bn": "সান্ত্বনার দোয়া (নবীজি সা. তাঁর কন্যাকে বলে পাঠিয়েছিলেন)", "en": "Words of condolence (the Prophet''s message to his daughter)"}, "ar": "إِنَّ لِلّٰهِ مَا أَخَذَ، وَلَهُ مَا أَعْطَىٰ، وَكُلٌّ عِنْدَهُ بِأَجَلٍ مُسَمًّى، فَلْتَصْبِرْ وَلْتَحْتَسِبْ", "pron": {"bn": "ইন্না লিল্লাহি মা আখাযা, ওয়া লাহূ মা আ''তা, ওয়া কুল্লুন ইনদাহূ বিআজালিম মুসাম্মা, ফালতাসবির ওয়ালতাহতাসিব।", "en": "Inna lillahi ma akhadha, wa lahu ma a''ta, wa kullun ''indahu bi-ajalin musamma, faltasbir waltahtasib."}, "meaning": {"bn": "আল্লাহ যা নিয়েছেন তা তাঁরই, আর যা দিয়েছেন তাও তাঁরই; তাঁর কাছে প্রত্যেক কিছুর নির্দিষ্ট মেয়াদ আছে। অতএব (তুমি) ধৈর্য ধরো এবং সওয়াবের আশা রাখো।", "en": "To Allah belongs what He took and what He gave, and everything with Him has an appointed term; so be patient and hope for reward."}, "ref": {"bn": "সহিহ বুখারি ১২৮৪", "en": "Sahih al-Bukhari 1284"}}, {"type": "note", "tone": "info", "text": {"bn": "হাদিসে শেষ অংশ ‘ফালতাসবির ওয়ালতাহতাসিব’ স্ত্রীলিঙ্গে, কারণ তা কন্যাকে বলা হয়েছিল। পুরুষকে বলতে পারেন ‘ফাসবির ওয়াহতাসিব’ (فَاصْبِرْ وَاحْتَسِبْ)। নিজের ভাষায় সান্ত্বনা দেওয়াও সুন্নত আদায় করে।", "en": "The last phrase is feminine, as it was said to his daughter. To a man say ''fasbir wahtasib'' (فَاصْبِرْ وَاحْتَسِبْ). Comforting in your own words also fulfils the sunnah."}}, {"type": "heading", "text": {"bn": "যা করবেন", "en": "What to do"}}, {"type": "list", "items": [{"bn": "মৃতের পরিবারের জন্য খাবার পাঠানো: জা''ফর (রা.)-এর শাহাদাতের খবর এলে নবীজি (সা.) বললেন, জা''ফরের পরিবারের জন্য খাবার তৈরি করো, কারণ তাদের ওপর এমন বিপদ এসেছে যা তাদের ব্যস্ত রেখেছে (সুনান আবু দাউদ ৩১৩২; জামে তিরমিজি ৯৯৮)।", "en": "Send food to the family: when news of Ja''far''s death came, the Prophet said, ''Prepare food for Ja''far''s family, for what has befallen them keeps them busy'' (Sunan Abi Dawud 3132; Jami'' al-Tirmidhi 998)."}, {"bn": "সংক্ষিপ্ত ও কোমল কথা বলুন; মৃতের ভালো দিকগুলো স্মরণ করুন।", "en": "Keep your words brief and gentle; mention the deceased''s good qualities."}, {"bn": "মৃতের ঋণ, সন্তানদের দেখাশোনা বা প্রয়োজনীয় কাজে সাহায্যের প্রস্তাব দিন।", "en": "Offer help with debts, children or practical tasks."}]}, {"type": "heading", "text": {"bn": "যা এড়িয়ে চলবেন", "en": "What to avoid"}}, {"type": "list", "items": [{"bn": "শোকাহত পরিবারকে মেহমানদারি ও বড় খাবারের আয়োজন করতে বাধ্য করা। জারির (রা.) বলেন, আমরা মৃতের পরিবারের কাছে সমবেত হওয়া ও তাদের খাবার তৈরি করাকে বিলাপের অংশ মনে করতাম (সুনান ইবনে মাজাহ ১৬১২)।", "en": "Burdening the bereaved with hosting and big meals. Jarir said: we considered gathering at the family of the deceased and their preparing food to be part of wailing (Sunan Ibn Majah 1612)."}, {"bn": "‘তার সময় হয়নি’, ‘কেন এমন হলো’ ধরনের অভিযোগের কথা বা তাকদিরের বিরুদ্ধে কথা।", "en": "Complaints against fate such as ''why did this happen''."}, {"bn": "দীর্ঘ সময় বসে থেকে পরিবারকে ক্লান্ত করা।", "en": "Sitting for long and tiring the family."}]}, {"type": "note", "tone": "info", "text": {"bn": "সুনান ইবনে মাজাহ ১৬১২-এর বর্ণনার সনদ নিয়ে মুহাদ্দিসদের মতভেদ আছে (কেউ সহিহ, কেউ দুর্বল বলেছেন)।", "en": "Scholars differ on the chain of the Sunan Ibn Majah 1612 report (some graded it sahih, others weak)."}}, {"type": "heading", "text": {"bn": "শোক পালনের সময়সীমা", "en": "Period of mourning"}}, {"type": "text", "text": {"bn": "কোনো আত্মীয়ের মৃত্যুতে তিন দিনের বেশি শোক পালন (সাজসজ্জা বর্জন ইত্যাদি) জায়েজ নয়; তবে স্ত্রী তার স্বামীর মৃত্যুতে চার মাস দশ দিন শোক পালন করবেন (সহিহ বুখারি ১২৮১)।", "en": "Mourning (giving up adornment, etc.) for any relative is not allowed beyond three days, except a wife for her husband: four months and ten days (Sahih al-Bukhari 1281)."}}]', 'in_review', 80 FROM is_guide_topics WHERE slug = 'janazah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'b9a5d864-8cb9-5738-84d5-8a14bafb9de9', id, 'janazah-iddah', '{"bn": "স্বামীর মৃত্যুর পর ইদ্দত (সংক্ষেপে)", "en": "Widow''s ''Iddah (Brief)"}', '{"bn": "স্বামী মারা গেলে স্ত্রীর ইদ্দতের সময়, এ সময়ে যা করবেন ও যা বর্জন করবেন, এবং প্রচলিত ভুল ধারণা।", "en": "The widow''s waiting period: its length, what to do and avoid, and common misconceptions."}', 'basic', '[{"type": "arabic", "ar": "وَالَّذِينَ يُتَوَفَّوْنَ مِنْكُمْ وَيَذَرُونَ أَزْوَاجًا يَتَرَبَّصْنَ بِأَنْفُسِهِنَّ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا", "pron": {"bn": "ওয়াল্লাযীনা ইউতাওয়াফফাওনা মিনকুম ওয়া ইয়াযারূনা আযওয়াজাই ইয়াতারাব্বাসনা বিআনফুসিহিন্না আরবাআতা আশহুরিও ওয়া আশরা।", "en": "Walladhina yutawaffawna minkum wa yadharuna azwajan yatarabbasna bi-anfusihinna arba''ata ashhurin wa ''ashra."}, "meaning": {"bn": "তোমাদের মধ্যে যারা মারা যায় এবং স্ত্রী রেখে যায়, সেই স্ত্রীরা চার মাস দশ দিন অপেক্ষা করবে।", "en": "Those of you who die leaving wives, the wives shall wait four months and ten days."}, "ref": {"bn": "সূরা বাকারা ২:২৩৪ (আয়াতের অংশ)", "en": "Al-Baqarah 2:234 (part of the verse)"}}, {"type": "table", "head": [{"bn": "অবস্থা", "en": "Situation"}, {"bn": "ইদ্দতের সময়", "en": "Length of ''iddah"}], "rows": [[{"bn": "স্বামীর মৃত্যু, স্ত্রী গর্ভবতী নন", "en": "Husband died, wife not pregnant"}, {"bn": "চার মাস দশ দিন (সূরা বাকারা ২:২৩৪)", "en": "Four months and ten days (Al-Baqarah 2:234)"}], [{"bn": "স্বামীর মৃত্যু, স্ত্রী গর্ভবতী", "en": "Husband died, wife pregnant"}, {"bn": "সন্তান প্রসব পর্যন্ত (সূরা তালাক ৬৫:৪)", "en": "Until she gives birth (At-Talaq 65:4)"}], [{"bn": "তালাক (তুলনার জন্য)", "en": "Divorce (for comparison)"}, {"bn": "তিন ঋতুস্রাব/পবিত্রতা (সূরা বাকারা ২:২২৮); ঋতুস্রাব না হলে তিন মাস (সূরা তালাক ৬৫:৪)", "en": "Three menstrual cycles (Al-Baqarah 2:228); three months if she does not menstruate (At-Talaq 65:4)"}]]}, {"type": "heading", "text": {"bn": "ইদ্দতের সময় করণীয় ও বর্জনীয়", "en": "During the ''iddah"}}, {"type": "list", "items": [{"bn": "স্বামীর ঘরে (যেখানে মৃত্যুর খবর পেয়েছেন) ইদ্দত পালন করবেন। ফুরাইআ (রা.)-কে নবীজি (সা.) ইদ্দত শেষ না হওয়া পর্যন্ত নিজের ঘরে থাকতে বলেছিলেন (সুনান আবু দাউদ ২৩০০)।", "en": "Stay in the marital home. The Prophet told Furay''ah to stay in her house until the ''iddah ended (Sunan Abi Dawud 2300)."}, {"bn": "প্রয়োজনে (যেমন জীবিকা, চিকিৎসা) দিনের বেলায় বের হওয়া যায়, রাতে নিজের ঘরে ফিরবেন।", "en": "She may go out by day for need (livelihood, treatment) and return to sleep at home."}, {"bn": "সাজসজ্জা বর্জন: সুগন্ধি, মেকআপ, মেহেদি, সুরমা (চিকিৎসা ছাড়া), অলংকার ও সাজের জন্য রঙিন জমকালো পোশাক।", "en": "Avoid adornment: perfume, make-up, henna, kohl (except as treatment), jewellery and decorative clothing."}, {"bn": "এ সময় বিয়ে করা বা বিয়ের প্রস্তাব গ্রহণ করা যাবে না; শুধু ইঙ্গিতে আগ্রহ প্রকাশ করা জায়েজ (সূরা বাকারা ২:২৩৫)।", "en": "No marriage or explicit proposal; only an indirect hint is allowed (Al-Baqarah 2:235)."}, {"bn": "গোসল, পরিচ্ছন্নতা, সাধারণ পরিষ্কার কাপড় পরা, নামাজ, কুরআন পড়া, মাহরাম ও প্রয়োজনে অন্যদের সাথে শালীনভাবে কথা বলা: সবই জায়েজ।", "en": "Bathing, cleanliness, plain clean clothes, prayer, Quran, and modest speech with mahrams and others when needed are all allowed."}]}, {"type": "note", "tone": "warn", "text": {"bn": "শুধু সাদা শাড়ি পরা বাধ্যতামূলক, চুড়ি ভাঙা, কারও সাথে কথা না বলা, চাঁদ বা আকাশ দেখা নিষেধ, ঘরের নির্দিষ্ট কোণে আটকে থাকা: এগুলো শরিয়তের বিধান নয়, সামাজিক প্রথা। শরিয়ত যা বলেছে, তা-ই পালন করুন।", "en": "Being required to wear only a white sari, breaking bangles, not speaking to anyone, not looking at the moon or sky, or being confined to a corner are customs, not Shari''ah rulings. Follow what the Shari''ah requires."}}, {"type": "note", "tone": "info", "text": {"bn": "ইদ্দত, উত্তরাধিকার ও তালাকের বিস্তারিত বিধান জটিল; নিজের অবস্থার জন্য একজন নির্ভরযোগ্য আলেমের পরামর্শ নিন।", "en": "The detailed rulings of ''iddah, inheritance and divorce are complex; consult a reliable scholar for your situation."}}]', 'in_review', 90 FROM is_guide_topics WHERE slug = 'janazah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '5350984c-399a-54eb-8606-c0bd43ee27a7', id, 'janazah-customs-to-avoid', '{"bn": "মৃত্যু ও জানাযাকেন্দ্রিক প্রচলিত রীতি: সতর্কতা", "en": "Funeral Customs: What Scholars Caution Against"}', '{"bn": "মৃত্যুকে কেন্দ্র করে সমাজে প্রচলিত কিছু রীতি, যেগুলো কুরআন-সুন্নাহয় প্রমাণিত নয় বলে আলেমরা সতর্ক করেছেন; সংযত ও নিরপেক্ষভাবে।", "en": "Some common customs around death that scholars caution have no basis in the Quran and sunnah, stated carefully and neutrally."}', 'detail', '[{"type": "arabic", "ar": "مَنْ أَحْدَثَ فِي أَمْرِنَا هٰذَا مَا لَيْسَ فِيهِ فَهُوَ رَدٌّ", "pron": {"bn": "মান আহদাসা ফী আমরিনা হাযা মা লাইসা ফীহি ফাহুয়া রাদ্দ।", "en": "Man ahdatha fi amrina hadha ma laysa fihi fahuwa radd."}, "meaning": {"bn": "যে আমাদের এই দ্বীনে এমন কিছু নতুন সংযোজন করে যা এর অংশ নয়, তা প্রত্যাখ্যাত।", "en": "Whoever introduces into this matter of ours something that is not part of it, it is rejected."}, "ref": {"bn": "সহিহ বুখারি ২৬৯৭", "en": "Sahih al-Bukhari 2697"}}, {"type": "text", "text": {"bn": "নিচের বিষয়গুলো সমাজে প্রচলিত, কিন্তু কুরআন-সুন্নাহ বা সাহাবিদের আমলে এগুলোর প্রমাণ নেই বলে বিভিন্ন মাজহাবের বহু আলেম সতর্ক করেছেন। উদ্দেশ্য কাউকে দোষারোপ করা নয়; মৃতের জন্য যা সত্যিই উপকারী (দোয়া, সদকা, ঋণ পরিশোধ), সেদিকে মনোযোগ দেওয়া। কিছু বিষয়ে আলেমদের মতভেদ আছে, তা উল্লেখ করা হলো।", "en": "The following are common, but many scholars across the schools caution that they have no basis in the Quran, sunnah or practice of the Companions. The aim is not to blame anyone but to focus on what truly benefits the dead (du''a, charity, paying debts). Where scholars differ, this is noted."}}, {"type": "heading", "text": {"bn": "যেসব বিষয়ে আলেমরা সতর্ক করেছেন", "en": "What scholars caution against"}}, {"type": "list", "items": [{"bn": "নির্দিষ্ট দিনে আয়োজন: মৃত্যুর তৃতীয় দিন (কুলখানি), চল্লিশতম দিন (চল্লিশা/চেহলাম), বার্ষিকী ইত্যাদিতে ভোজ ও মাহফিলকে দ্বীনের অংশ বা জরুরি মনে করা। সদকা ও দোয়া যেকোনো দিন করা যায়; নির্দিষ্ট দিন বেঁধে দেওয়ার প্রমাণ নেই।", "en": "Fixed-day gatherings: the 3rd day (kulkhani), 40th day (chollisha/chehlam), anniversaries, treated as religious or required. Charity and du''a can be done any day; fixing days has no evidence."}, {"bn": "মৃতের পরিবারের খরচে, বিশেষ করে এতিমের সম্পদ থেকে, বড় ভোজের আয়োজন। উত্তরাধিকারীদের মধ্যে নাবালেগ থাকলে তাদের অংশ থেকে এ খরচ করা জায়েজ নয়।", "en": "Large feasts paid by the bereaved family, especially from orphans'' shares. Spending a minor heir''s share on this is not permissible."}, {"bn": "টাকার বিনিময়ে খতম বা কুরআন পড়িয়ে মৃতের কাছে সওয়াব পাঠানো। হানাফি পরবর্তী আলেমসহ অনেকে বলেছেন, পারিশ্রমিক নিয়ে তিলাওয়াতে সওয়াব হয় না, তাই সওয়াব পৌঁছানোরও প্রশ্ন থাকে না।", "en": "Paying people to recite the Quran for the dead. Many scholars, including later Hanafis, said recitation for payment earns no reward, so there is none to pass on."}, {"bn": "জানাযার নামাজের পরপর সম্মিলিতভাবে হাত তুলে নির্দিষ্ট দোয়ার প্রথা: অনেক আলেম (উপমহাদেশের অনেক হানাফি আলেমসহ) একে সুন্নাহবিরোধী বলেছেন, কারণ জানাযা নিজেই দোয়া এবং এর পরে সম্মিলিত দোয়া প্রমাণিত নয়; কিছু আলেম অনুমতি দেন। একে জরুরি মনে না করা ও বিবাদ না করাই নিরাপদ।", "en": "A fixed collective du''a with raised hands right after the funeral prayer: many scholars (including many subcontinent Hanafis) say it is contrary to the sunnah since the prayer itself is du''a; some permit it. Safest not to treat it as required or quarrel over it."}, {"bn": "লাশ বহনের সময় উচ্চস্বরে সমবেত জিকির বা কালিমা পাঠ; সুন্নত হলো চুপচাপ চলা।", "en": "Loud collective dhikr while carrying the body; the sunnah is to walk quietly."}, {"bn": "কাফনে কালিমা বা আয়াত লেখা; কবরে আহাদনামা বা দোয়া লেখা কাগজ রাখা।", "en": "Writing the kalimah or verses on the shroud; placing written covenants or du''as in the grave."}, {"bn": "কবর পাকা করা, কবরের ওপর ঘর বা গম্বুজ নির্মাণ, কবরে বাতি বা মোমবাতি জ্বালানো, চাদর চড়ানো (সহিহ মুসলিম ৯৭০)।", "en": "Plastering graves, building over them, lighting lamps or candles, draping sheets on them (Sahih Muslim 970)."}, {"bn": "মৃতের রুহ নির্দিষ্ট রাতে (যেমন বৃহস্পতিবার রাতে) ঘরে ফিরে আসে, এমন বিশ্বাস রাখা; এর কোনো প্রমাণ নেই।", "en": "Believing the soul returns home on certain nights (e.g. Thursday night); there is no evidence for this."}, {"bn": "শোকের নামে নির্দিষ্ট দিন পর্যন্ত বাড়িতে রান্না বন্ধ রাখা, বা তিন দিনের বেশি শোক পালন (স্ত্রীর ইদ্দত ছাড়া)।", "en": "Not cooking at home for fixed days, or mourning beyond three days (other than a widow''s ''iddah)."}, {"bn": "বিলাপ, বুক চাপড়ানো, কাপড় ছেঁড়া, ভাড়া করা কান্নাকারী (সহিহ বুখারি ১২৯৪)।", "en": "Wailing, chest-beating, tearing clothes, hired mourners (Sahih al-Bukhari 1294)."}]}, {"type": "note", "tone": "info", "text": {"bn": "কবরে খেজুরের ডাল বা গাছের ডাল পোঁতা নিয়ে আলেমদের মতভেদ আছে: নবীজি (সা.) দুটি কবরে ডাল পুঁতেছিলেন (সহিহ বুখারি); কেউ কেউ একে নবীজি (সা.)-এর বিশেষ ঘটনা বলেছেন, কেউ সাধারণভাবে জায়েজ বলেছেন। ফুল দেওয়ার প্রথাকে অনেক আলেম অমুসলিমদের রীতির অনুকরণ বলে নিরুৎসাহিত করেছেন।", "en": "Scholars differ on placing palm or tree branches on graves: the Prophet placed branches on two graves (Sahih al-Bukhari); some see it as specific to him, others allow it generally. Many scholars discourage laying flowers as imitating non-Muslim customs."}, "check": true}, {"type": "heading", "text": {"bn": "যা সত্যিই উপকারে আসে", "en": "What truly helps"}}, {"type": "list", "items": [{"bn": "মৃতের ঋণ দ্রুত পরিশোধ ও ওসিয়ত পূরণ", "en": "Paying the deceased''s debts promptly and fulfilling the will"}, {"bn": "যেকোনো দিন, নিজের সামর্থ্যমতো তাদের পক্ষ থেকে সদকা, বিশেষ করে চলমান সদকা (পানির ব্যবস্থা, মসজিদ, দ্বীনি শিক্ষা)", "en": "Charity on their behalf any day, especially ongoing charity (water, mosques, religious education)"}, {"bn": "নিয়মিত তাদের জন্য দোয়া ও ইস্তিগফার", "en": "Regular du''a and istighfar for them"}, {"bn": "তাদের আত্মীয় ও বন্ধুদের সাথে সম্পর্ক রক্ষা", "en": "Keeping ties with their relatives and friends"}]}, {"type": "note", "tone": "tip", "text": {"bn": "এসব বিষয়ে পরিবারে বা সমাজে বিবাদ না করে নম্রভাবে আলোচনা করুন এবং নির্ভরযোগ্য স্থানীয় আলেমের পরামর্শ নিন।", "en": "Discuss these matters gently without quarrels in the family or community, and consult a reliable local scholar."}}]', 'in_review', 100 FROM is_guide_topics WHERE slug = 'janazah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'e8571845-b188-5ddc-8d9b-472420ac7530', id, 'fazilat-farz-salah', '{"bn": "ফরজ নামাজ: সময়মতো ও জামাতে পড়ার ফজিলত", "en": "Obligatory prayer: praying on time and in congregation"}', '{"bn": "সময়মতো নামাজ আল্লাহর কাছে সবচেয়ে প্রিয় আমলগুলোর একটি; জামাতে, বিশেষ করে ফজর ও এশা জামাতে পড়ার রয়েছে বিরাট সওয়াব।", "en": "Praying on time is among the deeds Allah loves most, and praying in congregation, especially Fajr and Isha, carries great reward."}', 'basic', '[{"type": "text", "text": {"bn": "নামাজ ইসলামের দ্বিতীয় স্তম্ভ। আল্লাহ বলেন: “নিশ্চয়ই নামাজ মুমিনদের ওপর নির্দিষ্ট সময়ে ফরজ করা হয়েছে।” আরও বলেন: “নিশ্চয়ই নামাজ অশ্লীল ও মন্দ কাজ থেকে বিরত রাখে।”", "en": "Prayer is the second pillar of Islam. Allah says: “Indeed, prayer has been decreed upon the believers at fixed times.” And: “Indeed, prayer prohibits immorality and wrongdoing.”"}}, {"type": "ref", "text": {"bn": "সূরা নিসা ৪:১০৩; সূরা আনকাবুত ২৯:৪৫", "en": "An-Nisa 4:103; Al-''Ankabut 29:45"}}, {"type": "heading", "text": {"bn": "সময়মতো নামাজ", "en": "Praying on time"}}, {"type": "text", "text": {"bn": "আবদুল্লাহ ইবনে মাসউদ (রা.) রাসুল ﷺ-কে জিজ্ঞেস করলেন, আল্লাহর কাছে সবচেয়ে প্রিয় আমল কোনটি? তিনি বললেন: “সময়মতো নামাজ পড়া।” তারপর মা-বাবার সঙ্গে সদ্ব্যবহার, তারপর আল্লাহর পথে জিহাদ।", "en": "Ibn Mas''ud (RA) asked which deed Allah loves most. The Prophet ﷺ said: “Prayer at its proper time,” then kindness to parents, then striving in Allah''s path."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৫২৭; সহিহ মুসলিম ৮৫", "en": "Sahih al-Bukhari 527; Sahih Muslim 85"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: তোমাদের কারও দরজার সামনে যদি একটি নদী থাকে আর সে দিনে পাঁচবার তাতে গোসল করে, তার শরীরে কি কোনো ময়লা থাকবে? পাঁচ ওয়াক্ত নামাজের উদাহরণও এমন; এর মাধ্যমে আল্লাহ গুনাহ মুছে দেন।", "en": "The Prophet ﷺ said: if a river ran by your door and you bathed in it five times a day, would any dirt remain? So it is with the five prayers; through them Allah wipes away sins."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৫২৮; সহিহ মুসলিম ৬৬৭", "en": "Sahih al-Bukhari 528; Sahih Muslim 667"}}, {"type": "text", "text": {"bn": "পাঁচ ওয়াক্ত নামাজ, এক জুমা থেকে আরেক জুমা এবং এক রমজান থেকে আরেক রমজান মাঝখানের গুনাহগুলোর কাফফারা, যদি কবিরা গুনাহ থেকে বেঁচে থাকা হয়।", "en": "The five prayers, Friday to Friday, and Ramadan to Ramadan expiate the sins between them, as long as major sins are avoided."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৩৩", "en": "Sahih Muslim 233"}}, {"type": "text", "text": {"bn": "কিয়ামতের দিন বান্দার আমলের মধ্যে সবার আগে নামাজের হিসাব নেওয়া হবে; নামাজ ঠিক থাকলে সে সফল হবে।", "en": "The first deed a servant will be asked about on the Day of Resurrection is prayer; if it is sound, he will succeed."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি ৪১৩", "en": "Jami'' at-Tirmidhi 413"}}, {"type": "heading", "text": {"bn": "জামাতে নামাজ", "en": "Praying in congregation"}}, {"type": "text", "text": {"bn": "জামাতে নামাজ একা নামাজের চেয়ে সাতাশ গুণ বেশি মর্যাদাপূর্ণ।", "en": "Prayer in congregation is twenty-seven degrees better than praying alone."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৬৪৫; সহিহ মুসলিম ৬৫০", "en": "Sahih al-Bukhari 645; Sahih Muslim 650"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: ভালোভাবে ওযু করে শুধু নামাজের উদ্দেশ্যে মসজিদে গেলে প্রতিটি কদমে একটি মর্যাদা বাড়ে ও একটি গুনাহ মাফ হয়, আর নামাজের অপেক্ষায় থাকা পর্যন্ত ফেরেশতারা তার জন্য দোয়া করতে থাকে।", "en": "Whoever makes wudu well and walks to the mosque only for prayer, every step raises him a degree and erases a sin, and the angels pray for him while he waits for the prayer."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৬৪৭", "en": "Sahih al-Bukhari 647"}}, {"type": "heading", "text": {"bn": "ফজর ও এশা জামাতে", "en": "Fajr and Isha in congregation"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: যে এশা জামাতে পড়ল, সে যেন অর্ধেক রাত নামাজ পড়ল; আর যে ফজরও জামাতে পড়ল, সে যেন সারা রাত নামাজ পড়ল।", "en": "The Prophet ﷺ said: whoever prays Isha in congregation, it is as if he prayed half the night; and whoever prays Fajr in congregation, it is as if he prayed the whole night."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৬৫৬", "en": "Sahih Muslim 656"}}, {"type": "text", "text": {"bn": "যে ফজরের নামাজ পড়ে, সে সারা দিন আল্লাহর জিম্মায় (নিরাপত্তায়) থাকে।", "en": "Whoever prays Fajr is under the protection of Allah."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৬৫৭", "en": "Sahih Muslim 657"}}, {"type": "text", "text": {"bn": "যে দুই ঠান্ডা সময়ের নামাজ (ফজর ও আসর) পড়ে, সে জান্নাতে প্রবেশ করবে।", "en": "Whoever prays the two cool prayers (Fajr and Asr) will enter Paradise."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৫৭৪; সহিহ মুসলিম ৬৩৫", "en": "Sahih al-Bukhari 574; Sahih Muslim 635"}}, {"type": "note", "tone": "warn", "text": {"bn": "মুনাফিকদের জন্য ফজর ও এশার চেয়ে ভারী কোনো নামাজ নেই; তারা যদি জানত এ দুটিতে কী আছে, হামাগুড়ি দিয়ে হলেও আসত (সহিহ বুখারি ৬৫৭)।", "en": "No prayer is heavier on the hypocrites than Fajr and Isha; if they knew what is in them, they would come even crawling (Sahih al-Bukhari 657)."}}, {"type": "differ", "title": {"bn": "পুরুষদের জন্য জামাতের হুকুম", "en": "Ruling of congregation for men"}, "views": [{"label": {"bn": "হানাফি ও মালিকি", "en": "Hanafi and Maliki"}, "text": {"bn": "সুন্নতে মুয়াক্কাদা; অনেক হানাফি আলেম বলেন এটি ওয়াজিবের কাছাকাছি, বিনা ওজরে নিয়মিত ছাড়া গুনাহ।", "en": "An emphasised sunnah; many Hanafi scholars say it is close to wajib and habitually leaving it without excuse is sinful."}, "evidence": {"bn": "সাতাশ গুণ বেশি সওয়াবের হাদিস দেখায় যে একা নামাজও সহিহ, তবে জামাত অনেক উত্তম (সহিহ বুখারি ৬৪৫)।", "en": "The twenty-seven-fold hadith shows that a lone prayer is valid but congregation is far better (Sahih al-Bukhari 645)."}}, {"label": {"bn": "শাফেয়ি", "en": "Shafi''i"}, "text": {"bn": "মাযহাবের প্রসিদ্ধ মত: ফরজে কিফায়া; এলাকায় কিছু লোক আদায় করলে বাকিরা দায়মুক্ত।", "en": "The well-known view: a communal obligation; if some in the area establish it, the rest are relieved."}, "evidence": {"bn": "জামাত কায়েম রাখার নির্দেশসংবলিত হাদিসগুলো সম্প্রদায়ের ওপর দায়িত্ব হিসেবে বোঝা হয়।", "en": "Hadiths ordering congregation to be established are understood as a duty on the community."}}, {"label": {"bn": "হাম্বলি", "en": "Hanbali"}, "text": {"bn": "সক্ষম প্রত্যেক পুরুষের ওপর ওয়াজিব, তবে একা পড়লেও নামাজ আদায় হয়ে যায়।", "en": "Obligatory on every able man, though a prayer prayed alone is still valid."}, "evidence": {"bn": "যারা জামাতে আসে না তাদের ঘর পুড়িয়ে দেওয়ার ইচ্ছা প্রকাশের হাদিস (সহিহ বুখারি ৬৪৪) এবং অন্ধ সাহাবিকেও আজান শুনলে আসতে বলা (সহিহ মুসলিম ৬৫৩)।", "en": "The hadith in which the Prophet ﷺ considered burning the houses of those who stayed away (Sahih al-Bukhari 644), and his telling a blind man who heard the call to come (Sahih Muslim 653)."}}]}]', 'in_review', 10 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'f3ad43d5-e127-5c7b-a72d-8d3c7191cb79', id, 'fazilat-sunnah-salah', '{"bn": "সুন্নত নামাজ: ফজরের দুই রাকাত ও দৈনিক ১২ রাকাত", "en": "Sunnah prayers: the two before Fajr and the daily twelve"}', '{"bn": "ফজরের আগের দুই রাকাত দুনিয়ার সবকিছুর চেয়ে উত্তম, আর দৈনিক ১২ রাকাত সুন্নতের বিনিময়ে জান্নাতে ঘর।", "en": "The two rak''ahs before Fajr are better than the world, and the daily twelve sunnah rak''ahs earn a house in Paradise."}', 'basic', '[{"type": "heading", "text": {"bn": "ফজরের আগের দুই রাকাত সুন্নত", "en": "The two rak''ahs before Fajr"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: “ফজরের দুই রাকাত (সুন্নত) দুনিয়া ও তার মধ্যে যা কিছু আছে তার চেয়ে উত্তম।”", "en": "The Prophet ﷺ said: “The two rak''ahs of Fajr are better than this world and all it contains.”"}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৭২৫", "en": "Sahih Muslim 725"}}, {"type": "text", "text": {"bn": "আয়েশা (রা.) বলেন: নফল নামাজগুলোর মধ্যে রাসুল ﷺ ফজরের দুই রাকাতের প্রতি যতটা যত্নশীল ছিলেন, অন্য কোনোটির প্রতি ততটা ছিলেন না।", "en": "Aishah (RA) said the Prophet ﷺ was not more regular about any voluntary prayer than the two rak''ahs of Fajr."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১১৬৯; সহিহ মুসলিম ৭২৪", "en": "Sahih al-Bukhari 1169; Sahih Muslim 724"}}, {"type": "heading", "text": {"bn": "দৈনিক ১২ রাকাত সুন্নতে মুয়াক্কাদা", "en": "The twelve emphasised sunnah rak''ahs"}}, {"type": "text", "text": {"bn": "উম্মে হাবিবা (রা.) থেকে বর্ণিত, রাসুল ﷺ বলেছেন: যে মুসলিম বান্দা প্রতিদিন ফরজ ছাড়া বারো রাকাত নফল নামাজ পড়ে, আল্লাহ তার জন্য জান্নাতে একটি ঘর বানিয়ে দেন।", "en": "Umm Habibah (RA) reported the Prophet ﷺ said: any Muslim who prays twelve voluntary rak''ahs each day besides the obligatory, Allah builds for him a house in Paradise."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৭২৮", "en": "Sahih Muslim 728"}}, {"type": "text", "text": {"bn": "তিরমিজির বর্ণনায় এর বিবরণ এসেছে:", "en": "Tirmidhi''s narration gives the breakdown:"}}, {"type": "table", "head": [{"bn": "ওয়াক্ত", "en": "Prayer"}, {"bn": "সুন্নত রাকাত", "en": "Sunnah rak''ahs"}], "rows": [[{"bn": "ফজরের আগে", "en": "Before Fajr"}, {"bn": "২", "en": "2"}], [{"bn": "যোহরের আগে", "en": "Before Zuhr"}, {"bn": "৪", "en": "4"}], [{"bn": "যোহরের পরে", "en": "After Zuhr"}, {"bn": "২", "en": "2"}], [{"bn": "মাগরিবের পরে", "en": "After Maghrib"}, {"bn": "২", "en": "2"}], [{"bn": "এশার পরে", "en": "After Isha"}, {"bn": "২", "en": "2"}]]}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি", "en": "Jami'' at-Tirmidhi"}, "check": true}, {"type": "differ", "title": {"bn": "যোহরের আগে দুই না চার রাকাত", "en": "Two or four before Zuhr"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "যোহরের আগে চার রাকাত সুন্নতে মুয়াক্কাদা।", "en": "Four rak''ahs before Zuhr are the emphasised sunnah."}, "evidence": {"bn": "উম্মে হাবিবা (রা.)-এর ১২ রাকাতের বিস্তারিত বর্ণনা (সুনান তিরমিজি), এবং আয়েশা (রা.) বলেছেন রাসুল ﷺ যোহরের আগে চার রাকাত ছাড়তেন না (সহিহ বুখারি)।", "en": "Umm Habibah''s detailed narration of the twelve (Tirmidhi), and Aishah''s report that he ﷺ did not leave four before Zuhr (al-Bukhari)."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি", "en": "Shafi''i and Hanbali"}, "text": {"bn": "দুই রাকাত মুয়াক্কাদা; চার রাকাত পড়া আরও উত্তম।", "en": "Two rak''ahs are emphasised; four are even better."}, "evidence": {"bn": "ইবনে উমর (রা.)-এর বর্ণনা: রাসুল ﷺ-এর কাছ থেকে দশ রাকাত মুখস্থ করেছি, যার মধ্যে যোহরের আগে দুই রাকাত (সহিহ বুখারি)।", "en": "Ibn Umar''s narration: I memorised ten rak''ahs from the Prophet ﷺ, including two before Zuhr (al-Bukhari)."}}], "check": true}, {"type": "note", "tone": "tip", "text": {"bn": "কোনো দিন সব না পারলেও অন্তত ফজরের দুই রাকাত সুন্নত কখনো ছাড়বেন না।", "en": "Even on a busy day, never leave the two sunnah rak''ahs of Fajr."}}]', 'in_review', 20 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '4daf878d-5b34-5cdf-99bc-2e31e60062ac', id, 'fazilat-wudu', '{"bn": "ওযুর ফজিলত", "en": "Virtues of wudu"}', '{"bn": "ওযুর পানির সঙ্গে গুনাহ ঝরে যায়, কিয়ামতের দিন ওযুর অঙ্গগুলো উজ্জ্বল হবে, আর ওযুর পরের দোয়ায় জান্নাতের আট দরজা খুলে যায়।", "en": "Sins fall away with the water of wudu, its traces will shine on the Last Day, and the dua after it opens all eight gates of Paradise."}', 'basic', '[{"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: মুসলিম বান্দা ওযু করার সময় মুখ ধুলে চোখ দিয়ে করা সব গুনাহ পানির সঙ্গে (বা পানির শেষ ফোঁটার সঙ্গে) বেরিয়ে যায়; হাত ধুলে হাত দিয়ে করা গুনাহ বেরিয়ে যায়; পা ধুলে পা দিয়ে করা গুনাহ বেরিয়ে যায়, শেষে সে গুনাহ থেকে পরিচ্ছন্ন হয়ে যায়।", "en": "The Prophet ﷺ said: when a Muslim washes his face in wudu, every sin his eyes committed leaves with the water; when he washes his hands, the sins of his hands leave; when he washes his feet, the sins his feet walked to leave, until he comes out cleansed of sin."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৪৪", "en": "Sahih Muslim 244"}}, {"type": "text", "text": {"bn": "উসমান (রা.) রাসুল ﷺ-এর মতো ওযু করে দেখালেন এবং বললেন, তিনি ﷺ বলেছেন: যে আমার এই ওযুর মতো ওযু করে মনোযোগ দিয়ে দুই রাকাত নামাজ পড়ে, তার আগের গুনাহ মাফ করে দেওয়া হয়।", "en": "Uthman (RA) demonstrated the Prophet''s ﷺ wudu and reported: whoever makes wudu like this and then prays two rak''ahs with focus, his previous sins are forgiven."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২২৬", "en": "Sahih Muslim 226"}}, {"type": "text", "text": {"bn": "কিয়ামতের দিন আমার উম্মতকে ডাকা হবে এমন অবস্থায় যে ওযুর প্রভাবে তাদের মুখ, হাত ও পা উজ্জ্বল থাকবে।", "en": "My ummah will be called on the Day of Resurrection with faces, hands and feet shining from the traces of wudu."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৩৬; সহিহ মুসলিম ২৪৬", "en": "Sahih al-Bukhari 136; Sahih Muslim 246"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: আমি কি তোমাদের এমন আমলের কথা বলব না যাতে আল্লাহ গুনাহ মুছে দেন ও মর্যাদা বাড়ান? কষ্টের সময়েও পূর্ণভাবে ওযু করা, মসজিদের দিকে বেশি কদম ফেলা এবং এক নামাজের পর আরেক নামাজের অপেক্ষা করা।", "en": "Shall I tell you what Allah wipes out sins with and raises ranks by? Completing wudu despite hardship, many steps to the mosque, and waiting for the next prayer after a prayer."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৫১", "en": "Sahih Muslim 251"}}, {"type": "heading", "text": {"bn": "ওযুর পরের দোয়া", "en": "Dua after wudu"}}, {"type": "arabic", "label": {"bn": "ওযুর পর কালেমা শাহাদাত", "en": "Testimony after wudu"}, "ar": "أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ", "pron": {"bn": "আশহাদু আল লা-ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারীকা লাহু, ওয়া আশহাদু আন্না মুহাম্মাদান আবদুহু ওয়া রাসূলুহু", "en": "Ash-hadu al-la ilaha illallahu wahdahu la sharika lah, wa ash-hadu anna Muhammadan ''abduhu wa rasuluh"}, "meaning": {"bn": "আমি সাক্ষ্য দিচ্ছি, আল্লাহ ছাড়া কোনো সত্য ইলাহ নেই, তিনি এক, তাঁর কোনো শরিক নেই; আর আমি সাক্ষ্য দিচ্ছি, মুহাম্মাদ তাঁর বান্দা ও রাসুল।", "en": "I bear witness that there is no god but Allah alone, without partner, and I bear witness that Muhammad is His servant and Messenger."}, "ref": {"bn": "সহিহ মুসলিম ২৩৪", "en": "Sahih Muslim 234"}}, {"type": "text", "text": {"bn": "যে ভালোভাবে ওযু করে এই দোয়া পড়ে, তার জন্য জান্নাতের আটটি দরজা খুলে দেওয়া হয়; যেটি দিয়ে ইচ্ছা প্রবেশ করবে।", "en": "Whoever makes wudu well and says this, the eight gates of Paradise are opened for him to enter by whichever he wishes."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৩৪", "en": "Sahih Muslim 234"}}, {"type": "note", "tone": "info", "text": {"bn": "ওযুর নিয়ম ও ফরজ-সুন্নত জানতে “তাহারাত” বিভাগ দেখুন।", "en": "For how to make wudu and its obligations, see the Taharah section."}}]', 'in_review', 30 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '16666e3c-3aff-54fc-aa70-45664dcc5312', id, 'fazilat-adhan', '{"bn": "আজান দেওয়া ও আজানের জবাব দেওয়ার ফজিলত", "en": "Virtues of the adhan and answering it"}', '{"bn": "মুয়াজ্জিনের মর্যাদা, আজানের জবাব দেওয়ার নিয়ম এবং আজানের পরের দোয়ায় রাসুল ﷺ-এর শাফায়াত লাভ।", "en": "The rank of the muadhdhin, how to answer the adhan, and the dua after it that earns the Prophet''s ﷺ intercession."}', 'basic', '[{"type": "heading", "text": {"bn": "আজান দেওয়ার ফজিলত", "en": "Virtue of calling the adhan"}}, {"type": "text", "text": {"bn": "মানুষ যদি জানত আজান দেওয়া ও প্রথম কাতারে কী সওয়াব আছে, আর লটারি ছাড়া তা পাওয়ার উপায় না থাকত, তবে তারা লটারি করত।", "en": "If people knew the reward of the adhan and the first row, and could only get them by drawing lots, they would draw lots."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৬১৫; সহিহ মুসলিম ৪৩৭", "en": "Sahih al-Bukhari 615; Sahih Muslim 437"}}, {"type": "text", "text": {"bn": "কিয়ামতের দিন মুয়াজ্জিনরা সবচেয়ে লম্বা গলাওয়ালা (সবচেয়ে সম্মানিত) হবে।", "en": "The muadhdhins will have the longest necks (the highest honour) on the Day of Resurrection."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৩৮৭", "en": "Sahih Muslim 387"}}, {"type": "text", "text": {"bn": "মুয়াজ্জিনের আওয়াজ যত দূর পৌঁছে, জিন, মানুষ ও যা কিছু তা শোনে, কিয়ামতের দিন তার পক্ষে সাক্ষ্য দেবে।", "en": "Every jinn, human or thing that hears the muadhdhin''s voice will testify for him on the Day of Resurrection."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৬০৯", "en": "Sahih al-Bukhari 609"}}, {"type": "heading", "text": {"bn": "আজানের জবাব", "en": "Answering the adhan"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: মুয়াজ্জিনকে শুনলে সে যা বলে তোমরাও তা-ই বলো; তারপর আমার ওপর দরুদ পড়ো, তারপর আমার জন্য আল্লাহর কাছে “ওয়াসিলা” চাও। যে আমার জন্য ওয়াসিলা চাইবে, তার জন্য আমার শাফায়াত অবধারিত হবে।", "en": "When you hear the muadhdhin, say what he says, then send blessings on me, then ask Allah for al-Wasilah for me; whoever asks for it for me, my intercession becomes due for him."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৩৮৪", "en": "Sahih Muslim 384"}}, {"type": "text", "text": {"bn": "“হাইয়া আলাস সালাহ” ও “হাইয়া আলাল ফালাহ” শুনে বলতে হয়: “লা হাওলা ওয়ালা কুওয়াতা ইল্লা বিল্লাহ।” যে আন্তরিকভাবে এভাবে জবাব দেয়, সে জান্নাতে যাবে।", "en": "On hearing “Hayya ''alas-salah” and “Hayya ''alal-falah,” say “La hawla wa la quwwata illa billah.” Whoever answers sincerely like this will enter Paradise."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৩৮৫", "en": "Sahih Muslim 385"}}, {"type": "arabic", "label": {"bn": "মুয়াজ্জিনের শাহাদাত শুনে", "en": "On hearing the muadhdhin''s testimony"}, "ar": "وَأَنَا أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، رَضِيتُ بِاللّٰهِ رَبًّا، وَبِمُحَمَّدٍ رَسُولًا، وَبِالْإِسْلَامِ دِينًا", "pron": {"bn": "ওয়া আনা আশহাদু আল লা-ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারীকা লাহু, ওয়া আন্না মুহাম্মাদান আবদুহু ওয়া রাসূলুহু, রাদীতু বিল্লাহি রব্বান, ওয়া বিমুহাম্মাদিন রাসূলান, ওয়া বিল ইসলামি দীনা", "en": "Wa ana ash-hadu al-la ilaha illallahu wahdahu la sharika lah, wa anna Muhammadan ''abduhu wa rasuluh, raditu billahi rabban, wa bi-Muhammadin rasulan, wa bil-Islami dina"}, "meaning": {"bn": "আমিও সাক্ষ্য দিচ্ছি, আল্লাহ ছাড়া কোনো সত্য ইলাহ নেই, তিনি এক, তাঁর শরিক নেই, আর মুহাম্মাদ তাঁর বান্দা ও রাসুল। আমি আল্লাহকে রব, মুহাম্মাদকে রাসুল এবং ইসলামকে দ্বীন হিসেবে পেয়ে সন্তুষ্ট।", "en": "And I too bear witness that there is no god but Allah alone, without partner, and that Muhammad is His servant and Messenger. I am pleased with Allah as Lord, Muhammad as Messenger and Islam as religion."}, "ref": {"bn": "সহিহ মুসলিম ৩৮৬", "en": "Sahih Muslim 386"}}, {"type": "text", "text": {"bn": "যে মুয়াজ্জিনের শাহাদাত শুনে এটি বলে, তার গুনাহ মাফ করে দেওয়া হয়।", "en": "Whoever says this on hearing the muadhdhin, his sins are forgiven."}}, {"type": "heading", "text": {"bn": "আজানের পরের দোয়া", "en": "Dua after the adhan"}}, {"type": "arabic", "label": {"bn": "আজানের পরের দোয়া", "en": "Dua after the adhan"}, "ar": "اللّٰهُمَّ رَبَّ هٰذِهِ الدَّعْوَةِ التَّامَّةِ، وَالصَّلَاةِ الْقَائِمَةِ، آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ، وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ", "pron": {"bn": "আল্লাহুম্মা রব্বা হাযিহিদ দা''ওয়াতিত তাম্মাহ, ওয়াস সালাতিল কা-ইমাহ, আতি মুহাম্মাদানিল ওয়াসীলাতা ওয়াল ফাদীলাহ, ওয়াব''আসহু মাকামাম মাহমূদানিল্লাযী ওয়া''আদতাহ", "en": "Allahumma rabba hadhihid-da''watit-tammah, was-salatil-qa''imah, ati Muhammadanil-wasilata wal-fadilah, wab''ath-hu maqamam mahmudanil-ladhi wa''adtah"}, "meaning": {"bn": "হে আল্লাহ, এই পরিপূর্ণ আহ্বান ও প্রতিষ্ঠিত নামাজের রব, মুহাম্মাদ ﷺ-কে ওয়াসিলা ও শ্রেষ্ঠ মর্যাদা দান করুন এবং তাঁকে সেই প্রশংসিত স্থানে পৌঁছে দিন, যার ওয়াদা আপনি তাঁকে দিয়েছেন।", "en": "O Allah, Lord of this perfect call and the prayer about to be established, grant Muhammad al-Wasilah and excellence, and raise him to the praised station You promised him."}, "ref": {"bn": "সহিহ বুখারি ৬১৪", "en": "Sahih al-Bukhari 614"}}, {"type": "text", "text": {"bn": "যে আজান শুনে এই দোয়া পড়ে, কিয়ামতের দিন তার জন্য রাসুল ﷺ-এর শাফায়াত অবধারিত হয়ে যায়।", "en": "Whoever says this after hearing the adhan, the Prophet''s ﷺ intercession becomes due for him on the Day of Resurrection."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৬১৪", "en": "Sahih al-Bukhari 614"}}, {"type": "note", "tone": "info", "text": {"bn": "প্রচলিত কিছু দোয়ার বইয়ে “ওয়াদ-দারাজাতার রাফিআহ” অংশ যোগ করা থাকে; সহিহ বুখারির বর্ণনায় এটি নেই। শেষে “ইন্নাকা লা তুখলিফুল মী''আদ” বায়হাকির একটি বর্ণনায় এসেছে, যার সনদ নিয়ে মুহাদ্দিসদের আপত্তি আছে। বুখারির শব্দগুলো পড়াই নিরাপদ।", "en": "Some dua books add “wad-darajatar-rafi''ah”; it is not in al-Bukhari''s narration. “Innaka la tukhliful-mi''ad” at the end comes in a narration of al-Bayhaqi whose chain scholars have questioned. Reciting al-Bukhari''s wording is safest."}}]', 'in_review', 40 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'e6d41a69-1d08-5baf-b6c6-77679bfc6c3a', id, 'fazilat-jumuah', '{"bn": "জুমার দিনের ফজিলত", "en": "Virtues of Friday (Jumu''ah)"}', '{"bn": "জুমা সপ্তাহের শ্রেষ্ঠ দিন: গোসল করে আগে আগে মসজিদে যাওয়া, চুপ করে খুতবা শোনা, দোয়া কবুলের মুহূর্ত ও বেশি বেশি দরুদ।", "en": "Friday is the best day of the week: ghusl, going early, listening silently to the khutbah, the hour of answered dua, and abundant salawat."}', 'basic', '[{"type": "text", "text": {"bn": "আল্লাহ বলেন: “হে মুমিনগণ, জুমার দিনে যখন নামাজের জন্য আহ্বান করা হয়, তখন আল্লাহর স্মরণের দিকে ছুটে যাও এবং বেচাকেনা ছেড়ে দাও।”", "en": "Allah says: “O you who believe, when the call is made for prayer on Friday, hasten to the remembrance of Allah and leave trade.”"}}, {"type": "ref", "text": {"bn": "সূরা জুমুআ ৬২:৯", "en": "Al-Jumu''ah 62:9"}}, {"type": "text", "text": {"bn": "সূর্য উদিত হয় এমন দিনগুলোর মধ্যে শ্রেষ্ঠ দিন জুমার দিন; এ দিনে আদম (আ.)-কে সৃষ্টি করা হয়েছে, এ দিনে তাঁকে জান্নাতে প্রবেশ করানো হয়েছে, এ দিনেই সেখান থেকে বের করা হয়েছে, আর কিয়ামতও জুমার দিনেই হবে।", "en": "The best day on which the sun rises is Friday: on it Adam was created, entered Paradise and was sent out of it, and the Hour will be on a Friday."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৮৫৪", "en": "Sahih Muslim 854"}}, {"type": "heading", "text": {"bn": "আগে আগে মসজিদে যাওয়া", "en": "Going early"}}, {"type": "text", "text": {"bn": "যে জুমার দিন জানাবাতের গোসলের মতো গোসল করে প্রথম সময়ে মসজিদে যায়, সে যেন একটি উট কুরবানি করল; দ্বিতীয় সময়ে গেলে গরু, তৃতীয় সময়ে শিংওয়ালা দুম্বা, চতুর্থ সময়ে মুরগি, পঞ্চম সময়ে ডিম। ইমাম খুতবার জন্য বের হলে ফেরেশতারা খাতা বন্ধ করে খুতবা শুনতে থাকেন।", "en": "Whoever takes a full ghusl on Friday and goes in the first hour, it is as if he sacrificed a camel; in the second a cow, the third a horned ram, the fourth a hen, the fifth an egg. When the imam comes out, the angels close their records and listen."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৮৮১; সহিহ মুসলিম ৮৫০", "en": "Sahih al-Bukhari 881; Sahih Muslim 850"}}, {"type": "text", "text": {"bn": "যে জুমার দিন গোসল করে, সাধ্যমতো পবিত্রতা অর্জন করে, তেল বা সুগন্ধি লাগায়, মসজিদে গিয়ে দুজনের মাঝে ফাঁক করে না, তার জন্য যা নির্ধারিত তা নামাজ পড়ে, তারপর ইমাম কথা বললে চুপ থাকে, তার এই জুমা থেকে আগের জুমা পর্যন্ত গুনাহ মাফ হয়।", "en": "Whoever bathes on Friday, purifies himself as he can, uses oil or perfume, goes out without separating two people, prays what is written for him and listens silently when the imam speaks, is forgiven what is between that Friday and the previous one."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৮৮৩", "en": "Sahih al-Bukhari 883"}}, {"type": "text", "text": {"bn": "মুসলিমের বর্ণনায় আছে: এর সঙ্গে আরও তিন দিনের গুনাহ মাফ হয়।", "en": "In Muslim''s narration: plus three more days."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৮৫৭", "en": "Sahih Muslim 857"}}, {"type": "heading", "text": {"bn": "দোয়া কবুলের মুহূর্ত", "en": "The hour of acceptance"}}, {"type": "text", "text": {"bn": "জুমার দিনে একটি মুহূর্ত আছে, কোনো মুসলিম বান্দা তখন নামাজে দাঁড়িয়ে আল্লাহর কাছে কোনো কল্যাণ চাইলে আল্লাহ তা দেন।", "en": "On Friday there is an hour in which no Muslim stands praying and asks Allah for good except that He gives it to him."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৯৩৫; সহিহ মুসলিম ৮৫২", "en": "Sahih al-Bukhari 935; Sahih Muslim 852"}}, {"type": "note", "tone": "info", "text": {"bn": "এই মুহূর্ত কখন, তা নিয়ে আলেমদের কয়েকটি মত আছে; প্রসিদ্ধ দুটি হলো: ইমাম মিম্বরে বসা থেকে নামাজ শেষ হওয়া পর্যন্ত (সহিহ মুসলিম ৮৫৩), এবং আসরের পর থেকে সূর্যাস্ত পর্যন্ত (সুনান আবু দাউদ)। দুটো সময়েই দোয়া করা ভালো।", "en": "Scholars hold several views on when this hour is; the best known are from when the imam sits on the minbar until the prayer ends (Sahih Muslim 853), and the last hour after Asr until sunset (Sunan Abi Dawud). It is good to make dua in both."}, "check": true}, {"type": "heading", "text": {"bn": "জুমার দিনে বেশি দরুদ", "en": "More salawat on Friday"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: তোমাদের দিনগুলোর মধ্যে জুমার দিন শ্রেষ্ঠ; এ দিনে আমার ওপর বেশি বেশি দরুদ পড়ো, কারণ তোমাদের দরুদ আমার কাছে পেশ করা হয়।", "en": "The best of your days is Friday, so send abundant blessings on me on it, for your blessings are presented to me."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ; সুনান নাসায়ি", "en": "Sunan Abi Dawud; Sunan an-Nasa''i"}, "check": true}, {"type": "note", "tone": "warn", "text": {"bn": "বিনা ওজরে অবহেলা করে পরপর তিন জুমা ছেড়ে দিলে আল্লাহ তার অন্তরে মোহর মেরে দেন (সুনান আবু দাউদ, সুনান তিরমিজি)।", "en": "Whoever leaves three Fridays in a row out of negligence, Allah seals his heart (Sunan Abi Dawud, Jami'' at-Tirmidhi)."}, "check": true}, {"type": "note", "tone": "tip", "text": {"bn": "জুমার দিন সূরা কাহফ পড়ার ফজিলত আলাদা গাইডে দেখুন।", "en": "See the separate guide on reciting Surah Al-Kahf on Friday."}}]', 'in_review', 50 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'e529c1cb-54f5-5fc2-80bd-682804ed623a', id, 'fazilat-tahajjud', '{"bn": "তাহাজ্জুদ (রাতের নামাজ)-এর ফজিলত", "en": "Virtues of Tahajjud (night prayer)"}', '{"bn": "ফরজের পর শ্রেষ্ঠ নামাজ রাতের নামাজ; রাতের শেষ তৃতীয়াংশে আল্লাহ বান্দাদের ডাকেন।", "en": "After the obligatory prayers, the best prayer is the night prayer; in the last third of the night Allah calls out to His servants."}', 'basic', '[{"type": "text", "text": {"bn": "আল্লাহ রাসুল ﷺ-কে বলেন: “রাতের কিছু অংশে তাহাজ্জুদ পড়ো, এটি তোমার জন্য অতিরিক্ত; আশা করা যায় তোমার রব তোমাকে প্রশংসিত স্থানে পৌঁছাবেন।” আর মুমিনদের প্রশংসায় বলেন: “তাদের পার্শ্ব বিছানা থেকে আলাদা থাকে; তারা ভয় ও আশা নিয়ে তাদের রবকে ডাকে।”", "en": "Allah tells the Prophet ﷺ: “And from part of the night, pray with it as extra for you; it is expected your Lord will raise you to a praised station.” And He praises the believers: “Their sides forsake their beds; they call upon their Lord in fear and hope.”"}}, {"type": "ref", "text": {"bn": "সূরা বনি ইসরাঈল ১৭:৭৯; সূরা সাজদা ৩২:১৬", "en": "Al-Isra 17:79; As-Sajdah 32:16"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: রমজানের পর শ্রেষ্ঠ রোজা আল্লাহর মাস মহররমের রোজা, আর ফরজ নামাজের পর শ্রেষ্ঠ নামাজ রাতের নামাজ।", "en": "The best fasting after Ramadan is in Allah''s month of Muharram, and the best prayer after the obligatory is the night prayer."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১১৬৩", "en": "Sahih Muslim 1163"}}, {"type": "text", "text": {"bn": "প্রতি রাতে শেষ তৃতীয়াংশে আমাদের রব দুনিয়ার আসমানে নেমে আসেন এবং বলেন: কে আমাকে ডাকবে, আমি সাড়া দেব? কে আমার কাছে চাইবে, আমি দেব? কে আমার কাছে ক্ষমা চাইবে, আমি ক্ষমা করব?", "en": "Every night, in its last third, our Lord descends to the lowest heaven and says: Who will call on Me that I may answer? Who will ask Me that I may give? Who will seek My forgiveness that I may forgive?"}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১১৪৫; সহিহ মুসলিম ৭৫৮", "en": "Sahih al-Bukhari 1145; Sahih Muslim 758"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ রাতে এত দীর্ঘ নামাজ পড়তেন যে তাঁর পা ফুলে যেত; জিজ্ঞেস করা হলে বলতেন: “আমি কি কৃতজ্ঞ বান্দা হব না?”", "en": "The Prophet ﷺ prayed so long at night that his feet swelled; when asked, he said: “Should I not be a grateful servant?”"}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি; সহিহ মুসলিম", "en": "Sahih al-Bukhari; Sahih Muslim"}, "check": true}, {"type": "heading", "text": {"bn": "কীভাবে শুরু করবেন", "en": "How to start"}}, {"type": "list", "items": [{"bn": "ঘুমানোর আগে নিয়ত করে রাখুন এবং এশার পর তাড়াতাড়ি ঘুমান।", "en": "Intend it before sleeping and sleep early after Isha."}, {"bn": "দুই রাকাত দিয়েও শুরু করা যায়; রাসুল ﷺ সাধারণত বিতরসহ এগারো রাকাতের বেশি পড়তেন না (সহিহ বুখারি ১১৪৭)।", "en": "You can start with just two rak''ahs; the Prophet ﷺ usually did not exceed eleven including witr (Sahih al-Bukhari 1147)."}, {"bn": "শেষ রাতে উঠতে না পারার আশঙ্কা থাকলে ঘুমানোর আগেই বিতর পড়ে নিন (সহিহ মুসলিম ৭৫৫)।", "en": "If you fear not waking, pray witr before sleeping (Sahih Muslim 755)."}, {"bn": "সিজদায় ও নামাজ শেষে নিজের ভাষায় মন খুলে দোয়া করুন।", "en": "Make heartfelt dua in sujood and after the prayer in your own words."}]}]', 'in_review', 60 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '484f1126-c853-5628-97f6-02b33779f68c', id, 'fazilat-quran-tilawat', '{"bn": "কুরআন তিলাওয়াতের ফজিলত", "en": "Virtues of reciting the Quran"}', '{"bn": "প্রতিটি হরফে নেকি, কিয়ামতের দিন সুপারিশ, আর আটকে আটকে পড়লেও দ্বিগুণ সওয়াব।", "en": "A reward for every letter, intercession on the Last Day, and a double reward even for one who struggles."}', 'basic', '[{"type": "text", "text": {"bn": "আল্লাহ বলেন: “যারা আল্লাহর কিতাব তিলাওয়াত করে, নামাজ কায়েম করে এবং আমার দেওয়া রিজিক থেকে গোপনে ও প্রকাশ্যে ব্যয় করে, তারা এমন ব্যবসার আশা করে যা কখনো লোকসান হবে না।”", "en": "Allah says: “Those who recite the Book of Allah, establish prayer and spend from what We provided them, secretly and openly, hope for a trade that will never perish.”"}}, {"type": "ref", "text": {"bn": "সূরা ফাতির ৩৫:২৯–৩০", "en": "Fatir 35:29–30"}}, {"type": "text", "text": {"bn": "যে আল্লাহর কিতাবের একটি হরফ পড়ে, সে একটি নেকি পায়, আর একটি নেকি দশ গুণ। আমি বলি না “আলিফ-লাম-মীম” একটি হরফ; বরং আলিফ একটি হরফ, লাম একটি হরফ, মীম একটি হরফ।", "en": "Whoever reads a letter of Allah''s Book gets a good deed, and a good deed is multiplied by ten. I do not say “Alif-Lam-Mim” is one letter; Alif is a letter, Lam is a letter and Mim is a letter."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি ২৯১০", "en": "Jami'' at-Tirmidhi 2910"}}, {"type": "text", "text": {"bn": "তোমাদের মধ্যে সর্বোত্তম সে, যে কুরআন শেখে ও শেখায়।", "en": "The best of you are those who learn the Quran and teach it."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৫০২৭", "en": "Sahih al-Bukhari 5027"}}, {"type": "text", "text": {"bn": "কুরআন পড়ো, কারণ কিয়ামতের দিন কুরআন তার পাঠকদের জন্য সুপারিশকারী হয়ে আসবে।", "en": "Recite the Quran, for it will come on the Day of Resurrection as an intercessor for its companions."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৮০৪", "en": "Sahih Muslim 804"}}, {"type": "text", "text": {"bn": "যে কুরআনে দক্ষ, সে সম্মানিত পুণ্যবান লেখক ফেরেশতাদের সঙ্গে থাকবে; আর যে কষ্ট করে আটকে আটকে পড়ে, সে দ্বিগুণ সওয়াব পাবে।", "en": "One skilled in the Quran will be with the noble, righteous scribes; and one who recites with difficulty, stumbling, gets a double reward."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৪৯৩৭; সহিহ মুসলিম ৭৯৮", "en": "Sahih al-Bukhari 4937; Sahih Muslim 798"}}, {"type": "text", "text": {"bn": "যখন কিছু মানুষ আল্লাহর কোনো ঘরে একত্র হয়ে কুরআন পড়ে ও পরস্পর আলোচনা করে, তাদের ওপর প্রশান্তি নাজিল হয়, রহমত তাদের ঢেকে নেয়, ফেরেশতারা তাদের ঘিরে রাখে এবং আল্লাহ তাঁর কাছে থাকা ফেরেশতাদের কাছে তাদের কথা উল্লেখ করেন।", "en": "Whenever people gather in a house of Allah reciting and studying the Quran together, tranquillity descends on them, mercy covers them, angels surround them and Allah mentions them to those with Him."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৬৯৯", "en": "Sahih Muslim 2699"}}, {"type": "text", "text": {"bn": "আল্লাহ এই কিতাব দিয়ে কিছু জাতিকে উঁচু করেন আর কিছু জাতিকে নিচু করেন।", "en": "Allah raises some people by this Book and lowers others by it."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৮১৭", "en": "Sahih Muslim 817"}}, {"type": "note", "tone": "tip", "text": {"bn": "অর্থ না বুঝে পড়লেও সওয়াব আছে, তবে প্রতিদিন অল্প হলেও অর্থসহ পড়ার চেষ্টা করুন, যাতে কুরআন জীবনে প্রভাব ফেলে।", "en": "There is reward even without understanding, but try to read a little with meaning each day so the Quran shapes your life."}}]', 'in_review', 70 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '28d707d4-63ce-5ee6-9f9e-c6db196051f8', id, 'fazilat-surah-fatihah', '{"bn": "সূরা ফাতিহার ফজিলত", "en": "Virtues of Surah Al-Fatihah"}', '{"bn": "কুরআনের সবচেয়ে মহান সূরা, যা প্রতি রাকাতে পড়া হয় এবং যার প্রতিটি আয়াতে আল্লাহ বান্দার জবাব দেন।", "en": "The greatest surah of the Quran, recited in every rak''ah, with Allah responding to each verse."}', 'basic', '[{"type": "text", "text": {"bn": "রাসুল ﷺ আবু সাঈদ ইবনুল মুআল্লা (রা.)-কে বললেন: আমি তোমাকে কুরআনের সবচেয়ে মহান সূরা শিখিয়ে দেব: “আলহামদু লিল্লাহি রব্বিল আলামীন”; এটিই “আস-সাবউল মাসানি” (বারবার পঠিত সাত আয়াত) এবং আমাকে দেওয়া মহান কুরআন।", "en": "The Prophet ﷺ told Abu Sa''id ibn al-Mu''alla (RA): I will teach you the greatest surah in the Quran: “Al-hamdu lillahi rabbil-''alamin”; it is the seven oft-repeated verses and the great Quran given to me."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৪৪৭৪", "en": "Sahih al-Bukhari 4474"}}, {"type": "text", "text": {"bn": "একজন ফেরেশতা রাসুল ﷺ-কে বললেন: আপনাকে এমন দুটি নূরের সুসংবাদ দিচ্ছি যা আপনার আগে কোনো নবীকে দেওয়া হয়নি: সূরা ফাতিহা এবং সূরা বাকারার শেষ আয়াতগুলো। এগুলোর যে অংশই আপনি পড়বেন, তা আপনাকে দেওয়া হবে।", "en": "An angel told the Prophet ﷺ: rejoice in two lights given to you that were given to no prophet before you: Al-Fatihah and the closing verses of Al-Baqarah. You will not recite a letter of them without being given it."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৮০৬", "en": "Sahih Muslim 806"}}, {"type": "heading", "text": {"bn": "বান্দা ও আল্লাহর কথোপকথন", "en": "A conversation between the servant and Allah"}}, {"type": "text", "text": {"bn": "হাদিসে কুদসিতে আল্লাহ বলেন: আমি নামাজকে (ফাতিহাকে) আমার ও আমার বান্দার মাঝে ভাগ করেছি, আর আমার বান্দা যা চায় তা পাবে।", "en": "In a hadith qudsi Allah says: I have divided the prayer (Al-Fatihah) between Myself and My servant, and My servant shall have what he asks."}}, {"type": "list", "items": [{"bn": "বান্দা বলে “আলহামদু লিল্লাহি রব্বিল আলামীন”, আল্লাহ বলেন: আমার বান্দা আমার প্রশংসা করেছে।", "en": "The servant says “All praise is for Allah, Lord of the worlds”; Allah says: My servant has praised Me."}, {"bn": "বান্দা বলে “আর-রহমানির রহীম”, আল্লাহ বলেন: আমার বান্দা আমার গুণগান করেছে।", "en": "He says “the Most Gracious, the Most Merciful”; Allah says: My servant has extolled Me."}, {"bn": "বান্দা বলে “মালিকি ইয়াওমিদ্দীন”, আল্লাহ বলেন: আমার বান্দা আমার মহিমা ঘোষণা করেছে।", "en": "He says “Master of the Day of Judgement”; Allah says: My servant has glorified Me."}, {"bn": "বান্দা বলে “ইয়্যাকা না''বুদু ওয়া ইয়্যাকা নাসতাঈন”, আল্লাহ বলেন: এটি আমার ও আমার বান্দার মাঝে, আর বান্দা যা চায় তা পাবে।", "en": "He says “You alone we worship and You alone we ask for help”; Allah says: This is between Me and My servant, and he shall have what he asks."}, {"bn": "বান্দা শেষ আয়াতগুলোতে হেদায়াত চায়, আল্লাহ বলেন: এগুলো আমার বান্দার জন্য, আর সে যা চায় তা পাবে।", "en": "He asks for guidance in the last verses; Allah says: This is for My servant, and he shall have what he asks."}]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৩৯৫", "en": "Sahih Muslim 395"}}, {"type": "arabic", "ar": "إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ", "pron": {"bn": "ইয়্যাকা না''বুদু ওয়া ইয়্যাকা নাসতাঈন", "en": "Iyyaka na''budu wa iyyaka nasta''in"}, "meaning": {"bn": "আমরা কেবল আপনারই ইবাদত করি এবং কেবল আপনারই সাহায্য চাই।", "en": "You alone we worship, and You alone we ask for help."}, "ref": {"bn": "সূরা ফাতিহা ১:৫", "en": "Al-Fatihah 1:5"}}, {"type": "text", "text": {"bn": "এক সাহাবি সাপে কাটা এক গোত্রপ্রধানের ওপর সূরা ফাতিহা পড়ে ফুঁ দিলে তিনি সুস্থ হন, আর রাসুল ﷺ তা সমর্থন করেন; তাই ফাতিহা রুকইয়া (ঝাড়ফুঁক) হিসেবেও পড়া যায়।", "en": "A Companion recited Al-Fatihah over a tribal chief stung by a scorpion and he recovered, and the Prophet ﷺ approved; so it may be recited as ruqyah."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি", "en": "Sahih al-Bukhari"}, "check": true}]', 'in_review', 80 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '2104f8ee-7334-50fb-8368-8c8216d71c76', id, 'fazilat-surah-ikhlas', '{"bn": "সূরা ইখলাসের ফজিলত", "en": "Virtues of Surah Al-Ikhlas"}', '{"bn": "সূরা ইখলাস কুরআনের এক-তৃতীয়াংশের সমান, আর এর প্রতি ভালোবাসা আল্লাহর ভালোবাসা এনে দেয়।", "en": "Surah Al-Ikhlas equals a third of the Quran, and loving it brings Allah''s love."}', 'basic', '[{"type": "arabic", "label": {"bn": "সূরা ইখলাস", "en": "Surah Al-Ikhlas"}, "ar": "قُلْ هُوَ اللّٰهُ أَحَدٌ ۝ اللّٰهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ", "pron": {"bn": "কুল হুওয়াল্লাহু আহাদ। আল্লাহুস সামাদ। লাম ইয়ালিদ ওয়া লাম ইউলাদ। ওয়া লাম ইয়াকুল লাহু কুফুওয়ান আহাদ।", "en": "Qul huwallahu ahad. Allahus-samad. Lam yalid wa lam yulad. Wa lam yakun lahu kufuwan ahad."}, "meaning": {"bn": "বলো, তিনি আল্লাহ, এক ও অদ্বিতীয়। আল্লাহ অমুখাপেক্ষী। তিনি কাউকে জন্ম দেননি, তাঁকেও কেউ জন্ম দেয়নি। আর তাঁর সমকক্ষ কেউ নেই।", "en": "Say: He is Allah, the One. Allah, the Eternal Refuge. He neither begets nor is born. And there is none comparable to Him."}, "ref": {"bn": "সূরা ইখলাস ১১২:১–৪", "en": "Al-Ikhlas 112:1–4"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: যাঁর হাতে আমার প্রাণ, তাঁর কসম, এই সূরা কুরআনের এক-তৃতীয়াংশের সমান।", "en": "By Him in whose hand is my soul, it is equal to a third of the Quran."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৫০১৩; সহিহ মুসলিম ৮১১", "en": "Sahih al-Bukhari 5013; Sahih Muslim 811"}}, {"type": "text", "text": {"bn": "এক সাহাবি প্রতি রাকাতে কিরাত শেষে সূরা ইখলাস পড়তেন। কারণ জিজ্ঞেস করলে বললেন, এতে দয়াময় আল্লাহর গুণাবলি আছে, তাই আমি এটি পড়তে ভালোবাসি। রাসুল ﷺ বললেন: “তাকে জানিয়ে দাও, আল্লাহ তাকে ভালোবাসেন।”", "en": "A Companion ended his recitation in every rak''ah with Al-Ikhlas because it describes the Most Merciful and he loved to recite it. The Prophet ﷺ said: “Tell him that Allah loves him.”"}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৭৩৭৫; সহিহ মুসলিম ৮১৩", "en": "Sahih al-Bukhari 7375; Sahih Muslim 813"}}, {"type": "heading", "text": {"bn": "ঘুমানোর আগে ও সকাল-সন্ধ্যায়", "en": "Before sleep and morning and evening"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ প্রতি রাতে বিছানায় গিয়ে দুই হাত একত্র করে সূরা ইখলাস, ফালাক ও নাস পড়ে তাতে ফুঁ দিতেন, তারপর মাথা ও মুখ থেকে শুরু করে যতটুকু সম্ভব শরীরে হাত বুলাতেন; এভাবে তিনবার করতেন।", "en": "Each night in bed the Prophet ﷺ would cup his hands, recite Al-Ikhlas, Al-Falaq and An-Nas, blow into them and wipe over as much of his body as he could, starting with his head and face, three times."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৫০১৭", "en": "Sahih al-Bukhari 5017"}}, {"type": "text", "text": {"bn": "সকাল ও সন্ধ্যায় তিনবার করে সূরা ইখলাস, ফালাক ও নাস পড়লে তা সব কিছু থেকে রক্ষার জন্য যথেষ্ট হবে।", "en": "Reciting Al-Ikhlas, Al-Falaq and An-Nas three times each morning and evening will suffice you against everything."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ; সুনান তিরমিজি", "en": "Sunan Abi Dawud; Jami'' at-Tirmidhi"}, "check": true}, {"type": "note", "tone": "info", "text": {"bn": "এক-তৃতীয়াংশের সমান হওয়া মানে সওয়াব ও অর্থের দিক থেকে মর্যাদা; এর মানে এই নয় যে তিনবার ইখলাস পড়লে পুরো কুরআন পড়ার প্রয়োজন শেষ।", "en": "Equalling a third of the Quran refers to its rank and reward; it does not mean reading it three times replaces reading the whole Quran."}}]', 'in_review', 90 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '955ab243-2993-5ed5-866c-dc910ac4c77b', id, 'fazilat-ayatul-kursi-baqarah', '{"bn": "আয়াতুল কুরসি ও সূরা বাকারার শেষ দুই আয়াতের ফজিলত", "en": "Virtues of Ayat al-Kursi and the last two verses of Al-Baqarah"}', '{"bn": "কুরআনের সবচেয়ে মহান আয়াত ঘুমের আগে সুরক্ষা দেয়, আর রাতে বাকারার শেষ দুই আয়াত পড়া যথেষ্ট হয়ে যায়।", "en": "The greatest verse of the Quran protects before sleep, and the last two verses of Al-Baqarah suffice whoever recites them at night."}', 'basic', '[{"type": "text", "text": {"bn": "যে ঘরে সূরা বাকারা পড়া হয়, শয়তান সেখান থেকে পালিয়ে যায়; তাই ঘরকে কবরস্থান বানিয়ো না।", "en": "Do not make your houses graveyards; Shaytan flees from a house in which Surah Al-Baqarah is recited."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৭৮০", "en": "Sahih Muslim 780"}}, {"type": "heading", "text": {"bn": "আয়াতুল কুরসি", "en": "Ayat al-Kursi"}}, {"type": "arabic", "label": {"bn": "আয়াতুল কুরসি", "en": "Ayat al-Kursi"}, "ar": "اللّٰهُ لَا إِلٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَهُ مَا فِي السَّمٰوٰتِ وَمَا فِي الْأَرْضِ ۗ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمٰوٰتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ", "pron": {"bn": "আল্লাহু লা ইলাহা ইল্লা হুওয়াল হাইয়্যুল কাইয়ুম। লা তা''খুযুহু সিনাতুঁ ওয়ালা নাওম। লাহু মা ফিস সামাওয়াতি ওয়ামা ফিল আরদ। মান যাল্লাযী ইয়াশফাউ ইনদাহু ইল্লা বিইযনিহ। ইয়া''লামু মা বাইনা আইদীহিম ওয়ামা খালফাহুম। ওয়ালা ইউহীতূনা বিশাইয়িম মিন ইলমিহী ইল্লা বিমা শা-আ। ওয়াসিআ কুরসিয়্যুহুস সামাওয়াতি ওয়াল আরদ। ওয়ালা ইয়াউদুহু হিফযুহুমা, ওয়া হুওয়াল আলিয়্যুল আযীম।", "en": "Allahu la ilaha illa huwal-hayyul-qayyum. La ta''khudhuhu sinatun wa la nawm. Lahu ma fis-samawati wa ma fil-ard. Man dhal-ladhi yashfa''u ''indahu illa bi-idhnih. Ya''lamu ma bayna aydihim wa ma khalfahum. Wa la yuhituna bi-shay''im-min ''ilmihi illa bima sha''. Wasi''a kursiyyuhus-samawati wal-ard. Wa la ya''uduhu hifzuhuma, wa huwal-''aliyyul-''azim."}, "meaning": {"bn": "আল্লাহ, তিনি ছাড়া কোনো সত্য ইলাহ নেই; তিনি চিরঞ্জীব, সবকিছুর ধারক। তন্দ্রা ও নিদ্রা তাঁকে স্পর্শ করে না। আসমান ও জমিনে যা কিছু আছে সব তাঁরই। কে আছে যে তাঁর অনুমতি ছাড়া তাঁর কাছে সুপারিশ করবে? তাদের সামনে ও পেছনে যা আছে সব তিনি জানেন; তিনি যতটুকু চান তার বাইরে তাঁর জ্ঞানের কিছুই তারা আয়ত্ত করতে পারে না। তাঁর কুরসি আসমান ও জমিন পরিব্যাপ্ত; এ দুটির রক্ষণাবেক্ষণ তাঁকে ক্লান্ত করে না। তিনি সমুচ্চ, মহান।", "en": "Allah: there is no god but He, the Ever-Living, the Sustainer of all. Neither drowsiness nor sleep overtakes Him. His is whatever is in the heavens and the earth. Who can intercede with Him except by His permission? He knows what is before them and behind them, and they encompass nothing of His knowledge except what He wills. His Kursi extends over the heavens and the earth, and guarding them does not tire Him. He is the Most High, the Magnificent."}, "ref": {"bn": "সূরা বাকারা ২:২৫৫", "en": "Al-Baqarah 2:255"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ উবাই ইবনে কা''ব (রা.)-কে জিজ্ঞেস করলেন, আল্লাহর কিতাবের কোন আয়াত সবচেয়ে মহান? তিনি বললেন: আয়াতুল কুরসি। রাসুল ﷺ তাঁর বুকে হাত দিয়ে বললেন: “আবুল মুনযির, এই জ্ঞান তোমার জন্য মোবারক হোক।”", "en": "The Prophet ﷺ asked Ubayy ibn Ka''b (RA) which verse of Allah''s Book is greatest. He said: Ayat al-Kursi. The Prophet ﷺ struck his chest and said: “May knowledge be pleasant for you, Abul-Mundhir.”"}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৮১০", "en": "Sahih Muslim 810"}}, {"type": "text", "text": {"bn": "আবু হুরাইরা (রা.)-এর ঘটনায় এসেছে: ঘুমানোর সময় আয়াতুল কুরসি পড়লে সকাল পর্যন্ত আল্লাহর পক্ষ থেকে একজন রক্ষক থাকবে, আর শয়তান কাছে আসতে পারবে না। রাসুল ﷺ বললেন: “সে (শয়তান) মিথ্যুক হলেও এ কথাটি সত্য বলেছে।”", "en": "In the story of Abu Hurairah (RA): whoever recites Ayat al-Kursi when going to bed will have a guardian from Allah and no devil will come near him until morning. The Prophet ﷺ said: “He told you the truth though he is a liar.”"}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ২৩১১", "en": "Sahih al-Bukhari 2311"}}, {"type": "text", "text": {"bn": "প্রত্যেক ফরজ নামাজের পর আয়াতুল কুরসি পড়লে মৃত্যু ছাড়া আর কিছু তাকে জান্নাতে প্রবেশে বাধা দেবে না।", "en": "Whoever recites Ayat al-Kursi after every obligatory prayer, nothing prevents him from entering Paradise except death."}}, {"type": "ref", "text": {"bn": "সুনানুল কুবরা, নাসায়ি", "en": "As-Sunan al-Kubra, an-Nasa''i"}, "check": true}, {"type": "note", "tone": "info", "text": {"bn": "এই শেষ হাদিসটি নাসায়ির “আমালুল ইয়াওমি ওয়াল লাইলা” / “সুনানুল কুবরা”-তে আছে; অনেক মুহাদ্দিস (যেমন আলবানি) একে সহিহ বলেছেন, কেউ কেউ সনদে আপত্তি করেছেন।", "en": "This last hadith is in an-Nasa''i''s ''Amal al-Yawm wal-Laylah / As-Sunan al-Kubra; many hadith scholars (e.g. al-Albani) graded it sahih, while some questioned its chain."}, "check": true}, {"type": "heading", "text": {"bn": "সূরা বাকারার শেষ দুই আয়াত", "en": "The last two verses of Al-Baqarah"}}, {"type": "text", "text": {"bn": "যে রাতে সূরা বাকারার শেষ দুই আয়াত (২৮৫–২৮৬) পড়ে, তার জন্য এ দুটিই যথেষ্ট।", "en": "Whoever recites the last two verses of Surah Al-Baqarah (285–286) at night, they will suffice him."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৫০০৯; সহিহ মুসলিম ৮০৭", "en": "Sahih al-Bukhari 5009; Sahih Muslim 807"}}, {"type": "text", "text": {"bn": "এ দুটি আয়াত সেই দুই নূরের একটি, যা রাসুল ﷺ-এর আগে কোনো নবীকে দেওয়া হয়নি (অন্যটি সূরা ফাতিহা)।", "en": "These verses are one of the two lights given to no prophet before him ﷺ (the other being Al-Fatihah)."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৮০৬", "en": "Sahih Muslim 806"}}, {"type": "text", "text": {"bn": "শেষ আয়াতের প্রতিটি দোয়ার পর আল্লাহ বলেছেন: “আমি তা কবুল করলাম।”", "en": "After each supplication in the final verse, Allah said: “I have done so.”"}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম", "en": "Sahih Muslim"}, "check": true}, {"type": "note", "tone": "info", "text": {"bn": "“যথেষ্ট” শব্দের ব্যাখ্যায় আলেমরা বলেছেন: রাতের নফল নামাজের জন্য যথেষ্ট, অথবা সব অনিষ্ট থেকে রক্ষার জন্য যথেষ্ট; দুটো অর্থই হতে পারে।", "en": "Scholars explain “suffice” as sufficing for night prayer, or protecting from all harm; both meanings are possible."}}]', 'in_review', 100 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '864720a8-ae13-5381-b0ff-7df25921cbfd', id, 'fazilat-surah-mulk', '{"bn": "সূরা মুলকের ফজিলত", "en": "Virtues of Surah Al-Mulk"}', '{"bn": "ত্রিশ আয়াতের এই সূরা তার পাঠকের জন্য সুপারিশ করে, এবং রাসুল ﷺ রাতে এটি না পড়ে ঘুমাতেন না।", "en": "This thirty-verse surah intercedes for its reciter, and the Prophet ﷺ would not sleep without reciting it."}', 'basic', '[{"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: কুরআনে ত্রিশ আয়াতের একটি সূরা আছে, যা এক ব্যক্তির জন্য সুপারিশ করেছিল, শেষে তাকে ক্ষমা করে দেওয়া হয়েছে। সেটি হলো “তাবারাকাল্লাযী বিয়াদিহিল মুলক”।", "en": "There is a surah in the Quran of thirty verses that interceded for a man until he was forgiven: “Tabarakal-ladhi biyadihil-mulk.”"}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি ২৮৯১; সুনান আবু দাউদ ১৪০০", "en": "Jami'' at-Tirmidhi 2891; Sunan Abi Dawud 1400"}}, {"type": "note", "tone": "info", "text": {"bn": "ইমাম তিরমিজি এই হাদিসকে হাসান বলেছেন।", "en": "Imam at-Tirmidhi graded this hadith hasan."}}, {"type": "text", "text": {"bn": "জাবির (রা.) বলেন: রাসুল ﷺ সূরা আলিফ-লাম-মীম সাজদা ও সূরা মুলক না পড়ে ঘুমাতেন না।", "en": "Jabir (RA) said: the Prophet ﷺ would not sleep until he had recited Alif-Lam-Mim As-Sajdah and Al-Mulk."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি", "en": "Jami'' at-Tirmidhi"}, "check": true}, {"type": "text", "text": {"bn": "আবদুল্লাহ ইবনে মাসউদ (রা.) থেকে বর্ণিত: সূরা মুলক কবরের আজাব থেকে রক্ষাকারী।", "en": "From Abdullah ibn Mas''ud (RA): Surah Al-Mulk is the protector from the punishment of the grave."}}, {"type": "ref", "text": {"bn": "সুনানুল কুবরা, নাসায়ি; মুস্তাদরাক হাকিম", "en": "As-Sunan al-Kubra, an-Nasa''i; Al-Mustadrak, al-Hakim"}, "check": true}, {"type": "note", "tone": "info", "text": {"bn": "শেষ বর্ণনাটি অনেক মুহাদ্দিস হাসান বলেছেন; এটি ইবনে মাসউদ (রা.)-এর কথা হিসেবে এসেছে, কোনো কোনো সূত্রে রাসুল ﷺ-এর কথা হিসেবে।", "en": "Many scholars graded the last report hasan; it comes as the words of Ibn Mas''ud (RA), and in some routes from the Prophet ﷺ."}, "check": true}, {"type": "note", "tone": "tip", "text": {"bn": "প্রতি রাতে এশার পর বা ঘুমানোর আগে সূরা মুলক পড়ার অভ্যাস করুন; মুখস্থ না থাকলে দেখে পড়ুন।", "en": "Make a habit of reciting Al-Mulk after Isha or before sleep; read from the mushaf if you have not memorised it."}}]', 'in_review', 110 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '6373ee4d-21ba-5de5-9986-c58bfec6a270', id, 'fazilat-surah-kahf', '{"bn": "সূরা কাহফ ও জুমার দিনে পড়ার ফজিলত", "en": "Surah Al-Kahf and reciting it on Friday"}', '{"bn": "সূরা কাহফের প্রথম দশ আয়াত দাজ্জাল থেকে রক্ষা করে, আর জুমার দিনে পড়লে দুই জুমার মাঝে নূর পাওয়া যায়।", "en": "The first ten verses of Al-Kahf protect from the Dajjal, and reciting it on Friday brings light between two Fridays."}', 'basic', '[{"type": "text", "text": {"bn": "যে সূরা কাহফের প্রথম দশ আয়াত মুখস্থ করবে, সে দাজ্জালের ফিতনা থেকে রক্ষা পাবে।", "en": "Whoever memorises the first ten verses of Surah Al-Kahf will be protected from the Dajjal."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৮০৯", "en": "Sahih Muslim 809"}}, {"type": "note", "tone": "info", "text": {"bn": "একই হাদিসের এক বর্ণনায় “শেষ দশ আয়াত” এসেছে; তাই আলেমরা প্রথম ও শেষ দুই দশ আয়াতই মুখস্থ করার পরামর্শ দেন।", "en": "One narration of the same hadith says “the last ten verses,” so scholars advise memorising both the first and last ten."}}, {"type": "heading", "text": {"bn": "জুমার দিনে সূরা কাহফ", "en": "Al-Kahf on Friday"}}, {"type": "text", "text": {"bn": "আবু সাঈদ খুদরি (রা.) থেকে বর্ণিত: যে জুমার দিন সূরা কাহফ পড়ে, তার জন্য দুই জুমার মাঝখানের সময় নূর দিয়ে আলোকিত করে দেওয়া হয়।", "en": "From Abu Sa''id al-Khudri (RA): whoever recites Surah Al-Kahf on Friday, light will shine for him between the two Fridays."}}, {"type": "ref", "text": {"bn": "মুস্তাদরাক হাকিম; শুআবুল ঈমান / সুনানুল কুবরা, বায়হাকি", "en": "Al-Mustadrak, al-Hakim; Shu''ab al-Iman / As-Sunan al-Kubra, al-Bayhaqi"}, "check": true}, {"type": "note", "tone": "info", "text": {"bn": "এই বর্ণনাকে আলবানিসহ অনেক মুহাদ্দিস সহিহ বলেছেন। কেউ কেউ বলেন এটি মূলত আবু সাঈদ (রা.)-এর কথা (মাওকুফ); তবে এমন বিষয় সাহাবি নিজে থেকে বলেন না, তাই এর হুকুম রাসুল ﷺ-এর কথার মতো বলে তাঁরা মনে করেন।", "en": "Many hadith scholars, including al-Albani, graded this sahih. Some say it is the words of Abu Sa''id (mawquf), but since a Companion would not say this from opinion, it carries the ruling of the Prophet''s ﷺ words."}, "check": true}, {"type": "note", "tone": "tip", "text": {"bn": "জুমার দিন শুরু হয় বৃহস্পতিবার সূর্যাস্তের পর থেকে এবং শেষ হয় শুক্রবার সূর্যাস্তে; এর মধ্যে যেকোনো সময় পড়া যায়।", "en": "Friday runs from sunset on Thursday to sunset on Friday; you may recite it any time in between."}}]', 'in_review', 120 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'da43853e-499e-52df-816c-5f55bf6fb100', id, 'fazilat-tasbih', '{"bn": "সুবহানাল্লাহ ও অন্যান্য তাসবিহের ফজিলত", "en": "Virtues of SubhanAllah and other tasbih"}', '{"bn": "জিহ্বায় হালকা কিন্তু মিজানে ভারী দুটি বাক্য, দিনে একশ বার তাসবিহ এবং নামাজের পরের তাসবিহের ফজিলত।", "en": "Two phrases light on the tongue but heavy on the scale, a hundred tasbih a day, and the dhikr after prayer."}', 'basic', '[{"type": "arabic", "label": {"bn": "দিনে ১০০ বার", "en": "100 times a day"}, "ar": "سُبْحَانَ اللّٰهِ وَبِحَمْدِهِ", "pron": {"bn": "সুবহানাল্লাহি ওয়া বিহামদিহী", "en": "Subhanallahi wa bihamdihi"}, "meaning": {"bn": "আল্লাহ পবিত্র, আর সব প্রশংসা তাঁরই।", "en": "Glory be to Allah and praise be to Him."}, "ref": {"bn": "সহিহ বুখারি ৬৪০৫", "en": "Sahih al-Bukhari 6405"}}, {"type": "text", "text": {"bn": "যে দিনে একশ বার “সুবহানাল্লাহি ওয়া বিহামদিহী” বলে, তার গুনাহ সমুদ্রের ফেনার সমান হলেও মাফ করে দেওয়া হয়।", "en": "Whoever says “Subhanallahi wa bihamdihi” a hundred times a day, his sins are forgiven even if they are like the foam of the sea."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৬৪০৫; সহিহ মুসলিম ২৬৯১", "en": "Sahih al-Bukhari 6405; Sahih Muslim 2691"}}, {"type": "arabic", "ar": "سُبْحَانَ اللّٰهِ وَبِحَمْدِهِ، سُبْحَانَ اللّٰهِ الْعَظِيمِ", "pron": {"bn": "সুবহানাল্লাহি ওয়া বিহামদিহী, সুবহানাল্লাহিল আযীম", "en": "Subhanallahi wa bihamdihi, subhanallahil-''azim"}, "meaning": {"bn": "আল্লাহ পবিত্র ও সব প্রশংসা তাঁর; মহান আল্লাহ পবিত্র।", "en": "Glory be to Allah and praise be to Him; glory be to Allah the Magnificent."}, "ref": {"bn": "সহিহ বুখারি ৭৫৬৩", "en": "Sahih al-Bukhari 7563"}}, {"type": "text", "text": {"bn": "দুটি বাক্য জিহ্বায় হালকা, মিজানে ভারী এবং দয়াময় আল্লাহর কাছে প্রিয়: “সুবহানাল্লাহি ওয়া বিহামদিহী, সুবহানাল্লাহিল আযীম।” (এটি সহিহ বুখারির সর্বশেষ হাদিস।)", "en": "Two phrases are light on the tongue, heavy on the scale and beloved to the Most Merciful: “Subhanallahi wa bihamdihi, subhanallahil-''azim.” (It is the last hadith in Sahih al-Bukhari.)"}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৭৫৬৩; সহিহ মুসলিম ২৬৯৪", "en": "Sahih al-Bukhari 7563; Sahih Muslim 2694"}}, {"type": "heading", "text": {"bn": "চারটি প্রিয় বাক্য", "en": "Four beloved phrases"}}, {"type": "arabic", "ar": "سُبْحَانَ اللّٰهِ، وَالْحَمْدُ لِلّٰهِ، وَلَا إِلٰهَ إِلَّا اللّٰهُ، وَاللّٰهُ أَكْبَرُ", "pron": {"bn": "সুবহানাল্লাহ, ওয়াল হামদুলিল্লাহ, ওয়া লা ইলাহা ইল্লাল্লাহু, ওয়াল্লাহু আকবার", "en": "Subhanallah, wal-hamdu lillah, wa la ilaha illallah, wallahu akbar"}, "meaning": {"bn": "আল্লাহ পবিত্র, সব প্রশংসা আল্লাহর, আল্লাহ ছাড়া কোনো সত্য ইলাহ নেই, আল্লাহ সর্বশ্রেষ্ঠ।", "en": "Glory be to Allah, praise be to Allah, there is no god but Allah, Allah is the Greatest."}, "ref": {"bn": "সহিহ মুসলিম ২১৩৭", "en": "Sahih Muslim 2137"}}, {"type": "text", "text": {"bn": "আল্লাহর কাছে সবচেয়ে প্রিয় বাক্য এই চারটি; যেটি দিয়েই শুরু করো, কোনো ক্ষতি নেই। রাসুল ﷺ বলেছেন, এগুলো বলা আমার কাছে সূর্য যা কিছুর ওপর উদিত হয় তার চেয়েও প্রিয়।", "en": "These four are the most beloved words to Allah, in any order. The Prophet ﷺ said saying them is dearer to him than all the sun rises upon."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২১৩৭; সহিহ মুসলিম ২৬৯৫", "en": "Sahih Muslim 2137; Sahih Muslim 2695"}}, {"type": "text", "text": {"bn": "“আলহামদুলিল্লাহ” মিজান পূর্ণ করে দেয়, আর “সুবহানাল্লাহ ওয়াল হামদুলিল্লাহ” আসমান-জমিনের মাঝখান পূর্ণ করে দেয়।", "en": "“Al-hamdu lillah” fills the scale, and “Subhanallah wal-hamdu lillah” fill what is between the heavens and the earth."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২২৩", "en": "Sahih Muslim 223"}}, {"type": "arabic", "label": {"bn": "জান্নাতের গুপ্তধন", "en": "A treasure of Paradise"}, "ar": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللّٰهِ", "pron": {"bn": "লা হাওলা ওয়ালা কুওয়াতা ইল্লা বিল্লাহ", "en": "La hawla wa la quwwata illa billah"}, "meaning": {"bn": "আল্লাহর সাহায্য ছাড়া কোনো উপায় ও শক্তি নেই।", "en": "There is no might nor power except with Allah."}, "ref": {"bn": "সহিহ বুখারি ৪২০৫; সহিহ মুসলিম ২৭০৪", "en": "Sahih al-Bukhari 4205; Sahih Muslim 2704"}}, {"type": "heading", "text": {"bn": "নামাজের পর তাসবিহ", "en": "Tasbih after prayer"}}, {"type": "text", "text": {"bn": "যে প্রত্যেক নামাজের পর ৩৩ বার সুবহানাল্লাহ, ৩৩ বার আলহামদুলিল্লাহ, ৩৩ বার আল্লাহু আকবার বলে, আর একশ পূর্ণ করতে বলে “লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারীকা লাহু, লাহুল মুলকু ওয়া লাহুল হামদু ওয়া হুওয়া আলা কুল্লি শাইয়িন কাদীর”, তার গুনাহ সমুদ্রের ফেনার সমান হলেও মাফ হয়ে যায়।", "en": "Whoever after every prayer says SubhanAllah 33 times, Alhamdulillah 33 times, Allahu Akbar 33 times, and completes the hundred with “La ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamdu wa huwa ''ala kulli shay''in qadir,” his sins are forgiven even if like the foam of the sea."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৫৯৭", "en": "Sahih Muslim 597"}}]', 'in_review', 130 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '1e79f9f5-ca00-526b-8c5b-d781d29aa233', id, 'fazilat-la-ilaha-illallah', '{"bn": "লা ইলাহা ইল্লাল্লাহর ফজিলত", "en": "Virtues of La ilaha illallah"}', '{"bn": "সর্বোত্তম জিকির “লা ইলাহা ইল্লাল্লাহ”; দিনে একশ বার তাহলিলের বিরাট সওয়াব এবং শেষ কথা হিসেবে এর মর্যাদা।", "en": "The best dhikr is “La ilaha illallah”; the great reward of saying the tahlil a hundred times a day, and its worth as one''s last words."}', 'basic', '[{"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: সর্বোত্তম জিকির “লা ইলাহা ইল্লাল্লাহ”, আর সর্বোত্তম দোয়া “আলহামদুলিল্লাহ”।", "en": "The best remembrance is “La ilaha illallah,” and the best supplication is “Al-hamdu lillah.”"}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি ৩৩৮৩", "en": "Jami'' at-Tirmidhi 3383"}}, {"type": "text", "text": {"bn": "ঈমানের সত্তরের বেশি শাখা আছে; এর সর্বোচ্চটি “লা ইলাহা ইল্লাল্লাহ” বলা।", "en": "Faith has seventy-odd branches; the highest is saying “La ilaha illallah.”"}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৩৫", "en": "Sahih Muslim 35"}}, {"type": "arabic", "label": {"bn": "দিনে ১০০ বার", "en": "100 times a day"}, "ar": "لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلٰى كُلِّ شَيْءٍ قَدِيرٌ", "pron": {"bn": "লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারীকা লাহু, লাহুল মুলকু ওয়া লাহুল হামদু, ওয়া হুওয়া আলা কুল্লি শাইয়িন কাদীর", "en": "La ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamd, wa huwa ''ala kulli shay''in qadir"}, "meaning": {"bn": "আল্লাহ ছাড়া কোনো সত্য ইলাহ নেই, তিনি এক, তাঁর কোনো শরিক নেই; রাজত্ব তাঁরই, প্রশংসাও তাঁর, আর তিনি সবকিছুর ওপর ক্ষমতাবান।", "en": "There is no god but Allah alone, without partner; His is the dominion and His is the praise, and He has power over all things."}, "ref": {"bn": "সহিহ বুখারি ৩২৯৩; সহিহ মুসলিম ২৬৯১", "en": "Sahih al-Bukhari 3293; Sahih Muslim 2691"}}, {"type": "text", "text": {"bn": "যে দিনে একশ বার এটি বলে, সে দশটি গোলাম আজাদ করার সমান সওয়াব পায়, তার জন্য একশ নেকি লেখা হয়, একশ গুনাহ মুছে দেওয়া হয়, আর সেদিন সন্ধ্যা পর্যন্ত সে শয়তান থেকে সুরক্ষিত থাকে। এর চেয়ে বেশি আমলকারী ছাড়া কেউ তার চেয়ে উত্তম আমল নিয়ে আসবে না।", "en": "Whoever says it a hundred times a day gets the reward of freeing ten slaves, a hundred good deeds are written for him, a hundred sins erased, and he is protected from Shaytan that day until evening; no one brings better except one who did more."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৩২৯৩; সহিহ মুসলিম ২৬৯১", "en": "Sahih al-Bukhari 3293; Sahih Muslim 2691"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: কিয়ামতের দিন আমার শাফায়াতের সবচেয়ে সৌভাগ্যবান সে, যে অন্তর থেকে একনিষ্ঠভাবে “লা ইলাহা ইল্লাল্লাহ” বলেছে।", "en": "The happiest of people with my intercession on the Day of Resurrection is the one who said “La ilaha illallah” sincerely from his heart."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৯৯", "en": "Sahih al-Bukhari 99"}}, {"type": "text", "text": {"bn": "যার শেষ কথা “লা ইলাহা ইল্লাল্লাহ” হবে, সে জান্নাতে প্রবেশ করবে।", "en": "Whoever''s last words are “La ilaha illallah” will enter Paradise."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ ৩১১৬", "en": "Sunan Abi Dawud 3116"}}, {"type": "note", "tone": "tip", "text": {"bn": "মুমূর্ষু ব্যক্তির পাশে নরমভাবে কালিমা পড়ুন যাতে তিনি শুনে বলতে পারেন; তাঁকে জোর করে বারবার বলতে বলবেন না।", "en": "Beside a dying person, gently say the kalimah so they can hear and repeat it; do not press them repeatedly."}}]', 'in_review', 140 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '19e3d083-2e81-5164-b14a-22e6b810042a', id, 'fazilat-istighfar', '{"bn": "ইস্তিগফার ও সাইয়িদুল ইস্তিগফারের ফজিলত", "en": "Virtues of istighfar and Sayyid al-Istighfar"}', '{"bn": "রাসুল ﷺ নিজে দিনে সত্তর-একশ বার ইস্তিগফার করতেন; সাইয়িদুল ইস্তিগফার দৃঢ় বিশ্বাসে পড়ে মারা গেলে জান্নাত।", "en": "The Prophet ﷺ himself sought forgiveness seventy to a hundred times a day; whoever says Sayyid al-Istighfar with certainty and dies that day enters Paradise."}', 'basic', '[{"type": "text", "text": {"bn": "নূহ (আ.) তাঁর জাতিকে বলেছিলেন: “তোমাদের রবের কাছে ক্ষমা চাও, নিশ্চয়ই তিনি মহাক্ষমাশীল। তিনি তোমাদের ওপর প্রচুর বৃষ্টি পাঠাবেন, ধন-সম্পদ ও সন্তান দিয়ে সাহায্য করবেন, তোমাদের জন্য বাগান ও নদী দেবেন।”", "en": "Nuh (AS) told his people: “Ask forgiveness of your Lord; He is ever Forgiving. He will send rain upon you in abundance, give you wealth and children, and provide for you gardens and rivers.”"}}, {"type": "ref", "text": {"bn": "সূরা নূহ ৭১:১০–১২", "en": "Nuh 71:10–12"}}, {"type": "arabic", "ar": "أَسْتَغْفِرُ اللّٰهَ وَأَتُوبُ إِلَيْهِ", "pron": {"bn": "আস্তাগফিরুল্লাহা ওয়া আতূবু ইলাইহি", "en": "Astaghfirullaha wa atubu ilayh"}, "meaning": {"bn": "আমি আল্লাহর কাছে ক্ষমা চাই এবং তাঁর কাছে তওবা করি।", "en": "I seek Allah''s forgiveness and turn to Him in repentance."}, "ref": {"bn": "সহিহ বুখারি ৬৩০৭", "en": "Sahih al-Bukhari 6307"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: আল্লাহর কসম, আমি দিনে সত্তর বারের বেশি আল্লাহর কাছে ক্ষমা চাই ও তওবা করি। অন্য বর্ণনায়: হে লোকসকল, আল্লাহর কাছে তওবা করো; আমি দিনে একশ বার তওবা করি।", "en": "By Allah, I seek Allah''s forgiveness and repent to Him more than seventy times a day. In another narration: O people, repent to Allah, for I repent a hundred times a day."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৬৩০৭; সহিহ মুসলিম ২৭০২", "en": "Sahih al-Bukhari 6307; Sahih Muslim 2702"}}, {"type": "text", "text": {"bn": "যাঁর হাতে আমার প্রাণ, তাঁর কসম, তোমরা যদি গুনাহ না করতে, আল্লাহ তোমাদের সরিয়ে এমন জাতি আনতেন যারা গুনাহ করে আল্লাহর কাছে ক্ষমা চাইত, আর তিনি তাদের ক্ষমা করতেন।", "en": "By Him in whose hand is my soul, if you did not sin, Allah would replace you with people who sin and then seek His forgiveness, and He would forgive them."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৭৪৯", "en": "Sahih Muslim 2749"}}, {"type": "heading", "text": {"bn": "সাইয়িদুল ইস্তিগফার", "en": "Sayyid al-Istighfar"}}, {"type": "arabic", "label": {"bn": "সাইয়িদুল ইস্তিগফার", "en": "Sayyid al-Istighfar"}, "ar": "اللّٰهُمَّ أَنْتَ رَبِّي لَا إِلٰهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلٰى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ لَكَ بِذَنْبِي، فَاغْفِرْ لِي، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ", "pron": {"bn": "আল্লাহুম্মা আনতা রব্বী, লা ইলাহা ইল্লা আনতা, খালাকতানী ওয়া আনা আবদুকা, ওয়া আনা আলা আহদিকা ওয়া ওয়া''দিকা মাসতাতা''তু, আউযু বিকা মিন শাররি মা সানা''তু, আবূউ লাকা বিনি''মাতিকা আলাইয়্যা, ওয়া আবূউ লাকা বিযামবী, ফাগফির লী, ফাইন্নাহু লা ইয়াগফিরুয যুনূবা ইল্লা আনতা", "en": "Allahumma anta rabbi, la ilaha illa ant, khalaqtani wa ana ''abduk, wa ana ''ala ''ahdika wa wa''dika mastata''t, a''udhu bika min sharri ma sana''t, abu''u laka bi-ni''matika ''alayy, wa abu''u laka bi-dhanbi, faghfir li, fa-innahu la yaghfirudh-dhunuba illa ant"}, "meaning": {"bn": "হে আল্লাহ, আপনি আমার রব, আপনি ছাড়া কোনো সত্য ইলাহ নেই। আপনি আমাকে সৃষ্টি করেছেন, আমি আপনার বান্দা। আমি সাধ্যমতো আপনার সঙ্গে করা অঙ্গীকার ও ওয়াদার ওপর আছি। আমার কৃতকর্মের অনিষ্ট থেকে আপনার আশ্রয় চাই। আমার ওপর আপনার নিয়ামত স্বীকার করছি এবং আমার গুনাহও স্বীকার করছি। আমাকে ক্ষমা করুন, কারণ আপনি ছাড়া কেউ গুনাহ ক্ষমা করতে পারে না।", "en": "O Allah, You are my Lord; there is no god but You. You created me and I am Your servant, and I keep Your covenant and promise as best I can. I seek refuge in You from the evil of what I have done. I acknowledge Your favour upon me and I acknowledge my sin, so forgive me, for none forgives sins but You."}, "ref": {"bn": "সহিহ বুখারি ৬৩০৬", "en": "Sahih al-Bukhari 6306"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: যে দৃঢ় বিশ্বাসের সঙ্গে দিনের বেলা এটি পড়ে সন্ধ্যার আগে মারা যায়, সে জান্নাতি; আর যে রাতে দৃঢ় বিশ্বাসের সঙ্গে পড়ে সকালের আগে মারা যায়, সেও জান্নাতি।", "en": "Whoever says it during the day with firm faith and dies before evening is among the people of Paradise; and whoever says it at night with firm faith and dies before morning is among the people of Paradise."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৬৩০৬", "en": "Sahih al-Bukhari 6306"}}, {"type": "note", "tone": "warn", "text": {"bn": "“যে নিয়মিত ইস্তিগফার করে, আল্লাহ তাকে সব সংকট থেকে মুক্তির পথ ও অপ্রত্যাশিত রিজিক দেন” — এই প্রসিদ্ধ হাদিসটি সুনান আবু দাউদে আছে, তবে বর্ণনাকারী অজ্ঞাত হওয়ায় অনেক মুহাদ্দিস একে দুর্বল বলেছেন। ইস্তিগফারের বরকতের জন্য সূরা নূহের আয়াতগুলোই যথেষ্ট প্রমাণ।", "en": "The popular hadith “whoever holds to istighfar, Allah gives him a way out of every distress and provision from where he does not expect” is in Sunan Abi Dawud, but many scholars graded it weak due to an unknown narrator. The verses of Surah Nuh are sufficient evidence for the blessings of istighfar."}, "check": true}]', 'in_review', 150 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'bc8af39e-1d50-5c5b-9303-e4539ae3f690', id, 'fazilat-durood', '{"bn": "রাসুল ﷺ-এর ওপর দরুদ পড়ার ফজিলত", "en": "Virtues of sending salawat on the Prophet ﷺ"}', '{"bn": "একবার দরুদ পড়লে আল্লাহ দশটি রহমত পাঠান; সহিহ হাদিসে শেখানো দরুদ এবং ভিত্তিহীন দরুদ সম্পর্কে সতর্কতা।", "en": "One salawat brings ten blessings from Allah; the salawat taught in sahih hadith, and a caution about baseless ones."}', 'basic', '[{"type": "arabic", "ar": "إِنَّ اللّٰهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ ۚ يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا", "pron": {"bn": "ইন্নাল্লাহা ওয়া মালাইকাতাহু ইউসাল্লূনা আলান নাবিয়্যি, ইয়া আইয়্যুহাল্লাযীনা আমানূ সাল্লূ আলাইহি ওয়া সাল্লিমূ তাসলীমা", "en": "Innallaha wa mala''ikatahu yusalluna ''alan-nabiyy, ya ayyuhal-ladhina amanu sallu ''alayhi wa sallimu taslima"}, "meaning": {"bn": "নিশ্চয়ই আল্লাহ ও তাঁর ফেরেশতারা নবীর ওপর রহমত পাঠান। হে মুমিনগণ, তোমরাও তাঁর ওপর দরুদ পাঠাও এবং যথাযথভাবে সালাম পাঠাও।", "en": "Indeed, Allah and His angels send blessings upon the Prophet. O you who believe, send blessings upon him and greet him with peace."}, "ref": {"bn": "সূরা আহযাব ৩৩:৫৬", "en": "Al-Ahzab 33:56"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: যে আমার ওপর একবার দরুদ পড়ে, আল্লাহ তার ওপর দশবার রহমত নাজিল করেন।", "en": "Whoever sends blessings on me once, Allah sends blessings on him ten times."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৪০৮", "en": "Sahih Muslim 408"}}, {"type": "text", "text": {"bn": "অন্য বর্ণনায় আছে: তার দশটি গুনাহ মাফ হয় এবং দশটি মর্যাদা বাড়ানো হয়।", "en": "Another narration adds: ten sins are erased from him and he is raised ten degrees."}}, {"type": "ref", "text": {"bn": "সুনান নাসায়ি", "en": "Sunan an-Nasa''i"}, "check": true}, {"type": "text", "text": {"bn": "প্রকৃত কৃপণ সেই ব্যক্তি, যার সামনে আমার নাম উল্লেখ করা হলো অথচ সে আমার ওপর দরুদ পড়ল না।", "en": "The true miser is the one in whose presence I am mentioned and he does not send blessings on me."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি", "en": "Jami'' at-Tirmidhi"}, "check": true}, {"type": "heading", "text": {"bn": "দরুদে ইবরাহিমি", "en": "The Ibrahimi salawat"}}, {"type": "arabic", "label": {"bn": "সাহাবিদের শেখানো দরুদ", "en": "The salawat taught to the Companions"}, "ar": "اللّٰهُمَّ صَلِّ عَلٰى مُحَمَّدٍ وَعَلٰى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلٰى إِبْرَاهِيمَ وَعَلٰى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ، اللّٰهُمَّ بَارِكْ عَلٰى مُحَمَّدٍ وَعَلٰى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلٰى إِبْرَاهِيمَ وَعَلٰى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ", "pron": {"bn": "আল্লাহুম্মা সাল্লি আলা মুহাম্মাদিওঁ ওয়া আলা আলি মুহাম্মাদ, কামা সাল্লাইতা আলা ইবরাহীমা ওয়া আলা আলি ইবরাহীম, ইন্নাকা হামীদুম মাজীদ। আল্লাহুম্মা বারিক আলা মুহাম্মাদিওঁ ওয়া আলা আলি মুহাম্মাদ, কামা বারাকতা আলা ইবরাহীমা ওয়া আলা আলি ইবরাহীম, ইন্নাকা হামীদুম মাজীদ।", "en": "Allahumma salli ''ala Muhammadin wa ''ala ali Muhammad, kama sallayta ''ala Ibrahima wa ''ala ali Ibrahim, innaka Hamidun Majid. Allahumma barik ''ala Muhammadin wa ''ala ali Muhammad, kama barakta ''ala Ibrahima wa ''ala ali Ibrahim, innaka Hamidun Majid."}, "meaning": {"bn": "হে আল্লাহ, মুহাম্মাদ ও তাঁর পরিবারের ওপর রহমত পাঠান, যেমন আপনি ইবরাহিম ও তাঁর পরিবারের ওপর রহমত পাঠিয়েছেন; নিশ্চয়ই আপনি প্রশংসিত, মহিমান্বিত। হে আল্লাহ, মুহাম্মাদ ও তাঁর পরিবারের ওপর বরকত দিন, যেমন আপনি ইবরাহিম ও তাঁর পরিবারের ওপর বরকত দিয়েছেন; নিশ্চয়ই আপনি প্রশংসিত, মহিমান্বিত।", "en": "O Allah, send blessings on Muhammad and the family of Muhammad as You sent blessings on Ibrahim and the family of Ibrahim; You are Praiseworthy, Glorious. O Allah, bless Muhammad and the family of Muhammad as You blessed Ibrahim and the family of Ibrahim; You are Praiseworthy, Glorious."}, "ref": {"bn": "সহিহ বুখারি ৩৩৭০", "en": "Sahih al-Bukhari 3370"}}, {"type": "text", "text": {"bn": "সাহাবিরা জিজ্ঞেস করেছিলেন, আমরা আপনার ওপর কীভাবে দরুদ পড়ব? তখন রাসুল ﷺ এই দরুদ শিখিয়ে দেন। তাই এটিই সর্বোত্তম দরুদ; ছোট করে “সাল্লাল্লাহু আলাইহি ওয়া সাল্লাম” বলাও দরুদ।", "en": "The Companions asked how to send blessings on him, and he ﷺ taught them this; so it is the best form. Saying “sallallahu ''alayhi wa sallam” briefly is also salawat."}}, {"type": "note", "tone": "warn", "text": {"bn": "বিভিন্ন পুস্তিকায় নির্দিষ্ট নামের দরুদের জন্য অস্বাভাবিক ফজিলত লেখা থাকে (যেমন: একবার পড়লে লাখ দরুদের সওয়াব)। এ ধরনের বেশিরভাগ ফজিলতের কোনো নির্ভরযোগ্য সনদ নেই। সহিহ হাদিসে শেখানো দরুদই যথেষ্ট ও উত্তম।", "en": "Some booklets attach extraordinary rewards to specially named salawat (e.g. “one recitation equals a hundred thousand”). Most of these have no reliable chain. The salawat taught in sahih hadith is sufficient and best."}}, {"type": "note", "tone": "tip", "text": {"bn": "জুমার দিনে বেশি বেশি দরুদ পড়ার বিশেষ নির্দেশ আছে; জুমার গাইড দেখুন।", "en": "There is a special instruction to increase salawat on Friday; see the Friday guide."}}]', 'in_review', 160 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'cfce21f4-237e-53c6-85f3-295d51ab4f22', id, 'fazilat-dua', '{"bn": "দোয়ার ফজিলত ও কবুলের সময়", "en": "Virtues of dua and times of acceptance"}', '{"bn": "দোয়াই ইবাদত; আল্লাহ নিকটে আছেন এবং সাড়া দেন। কোন কোন সময় দোয়া কবুলের বেশি আশা করা যায়।", "en": "Dua is worship; Allah is near and answers. The times when dua is most hoped to be accepted."}', 'basic', '[{"type": "arabic", "ar": "وَقَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ", "pron": {"bn": "ওয়া কালা রব্বুকুমুদ''ঊনী আসতাজিব লাকুম", "en": "Wa qala rabbukumud''uni astajib lakum"}, "meaning": {"bn": "তোমাদের রব বলেছেন: তোমরা আমাকে ডাকো, আমি তোমাদের ডাকে সাড়া দেব।", "en": "Your Lord has said: Call upon Me; I will respond to you."}, "ref": {"bn": "সূরা গাফির ৪০:৬০", "en": "Ghafir 40:60"}}, {"type": "text", "text": {"bn": "আল্লাহ বলেন: “আমার বান্দারা যখন তোমাকে আমার সম্পর্কে জিজ্ঞেস করে, (বলো) আমি নিকটেই আছি; আহ্বানকারী যখন আমাকে ডাকে, আমি তার ডাকে সাড়া দিই।”", "en": "Allah says: “When My servants ask you about Me, I am near; I respond to the call of the caller when he calls on Me.”"}}, {"type": "ref", "text": {"bn": "সূরা বাকারা ২:১৮৬", "en": "Al-Baqarah 2:186"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: “দোয়াই ইবাদত।” তারপর তিনি উপরের আয়াতটি (৪০:৬০) পড়লেন।", "en": "The Prophet ﷺ said: “Supplication is worship,” then recited the verse above (40:60)."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ ১৪৭৯; সুনান তিরমিজি ২৯৬৯", "en": "Sunan Abi Dawud 1479; Jami'' at-Tirmidhi 2969"}}, {"type": "note", "tone": "info", "text": {"bn": "প্রচলিত বাক্য “দোয়া ইবাদতের মগজ (সার)” তিরমিজিতে এসেছে, কিন্তু এর সনদ দুর্বল; সহিহ শব্দ হলো “দোয়াই ইবাদত”।", "en": "The popular wording “dua is the marrow of worship” is in Tirmidhi but its chain is weak; the sahih wording is “dua is worship.”"}, "check": true}, {"type": "text", "text": {"bn": "কোনো মুসলিম যখন গুনাহ বা আত্মীয়তা ছিন্ন করার দোয়া ছাড়া অন্য কোনো দোয়া করে, আল্লাহ তাকে তিনটির একটি দেন: দ্রুত দোয়া কবুল করেন, অথবা আখিরাতের জন্য জমা রাখেন, অথবা সমপরিমাণ কোনো বিপদ দূর করে দেন।", "en": "Whenever a Muslim makes a dua that involves no sin or cutting of kinship, Allah gives him one of three: an answer soon, a reward stored for the Hereafter, or an equal harm turned away from him."}}, {"type": "ref", "text": {"bn": "মুসনাদ আহমাদ", "en": "Musnad Ahmad"}, "check": true}, {"type": "text", "text": {"bn": "তোমাদের দোয়া কবুল হয়, যতক্ষণ না কেউ তাড়াহুড়া করে বলে: “আমি দোয়া করলাম, কিন্তু কবুল হলো না।”", "en": "Your dua is answered as long as you are not hasty, saying: “I prayed but was not answered.”"}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৬৩৪০; সহিহ মুসলিম ২৭৩৫", "en": "Sahih al-Bukhari 6340; Sahih Muslim 2735"}}, {"type": "text", "text": {"bn": "কোনো মুসলিম তার ভাইয়ের অনুপস্থিতিতে তার জন্য দোয়া করলে একজন ফেরেশতা বলেন: “আমিন, আর তোমার জন্যও তেমনই হোক।”", "en": "When a Muslim prays for his brother in his absence, an angel says: “Amin, and for you the same.”"}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৭৩৩", "en": "Sahih Muslim 2733"}}, {"type": "heading", "text": {"bn": "দোয়া কবুলের বিশেষ সময়", "en": "Special times of acceptance"}}, {"type": "list", "items": [{"bn": "রাতের শেষ তৃতীয়াংশ (সহিহ বুখারি ১১৪৫)", "en": "The last third of the night (Sahih al-Bukhari 1145)"}, {"bn": "সিজদারত অবস্থায়; বান্দা সিজদায় রবের সবচেয়ে নিকটে থাকে (সহিহ মুসলিম ৪৮২)", "en": "In sujood; the servant is closest to his Lord in prostration (Sahih Muslim 482)"}, {"bn": "জুমার দিনের বিশেষ মুহূর্ত (সহিহ বুখারি ৯৩৫)", "en": "The special hour on Friday (Sahih al-Bukhari 935)"}, {"bn": "আরাফার দিন (সুনান তিরমিজি)", "en": "The Day of Arafah (Jami'' at-Tirmidhi)"}, {"bn": "আজান ও ইকামতের মাঝখানে (সুনান আবু দাউদ, সুনান তিরমিজি)", "en": "Between the adhan and the iqamah (Sunan Abi Dawud, Jami'' at-Tirmidhi)"}]}, {"type": "note", "tone": "info", "text": {"bn": "শেষ দুটি সময়ের হাদিস সুনান গ্রন্থে আছে এবং বেশিরভাগ মুহাদ্দিস এগুলোকে সহিহ বা হাসান বলেছেন।", "en": "The hadiths for the last two times are in the Sunan collections and most hadith scholars graded them sahih or hasan."}, "check": true}, {"type": "note", "tone": "tip", "text": {"bn": "দোয়ার আগে আল্লাহর প্রশংসা ও দরুদ পড়ুন, মন দিয়ে ও দৃঢ় আশা নিয়ে চান, আর হালাল উপার্জনের খেয়াল রাখুন।", "en": "Begin with praise of Allah and salawat, ask with presence of heart and firm hope, and keep your earnings halal."}}]', 'in_review', 170 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '52f9d37d-82c9-52e8-8c1c-4f6693d76fcf', id, 'fazilat-asmaul-husna', '{"bn": "আল্লাহর নামসমূহ মুখস্থ করার ফজিলত", "en": "Virtue of learning the names of Allah"}', '{"bn": "আল্লাহর নিরানব্বইটি নাম আছে, যে এগুলো আয়ত্ত করবে সে জান্নাতে যাবে; প্রচলিত তালিকাটি কোথা থেকে এসেছে তাও জানুন।", "en": "Allah has ninety-nine names, and whoever comprehends them will enter Paradise; also learn where the popular list comes from."}', 'basic', '[{"type": "arabic", "ar": "وَلِلّٰهِ الْأَسْمَاءُ الْحُسْنٰى فَادْعُوهُ بِهَا", "pron": {"bn": "ওয়া লিল্লাহিল আসমাউল হুসনা ফাদ''ঊহু বিহা", "en": "Wa lillahil-asma''ul-husna fad''uhu biha"}, "meaning": {"bn": "আর আল্লাহর রয়েছে সুন্দরতম নামসমূহ; সুতরাং সেগুলো দিয়ে তাঁকে ডাকো।", "en": "And to Allah belong the best names, so call upon Him by them."}, "ref": {"bn": "সূরা আ''রাফ ৭:১৮০", "en": "Al-A''raf 7:180"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: আল্লাহর নিরানব্বইটি নাম আছে, একশ থেকে এক কম। যে এগুলো আয়ত্ত করবে (আহসাহা), সে জান্নাতে প্রবেশ করবে।", "en": "The Prophet ﷺ said: Allah has ninety-nine names, one hundred less one. Whoever comprehends them (ahsaha) will enter Paradise."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ২৭৩৬; সহিহ মুসলিম ২৬৭৭", "en": "Sahih al-Bukhari 2736; Sahih Muslim 2677"}}, {"type": "heading", "text": {"bn": "“আয়ত্ত করা” মানে কী", "en": "What “comprehending” means"}}, {"type": "text", "text": {"bn": "আলেমরা “আহসাহা” শব্দের ব্যাখ্যায় কয়েকটি স্তর বলেছেন; সব মিলিয়েই পূর্ণ ফজিলত আশা করা যায়:", "en": "Scholars explain “ahsaha” in several levels; together they bring the full virtue:"}}, {"type": "list", "items": [{"bn": "নামগুলো মুখস্থ ও গুনে রাখা।", "en": "Memorising and counting the names."}, {"bn": "প্রতিটি নামের অর্থ বোঝা ও তা বিশ্বাস করা।", "en": "Understanding each name''s meaning and believing in it."}, {"bn": "নামগুলো দিয়ে আল্লাহকে ডাকা, যেমন ক্ষমা চাইতে “ইয়া গাফুর”, রিজিক চাইতে “ইয়া রায্যাক”।", "en": "Calling on Allah by them, e.g. “Ya Ghafur” when seeking forgiveness, “Ya Razzaq” when asking for provision."}, {"bn": "নামগুলোর দাবি অনুযায়ী জীবন চালানো, যেমন “আস-সামী” জেনে মুখ সংযত রাখা।", "en": "Living by what they imply, e.g. guarding the tongue knowing He is As-Sami''."}]}, {"type": "heading", "text": {"bn": "৯৯ নামের তালিকা কোথা থেকে", "en": "Where the list of 99 comes from"}}, {"type": "text", "text": {"bn": "“আল্লাহর নিরানব্বইটি নাম আছে” — এই হাদিস সহিহ বুখারি ও সহিহ মুসলিমে আছে, এবং এটি সম্পূর্ণ সহিহ। তবে বুখারি-মুসলিমের বর্ণনায় নামগুলোর তালিকা নেই।", "en": "The hadith “Allah has ninety-nine names” is in Sahih al-Bukhari and Sahih Muslim and is fully sahih. But their narrations do not list the names."}}, {"type": "text", "text": {"bn": "প্রচলিত ৯৯ নামের তালিকাটি এসেছে সুনান তিরমিজির (৩৫০৭) বর্ণনা থেকে। ইমাম তিরমিজি নিজেই একে “গরিব” বলেছেন, আর অনেক মুহাদ্দিসের মতে তালিকাটি রাসুল ﷺ-এর কথা নয়, বরং কোনো বর্ণনাকারী নামগুলো কুরআন-হাদিস থেকে সংকলন করে যুক্ত করেছেন। তাই তালিকাটির সনদ অনেকের মতে দুর্বল।", "en": "The popular list of 99 comes from the narration in Jami'' at-Tirmidhi (3507). At-Tirmidhi himself called it gharib, and many hadith scholars hold that the list is not the Prophet''s ﷺ words but was compiled from the Quran and Sunnah and inserted by a narrator. So many consider the list itself weak."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি ৩৫০৭", "en": "Jami'' at-Tirmidhi 3507"}}, {"type": "note", "tone": "info", "text": {"bn": "তালিকার প্রায় সব নামই কুরআন বা সহিহ হাদিসে নাম বা গুণ হিসেবে এসেছে, তাই এগুলো মুখস্থ করা ও এগুলো দিয়ে দোয়া করা ভালো আমল। তিরমিজির বিভিন্ন সংস্করণে সামান্য পার্থক্যও আছে (যেমন কোথাও “আল-আহাদ” নেই)। এই অ্যাপে প্রচলিত ক্রম অনুসরণ করা হয়েছে।", "en": "Almost every name in the list occurs in the Quran or sahih hadith as a name or attribute, so learning them and calling on Allah by them is a good deed. Editions of Tirmidhi differ slightly (e.g. some lack “Al-Ahad”). This app follows the common order."}}, {"type": "text", "text": {"bn": "আল্লাহর নাম শুধু ৯৯-এ সীমাবদ্ধ নয়। রাসুল ﷺ-এর একটি দোয়ায় আছে: “আপনার প্রতিটি নামের উসিলায় চাই, যা আপনি নিজের জন্য রেখেছেন... অথবা আপনার কাছে গায়েবের জ্ঞানে গোপন রেখেছেন।” অর্থাৎ ৯৯টি নাম হলো এমন নাম যা আয়ত্ত করলে জান্নাতের প্রতিশ্রুতি আছে।", "en": "Allah''s names are not limited to 99. A dua of the Prophet ﷺ says: “I ask You by every name that is Yours… or that You kept in the knowledge of the unseen with You.” The 99 are those whose comprehension carries the promise of Paradise."}}, {"type": "ref", "text": {"bn": "মুসনাদ আহমাদ", "en": "Musnad Ahmad"}, "check": true}]', 'in_review', 180 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'd36d4838-89eb-5d29-962b-15ceabfd8615', id, 'fazilat-ramadan', '{"bn": "রমজান মাস ও রোজার ফজিলত", "en": "Virtues of Ramadan and fasting"}', '{"bn": "রমজানে জান্নাতের দরজা খোলা থাকে, ঈমান ও সওয়াবের আশায় রোজা রাখলে আগের গুনাহ মাফ, আর রোজাদারের জন্য রাইয়ান দরজা।", "en": "In Ramadan the gates of Paradise open, fasting it with faith and hope of reward forgives past sins, and the gate of Rayyan awaits the fasting."}', 'basic', '[{"type": "text", "text": {"bn": "আল্লাহ বলেন: “রমজান মাস, যাতে কুরআন নাজিল হয়েছে মানুষের জন্য হেদায়াত হিসেবে... সুতরাং তোমাদের মধ্যে যে এই মাস পাবে, সে যেন রোজা রাখে।”", "en": "Allah says: “The month of Ramadan in which the Quran was revealed as guidance for mankind… So whoever of you witnesses the month, let him fast it.”"}}, {"type": "ref", "text": {"bn": "সূরা বাকারা ২:১৮৩–১৮৫", "en": "Al-Baqarah 2:183–185"}}, {"type": "text", "text": {"bn": "রমজান এলে জান্নাতের দরজাগুলো খুলে দেওয়া হয়, জাহান্নামের দরজাগুলো বন্ধ করা হয় এবং শয়তানদের শিকলবন্দি করা হয়।", "en": "When Ramadan comes, the gates of Paradise are opened, the gates of Hell are closed and the devils are chained."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৮৯৯; সহিহ মুসলিম ১০৭৯", "en": "Sahih al-Bukhari 1899; Sahih Muslim 1079"}}, {"type": "heading", "text": {"bn": "রোজার ফজিলত", "en": "Virtues of fasting"}}, {"type": "text", "text": {"bn": "যে ঈমানের সঙ্গে ও সওয়াবের আশায় রমজানের রোজা রাখে, তার আগের গুনাহ মাফ করে দেওয়া হয়।", "en": "Whoever fasts Ramadan out of faith and hoping for reward, his previous sins are forgiven."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৩৮; সহিহ মুসলিম ৭৬০", "en": "Sahih al-Bukhari 38; Sahih Muslim 760"}}, {"type": "text", "text": {"bn": "হাদিসে কুদসিতে আল্লাহ বলেন: আদম সন্তানের প্রতিটি আমল তার নিজের জন্য, রোজা ছাড়া; রোজা আমার জন্য, আর আমিই এর প্রতিদান দেব। রোজাদারের দুটি আনন্দ: ইফতারের সময় এবং রবের সঙ্গে সাক্ষাতের সময়। রোজাদারের মুখের গন্ধ আল্লাহর কাছে মিশকের চেয়েও সুগন্ধময়।", "en": "In a hadith qudsi Allah says: every deed of the son of Adam is for himself except fasting; it is for Me and I will reward it. The fasting person has two joys: at breaking the fast and when meeting his Lord. The smell of his mouth is better to Allah than musk."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৯০৪; সহিহ মুসলিম ১১৫১", "en": "Sahih al-Bukhari 1904; Sahih Muslim 1151"}}, {"type": "text", "text": {"bn": "জান্নাতে “রাইয়ান” নামে একটি দরজা আছে; কিয়ামতের দিন শুধু রোজাদাররাই সেখান দিয়ে প্রবেশ করবে।", "en": "In Paradise there is a gate called ar-Rayyan; only those who fasted will enter through it on the Day of Resurrection."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৮৯৬; সহিহ মুসলিম ১১৫২", "en": "Sahih al-Bukhari 1896; Sahih Muslim 1152"}}, {"type": "heading", "text": {"bn": "রমজানের অন্যান্য আমল", "en": "Other deeds of Ramadan"}}, {"type": "list", "items": [{"bn": "ঈমান ও সওয়াবের আশায় রমজানের রাতে নামাজ (তারাবিহ) পড়লে আগের গুনাহ মাফ হয় (সহিহ বুখারি ৩৭)।", "en": "Praying the nights of Ramadan (tarawih) with faith and hope forgives past sins (Sahih al-Bukhari 37)."}, {"bn": "সাহরি খাও, কারণ সাহরিতে বরকত আছে (সহিহ বুখারি ১৯২৩)।", "en": "Eat suhur, for in suhur there is blessing (Sahih al-Bukhari 1923)."}, {"bn": "যে রোজাদারকে ইফতার করায়, সে রোজাদারের সমান সওয়াব পায়, রোজাদারের সওয়াব একটুও কমে না (সুনান তিরমিজি ৮০৭)।", "en": "Whoever gives iftar to a fasting person gets his reward without it decreasing his (Jami'' at-Tirmidhi 807)."}, {"bn": "রমজানে জিবরিল (আ.) প্রতি রাতে রাসুল ﷺ-এর সঙ্গে কুরআন পুনরাবৃত্তি করতেন, আর তখন তিনি প্রবাহিত বাতাসের চেয়েও বেশি দানশীল হতেন (সহিহ বুখারি ৬)।", "en": "In Ramadan Jibril reviewed the Quran with the Prophet ﷺ every night, and he was more generous than the blowing wind (Sahih al-Bukhari 6)."}, {"bn": "রমজানে উমরাহ করা হজের সমান সওয়াব (সহিহ মুসলিম ১২৫৬)।", "en": "Umrah in Ramadan equals a hajj in reward (Sahih Muslim 1256)."}, {"bn": "রাসুল ﷺ ইন্তেকাল পর্যন্ত রমজানের শেষ দশ দিন ইতিকাফ করতেন (সহিহ বুখারি ২০২৬)।", "en": "The Prophet ﷺ observed i''tikaf in the last ten days of Ramadan until he passed away (Sahih al-Bukhari 2026)."}]}, {"type": "note", "tone": "warn", "text": {"bn": "যে মিথ্যা কথা ও মিথ্যা অনুযায়ী কাজ ছাড়ে না, তার খাবার-পানীয় ছেড়ে দেওয়ায় আল্লাহর কোনো প্রয়োজন নেই (সহিহ বুখারি ১৯০৩)।", "en": "Whoever does not give up false speech and acting upon it, Allah has no need of his leaving food and drink (Sahih al-Bukhari 1903)."}}, {"type": "note", "tone": "info", "text": {"bn": "“রমজানের প্রথম দশ দিন রহমত, মাঝের দশ দিন মাগফিরাত, শেষ দশ দিন জাহান্নাম থেকে মুক্তি” — এই প্রসিদ্ধ বর্ণনাটি সহিহ ইবনে খুযাইমা ও বায়হাকিতে এসেছে, কিন্তু এর সনদ দুর্বল। পুরো রমজানই রহমত, মাগফিরাত ও মুক্তির মাস।", "en": "The popular report “the first ten days of Ramadan are mercy, the middle forgiveness, the last freedom from Hell” is in Sahih Ibn Khuzaymah and al-Bayhaqi but its chain is weak. The whole of Ramadan is a month of mercy, forgiveness and release."}}]', 'in_review', 190 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '0927dd39-7dea-5f4c-b2d1-57e4654ee9eb', id, 'fazilat-laylatul-qadr', '{"bn": "লাইলাতুল কদরের ফজিলত", "en": "Virtues of Laylat al-Qadr"}', '{"bn": "হাজার মাসের চেয়ে উত্তম এক রাত; রমজানের শেষ দশকের বেজোড় রাতে খুঁজতে হয়, আর রাসুল ﷺ শিখিয়েছেন বিশেষ দোয়া।", "en": "A night better than a thousand months; seek it in the odd nights of the last ten of Ramadan, with the special dua the Prophet ﷺ taught."}', 'basic', '[{"type": "arabic", "ar": "لَيْلَةُ الْقَدْرِ خَيْرٌ مِنْ أَلْفِ شَهْرٍ", "pron": {"bn": "লাইলাতুল কাদরি খাইরুম মিন আলফি শাহর", "en": "Laylatul-qadri khayrum min alfi shahr"}, "meaning": {"bn": "কদরের রাত হাজার মাসের চেয়ে উত্তম।", "en": "The Night of Decree is better than a thousand months."}, "ref": {"bn": "সূরা কদর ৯৭:৩", "en": "Al-Qadr 97:3"}}, {"type": "text", "text": {"bn": "এই রাতে কুরআন নাজিল হয়েছে; এ রাতে ফেরেশতা ও জিবরিল (আ.) রবের অনুমতিতে নেমে আসেন, আর ফজর পর্যন্ত শান্তি থাকে। আল্লাহ আরও বলেন: “এ রাতে প্রতিটি প্রজ্ঞাপূর্ণ বিষয়ের ফয়সালা করা হয়।”", "en": "The Quran was revealed in this night; angels and Jibril descend by their Lord''s permission, and it is peace until dawn. Allah also says: “In it every wise matter is made distinct.”"}}, {"type": "ref", "text": {"bn": "সূরা কদর ৯৭:১–৫; সূরা দুখান ৪৪:৩–৪", "en": "Al-Qadr 97:1–5; Ad-Dukhan 44:3–4"}}, {"type": "text", "text": {"bn": "যে ঈমানের সঙ্গে ও সওয়াবের আশায় লাইলাতুল কদরে নামাজে দাঁড়ায়, তার আগের গুনাহ মাফ করে দেওয়া হয়।", "en": "Whoever stands in prayer on Laylat al-Qadr out of faith and hoping for reward, his previous sins are forgiven."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৯০১; সহিহ মুসলিম ৭৬০", "en": "Sahih al-Bukhari 1901; Sahih Muslim 760"}}, {"type": "text", "text": {"bn": "রমজানের শেষ দশ দিন শুরু হলে রাসুল ﷺ কোমর বেঁধে নিতেন, রাত জেগে ইবাদত করতেন এবং পরিবারকেও জাগাতেন। তিনি এই দশ দিনে অন্য সময়ের চেয়ে বেশি পরিশ্রম করতেন।", "en": "When the last ten days began, the Prophet ﷺ tightened his waist-wrap, spent the nights in worship and woke his family; he strove in them more than at any other time."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ২০২৪; সহিহ মুসলিম ১১৭৫", "en": "Sahih al-Bukhari 2024; Sahih Muslim 1175"}}, {"type": "differ", "title": {"bn": "কোন রাত লাইলাতুল কদর", "en": "Which night is Laylat al-Qadr"}, "views": [{"label": {"bn": "শেষ দশকের যেকোনো বেজোড় রাত", "en": "Any odd night of the last ten"}, "text": {"bn": "রাতটি নির্দিষ্ট করে জানানো হয়নি; শেষ দশকের বেজোড় রাতগুলোতে (২১, ২৩, ২৫, ২৭, ২৯) খুঁজতে হবে, এবং অনেক আলেমের মতে এটি বছরে বছরে পরিবর্তন হতে পারে।", "en": "The night was not fixed for us; seek it in the odd nights of the last ten (21, 23, 25, 27, 29), and many scholars hold it may move from year to year."}, "evidence": {"bn": "“রমজানের শেষ দশকের বেজোড় রাতে লাইলাতুল কদর খোঁজো” (সহিহ বুখারি ২০১৭)।", "en": "“Seek Laylat al-Qadr in the odd nights of the last ten of Ramadan” (Sahih al-Bukhari 2017)."}}, {"label": {"bn": "২৭তম রাতের সম্ভাবনা সবচেয়ে বেশি", "en": "The 27th is the most likely"}, "text": {"bn": "সাহাবি উবাই ইবনে কা''ব (রা.) কসম করে বলতেন এটি ২৭তম রাত; উপমহাদেশে হানাফিসহ অনেকেই এ রাতকে বিশেষ গুরুত্ব দেন, তবে অন্য রাতগুলোও ছাড়েন না।", "en": "Ubayy ibn Ka''b (RA) used to swear it was the 27th; many in the subcontinent, including Hanafis, give that night special weight without neglecting the others."}, "evidence": {"bn": "উবাই ইবনে কা''ব (রা.)-এর বর্ণনা (সহিহ মুসলিম ৭৬২)।", "en": "The narration of Ubayy ibn Ka''b (Sahih Muslim 762)."}}]}, {"type": "heading", "text": {"bn": "লাইলাতুল কদরের দোয়া", "en": "The dua for Laylat al-Qadr"}}, {"type": "arabic", "label": {"bn": "আয়েশা (রা.)-কে শেখানো দোয়া", "en": "The dua taught to Aishah (RA)"}, "ar": "اللّٰهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي", "pron": {"bn": "আল্লাহুম্মা ইন্নাকা আফুউউন তুহিব্বুল আফওয়া ফা''ফু আন্নী", "en": "Allahumma innaka ''afuwwun tuhibbul-''afwa fa''fu ''anni"}, "meaning": {"bn": "হে আল্লাহ, আপনি ক্ষমাশীল, ক্ষমা করতে ভালোবাসেন; সুতরাং আমাকে ক্ষমা করুন।", "en": "O Allah, You are Pardoning and love to pardon, so pardon me."}, "ref": {"bn": "সুনান তিরমিজি ৩৫১৩; সুনান ইবনে মাজাহ ৩৮৫০", "en": "Jami'' at-Tirmidhi 3513; Sunan Ibn Majah 3850"}}, {"type": "note", "tone": "info", "text": {"bn": "কিছু ছাপায় এই দোয়ায় “কারীম” শব্দ যুক্ত আছে; অনেক মুহাদ্দিস উল্লেখ করেছেন যে নির্ভরযোগ্য বর্ণনায় শব্দটি নেই।", "en": "Some prints add “karim” to this dua; many hadith scholars note that the reliable narrations do not contain it."}}, {"type": "note", "tone": "tip", "text": {"bn": "শেষ দশকের প্রতিটি রাতে অন্তত কিছু নামাজ, কুরআন, দোয়া ও ইস্তিগফার করুন, তাহলে যে রাতেই হোক আপনি তা পাবেন ইনশাআল্লাহ।", "en": "Spend every night of the last ten with some prayer, Quran, dua and istighfar, so you catch it whichever night it is, in sha Allah."}}]', 'in_review', 200 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '580c6d4d-8962-57da-899f-293addd4dc85', id, 'fazilat-nafl-sawm', '{"bn": "নফল রোজার ফজিলত: আরাফা, আশুরা, শাওয়াল ও অন্যান্য", "en": "Voluntary fasts: Arafah, Ashura, Shawwal and more"}', '{"bn": "আরাফার রোজা দুই বছরের, আশুরার রোজা এক বছরের গুনাহের কাফফারা; শাওয়ালের ছয় রোজায় সারা বছরের সওয়াব।", "en": "Fasting Arafah expiates two years and Ashura one year; six days of Shawwal bring the reward of a whole year."}', 'detail', '[{"type": "text", "text": {"bn": "আল্লাহর পথে (আল্লাহর সন্তুষ্টির জন্য) একদিন রোজা রাখলে আল্লাহ তার চেহারাকে জাহান্নাম থেকে সত্তর বছরের দূরত্বে সরিয়ে দেন।", "en": "Whoever fasts one day for the sake of Allah, Allah keeps his face seventy years'' distance from the Fire."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ২৮৪০; সহিহ মুসলিম ১১৫৩", "en": "Sahih al-Bukhari 2840; Sahih Muslim 1153"}}, {"type": "table", "head": [{"bn": "রোজা", "en": "Fast"}, {"bn": "ফজিলত", "en": "Virtue"}, {"bn": "সূত্র", "en": "Source"}], "rows": [[{"bn": "আরাফার দিন (৯ জিলহজ)", "en": "Day of Arafah (9 Dhul-Hijjah)"}, {"bn": "আগের ও পরের এক বছরের গুনাহের কাফফারা আশা করা যায়", "en": "Hoped to expiate the year before and the year after"}, {"bn": "সহিহ মুসলিম ১১৬২", "en": "Sahih Muslim 1162"}], [{"bn": "আশুরা (১০ মহররম)", "en": "Ashura (10 Muharram)"}, {"bn": "আগের এক বছরের গুনাহের কাফফারা আশা করা যায়", "en": "Hoped to expiate the previous year"}, {"bn": "সহিহ মুসলিম ১১৬২", "en": "Sahih Muslim 1162"}], [{"bn": "শাওয়ালের ছয় রোজা", "en": "Six days of Shawwal"}, {"bn": "রমজানের সঙ্গে মিলে সারা বছর রোজার সমান", "en": "With Ramadan, like fasting the whole year"}, {"bn": "সহিহ মুসলিম ১১৬৪", "en": "Sahih Muslim 1164"}], [{"bn": "মহররম মাস", "en": "The month of Muharram"}, {"bn": "রমজানের পর শ্রেষ্ঠ রোজা", "en": "The best fasting after Ramadan"}, {"bn": "সহিহ মুসলিম ১১৬৩", "en": "Sahih Muslim 1163"}], [{"bn": "সোমবার", "en": "Monday"}, {"bn": "রাসুল ﷺ-এর জন্মদিন ও ওহি নাজিলের দিন", "en": "The day the Prophet ﷺ was born and revelation began"}, {"bn": "সহিহ মুসলিম ১১৬২", "en": "Sahih Muslim 1162"}]]}, {"type": "note", "tone": "info", "text": {"bn": "আরাফার রোজা হজে না যাওয়া লোকদের জন্য; আরাফার ময়দানে থাকা হাজিদের জন্য রোজা না রাখাই সুন্নত।", "en": "The Arafah fast is for those not on hajj; for pilgrims standing at Arafah, the sunnah is not to fast."}}, {"type": "heading", "text": {"bn": "আশুরার সঙ্গে ৯ তারিখ", "en": "Adding the 9th to Ashura"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছিলেন: আগামী বছর বেঁচে থাকলে আমি অবশ্যই ৯ তারিখেও রোজা রাখব। তাই আলেমরা ১০ তারিখের সঙ্গে ৯ তারিখ (না পারলে ১১ তারিখ) মিলিয়ে রোজা রাখতে উৎসাহ দেন; হানাফি আলেমরা শুধু ১০ তারিখ একা রাখাকে অনুত্তম বলেছেন।", "en": "The Prophet ﷺ said: if I live until next year I will fast the 9th as well. So scholars encourage adding the 9th (or else the 11th) to the 10th; Hanafi scholars consider fasting the 10th alone less preferable."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১১৩৪", "en": "Sahih Muslim 1134"}}, {"type": "heading", "text": {"bn": "প্রতি মাসের রোজা", "en": "Monthly fasts"}}, {"type": "list", "items": [{"bn": "প্রতি মাসে তিন দিন রোজা রাখা সারা বছর রোজা রাখার মতো; আবু হুরাইরা (রা.)-কে রাসুল ﷺ এর অসিয়ত করেছিলেন (সহিহ বুখারি, সহিহ মুসলিম)।", "en": "Fasting three days every month is like fasting all year; the Prophet ﷺ advised Abu Hurairah (RA) with it (al-Bukhari, Muslim)."}, {"bn": "সোমবার ও বৃহস্পতিবার আমল আল্লাহর কাছে পেশ করা হয়, তাই রাসুল ﷺ এ দুই দিন রোজা রাখতে পছন্দ করতেন (সুনান তিরমিজি)।", "en": "Deeds are presented to Allah on Mondays and Thursdays, so the Prophet ﷺ liked to fast on them (Jami'' at-Tirmidhi)."}], "check": true}, {"type": "note", "tone": "tip", "text": {"bn": "শাওয়ালের ছয় রোজা ঈদের পর একটানা বা আলাদা আলাদা যেকোনোভাবে রাখা যায়; কারও রমজানের কাজা থাকলে আগে কাজা আদায় করা উত্তম।", "en": "The six Shawwal fasts may be kept consecutively or separately after Eid; whoever owes Ramadan days should preferably make them up first."}}]', 'in_review', 210 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '1c0323c1-35a4-59a5-954b-db64d917ac3d', id, 'fazilat-dhul-hijjah', '{"bn": "জিলহজের প্রথম দশ দিনের ফজিলত", "en": "Virtues of the first ten days of Dhul-Hijjah"}', '{"bn": "বছরের শ্রেষ্ঠ দিনগুলো: এ সময়ের নেক আমল আল্লাহর কাছে সবচেয়ে প্রিয়; আরাফার রোজা, তাকবির ও কুরবানি।", "en": "The best days of the year: good deeds in them are most beloved to Allah; the Arafah fast, takbir and sacrifice."}', 'basic', '[{"type": "text", "text": {"bn": "আল্লাহ কসম করে বলেছেন: “শপথ ফজরের, শপথ দশ রাতের।” অধিকাংশ মুফাসসিরের মতে এই দশ রাত জিলহজের প্রথম দশক।", "en": "Allah swears: “By the dawn, and by the ten nights.” Most commentators say these are the first ten of Dhul-Hijjah."}}, {"type": "ref", "text": {"bn": "সূরা ফাজর ৮৯:১–২", "en": "Al-Fajr 89:1–2"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: এমন কোনো দিন নেই যেদিনের নেক আমল আল্লাহর কাছে এই দশ দিনের আমলের চেয়ে বেশি প্রিয়। সাহাবিরা বললেন, আল্লাহর পথে জিহাদও নয়? তিনি বললেন: জিহাদও নয়; তবে সেই ব্যক্তি ছাড়া, যে জান-মাল নিয়ে বের হয়ে আর কিছু নিয়েই ফেরেনি।", "en": "There are no days in which righteous deeds are more beloved to Allah than these ten. They asked: not even jihad? He said: not even jihad, except a man who went out with his life and wealth and returned with nothing."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৯৬৯; সুনান আবু দাউদ ২৪৩৮", "en": "Sahih al-Bukhari 969; Sunan Abi Dawud 2438"}}, {"type": "heading", "text": {"bn": "এই দিনগুলোর আমল", "en": "Deeds in these days"}}, {"type": "list", "items": [{"bn": "বেশি বেশি তাকবির, তাহলিল ও তাহমিদ পড়া; সাহাবি ইবনে উমর ও আবু হুরাইরা (রা.) এই দিনগুলোতে বাজারে গিয়ে তাকবির বলতেন, আর মানুষও তাঁদের সঙ্গে বলত (সহিহ বুখারি, ঈদ অধ্যায়)।", "en": "Abundant takbir, tahlil and praise; Ibn Umar and Abu Hurairah (RA) would go to the market in these days saying takbir and people would join them (al-Bukhari, Book of the Eids)."}, {"bn": "৯ তারিখ আরাফার রোজা, যা আগের ও পরের এক বছরের গুনাহের কাফফারা আশা করা যায় (সহিহ মুসলিম ১১৬২)।", "en": "Fasting on the 9th, the Day of Arafah, hoped to expiate the year before and after (Sahih Muslim 1162)."}, {"bn": "আরাফার দিনের মতো আর কোনো দিন আল্লাহ এত বান্দাকে জাহান্নাম থেকে মুক্তি দেন না (সহিহ মুসলিম ১৩৪৮)।", "en": "There is no day on which Allah frees more servants from the Fire than the Day of Arafah (Sahih Muslim 1348)."}, {"bn": "সামর্থ্য থাকলে ঈদের দিন কুরবানি করা।", "en": "Offering the sacrifice on Eid if able."}, {"bn": "নামাজ, কুরআন, সদকা, তওবা ইত্যাদি সব নেক আমল বাড়িয়ে দেওয়া।", "en": "Increasing all good deeds: prayer, Quran, charity and repentance."}]}, {"type": "arabic", "label": {"bn": "তাকবির (সাহাবিদের থেকে বর্ণিত শব্দ)", "en": "Takbir (wording reported from the Companions)"}, "ar": "اللّٰهُ أَكْبَرُ، اللّٰهُ أَكْبَرُ، لَا إِلٰهَ إِلَّا اللّٰهُ، وَاللّٰهُ أَكْبَرُ، اللّٰهُ أَكْبَرُ، وَلِلّٰهِ الْحَمْدُ", "pron": {"bn": "আল্লাহু আকবার, আল্লাহু আকবার, লা ইলাহা ইল্লাল্লাহু ওয়াল্লাহু আকবার, আল্লাহু আকবার, ওয়া লিল্লাহিল হামদ", "en": "Allahu akbar, Allahu akbar, la ilaha illallahu wallahu akbar, Allahu akbar, wa lillahil-hamd"}, "meaning": {"bn": "আল্লাহ সর্বশ্রেষ্ঠ, আল্লাহ সর্বশ্রেষ্ঠ; আল্লাহ ছাড়া কোনো সত্য ইলাহ নেই; আল্লাহ সর্বশ্রেষ্ঠ, আল্লাহ সর্বশ্রেষ্ঠ, আর সব প্রশংসা আল্লাহর।", "en": "Allah is the Greatest, Allah is the Greatest; there is no god but Allah; Allah is the Greatest, Allah is the Greatest, and to Allah belongs all praise."}, "ref": {"bn": "মুসান্নাফ ইবনে আবি শাইবা", "en": "Musannaf Ibn Abi Shaybah"}, "check": true}, {"type": "heading", "text": {"bn": "কুরবানিদাতার চুল-নখ না কাটা", "en": "The sacrificer not cutting hair and nails"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: জিলহজের দশ দিন শুরু হলে তোমাদের কেউ কুরবানি করার ইচ্ছা করলে সে যেন (কুরবানি পর্যন্ত) চুল ও নখ না কাটে।", "en": "When the ten days begin and one of you intends to sacrifice, let him not cut his hair or nails (until he sacrifices)."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১৯৭৭", "en": "Sahih Muslim 1977"}}, {"type": "differ", "title": {"bn": "এই নির্দেশের হুকুম", "en": "Ruling of this instruction"}, "views": [{"label": {"bn": "হানাফি, মালিকি ও শাফেয়ি", "en": "Hanafi, Maliki and Shafi''i"}, "text": {"bn": "মুস্তাহাব; কাটলে গুনাহ নেই, তবে না কাটা উত্তম।", "en": "Recommended; cutting is not sinful, but refraining is better."}, "evidence": {"bn": "আয়েশা (রা.)-এর বর্ণনা: রাসুল ﷺ মদিনা থেকে কুরবানির পশু পাঠাতেন, অথচ ইহরামকারীর জন্য যা নিষিদ্ধ তার কিছুই নিজের ওপর হারাম করতেন না (সহিহ বুখারি, সহিহ মুসলিম); তাই তাঁরা নির্দেশটিকে উৎসাহমূলক বুঝেছেন।", "en": "Aishah''s narration that the Prophet ﷺ sent sacrificial animals from Madinah without abstaining from anything forbidden to a pilgrim (al-Bukhari, Muslim); so they read the instruction as encouragement."}}, {"label": {"bn": "হাম্বলি", "en": "Hanbali"}, "text": {"bn": "ওয়াজিব; কুরবানির আগে কাটা হারাম, তবে কুরবানি সহিহ হবে।", "en": "Obligatory; cutting before the sacrifice is forbidden, though the sacrifice remains valid."}, "evidence": {"bn": "সহিহ মুসলিমের নির্দেশটি সরাসরি নিষেধবাচক শব্দে এসেছে।", "en": "The instruction in Sahih Muslim is a direct prohibition."}}], "check": true}]', 'in_review', 220 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'deb3fef6-a819-5275-ab05-0b40d20ed582', id, 'fazilat-shab-e-barat', '{"bn": "শবে বরাত (১৫ শাবান): বর্ণনা ও আলেমদের মত", "en": "Shab-e-Barat (15 Sha''ban): narrations and scholarly views"}', '{"bn": "মধ্য শাবানের রাত সম্পর্কে বর্ণিত হাদিসগুলোর মান, আলেমদের দুটি প্রধান মত এবং যেসব বিষয়ে সবাই একমত।", "en": "The grading of the narrations about the night of mid-Sha''ban, the two main scholarly views, and what all agree on."}', 'detail', '[{"type": "text", "text": {"bn": "শাবান মাস নিজেই ফজিলতপূর্ণ: আয়েশা (রা.) বলেন, রমজান ছাড়া অন্য কোনো মাসে রাসুল ﷺ-কে শাবানের চেয়ে বেশি রোজা রাখতে দেখিনি।", "en": "Sha''ban itself is virtuous: Aishah (RA) said she never saw the Prophet ﷺ fast more in any month besides Ramadan than in Sha''ban."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৯৬৯; সহিহ মুসলিম ১১৫৬", "en": "Sahih al-Bukhari 1969; Sahih Muslim 1156"}}, {"type": "text", "text": {"bn": "উসামা ইবনে যায়েদ (রা.)-এর বর্ণনায় রাসুল ﷺ বলেছেন, শাবান এমন মাস যার ব্যাপারে মানুষ উদাসীন থাকে, আর এ মাসে আমল রব্বুল আলামিনের কাছে তুলে ধরা হয়।", "en": "In the narration of Usamah ibn Zayd (RA), the Prophet ﷺ said Sha''ban is a month people neglect, and in it deeds are raised to the Lord of the worlds."}}, {"type": "ref", "text": {"bn": "সুনান নাসায়ি", "en": "Sunan an-Nasa''i"}, "check": true}, {"type": "heading", "text": {"bn": "মধ্য শাবানের রাত সম্পর্কে বর্ণনা", "en": "Narrations about the night of mid-Sha''ban"}}, {"type": "list", "items": [{"bn": "“আল্লাহ মধ্য শাবানের রাতে সৃষ্টির দিকে দৃষ্টি দেন এবং মুশরিক ও বিদ্বেষ পোষণকারী ছাড়া সবাইকে ক্ষমা করেন।” এটি সুনান ইবনে মাজাহ (১৩৯০), সহিহ ইবনে হিব্বান ইত্যাদিতে কয়েকজন সাহাবি থেকে এসেছে। প্রতিটি সনদে দুর্বলতা আছে; তবে সব সূত্র মিলিয়ে অনেক মুহাদ্দিস (যেমন আলবানি) একে সহিহ/হাসান বলেছেন, আর অন্যরা দুর্বলই মনে করেন।", "en": "“Allah looks at His creation on the night of mid-Sha''ban and forgives all except a polytheist or one harbouring hatred.” Reported from several Companions in Sunan Ibn Majah (1390), Sahih Ibn Hibban and others. Each chain has weakness; combining them, many scholars (e.g. al-Albani) graded it sahih/hasan, while others still consider it weak."}, {"bn": "আয়েশা (রা.)-এর বর্ণনা: রাসুল ﷺ এক রাতে বাকি কবরস্থানে গিয়েছিলেন এবং বলেছিলেন, আল্লাহ মধ্য শাবানের রাতে কালব গোত্রের ছাগলের পশমের চেয়েও বেশি মানুষকে ক্ষমা করেন (সুনান তিরমিজি ৭৩৯)। ইমাম তিরমিজি উল্লেখ করেছেন যে ইমাম বুখারি এটিকে দুর্বল বলেছেন।", "en": "Aishah''s (RA) report that the Prophet ﷺ went to al-Baqi'' one night and said Allah forgives on the night of mid-Sha''ban more than the hairs of the sheep of Kalb (Jami'' at-Tirmidhi 739). At-Tirmidhi notes that al-Bukhari declared it weak."}, {"bn": "“মধ্য শাবানের রাতে নামাজ পড়ো এবং দিনে রোজা রাখো” (সুনান ইবনে মাজাহ ১৩৮৮) — এর সনদে একজন বর্ণনাকারীকে হাদিস জাল করার অভিযোগে অভিযুক্ত করা হয়েছে, তাই মুহাদ্দিসদের মতে এটি অত্যন্ত দুর্বল বা জাল।", "en": "“Pray in its night and fast its day” (Sunan Ibn Majah 1388) — its chain contains a narrator accused of fabricating hadith, so scholars rate it very weak or fabricated."}]}, {"type": "ref", "text": {"bn": "সুনান ইবনে মাজাহ ১৩৯০; সুনান তিরমিজি ৭৩৯; সুনান ইবনে মাজাহ ১৩৮৮", "en": "Sunan Ibn Majah 1390; Jami'' at-Tirmidhi 739; Sunan Ibn Majah 1388"}, "check": true}, {"type": "differ", "title": {"bn": "রাতটির বিশেষ ফজিলত আছে কি না", "en": "Does the night have a special virtue?"}, "views": [{"label": {"bn": "ফজিলত আছে", "en": "It has a virtue"}, "text": {"bn": "রাতটি ক্ষমার রাত; একাকী নফল নামাজ, তিলাওয়াত, দোয়া ও ইস্তিগফার করা ভালো, তবে নির্দিষ্ট কোনো পদ্ধতি বা সম্মিলিত অনুষ্ঠান নেই। উপমহাদেশের অনেক হানাফি আলেমসহ পূর্বসূরি ও পরবর্তী বহু আলেম এই মত দিয়েছেন।", "en": "It is a night of forgiveness; individual voluntary prayer, recitation, dua and istighfar are good, but with no fixed method or collective ritual. Many Hanafi scholars of the subcontinent and many earlier and later scholars hold this view."}, "evidence": {"bn": "ক্ষমার হাদিসটির বিভিন্ন সূত্র মিলিয়ে তা হাসান/সহিহ পর্যায়ে পৌঁছে; কিছু তাবেয়ি এ রাতে ইবাদতে বিশেষ যত্ন নিতেন বলে বর্ণিত আছে।", "en": "The forgiveness hadith reaches hasan/sahih by its combined routes; some of the Tabi''un are reported to have given this night special care in worship."}}, {"label": {"bn": "বিশেষ ফজিলত প্রমাণিত নয়", "en": "No special virtue is established"}, "text": {"bn": "রাতটিকে অন্য সাধারণ রাতের মতোই দেখা উচিত; নিয়মিত তাহাজ্জুদ যে করে সে করবে, কিন্তু এ রাতকে আলাদা ইবাদতের জন্য নির্দিষ্ট করা ঠিক নয়।", "en": "The night should be treated like any other; whoever regularly prays tahajjud may do so, but singling it out for special worship is not correct."}, "evidence": {"bn": "প্রতিটি সনদ আলাদাভাবে দুর্বল, আর দুর্বল সূত্রের সমষ্টি দিয়ে নির্দিষ্ট ইবাদত প্রমাণ করা যায় না; রাসুল ﷺ বা সাহাবিদের থেকে এ রাতে বিশেষ আমলের সহিহ প্রমাণ নেই।", "en": "Each chain is weak on its own and weak routes cannot establish a specific act of worship; there is no sahih evidence of special practice on this night from the Prophet ﷺ or the Companions."}}]}, {"type": "heading", "text": {"bn": "যেসব বিষয়ে আলেমরা একমত", "en": "What scholars agree on"}}, {"type": "list", "items": [{"bn": "এ রাতের জন্য নির্দিষ্ট রাকাত ও সূরার কোনো বিশেষ নামাজ (যেমন একশ রাকাতের “সালাতুল আলফিয়া”) প্রমাণিত নয়; এ সংক্রান্ত বর্ণনাগুলো জাল।", "en": "No special prayer with fixed rak''ahs and surahs (such as the hundred-rak''ah “salat al-alfiyyah”) is established; the reports about it are fabricated."}, {"bn": "হালুয়া-রুটি, আতশবাজি, আলোকসজ্জা ও কবরস্থানে দলবদ্ধ উৎসবের কোনো ভিত্তি নেই।", "en": "Halwa-ruti, fireworks, illuminations and group festivities at graveyards have no basis."}, {"bn": "“এ রাতে ভাগ্য লেখা হয়” — সূরা দুখানের (৪৪:৩–৪) “বরকতময় রাত” অধিকাংশ মুফাসসিরের মতে লাইলাতুল কদর, কারণ কুরআন রমজানে নাজিল হয়েছে (২:১৮৫, ৯৭:১)।", "en": "“Destinies are written this night” — the “blessed night” of Ad-Dukhan (44:3–4) is Laylat al-Qadr according to most commentators, since the Quran was revealed in Ramadan (2:185, 97:1)."}, {"bn": "শুধু ১৫ তারিখের রোজার হাদিসটি অত্যন্ত দুর্বল; তবে প্রতি মাসের ১৩, ১৪, ১৫ তারিখ (আইয়ামে বিয) এবং শাবানে বেশি রোজা রাখা সুন্নত, তাই এই নিয়তে ১৫ তারিখ রোজা রাখা যায়।", "en": "The hadith on fasting the 15th alone is very weak; but fasting the 13th–15th of every month and much of Sha''ban is sunnah, so one may fast the 15th with that intention."}, {"bn": "ক্ষমা পেতে শিরক ও মানুষের প্রতি বিদ্বেষ থেকে মুক্ত হওয়া জরুরি; এটি সব মতেই গুরুত্বপূর্ণ শিক্ষা।", "en": "To be forgiven one must be free of shirk and of hatred towards others; this lesson matters on every view."}]}, {"type": "note", "tone": "tip", "text": {"bn": "যে মতই অনুসরণ করুন, অন্য মতের মানুষকে কটাক্ষ করবেন না; এটি ইজতিহাদি বিষয়।", "en": "Whichever view you follow, do not belittle those who follow the other; it is a matter of scholarly judgement."}}]', 'in_review', 230 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '3cd5469c-95e1-5819-b99e-1a35c119d5cc', id, 'fazilat-sadaqah', '{"bn": "সদকার ফজিলত", "en": "Virtues of sadaqah (charity)"}', '{"bn": "সদকা সম্পদ কমায় না, আল্লাহ হালাল উপার্জনের সদকা বাড়িয়ে দেন, আর সদকায়ে জারিয়া মৃত্যুর পরও চলতে থাকে।", "en": "Charity does not decrease wealth, Allah grows charity from pure earnings, and ongoing charity continues after death."}', 'basic', '[{"type": "text", "text": {"bn": "আল্লাহ বলেন: “যারা আল্লাহর পথে নিজেদের সম্পদ ব্যয় করে, তাদের উদাহরণ একটি শস্যদানার মতো, যা থেকে সাতটি শীষ জন্মায়, প্রতিটি শীষে একশ দানা; আর আল্লাহ যাকে ইচ্ছা আরও বহুগুণ বাড়িয়ে দেন।”", "en": "Allah says: “The example of those who spend their wealth in the way of Allah is like a seed that grows seven ears, in each ear a hundred grains; and Allah multiplies for whom He wills.”"}}, {"type": "ref", "text": {"bn": "সূরা বাকারা ২:২৬১", "en": "Al-Baqarah 2:261"}}, {"type": "text", "text": {"bn": "সদকা সম্পদ কমায় না; ক্ষমা করার কারণে আল্লাহ বান্দার সম্মানই বাড়িয়ে দেন; আর যে আল্লাহর জন্য বিনয়ী হয়, আল্লাহ তাকে উঁচু করেন।", "en": "Charity does not decrease wealth; Allah only increases a servant in honour for forgiving; and whoever humbles himself for Allah, Allah raises him."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৫৮৮", "en": "Sahih Muslim 2588"}}, {"type": "text", "text": {"bn": "যে হালাল উপার্জন থেকে একটি খেজুর পরিমাণও সদকা করে — আর আল্লাহ শুধু পবিত্র জিনিসই গ্রহণ করেন — আল্লাহ তা ডান হাতে গ্রহণ করে লালন করেন, যেমন তোমরা ঘোড়ার বাচ্চা লালন কর, শেষে তা পাহাড়ের সমান হয়ে যায়।", "en": "Whoever gives charity equal to a date from pure earnings — and Allah accepts only the pure — Allah takes it in His right hand and grows it as you raise a foal, until it becomes like a mountain."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৪১০; সহিহ মুসলিম ১০১৪", "en": "Sahih al-Bukhari 1410; Sahih Muslim 1014"}}, {"type": "text", "text": {"bn": "অর্ধেক খেজুর দিয়ে হলেও জাহান্নাম থেকে বাঁচো।", "en": "Protect yourselves from the Fire even with half a date."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৪১৭; সহিহ মুসলিম ১০১৬", "en": "Sahih al-Bukhari 1417; Sahih Muslim 1016"}}, {"type": "text", "text": {"bn": "প্রতিদিন সকালে দুজন ফেরেশতা নামেন; একজন বলেন: হে আল্লাহ, দানকারীকে বিনিময় দিন; আরেকজন বলেন: হে আল্লাহ, কৃপণের সম্পদ ধ্বংস করুন।", "en": "Every morning two angels descend; one says: O Allah, give the spender a replacement; the other says: O Allah, give the withholder ruin."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৪৪২; সহিহ মুসলিম ১০১০", "en": "Sahih al-Bukhari 1442; Sahih Muslim 1010"}}, {"type": "text", "text": {"bn": "কিয়ামতের দিন আল্লাহর ছায়ায় যে সাত শ্রেণির মানুষ থাকবে, তাদের একজন সেই ব্যক্তি, যে এত গোপনে সদকা করে যে তার বাম হাত জানে না ডান হাত কী দিল।", "en": "Among the seven shaded by Allah on the Last Day is one who gives charity so secretly that his left hand does not know what his right hand gave."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৪২৩; সহিহ মুসলিম ১০৩১", "en": "Sahih al-Bukhari 1423; Sahih Muslim 1031"}}, {"type": "heading", "text": {"bn": "সদকায়ে জারিয়া", "en": "Ongoing charity"}}, {"type": "text", "text": {"bn": "মানুষ মারা গেলে তার আমল বন্ধ হয়ে যায়, তিনটি ছাড়া: সদকায়ে জারিয়া, উপকারী জ্ঞান, এবং নেক সন্তান যে তার জন্য দোয়া করে।", "en": "When a person dies, his deeds end except three: ongoing charity, beneficial knowledge, or a righteous child who prays for him."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১৬৩১", "en": "Sahih Muslim 1631"}}, {"type": "note", "tone": "tip", "text": {"bn": "প্রতিটি ভালো কাজই সদকা (সহিহ বুখারি ৬০২১)। টাকা না থাকলেও হাসিমুখ, ভালো কথা, কারও কাজে সাহায্য — সবই সদকা।", "en": "Every good deed is charity (Sahih al-Bukhari 6021). Even without money, a smile, a kind word or helping someone is sadaqah."}}, {"type": "text", "text": {"bn": "সদকা গুনাহকে এমনভাবে নিভিয়ে দেয়, যেমন পানি আগুন নিভিয়ে দেয়।", "en": "Charity extinguishes sin as water extinguishes fire."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি", "en": "Jami'' at-Tirmidhi"}, "check": true}]', 'in_review', 240 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'b02ae94b-e5c7-5ccb-b1e0-546675182642', id, 'fazilat-zakat', '{"bn": "যাকাতের ফজিলত", "en": "Virtues of zakat"}', '{"bn": "যাকাত ইসলামের স্তম্ভ, সম্পদ ও মনকে পবিত্র করে, জান্নাতের পথ সহজ করে; আর না দেওয়ার কঠিন পরিণাম।", "en": "Zakat is a pillar of Islam that purifies wealth and soul and leads to Paradise; withholding it has a severe consequence."}', 'basic', '[{"type": "text", "text": {"bn": "ইসলাম পাঁচটি স্তম্ভের ওপর প্রতিষ্ঠিত: আল্লাহ ছাড়া কোনো ইলাহ নেই ও মুহাম্মাদ ﷺ আল্লাহর রাসুল — এই সাক্ষ্য দেওয়া, নামাজ কায়েম করা, যাকাত দেওয়া, হজ করা এবং রমজানের রোজা রাখা।", "en": "Islam is built on five: testifying there is no god but Allah and Muhammad is His Messenger, establishing prayer, giving zakat, hajj and fasting Ramadan."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৮; সহিহ মুসলিম ১৬", "en": "Sahih al-Bukhari 8; Sahih Muslim 16"}}, {"type": "text", "text": {"bn": "আল্লাহ বলেন: “তাদের সম্পদ থেকে সদকা (যাকাত) গ্রহণ করো, যা দিয়ে তুমি তাদের পবিত্র ও পরিশুদ্ধ করবে।”", "en": "Allah says: “Take from their wealth a charity by which you purify them and cause them increase.”"}}, {"type": "ref", "text": {"bn": "সূরা তাওবা ৯:১০৩", "en": "At-Tawbah 9:103"}}, {"type": "text", "text": {"bn": "আল্লাহ বলেন: “নিশ্চয়ই যারা ঈমান আনে, নেক আমল করে, নামাজ কায়েম করে ও যাকাত দেয়, তাদের প্রতিদান তাদের রবের কাছে; তাদের কোনো ভয় নেই, তারা চিন্তিতও হবে না।”", "en": "Allah says: “Those who believe, do righteous deeds, establish prayer and give zakat will have their reward with their Lord; no fear will be on them, nor will they grieve.”"}}, {"type": "ref", "text": {"bn": "সূরা বাকারা ২:২৭৭", "en": "Al-Baqarah 2:277"}}, {"type": "text", "text": {"bn": "এক ব্যক্তি জিজ্ঞেস করল, এমন আমল বলুন যা আমাকে জান্নাতে নিয়ে যাবে। রাসুল ﷺ বললেন: আল্লাহর ইবাদত করো, তাঁর সঙ্গে কিছু শরিক করো না, নামাজ কায়েম করো, যাকাত দাও এবং আত্মীয়তার সম্পর্ক বজায় রাখো।", "en": "A man asked for a deed that would take him to Paradise. The Prophet ﷺ said: worship Allah without associating anything with Him, establish prayer, give zakat and keep ties of kinship."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৩৯৬; সহিহ মুসলিম ১৩", "en": "Sahih al-Bukhari 1396; Sahih Muslim 13"}}, {"type": "note", "tone": "warn", "text": {"bn": "যাকে আল্লাহ সম্পদ দিয়েছেন কিন্তু সে যাকাত দেয়নি, কিয়ামতের দিন তার সম্পদকে একটি বিষধর টেকো সাপ বানানো হবে, যা তার গলা পেঁচিয়ে ধরে বলবে: আমি তোমার সম্পদ, আমি তোমার সঞ্চয় (সহিহ বুখারি ১৪০৩)।", "en": "Whoever Allah gave wealth and did not pay its zakat, his wealth will be made a bald venomous snake on the Day of Resurrection, coiling around his neck and saying: I am your wealth, I am your treasure (Sahih al-Bukhari 1403)."}}, {"type": "text", "text": {"bn": "যাকাত গরিবের হক, দাতার দয়া নয়; এটি দিলে সম্পদে বরকত আসে এবং মন কৃপণতা থেকে মুক্ত হয়। সদকা সম্পদ কমায় না (সহিহ মুসলিম ২৫৮৮)।", "en": "Zakat is the right of the poor, not a favour from the giver; it brings blessing to wealth and frees the heart from stinginess. Charity does not decrease wealth (Sahih Muslim 2588)."}}, {"type": "note", "tone": "info", "text": {"bn": "যাকাতের নিসাব, হার ও খাত জানতে “যাকাত ও সদকা” বিভাগ দেখুন।", "en": "For nisab, rates and recipients, see the Zakat and Sadaqah section."}}]', 'in_review', 250 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'aa04c452-c96e-5bc6-9552-9b336032151d', id, 'fazilat-hajj-umrah', '{"bn": "হজ ও উমরাহর ফজিলত", "en": "Virtues of hajj and umrah"}', '{"bn": "মাবরুর হজের প্রতিদান জান্নাত; গুনাহমুক্ত হজ মানুষকে নবজাতকের মতো নিষ্পাপ করে দেয়, আর এক উমরাহ থেকে আরেক উমরাহ কাফফারা।", "en": "The reward of an accepted hajj is Paradise; a sin-free hajj leaves one like a newborn, and umrah to umrah is expiation."}', 'basic', '[{"type": "text", "text": {"bn": "আল্লাহ বলেন: “মানুষের ওপর আল্লাহর জন্য এই ঘরের হজ করা ফরজ, যে সেখানে যাওয়ার সামর্থ্য রাখে।”", "en": "Allah says: “Pilgrimage to the House is a duty owed to Allah by people who are able to find a way there.”"}}, {"type": "ref", "text": {"bn": "সূরা আলে ইমরান ৩:৯৭", "en": "Al ''Imran 3:97"}}, {"type": "text", "text": {"bn": "যে আল্লাহর জন্য হজ করে এবং তাতে অশ্লীল কথা ও গুনাহ থেকে বেঁচে থাকে, সে এমনভাবে ফিরে আসে যেন সেদিন মা তাকে জন্ম দিয়েছে।", "en": "Whoever performs hajj for Allah without obscenity or sin returns as on the day his mother bore him."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৫২১; সহিহ মুসলিম ১৩৫০", "en": "Sahih al-Bukhari 1521; Sahih Muslim 1350"}}, {"type": "text", "text": {"bn": "এক উমরাহ থেকে আরেক উমরাহ মাঝখানের গুনাহের কাফফারা, আর মাবরুর (কবুল) হজের প্রতিদান জান্নাত ছাড়া আর কিছু নয়।", "en": "One umrah to the next expiates what is between them, and the reward of an accepted hajj is nothing but Paradise."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৭৭৩; সহিহ মুসলিম ১৩৪৯", "en": "Sahih al-Bukhari 1773; Sahih Muslim 1349"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ-কে জিজ্ঞেস করা হলো, কোন আমল শ্রেষ্ঠ? বললেন: আল্লাহ ও রাসুলের প্রতি ঈমান; তারপর আল্লাহর পথে জিহাদ; তারপর মাবরুর হজ।", "en": "He ﷺ was asked which deed is best. He said: faith in Allah and His Messenger, then jihad in Allah''s path, then an accepted hajj."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ২৬", "en": "Sahih al-Bukhari 26"}}, {"type": "text", "text": {"bn": "আয়েশা (রা.) জিহাদের কথা বললে রাসুল ﷺ বলেন: তোমাদের (নারীদের) জন্য শ্রেষ্ঠ জিহাদ হলো মাবরুর হজ।", "en": "When Aishah (RA) asked about jihad, he ﷺ said: the best jihad for you (women) is an accepted hajj."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৫২০", "en": "Sahih al-Bukhari 1520"}}, {"type": "text", "text": {"bn": "হজ ও উমরাহ পরপর করো, কারণ এ দুটি দারিদ্র্য ও গুনাহ এমনভাবে দূর করে, যেমন হাপর লোহা, সোনা ও রুপার ময়লা দূর করে।", "en": "Follow hajj with umrah, for they remove poverty and sins as the bellows removes impurity from iron, gold and silver."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি; সুনান নাসায়ি", "en": "Jami'' at-Tirmidhi; Sunan an-Nasa''i"}, "check": true}, {"type": "note", "tone": "tip", "text": {"bn": "রমজানে উমরাহ করা হজের সমান সওয়াব (সহিহ মুসলিম ১২৫৬), তবে তা ফরজ হজের বিকল্প নয়।", "en": "Umrah in Ramadan equals hajj in reward (Sahih Muslim 1256), but it does not replace the obligatory hajj."}}, {"type": "note", "tone": "info", "text": {"bn": "হজ ও উমরাহর নিয়ম জানতে “হজ” ও “উমরাহ” বিভাগ দেখুন।", "en": "For how to perform them, see the Hajj and Umrah sections."}}]', 'in_review', 260 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '02578f51-25bd-5c7f-804f-f75ce482fd02', id, 'fazilat-ilm', '{"bn": "দ্বীনি জ্ঞান অর্জনের ফজিলত", "en": "Virtues of seeking knowledge"}', '{"bn": "জ্ঞানের পথে চললে আল্লাহ জান্নাতের পথ সহজ করেন; আল্লাহ যার কল্যাণ চান তাকে দ্বীনের বুঝ দেন।", "en": "Whoever walks a path of knowledge, Allah eases his path to Paradise; when Allah wills good for someone, He gives him understanding of the religion."}', 'basic', '[{"type": "text", "text": {"bn": "আল্লাহ বলেন: “তোমাদের মধ্যে যারা ঈমান এনেছে এবং যাদের জ্ঞান দেওয়া হয়েছে, আল্লাহ তাদের মর্যাদা বহু স্তরে উঁচু করবেন।” এবং: “বলো, যারা জানে আর যারা জানে না, তারা কি সমান?”", "en": "Allah says: “Allah will raise those who have believed among you and those given knowledge by degrees.” And: “Say: are those who know equal to those who do not know?”"}}, {"type": "ref", "text": {"bn": "সূরা মুজাদালা ৫৮:১১; সূরা যুমার ৩৯:৯", "en": "Al-Mujadilah 58:11; Az-Zumar 39:9"}}, {"type": "arabic", "label": {"bn": "কুরআনে শেখানো দোয়া", "en": "A dua taught in the Quran"}, "ar": "رَبِّ زِدْنِي عِلْمًا", "pron": {"bn": "রব্বি যিদনী ইলমা", "en": "Rabbi zidni ''ilma"}, "meaning": {"bn": "হে আমার রব, আমার জ্ঞান বাড়িয়ে দিন।", "en": "My Lord, increase me in knowledge."}, "ref": {"bn": "সূরা ত্বা-হা ২০:১১৪", "en": "Ta-Ha 20:114"}}, {"type": "text", "text": {"bn": "আল্লাহ যার কল্যাণ চান, তাকে দ্বীনের গভীর বুঝ দান করেন।", "en": "When Allah wills good for someone, He gives him understanding of the religion."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৭১; সহিহ মুসলিম ১০৩৭", "en": "Sahih al-Bukhari 71; Sahih Muslim 1037"}}, {"type": "text", "text": {"bn": "যে জ্ঞান অর্জনের জন্য কোনো পথে চলে, আল্লাহ তার জন্য জান্নাতের পথ সহজ করে দেন।", "en": "Whoever travels a path seeking knowledge, Allah makes easy for him a path to Paradise."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৬৯৯", "en": "Sahih Muslim 2699"}}, {"type": "text", "text": {"bn": "ফেরেশতারা জ্ঞান অন্বেষণকারীর সন্তুষ্টিতে তাদের ডানা বিছিয়ে দেন; আলেমদের জন্য আসমান-জমিনের সবাই, এমনকি পানির মাছও ক্ষমা প্রার্থনা করে; আর আলেমরা নবীদের উত্তরাধিকারী।", "en": "The angels lower their wings for the seeker of knowledge out of pleasure; everyone in the heavens and earth, even the fish in the water, seeks forgiveness for the scholar; and the scholars are the heirs of the prophets."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ ৩৬৪১; সুনান তিরমিজি ২৬৮২", "en": "Sunan Abi Dawud 3641; Jami'' at-Tirmidhi 2682"}}, {"type": "text", "text": {"bn": "প্রত্যেক মুসলিমের ওপর জ্ঞান অর্জন করা ফরজ।", "en": "Seeking knowledge is an obligation on every Muslim."}}, {"type": "ref", "text": {"bn": "সুনান ইবনে মাজাহ ২২৪", "en": "Sunan Ibn Majah 224"}}, {"type": "note", "tone": "info", "text": {"bn": "শেষ হাদিসটির প্রতিটি সনদ দুর্বল, তবে অনেক সূত্রে আসায় বেশ কয়েকজন মুহাদ্দিস একে হাসান/সহিহ বলেছেন। এখানে “জ্ঞান” বলতে মূলত সেই দ্বীনি জ্ঞান বোঝায় যা ছাড়া ফরজ ইবাদত ও হালাল-হারাম জানা যায় না।", "en": "Each chain of the last hadith is weak, but due to its many routes several scholars graded it hasan/sahih. “Knowledge” here mainly means the religious knowledge needed for obligatory worship and halal and haram."}}, {"type": "note", "tone": "warn", "text": {"bn": "প্রচলিত কথা “জ্ঞান অর্জনের জন্য প্রয়োজনে চীন দেশে যাও” রাসুল ﷺ-এর হাদিস হিসেবে প্রমাণিত নয়; মুহাদ্দিসদের মতে এটি অত্যন্ত দুর্বল বা জাল।", "en": "The popular saying “seek knowledge even in China” is not established as a hadith; scholars rate it very weak or fabricated."}}]', 'in_review', 270 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '4a90206c-e79e-5390-a225-0569bee9c99c', id, 'fazilat-akhlaq', '{"bn": "উত্তম চরিত্রের ফজিলত", "en": "Virtues of good character"}', '{"bn": "কিয়ামতের দিন মিজানে উত্তম চরিত্রের চেয়ে ভারী কিছু নেই; ভালো চরিত্রের মানুষই শ্রেষ্ঠ মানুষ।", "en": "Nothing is heavier on the scale on the Last Day than good character; the best people are those best in character."}', 'basic', '[{"type": "text", "text": {"bn": "আল্লাহ রাসুল ﷺ সম্পর্কে বলেন: “নিশ্চয়ই তুমি মহান চরিত্রের অধিকারী।”", "en": "Allah says of the Prophet ﷺ: “And indeed, you are of a great moral character.”"}}, {"type": "ref", "text": {"bn": "সূরা কলম ৬৮:৪", "en": "Al-Qalam 68:4"}}, {"type": "text", "text": {"bn": "তোমাদের মধ্যে সর্বোত্তম সে, যার চরিত্র সবচেয়ে সুন্দর।", "en": "The best of you are those with the best character."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৩৫৫৯; সহিহ মুসলিম ২৩২১", "en": "Sahih al-Bukhari 3559; Sahih Muslim 2321"}}, {"type": "text", "text": {"bn": "কিয়ামতের দিন মুমিনের মিজানে উত্তম চরিত্রের চেয়ে ভারী আর কিছু থাকবে না।", "en": "Nothing will be heavier on the believer''s scale on the Day of Resurrection than good character."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি ২০০২; সুনান আবু দাউদ ৪৭৯৯", "en": "Jami'' at-Tirmidhi 2002; Sunan Abi Dawud 4799"}}, {"type": "text", "text": {"bn": "মুমিন তার উত্তম চরিত্রের মাধ্যমে সারা দিন রোজাদার ও সারা রাত নামাজ আদায়কারীর মর্যাদা লাভ করে।", "en": "By good character a believer reaches the rank of one who fasts by day and prays by night."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ ৪৭৯৮", "en": "Sunan Abi Dawud 4798"}}, {"type": "text", "text": {"bn": "সবচেয়ে বেশি যে জিনিস মানুষকে জান্নাতে নিয়ে যাবে তা হলো আল্লাহভীতি ও উত্তম চরিত্র।", "en": "What most admits people into Paradise is fear of Allah and good character."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি ২০০৪", "en": "Jami'' at-Tirmidhi 2004"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: যে হকের ওপর থেকেও ঝগড়া ছেড়ে দেয়, তার জন্য আমি জান্নাতের পাশে একটি ঘরের জামিন; যে ঠাট্টা করেও মিথ্যা বলে না, তার জন্য জান্নাতের মাঝখানে একটি ঘর; আর যার চরিত্র উত্তম, তার জন্য জান্নাতের সর্বোচ্চ স্থানে একটি ঘর।", "en": "I guarantee a house on the outskirts of Paradise for whoever leaves arguing even when right, a house in its middle for whoever leaves lying even in jest, and a house in its highest part for whoever has good character."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ ৪৮০০", "en": "Sunan Abi Dawud 4800"}}, {"type": "note", "tone": "tip", "text": {"bn": "চরিত্র চর্চা শুরু হয় ঘর থেকে: পরিবারের সঙ্গে নরম কথা, রাগ নিয়ন্ত্রণ, ক্ষমা করা ও প্রতিশ্রুতি রক্ষা।", "en": "Character begins at home: gentle words with family, controlling anger, forgiving and keeping promises."}}]', 'in_review', 280 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'fc15c20b-ddd8-5144-839f-d893049401da', id, 'fazilat-parents', '{"bn": "মা-বাবার সঙ্গে সদ্ব্যবহারের ফজিলত", "en": "Virtues of kindness to parents"}', '{"bn": "আল্লাহর ইবাদতের পরেই মা-বাবার প্রতি সদ্ব্যবহারের নির্দেশ; মায়ের হক তিন গুণ, আর বৃদ্ধ মা-বাবার সেবা জান্নাতের পথ।", "en": "After worshipping Allah comes kindness to parents; the mother''s right is threefold, and serving elderly parents is a path to Paradise."}', 'basic', '[{"type": "text", "text": {"bn": "আল্লাহ বলেন: “তোমার রব নির্দেশ দিয়েছেন, তাঁকে ছাড়া কারও ইবাদত করো না এবং মা-বাবার সঙ্গে সদ্ব্যবহার করো। তাদের একজন বা দুজনই বার্ধক্যে পৌঁছালে তাদের “উফ” পর্যন্ত বলো না, ধমক দিয়ো না, বরং সম্মানের সঙ্গে নরম কথা বলো।”", "en": "Allah says: “Your Lord has decreed that you worship none but Him, and be good to parents. If one or both reach old age with you, do not say to them ‘uff’ or repel them, but speak to them a noble word.”"}}, {"type": "ref", "text": {"bn": "সূরা বনি ইসরাঈল ১৭:২৩–২৪", "en": "Al-Isra 17:23–24"}}, {"type": "arabic", "label": {"bn": "মা-বাবার জন্য দোয়া", "en": "Dua for parents"}, "ar": "رَبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا", "pron": {"bn": "রব্বির হামহুমা কামা রব্বাইয়ানী সাগীরা", "en": "Rabbir-hamhuma kama rabbayani saghira"}, "meaning": {"bn": "হে আমার রব, তাদের প্রতি দয়া করুন, যেমন তারা শৈশবে আমাকে লালন-পালন করেছেন।", "en": "My Lord, have mercy on them as they raised me when I was small."}, "ref": {"bn": "সূরা বনি ইসরাঈল ১৭:২৪", "en": "Al-Isra 17:24"}}, {"type": "text", "text": {"bn": "আল্লাহর কাছে প্রিয় আমলের তালিকায় সময়মতো নামাজের পরেই মা-বাবার সঙ্গে সদ্ব্যবহার।", "en": "In the list of deeds beloved to Allah, kindness to parents comes right after prayer on time."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৫২৭", "en": "Sahih al-Bukhari 527"}}, {"type": "text", "text": {"bn": "এক ব্যক্তি জিজ্ঞেস করল, আমার সদ্ব্যবহারের সবচেয়ে বেশি হকদার কে? রাসুল ﷺ বললেন: তোমার মা। তারপর? তোমার মা। তারপর? তোমার মা। তারপর? তোমার বাবা।", "en": "A man asked who most deserves his good companionship. He ﷺ said: your mother. Then? Your mother. Then? Your mother. Then? Your father."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৫৯৭১; সহিহ মুসলিম ২৫৪৮", "en": "Sahih al-Bukhari 5971; Sahih Muslim 2548"}}, {"type": "text", "text": {"bn": "তার নাক ধুলোয় মলিন হোক, যে মা-বাবার একজন বা দুজনকেই বার্ধক্যে পেল, অথচ (তাদের সেবা করে) জান্নাতে যেতে পারল না।", "en": "May his nose be in the dust, the one who finds one or both parents in old age and does not enter Paradise (by serving them)."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৫৫১", "en": "Sahih Muslim 2551"}}, {"type": "text", "text": {"bn": "রবের সন্তুষ্টি বাবার সন্তুষ্টিতে, আর রবের অসন্তুষ্টি বাবার অসন্তুষ্টিতে।", "en": "The Lord''s pleasure lies in the father''s pleasure, and His displeasure in the father''s displeasure."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি ১৮৯৯", "en": "Jami'' at-Tirmidhi 1899"}}, {"type": "text", "text": {"bn": "এক সাহাবি জিহাদে যাওয়ার অনুমতি চাইলে রাসুল ﷺ জিজ্ঞেস করলেন, তোমার মা আছেন? তিনি হ্যাঁ বললে রাসুল ﷺ বললেন: তাঁর সেবায় লেগে থাকো, কারণ জান্নাত তাঁর পায়ের কাছে।", "en": "A Companion sought permission for jihad; the Prophet ﷺ asked if his mother was alive, then said: stay with her, for Paradise is at her feet."}}, {"type": "ref", "text": {"bn": "সুনান নাসায়ি", "en": "Sunan an-Nasa''i"}, "check": true}, {"type": "note", "tone": "info", "text": {"bn": "“মায়ের পায়ের নিচে সন্তানের জান্নাত” — প্রচলিত এই শব্দে বর্ণনাটি দুর্বল; তবে উপরের নাসায়ির বর্ণনাটি একই অর্থে এবং মুহাদ্দিসদের মতে হাসান।", "en": "The popular wording “Paradise lies under the feet of mothers” is weak, but the an-Nasa''i narration above carries the same meaning and is graded hasan."}}, {"type": "note", "tone": "warn", "text": {"bn": "মা-বাবার অবাধ্যতা শিরকের পরেই সবচেয়ে বড় গুনাহগুলোর একটি (সহিহ বুখারি ২৬৫৪)।", "en": "Disobedience to parents is among the greatest sins, mentioned right after shirk (Sahih al-Bukhari 2654)."}}, {"type": "note", "tone": "tip", "text": {"bn": "মা-বাবা মারা গেলেও তাদের জন্য দোয়া, তাদের পক্ষ থেকে সদকা এবং তাদের বন্ধু ও আত্মীয়দের সম্মান করার মাধ্যমে সদ্ব্যবহার চালিয়ে যাওয়া যায় (সহিহ মুসলিম ১৬৩১)।", "en": "Even after they pass away, kindness continues through dua, charity on their behalf and honouring their friends and relatives (Sahih Muslim 1631)."}}]', 'in_review', 290 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '914fa59e-fe6f-50ca-bc7e-e7258654640d', id, 'fazilat-silat-rahim', '{"bn": "আত্মীয়তার সম্পর্ক রক্ষার ফজিলত", "en": "Virtues of keeping ties of kinship"}', '{"bn": "আত্মীয়তার সম্পর্ক রক্ষা করলে রিজিক ও আয়ু বরকতময় হয়; সম্পর্ক ছিন্নকারী জান্নাতে যাবে না।", "en": "Keeping ties of kinship brings blessing in provision and life; one who cuts them will not enter Paradise."}', 'basic', '[{"type": "text", "text": {"bn": "আল্লাহ বলেন: “আল্লাহকে ভয় করো, যাঁর নামে তোমরা একে অপরের কাছে চাও, এবং আত্মীয়তার সম্পর্কের ব্যাপারে সতর্ক থাকো।”", "en": "Allah says: “Fear Allah, through whom you ask one another, and the wombs (ties of kinship).”"}}, {"type": "ref", "text": {"bn": "সূরা নিসা ৪:১", "en": "An-Nisa 4:1"}}, {"type": "text", "text": {"bn": "যে চায় তার রিজিক প্রশস্ত হোক এবং আয়ু বাড়ুক, সে যেন আত্মীয়তার সম্পর্ক বজায় রাখে।", "en": "Whoever would like his provision expanded and his life extended, let him keep ties of kinship."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৫৯৮৬; সহিহ মুসলিম ২৫৫৭", "en": "Sahih al-Bukhari 5986; Sahih Muslim 2557"}}, {"type": "text", "text": {"bn": "প্রকৃত সম্পর্ক রক্ষাকারী সে নয়, যে শুধু প্রতিদানে সম্পর্ক রাখে; বরং সে-ই প্রকৃত রক্ষাকারী, যার সঙ্গে সম্পর্ক ছিন্ন করা হলেও সে তা জোড়া লাগায়।", "en": "The one who maintains ties is not the one who merely reciprocates; it is the one who rejoins them when they are cut."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৫৯৯১", "en": "Sahih al-Bukhari 5991"}}, {"type": "text", "text": {"bn": "এক ব্যক্তি বলল, আমার আত্মীয়দের সঙ্গে সম্পর্ক রাখি, তারা ছিন্ন করে; ভালো করি, তারা মন্দ করে। রাসুল ﷺ বললেন: তুমি যেমন বললে তেমন হলে তুমি যেন তাদের মুখে গরম ছাই পুরে দিচ্ছ, আর যতক্ষণ তুমি এমন থাকবে, আল্লাহর পক্ষ থেকে একজন সাহায্যকারী তোমার সঙ্গে থাকবে।", "en": "A man said: I keep ties with my relatives and they cut me; I do good to them and they harm me. He ﷺ said: if you are as you say, it is as if you feed them hot ashes, and a helper from Allah will remain with you as long as you continue."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৫৫৮", "en": "Sahih Muslim 2558"}}, {"type": "note", "tone": "warn", "text": {"bn": "আত্মীয়তার সম্পর্ক ছিন্নকারী জান্নাতে প্রবেশ করবে না (সহিহ বুখারি ৫৯৮৪)।", "en": "The one who severs ties of kinship will not enter Paradise (Sahih al-Bukhari 5984)."}}, {"type": "note", "tone": "tip", "text": {"bn": "নিয়মিত খোঁজখবর নেওয়া, ফোন করা, উপহার দেওয়া, বিপদে পাশে থাকা — সবই সম্পর্ক রক্ষা; অভাবী আত্মীয়কে সদকা দিলে সদকা ও আত্মীয়তা দুটোরই সওয়াব।", "en": "Checking in, calling, giving gifts and standing by them in hardship all keep ties; charity to a needy relative earns the reward of both charity and kinship."}}]', 'in_review', 300 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'd5f8612d-cd3e-56cf-b756-7c136698a586', id, 'fazilat-sabr', '{"bn": "সবর (ধৈর্য)-এর ফজিলত", "en": "Virtues of patience (sabr)"}', '{"bn": "আল্লাহ ধৈর্যশীলদের সঙ্গে আছেন; তাদের প্রতিদান হিসাব ছাড়া, আর ছোট কষ্টেও গুনাহ মাফ হয়।", "en": "Allah is with the patient; their reward is without measure, and even small hardships erase sins."}', 'basic', '[{"type": "text", "text": {"bn": "আল্লাহ বলেন: “হে মুমিনগণ, ধৈর্য ও নামাজের মাধ্যমে সাহায্য চাও; নিশ্চয়ই আল্লাহ ধৈর্যশীলদের সঙ্গে আছেন।” আরও বলেন: “ধৈর্যশীলদের প্রতিদান দেওয়া হবে হিসাব ছাড়াই।”", "en": "Allah says: “O you who believe, seek help through patience and prayer; indeed Allah is with the patient.” And: “The patient will be given their reward without account.”"}}, {"type": "ref", "text": {"bn": "সূরা বাকারা ২:১৫৩; সূরা যুমার ৩৯:১০", "en": "Al-Baqarah 2:153; Az-Zumar 39:10"}}, {"type": "text", "text": {"bn": "“আমি অবশ্যই তোমাদের পরীক্ষা করব কিছু ভয়, ক্ষুধা এবং সম্পদ, জীবন ও ফসলের ক্ষতি দিয়ে; আর ধৈর্যশীলদের সুসংবাদ দাও — যারা বিপদে পড়লে বলে: আমরা আল্লাহর জন্য, আর তাঁর কাছেই ফিরে যাব। তাদের ওপর রবের পক্ষ থেকে রহমত ও অনুগ্রহ, আর তারাই সঠিক পথে আছে।”", "en": "“We will surely test you with some fear, hunger and loss of wealth, lives and fruits; but give good news to the patient, who say when struck by calamity: ‘To Allah we belong and to Him we return.’ Upon them are blessings and mercy from their Lord, and they are the rightly guided.”"}}, {"type": "ref", "text": {"bn": "সূরা বাকারা ২:১৫৫–১৫৭", "en": "Al-Baqarah 2:155–157"}}, {"type": "text", "text": {"bn": "ধৈর্যের চেয়ে উত্তম ও প্রশস্ত দান আর কাউকে দেওয়া হয়নি।", "en": "No one has been given a gift better and more vast than patience."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৪৬৯; সহিহ মুসলিম ১০৫৩", "en": "Sahih al-Bukhari 1469; Sahih Muslim 1053"}}, {"type": "text", "text": {"bn": "মুমিনের ব্যাপারটি আশ্চর্যজনক; তার সবকিছুই কল্যাণকর। সুখ পেলে শোকর করে, তা তার জন্য কল্যাণ; বিপদে পড়লে সবর করে, তাও তার জন্য কল্যাণ।", "en": "How wonderful is the affair of the believer; all of it is good. If good befalls him he is grateful, and that is good for him; if harm befalls him he is patient, and that is good for him."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৯৯৯", "en": "Sahih Muslim 2999"}}, {"type": "text", "text": {"bn": "মুসলিমের যে কোনো ক্লান্তি, অসুখ, দুশ্চিন্তা, দুঃখ, কষ্ট ও মনোবেদনা, এমনকি একটি কাঁটা বিঁধলেও, আল্লাহ এর মাধ্যমে তার গুনাহ মাফ করে দেন।", "en": "No fatigue, illness, worry, grief, harm or distress befalls a Muslim, even a thorn''s prick, except that Allah expiates some of his sins by it."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৫৬৪১; সহিহ মুসলিম ২৫৭৩", "en": "Sahih al-Bukhari 5641; Sahih Muslim 2573"}}, {"type": "text", "text": {"bn": "প্রকৃত সবর হলো বিপদের প্রথম আঘাতের সময় ধৈর্য ধরা।", "en": "True patience is at the first stroke of calamity."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১২৮৩; সহিহ মুসলিম ৯২৬", "en": "Sahih al-Bukhari 1283; Sahih Muslim 926"}}, {"type": "arabic", "label": {"bn": "বিপদের সময় দোয়া", "en": "Dua at a time of loss"}, "ar": "إِنَّا لِلّٰهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، اللّٰهُمَّ أْجُرْنِي فِي مُصِيبَتِي، وَأَخْلِفْ لِي خَيْرًا مِنْهَا", "pron": {"bn": "ইন্না লিল্লাহি ওয়া ইন্না ইলাইহি রাজিউন, আল্লাহুম্মা''জুরনী ফী মুসীবাতী, ওয়া আখলিফ লী খাইরাম মিনহা", "en": "Inna lillahi wa inna ilayhi raji''un, Allahumma''jurni fi musibati, wa akhlif li khayram minha"}, "meaning": {"bn": "আমরা আল্লাহর জন্য এবং তাঁর কাছেই ফিরে যাব। হে আল্লাহ, আমার এই বিপদে আমাকে প্রতিদান দিন এবং এর বদলে এর চেয়ে উত্তম কিছু দিন।", "en": "To Allah we belong and to Him we return. O Allah, reward me in my affliction and replace it for me with something better."}, "ref": {"bn": "সহিহ মুসলিম ৯১৮", "en": "Sahih Muslim 918"}}, {"type": "text", "text": {"bn": "উম্মে সালামা (রা.) স্বামী আবু সালামার মৃত্যুর পর এই দোয়া পড়েছিলেন, আর আল্লাহ তাঁকে বদলে রাসুল ﷺ-কে স্বামী হিসেবে দিয়েছিলেন।", "en": "Umm Salamah (RA) said this after her husband Abu Salamah died, and Allah replaced him for her with the Prophet ﷺ."}}]', 'in_review', 310 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '139b88d1-d10f-51e2-8624-92ef25bc7710', id, 'fazilat-rogi-dekha', '{"bn": "রোগী দেখতে যাওয়ার ফজিলত", "en": "Virtues of visiting the sick"}', '{"bn": "রোগী দেখতে যাওয়া মুসলিমের হক; যতক্ষণ রোগীর কাছে থাকে, ততক্ষণ সে জান্নাতের বাগানে থাকে।", "en": "Visiting the sick is a Muslim''s right; while with the sick, the visitor is in the harvest of Paradise."}', 'basic', '[{"type": "text", "text": {"bn": "এক মুসলিমের ওপর আরেক মুসলিমের পাঁচটি হক: সালামের জবাব দেওয়া, রোগী দেখতে যাওয়া, জানাযার সঙ্গে যাওয়া, দাওয়াত কবুল করা এবং হাঁচিদাতার জবাব দেওয়া।", "en": "A Muslim has five rights over another: returning the greeting, visiting the sick, following the funeral, accepting the invitation and replying to one who sneezes."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১২৪০; সহিহ মুসলিম ২১৬২", "en": "Sahih al-Bukhari 1240; Sahih Muslim 2162"}}, {"type": "text", "text": {"bn": "যে মুসলিম তার অসুস্থ ভাইকে দেখতে যায়, সে ফিরে আসা পর্যন্ত জান্নাতের বাগানে (ফল আহরণে) থাকে।", "en": "Whoever visits a sick Muslim remains in the harvest of Paradise until he returns."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৫৬৮", "en": "Sahih Muslim 2568"}}, {"type": "text", "text": {"bn": "হাদিসে কুদসিতে আল্লাহ কিয়ামতের দিন বলবেন: হে আদম সন্তান, আমি অসুস্থ ছিলাম, তুমি আমাকে দেখতে আসোনি। সে বলবে: আপনি তো জগতের রব, কীভাবে দেখতে যাব? আল্লাহ বলবেন: তুমি কি জানতে না আমার অমুক বান্দা অসুস্থ ছিল? তাকে দেখতে গেলে আমাকে তার কাছেই পেতে।", "en": "In a hadith qudsi, Allah will say on the Last Day: O son of Adam, I was ill and you did not visit Me. He will say: how could I, when You are Lord of the worlds? He will say: did you not know My servant so-and-so was ill? Had you visited him, you would have found Me with him."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৫৬৯", "en": "Sahih Muslim 2569"}}, {"type": "text", "text": {"bn": "কোনো মুসলিম সকালে রোগী দেখতে গেলে সন্ধ্যা পর্যন্ত সত্তর হাজার ফেরেশতা তার জন্য দোয়া করে, আর সন্ধ্যায় গেলে সকাল পর্যন্ত।", "en": "If a Muslim visits a sick person in the morning, seventy thousand angels pray for him until evening, and if in the evening, until morning."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি", "en": "Jami'' at-Tirmidhi"}, "check": true}, {"type": "heading", "text": {"bn": "রোগীর জন্য দোয়া", "en": "Dua for the sick"}}, {"type": "arabic", "ar": "لَا بَأْسَ، طَهُورٌ إِنْ شَاءَ اللّٰهُ", "pron": {"bn": "লা বা''সা, তাহূরুন ইনশাআল্লাহ", "en": "La ba''s, tahurun in sha Allah"}, "meaning": {"bn": "কোনো চিন্তা নেই, ইনশাআল্লাহ এটি (গুনাহ থেকে) পবিত্রকারী।", "en": "No harm; it is a purification, if Allah wills."}, "ref": {"bn": "সহিহ বুখারি", "en": "Sahih al-Bukhari"}, "check": true}, {"type": "arabic", "label": {"bn": "সাতবার", "en": "Seven times"}, "ar": "أَسْأَلُ اللّٰهَ الْعَظِيمَ، رَبَّ الْعَرْشِ الْعَظِيمِ، أَنْ يَشْفِيَكَ", "pron": {"bn": "আসআলুল্লাহাল আযীম, রব্বাল আরশিল আযীম, আঁই ইয়াশফিয়াক", "en": "As''alullahal-''azim, rabbal-''arshil-''azim, an yashfiyak"}, "meaning": {"bn": "আমি মহান আল্লাহর কাছে, যিনি মহান আরশের রব, প্রার্থনা করছি তিনি যেন তোমাকে সুস্থ করেন।", "en": "I ask Allah the Magnificent, Lord of the magnificent Throne, to cure you."}, "ref": {"bn": "সুনান আবু দাউদ; সুনান তিরমিজি", "en": "Sunan Abi Dawud; Jami'' at-Tirmidhi"}, "check": true}, {"type": "note", "tone": "tip", "text": {"bn": "রোগীর কাছে বেশি সময় বসবেন না, আশার কথা বলুন, আর তাঁর কাছে নিজের জন্যও দোয়া চাইতে পারেন।", "en": "Do not stay too long, speak words of hope, and you may ask the sick person to pray for you."}}]', 'in_review', 320 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '6cf0c2f1-7ca9-5195-a929-66c88e5963a3', id, 'fazilat-salam-hasi', '{"bn": "সালাম, হাসিমুখ ও রাস্তা থেকে কষ্টদায়ক জিনিস সরানো", "en": "Salam, a smiling face and removing harm from the road"}', '{"bn": "ছোট ছোট আমলের বড় সওয়াব: সালামের প্রসার ভালোবাসা আনে, হাসিমুখ সদকা, আর রাস্তা থেকে কাঁটা সরিয়ে একজন জান্নাত পেয়েছে।", "en": "Small deeds, great rewards: spreading salam brings love, a smile is charity, and a man entered Paradise for removing a thorny branch from the road."}', 'basic', '[{"type": "heading", "text": {"bn": "সালামের প্রসার", "en": "Spreading salam"}}, {"type": "text", "text": {"bn": "তোমরা ঈমান না আনা পর্যন্ত জান্নাতে যাবে না, আর পরস্পরকে না ভালোবাসা পর্যন্ত ঈমানদার হবে না। আমি কি তোমাদের এমন জিনিস বলব না যা করলে তোমরা পরস্পরকে ভালোবাসবে? তোমাদের মাঝে সালামের প্রসার ঘটাও।", "en": "You will not enter Paradise until you believe, and you will not believe until you love one another. Shall I tell you something that, if you do it, you will love one another? Spread salam among you."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৫৪", "en": "Sahih Muslim 54"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ-কে জিজ্ঞেস করা হলো, ইসলামের কোন কাজ উত্তম? বললেন: খাবার খাওয়ানো এবং পরিচিত-অপরিচিত সবাইকে সালাম দেওয়া।", "en": "He ﷺ was asked which act of Islam is best. He said: feeding people and greeting those you know and those you do not."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১২; সহিহ মুসলিম ৩৯", "en": "Sahih al-Bukhari 12; Sahih Muslim 39"}}, {"type": "arabic", "label": {"bn": "পূর্ণ সালাম", "en": "The full greeting"}, "ar": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللّٰهِ وَبَرَكَاتُهُ", "pron": {"bn": "আসসালামু আলাইকুম ওয়া রহমাতুল্লাহি ওয়া বারাকাতুহ", "en": "As-salamu ''alaykum wa rahmatullahi wa barakatuh"}, "meaning": {"bn": "আপনার ওপর শান্তি, আল্লাহর রহমত ও তাঁর বরকত বর্ষিত হোক।", "en": "Peace be upon you, and the mercy of Allah and His blessings."}}, {"type": "text", "text": {"bn": "শুধু “আসসালামু আলাইকুম” বললে দশ নেকি, “ওয়া রহমাতুল্লাহ” যোগ করলে বিশ, আর “ওয়া বারাকাতুহ” যোগ করলে ত্রিশ নেকি।", "en": "Saying “As-salamu ''alaykum” earns ten good deeds, adding “wa rahmatullah” twenty, and adding “wa barakatuh” thirty."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ; সুনান তিরমিজি", "en": "Sunan Abi Dawud; Jami'' at-Tirmidhi"}, "check": true}, {"type": "text", "text": {"bn": "আল্লাহর কাছে সবচেয়ে নিকটবর্তী সে, যে আগে সালাম দেয়।", "en": "The closest of people to Allah is the one who begins the greeting."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ ৫১৯৭", "en": "Sunan Abi Dawud 5197"}}, {"type": "heading", "text": {"bn": "হাসিমুখ", "en": "A smiling face"}}, {"type": "text", "text": {"bn": "তোমার ভাইয়ের সামনে তোমার হাসিমুখ সদকা।", "en": "Your smile in the face of your brother is charity."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি ১৯৫৬", "en": "Jami'' at-Tirmidhi 1956"}}, {"type": "text", "text": {"bn": "কোনো ভালো কাজকে তুচ্ছ মনে কোরো না, এমনকি তোমার ভাইয়ের সঙ্গে হাসিমুখে দেখা করাও।", "en": "Do not belittle any good deed, even meeting your brother with a cheerful face."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৬২৬", "en": "Sahih Muslim 2626"}}, {"type": "heading", "text": {"bn": "রাস্তা থেকে কষ্টদায়ক জিনিস সরানো", "en": "Removing harm from the road"}}, {"type": "text", "text": {"bn": "ঈমানের সত্তরের বেশি শাখা আছে; সর্বোচ্চটি “লা ইলাহা ইল্লাল্লাহ” বলা, আর সর্বনিম্নটি রাস্তা থেকে কষ্টদায়ক জিনিস সরানো। লজ্জাশীলতাও ঈমানের একটি শাখা।", "en": "Faith has seventy-odd branches; the highest is saying “La ilaha illallah” and the lowest is removing something harmful from the road. Modesty is also a branch of faith."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৩৫", "en": "Sahih Muslim 35"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: আমি এক ব্যক্তিকে জান্নাতে ঘুরে বেড়াতে দেখেছি, শুধু এই কারণে যে সে রাস্তার মাঝখান থেকে একটি গাছ (কাঁটাযুক্ত ডাল) কেটে সরিয়েছিল, যা মানুষকে কষ্ট দিত।", "en": "I saw a man moving about in Paradise because of a tree he cut from the middle of the road that used to harm people."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৬৫২; সহিহ মুসলিম ১৯১৪", "en": "Sahih al-Bukhari 652; Sahih Muslim 1914"}}, {"type": "note", "tone": "tip", "text": {"bn": "আজকের জীবনে এর উদাহরণ: রাস্তায় কলার খোসা, কাচ বা ইট সরানো, ময়লা নির্দিষ্ট জায়গায় ফেলা, আর গাড়ি এমনভাবে না রাখা যাতে পথচারীর কষ্ট হয়।", "en": "Today this includes removing banana peels, glass or bricks from the road, putting rubbish in its place and not parking in a way that blocks pedestrians."}}]', 'in_review', 330 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'fd75b63c-48ac-5303-996a-55ec55d75e43', id, 'fazilat-khabar-khawano', '{"bn": "মানুষকে খাবার খাওয়ানোর ফজিলত", "en": "Virtues of feeding people"}', '{"bn": "খাবার খাওয়ানো ইসলামের উত্তম কাজ; সালাম, খাবার ও রাতের নামাজে শান্তির সঙ্গে জান্নাত।", "en": "Feeding people is among the best acts of Islam; salam, food and night prayer lead to Paradise in peace."}', 'basic', '[{"type": "text", "text": {"bn": "আল্লাহ নেককারদের প্রশংসায় বলেন: “তারা আল্লাহর ভালোবাসায় মিসকিন, এতিম ও বন্দিকে খাবার খাওয়ায় (এবং বলে): আমরা কেবল আল্লাহর সন্তুষ্টির জন্য তোমাদের খাওয়াই; তোমাদের কাছে কোনো প্রতিদান বা কৃতজ্ঞতা চাই না।”", "en": "Allah praises the righteous: “They give food, despite love for it, to the poor, the orphan and the captive, (saying) we feed you only for the sake of Allah; we want from you no reward or thanks.”"}}, {"type": "ref", "text": {"bn": "সূরা দাহর ৭৬:৮–৯", "en": "Al-Insan 76:8–9"}}, {"type": "text", "text": {"bn": "ইসলামের উত্তম কাজ হলো খাবার খাওয়ানো এবং পরিচিত-অপরিচিত সবাইকে সালাম দেওয়া।", "en": "The best act in Islam is feeding people and greeting those you know and do not know."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১২", "en": "Sahih al-Bukhari 12"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ মদিনায় এসে প্রথম যে কথাগুলো বলেছিলেন: হে লোকসকল, সালামের প্রসার ঘটাও, খাবার খাওয়াও, মানুষ যখন ঘুমিয়ে থাকে তখন নামাজ পড়ো, তাহলে শান্তির সঙ্গে জান্নাতে প্রবেশ করবে।", "en": "Among the first words of the Prophet ﷺ in Madinah: O people, spread salam, feed others, and pray at night while people sleep, and you will enter Paradise in peace."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি ২৪৮৫; সুনান ইবনে মাজাহ ১৩৩৪", "en": "Jami'' at-Tirmidhi 2485; Sunan Ibn Majah 1334"}}, {"type": "text", "text": {"bn": "ক্ষুধার্তকে খাবার দাও, রোগীকে দেখতে যাও এবং বন্দিকে মুক্ত করো।", "en": "Feed the hungry, visit the sick and free the captive."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৫৩৭৩", "en": "Sahih al-Bukhari 5373"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ আবু যর (রা.)-কে বলেছিলেন: তরকারি রান্না করলে ঝোল একটু বাড়িয়ে দাও এবং প্রতিবেশীর খোঁজ নাও।", "en": "The Prophet ﷺ told Abu Dharr (RA): when you cook a stew, add more water and look after your neighbours."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৬২৫", "en": "Sahih Muslim 2625"}}, {"type": "text", "text": {"bn": "যে রোজাদারকে ইফতার করায়, সে রোজাদারের সমান সওয়াব পায়, অথচ রোজাদারের সওয়াব একটুও কমে না।", "en": "Whoever gives a fasting person food to break his fast earns the same reward without decreasing his."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি ৮০৭", "en": "Jami'' at-Tirmidhi 807"}}, {"type": "note", "tone": "tip", "text": {"bn": "দাওয়াতে শুধু ধনী আত্মীয়দের নয়, গরিবদেরও ডাকুন; শুধু ধনীদের দাওয়াত দেওয়া ওয়ালিমাকে রাসুল ﷺ সবচেয়ে মন্দ খাবার বলেছেন (সহিহ মুসলিম ১৪৩২)।", "en": "Invite the poor, not only wealthy relatives; the Prophet ﷺ called a wedding feast to which only the rich are invited the worst food (Sahih Muslim 1432)."}}]', 'in_review', 340 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'cba49f6b-1da9-5c57-8b67-db4313e63ef1', id, 'fazilat-sat-byabsa', '{"bn": "ব্যবসায় সততার ফজিলত", "en": "Virtues of honesty in trade"}', '{"bn": "সত্য বলা ও দোষ প্রকাশ করলে ব্যবসায় বরকত আসে; সৎ ও বিশ্বস্ত ব্যবসায়ী কিয়ামতে নবী, সিদ্দিক ও শহিদদের সঙ্গী।", "en": "Truthfulness and disclosing defects bring blessing to trade; the honest, trustworthy merchant will be with the prophets, the truthful and the martyrs."}', 'basic', '[{"type": "text", "text": {"bn": "আল্লাহ বলেন: “ধ্বংস তাদের জন্য যারা মাপে কম দেয়; যারা মানুষের কাছ থেকে নেওয়ার সময় পূর্ণ মাপে নেয়, আর তাদের মেপে বা ওজন করে দেওয়ার সময় কম দেয়।”", "en": "Allah says: “Woe to those who give less; who take full measure from people but give less when they measure or weigh for them.”"}}, {"type": "ref", "text": {"bn": "সূরা মুতাফফিফিন ৮৩:১–৩", "en": "Al-Mutaffifin 83:1–3"}}, {"type": "text", "text": {"bn": "ক্রেতা-বিক্রেতা আলাদা না হওয়া পর্যন্ত চুক্তি বাতিলের অধিকার রাখে; যদি তারা সত্য বলে ও (পণ্যের দোষ) স্পষ্ট করে, তাদের বেচাকেনায় বরকত দেওয়া হয়; আর যদি গোপন করে ও মিথ্যা বলে, তাদের বেচাকেনার বরকত মুছে দেওয়া হয়।", "en": "Buyer and seller may cancel until they part; if they are truthful and make things clear, their sale is blessed; if they conceal and lie, the blessing of their sale is erased."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ২০৭৯; সহিহ মুসলিম ১৫৩২", "en": "Sahih al-Bukhari 2079; Sahih Muslim 1532"}}, {"type": "text", "text": {"bn": "আল্লাহ সেই ব্যক্তির ওপর রহম করুন, যে বিক্রির সময়, কেনার সময় এবং পাওনা চাওয়ার সময় নম্র থাকে।", "en": "May Allah have mercy on a man who is lenient when he sells, when he buys and when he asks for repayment."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ২০৭৬", "en": "Sahih al-Bukhari 2076"}}, {"type": "text", "text": {"bn": "এক ব্যবসায়ী মানুষকে ঋণ দিত এবং কর্মচারীকে বলত, অভাবী কাউকে পেলে ছাড় দিয়ো, হয়তো আল্লাহ আমাদের ছাড় দেবেন। ফলে আল্লাহ তাকে ক্ষমা করে দিলেন।", "en": "A merchant used to lend to people and tell his servant: if you find someone in hardship, let him off, perhaps Allah will let us off. So Allah forgave him."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ২০৭৮; সহিহ মুসলিম ১৫৬২", "en": "Sahih al-Bukhari 2078; Sahih Muslim 1562"}}, {"type": "text", "text": {"bn": "সত্যবাদী ও বিশ্বস্ত ব্যবসায়ী (কিয়ামতের দিন) নবী, সিদ্দিক ও শহিদদের সঙ্গে থাকবে।", "en": "The truthful, trustworthy merchant will be with the prophets, the truthful and the martyrs."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি ১২০৯", "en": "Jami'' at-Tirmidhi 1209"}}, {"type": "note", "tone": "info", "text": {"bn": "ইমাম তিরমিজি এই শেষ হাদিসটিকে হাসান বলেছেন; কিছু মুহাদ্দিস এর সনদকে দুর্বল বলেছেন, তবে অর্থটি অন্যান্য সহিহ দলিলের সঙ্গে সামঞ্জস্যপূর্ণ।", "en": "At-Tirmidhi graded this last hadith hasan; some scholars consider its chain weak, though its meaning agrees with other sahih evidence."}}, {"type": "note", "tone": "warn", "text": {"bn": "রাসুল ﷺ খাদ্যের স্তূপে হাত ঢুকিয়ে ভেজা অংশ পেয়ে বললেন: যে প্রতারণা করে, সে আমার দলভুক্ত নয় (সহিহ মুসলিম ১০২)।", "en": "The Prophet ﷺ put his hand into a pile of grain and found it wet inside, and said: whoever cheats is not of us (Sahih Muslim 102)."}}]', 'in_review', 350 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('6beb7843-1fd6-586f-8ef5-5e2ab461a0d9', 1, 'الرَّحْمٰنُ', '{"bn": "আর-রহমান", "en": "Ar-Rahman"}', '{"bn": "পরম দয়াময়", "en": "The Most Gracious"}', '{"bn": "যাঁর দয়া দুনিয়াতে সব সৃষ্টির জন্য বিস্তৃত। তাওবা ছাড়া কুরআনের প্রতিটি সূরার শুরুতে বিসমিল্লাহর মধ্যে এই নাম আছে।", "en": "The One whose mercy reaches all creation in this world. It is in the Basmalah that opens every surah except At-Tawbah."}', '{"bn": "সূরা ফাতিহা ১:৩", "en": "Al-Fatihah 1:3"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('73832d2e-7d94-5823-b9c5-716ac0ab4911', 2, 'الرَّحِيمُ', '{"bn": "আর-রহিম", "en": "Ar-Rahim"}', '{"bn": "অতিশয় দয়ালু", "en": "The Most Merciful"}', '{"bn": "যিনি বিশেষভাবে মুমিনদের প্রতি দয়া করেন। কুরআনে আছে: “আর তিনি মুমিনদের প্রতি পরম দয়ালু।”", "en": "The One who is especially merciful to the believers: “And He is ever Merciful to the believers.”"}', '{"bn": "সূরা আহযাব ৩৩:৪৩", "en": "Al-Ahzab 33:43"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('5b1c7ac6-89cc-56cc-accc-b474c8dece4c', 3, 'الْمَلِكُ', '{"bn": "আল-মালিক", "en": "Al-Malik"}', '{"bn": "মহাবাদশাহ, প্রকৃত অধিপতি", "en": "The King, the Sovereign"}', '{"bn": "সব রাজত্ব ও ক্ষমতার প্রকৃত মালিক তিনিই; দুনিয়ার সব রাজত্ব সাময়িক। “মহিমান্বিত আল্লাহ, যিনি প্রকৃত বাদশাহ।”", "en": "All true kingship belongs to Him; every worldly kingdom is temporary. “Exalted is Allah, the True King.”"}', '{"bn": "সূরা ত্বা-হা ২০:১১৪", "en": "Ta-Ha 20:114"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('b3098450-bd91-57fa-8cdd-de4c03fa2c34', 4, 'الْقُدُّوسُ', '{"bn": "আল-কুদ্দুস", "en": "Al-Quddus"}', '{"bn": "পরম পবিত্র", "en": "The Most Holy"}', '{"bn": "সব দোষ-ত্রুটি ও অপূর্ণতা থেকে তিনি সম্পূর্ণ পবিত্র।", "en": "He is completely pure, free of every flaw and imperfection."}', '{"bn": "সূরা জুমুআ ৬২:১", "en": "Al-Jumu''ah 62:1"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('1f385073-2079-5531-a1d4-c7adc78aa6df', 5, 'السَّلَامُ', '{"bn": "আস-সালাম", "en": "As-Salam"}', '{"bn": "শান্তিদাতা, সব ত্রুটিমুক্ত", "en": "The Source of Peace"}', '{"bn": "তিনি সব দোষ থেকে মুক্ত এবং বান্দাদের শান্তি ও নিরাপত্তা দেন। ফরজ নামাজের পর পড়া হয়: “আল্লাহুম্মা আনতাস সালাম, ওয়া মিনকাস সালাম” (সহিহ মুসলিম ৫৯১)।", "en": "He is free of all defects and grants peace and safety. After the obligatory prayer we say “Allahumma antas-salam wa minkas-salam” (Sahih Muslim 591)."}', '{"bn": "সূরা হাশর ৫৯:২৩", "en": "Al-Hashr 59:23"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('c4362efb-4a0e-5354-8860-2fcce4dc057c', 6, 'الْمُؤْمِنُ', '{"bn": "আল-মু''মিন", "en": "Al-Mu''min"}', '{"bn": "নিরাপত্তাদাতা, বিশ্বস্ত", "en": "The Giver of Security, the Faithful"}', '{"bn": "যিনি বান্দাদের ভয় থেকে নিরাপত্তা দেন এবং নিজের ওয়াদা ও রাসুলদের সত্যতা প্রমাণ করেন।", "en": "He gives His servants safety from fear and confirms the truth of His promise and His messengers."}', '{"bn": "সূরা হাশর ৫৯:২৩", "en": "Al-Hashr 59:23"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('c74fe3d6-d3f8-59ab-bcb4-c3a802da9c45', 7, 'الْمُهَيْمِنُ', '{"bn": "আল-মুহাইমিন", "en": "Al-Muhaymin"}', '{"bn": "রক্ষাকর্তা, সর্বতত্ত্বাবধায়ক", "en": "The Guardian, the Overseer"}', '{"bn": "যিনি সবকিছুর ওপর নজর রাখেন ও রক্ষা করেন; সবকিছু তাঁর নিয়ন্ত্রণে।", "en": "He watches over and protects everything; all things are under His control."}', '{"bn": "সূরা হাশর ৫৯:২৩", "en": "Al-Hashr 59:23"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('94d980a9-cf73-506a-be8d-07b28300405e', 8, 'الْعَزِيزُ', '{"bn": "আল-আযীয", "en": "Al-''Aziz"}', '{"bn": "মহাপরাক্রমশালী", "en": "The Almighty"}', '{"bn": "তিনি এমন শক্তিমান যাঁকে কেউ পরাজিত করতে পারে না। কুরআনে প্রায়ই “আল-আযীযুল হাকীম” একসঙ্গে এসেছে।", "en": "He is mighty and can never be overcome. The Quran often pairs it with Al-Hakim: “the Almighty, the All-Wise.”"}', '{"bn": "সূরা আলে ইমরান ৩:৬", "en": "Al ''Imran 3:6"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('b88a8c70-4847-51b3-8b1b-d908ff4c6075', 9, 'الْجَبَّارُ', '{"bn": "আল-জাব্বার", "en": "Al-Jabbar"}', '{"bn": "মহাপ্রতাপশালী, ক্ষতিপূরণকারী", "en": "The Compeller, the Restorer"}', '{"bn": "তাঁর ইচ্ছা সবার ওপর কার্যকর; আবার তিনিই ভাঙা হৃদয় জোড়া লাগান ও দুর্বলের অভাব পূরণ করেন।", "en": "His will prevails over all; and He mends broken hearts and makes up what the weak lack."}', '{"bn": "সূরা হাশর ৫৯:২৩", "en": "Al-Hashr 59:23"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('f2b197ad-e65a-5293-a4e4-b50492e2e626', 10, 'الْمُتَكَبِّرُ', '{"bn": "আল-মুতাকাব্বির", "en": "Al-Mutakabbir"}', '{"bn": "সর্বশ্রেষ্ঠত্বের অধিকারী", "en": "The Supreme in Greatness"}', '{"bn": "সব বড়ত্ব ও শ্রেষ্ঠত্ব কেবল তাঁরই প্রাপ্য; বান্দার জন্য অহংকার নিন্দনীয়।", "en": "All greatness belongs to Him alone; for a servant, arrogance is blameworthy."}', '{"bn": "সূরা হাশর ৫৯:২৩", "en": "Al-Hashr 59:23"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('e48feac5-8b18-58c6-aa65-1b72bf0663df', 11, 'الْخَالِقُ', '{"bn": "আল-খালিক", "en": "Al-Khaliq"}', '{"bn": "সৃষ্টিকর্তা", "en": "The Creator"}', '{"bn": "যিনি সবকিছু নির্ধারিত পরিমাপে অস্তিত্বে এনেছেন।", "en": "He brought everything into being in a measured, decreed way."}', '{"bn": "সূরা হাশর ৫৯:২৪", "en": "Al-Hashr 59:24"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('ffda24ea-de41-51c8-a022-3e6c131af9c1', 12, 'الْبَارِئُ', '{"bn": "আল-বারি", "en": "Al-Bari''"}', '{"bn": "উদ্ভাবনকারী", "en": "The Originator, the Maker"}', '{"bn": "যিনি সৃষ্টিকে কোনো পূর্ব নমুনা ছাড়া, ত্রুটিমুক্তভাবে অস্তিত্ব দেন।", "en": "He brings creation into existence without any prior model and free of flaws."}', '{"bn": "সূরা হাশর ৫৯:২৪", "en": "Al-Hashr 59:24"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('ec852e39-620f-5603-83fc-6569b2574a41', 13, 'الْمُصَوِّرُ', '{"bn": "আল-মুসাওয়ির", "en": "Al-Musawwir"}', '{"bn": "আকৃতিদাতা", "en": "The Fashioner of Forms"}', '{"bn": "যিনি প্রতিটি সৃষ্টিকে আলাদা রূপ দেন; মাতৃগর্ভে যেমন ইচ্ছা তেমন আকৃতি দেন (সূরা আলে ইমরান ৩:৬)।", "en": "He gives every creature its own form; He shapes us in the womb as He wills (Al ''Imran 3:6)."}', '{"bn": "সূরা হাশর ৫৯:২৪", "en": "Al-Hashr 59:24"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('a9ab9834-8676-543e-9ec1-2236d17590b0', 14, 'الْغَفَّارُ', '{"bn": "আল-গাফ্ফার", "en": "Al-Ghaffar"}', '{"bn": "মহাক্ষমাশীল", "en": "The Ever-Forgiving"}', '{"bn": "যিনি বারবার ক্ষমা করেন। নূহ (আ.) বলেছিলেন: “তোমাদের রবের কাছে ক্ষমা চাও, নিশ্চয়ই তিনি মহাক্ষমাশীল।”", "en": "He forgives again and again. Nuh (AS) said: “Ask forgiveness of your Lord; indeed He is ever Forgiving.”"}', '{"bn": "সূরা নূহ ৭১:১০", "en": "Nuh 71:10"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('16a0777d-b763-50c8-b507-9521edda723a', 15, 'الْقَهَّارُ', '{"bn": "আল-কাহ্হার", "en": "Al-Qahhar"}', '{"bn": "মহাপরাক্রান্ত, সবার ওপর বিজয়ী", "en": "The Subduer"}', '{"bn": "সব সৃষ্টি তাঁর ক্ষমতার অধীন। কিয়ামতের দিন ঘোষণা হবে: “আজ রাজত্ব কার? এক, মহাপরাক্রান্ত আল্লাহর।”", "en": "All creation is subject to His power. On the Last Day: “To whom belongs the kingdom today? To Allah, the One, the Prevailing.”"}', '{"bn": "সূরা গাফির ৪০:১৬", "en": "Ghafir 40:16"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('ce70640f-d02f-5883-beb8-a4607099f798', 16, 'الْوَهَّابُ', '{"bn": "আল-ওয়াহ্হাব", "en": "Al-Wahhab"}', '{"bn": "মহাদাতা", "en": "The Bestower"}', '{"bn": "যিনি বিনিময় ছাড়াই অফুরন্ত দান করেন। মুমিনদের দোয়া: “নিশ্চয়ই আপনি মহাদাতা।”", "en": "He gives endlessly without asking anything in return. The believers pray: “Indeed, You are the Bestower.”"}', '{"bn": "সূরা আলে ইমরান ৩:৮", "en": "Al ''Imran 3:8"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('39dcf412-69c3-554c-9c22-49a693bdffa8', 17, 'الرَّزَّاقُ', '{"bn": "আর-রায্যাক", "en": "Ar-Razzaq"}', '{"bn": "রিজিকদাতা", "en": "The Provider"}', '{"bn": "সব সৃষ্টির রিজিক তাঁর হাতে; “নিশ্চয়ই আল্লাহই রিজিকদাতা, প্রবল শক্তিধর।”", "en": "The provision of all creation is in His hand: “Indeed, Allah is the Provider, the Firm Possessor of strength.”"}', '{"bn": "সূরা যারিয়াত ৫১:৫৮", "en": "Adh-Dhariyat 51:58"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('c21c14a7-1832-5179-b290-b0afba268654', 18, 'الْفَتَّاحُ', '{"bn": "আল-ফাত্তাহ", "en": "Al-Fattah"}', '{"bn": "উন্মোচনকারী, মীমাংসাকারী", "en": "The Opener, the Judge"}', '{"bn": "যিনি রহমত ও রিজিকের দরজা খুলে দেন এবং বান্দাদের মাঝে ন্যায্য ফয়সালা করেন।", "en": "He opens the doors of mercy and provision and judges between His servants with truth."}', '{"bn": "সূরা সাবা ৩৪:২৬", "en": "Saba 34:26"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('3611a2e4-f6f9-5f8c-a433-84dd97e07531', 19, 'الْعَلِيمُ', '{"bn": "আল-আলীম", "en": "Al-''Alim"}', '{"bn": "সর্বজ্ঞ", "en": "The All-Knowing"}', '{"bn": "প্রকাশ্য-গোপন, অতীত-ভবিষ্যৎ সবকিছু তিনি জানেন। ফেরেশতারা বলেছিলেন: “নিশ্চয়ই আপনি সর্বজ্ঞ, প্রজ্ঞাময়।”", "en": "He knows the seen and unseen, past and future. The angels said: “Indeed, You are the All-Knowing, the All-Wise.”"}', '{"bn": "সূরা বাকারা ২:৩২", "en": "Al-Baqarah 2:32"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('bad379ab-b1f1-5848-b447-d37c1bacc147', 20, 'الْقَابِضُ', '{"bn": "আল-কাবিদ", "en": "Al-Qabid"}', '{"bn": "সংকোচনকারী", "en": "The Withholder"}', '{"bn": "যিনি নিজ প্রজ্ঞায় রিজিক ইত্যাদি সংকুচিত করেন। “আল্লাহই সংকুচিত করেন ও প্রশস্ত করেন”; তাই এই নাম আল-বাসিতের সঙ্গে মিলিয়ে বলা উত্তম।", "en": "He constricts provision by His wisdom. “Allah withholds and grants abundance,” so this name is best mentioned together with Al-Basit."}', '{"bn": "সূরা বাকারা ২:২৪৫", "en": "Al-Baqarah 2:245"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('099576f0-41ec-52bb-89c2-7a3bed3e6d76', 21, 'الْبَاسِطُ', '{"bn": "আল-বাসিত", "en": "Al-Basit"}', '{"bn": "প্রসারকারী", "en": "The Expander"}', '{"bn": "যিনি যাকে ইচ্ছা রিজিক ও অনুগ্রহ প্রশস্ত করে দেন।", "en": "He expands provision and favour for whom He wills."}', '{"bn": "সূরা বাকারা ২:২৪৫", "en": "Al-Baqarah 2:245"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('2be487ed-679c-574f-9e6f-ae329a058bc5', 22, 'الْخَافِضُ', '{"bn": "আল-খাফিদ", "en": "Al-Khafid"}', '{"bn": "অবনতকারী", "en": "The Abaser"}', '{"bn": "যিনি অহংকারী ও জালিমদের নিচু করেন। নামটি কুরআনে নাম হিসেবে আসেনি; সহিহ হাদিসে আছে, আল্লাহ দাঁড়িপাল্লা নিচু করেন ও উঁচু করেন (সহিহ মুসলিম ১৭৯)।", "en": "He lowers the arrogant and the oppressors. It does not occur in the Quran as a name; a sahih hadith says Allah lowers the scale and raises it (Sahih Muslim 179)."}', '{}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('f1f44131-3292-5962-9f54-4b771a61af4c', 23, 'الرَّافِعُ', '{"bn": "আর-রাফি", "en": "Ar-Rafi''"}', '{"bn": "উন্নীতকারী", "en": "The Exalter"}', '{"bn": "যিনি মর্যাদা উঁচু করেন; “তোমাদের মধ্যে যারা ঈমান এনেছে এবং যাদের জ্ঞান দেওয়া হয়েছে, আল্লাহ তাদের মর্যাদা উঁচু করবেন।”", "en": "He raises people in rank: “Allah will raise those who have believed among you and those given knowledge, by degrees.”"}', '{"bn": "সূরা মুজাদালা ৫৮:১১", "en": "Al-Mujadilah 58:11"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('00905c3b-1c1f-5614-ad81-5b90aea6b33f', 24, 'الْمُعِزُّ', '{"bn": "আল-মুইয্য", "en": "Al-Mu''izz"}', '{"bn": "সম্মানদাতা", "en": "The Giver of Honour"}', '{"bn": "সম্মান কেবল তাঁর হাতে; “আপনি যাকে ইচ্ছা সম্মান দেন।”", "en": "Honour is in His hand alone: “You honour whom You will.”"}', '{"bn": "সূরা আলে ইমরান ৩:২৬", "en": "Al ''Imran 3:26"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('a72ff8d0-9982-5aea-ad63-68f655e41810', 25, 'الْمُذِلُّ', '{"bn": "আল-মুযিল্ল", "en": "Al-Mudhill"}', '{"bn": "অপমানকারী", "en": "The Giver of Disgrace"}', '{"bn": "তিনি যাকে ইচ্ছা ন্যায়সঙ্গতভাবে লাঞ্ছিত করেন; “আর যাকে ইচ্ছা অপমানিত করেন।” আল-মুইয্যের সঙ্গে মিলিয়ে বলা উত্তম।", "en": "He humbles whom He wills, justly: “and You humble whom You will.” Best mentioned together with Al-Mu''izz."}', '{"bn": "সূরা আলে ইমরান ৩:২৬", "en": "Al ''Imran 3:26"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('e7087ef0-bb1c-5801-8f8d-3c39d062634d', 26, 'السَّمِيعُ', '{"bn": "আস-সামী", "en": "As-Sami''"}', '{"bn": "সর্বশ্রোতা", "en": "The All-Hearing"}', '{"bn": "সব আওয়াজ, এমনকি মনের নীরব দোয়াও তিনি শোনেন।", "en": "He hears every sound, even the silent prayer of the heart."}', '{"bn": "সূরা শূরা ৪২:১১", "en": "Ash-Shura 42:11"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('ae5e7271-c5d6-56c4-b21f-2c5e91e0d0c5', 27, 'الْبَصِيرُ', '{"bn": "আল-বাসীর", "en": "Al-Basir"}', '{"bn": "সর্বদ্রষ্টা", "en": "The All-Seeing"}', '{"bn": "কোনো কিছুই তাঁর দৃষ্টির আড়ালে নয়; “তাঁর মতো কিছুই নেই, তিনি সর্বশ্রোতা, সর্বদ্রষ্টা।”", "en": "Nothing is hidden from His sight: “There is nothing like Him, and He is the All-Hearing, the All-Seeing.”"}', '{"bn": "সূরা শূরা ৪২:১১", "en": "Ash-Shura 42:11"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('173543e4-5803-577b-8c4d-8f19ffae858c', 28, 'الْحَكَمُ', '{"bn": "আল-হাকাম", "en": "Al-Hakam"}', '{"bn": "মহাবিচারক", "en": "The Judge"}', '{"bn": "চূড়ান্ত ফয়সালা ও বিধান দেওয়ার অধিকার তাঁরই; “আমি কি আল্লাহ ছাড়া অন্য কাউকে বিচারক মানব?”", "en": "The final judgement and law belong to Him: “Shall I seek a judge other than Allah?”"}', '{"bn": "সূরা আনআম ৬:১১৪", "en": "Al-An''am 6:114"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('17dbabc9-731f-5308-b964-adc2272364c0', 29, 'الْعَدْلُ', '{"bn": "আল-আদল", "en": "Al-''Adl"}', '{"bn": "ন্যায়পরায়ণ", "en": "The Just"}', '{"bn": "তিনি কারও প্রতি বিন্দুমাত্র জুলুম করেন না। শব্দটি কুরআনে নাম হিসেবে নয়, গুণ হিসেবে এসেছে: “তোমার রবের বাণী সত্য ও ন্যায়ে পরিপূর্ণ।”", "en": "He never wrongs anyone in the least. The word occurs in the Quran as a quality, not a name: “The word of your Lord is complete in truth and justice.”"}', '{"bn": "সূরা আনআম ৬:১১৫", "en": "Al-An''am 6:115"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('8c081497-f091-520d-a177-48e2078b3057', 30, 'اللَّطِيفُ', '{"bn": "আল-লাতীফ", "en": "Al-Latif"}', '{"bn": "সূক্ষ্মদর্শী, কোমল দয়ালু", "en": "The Subtle, the Gentle"}', '{"bn": "যিনি অতি সূক্ষ্ম বিষয়ও জানেন এবং বান্দার প্রতি অদৃশ্যভাবে অনুগ্রহ করেন।", "en": "He knows the finest details and is kind to His servants in ways they do not see."}', '{"bn": "সূরা মুলক ৬৭:১৪", "en": "Al-Mulk 67:14"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('e676e7e9-7aab-5087-bd35-1d06f3ff1a59', 31, 'الْخَبِيرُ', '{"bn": "আল-খাবীর", "en": "Al-Khabir"}', '{"bn": "সর্ববিষয়ে অবগত", "en": "The All-Aware"}', '{"bn": "সবকিছুর ভেতরের খবরও তিনি জানেন; “যিনি সৃষ্টি করেছেন তিনি কি জানবেন না? তিনি সূক্ষ্মদর্শী, সব বিষয়ে অবগত।”", "en": "He knows the inner reality of all things: “Does He not know, He who created, while He is the Subtle, the All-Aware?”"}', '{"bn": "সূরা মুলক ৬৭:১৪", "en": "Al-Mulk 67:14"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('31e75f15-7475-5834-b36d-eaa2a1ae7767', 32, 'الْحَلِيمُ', '{"bn": "আল-হালীম", "en": "Al-Halim"}', '{"bn": "সহনশীল", "en": "The Forbearing"}', '{"bn": "বান্দা অপরাধ করলেও তিনি সঙ্গে সঙ্গে শাস্তি দেন না, তওবার সুযোগ দেন।", "en": "Even when servants sin, He does not punish at once but gives time to repent."}', '{"bn": "সূরা বাকারা ২:২৬৩", "en": "Al-Baqarah 2:263"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('4978ea52-d4ce-5cc8-bb28-8b7f608ec8bc', 33, 'الْعَظِيمُ', '{"bn": "আল-আযীম", "en": "Al-''Azim"}', '{"bn": "মহান", "en": "The Magnificent"}', '{"bn": "সত্তা ও গুণে তিনি সর্বোচ্চ মহান; আয়াতুল কুরসি শেষ হয় “ওয়া হুওয়াল আলিয়্যুল আযীম” দিয়ে।", "en": "He is supremely great in Essence and attributes; Ayat al-Kursi ends with “and He is the Most High, the Magnificent.”"}', '{"bn": "সূরা বাকারা ২:২৫৫", "en": "Al-Baqarah 2:255"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('4ecf54e1-06d5-5de3-a2f2-925c49960d0c', 34, 'الْغَفُورُ', '{"bn": "আল-গাফুর", "en": "Al-Ghafur"}', '{"bn": "অতি ক্ষমাশীল", "en": "The All-Forgiving"}', '{"bn": "যিনি বড় বড় গুনাহও ক্ষমা করেন; “আমার বান্দাদের জানিয়ে দাও, আমি অতি ক্ষমাশীল, পরম দয়ালু।”", "en": "He forgives even great sins: “Inform My servants that I am the Forgiving, the Merciful.”"}', '{"bn": "সূরা হিজর ১৫:৪৯", "en": "Al-Hijr 15:49"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('b214a88a-5a51-569d-bc2c-87b21f9feee4', 35, 'الشَّكُورُ', '{"bn": "আশ-শাকুর", "en": "Ash-Shakur"}', '{"bn": "গুণগ্রাহী", "en": "The Appreciative"}', '{"bn": "বান্দার অল্প আমলকেও তিনি মূল্য দেন এবং বহুগুণ প্রতিদান দেন।", "en": "He values even a small deed of His servant and rewards it many times over."}', '{"bn": "সূরা তাগাবুন ৬৪:১৭", "en": "At-Taghabun 64:17"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('3823f923-9601-5216-937b-b39bd36e18c9', 36, 'الْعَلِيُّ', '{"bn": "আল-আলিয়্য", "en": "Al-''Aliyy"}', '{"bn": "সমুচ্চ", "en": "The Most High"}', '{"bn": "সত্তা, মর্যাদা ও ক্ষমতায় তিনি সবার ঊর্ধ্বে।", "en": "He is above all in Essence, rank and power."}', '{"bn": "সূরা হজ ২২:৬২", "en": "Al-Hajj 22:62"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('534b65fd-7cc9-5019-a3c8-f0cc37d6419f', 37, 'الْكَبِيرُ', '{"bn": "আল-কাবীর", "en": "Al-Kabir"}', '{"bn": "মহীয়ান, সর্বশ্রেষ্ঠ", "en": "The Most Great"}', '{"bn": "তাঁর চেয়ে বড় কিছু নেই; তাই আমরা “আল্লাহু আকবার” বলি।", "en": "Nothing is greater than Him; that is why we say “Allahu Akbar.”"}', '{"bn": "সূরা হজ ২২:৬২", "en": "Al-Hajj 22:62"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('1b15524d-5df3-5dc4-be5e-8a872858857d', 38, 'الْحَفِيظُ', '{"bn": "আল-হাফীয", "en": "Al-Hafiz"}', '{"bn": "সংরক্ষণকারী", "en": "The Preserver"}', '{"bn": "যিনি সবকিছু রক্ষা করেন এবং বান্দার আমল সংরক্ষণ করেন; “নিশ্চয়ই আমার রব সবকিছুর রক্ষক।”", "en": "He guards all things and keeps record of deeds: “Indeed, my Lord is Guardian over all things.”"}', '{"bn": "সূরা হুদ ১১:৫৭", "en": "Hud 11:57"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('808e29d2-76c4-50f1-b2ee-2f5e3271ee8a', 39, 'الْمُقِيتُ', '{"bn": "আল-মুকীত", "en": "Al-Muqit"}', '{"bn": "আহার ও শক্তিদাতা", "en": "The Nourisher"}', '{"bn": "যিনি প্রতিটি প্রাণীর খাদ্য ও শক্তি জোগান এবং সবকিছুর ওপর ক্ষমতাবান।", "en": "He supplies every creature with food and strength and has power over all things."}', '{"bn": "সূরা নিসা ৪:৮৫", "en": "An-Nisa 4:85"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('ca8df54b-5084-59ce-8ad7-957bed54e02d', 40, 'الْحَسِيبُ', '{"bn": "আল-হাসীব", "en": "Al-Hasib"}', '{"bn": "হিসাব গ্রহণকারী, যথেষ্ট", "en": "The Reckoner, the Sufficient"}', '{"bn": "যিনি বান্দার সব আমলের হিসাব নেবেন, আর যে তাঁর ওপর ভরসা করে তার জন্য তিনিই যথেষ্ট।", "en": "He will take account of every deed, and He is enough for whoever relies on Him."}', '{"bn": "সূরা নিসা ৪:৮৬", "en": "An-Nisa 4:86"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('c20343e0-8636-594f-ab96-321595b9b9a6', 41, 'الْجَلِيلُ', '{"bn": "আল-জালীল", "en": "Al-Jalil"}', '{"bn": "মহিমান্বিত", "en": "The Majestic"}', '{"bn": "মহত্ত্ব ও মর্যাদার পূর্ণতা তাঁরই। নামটি এই রূপে কুরআনে নেই; তবে “যুল-জালাল” (মহিমার অধিকারী) রূপে এসেছে।", "en": "Perfect majesty is His. The name is not in the Quran in this form, but occurs as “Dhul-Jalal” (Owner of Majesty)."}', '{"bn": "সূরা আর-রহমান ৫৫:৭৮", "en": "Ar-Rahman 55:78"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('630a34e9-8046-5c8d-a37a-b4e162ed2e3a', 42, 'الْكَرِيمُ', '{"bn": "আল-কারীম", "en": "Al-Karim"}', '{"bn": "পরম দানশীল, মহাসম্মানিত", "en": "The Most Generous"}', '{"bn": "যিনি না চাইতেই দেন এবং অপরাধীকেও দয়া করেন; “হে মানুষ, কিসে তোমাকে তোমার মহান রব সম্পর্কে ধোঁকায় ফেলল?”", "en": "He gives without being asked and is kind even to wrongdoers: “O mankind, what has deceived you about your Lord, the Generous?”"}', '{"bn": "সূরা ইনফিতার ৮২:৬", "en": "Al-Infitar 82:6"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('05ddeee7-27c6-5515-93bf-25ce24b358e8', 43, 'الرَّقِيبُ', '{"bn": "আর-রাকীব", "en": "Ar-Raqib"}', '{"bn": "পর্যবেক্ষক", "en": "The Watchful"}', '{"bn": "তিনি সবসময় বান্দার প্রতিটি কাজ ও চিন্তা দেখছেন; “নিশ্চয়ই আল্লাহ তোমাদের ওপর সজাগ দৃষ্টি রাখেন।”", "en": "He constantly watches every deed and thought: “Indeed, Allah is ever, over you, an Observer.”"}', '{"bn": "সূরা নিসা ৪:১", "en": "An-Nisa 4:1"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('f58cad78-de7f-575b-8811-353648306cfe', 44, 'الْمُجِيبُ', '{"bn": "আল-মুজীব", "en": "Al-Mujib"}', '{"bn": "দোয়া কবুলকারী", "en": "The Responsive"}', '{"bn": "যিনি বান্দার ডাকে সাড়া দেন; সালেহ (আ.) বলেছিলেন: “নিশ্চয়ই আমার রব নিকটে, ডাকে সাড়া দেন।”", "en": "He answers those who call on Him. Salih (AS) said: “Indeed, my Lord is near and responsive.”"}', '{"bn": "সূরা হুদ ১১:৬১", "en": "Hud 11:61"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('6fb270b4-b483-59d7-b8c2-27e94cfb8519', 45, 'الْوَاسِعُ', '{"bn": "আল-ওয়াসি", "en": "Al-Wasi''"}', '{"bn": "সর্বব্যাপী, প্রাচুর্যময়", "en": "The All-Encompassing"}', '{"bn": "তাঁর জ্ঞান, রহমত ও দান সবকিছুকে পরিব্যাপ্ত করে আছে।", "en": "His knowledge, mercy and giving encompass everything."}', '{"bn": "সূরা বাকারা ২:১১৫", "en": "Al-Baqarah 2:115"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('28c464db-8ba1-54a9-a6e3-4e013bc61841', 46, 'الْحَكِيمُ', '{"bn": "আল-হাকীম", "en": "Al-Hakim"}', '{"bn": "প্রজ্ঞাময়", "en": "The All-Wise"}', '{"bn": "তাঁর প্রতিটি আদেশ ও সিদ্ধান্তে গভীর প্রজ্ঞা আছে, যদিও আমরা সব সময় তা বুঝি না।", "en": "There is deep wisdom in each of His commands and decrees, even when we do not see it."}', '{"bn": "সূরা আনআম ৬:১৮", "en": "Al-An''am 6:18"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('c26398db-1c0d-5e2b-b005-ba7f2dd562e6', 47, 'الْوَدُودُ', '{"bn": "আল-ওয়াদুদ", "en": "Al-Wadud"}', '{"bn": "প্রেমময়", "en": "The Most Loving"}', '{"bn": "যিনি মুমিনদের ভালোবাসেন এবং মুমিনরাও যাঁকে ভালোবাসে; “তিনি ক্ষমাশীল, প্রেমময়।”", "en": "He loves the believers and is loved by them: “And He is the Forgiving, the Loving.”"}', '{"bn": "সূরা বুরুজ ৮৫:১৪", "en": "Al-Buruj 85:14"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('cf1d8af6-3907-5136-85a8-5d4161c2dd5a', 48, 'الْمَجِيدُ', '{"bn": "আল-মাজীদ", "en": "Al-Majid"}', '{"bn": "মহাগৌরবময়", "en": "The Most Glorious"}', '{"bn": "মর্যাদা ও দানে তিনি অতি গৌরবময়; দরুদে ইবরাহিমি শেষ হয় “ইন্নাকা হামীদুম মাজীদ” দিয়ে।", "en": "He is most glorious in honour and generosity; the Ibrahimi durood ends with “innaka Hamidun Majid.”"}', '{"bn": "সূরা হুদ ১১:৭৩", "en": "Hud 11:73"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('8ce23d91-65db-5536-9b2d-bc989a95ed6b', 49, 'الْبَاعِثُ', '{"bn": "আল-বা''ইস", "en": "Al-Ba''ith"}', '{"bn": "পুনরুত্থানকারী", "en": "The Resurrector"}', '{"bn": "যিনি রাসুল পাঠিয়েছেন এবং মৃতদের কবর থেকে আবার জীবিত করে উঠাবেন; “আল্লাহ কবরবাসীদের পুনরুত্থিত করবেন।”", "en": "He sent the messengers and will raise the dead from their graves: “Allah will resurrect those in the graves.”"}', '{"bn": "সূরা হজ ২২:৭", "en": "Al-Hajj 22:7"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('612e0290-68e6-5446-a8ba-d9bec61807cc', 50, 'الشَّهِيدُ', '{"bn": "আশ-শাহীদ", "en": "Ash-Shahid"}', '{"bn": "সাক্ষী, সর্বপ্রত্যক্ষকারী", "en": "The Witness"}', '{"bn": "সবকিছু তাঁর সামনে উপস্থিত; “নিশ্চয়ই আল্লাহ সবকিছুর সাক্ষী।”", "en": "Everything is present before Him: “Indeed, Allah is Witness over all things.”"}', '{"bn": "সূরা হজ ২২:১৭", "en": "Al-Hajj 22:17"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('a20a94b3-f6c4-573f-9890-fb855e3020e8', 51, 'الْحَقُّ', '{"bn": "আল-হাক্ক", "en": "Al-Haqq"}', '{"bn": "চিরসত্য", "en": "The Truth"}', '{"bn": "তাঁর অস্তিত্ব, কথা ও ওয়াদা সবই সত্য; “তারা জানবে যে আল্লাহই সুস্পষ্ট সত্য।”", "en": "His existence, word and promise are all true: “They will know that Allah is the manifest Truth.”"}', '{"bn": "সূরা নূর ২৪:২৫", "en": "An-Nur 24:25"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('156f3eb8-e962-5543-9257-6ea61e3b9869', 52, 'الْوَكِيلُ', '{"bn": "আল-ওয়াকীল", "en": "Al-Wakil"}', '{"bn": "কর্মবিধায়ক, ভরসাস্থল", "en": "The Trustee"}', '{"bn": "যাঁর ওপর ভরসা করলে তিনিই যথেষ্ট; বিপদে মুমিনরা বলেছিলেন: “হাসবুনাল্লাহু ওয়া নি''মাল ওয়াকীল।”", "en": "He is enough for whoever trusts Him; in danger the believers said: “Allah is sufficient for us, and He is the best Trustee.”"}', '{"bn": "সূরা আলে ইমরান ৩:১৭৩", "en": "Al ''Imran 3:173"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('a00dff7a-1529-5d92-b1b3-c9cda7e3f3f8', 53, 'الْقَوِيُّ', '{"bn": "আল-কাবিয়্য", "en": "Al-Qawiyy"}', '{"bn": "মহাশক্তিমান", "en": "The All-Strong"}', '{"bn": "তাঁর শক্তির কোনো সীমা নেই, তিনি কখনো দুর্বল হন না।", "en": "His strength has no limit; He never weakens."}', '{"bn": "সূরা শূরা ৪২:১৯", "en": "Ash-Shura 42:19"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('f9fac01f-9bbf-51bb-9722-6d0262c0f470', 54, 'الْمَتِينُ', '{"bn": "আল-মাতীন", "en": "Al-Matin"}', '{"bn": "সুদৃঢ়", "en": "The Firm"}', '{"bn": "যাঁর শক্তি অটল ও সুদৃঢ়; কোনো কাজে তিনি ক্লান্ত হন না।", "en": "His strength is firm and unshakable; no task tires Him."}', '{"bn": "সূরা যারিয়াত ৫১:৫৮", "en": "Adh-Dhariyat 51:58"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('38eedc9c-f2ec-58ad-a06e-45d971921b97', 55, 'الْوَلِيُّ', '{"bn": "আল-ওয়ালিয়্য", "en": "Al-Waliyy"}', '{"bn": "অভিভাবক, বন্ধু", "en": "The Protecting Friend"}', '{"bn": "তিনি মুমিনদের অভিভাবক; “আল্লাহ মুমিনদের অভিভাবক, তিনি তাদের অন্ধকার থেকে আলোর দিকে বের করে আনেন।”", "en": "He is the ally of the believers: “Allah is the ally of those who believe; He brings them out of darkness into light.”"}', '{"bn": "সূরা বাকারা ২:২৫৭", "en": "Al-Baqarah 2:257"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('07936025-bc65-5722-8dc8-438d245f7990', 56, 'الْحَمِيدُ', '{"bn": "আল-হামীদ", "en": "Al-Hamid"}', '{"bn": "প্রশংসিত", "en": "The Praiseworthy"}', '{"bn": "সব অবস্থায় সব প্রশংসা তাঁরই প্রাপ্য; “আল্লাহই অভাবমুক্ত, প্রশংসিত।”", "en": "All praise in every state is His due: “Allah is the Free of need, the Praiseworthy.”"}', '{"bn": "সূরা ফাতির ৩৫:১৫", "en": "Fatir 35:15"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('25ed88bb-5ee4-5394-8a1e-e38da3a603e8', 57, 'الْمُحْصِي', '{"bn": "আল-মুহসী", "en": "Al-Muhsi"}', '{"bn": "সবকিছু গণনাকারী", "en": "The Accounter"}', '{"bn": "যিনি সবকিছু গুনে রেখেছেন; “তিনি তাদের পরিবেষ্টন করে রেখেছেন এবং গুনে গুনে হিসাব রেখেছেন।”", "en": "He has counted everything: “He has enumerated them and counted them a full counting.”"}', '{"bn": "সূরা মারইয়াম ১৯:৯৪", "en": "Maryam 19:94"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('99f5ce49-4227-515d-8408-070d7c884c5e', 58, 'الْمُبْدِئُ', '{"bn": "আল-মুবদি", "en": "Al-Mubdi''"}', '{"bn": "প্রথমবার সৃষ্টিকারী", "en": "The Originator"}', '{"bn": "যিনি সৃষ্টিকে প্রথমবার অস্তিত্বে এনেছেন; “তিনিই প্রথমবার সৃষ্টি করেন এবং পুনরায় করবেন।”", "en": "He brought creation into being the first time: “It is He who originates and repeats.”"}', '{"bn": "সূরা বুরুজ ৮৫:১৩", "en": "Al-Buruj 85:13"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('af51131e-4e46-5e2c-a11f-e0ab6fbd246c', 59, 'الْمُعِيدُ', '{"bn": "আল-মুঈদ", "en": "Al-Mu''id"}', '{"bn": "পুনরায় সৃষ্টিকারী", "en": "The Restorer"}', '{"bn": "যিনি মৃত্যুর পর সৃষ্টিকে আবার জীবিত করবেন।", "en": "He will bring creation back to life after death."}', '{"bn": "সূরা বুরুজ ৮৫:১৩", "en": "Al-Buruj 85:13"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('ec816b91-340d-5a53-8a4d-63f8ffa9b93a', 60, 'الْمُحْيِي', '{"bn": "আল-মুহয়ী", "en": "Al-Muhyi"}', '{"bn": "জীবনদাতা", "en": "The Giver of Life"}', '{"bn": "যিনি মৃত মাটিকে জীবিত করেন; “নিশ্চয়ই তিনিই মৃতদের জীবনদাতা।”", "en": "He revives dead land: “Indeed, that same One will give life to the dead.”"}', '{"bn": "সূরা রুম ৩০:৫০", "en": "Ar-Rum 30:50"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('1b16e82f-0439-5e43-8812-653963e2c7b4', 61, 'الْمُمِيتُ', '{"bn": "আল-মুমীত", "en": "Al-Mumit"}', '{"bn": "মৃত্যুদাতা", "en": "The Bringer of Death"}', '{"bn": "প্রতিটি প্রাণের মৃত্যু তাঁর নির্ধারিত সময়েই আসে; “তিনিই জীবন দেন ও মৃত্যু দেন।”", "en": "Every soul dies at the time He has set: “He gives life and causes death.”"}', '{"bn": "সূরা হাদিদ ৫৭:২", "en": "Al-Hadid 57:2"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('c5fd459c-6575-59d3-aafb-5de204d88c21', 62, 'الْحَيُّ', '{"bn": "আল-হাইয়্য", "en": "Al-Hayy"}', '{"bn": "চিরঞ্জীব", "en": "The Ever-Living"}', '{"bn": "যাঁর জীবনের শুরু ও শেষ নেই; “ভরসা করো সেই চিরঞ্জীবের ওপর, যিনি কখনো মরবেন না।”", "en": "His life has no beginning or end: “Rely upon the Ever-Living who does not die.”"}', '{"bn": "সূরা ফুরকান ২৫:৫৮", "en": "Al-Furqan 25:58"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('52cd2210-5dc4-5e4a-9f97-155ea2bf2220', 63, 'الْقَيُّومُ', '{"bn": "আল-কাইয়ুম", "en": "Al-Qayyum"}', '{"bn": "চিরস্থায়ী, সবকিছুর ধারক", "en": "The Self-Sustaining"}', '{"bn": "তিনি কারও মুখাপেক্ষী নন, আর সবকিছু তাঁরই ওপর নির্ভর করে টিকে আছে; আয়াতুল কুরসিতে নামটি আছে।", "en": "He depends on none, while all things depend on Him for their existence; it occurs in Ayat al-Kursi."}', '{"bn": "সূরা বাকারা ২:২৫৫", "en": "Al-Baqarah 2:255"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('65037622-4c46-5721-8ce1-a7e57b3c73e8', 64, 'الْوَاجِدُ', '{"bn": "আল-ওয়াজিদ", "en": "Al-Wajid"}', '{"bn": "অভাবমুক্ত, যিনি যা চান পান", "en": "The Finder, the Self-Sufficient"}', '{"bn": "তাঁর কোনো কিছুর অভাব নেই; যা ইচ্ছা করেন তা-ই পান। এই নামটি কুরআনে আসেনি, তিরমিজির তালিকায় আছে।", "en": "He lacks nothing and finds whatever He wills. This name does not occur in the Quran; it is in Tirmidhi''s list."}', '{}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('52584c10-2804-5b83-a52d-02c7ac99ef62', 65, 'الْمَاجِدُ', '{"bn": "আল-মাজিদ", "en": "Al-Maajid"}', '{"bn": "মহিমান্বিত, মর্যাদাবান", "en": "The Noble, the Illustrious"}', '{"bn": "মর্যাদা ও দানশীলতায় পরিপূর্ণ; অর্থে আল-মাজীদের কাছাকাছি। এই রূপটি কুরআনে আসেনি।", "en": "Full of honour and generosity; close in meaning to Al-Majid. This form does not occur in the Quran."}', '{}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('929b26a4-a8fc-5a13-a96b-e92d1077d390', 66, 'الْوَاحِدُ', '{"bn": "আল-ওয়াহিদ", "en": "Al-Wahid"}', '{"bn": "এক, একক", "en": "The One"}', '{"bn": "সত্তা ও গুণে তিনি এক, তাঁর কোনো শরিক নেই; “তিনি এক, মহাপরাক্রান্ত।”", "en": "He is One in Essence and attributes, without partner: “He is the One, the Prevailing.”"}', '{"bn": "সূরা রা''দ ১৩:১৬", "en": "Ar-Ra''d 13:16"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('dd97d7a3-2ad6-5715-886b-55a7ba64e319', 67, 'الْأَحَدُ', '{"bn": "আল-আহাদ", "en": "Al-Ahad"}', '{"bn": "অদ্বিতীয়", "en": "The Unique, the Only One"}', '{"bn": "যাঁর মতো আর কেউ নেই; সূরা ইখলাস শুরু হয় “কুল হুওয়াল্লাহু আহাদ” দিয়ে। তিরমিজির কিছু সংস্করণে এই নামটি নেই।", "en": "There is none like Him; Surah Al-Ikhlas begins “Say: He is Allah, the One.” Some editions of Tirmidhi''s list do not include it."}', '{"bn": "সূরা ইখলাস ১১২:১", "en": "Al-Ikhlas 112:1"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('ccb75737-309d-529f-b6f5-49d61bd74741', 68, 'الصَّمَدُ', '{"bn": "আস-সামাদ", "en": "As-Samad"}', '{"bn": "অমুখাপেক্ষী, সবার আশ্রয়স্থল", "en": "The Eternal Refuge"}', '{"bn": "সবাই তাঁর মুখাপেক্ষী, কিন্তু তিনি কারও মুখাপেক্ষী নন।", "en": "All depend on Him, while He depends on none."}', '{"bn": "সূরা ইখলাস ১১২:২", "en": "Al-Ikhlas 112:2"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('4955c80a-7893-593d-921f-b96c6c73278d', 69, 'الْقَادِرُ', '{"bn": "আল-কাদির", "en": "Al-Qadir"}', '{"bn": "সর্বশক্তিমান", "en": "The All-Capable"}', '{"bn": "যা ইচ্ছা তা করতে তিনি সক্ষম; “বলো, তিনি তোমাদের ওপর শাস্তি পাঠাতে সক্ষম।”", "en": "He is able to do whatever He wills: “Say: He is able to send upon you punishment.”"}', '{"bn": "সূরা আনআম ৬:৬৫", "en": "Al-An''am 6:65"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('527749d8-3ba4-5aa9-ac91-448c546b5c13', 70, 'الْمُقْتَدِرُ', '{"bn": "আল-মুকতাদির", "en": "Al-Muqtadir"}', '{"bn": "পূর্ণ ক্ষমতাবান", "en": "The All-Powerful"}', '{"bn": "যাঁর ক্ষমতা পরিপূর্ণ; মুত্তাকিরা থাকবে “সর্বশক্তিমান অধিপতির সান্নিধ্যে।”", "en": "His power is complete; the righteous will be “in the presence of a Sovereign, Perfect in Ability.”"}', '{"bn": "সূরা কামার ৫৪:৫৫", "en": "Al-Qamar 54:55"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('0164d77c-2df7-54ad-9d58-cf4fcbecbc66', 71, 'الْمُقَدِّمُ', '{"bn": "আল-মুকাদ্দিম", "en": "Al-Muqaddim"}', '{"bn": "অগ্রসরকারী", "en": "The Expediter"}', '{"bn": "যিনি যাকে ইচ্ছা ও যা ইচ্ছা আগে নিয়ে আসেন। রাসুল ﷺ রাতের নামাজের দোয়ায় বলতেন: “আনতাল মুকাদ্দিমু ওয়া আনতাল মুআখখির” (সহিহ বুখারি ও মুসলিম)।", "en": "He brings forward whom and what He wills. The Prophet ﷺ said in his night-prayer dua: “You are the One who brings forward and the One who delays” (Bukhari and Muslim)."}', '{"bn": "সূরা কাফ ৫০:২৮", "en": "Qaf 50:28"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('ff5cb5b1-bc8c-5f47-bed3-05f37bd4b7c6', 72, 'الْمُؤَخِّرُ', '{"bn": "আল-মুআখখির", "en": "Al-Mu''akhkhir"}', '{"bn": "বিলম্বকারী", "en": "The Delayer"}', '{"bn": "যিনি নিজ প্রজ্ঞায় যা ইচ্ছা পিছিয়ে দেন; তিনি মানুষকে নির্দিষ্ট সময় পর্যন্ত অবকাশ দেন।", "en": "He delays what He wills by His wisdom; He gives people respite until an appointed time."}', '{"bn": "সূরা নাহল ১৬:৬১", "en": "An-Nahl 16:61"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('e51acc55-e469-56a4-a85a-5bd95f3ce946', 73, 'الْأَوَّلُ', '{"bn": "আল-আওয়াল", "en": "Al-Awwal"}', '{"bn": "আদি, সর্বপ্রথম", "en": "The First"}', '{"bn": "যাঁর আগে কিছুই ছিল না; রাসুল ﷺ এভাবেই নামটি ব্যাখ্যা করেছেন (সহিহ মুসলিম ২৭১৩)।", "en": "There was nothing before Him; this is how the Prophet ﷺ explained it (Sahih Muslim 2713)."}', '{"bn": "সূরা হাদিদ ৫৭:৩", "en": "Al-Hadid 57:3"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('85e4da60-cdfa-5c2a-9459-b6b203489ea0', 74, 'الْآخِرُ', '{"bn": "আল-আখির", "en": "Al-Akhir"}', '{"bn": "অন্ত, সর্বশেষ", "en": "The Last"}', '{"bn": "যাঁর পরে কিছু নেই; সবকিছু শেষ হয়ে যাবে, তিনি থাকবেন।", "en": "There is nothing after Him; all will end and He will remain."}', '{"bn": "সূরা হাদিদ ৫৭:৩", "en": "Al-Hadid 57:3"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('389363fb-6df2-5485-a9b7-363c5399b3d8', 75, 'الظَّاهِرُ', '{"bn": "আয-যাহির", "en": "Az-Zahir"}', '{"bn": "প্রকাশ্য, সবার ঊর্ধ্বে", "en": "The Manifest"}', '{"bn": "যাঁর ঊর্ধ্বে কিছু নেই; তাঁর নিদর্শন সবখানে স্পষ্ট।", "en": "There is nothing above Him; His signs are clear everywhere."}', '{"bn": "সূরা হাদিদ ৫৭:৩", "en": "Al-Hadid 57:3"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('70ea66f2-0333-571b-94c5-4d9d64ff1c37', 76, 'الْبَاطِنُ', '{"bn": "আল-বাতিন", "en": "Al-Batin"}', '{"bn": "গোপন, অন্তর্নিহিত", "en": "The Hidden"}', '{"bn": "যাঁর চেয়ে নিকটে কিছু নেই, অথচ চোখ তাঁকে দেখতে পায় না।", "en": "Nothing is nearer than Him, yet eyes cannot perceive Him."}', '{"bn": "সূরা হাদিদ ৫৭:৩", "en": "Al-Hadid 57:3"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('fbd3b3d6-2e7e-552a-9d43-fb52cfb89a2b', 77, 'الْوَالِي', '{"bn": "আল-ওয়ালী", "en": "Al-Wali"}', '{"bn": "সবকিছুর পরিচালক", "en": "The Governor"}', '{"bn": "যিনি সবকিছুর কাজ পরিচালনা করেন; “তিনি ছাড়া তাদের আর কোনো অভিভাবক নেই।”", "en": "He manages the affairs of all things: “There is not for them besides Him any patron.”"}', '{"bn": "সূরা রা''দ ১৩:১১", "en": "Ar-Ra''d 13:11"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('1f5bf4ab-1c10-541f-b808-6a774c8669e1', 78, 'الْمُتَعَالِي', '{"bn": "আল-মুতাআলী", "en": "Al-Muta''ali"}', '{"bn": "সর্বোচ্চ মহিমান্বিত", "en": "The Most Exalted"}', '{"bn": "সব সৃষ্টির ঊর্ধ্বে এবং সব অপূর্ণতা থেকে বহু ঊর্ধ্বে; “তিনি মহান, সর্বোচ্চ।”", "en": "Above all creation and far above every imperfection: “the Grand, the Exalted.”"}', '{"bn": "সূরা রা''দ ১৩:৯", "en": "Ar-Ra''d 13:9"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('debbadc7-306b-530e-b360-2ff14eb651f1', 79, 'الْبَرُّ', '{"bn": "আল-বার্র", "en": "Al-Barr"}', '{"bn": "পরম কল্যাণকারী", "en": "The Source of Goodness"}', '{"bn": "যিনি বান্দাদের প্রতি অশেষ সদয়; “নিশ্চয়ই তিনি কল্যাণময়, পরম দয়ালু।”", "en": "He is endlessly good to His servants: “Indeed, it is He who is the Beneficent, the Merciful.”"}', '{"bn": "সূরা তূর ৫২:২৮", "en": "At-Tur 52:28"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('ebc8ba32-f7a8-5aca-a1dc-a7ea05f0d8bd', 80, 'التَّوَّابُ', '{"bn": "আত-তাওয়াব", "en": "At-Tawwab"}', '{"bn": "তওবা কবুলকারী", "en": "The Accepter of Repentance"}', '{"bn": "যিনি বারবার তওবা কবুল করেন; আদম (আ.)-এর তওবাও তিনি কবুল করেছিলেন।", "en": "He accepts repentance again and again; He accepted the repentance of Adam (AS)."}', '{"bn": "সূরা বাকারা ২:৩৭", "en": "Al-Baqarah 2:37"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('fb28cb60-c7a2-58ed-80ed-5fd6bd1db95a', 81, 'الْمُنْتَقِمُ', '{"bn": "আল-মুনতাকিম", "en": "Al-Muntaqim"}', '{"bn": "প্রতিশোধ গ্রহণকারী", "en": "The Avenger"}', '{"bn": "যিনি অবাধ্য অপরাধীদের ন্যায্য শাস্তি দেন; কুরআনে আছে: “আমি অপরাধীদের থেকে প্রতিশোধ নেব।”", "en": "He justly punishes persistent criminals: “Indeed, We will take retribution from the criminals.”"}', '{"bn": "সূরা সাজদা ৩২:২২", "en": "As-Sajdah 32:22"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('d9ddb9dd-7d30-5174-b0aa-f9fb15376eec', 82, 'الْعَفُوُّ', '{"bn": "আল-আফুউ", "en": "Al-''Afuww"}', '{"bn": "মার্জনাকারী", "en": "The Pardoner"}', '{"bn": "যিনি গুনাহ এমনভাবে মুছে দেন যেন চিহ্নও না থাকে; লাইলাতুল কদরের দোয়ায় এই নাম আছে (সুনান তিরমিজি ৩৫১৩)।", "en": "He erases sins as if they never were; this name is in the dua for Laylat al-Qadr (Jami'' at-Tirmidhi 3513)."}', '{"bn": "সূরা নিসা ৪:৪৩", "en": "An-Nisa 4:43"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('fd0123e6-3550-57de-bdd0-ae66cc78a37b', 83, 'الرَّءُوفُ', '{"bn": "আর-রাউফ", "en": "Ar-Ra''uf"}', '{"bn": "অতি স্নেহশীল", "en": "The Most Kind"}', '{"bn": "যাঁর দয়া অত্যন্ত কোমল ও গভীর; “নিশ্চয়ই আল্লাহ মানুষের প্রতি অতি স্নেহশীল, পরম দয়ালু।”", "en": "His mercy is most tender: “Indeed, Allah is, to the people, Kind and Merciful.”"}', '{"bn": "সূরা বাকারা ২:১৪৩", "en": "Al-Baqarah 2:143"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('54e08c82-6dce-5744-b63b-bc4ca5421973', 84, 'مَالِكُ الْمُلْكِ', '{"bn": "মালিকুল মুলক", "en": "Malik al-Mulk"}', '{"bn": "সার্বভৌম ক্ষমতার মালিক", "en": "Owner of All Sovereignty"}', '{"bn": "তিনি যাকে ইচ্ছা রাজত্ব দেন, যার থেকে ইচ্ছা কেড়ে নেন; “বলো, হে আল্লাহ, রাজত্বের মালিক।”", "en": "He gives kingship to whom He wills and takes it from whom He wills: “Say: O Allah, Owner of Sovereignty.”"}', '{"bn": "সূরা আলে ইমরান ৩:২৬", "en": "Al ''Imran 3:26"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('76c5db6b-4cdf-5e08-bff5-8544ea73267f', 85, 'ذُو الْجَلَالِ وَالْإِكْرَامِ', '{"bn": "যুল-জালালি ওয়াল-ইকরাম", "en": "Dhul-Jalali wal-Ikram"}', '{"bn": "মহিমা ও সম্মানের অধিকারী", "en": "Lord of Majesty and Honour"}', '{"bn": "সব সৃষ্টি ধ্বংস হবে, কেবল মহিমা ও সম্মানের অধিকারী রবের চেহারা বাকি থাকবে।", "en": "All creation will perish, and only the Face of your Lord, Owner of Majesty and Honour, will remain."}', '{"bn": "সূরা আর-রহমান ৫৫:২৭", "en": "Ar-Rahman 55:27"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('fe420444-ae03-5586-8720-a50f6959b702', 86, 'الْمُقْسِطُ', '{"bn": "আল-মুকসিত", "en": "Al-Muqsit"}', '{"bn": "ন্যায়বিচারক", "en": "The Equitable"}', '{"bn": "যিনি পূর্ণ ন্যায়ের সঙ্গে বিচার করেন; আল্লাহ নিজেই সাক্ষ্য দিয়েছেন যে তিনি ন্যায়ের সঙ্গে প্রতিষ্ঠিত।", "en": "He judges with perfect fairness; Allah Himself bears witness that He maintains justice."}', '{"bn": "সূরা আলে ইমরান ৩:১৮", "en": "Al ''Imran 3:18"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('9331779e-0191-50d7-adc0-1f0a8161441a', 87, 'الْجَامِعُ', '{"bn": "আল-জামি", "en": "Al-Jami''"}', '{"bn": "একত্রকারী", "en": "The Gatherer"}', '{"bn": "যিনি কিয়ামতের দিন সব মানুষকে একত্র করবেন; “হে আমাদের রব, আপনি মানুষকে এমন দিনে একত্র করবেন যাতে কোনো সন্দেহ নেই।”", "en": "He will gather all people on the Last Day: “Our Lord, You will gather the people for a Day about which there is no doubt.”"}', '{"bn": "সূরা আলে ইমরান ৩:৯", "en": "Al ''Imran 3:9"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('f2fa5830-7c45-50f5-8774-a6259055771a', 88, 'الْغَنِيُّ', '{"bn": "আল-গানিয়্য", "en": "Al-Ghaniyy"}', '{"bn": "অভাবমুক্ত", "en": "The Self-Sufficient"}', '{"bn": "তিনি কারও মুখাপেক্ষী নন, আর সবাই তাঁর মুখাপেক্ষী; “আল্লাহ অভাবমুক্ত, আর তোমরা অভাবী।”", "en": "He needs no one, while all need Him: “Allah is the Free of need, and you are the needy.”"}', '{"bn": "সূরা মুহাম্মাদ ৪৭:৩৮", "en": "Muhammad 47:38"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('2bf680bb-c7a8-5b29-ad79-2accb16064b0', 89, 'الْمُغْنِي', '{"bn": "আল-মুগনী", "en": "Al-Mughni"}', '{"bn": "অভাব মোচনকারী", "en": "The Enricher"}', '{"bn": "যিনি বান্দাকে অভাবমুক্ত ও সচ্ছল করেন; “তিনিই ধনী করেন ও সম্পদ দান করেন।”", "en": "He frees His servants from need: “It is He who enriches and suffices.”"}', '{"bn": "সূরা নাজম ৫৩:৪৮", "en": "An-Najm 53:48"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('034249ed-d8d0-5a86-955a-9f13ca529e1e', 90, 'الْمَانِعُ', '{"bn": "আল-মানি", "en": "Al-Mani''"}', '{"bn": "প্রতিরোধকারী", "en": "The Preventer"}', '{"bn": "তিনি যা আটকে রাখেন কেউ তা দিতে পারে না; নামাজের পর দোয়ায় আছে: “আপনি যা আটকান তা দেওয়ার কেউ নেই” (সহিহ বুখারি ৮৪৪)। এই নামটি কুরআনে আসেনি।", "en": "None can give what He withholds; after prayer we say “none can give what You withhold” (Sahih al-Bukhari 844). This name does not occur in the Quran."}', '{}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('d7375886-8fc3-5c7f-9b7a-85133b7114f5', 91, 'الضَّارُّ', '{"bn": "আদ-দার্র", "en": "Ad-Darr"}', '{"bn": "ক্ষতির মালিক", "en": "The Distresser"}', '{"bn": "ক্ষতি ও কষ্টও তাঁর অনুমতি ছাড়া আসে না, তাই তা দূর করতে কেবল তাঁর কাছেই চাইতে হয়; আন-নাফির সঙ্গে মিলিয়ে বলা উত্তম।", "en": "No harm comes except by His permission, so only He can remove it; best mentioned together with An-Nafi''."}', '{"bn": "সূরা ইউনুস ১০:১০৭", "en": "Yunus 10:107"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('7fb84727-b15f-5d6d-925b-d61be191f12d', 92, 'النَّافِعُ', '{"bn": "আন-নাফি", "en": "An-Nafi''"}', '{"bn": "কল্যাণদাতা", "en": "The Benefactor"}', '{"bn": "সব উপকার ও কল্যাণ তাঁর পক্ষ থেকেই আসে; তিনি উপকার করতে চাইলে কেউ বাধা দিতে পারে না।", "en": "All benefit comes from Him; if He intends benefit, none can prevent it."}', '{"bn": "সূরা ফাতহ ৪৮:১১", "en": "Al-Fath 48:11"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('c140ff65-15f3-5e8f-b7f7-e76ff1b7f3c1', 93, 'النُّورُ', '{"bn": "আন-নূর", "en": "An-Nur"}', '{"bn": "জ্যোতি", "en": "The Light"}', '{"bn": "“আল্লাহ আসমান ও জমিনের নূর”; তিনিই হেদায়াতের আলো দান করেন।", "en": "“Allah is the Light of the heavens and the earth”; He grants the light of guidance."}', '{"bn": "সূরা নূর ২৪:৩৫", "en": "An-Nur 24:35"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('8a63bee1-5fb3-5671-8a56-67208ce19099', 94, 'الْهَادِي', '{"bn": "আল-হাদী", "en": "Al-Hadi"}', '{"bn": "পথপ্রদর্শক", "en": "The Guide"}', '{"bn": "যিনি সঠিক পথ দেখান; “পথপ্রদর্শক ও সাহায্যকারী হিসেবে তোমার রবই যথেষ্ট।”", "en": "He guides to the right path: “Sufficient is your Lord as a Guide and a Helper.”"}', '{"bn": "সূরা ফুরকান ২৫:৩১", "en": "Al-Furqan 25:31"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('ffc39e48-9d0d-5182-9e9b-bcb0481a2428', 95, 'الْبَدِيعُ', '{"bn": "আল-বাদী", "en": "Al-Badi''"}', '{"bn": "অভিনব স্রষ্টা", "en": "The Incomparable Originator"}', '{"bn": "যিনি কোনো পূর্ব নমুনা ছাড়াই আসমান-জমিন সৃষ্টি করেছেন।", "en": "He created the heavens and the earth with no prior model."}', '{"bn": "সূরা বাকারা ২:১১৭", "en": "Al-Baqarah 2:117"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('9946d179-bb9f-5699-8203-a3754e35eedf', 96, 'الْبَاقِي', '{"bn": "আল-বাকী", "en": "Al-Baqi"}', '{"bn": "চিরস্থায়ী", "en": "The Everlasting"}', '{"bn": "সবকিছু ধ্বংস হবে, কেবল তিনিই বাকি থাকবেন; “আর বাকি থাকবে তোমার রবের চেহারা।”", "en": "Everything will perish and He alone will remain: “And there will remain the Face of your Lord.”"}', '{"bn": "সূরা আর-রহমান ৫৫:২৭", "en": "Ar-Rahman 55:27"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('b72cb272-72cd-5cd8-a7ec-ffb994a9fe67', 97, 'الْوَارِثُ', '{"bn": "আল-ওয়ারিস", "en": "Al-Warith"}', '{"bn": "উত্তরাধিকারী", "en": "The Inheritor"}', '{"bn": "সবকিছু শেষ হলে সবকিছুর মালিকানা তাঁরই থাকবে; “আর আমিই চূড়ান্ত উত্তরাধিকারী।”", "en": "When all passes away, everything remains His: “And We are the Inheritor.”"}', '{"bn": "সূরা হিজর ১৫:২৩", "en": "Al-Hijr 15:23"}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('ba5d077b-5824-5827-920f-7c00d40845e6', 98, 'الرَّشِيدُ', '{"bn": "আর-রাশীদ", "en": "Ar-Rashid"}', '{"bn": "সঠিক পথে পরিচালনাকারী", "en": "The Guide to the Right Path"}', '{"bn": "যাঁর সব কাজ সঠিক ও কল্যাণকর এবং যিনি বান্দাকে সঠিক পথে চালান। এই নামটি এই রূপে কুরআনে আসেনি।", "en": "All His actions are right and good, and He directs His servants aright. This name does not occur in the Quran in this form."}', '{}', 'in_review') ON CONFLICT (n) DO NOTHING;
INSERT INTO is_allah_names (id, n, ar, pron, meaning, note, ref, review_status) VALUES ('e75a477f-1b03-5c81-8e62-dd0f5d9d155d', 99, 'الصَّبُورُ', '{"bn": "আস-সাবুর", "en": "As-Sabur"}', '{"bn": "পরম ধৈর্যশীল", "en": "The Most Patient"}', '{"bn": "বান্দাদের অবাধ্যতা দেখেও তিনি তাড়াহুড়া করে শাস্তি দেন না। সহিহ হাদিসে আছে, কষ্টদায়ক কথা শুনে আল্লাহর চেয়ে বেশি ধৈর্যশীল কেউ নেই (সহিহ বুখারি)।", "en": "He does not hasten to punish despite His servants'' disobedience. A sahih hadith says no one is more patient with hurtful words than Allah (Sahih al-Bukhari)."}', '{}', 'in_review') ON CONFLICT (n) DO NOTHING;
